B.aop=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",2,"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",3,"\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",4,"\u0645\u064e\u0627\u0644\u0650\u0643\u0650 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",5,"\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064e \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064e \u0646\u064e\u0633\u0652\u062a\u064e\u0639\u0650\u064a\u0646\u064f",6,"\u0627\u0647\u0652\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064e",7,"\u0635\u0650\u0631\u064e\u0627\u0637\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0636\u064f\u0648\u0628\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e"],t.v)
B.arY=new A.U([1,u.d,2,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u06db \u0641\u0650\u064a\u0647\u0650 \u06db \u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",5,u.g,6,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0623\u064e\u0646\u0652\u0630\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0646\u0652\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",7,"\u062e\u064e\u062a\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0645\u0652\u0639\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u063a\u0650\u0634\u064e\u0627\u0648\u064e\u0629\u064c \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",8,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",9,"\u064a\u064f\u062e\u064e\u0627\u062f\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u062f\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",10,"\u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0631\u064e\u0636\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0648\u0646\u064e",11,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",12,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0643\u064e\u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u064e \u0627\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0621\u064f \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0621\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",15,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",16,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0650\u062d\u064e\u062a\u0652 \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",17,"\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0633\u0652\u062a\u064e\u0648\u0652\u0642\u064e\u062f\u064e \u0646\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0636\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0630\u064e\u0647\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0646\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064d \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",18,"\u0635\u064f\u0645\u0651\u064c \u0628\u064f\u0643\u0652\u0645\u064c \u0639\u064f\u0645\u0652\u064a\u064c \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",19,"\u0623\u064e\u0648\u0652 \u0643\u064e\u0635\u064e\u064a\u0651\u0650\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u0650\u064a\u0647\u0650 \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064c \u0648\u064e\u0631\u064e\u0639\u0652\u062f\u064c \u0648\u064e\u0628\u064e\u0631\u0652\u0642\u064c \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0635\u064e\u0627\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0648\u064e\u0627\u0639\u0650\u0642\u0650 \u062d\u064e\u0630\u064e\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062d\u0650\u064a\u0637\u064c \u0628\u0650\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",20,"\u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0652\u0642\u064f \u064a\u064e\u062e\u0652\u0637\u064e\u0641\u064f \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0636\u064e\u0627\u0621\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0634\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u064e\u0647\u064e\u0628\u064e \u0628\u0650\u0633\u064e\u0645\u0652\u0639\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",21,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",22,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u0631\u064e\u0627\u0634\u064b\u0627 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0621\u064b \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u064a\u0652\u0628\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0633\u064f\u0648\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",24,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0642\u064f\u0648\u062f\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064f \u06d6 \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u0652 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",25,"\u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0631\u064f\u0632\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062b\u064e\u0645\u064e\u0631\u064e\u0629\u064d \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u06d9 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0631\u064f\u0632\u0650\u0642\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0623\u064f\u062a\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064c \u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064c \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",26,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u0650\u064a \u0623\u064e\u0646\u0652 \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0645\u064e\u0627 \u0628\u064e\u0639\u064f\u0648\u0636\u064e\u0629\u064b \u0641\u064e\u0645\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064e\u0627 \u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u06d8 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",27,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u0652\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",28,"\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064b\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",29,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",30,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0639\u0650\u0644\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u0641\u0650\u0643\u064f \u0627\u0644\u062f\u0651\u0650\u0645\u064e\u0627\u0621\u064e \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0646\u064f\u0642\u064e\u062f\u0651\u0650\u0633\u064f \u0644\u064e\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0622\u062f\u064e\u0645\u064e \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0631\u064e\u0636\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0652\u0628\u0650\u0626\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u0650 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0644\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064e \u0644\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u0652\u062a\u064e\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",33,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0622\u062f\u064e\u0645\u064f \u0623\u064e\u0646\u0652\u0628\u0650\u0626\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0628\u064e\u0623\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u063a\u064e\u064a\u0652\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0622\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",35,"\u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u064a\u064e\u0627 \u0622\u062f\u064e\u0645\u064f \u0627\u0633\u0652\u0643\u064f\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0632\u064e\u0648\u0652\u062c\u064f\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0643\u064f\u0644\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0631\u064e\u063a\u064e\u062f\u064b\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",36,"\u0641\u064e\u0623\u064e\u0632\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u0647\u0652\u0628\u0650\u0637\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064c \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",37,"\u0641\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670 \u0622\u062f\u064e\u0645\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064d \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",38,"\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u0647\u0652\u0628\u0650\u0637\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u0650\u064a \u0647\u064f\u062f\u064b\u0649 \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e \u0647\u064f\u062f\u064e\u0627\u064a\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",40,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u064a \u0623\u064f\u0648\u0641\u0650 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u064a\u064e \u0641\u064e\u0627\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u0650",41,"\u0648\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u062a\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u064d \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u064a\u064e \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",42,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",43,"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0631\u0652\u0643\u064e\u0639\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0631\u0651\u064e\u0627\u0643\u0650\u0639\u0650\u064a\u0646\u064e",44,"\u0623\u064e\u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u062a\u064e\u0646\u0652\u0633\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062e\u064e\u0627\u0634\u0650\u0639\u0650\u064a\u0646\u064e",46,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0644\u064e\u0627\u0642\u064f\u0648 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e",47,u.au,48,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0632\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u064c \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0628\u064e\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062e\u064e\u0630\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0639\u064e\u062f\u0652\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0644\u064e\u0627\u0621\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c",50,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0641\u064e\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0622\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",51,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0648\u064e\u0627\u0639\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",52,"\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0641\u064e\u0648\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",54,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u062a\u0651\u0650\u062e\u064e\u0627\u0630\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0641\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0627\u0631\u0650\u0626\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0628\u064e\u0627\u0631\u0650\u0626\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",55,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0631\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0647\u0652\u0631\u064e\u0629\u064b \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",56,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0648\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",57,"\u0648\u064e\u0638\u064e\u0644\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0645\u064e\u0627\u0645\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u0652\u0648\u064e\u0649\u0670 \u06d6 \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064e \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0631\u064e\u063a\u064e\u062f\u064b\u0627 \u0648\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u062d\u0650\u0637\u0651\u064e\u0629\u064c \u0646\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0633\u064e\u0646\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",59,"\u0641\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0631\u0650\u062c\u0652\u0632\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0625\u0650\u0630\u0650 \u0627\u0633\u0652\u062a\u064e\u0633\u0652\u0642\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0628\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u062c\u064e\u0631\u064e \u06d6 \u0641\u064e\u0627\u0646\u0652\u0641\u064e\u062c\u064e\u0631\u064e\u062a\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u0627 \u0639\u064e\u0634\u0652\u0631\u064e\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u06d6 \u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u064e\u0627\u0633\u064d \u0645\u064e\u0634\u0652\u0631\u064e\u0628\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",61,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0646\u0652 \u0646\u064e\u0635\u0652\u0628\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0641\u064e\u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0646\u0652\u0628\u0650\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0642\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u0650\u062b\u0651\u064e\u0627\u0626\u0650\u0647\u064e\u0627 \u0648\u064e\u0641\u064f\u0648\u0645\u0650\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0633\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0635\u064e\u0644\u0650\u0647\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u06da \u0627\u0647\u0652\u0628\u0650\u0637\u064f\u0648\u0627 \u0645\u0650\u0635\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0630\u0651\u0650\u0644\u0651\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0652\u0643\u064e\u0646\u064e\u0629\u064f \u0648\u064e\u0628\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0652\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",62,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0626\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",63,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",64,"\u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0644\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",65,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u062a\u0650 \u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064b \u062e\u064e\u0627\u0633\u0650\u0626\u0650\u064a\u0646\u064e",66,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0646\u064e\u0643\u064e\u0627\u0644\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",67,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0630\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0646\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",68,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u064c \u0644\u064e\u0627 \u0641\u064e\u0627\u0631\u0650\u0636\u064c \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0643\u0652\u0631\u064c \u0639\u064e\u0648\u064e\u0627\u0646\u064c \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0641\u064e\u0627\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u064e\u0631\u064f\u0648\u0646\u064e",69,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0648\u0652\u0646\u064f\u0647\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u064c \u0635\u064e\u0641\u0652\u0631\u064e\u0627\u0621\u064f \u0641\u064e\u0627\u0642\u0650\u0639\u064c \u0644\u064e\u0648\u0652\u0646\u064f\u0647\u064e\u0627 \u062a\u064e\u0633\u064f\u0631\u0651\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0638\u0650\u0631\u0650\u064a\u0646\u064e",70,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u0642\u064e\u0631\u064e \u062a\u064e\u0634\u064e\u0627\u0628\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",71,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u064c \u0644\u064e\u0627 \u0630\u064e\u0644\u064f\u0648\u0644\u064c \u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0642\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u062b\u064e \u0645\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u064c \u0644\u064e\u0627 \u0634\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0622\u0646\u064e \u062c\u0650\u0626\u0652\u062a\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0641\u064e\u0630\u064e\u0628\u064e\u062d\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u062f\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",72,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0641\u064e\u0627\u062f\u0651\u064e\u0627\u0631\u064e\u0623\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062e\u0652\u0631\u0650\u062c\u064c \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",73,"\u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0647\u064f \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u0650\u0647\u064e\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",74,"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0633\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0647\u0650\u064a\u064e \u0643\u064e\u0627\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0642\u064e\u0633\u0652\u0648\u064e\u0629\u064b \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0651\u064e\u0642\u0651\u064e\u0642\u064f \u0641\u064e\u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u0628\u0650\u0637\u064f \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",75,"\u0623\u064e\u0641\u064e\u062a\u064e\u0637\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0643\u064e\u0644\u064e\u0627\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0639\u064e\u0642\u064e\u0644\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",76,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062a\u064f\u062d\u064e\u062f\u0651\u0650\u062b\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",77,"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",78,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e",79,"\u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",80,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064b\u0627 \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0629\u064b \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0647\u0652\u062f\u064b\u0627 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0647\u0652\u062f\u064e\u0647\u064f \u06d6 \u0623\u064e\u0645\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",81,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0643\u064e\u0633\u064e\u0628\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u062d\u064e\u0627\u0637\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u062a\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",82,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",83,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",84,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0641\u0650\u0643\u064f\u0648\u0646\u064e \u062f\u0650\u0645\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0642\u0652\u0631\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e",85,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u062a\u064e\u0638\u064e\u0627\u0647\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064f\u0645\u0652 \u0623\u064f\u0633\u064e\u0627\u0631\u064e\u0649\u0670 \u062a\u064f\u0641\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u064f\u0647\u064f\u0645\u0652 \u06da \u0623\u064e\u0641\u064e\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u0650\u0632\u0652\u064a\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0634\u064e\u062f\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",86,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",87,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0628\u0650\u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0633\u0650 \u06d7 \u0623\u064e\u0641\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0647\u0652\u0648\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u064f \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e",88,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u063a\u064f\u0644\u0652\u0641\u064c \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",89,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064c \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u064a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650\u062d\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0639\u064e\u0631\u064e\u0641\u064f\u0648\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06da \u0641\u064e\u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",90,"\u0628\u0650\u0626\u0652\u0633\u064e\u0645\u064e\u0627 \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0628\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u0636\u064e\u0628\u064d \u06da \u0648\u064e\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",91,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0627\u0621\u064e\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0642\u064f\u0644\u0652 \u0641\u064e\u0644\u0650\u0645\u064e \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",92,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",93,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0634\u0652\u0631\u0650\u0628\u064f\u0648\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0628\u0650\u0626\u0652\u0633\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",94,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",95,"\u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0647\u064f \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",96,"\u0648\u064e\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0631\u064e\u0635\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u064a\u064e\u0627\u0629\u064d \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u06da \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0648\u0652 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064f \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0645\u064f\u0632\u064e\u062d\u0652\u0632\u0650\u062d\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",97,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0644\u0650\u062c\u0650\u0628\u0652\u0631\u0650\u064a\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0643\u064e \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",98,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u062c\u0650\u0628\u0652\u0631\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u0650\u064a\u0643\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",99,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u0628\u0650\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",100,"\u0623\u064e\u0648\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0639\u064e\u0647\u0652\u062f\u064b\u0627 \u0646\u064e\u0628\u064e\u0630\u064e\u0647\u064f \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",101,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064c \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0628\u064e\u0630\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0627\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",102,"\u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064e\u062a\u0652\u0644\u064f\u0648 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0644\u0652\u0643\u0650 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064e \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064e\u064a\u0652\u0646\u0650 \u0628\u0650\u0628\u064e\u0627\u0628\u0650\u0644\u064e \u0647\u064e\u0627\u0631\u064f\u0648\u062a\u064e \u0648\u064e\u0645\u064e\u0627\u0631\u064f\u0648\u062a\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u06d6 \u0641\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u0650 \u0648\u064e\u0632\u064e\u0648\u0652\u062c\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0636\u064e\u0627\u0631\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u064f\u0648\u0627 \u0644\u064e\u0645\u064e\u0646\u0650 \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u064e\u0627\u0642\u064d \u06da \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u0634\u064e\u0631\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",103,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0644\u064e\u0645\u064e\u062b\u064f\u0648\u0628\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u06d6 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",104,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0631\u064e\u0627\u0639\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0627\u0646\u0652\u0638\u064f\u0631\u0652\u0646\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",105,"\u0645\u064e\u0627 \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0651\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",106,"\u0645\u064e\u0627 \u0646\u064e\u0646\u0652\u0633\u064e\u062e\u0652 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0646\u064f\u0646\u0652\u0633\u0650\u0647\u064e\u0627 \u0646\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u064e\u0627 \u06d7 \u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",107,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",108,"\u0623\u064e\u0645\u0652 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0633\u064f\u0626\u0650\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",109,"\u0648\u064e\u062f\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0648\u0652 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u062f\u064b\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d6 \u0641\u064e\u0627\u0639\u0652\u0641\u064f\u0648\u0627 \u0648\u064e\u0627\u0635\u0652\u0641\u064e\u062d\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",110,"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",111,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u06d7 \u062a\u0650\u0644\u0652\u0643\u064e \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0642\u064f\u0644\u0652 \u0647\u064e\u0627\u062a\u064f\u0648\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",112,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064c \u0641\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",113,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0644\u064e\u064a\u0652\u0633\u064e\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0644\u064e\u064a\u0652\u0633\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u0652\u0644\u064e \u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",114,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0645\u064e\u0646\u064e\u0639\u064e \u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0630\u0652\u0643\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0633\u0652\u0645\u064f\u0647\u064f \u0648\u064e\u0633\u064e\u0639\u064e\u0649\u0670 \u0641\u0650\u064a \u062e\u064e\u0631\u064e\u0627\u0628\u0650\u0647\u064e\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0627\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062e\u0650\u0632\u0652\u064a\u064c \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",115,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u064f \u06da \u0641\u064e\u0623\u064e\u064a\u0652\u0646\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627 \u0641\u064e\u062b\u064e\u0645\u0651\u064e \u0648\u064e\u062c\u0652\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",116,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u06d7 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06d6 \u0628\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0643\u064f\u0644\u0651\u064c \u0644\u064e\u0647\u064f \u0642\u064e\u0627\u0646\u0650\u062a\u064f\u0648\u0646\u064e",117,"\u0628\u064e\u062f\u0650\u064a\u0639\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",118,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0622\u064a\u064e\u0629\u064c \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064e \u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d8 \u062a\u064e\u0634\u064e\u0627\u0628\u064e\u0647\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0642\u064e\u062f\u0652 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",119,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",120,"\u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0645\u0650\u0644\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0647\u064f\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u06d9 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",121,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e\u0647\u064f \u062d\u064e\u0642\u0651\u064e \u062a\u0650\u0644\u064e\u0627\u0648\u064e\u062a\u0650\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",122,u.au,123,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0632\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u064c \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0628\u064e\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0639\u064e\u062f\u0652\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064e\u0627 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",124,"\u0648\u064e\u0625\u0650\u0630\u0650 \u0627\u0628\u0652\u062a\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064d \u0641\u064e\u0623\u064e\u062a\u064e\u0645\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0639\u0650\u0644\u064f\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0645\u064e\u0627\u0645\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a \u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f \u0639\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",125,"\u0648\u064e\u0625\u0650\u0630\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0645\u064e\u062b\u064e\u0627\u0628\u064e\u0629\u064b \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0623\u064e\u0645\u0652\u0646\u064b\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u0642\u064e\u0627\u0645\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0645\u064f\u0635\u064e\u0644\u0651\u064b\u0649 \u06d6 \u0648\u064e\u0639\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0623\u064e\u0646\u0652 \u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0627 \u0628\u064e\u064a\u0652\u062a\u0650\u064a\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0643\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0643\u0651\u064e\u0639\u0650 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",126,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u062f\u064b\u0627 \u0622\u0645\u0650\u0646\u064b\u0627 \u0648\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0623\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0636\u0652\u0637\u064e\u0631\u0651\u064f\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",127,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u0631\u0652\u0641\u064e\u0639\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u064e\u0627\u0639\u0650\u062f\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",128,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064e\u064a\u0652\u0646\u0650 \u0644\u064e\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0646\u064e\u0627 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064e\u0629\u064b \u0644\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0633\u0650\u0643\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064f\u0628\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",129,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u0652 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",130,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u063a\u064e\u0628\u064f \u0639\u064e\u0646\u0652 \u0645\u0650\u0644\u0651\u064e\u0629\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0633\u064e\u0641\u0650\u0647\u064e \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",131,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0623\u064e\u0633\u0652\u0644\u0650\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",132,"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0628\u064e\u0646\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064f \u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",133,"\u0623\u064e\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0625\u0650\u0630\u0652 \u062d\u064e\u0636\u064e\u0631\u064e \u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0628\u064e\u0646\u0650\u064a\u0647\u0650 \u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u064a \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064b\u0627 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",134,u.aj,135,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0628\u064e\u0644\u0652 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",136,"\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",137,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u064d \u06d6 \u0641\u064e\u0633\u064e\u064a\u064e\u0643\u0652\u0641\u0650\u064a\u0643\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",138,"\u0635\u0650\u0628\u0652\u063a\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0635\u0650\u0628\u0652\u063a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0639\u064e\u0627\u0628\u0650\u062f\u064f\u0648\u0646\u064e",139,"\u0642\u064f\u0644\u0652 \u0623\u064e\u062a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u064f\u0648\u0646\u064e",140,"\u0623\u064e\u0645\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0637\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u06d7 \u0642\u064f\u0644\u0652 \u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0643\u064e\u062a\u064e\u0645\u064e \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",141,u.aj,142,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0642\u0650\u0628\u0652\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u064f \u06da \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",143,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0633\u064e\u0637\u064b\u0627 \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u0652\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0636\u0650\u064a\u0639\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",144,"\u0642\u064e\u062f\u0652 \u0646\u064e\u0631\u064e\u0649\u0670 \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064e \u0648\u064e\u062c\u0652\u0647\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0646\u064f\u0648\u064e\u0644\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0642\u0650\u0628\u0652\u0644\u064e\u0629\u064b \u062a\u064e\u0631\u0652\u0636\u064e\u0627\u0647\u064e\u0627 \u06da \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06da \u0648\u064e\u062d\u064e\u064a\u0652\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0644\u0651\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0637\u0652\u0631\u064e\u0647\u064f \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",145,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u062a\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0622\u064a\u064e\u0629\u064d \u0645\u064e\u0627 \u062a\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0642\u0650\u0628\u0652\u0644\u064e\u062a\u064e\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u062a\u064e\u0627\u0628\u0650\u0639\u064d \u0642\u0650\u0628\u0652\u0644\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u062a\u064e\u0627\u0628\u0650\u0639\u064d \u0642\u0650\u0628\u0652\u0644\u064e\u0629\u064e \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",146,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",147,"\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0645\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e",148,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u064d \u0648\u0650\u062c\u0652\u0647\u064e\u0629\u064c \u0647\u064f\u0648\u064e \u0645\u064f\u0648\u064e\u0644\u0651\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0628\u0650\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u06da \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",149,"\u0648\u064e\u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064e \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",150,"\u0648\u064e\u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064e \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06da \u0648\u064e\u062d\u064e\u064a\u0652\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0644\u0651\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0637\u0652\u0631\u064e\u0647\u064f \u0644\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062d\u064f\u062c\u0651\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u0650\u064a \u0648\u064e\u0644\u0650\u0623\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",151,"\u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",152,"\u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0630\u0652\u0643\u064f\u0631\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u0650",153,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0633\u0652\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",154,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064f\u0642\u0652\u062a\u064e\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064c \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",155,"\u0648\u064e\u0644\u064e\u0646\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0648\u0652\u0641\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0648\u0639\u0650 \u0648\u064e\u0646\u064e\u0642\u0652\u0635\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650 \u0648\u064e\u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",156,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e",157,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",158,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0635\u0651\u064e\u0641\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0648\u064e\u0629\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u062c\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0623\u064e\u0648\u0650 \u0627\u0639\u0652\u062a\u064e\u0645\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064e \u0628\u0650\u0647\u0650\u0645\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u0627\u0643\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",159,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u06d9 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0644\u0652\u0639\u064e\u0646\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0644\u0652\u0639\u064e\u0646\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u0639\u0650\u0646\u064f\u0648\u0646\u064e",160,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064f\u0648\u0627 \u0648\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",161,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",162,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",163,"\u0648\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",164,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0648\u064e\u062a\u064e\u0635\u0652\u0631\u0650\u064a\u0641\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u0650 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",165,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u062d\u064f\u0628\u0651\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062d\u064f\u0628\u0651\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652 \u064a\u064e\u0631\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650",166,"\u0625\u0650\u0630\u0652 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064f\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0648\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e\u062a\u0652 \u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0628\u064f",167,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u064b \u0641\u064e\u0646\u064e\u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0621\u064f\u0648\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0631\u0650\u064a\u0647\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0633\u064e\u0631\u064e\u0627\u062a\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0627\u0631\u0650\u062c\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",168,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u062e\u064f\u0637\u064f\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",169,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0633\u0651\u064f\u0648\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",170,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627 \u0623\u064e\u0644\u0652\u0641\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u06d7 \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",171,"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u0652\u0639\u0650\u0642\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0621\u064b \u0648\u064e\u0646\u0650\u062f\u064e\u0627\u0621\u064b \u06da \u0635\u064f\u0645\u0651\u064c \u0628\u064f\u0643\u0652\u0645\u064c \u0639\u064f\u0645\u0652\u064a\u064c \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",172,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",173,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u062d\u0652\u0645\u064e \u0627\u0644\u0652\u062e\u0650\u0646\u0652\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0628\u0650\u0647\u0650 \u0644\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0636\u0652\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u0627\u063a\u064d \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u064d \u0641\u064e\u0644\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",174,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d9 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",175,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u0650 \u06da \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0635\u0652\u0628\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",176,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",177,"\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064e \u0623\u064e\u0646\u0652 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0642\u0650\u0628\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064e \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0622\u062a\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064f\u0628\u0651\u0650\u0647\u0650 \u0630\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u0650\u064a\u0646\u064e \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0649 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u0650 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u0650 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",178,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u0635\u064e\u0627\u0635\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u064e\u0649 \u06d6 \u0627\u0644\u0652\u062d\u064f\u0631\u0651\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064f\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0639\u064f\u0641\u0650\u064a\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0641\u064e\u0627\u062a\u0651\u0650\u0628\u064e\u0627\u0639\u064c \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0623\u064e\u062f\u064e\u0627\u0621\u064c \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064d \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u062e\u0652\u0641\u0650\u064a\u0641\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u06d7 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",179,"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u0650\u0635\u064e\u0627\u0635\u0650 \u062d\u064e\u064a\u064e\u0627\u0629\u064c \u064a\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",180,"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0625\u0650\u0646\u0652 \u062a\u064e\u0631\u064e\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0627\u0644\u0652\u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u0650\u064a\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",181,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0628\u064e\u062f\u0651\u064e\u0644\u064e\u0647\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064e\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f\u0648\u0646\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",182,"\u0641\u064e\u0645\u064e\u0646\u0652 \u062e\u064e\u0627\u0641\u064e \u0645\u0650\u0646\u0652 \u0645\u064f\u0648\u0635\u064d \u062c\u064e\u0646\u064e\u0641\u064b\u0627 \u0623\u064e\u0648\u0652 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0641\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",183,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u064f \u0643\u064e\u0645\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",184,"\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064b\u0627 \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0627\u062a\u064d \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0623\u064f\u062e\u064e\u0631\u064e \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0637\u0650\u064a\u0642\u064f\u0648\u0646\u064e\u0647\u064f \u0641\u0650\u062f\u0652\u064a\u064e\u0629\u064c \u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064d \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0635\u064f\u0648\u0645\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",185,"\u0634\u064e\u0647\u0652\u0631\u064f \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0647\u0650\u062f\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u064e \u0641\u064e\u0644\u0652\u064a\u064e\u0635\u064f\u0645\u0652\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0623\u064f\u062e\u064e\u0631\u064e \u06d7 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064f\u0633\u0652\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u064e \u0648\u064e\u0644\u0650\u062a\u064f\u0643\u0652\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u0650\u062a\u064f\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",186,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u064e\u0643\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0639\u064e\u0646\u0651\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0628\u064c \u06d6 \u0623\u064f\u062c\u0650\u064a\u0628\u064f \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0639\u0650 \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0646\u0650 \u06d6 \u0641\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u0650\u064a \u0648\u064e\u0644\u0652\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u0634\u064f\u062f\u064f\u0648\u0646\u064e",187,"\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064e \u0627\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u0650 \u0627\u0644\u0631\u0651\u064e\u0641\u064e\u062b\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u06da \u0647\u064f\u0646\u0651\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0627\u0633\u064c \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u06d7 \u0639\u064e\u0644\u0650\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u062a\u064e\u0627\u0646\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0641\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0644\u0652\u0622\u0646\u064e \u0628\u064e\u0627\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0637\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u064a\u064e\u0636\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0637\u0650 \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0648\u064e\u062f\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u064e\u0627\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0627\u0643\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u0650 \u06d7 \u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0647\u064e\u0627 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",188,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064f\u062f\u0652\u0644\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064f\u0643\u0651\u064e\u0627\u0645\u0650 \u0644\u0650\u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",189,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0623\u064e\u0647\u0650\u0644\u0651\u064e\u0629\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0647\u0650\u064a\u064e \u0645\u064e\u0648\u064e\u0627\u0642\u0650\u064a\u062a\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u06d7 \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064f \u0628\u0650\u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0645\u0650\u0646\u0652 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064e \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",190,"\u0648\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",191,"\u0648\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u062b\u064e\u0642\u0650\u0641\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",192,"\u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0646\u0652\u062a\u064e\u0647\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",193,"\u0648\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0646\u0652\u062a\u064e\u0647\u064e\u0648\u0652\u0627 \u0641\u064e\u0644\u064e\u0627 \u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",194,"\u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u064f \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064f \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0631\u064f\u0645\u064e\u0627\u062a\u064f \u0642\u0650\u0635\u064e\u0627\u0635\u064c \u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",195,"\u0648\u064e\u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0644\u0652\u0642\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u062a\u0651\u064e\u0647\u0652\u0644\u064f\u0643\u064e\u0629\u0650 \u06db \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0627 \u06db \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",196,"\u0648\u064e\u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u0645\u0652\u0631\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064f\u062d\u0652\u0635\u0650\u0631\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u064a\u0652\u0633\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0644\u0650\u0642\u064f\u0648\u0627 \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u064f \u0645\u064e\u062d\u0650\u0644\u0651\u064e\u0647\u064f \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u0652 \u0628\u0650\u0647\u0650 \u0623\u064e\u0630\u064b\u0649 \u0645\u0650\u0646\u0652 \u0631\u064e\u0623\u0652\u0633\u0650\u0647\u0650 \u0641\u064e\u0641\u0650\u062f\u0652\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0635\u0650\u064a\u064e\u0627\u0645\u064d \u0623\u064e\u0648\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0646\u064f\u0633\u064f\u0643\u064d \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0645\u0652\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u064a\u0652\u0633\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u0648\u064e\u0633\u064e\u0628\u0652\u0639\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u06d7 \u062a\u0650\u0644\u0652\u0643\u064e \u0639\u064e\u0634\u064e\u0631\u064e\u0629\u064c \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u064c \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064f \u062d\u064e\u0627\u0636\u0650\u0631\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",197,"\u0627\u0644\u0652\u062d\u064e\u062c\u0651\u064f \u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064c \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064e\u0627\u062a\u064c \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0641\u064e\u0631\u064e\u0636\u064e \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u0631\u064e\u0641\u064e\u062b\u064e \u0648\u064e\u0644\u064e\u0627 \u0641\u064f\u0633\u064f\u0648\u0642\u064e \u0648\u064e\u0644\u064e\u0627 \u062c\u0650\u062f\u064e\u0627\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u062a\u064e\u0632\u064e\u0648\u0651\u064e\u062f\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0632\u0651\u064e\u0627\u062f\u0650 \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650 \u064a\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",198,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0641\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0631\u064e\u0641\u064e\u0627\u062a\u064d \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0639\u064e\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06d6 \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0647\u064f \u0643\u064e\u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",199,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0641\u0650\u064a\u0636\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u0641\u064e\u0627\u0636\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",200,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0646\u064e\u0627\u0633\u0650\u0643\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0630\u0650\u0643\u0652\u0631\u0650\u0643\u064f\u0645\u0652 \u0622\u0628\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0630\u0650\u0643\u0652\u0631\u064b\u0627 \u06d7 \u0641\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u064e\u0627\u0642\u064d",201,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",202,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",203,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u0650\u064a \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0627\u062a\u064d \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0644\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",204,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u0639\u0652\u062c\u0650\u0628\u064f\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u064a\u064f\u0634\u0652\u0647\u0650\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0644\u0652\u0628\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0644\u064e\u062f\u0651\u064f \u0627\u0644\u0652\u062e\u0650\u0635\u064e\u0627\u0645\u0650",205,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0633\u064e\u0639\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u0650\u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u062b\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0633\u0652\u0644\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064e",206,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f \u0627\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u06da \u0641\u064e\u062d\u064e\u0633\u0652\u0628\u064f\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06da \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",207,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0631\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",208,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u0650\u0644\u0652\u0645\u0650 \u0643\u064e\u0627\u0641\u0651\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u062e\u064f\u0637\u064f\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",209,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0632\u064e\u0644\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",210,"\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0638\u064f\u0644\u064e\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0645\u064e\u0627\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",211,"\u0633\u064e\u0644\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0643\u064e\u0645\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0629\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",212,"\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06d8 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",213,"\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064e \u0641\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0647\u064e\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",214,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0645\u064e\u0633\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u064e\u0627\u0621\u064f \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u064f \u0648\u064e\u0632\u064f\u0644\u0652\u0632\u0650\u0644\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0645\u064e\u062a\u064e\u0649\u0670 \u0646\u064e\u0635\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0646\u064e\u0635\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0631\u0650\u064a\u0628\u064c",215,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u06d6 \u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0644\u0650\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0628\u0652\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u064c",216,"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064f\u0631\u0652\u0647\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u0652\u0631\u064e\u0647\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",217,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0642\u0650\u062a\u064e\u0627\u0644\u064d \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0642\u0650\u062a\u064e\u0627\u0644\u064c \u0641\u0650\u064a\u0647\u0650 \u0643\u064e\u0628\u0650\u064a\u0631\u064c \u06d6 \u0648\u064e\u0635\u064e\u062f\u0651\u064c \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064c \u0628\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u064f \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u062f\u0650\u062f\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0645\u064f\u062a\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u064c \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",218,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",219,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u062e\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0633\u0650\u0631\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c \u0648\u064e\u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0625\u0650\u062b\u0652\u0645\u064f\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0639\u0650\u0647\u0650\u0645\u064e\u0627 \u06d7 \u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",220,"\u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d7 \u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u062e\u064e\u0627\u0644\u0650\u0637\u064f\u0648\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u0644\u0650\u062d\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u0639\u0652\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",221,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064e\u0627\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0644\u064e\u0623\u064e\u0645\u064e\u0629\u064c \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064c \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0628\u0652\u062f\u064c \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064d \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06d6 \u0648\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",222,"\u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u062d\u0650\u064a\u0636\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0630\u064b\u0649 \u0641\u064e\u0627\u0639\u0652\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062d\u0650\u064a\u0636\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0637\u0652\u0647\u064f\u0631\u0652\u0646\u064e \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u0652\u0646\u064e \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u0650\u064a\u0646\u064e",223,"\u0646\u0650\u0633\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u062d\u064e\u0631\u0652\u062b\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u062d\u064e\u0631\u0652\u062b\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u0644\u064e\u0627\u0642\u064f\u0648\u0647\u064f \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",224,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064f\u0631\u0652\u0636\u064e\u0629\u064b \u0644\u0650\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u062a\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",225,"\u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u0650 \u0641\u0650\u064a \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",226,"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u062a\u064e\u0631\u064e\u0628\u0651\u064f\u0635\u064f \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064d \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0641\u064e\u0627\u0621\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",227,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0632\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0637\u0651\u064e\u0644\u064e\u0627\u0642\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",228,"\u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0627\u062a\u064f \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u0652\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064e \u0642\u064f\u0631\u064f\u0648\u0621\u064d \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u0652\u0646\u064e \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650\u0647\u0650\u0646\u0651\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06da \u0648\u064e\u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0631\u064e\u062f\u0651\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u062b\u0652\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06da \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u064c \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",229,"\u0627\u0644\u0637\u0651\u064e\u0644\u064e\u0627\u0642\u064f \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u0627\u0646\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0645\u0652\u0633\u064e\u0627\u0643\u064c \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u0652 \u062a\u064e\u0633\u0652\u0631\u0650\u064a\u062d\u064c \u0628\u0650\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064d \u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u064e\u0627\u0641\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u0627\u0641\u0652\u062a\u064e\u062f\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u06d7 \u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",230,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064e \u0632\u064e\u0648\u0652\u062c\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0647\u064f \u06d7 \u0641\u064e\u0625\u0650\u0646\u0652 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0631\u064e\u0627\u062c\u064e\u0639\u064e\u0627 \u0625\u0650\u0646\u0652 \u0638\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f\u0647\u064e\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",231,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0628\u064e\u0644\u064e\u063a\u0652\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0623\u064e\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u0652 \u0633\u064e\u0631\u0651\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0636\u0650\u0631\u064e\u0627\u0631\u064b\u0627 \u0644\u0650\u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0638\u064e\u0644\u064e\u0645\u064e \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u06da \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u0650 \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",232,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0628\u064e\u0644\u064e\u063a\u0652\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0636\u064f\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0643\u0650\u062d\u0652\u0646\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0636\u064e\u0648\u0652\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0648\u0639\u064e\u0638\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0643\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0637\u0652\u0647\u064e\u0631\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",233,"\u0648\u064e\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u0627\u062a\u064f \u064a\u064f\u0631\u0652\u0636\u0650\u0639\u0652\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u062d\u064e\u0648\u0652\u0644\u064e\u064a\u0652\u0646\u0650 \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0644\u0650\u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0627\u0644\u0631\u0651\u064e\u0636\u064e\u0627\u0639\u064e\u0629\u064e \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064f\u0648\u062f\u0650 \u0644\u064e\u0647\u064f \u0631\u0650\u0632\u0652\u0642\u064f\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0643\u0650\u0633\u0652\u0648\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06da \u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u064e\u0641\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u06da \u0644\u064e\u0627 \u062a\u064f\u0636\u064e\u0627\u0631\u0651\u064e \u0648\u064e\u0627\u0644\u0650\u062f\u064e\u0629\u064c \u0628\u0650\u0648\u064e\u0644\u064e\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0648\u0652\u0644\u064f\u0648\u062f\u064c \u0644\u064e\u0647\u064f \u0628\u0650\u0648\u064e\u0644\u064e\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u0650 \u0645\u0650\u062b\u0652\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d7 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0627 \u0641\u0650\u0635\u064e\u0627\u0644\u064b\u0627 \u0639\u064e\u0646\u0652 \u062a\u064e\u0631\u064e\u0627\u0636\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u062a\u064e\u0634\u064e\u0627\u0648\u064f\u0631\u064d \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0631\u0652\u0636\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0644\u0651\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",234,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u0652\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u064e \u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064d \u0648\u064e\u0639\u064e\u0634\u0652\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u0652\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u0652\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",235,"\u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0639\u064e\u0631\u0651\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u062e\u0650\u0637\u0652\u0628\u064e\u0629\u0650 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0643\u0652\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0633\u064e\u062a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064f\u0648\u064e\u0627\u0639\u0650\u062f\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0633\u0650\u0631\u0651\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0632\u0650\u0645\u064f\u0648\u0627 \u0639\u064f\u0642\u0652\u062f\u064e\u0629\u064e \u0627\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",236,"\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u062a\u064e\u0641\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u064b \u06da \u0648\u064e\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0648\u0633\u0650\u0639\u0650 \u0642\u064e\u062f\u064e\u0631\u064f\u0647\u064f \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0642\u0652\u062a\u0650\u0631\u0650 \u0642\u064e\u062f\u064e\u0631\u064f\u0647\u064f \u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",237,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u0631\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u064b \u0641\u064e\u0646\u0650\u0635\u0652\u0641\u064f \u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0639\u0652\u0641\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0639\u064f\u0642\u0652\u062f\u064e\u0629\u064f \u0627\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u0650 \u06da \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u0652\u0641\u064f\u0648\u0627 \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0633\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",238,"\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0627\u0644\u0652\u0648\u064f\u0633\u0652\u0637\u064e\u0649\u0670 \u0648\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e",239,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0623\u064e\u0648\u0652 \u0631\u064f\u0643\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",240,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064b \u0644\u0650\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0648\u0652\u0644\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u064d \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062e\u064e\u0631\u064e\u062c\u0652\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u0652\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",241,"\u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0627\u062a\u0650 \u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",242,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",243,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u0644\u064f\u0648\u0641\u064c \u062d\u064e\u0630\u064e\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0648\u062a\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",244,"\u0648\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",245,"\u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0642\u0652\u0631\u0650\u0636\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0641\u064e\u064a\u064f\u0636\u064e\u0627\u0639\u0650\u0641\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0623\u064e\u0636\u0652\u0639\u064e\u0627\u0641\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u0652\u0628\u0650\u0636\u064f \u0648\u064e\u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",246,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0628\u0652\u0639\u064e\u062b\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0644\u0650\u0643\u064b\u0627 \u0646\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u0639\u064e\u0633\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",247,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u0652 \u0628\u064e\u0639\u064e\u062b\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0637\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0645\u064e\u0644\u0650\u0643\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u062a\u064e \u0633\u064e\u0639\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0644\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f \u0628\u064e\u0633\u0652\u0637\u064e\u0629\u064b \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0633\u0652\u0645\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0624\u0652\u062a\u0650\u064a \u0645\u064f\u0644\u0652\u0643\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",248,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e \u0622\u064a\u064e\u0629\u064e \u0645\u064f\u0644\u0652\u0643\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u062a\u0651\u064e\u0627\u0628\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u0642\u0650\u064a\u0651\u064e\u0629\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0622\u0644\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0622\u0644\u064f \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",249,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u0635\u064e\u0644\u064e \u0637\u064e\u0627\u0644\u064f\u0648\u062a\u064f \u0628\u0650\u0627\u0644\u0652\u062c\u064f\u0646\u064f\u0648\u062f\u0650 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0646\u064e\u0647\u064e\u0631\u064d \u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0631\u0650\u0628\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0637\u0652\u0639\u064e\u0645\u0652\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u063a\u0652\u062a\u064e\u0631\u064e\u0641\u064e \u063a\u064f\u0631\u0652\u0641\u064e\u0629\u064b \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u06da \u0641\u064e\u0634\u064e\u0631\u0650\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0648\u064e\u0632\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u0637\u064e\u0627\u0642\u064e\u0629\u064e \u0644\u064e\u0646\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0628\u0650\u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0644\u064e\u0627\u0642\u064f\u0648 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u0650\u0626\u064e\u0629\u064d \u0642\u064e\u0644\u0650\u064a\u0644\u064e\u0629\u064d \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0652 \u0641\u0650\u0626\u064e\u0629\u064b \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064b \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",250,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627 \u0644\u0650\u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0641\u0652\u0631\u0650\u063a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0635\u064e\u0628\u0652\u0631\u064b\u0627 \u0648\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u0652 \u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",251,"\u0641\u064e\u0647\u064e\u0632\u064e\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062a\u064e\u0644\u064e \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064f \u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u0622\u062a\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062f\u064e\u0641\u0652\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0644\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",252,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u0652\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",253,"\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06d8 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0633\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0627\u0642\u0652\u062a\u064e\u062a\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0627\u0642\u0652\u062a\u064e\u062a\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",254,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u0628\u064e\u064a\u0652\u0639\u064c \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u064f\u0644\u0651\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064c \u06d7 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",255,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c \u06da \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0626\u064f\u0648\u062f\u064f\u0647\u064f \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",256,"\u0644\u064e\u0627 \u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0647\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u06d6 \u0642\u064e\u062f\u0652 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0627\u0644\u0631\u0651\u064f\u0634\u0652\u062f\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0651\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u0633\u0652\u062a\u064e\u0645\u0652\u0633\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0631\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0648\u064f\u062b\u0652\u0642\u064e\u0649\u0670 \u0644\u064e\u0627 \u0627\u0646\u0652\u0641\u0650\u0635\u064e\u0627\u0645\u064e \u0644\u064e\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",257,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u064f \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",258,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064e\u0627\u062c\u0651\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0641\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u0622\u062a\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064e \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u0623\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u0623\u064f\u0645\u0650\u064a\u062a\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650 \u0641\u064e\u0628\u064f\u0647\u0650\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",259,"\u0623\u064e\u0648\u0652 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0648\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0627\u0626\u064e\u0629\u064e \u0639\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u064e\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0645\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0623\u064e\u0648\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u06d6 \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064e \u0645\u0650\u0627\u0626\u064e\u0629\u064e \u0639\u064e\u0627\u0645\u064d \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650\u0643\u064e \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u0650\u0643\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064e\u0633\u064e\u0646\u0651\u064e\u0647\u0652 \u06d6 \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u0645\u064e\u0627\u0631\u0650\u0643\u064e \u0648\u064e\u0644\u0650\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0643\u064e \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u0650\u0638\u064e\u0627\u0645\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0646\u0652\u0634\u0650\u0632\u064f\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0643\u0652\u0633\u064f\u0648\u0647\u064e\u0627 \u0644\u064e\u062d\u0652\u0645\u064b\u0627 \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",260,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0631\u0650\u0646\u0650\u064a \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u0650\u064a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064e\u0644\u0652\u0628\u0650\u064a \u06d6 \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u062e\u064f\u0630\u0652 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0641\u064e\u0635\u064f\u0631\u0652\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062b\u064f\u0645\u0651\u064e \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0628\u064e\u0644\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u062c\u064f\u0632\u0652\u0621\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0627\u062f\u0652\u0639\u064f\u0647\u064f\u0646\u0651\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0643\u064e \u0633\u064e\u0639\u0652\u064a\u064b\u0627 \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",261,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u0652\u0628\u064e\u062a\u064e\u062a\u0652 \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0646\u064e\u0627\u0628\u0650\u0644\u064e \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0633\u064f\u0646\u0652\u0628\u064f\u0644\u064e\u0629\u064d \u0645\u0650\u0627\u0626\u064e\u0629\u064f \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0636\u064e\u0627\u0639\u0650\u0641\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",262,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u062a\u0652\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u064e\u0646\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0630\u064b\u0649 \u06d9 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",263,"\u0642\u064e\u0648\u0652\u0644\u064c \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064c \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064d \u064a\u064e\u062a\u0652\u0628\u064e\u0639\u064f\u0647\u064e\u0627 \u0623\u064e\u0630\u064b\u0649 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",264,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0627 \u0635\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0630\u064e\u0649\u0670 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f \u0645\u064e\u0627\u0644\u064e\u0647\u064f \u0631\u0650\u0626\u064e\u0627\u0621\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06d6 \u0641\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0635\u064e\u0641\u0652\u0648\u064e\u0627\u0646\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u064e\u0627\u0628\u064c \u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u0648\u064e\u0627\u0628\u0650\u0644\u064c \u0641\u064e\u062a\u064e\u0631\u064e\u0643\u064e\u0647\u064f \u0635\u064e\u0644\u0652\u062f\u064b\u0627 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",265,"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u064e\u062b\u0652\u0628\u0650\u064a\u062a\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0628\u0650\u0631\u064e\u0628\u0652\u0648\u064e\u0629\u064d \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0650\u0644\u064c \u0641\u064e\u0622\u062a\u064e\u062a\u0652 \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0636\u0650\u0639\u0652\u0641\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064f\u0635\u0650\u0628\u0652\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0650\u0644\u064c \u0641\u064e\u0637\u064e\u0644\u0651\u064c \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",266,"\u0623\u064e\u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0646\u064e\u062e\u0650\u064a\u0644\u064d \u0648\u064e\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064c \u0636\u064f\u0639\u064e\u0641\u064e\u0627\u0621\u064f \u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064e\u0627 \u0625\u0650\u0639\u0652\u0635\u064e\u0627\u0631\u064c \u0641\u0650\u064a\u0647\u0650 \u0646\u064e\u0627\u0631\u064c \u0641\u064e\u0627\u062d\u0652\u062a\u064e\u0631\u064e\u0642\u064e\u062a\u0652 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",267,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0633\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0622\u062e\u0650\u0630\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u063a\u0652\u0645\u0650\u0636\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",268,"\u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0642\u0652\u0631\u064e \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",269,"\u064a\u064f\u0624\u0652\u062a\u0650\u064a \u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",270,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0646\u064e\u0630\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0652\u0631\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064d",271,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650 \u0641\u064e\u0646\u0650\u0639\u0650\u0645\u0651\u064e\u0627 \u0647\u0650\u064a\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0624\u0652\u062a\u064f\u0648\u0647\u064e\u0627 \u0627\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u064e \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064f \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",272,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0647\u064f\u062f\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0648\u064e\u062c\u0652\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u064a\u064f\u0648\u064e\u0641\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",273,"\u0644\u0650\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062d\u0652\u0635\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0636\u064e\u0631\u0652\u0628\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u064f \u0623\u064e\u063a\u0652\u0646\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0639\u064e\u0641\u0651\u064f\u0641\u0650 \u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0625\u0650\u0644\u0652\u062d\u064e\u0627\u0641\u064b\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u064c",274,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0633\u0650\u0631\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",275,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u062e\u064e\u0628\u0651\u064e\u0637\u064f\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0651\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u0639\u064f \u0645\u0650\u062b\u0652\u0644\u064f \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u06d7 \u0648\u064e\u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u0639\u064e \u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0647\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0633\u064e\u0644\u064e\u0641\u064e \u0648\u064e\u0623\u064e\u0645\u0652\u0631\u064f\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u062f\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",276,"\u064a\u064e\u0645\u0652\u062d\u064e\u0642\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u0648\u064e\u064a\u064f\u0631\u0652\u0628\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",277,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0648\u064f\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",278,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0628\u064e\u0642\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",279,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0623\u0652\u0630\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u062d\u064e\u0631\u0652\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064f\u0621\u064f\u0648\u0633\u064f \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",280,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0630\u064f\u0648 \u0639\u064f\u0633\u0652\u0631\u064e\u0629\u064d \u0641\u064e\u0646\u064e\u0638\u0650\u0631\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u064a\u0652\u0633\u064e\u0631\u064e\u0629\u064d \u06da \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",281,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",282,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u062f\u064e\u0627\u064a\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u062f\u064e\u064a\u0652\u0646\u064d \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0641\u064e\u0627\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0644\u0652\u064a\u064e\u0643\u0652\u062a\u064f\u0628\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u062a\u0650\u0628\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0628\u064e \u0643\u064e\u0627\u062a\u0650\u0628\u064c \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064e \u0643\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0641\u064e\u0644\u0652\u064a\u064e\u0643\u0652\u062a\u064f\u0628\u0652 \u0648\u064e\u0644\u0652\u064a\u064f\u0645\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0644\u0652\u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0628\u0652\u062e\u064e\u0633\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0633\u064e\u0641\u0650\u064a\u0647\u064b\u0627 \u0623\u064e\u0648\u0652 \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0645\u0650\u0644\u0651\u064e \u0647\u064f\u0648\u064e \u0641\u064e\u0644\u0652\u064a\u064f\u0645\u0652\u0644\u0650\u0644\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u06da \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0634\u0652\u0647\u0650\u062f\u064f\u0648\u0627 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0631\u0650\u062c\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0631\u064e\u062c\u064f\u0644\u064c \u0648\u064e\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0636\u0650\u0644\u0651\u064e \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u062a\u064f\u0630\u064e\u0643\u0651\u0650\u0631\u064e \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0628\u064e \u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064f \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0623\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0647\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0642\u0652\u0633\u064e\u0637\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0642\u0652\u0648\u064e\u0645\u064f \u0644\u0650\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0631\u0652\u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u06d6 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u062d\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u064b \u062a\u064f\u062f\u0650\u064a\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u0650\u062f\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0628\u064e\u0627\u064a\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0636\u064e\u0627\u0631\u0651\u064e \u0643\u064e\u0627\u062a\u0650\u0628\u064c \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u064f\u0633\u064f\u0648\u0642\u064c \u0628\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",283,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0643\u064e\u0627\u062a\u0650\u0628\u064b\u0627 \u0641\u064e\u0631\u0650\u0647\u064e\u0627\u0646\u064c \u0645\u064e\u0642\u0652\u0628\u064f\u0648\u0636\u064e\u0629\u064c \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0645\u0650\u0646\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064f\u0624\u064e\u062f\u0651\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0624\u0652\u062a\u064f\u0645\u0650\u0646\u064e \u0623\u064e\u0645\u064e\u0627\u0646\u064e\u062a\u064e\u0647\u064f \u0648\u064e\u0644\u0652\u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0627 \u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0622\u062b\u0650\u0645\u064c \u0642\u064e\u0644\u0652\u0628\u064f\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c",284,"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0647\u064f \u064a\u064f\u062d\u064e\u0627\u0633\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",285,"\u0622\u0645\u064e\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u06da \u0643\u064f\u0644\u0651\u064c \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u06d6 \u063a\u064f\u0641\u0652\u0631\u064e\u0627\u0646\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",286,"\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u06da \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u06d7 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u0652\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0646\u064e\u0633\u0650\u064a\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u062e\u0652\u0637\u064e\u0623\u0652\u0646\u064e\u0627 \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0635\u0652\u0631\u064b\u0627 \u0643\u064e\u0645\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u0652\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0646\u064e\u0627 \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0645\u0651\u0650\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0627 \u0637\u064e\u0627\u0642\u064e\u0629\u064e \u0644\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u06da \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0646\u064e\u0627 \u0641\u064e\u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e"],t.v)
B.ar9=new A.U([1,u.d,2,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f",3,"\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e",4,"\u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u0630\u064f\u0648 \u0627\u0646\u0652\u062a\u0650\u0642\u064e\u0627\u0645\u064d",5,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650",6,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0635\u064e\u0648\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",7,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u064c \u0645\u064f\u062d\u0652\u0643\u064e\u0645\u064e\u0627\u062a\u064c \u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064f \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064e\u0627\u062a\u064c \u06d6 \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0632\u064e\u064a\u0652\u063a\u064c \u0641\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0627\u0628\u064e\u0647\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0648\u064e\u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0627\u0633\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0643\u064f\u0644\u0651\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",8,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0632\u0650\u063a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0647\u064e\u062f\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0647\u064e\u0628\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u064f",9,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u062c\u064e\u0627\u0645\u0650\u0639\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",10,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u062a\u064f\u063a\u0652\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0648\u062f\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",11,"\u0643\u064e\u062f\u064e\u0623\u0652\u0628\u0650 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",12,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0633\u064e\u062a\u064f\u063a\u0652\u0644\u064e\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06da \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",13,"\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064c \u0641\u0650\u064a \u0641\u0650\u0626\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0627\u0644\u0652\u062a\u064e\u0642\u064e\u062a\u064e\u0627 \u06d6 \u0641\u0650\u0626\u064e\u0629\u064c \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0643\u064e\u0627\u0641\u0650\u0631\u064e\u0629\u064c \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u064e\u0623\u0652\u064a\u064e \u0627\u0644\u0652\u0639\u064e\u064a\u0652\u0646\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0624\u064e\u064a\u0651\u0650\u062f\u064f \u0628\u0650\u0646\u064e\u0635\u0652\u0631\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064b \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650",14,"\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u064f\u0628\u0651\u064f \u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0646\u064e\u0627\u0637\u0650\u064a\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0646\u0652\u0637\u064e\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0630\u0651\u064e\u0647\u064e\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u0650\u0636\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0631\u0652\u062b\u0650 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u062d\u064f\u0633\u0652\u0646\u064f \u0627\u0644\u0652\u0645\u064e\u0622\u0628\u0650",15,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0624\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u06da \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064c \u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",16,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",17,"\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u062d\u064e\u0627\u0631\u0650",18,"\u0634\u064e\u0647\u0650\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06da \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",19,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",20,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0646\u0650 \u06d7 \u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0623\u064e\u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",21,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0648\u064e\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",22,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",23,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u064a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",24,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064b\u0627 \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0627\u062a\u064d \u06d6 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",25,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0645\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0648\u064f\u0641\u0651\u0650\u064a\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",26,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0645\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u062a\u064f\u0624\u0652\u062a\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064e \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u062a\u064e\u0646\u0652\u0632\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u062a\u064f\u0639\u0650\u0632\u0651\u064f \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u062a\u064f\u0630\u0650\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0628\u0650\u064a\u064e\u062f\u0650\u0643\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",27,"\u062a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u062a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06d6 \u0648\u064e\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u06d6 \u0648\u064e\u062a\u064e\u0631\u0652\u0632\u064f\u0642\u064f \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",28,"\u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062a\u064f\u0642\u064e\u0627\u0629\u064b \u06d7 \u0648\u064e\u064a\u064f\u062d\u064e\u0630\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",29,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",30,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u062c\u0650\u062f\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0633\u064f\u0648\u0621\u064d \u062a\u064e\u0648\u064e\u062f\u0651\u064f \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0623\u064e\u0645\u064e\u062f\u064b\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627 \u06d7 \u0648\u064e\u064a\u064f\u062d\u064e\u0630\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",31,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650\u064a \u064a\u064f\u062d\u0652\u0628\u0650\u0628\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",32,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",33,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0649\u0670 \u0622\u062f\u064e\u0645\u064e \u0648\u064e\u0646\u064f\u0648\u062d\u064b\u0627 \u0648\u064e\u0622\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0622\u0644\u064e \u0639\u0650\u0645\u0652\u0631\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",34,"\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064b \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u064d \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",35,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f \u0639\u0650\u0645\u0652\u0631\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0630\u064e\u0631\u0652\u062a\u064f \u0644\u064e\u0643\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064e\u0637\u0652\u0646\u0650\u064a \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0631\u064b\u0627 \u0641\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u0652 \u0645\u0650\u0646\u0651\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",36,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0636\u064e\u0639\u064e\u062a\u0652\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0636\u064e\u0639\u0652\u062a\u064f\u0647\u064e\u0627 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0648\u064e\u0636\u064e\u0639\u064e\u062a\u0652 \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064f \u0643\u064e\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0633\u064e\u0645\u0651\u064e\u064a\u0652\u062a\u064f\u0647\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0639\u0650\u064a\u0630\u064f\u0647\u064e\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062c\u0650\u064a\u0645\u0650",37,"\u0641\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064e\u0627 \u0628\u0650\u0642\u064e\u0628\u064f\u0648\u0644\u064d \u062d\u064e\u0633\u064e\u0646\u064d \u0648\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u064e\u0647\u064e\u0627 \u0646\u064e\u0628\u064e\u0627\u062a\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0648\u064e\u0643\u064e\u0641\u0651\u064e\u0644\u064e\u0647\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u0650\u062d\u0652\u0631\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u062f\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064e\u0627 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0643\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",38,"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062f\u064e\u0639\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064b \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u0650",39,"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064c \u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u0650\u062d\u0652\u0631\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064e\u064a\u0651\u0650\u062f\u064b\u0627 \u0648\u064e\u062d\u064e\u0635\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",40,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0627\u0645\u064c \u0648\u064e\u0642\u064e\u062f\u0652 \u0628\u064e\u0644\u064e\u063a\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u064f \u0648\u064e\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u064c \u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f",41,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0622\u064a\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064e \u0622\u064a\u064e\u062a\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0645\u0652\u0632\u064b\u0627 \u06d7 \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0628\u0652\u0643\u064e\u0627\u0631\u0650",42,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0627\u0643\u0650 \u0648\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0643\u0650 \u0648\u064e\u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0627\u0643\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u0650\u0633\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",43,"\u064a\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064f \u0627\u0642\u0652\u0646\u064f\u062a\u0650\u064a \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0648\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u0650\u064a \u0648\u064e\u0627\u0631\u0652\u0643\u064e\u0639\u0650\u064a \u0645\u064e\u0639\u064e \u0627\u0644\u0631\u0651\u064e\u0627\u0643\u0650\u0639\u0650\u064a\u0646\u064e",44,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u0652 \u064a\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0642\u0652\u0644\u064e\u0627\u0645\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0644\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u0652 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",45,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u0650 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0633\u0652\u0645\u064f\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u062c\u0650\u064a\u0647\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0647\u0652\u062f\u0650 \u0648\u064e\u0643\u064e\u0647\u0652\u0644\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",47,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u062f\u064c \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0646\u0650\u064a \u0628\u064e\u0634\u064e\u0631\u064c \u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",48,"\u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e",49,"\u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0643\u064e\u0647\u064e\u064a\u0652\u0626\u064e\u0629\u0650 \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0641\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u062e\u064f \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0637\u064e\u064a\u0652\u0631\u064b\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0628\u0652\u0631\u0650\u0626\u064f \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0645\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0635\u064e \u0648\u064e\u0623\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0651\u064e\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",50,"\u0648\u064e\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0648\u064e\u0644\u0650\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",51,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u06d7 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",52,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062d\u064e\u0633\u0651\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0634\u0652\u0647\u064e\u062f\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",53,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u062a\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u0646\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0627\u0643\u0652\u062a\u064f\u0628\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",54,"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",55,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u0650\u064a\u0643\u064e \u0648\u064e\u0631\u064e\u0627\u0641\u0650\u0639\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0639\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0643\u064e \u0641\u064e\u0648\u0652\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",56,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",58,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062a\u0652\u0644\u064f\u0648\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",59,"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u062b\u064e\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0622\u062f\u064e\u0645\u064e \u06d6 \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",60,"\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0645\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e",61,"\u0641\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0627\u062c\u0651\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0641\u064e\u0642\u064f\u0644\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0646\u064e\u062f\u0652\u0639\u064f \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0628\u0652\u062a\u064e\u0647\u0650\u0644\u0652 \u0641\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0639\u0652\u0646\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",62,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",63,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",64,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064d \u0633\u064e\u0648\u064e\u0627\u0621\u064d \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0623\u064e\u0631\u0652\u0628\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0627\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",65,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0650 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",66,"\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u062d\u064e\u0627\u062c\u064e\u062c\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0641\u064e\u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",67,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u064a\u064e\u0647\u064f\u0648\u062f\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0652\u0631\u064e\u0627\u0646\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",68,"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",69,"\u0648\u064e\u062f\u0651\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0648\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",70,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e",71,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",72,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u062c\u0652\u0647\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0622\u062e\u0650\u0631\u064e\u0647\u064f \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0647\u064f\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u064e\u0649\u0670 \u0623\u064e\u062d\u064e\u062f\u064c \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064e \u0628\u0650\u064a\u064e\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",74,"\u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0651\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",75,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u064e\u0646\u0652 \u0625\u0650\u0646\u0652 \u062a\u064e\u0623\u0652\u0645\u064e\u0646\u0652\u0647\u064f \u0628\u0650\u0642\u0650\u0646\u0652\u0637\u064e\u0627\u0631\u064d \u064a\u064f\u0624\u064e\u062f\u0651\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0625\u0650\u0646\u0652 \u062a\u064e\u0623\u0652\u0645\u064e\u0646\u0652\u0647\u064f \u0628\u0650\u062f\u0650\u064a\u0646\u064e\u0627\u0631\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u062f\u0651\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062f\u064f\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064c \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",76,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0623\u064e\u0648\u0652\u0641\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",77,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0627 \u062e\u064e\u0644\u064e\u0627\u0642\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",78,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u064a\u064e\u0644\u0652\u0648\u064f\u0648\u0646\u064e \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",79,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064b\u0627 \u0644\u0650\u064a \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0627\u0646\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062f\u0652\u0631\u064f\u0633\u064f\u0648\u0646\u064e",80,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0627\u0628\u064b\u0627 \u06d7 \u0623\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",81,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0648\u064e\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064c \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u062a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0646\u0651\u064e\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0623\u064e\u0642\u0652\u0631\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0635\u0652\u0631\u0650\u064a \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0642\u0652\u0631\u064e\u0631\u0652\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0627\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",82,"\u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",83,"\u0623\u064e\u0641\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u062f\u0650\u064a\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0637\u064e\u0648\u0652\u0639\u064b\u0627 \u0648\u064e\u0643\u064e\u0631\u0652\u0647\u064b\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",84,"\u0642\u064f\u0644\u0652 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u062f\u0650\u064a\u0646\u064b\u0627 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u0642\u0652\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",86,"\u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",87,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",88,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",89,u.h,90,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0627\u0632\u0652\u062f\u064e\u0627\u062f\u064f\u0648\u0627 \u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u0644\u064e\u0646\u0652 \u062a\u064f\u0642\u0652\u0628\u064e\u0644\u064e \u062a\u064e\u0648\u0652\u0628\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u064f\u0648\u0646\u064e",91,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u0642\u0652\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0644\u0652\u0621\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0630\u064e\u0647\u064e\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0648\u0650 \u0627\u0641\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u0650\u0647\u0650 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",92,"\u0644\u064e\u0646\u0652 \u062a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u064c",93,"\u0643\u064f\u0644\u0651\u064f \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u0650 \u0643\u064e\u0627\u0646\u064e \u062d\u0650\u0644\u0651\u064b\u0627 \u0644\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064f \u06d7 \u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0641\u064e\u0627\u062a\u0652\u0644\u064f\u0648\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",94,"\u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",95,"\u0642\u064f\u0644\u0652 \u0635\u064e\u062f\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",96,"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u062a\u064d \u0648\u064f\u0636\u0650\u0639\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u0628\u064e\u0643\u0651\u064e\u0629\u064e \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064b\u0627 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",97,"\u0641\u0650\u064a\u0647\u0650 \u0622\u064a\u064e\u0627\u062a\u064c \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064c \u0645\u064e\u0642\u064e\u0627\u0645\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u062f\u064e\u062e\u064e\u0644\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0622\u0645\u0650\u0646\u064b\u0627 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u062c\u0651\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",98,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",99,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u062a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",100,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",101,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u062a\u064e\u0635\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0647\u064f\u062f\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",102,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",103,"\u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627 \u0628\u0650\u062d\u064e\u0628\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0641\u064e\u0627 \u062d\u064f\u0641\u0652\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0623\u064e\u0646\u0652\u0642\u064e\u0630\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",104,"\u0648\u064e\u0644\u0652\u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",105,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",106,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0628\u0652\u064a\u064e\u0636\u0651\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064c \u0648\u064e\u062a\u064e\u0633\u0652\u0648\u064e\u062f\u0651\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064c \u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u0648\u064e\u062f\u0651\u064e\u062a\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",107,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0628\u0652\u064a\u064e\u0636\u0651\u064e\u062a\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",108,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u0652\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",109,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",110,"\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u062a\u0652 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u062a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652 \u0622\u0645\u064e\u0646\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",111,"\u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0630\u064b\u0649 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",112,"\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0630\u0651\u0650\u0644\u0651\u064e\u0629\u064f \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u062b\u064f\u0642\u0650\u0641\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u062d\u064e\u0628\u0652\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u064e\u0628\u0652\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0628\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u0643\u064e\u0646\u064e\u0629\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0652\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",113,"\u0644\u064e\u064a\u0652\u0633\u064f\u0648\u0627 \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u06d7 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064c \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u0646\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0646\u064e",114,"\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",115,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u0643\u0652\u0641\u064e\u0631\u064f\u0648\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",116,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u062a\u064f\u063a\u0652\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06da \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",117,"\u0645\u064e\u062b\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0631\u0650\u064a\u062d\u064d \u0641\u0650\u064a\u0647\u064e\u0627 \u0635\u0650\u0631\u0651\u064c \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652 \u062d\u064e\u0631\u0652\u062b\u064e \u0642\u064e\u0648\u0652\u0645\u064d \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e\u062a\u0652\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",118,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0628\u0650\u0637\u064e\u0627\u0646\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0628\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u062f\u0651\u064f\u0648\u0627 \u0645\u064e\u0627 \u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u0628\u064e\u062f\u064e\u062a\u0650 \u0627\u0644\u0652\u0628\u064e\u063a\u0652\u0636\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062e\u0652\u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06da \u0642\u064e\u062f\u0652 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",119,"\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064f\u0648\u0644\u064e\u0627\u0621\u0650 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0643\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0639\u064e\u0636\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u064e\u0627\u0645\u0650\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0638\u0650 \u06da \u0642\u064f\u0644\u0652 \u0645\u064f\u0648\u062a\u064f\u0648\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0638\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",120,"\u0625\u0650\u0646\u0652 \u062a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0643\u064f\u0645\u0652 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u062a\u064e\u0633\u064f\u0624\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u064a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u062f\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u064c",121,"\u0648\u064e\u0625\u0650\u0630\u0652 \u063a\u064e\u062f\u064e\u0648\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u062a\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u064e\u0642\u064e\u0627\u0639\u0650\u062f\u064e \u0644\u0650\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",122,"\u0625\u0650\u0630\u0652 \u0647\u064e\u0645\u0651\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0641\u0652\u0634\u064e\u0644\u064e\u0627 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u064e\u0627 \u06d7 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",123,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0635\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0628\u064e\u062f\u0652\u0631\u064d \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064c \u06d6 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",124,"\u0625\u0650\u0630\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0645\u0650\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u0650 \u0622\u0644\u064e\u0627\u0641\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0646\u0652\u0632\u064e\u0644\u0650\u064a\u0646\u064e",125,"\u0628\u064e\u0644\u064e\u0649\u0670 \u06da \u0625\u0650\u0646\u0652 \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064f\u0645\u0652\u062f\u0650\u062f\u0652\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0645\u0652\u0633\u064e\u0629\u0650 \u0622\u0644\u064e\u0627\u0641\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0633\u064e\u0648\u0651\u0650\u0645\u0650\u064a\u0646\u064e",126,"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u062a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0635\u0652\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",127,"\u0644\u0650\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064e \u0637\u064e\u0631\u064e\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u064a\u064e\u0643\u0652\u0628\u0650\u062a\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627 \u062e\u064e\u0627\u0626\u0650\u0628\u0650\u064a\u0646\u064e",128,"\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0623\u064e\u0648\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",129,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",130,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u0623\u064e\u0636\u0652\u0639\u064e\u0627\u0641\u064b\u0627 \u0645\u064f\u0636\u064e\u0627\u0639\u064e\u0641\u064e\u0629\u064b \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",131,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u0652 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",132,"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",133,"\u0648\u064e\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0631\u0652\u0636\u064f\u0647\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u0652 \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",134,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0627\u0638\u0650\u0645\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0638\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",135,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0630\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0635\u0650\u0631\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",136,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0623\u064e\u062c\u0652\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e",137,"\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0633\u064f\u0646\u064e\u0646\u064c \u0641\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",138,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u0646\u064c \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",139,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",140,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0643\u064f\u0645\u0652 \u0642\u064e\u0631\u0652\u062d\u064c \u0641\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0633\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0642\u064e\u0631\u0652\u062d\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064f \u06da \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064f \u0646\u064f\u062f\u064e\u0627\u0648\u0650\u0644\u064f\u0647\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",141,"\u0648\u064e\u0644\u0650\u064a\u064f\u0645\u064e\u062d\u0651\u0650\u0635\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0645\u0652\u062d\u064e\u0642\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",142,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",143,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",144,"\u0648\u064e\u0645\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u06da \u0623\u064e\u0641\u064e\u0625\u0650\u0646\u0652 \u0645\u064e\u0627\u062a\u064e \u0623\u064e\u0648\u0652 \u0642\u064f\u062a\u0650\u0644\u064e \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",145,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u064d \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u064f\u0648\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u0624\u064e\u062c\u0651\u064e\u0644\u064b\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652 \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0646\u064f\u0624\u0652\u062a\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652 \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0646\u064f\u0624\u0652\u062a\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0633\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",146,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0642\u064e\u0627\u062a\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0631\u0650\u0628\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0641\u064e\u0645\u064e\u0627 \u0648\u064e\u0647\u064e\u0646\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0636\u064e\u0639\u064f\u0641\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",147,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0641\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u0652 \u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",148,"\u0641\u064e\u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",149,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627 \u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",150,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",151,"\u0633\u064e\u0646\u064f\u0644\u0652\u0642\u0650\u064a \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064f\u0639\u0652\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0628\u0650\u0647\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06da \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u062b\u0652\u0648\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",152,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0630\u0652 \u062a\u064e\u062d\u064f\u0633\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0634\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u06da \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06da \u062b\u064f\u0645\u0651\u064e \u0635\u064e\u0631\u064e\u0641\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0641\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",153,"\u0625\u0650\u0630\u0652 \u062a\u064f\u0635\u0652\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u0652\u0648\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062d\u064e\u062f\u064d \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064f\u062e\u0652\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062b\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u063a\u064e\u0645\u0651\u064b\u0627 \u0628\u0650\u063a\u064e\u0645\u0651\u064d \u0644\u0650\u0643\u064e\u064a\u0652\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",154,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0652\u063a\u064e\u0645\u0651\u0650 \u0623\u064e\u0645\u064e\u0646\u064e\u0629\u064b \u0646\u064f\u0639\u064e\u0627\u0633\u064b\u0627 \u064a\u064e\u063a\u0652\u0634\u064e\u0649\u0670 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u064e\u0645\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0638\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06d7 \u064a\u064f\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e \u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0645\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u0652\u0646\u064e\u0627 \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0628\u064e\u0631\u064e\u0632\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0644\u0650\u064a\u064e\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u064f\u0645\u064e\u062d\u0651\u0650\u0635\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",155,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0632\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u0650 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0641\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",156,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u063a\u064f\u0632\u0651\u064b\u0649 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0644\u0650\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0633\u0652\u0631\u064e\u0629\u064b \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",157,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0642\u064f\u062a\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652 \u0645\u064f\u062a\u0651\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",158,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0645\u064f\u062a\u0651\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0642\u064f\u062a\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",159,"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u0646\u0652\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u064e\u0638\u0651\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064e \u0627\u0644\u0652\u0642\u064e\u0644\u0652\u0628\u0650 \u0644\u064e\u0627\u0646\u0652\u0641\u064e\u0636\u0651\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u0650\u0643\u064e \u06d6 \u0641\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0634\u064e\u0627\u0648\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u0652\u062a\u064e \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u0650\u064a\u0646\u064e",160,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u063a\u064e\u0627\u0644\u0650\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062e\u0652\u0630\u064f\u0644\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",161,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u063a\u064f\u0644\u0651\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0644\u064f\u0644\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0645\u064e\u0627 \u063a\u064e\u0644\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",162,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u0646\u0652 \u0628\u064e\u0627\u0621\u064e \u0628\u0650\u0633\u064e\u062e\u064e\u0637\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06da \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",163,"\u0647\u064f\u0645\u0652 \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",164,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u0652 \u0628\u064e\u0639\u064e\u062b\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",165,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0642\u064e\u062f\u0652 \u0623\u064e\u0635\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",166,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u0650 \u0641\u064e\u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",167,"\u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0641\u064e\u0642\u064f\u0648\u0627 \u06da \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0650 \u0627\u062f\u0652\u0641\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0642\u0650\u062a\u064e\u0627\u0644\u064b\u0627 \u0644\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u06d7 \u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u06da \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",168,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064e\u0639\u064e\u062f\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0623\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0646\u064e\u0627 \u0645\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0641\u064e\u0627\u062f\u0652\u0631\u064e\u0621\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",169,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064b\u0627 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0631\u0652\u0632\u064e\u0642\u064f\u0648\u0646\u064e",170,"\u0641\u064e\u0631\u0650\u062d\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u062d\u064e\u0642\u064f\u0648\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",171,"\u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u0636\u0652\u0644\u064d \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",172,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u062d\u064f \u06da \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",173,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0642\u064e\u062f\u0652 \u062c\u064e\u0645\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u062e\u0652\u0634\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062d\u064e\u0633\u0652\u0628\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0648\u064e\u0643\u0650\u064a\u0644\u064f",174,"\u0641\u064e\u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u0636\u0652\u0644\u064d \u0644\u064e\u0645\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064c \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",175,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",176,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0652\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d7 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0638\u0651\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",177,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",178,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u0652\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u0652\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0632\u0652\u062f\u064e\u0627\u062f\u064f\u0648\u0627 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",179,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0630\u064e\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0645\u0650\u064a\u0632\u064e \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0637\u0652\u0644\u0650\u0639\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u062a\u064e\u0628\u0650\u064a \u0645\u0650\u0646\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0641\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",180,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0633\u064e\u064a\u064f\u0637\u064e\u0648\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0628\u064e\u062e\u0650\u0644\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u064a\u0631\u064e\u0627\u062b\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",181,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0633\u064e\u0645\u0650\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0642\u0650\u064a\u0631\u064c \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u063a\u0652\u0646\u0650\u064a\u064e\u0627\u0621\u064f \u06d8 \u0633\u064e\u0646\u064e\u0643\u0652\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0642\u064e\u062a\u0652\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0648\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",182,u.Z,183,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0647\u0650\u062f\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u064e\u0627 \u0628\u0650\u0642\u064f\u0631\u0652\u0628\u064e\u0627\u0646\u064d \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d7 \u0642\u064f\u0644\u0652 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u064a \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0644\u0650\u0645\u064e \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",184,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0630\u0651\u0650\u0628\u064e \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0650\u064a\u0631\u0650",185,"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0630\u064e\u0627\u0626\u0650\u0642\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0648\u0652\u0646\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0632\u064f\u062d\u0652\u0632\u0650\u062d\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u0627\u0632\u064e \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u063a\u064f\u0631\u064f\u0648\u0631\u0650",186,"\u0644\u064e\u062a\u064f\u0628\u0652\u0644\u064e\u0648\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0623\u064e\u0630\u064b\u0649 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0632\u0652\u0645\u0650 \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",187,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0644\u064e\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f\u0646\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0647\u064f \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0631\u064e\u0627\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",188,"\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0648\u0652\u0627 \u0648\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u0645\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0641\u064e\u0627\u0632\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",189,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",190,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",191,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u0650\u064a\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0642\u064f\u0639\u064f\u0648\u062f\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0627\u0637\u0650\u0644\u064b\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0641\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",192,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u064e\u0646\u0652 \u062a\u064f\u062f\u0652\u062e\u0650\u0644\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u0652\u0632\u064e\u064a\u0652\u062a\u064e\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064d",193,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0645\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u064b\u0627 \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a \u0644\u0650\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0623\u064e\u0646\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0641\u0651\u0650\u0631\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u0650",194,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0622\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064f\u0633\u064f\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0632\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",195,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u0650\u064a \u0644\u064e\u0627 \u0623\u064f\u0636\u0650\u064a\u0639\u064f \u0639\u064e\u0645\u064e\u0644\u064e \u0639\u064e\u0627\u0645\u0650\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u06d6 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u064d \u06d6 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064f\u0648\u0630\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0648\u064e\u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0644\u064e\u0623\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u062d\u064f\u0633\u0652\u0646\u064f \u0627\u0644\u062b\u0651\u064e\u0648\u064e\u0627\u0628\u0650",196,"\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u0650\u0644\u064e\u0627\u062f\u0650",197,"\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06da \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",198,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064f\u0632\u064f\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u0650",199,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062e\u064e\u0627\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",200,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u0631\u064e\u0627\u0628\u0650\u0637\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e"],t.v)
B.asg=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0632\u064e\u0648\u0652\u062c\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064b \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0631\u064e\u0642\u0650\u064a\u0628\u064b\u0627",2,"\u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0628\u0650\u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u062d\u064f\u0648\u0628\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",3,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0642\u0652\u0633\u0650\u0637\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0641\u064e\u0627\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0645\u064e\u0627 \u0637\u064e\u0627\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0645\u064e\u062b\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u062b\u064f\u0644\u064e\u0627\u062b\u064e \u0648\u064e\u0631\u064f\u0628\u064e\u0627\u0639\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u0641\u064e\u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u0648\u0644\u064f\u0648\u0627",4,"\u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0635\u064e\u062f\u064f\u0642\u064e\u0627\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0646\u0650\u062d\u0652\u0644\u064e\u0629\u064b \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0637\u0650\u0628\u0652\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0647\u064f \u0647\u064e\u0646\u0650\u064a\u0626\u064b\u0627 \u0645\u064e\u0631\u0650\u064a\u0626\u064b\u0627",5,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0624\u0652\u062a\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0642\u0650\u064a\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u064f\u0648\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0627\u0643\u0652\u0633\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627",6,"\u0648\u064e\u0627\u0628\u0652\u062a\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u064e \u0641\u064e\u0625\u0650\u0646\u0652 \u0622\u0646\u064e\u0633\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0634\u0652\u062f\u064b\u0627 \u0641\u064e\u0627\u062f\u0652\u0641\u064e\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0641\u064b\u0627 \u0648\u064e\u0628\u0650\u062f\u064e\u0627\u0631\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u0641\u0650\u0641\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0642\u0650\u064a\u0631\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u0643\u064f\u0644\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0641\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0634\u0652\u0647\u0650\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0633\u0650\u064a\u0628\u064b\u0627",7,"\u0644\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0623\u064e\u0648\u0652 \u0643\u064e\u062b\u064f\u0631\u064e \u06da \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u064e\u0641\u0652\u0631\u064f\u0648\u0636\u064b\u0627",8,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0645\u064e\u0629\u064e \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064f \u0641\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627",9,"\u0648\u064e\u0644\u0652\u064a\u064e\u062e\u0652\u0634\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064b \u0636\u0650\u0639\u064e\u0627\u0641\u064b\u0627 \u062e\u064e\u0627\u0641\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u0652\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0633\u064e\u062f\u0650\u064a\u062f\u064b\u0627",10,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u0646\u064e\u0627\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0633\u064e\u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",11,"\u064a\u064f\u0648\u0635\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0644\u0650\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u0650 \u0645\u0650\u062b\u0652\u0644\u064f \u062d\u064e\u0638\u0651\u0650 \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e \u0646\u0650\u0633\u064e\u0627\u0621\u064b \u0641\u064e\u0648\u0652\u0642\u064e \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u062b\u064f\u0644\u064f\u062b\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0644\u064e\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u0650\u0635\u0652\u0641\u064f \u06da \u0648\u064e\u0644\u0650\u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0652\u0647\u0650 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064c \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064c \u0648\u064e\u0648\u064e\u0631\u0650\u062b\u064e\u0647\u064f \u0623\u064e\u0628\u064e\u0648\u064e\u0627\u0647\u064f \u0641\u064e\u0644\u0650\u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0627\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u064f \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0625\u0650\u062e\u0652\u0648\u064e\u0629\u064c \u0641\u064e\u0644\u0650\u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0627\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f \u06da \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064d \u064a\u064f\u0648\u0635\u0650\u064a \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u062f\u064e\u064a\u0652\u0646\u064d \u06d7 \u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u06da \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",12,"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u0650\u0635\u0652\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u062f\u064c \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u062f\u064c \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064f\u0628\u064f\u0639\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e \u06da \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064d \u064a\u064f\u0648\u0635\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u062f\u064e\u064a\u0652\u0646\u064d \u06da \u0648\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0631\u0651\u064f\u0628\u064f\u0639\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u062f\u064c \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u062f\u064c \u0641\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u062b\u0651\u064f\u0645\u064f\u0646\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u06da \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064d \u062a\u064f\u0648\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u062f\u064e\u064a\u0652\u0646\u064d \u06d7 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u064a\u064f\u0648\u0631\u064e\u062b\u064f \u0643\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064b \u0623\u064e\u0648\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u062e\u064c \u0623\u064e\u0648\u0652 \u0623\u064f\u062e\u0652\u062a\u064c \u0641\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u0641\u0650\u064a \u0627\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u0650 \u06da \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064d \u064a\u064f\u0648\u0635\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u062f\u064e\u064a\u0652\u0646\u064d \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0636\u064e\u0627\u0631\u0651\u064d \u06da \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",13,"\u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",14,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0635\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e\u0647\u064f \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064b\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",15,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0634\u0652\u0647\u0650\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0623\u064e\u0648\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",16,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0630\u064e\u0627\u0646\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0627\u0646\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0622\u0630\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0627\u0628\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e\u0627 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",17,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0628\u064e\u0629\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0644\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0650\u064a\u0628\u064d \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",18,"\u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e\u062a\u0650 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064f\u0628\u0652\u062a\u064f \u0627\u0644\u0652\u0622\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",19,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0631\u0650\u062b\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0643\u064e\u0631\u0652\u0647\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0636\u064f\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064e\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u0650 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064d \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u06da \u0648\u064e\u0639\u064e\u0627\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0631\u0650\u0647\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u0652\u0631\u064e\u0647\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",20,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u062a\u064f\u0645\u064f \u0627\u0633\u0652\u062a\u0650\u0628\u0652\u062f\u064e\u0627\u0644\u064e \u0632\u064e\u0648\u0652\u062c\u064d \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0632\u064e\u0648\u0652\u062c\u064d \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0642\u0650\u0646\u0652\u0637\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0623\u064e\u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064f \u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",21,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0641\u0652\u0636\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064b\u0627",22,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0645\u064e\u0627 \u0646\u064e\u0643\u064e\u062d\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u0652 \u0633\u064e\u0644\u064e\u0641\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064b \u0648\u064e\u0645\u064e\u0642\u0652\u062a\u064b\u0627 \u0648\u064e\u0633\u064e\u0627\u0621\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",23,"\u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0645\u0651\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u062e\u064e\u0627\u0644\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u062e\u0650 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u062a\u0650 \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0623\u064e\u0631\u0652\u0636\u064e\u0639\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0636\u064e\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u064f \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0628\u064e\u0627\u0626\u0650\u0628\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0641\u0650\u064a \u062d\u064f\u062c\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u062f\u064e\u062e\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062f\u064e\u062e\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u062d\u064e\u0644\u064e\u0627\u0626\u0650\u0644\u064f \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u0644\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u062a\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u0652 \u0633\u064e\u0644\u064e\u0641\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",24,"\u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0627\u0621\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0645\u064f\u062d\u0652\u0635\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0633\u064e\u0627\u0641\u0650\u062d\u0650\u064a\u0646\u064e \u06da \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u064b \u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0636\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",25,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u0639\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0637\u064e\u0648\u0652\u0644\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0643\u0650\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0645\u0650\u0646\u0652 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u062a\u064e\u064a\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u06da \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0641\u064e\u0627\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u064d \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0633\u064e\u0627\u0641\u0650\u062d\u064e\u0627\u062a\u064d \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0627\u062a\u0650 \u0623\u064e\u062e\u0652\u062f\u064e\u0627\u0646\u064d \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u062d\u0652\u0635\u0650\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e \u0628\u0650\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064d \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0646\u0650\u0635\u0652\u0641\u064f \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0634\u0650\u064a\u064e \u0627\u0644\u0652\u0639\u064e\u0646\u064e\u062a\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",26,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0646\u064e\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",27,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0627 \u0645\u064e\u064a\u0652\u0644\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",28,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062e\u064e\u0641\u0651\u0650\u0641\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u062e\u064f\u0644\u0650\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627",29,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0639\u064e\u0646\u0652 \u062a\u064e\u0631\u064e\u0627\u0636\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",30,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u0646\u064f\u0635\u0652\u0644\u0650\u064a\u0647\u0650 \u0646\u064e\u0627\u0631\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",31,"\u0625\u0650\u0646\u0652 \u062a\u064e\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0643\u064e\u0628\u064e\u0627\u0626\u0650\u0631\u064e \u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0646\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u0652 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u062f\u0652\u062e\u064e\u0644\u064b\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064b\u0627",32,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0627 \u0645\u064e\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0644\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0644\u0650\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0633\u064e\u0628\u0652\u0646\u064e \u06da \u0648\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",33,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0648\u064e\u0627\u0644\u0650\u064a\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0642\u064e\u062f\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",34,"\u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064f \u0642\u064e\u0648\u0651\u064e\u0627\u0645\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u064f \u0642\u064e\u0627\u0646\u0650\u062a\u064e\u0627\u062a\u064c \u062d\u064e\u0627\u0641\u0650\u0638\u064e\u0627\u062a\u064c \u0644\u0650\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u062d\u064e\u0641\u0650\u0638\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0646\u064f\u0634\u064f\u0648\u0632\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0639\u0650\u0638\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0627\u0647\u0652\u062c\u064f\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650 \u0648\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u063a\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",35,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0634\u0650\u0642\u064e\u0627\u0642\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0641\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0627 \u062d\u064e\u0643\u064e\u0645\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u062d\u064e\u0643\u064e\u0645\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064e\u0627 \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u064b\u0627 \u064a\u064f\u0648\u064e\u0641\u0651\u0650\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",36,"\u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0628\u0650\u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0627\u0631\u0650 \u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0627\u0631\u0650 \u0627\u0644\u0652\u062c\u064f\u0646\u064f\u0628\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u062d\u0650\u0628\u0650 \u0628\u0650\u0627\u0644\u0652\u062c\u064e\u0646\u0652\u0628\u0650 \u0648\u064e\u0627\u0628\u0652\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062e\u0652\u062a\u064e\u0627\u0644\u064b\u0627 \u0641\u064e\u062e\u064f\u0648\u0631\u064b\u0627",37,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u0648\u064e\u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u0647\u0650\u064a\u0646\u064b\u0627",38,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0626\u064e\u0627\u0621\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0644\u064e\u0647\u064f \u0642\u064e\u0631\u0650\u064a\u0646\u064b\u0627 \u0641\u064e\u0633\u064e\u0627\u0621\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u064b\u0627",39,"\u0648\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0648\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",40,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u064f \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u064a\u064f\u0636\u064e\u0627\u0639\u0650\u0641\u0652\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u0650 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",41,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0628\u0650\u0634\u064e\u0647\u0650\u064a\u062f\u064d \u0648\u064e\u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",42,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u0648\u064f\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0648\u0652 \u062a\u064f\u0633\u064e\u0648\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064b\u0627",43,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0633\u064f\u0643\u064e\u0627\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064f\u0628\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0627\u0628\u0650\u0631\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u063a\u0652\u062a\u064e\u0633\u0650\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0626\u0650\u0637\u0650 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627\u0645\u064e\u0633\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627 \u0635\u064e\u0639\u0650\u064a\u062f\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0641\u064e\u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0641\u064f\u0648\u0651\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",44,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",45,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",46,"\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0644\u0650\u0645\u064e \u0639\u064e\u0646\u0652 \u0645\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0633\u0652\u0645\u064e\u0639\u064d \u0648\u064e\u0631\u064e\u0627\u0639\u0650\u0646\u064e\u0627 \u0644\u064e\u064a\u0651\u064b\u0627 \u0628\u0650\u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0637\u064e\u0639\u0652\u0646\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u0652 \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u0652\u0648\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",47,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u0637\u0652\u0645\u0650\u0633\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u064b\u0627 \u0641\u064e\u0646\u064e\u0631\u064f\u062f\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0644\u0652\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0639\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u062a\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627",48,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0645\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",49,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0632\u064e\u0643\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u064b\u0627",50,"\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u06d6 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",51,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062c\u0650\u0628\u0652\u062a\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",52,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0644\u0652\u0639\u064e\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",53,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u0641\u064e\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0646\u064e\u0642\u0650\u064a\u0631\u064b\u0627",54,"\u0623\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0633\u064f\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0622\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u064f\u0644\u0652\u0643\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",55,"\u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0635\u064e\u062f\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",56,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0633\u064e\u0648\u0652\u0641\u064e \u0646\u064f\u0635\u0652\u0644\u0650\u064a\u0647\u0650\u0645\u0652 \u0646\u064e\u0627\u0631\u064b\u0627 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u0636\u0650\u062c\u064e\u062a\u0652 \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u062f\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064f\u0644\u064f\u0648\u062f\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",57,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064c \u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064c \u06d6 \u0648\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u0638\u0650\u0644\u0651\u064b\u0627 \u0638\u064e\u0644\u0650\u064a\u0644\u064b\u0627",58,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u064e\u062f\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u0627\u0646\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0643\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0646\u0650\u0639\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",59,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064b\u0627",60,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0632\u0652\u0639\u064f\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u062d\u064e\u0627\u0643\u064e\u0645\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",61,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652\u0643\u064e \u0635\u064f\u062f\u064f\u0648\u062f\u064b\u0627",62,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064e \u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u062a\u064e\u0648\u0652\u0641\u0650\u064a\u0642\u064b\u0627",63,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u0650\u0638\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0628\u064e\u0644\u0650\u064a\u063a\u064b\u0627",64,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0637\u064e\u0627\u0639\u064e \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0644\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",65,"\u0641\u064e\u0644\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u062d\u064e\u0643\u0651\u0650\u0645\u064f\u0648\u0643\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0634\u064e\u062c\u064e\u0631\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u0631\u064e\u062c\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064e \u0648\u064e\u064a\u064f\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627 \u062a\u064e\u0633\u0652\u0644\u0650\u064a\u0645\u064b\u0627",66,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0650 \u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0650 \u0627\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u0638\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064e \u062a\u064e\u062b\u0652\u0628\u0650\u064a\u062a\u064b\u0627",67,"\u0648\u064e\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",68,"\u0648\u064e\u0644\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0635\u0650\u0631\u064e\u0627\u0637\u064b\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627",69,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e \u06da \u0648\u064e\u062d\u064e\u0633\u064f\u0646\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0631\u064e\u0641\u0650\u064a\u0642\u064b\u0627",70,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",71,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062e\u064f\u0630\u064f\u0648\u0627 \u062d\u0650\u0630\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u062b\u064f\u0628\u064e\u0627\u062a\u064d \u0623\u064e\u0648\u0650 \u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",72,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u064a\u064f\u0628\u064e\u0637\u0651\u0650\u0626\u064e\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0630\u0652 \u0644\u064e\u0645\u0652 \u0623\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",73,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0636\u0652\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064c \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0641\u064f\u0648\u0632\u064e \u0641\u064e\u0648\u0652\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",74,"\u0641\u064e\u0644\u0652\u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u0652\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064f\u0642\u0652\u062a\u064e\u0644\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u0652 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u0646\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",75,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650 \u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",76,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0643\u064e\u0627\u0646\u064e \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627",77,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u064b \u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u0645\u064e \u0643\u064e\u062a\u064e\u0628\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u062e\u0651\u064e\u0631\u0652\u062a\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0642\u064e\u0631\u0650\u064a\u0628\u064d \u06d7 \u0642\u064f\u0644\u0652 \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u064b\u0627",78,"\u0623\u064e\u064a\u0652\u0646\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u064a\u064f\u062f\u0652\u0631\u0650\u0643\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0628\u064f\u0631\u064f\u0648\u062c\u064d \u0645\u064f\u0634\u064e\u064a\u0651\u064e\u062f\u064e\u0629\u064d \u06d7 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u06da \u0642\u064f\u0644\u0652 \u0643\u064f\u0644\u0651\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064b\u0627",79,"\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064d \u0641\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064d \u0641\u064e\u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e \u06da \u0648\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",80,"\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0637\u064e\u0627\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0641\u0650\u064a\u0638\u064b\u0627",81,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0637\u064e\u0627\u0639\u064e\u0629\u064c \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u0628\u064e\u064a\u0651\u064e\u062a\u064e \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",82,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u062f\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",83,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0646\u0650 \u0623\u064e\u0648\u0650 \u0627\u0644\u0652\u062e\u064e\u0648\u0652\u0641\u0650 \u0623\u064e\u0630\u064e\u0627\u0639\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0631\u064e\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0650\u0645\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0628\u0650\u0637\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0644\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",84,"\u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u064e\u0641\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0641\u0652\u0633\u064e\u0643\u064e \u06da \u0648\u064e\u062d\u064e\u0631\u0651\u0650\u0636\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d6 \u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0641\u0651\u064e \u0628\u064e\u0623\u0652\u0633\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u0652\u0633\u064b\u0627 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062a\u064e\u0646\u0652\u0643\u0650\u064a\u0644\u064b\u0627",85,"\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u0652 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064b \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u0652 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064b \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064b \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0643\u0650\u0641\u0652\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064f\u0642\u0650\u064a\u062a\u064b\u0627",86,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064f\u064a\u0651\u0650\u064a\u062a\u064f\u0645\u0652 \u0628\u0650\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u064d \u0641\u064e\u062d\u064e\u064a\u0651\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u0633\u0650\u064a\u0628\u064b\u0627",87,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0644\u064e\u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0635\u0652\u062f\u064e\u0642\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u064b\u0627",88,"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u0626\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0631\u0652\u0643\u064e\u0633\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06da \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0647\u0652\u062f\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",89,"\u0648\u064e\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",90,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064c \u0623\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064f\u0645\u0652 \u062d\u064e\u0635\u0650\u0631\u064e\u062a\u0652 \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0633\u064e\u0644\u0651\u064e\u0637\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u06da \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0639\u0652\u062a\u064e\u0632\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",91,"\u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u0645\u064e\u0646\u064f\u0648\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064e\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0627 \u0631\u064f\u062f\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0623\u064f\u0631\u0652\u0643\u0650\u0633\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0644\u0652\u0642\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0648\u064e\u064a\u064e\u0643\u064f\u0641\u0651\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u062b\u064e\u0642\u0650\u0641\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064f\u0645\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",92,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0637\u064e\u0623\u064b \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u062a\u064e\u0644\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u062e\u064e\u0637\u064e\u0623\u064b \u0641\u064e\u062a\u064e\u062d\u0652\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064d \u0648\u064e\u062f\u0650\u064a\u064e\u0629\u064c \u0645\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064f\u0648\u0627 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u062a\u064e\u062d\u0652\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064d \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064c \u0641\u064e\u062f\u0650\u064a\u064e\u0629\u064c \u0645\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u062a\u064e\u062d\u0652\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064d \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u0634\u064e\u0647\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u062a\u064e\u062a\u064e\u0627\u0628\u0650\u0639\u064e\u064a\u0652\u0646\u0650 \u062a\u064e\u0648\u0652\u0628\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",93,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u0645\u064f\u062a\u064e\u0639\u064e\u0645\u0651\u0650\u062f\u064b\u0627 \u0641\u064e\u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u064b\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",94,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064e \u0644\u064e\u0633\u0652\u062a\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0641\u064e\u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064c \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",95,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0627\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u064f \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0636\u0651\u064e\u0631\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0627\u0639\u0650\u062f\u0650\u064a\u0646\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u064b \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0627\u0639\u0650\u062f\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",96,"\u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",97,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0641\u0650\u064a\u0645\u064e \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0633\u0650\u0639\u064e\u0629\u064b \u0641\u064e\u062a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06d6 \u0648\u064e\u0633\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",98,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u062d\u0650\u064a\u0644\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",99,"\u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0641\u064f\u0648\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0641\u064f\u0648\u0651\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",100,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u0650\u062f\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0631\u064e\u0627\u063a\u064e\u0645\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0633\u064e\u0639\u064e\u0629\u064b \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u062a\u0650\u0647\u0650 \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062f\u0652\u0631\u0650\u0643\u0652\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0648\u064e\u0642\u064e\u0639\u064e \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",101,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u0652\u0635\u064f\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",102,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0642\u064e\u0645\u0652\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0641\u064e\u0644\u0652\u062a\u064e\u0642\u064f\u0645\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0627 \u0623\u064e\u0633\u0652\u0644\u0650\u062d\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u062a\u064e\u0623\u0652\u062a\u0650 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0644\u064e\u0645\u0652 \u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0627 \u0641\u064e\u0644\u0652\u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0627 \u062d\u0650\u0630\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0633\u0652\u0644\u0650\u062d\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u062f\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u062a\u064e\u063a\u0652\u0641\u064f\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u0650\u062d\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u062a\u0650\u0639\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u064a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0630\u064b\u0649 \u0645\u0650\u0646\u0652 \u0645\u064e\u0637\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0636\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0633\u0652\u0644\u0650\u062d\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u062e\u064f\u0630\u064f\u0648\u0627 \u062d\u0650\u0630\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u0647\u0650\u064a\u0646\u064b\u0627",103,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u0650\u064a\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0642\u064f\u0639\u064f\u0648\u062f\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0637\u0652\u0645\u064e\u0623\u0652\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0645\u064e\u0648\u0652\u0642\u064f\u0648\u062a\u064b\u0627",104,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u06d6 \u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062a\u064e\u0623\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0623\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u062a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",105,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0644\u0650\u0644\u0652\u062e\u064e\u0627\u0626\u0650\u0646\u0650\u064a\u0646\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u064b\u0627",106,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",107,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u0652\u062a\u064e\u0627\u0646\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062e\u064e\u0648\u0651\u064e\u0627\u0646\u064b\u0627 \u0623\u064e\u062b\u0650\u064a\u0645\u064b\u0627",108,"\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u064b\u0627",109,"\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u062c\u064e\u0627\u062f\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0623\u064e\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",110,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0633\u064f\u0648\u0621\u064b\u0627 \u0623\u064e\u0648\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u0652 \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0650\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",111,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u0652 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",112,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u0652 \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0631\u0652\u0645\u0650 \u0628\u0650\u0647\u0650 \u0628\u064e\u0631\u0650\u064a\u0626\u064b\u0627 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u062d\u0652\u062a\u064e\u0645\u064e\u0644\u064e \u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",113,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0644\u064e\u0647\u064e\u0645\u0651\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",114,"\u0644\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064e \u0641\u0650\u064a \u0643\u064e\u062b\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u062c\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0645\u064e\u0631\u064e \u0628\u0650\u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u0652 \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u064d \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u0646\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",115,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u064e\u0627\u0642\u0650\u0642\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0646\u064f\u0648\u064e\u0644\u0651\u0650\u0647\u0650 \u0645\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0648\u064e\u0646\u064f\u0635\u0652\u0644\u0650\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06d6 \u0648\u064e\u0633\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",116,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0645\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",117,"\u0625\u0650\u0646\u0652 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0645\u064e\u0631\u0650\u064a\u062f\u064b\u0627",118,"\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d8 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u064e\u0641\u0652\u0631\u064f\u0648\u0636\u064b\u0627",119,"\u0648\u064e\u0644\u064e\u0623\u064f\u0636\u0650\u0644\u0651\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0623\u064f\u0645\u064e\u0646\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0622\u0645\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u062a\u0651\u0650\u0643\u064f\u0646\u0651\u064e \u0622\u0630\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0648\u064e\u0644\u064e\u0622\u0645\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0646\u0651\u064e \u062e\u064e\u0644\u0652\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0633\u0650\u0631\u064e \u062e\u064f\u0633\u0652\u0631\u064e\u0627\u0646\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",120,"\u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0645\u064e\u0646\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",121,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u062d\u0650\u064a\u0635\u064b\u0627",122,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06d6 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0635\u0652\u062f\u064e\u0642\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u0650\u064a\u0644\u064b\u0627",123,"\u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u0650 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u06d7 \u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0633\u064f\u0648\u0621\u064b\u0627 \u064a\u064f\u062c\u0652\u0632\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",124,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0642\u0650\u064a\u0631\u064b\u0627",125,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u062f\u0650\u064a\u0646\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064c \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062e\u064e\u0644\u0650\u064a\u0644\u064b\u0627",126,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064f\u062d\u0650\u064a\u0637\u064b\u0627",127,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0641\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0641\u0650\u064a \u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0644\u064e\u0627 \u062a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u062a\u064e\u0631\u0652\u063a\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",128,"\u0648\u064e\u0625\u0650\u0646\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u0629\u064c \u062e\u064e\u0627\u0641\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u0644\u0650\u0647\u064e\u0627 \u0646\u064f\u0634\u064f\u0648\u0632\u064b\u0627 \u0623\u064e\u0648\u0652 \u0625\u0650\u0639\u0652\u0631\u064e\u0627\u0636\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0635\u064f\u0644\u0652\u062d\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0635\u0651\u064f\u0644\u0652\u062d\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u06d7 \u0648\u064e\u0623\u064f\u062d\u0652\u0636\u0650\u0631\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f \u0627\u0644\u0634\u0651\u064f\u062d\u0651\u064e \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",129,"\u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u062d\u064e\u0631\u064e\u0635\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0627 \u0643\u064f\u0644\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0643\u064e\u0627\u0644\u0652\u0645\u064f\u0639\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",130,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064f\u0644\u0651\u064b\u0627 \u0645\u0650\u0646\u0652 \u0633\u064e\u0639\u064e\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",131,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0648\u064e\u0635\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064b\u0627 \u062d\u064e\u0645\u0650\u064a\u062f\u064b\u0627",132,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",133,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",134,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0641\u064e\u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0648\u064e\u0627\u0628\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",135,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0651\u064e\u0627\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u0650\u064a\u0646\u064e \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u063a\u064e\u0646\u0650\u064a\u0651\u064b\u0627 \u0623\u064e\u0648\u0652 \u0641\u064e\u0642\u0650\u064a\u0631\u064b\u0627 \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u0645\u064e\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0652\u0647\u064e\u0648\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0644\u0652\u0648\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u062a\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",136,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",137,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0627\u0632\u0652\u062f\u064e\u0627\u062f\u064f\u0648\u0627 \u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",138,"\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",139,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06da \u0623\u064e\u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",140,"\u0648\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0652 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u062a\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0643\u0652\u0641\u064e\u0631\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u064e\u0623\u064f \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0639\u064f\u062f\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627 \u0641\u0650\u064a \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u063a\u064e\u064a\u0652\u0631\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064b\u0627 \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0627\u0645\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",141,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u0652\u062d\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064c \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u0648\u0650\u0630\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u0645\u0652\u0646\u064e\u0639\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06da \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",142,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u064a\u064f\u062e\u064e\u0627\u062f\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u0627\u062f\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0643\u064f\u0633\u064e\u0627\u0644\u064e\u0649\u0670 \u064a\u064f\u0631\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",143,"\u0645\u064f\u0630\u064e\u0628\u0652\u0630\u064e\u0628\u0650\u064a\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",144,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06da \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",145,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064e\u0631\u0652\u0643\u0650 \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0641\u064e\u0644\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",146,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064f\u0648\u0627 \u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062e\u0652\u0644\u064e\u0635\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d6 \u0648\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0624\u0652\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",147,"\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0634\u064e\u0643\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0627\u0643\u0650\u0631\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",148,"\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062c\u064e\u0647\u0652\u0631\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064f\u0648\u0621\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0638\u064f\u0644\u0650\u0645\u064e \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",149,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0623\u064e\u0648\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u0652 \u062a\u064e\u0639\u0652\u0641\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064f\u0648\u0621\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0641\u064f\u0648\u0651\u064b\u0627 \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",150,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u0646\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",151,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u0647\u0650\u064a\u0646\u064b\u0627",152,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",153,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0652 \u062a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06da \u0641\u064e\u0642\u064e\u062f\u0652 \u0633\u064e\u0623\u064e\u0644\u064f\u0648\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0647\u0652\u0631\u064e\u0629\u064b \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064f \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u06da \u062b\u064f\u0645\u0651\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u0641\u064e\u0639\u064e\u0641\u064e\u0648\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",154,"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u0628\u0650\u0645\u0650\u064a\u062b\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u062a\u0650 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064b\u0627",155,"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u0652\u0636\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062a\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0648\u064e\u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u063a\u064f\u0644\u0652\u0641\u064c \u06da \u0628\u064e\u0644\u0652 \u0637\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",156,"\u0648\u064e\u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",157,"\u0648\u064e\u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0644\u064e\u0628\u064f\u0648\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0634\u064f\u0628\u0651\u0650\u0647\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u062a\u0651\u0650\u0628\u064e\u0627\u0639\u064e \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0647\u064f \u064a\u064e\u0642\u0650\u064a\u0646\u064b\u0627",158,"\u0628\u064e\u0644\u0652 \u0631\u064e\u0641\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",159,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0646\u0651\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u0650 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",160,"\u0641\u064e\u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u064d \u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0628\u0650\u0635\u064e\u062f\u0651\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",161,"\u0648\u064e\u0623\u064e\u062e\u0652\u0630\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0631\u0651\u0650\u0628\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u0652 \u0646\u064f\u0647\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0623\u064e\u0643\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u06da \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",162,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u0627\u0633\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0642\u0650\u064a\u0645\u0650\u064a\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u06da \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0633\u064e\u0646\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",163,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0648\u064e\u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u06da \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0632\u064e\u0628\u064f\u0648\u0631\u064b\u0627",164,"\u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0642\u064e\u062f\u0652 \u0642\u064e\u0635\u064e\u0635\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0644\u064e\u0645\u0652 \u0646\u064e\u0642\u0652\u0635\u064f\u0635\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062a\u064e\u0643\u0652\u0644\u0650\u064a\u0645\u064b\u0627",165,"\u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064f\u062c\u0651\u064e\u0629\u064c \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",166,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e\u0647\u064f \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",167,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",168,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627",169,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0637\u064e\u0631\u0650\u064a\u0642\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",170,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",171,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0627 \u062a\u064e\u063a\u0652\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f\u0647\u064f \u0623\u064e\u0644\u0652\u0642\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0631\u064f\u0648\u062d\u064c \u0645\u0650\u0646\u0652\u0647\u064f \u06d6 \u0641\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064c \u06da \u0627\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06d6 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064c \u06d8 \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",172,"\u0644\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0643\u0650\u0641\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0628\u0652\u062f\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0643\u0650\u0641\u0652 \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u0652 \u0641\u064e\u0633\u064e\u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",173,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0646\u0652\u0643\u064e\u0641\u064f\u0648\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",174,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0646\u064f\u0648\u0631\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",175,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u0633\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0641\u064e\u0636\u0652\u0644\u064d \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0635\u0650\u0631\u064e\u0627\u0637\u064b\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627",176,"\u064a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0641\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0650 \u0627\u0645\u0652\u0631\u064f\u0624\u064c \u0647\u064e\u0644\u064e\u0643\u064e \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064c \u0648\u064e\u0644\u064e\u0647\u064f \u0623\u064f\u062e\u0652\u062a\u064c \u0641\u064e\u0644\u064e\u0647\u064e\u0627 \u0646\u0650\u0635\u0652\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064c \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u064e\u0627\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u062e\u0652\u0648\u064e\u0629\u064b \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064b \u0641\u064e\u0644\u0650\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u0650 \u0645\u0650\u062b\u0652\u0644\u064f \u062d\u064e\u0638\u0651\u0650 \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u06d7 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c"],t.v)
B.asH=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0642\u064f\u0648\u062f\u0650 \u06da \u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u062d\u0650\u0644\u0651\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062f\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062d\u064f\u0631\u064f\u0645\u064c \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",2,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0627 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u064e \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0644\u064e\u0627\u0626\u0650\u062f\u064e \u0648\u064e\u0644\u064e\u0627 \u0622\u0645\u0651\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0635\u0652\u0637\u064e\u0627\u062f\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0652\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0646\u064e\u0622\u0646\u064f \u0642\u064e\u0648\u0652\u0645\u064d \u0623\u064e\u0646\u0652 \u0635\u064e\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06d8 \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0648\u064e\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u064e\u0627\u0648\u064e\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u0650 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",3,"\u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0645\u064f \u0648\u064e\u0644\u064e\u062d\u0652\u0645\u064f \u0627\u0644\u0652\u062e\u0650\u0646\u0652\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062e\u064e\u0646\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0642\u064f\u0648\u0630\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0631\u064e\u062f\u0651\u0650\u064a\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0637\u0650\u064a\u062d\u064e\u0629\u064f \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0643\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u064f\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0630\u064e\u0643\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0630\u064f\u0628\u0650\u062d\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0635\u064f\u0628\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u0633\u0650\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0632\u0652\u0644\u064e\u0627\u0645\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0641\u0650\u0633\u0652\u0642\u064c \u06d7 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0626\u0650\u0633\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u0650 \u06da \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064e\u0643\u0652\u0645\u064e\u0644\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062a\u0652\u0645\u064e\u0645\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0631\u064e\u0636\u0650\u064a\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064e \u062f\u0650\u064a\u0646\u064b\u0627 \u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0636\u0652\u0637\u064f\u0631\u0651\u064e \u0641\u0650\u064a \u0645\u064e\u062e\u0652\u0645\u064e\u0635\u064e\u0629\u064d \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u062a\u064e\u062c\u064e\u0627\u0646\u0650\u0641\u064d \u0644\u0650\u0625\u0650\u062b\u0652\u0645\u064d \u06d9 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",4,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0642\u064f\u0644\u0652 \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u064f \u06d9 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0648\u064e\u0627\u0631\u0650\u062d\u0650 \u0645\u064f\u0643\u064e\u0644\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0645\u0652\u0633\u064e\u0643\u0652\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",5,"\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u064f \u06d6 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u062d\u0650\u0644\u0651\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f\u0643\u064f\u0645\u0652 \u062d\u0650\u0644\u0651\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u062d\u0652\u0635\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0633\u064e\u0627\u0641\u0650\u062d\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u0650\u064a \u0623\u064e\u062e\u0652\u062f\u064e\u0627\u0646\u064d \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u062d\u064e\u0628\u0650\u0637\u064e \u0639\u064e\u0645\u064e\u0644\u064f\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",6,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0645\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0641\u064e\u0627\u063a\u0652\u0633\u0650\u0644\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0631\u064e\u0627\u0641\u0650\u0642\u0650 \u0648\u064e\u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0639\u0652\u0628\u064e\u064a\u0652\u0646\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062c\u064f\u0646\u064f\u0628\u064b\u0627 \u0641\u064e\u0627\u0637\u0651\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0626\u0650\u0637\u0650 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627\u0645\u064e\u0633\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627 \u0635\u064e\u0639\u0650\u064a\u062f\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0641\u064e\u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062d\u064e\u0631\u064e\u062c\u064d \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0644\u0650\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0627\u062b\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",8,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0651\u064e\u0627\u0645\u0650\u064a\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0652\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0646\u064e\u0622\u0646\u064f \u0642\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u06da \u0627\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u06d9 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",10,u.aX,11,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u0647\u064e\u0645\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u064c \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u062b\u0652\u0646\u064e\u064a\u0652 \u0639\u064e\u0634\u064e\u0631\u064e \u0646\u064e\u0642\u0650\u064a\u0628\u064b\u0627 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0642\u064e\u0645\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u064a \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0631\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u0652\u0631\u064e\u0636\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0644\u064e\u0623\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",13,"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u0652\u0636\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0646\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u064b \u06d6 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0644\u0650\u0645\u064e \u0639\u064e\u0646\u0652 \u0645\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650 \u06d9 \u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0627 \u062d\u064e\u0638\u0651\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u064e\u0627\u0644\u064f \u062a\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0627\u0626\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0635\u0652\u0641\u064e\u062d\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0646\u064e\u0633\u064f\u0648\u0627 \u062d\u064e\u0638\u0651\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u0636\u064e\u0627\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0648\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",15,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0646\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0641\u064f\u0648 \u0639\u064e\u0646\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u064d \u06da \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064f\u0648\u0631\u064c \u0648\u064e\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",16,"\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064e\u0647\u064f \u0633\u064f\u0628\u064f\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u0650 \u0648\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",17,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06da \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",18,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062d\u0650\u0628\u0651\u064e\u0627\u0624\u064f\u0647\u064f \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0644\u0650\u0645\u064e \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u06da \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",19,"\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0646\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0641\u064e\u062a\u0652\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0634\u0650\u064a\u0631\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064d \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0634\u0650\u064a\u0631\u064c \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064c \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",20,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0621\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u0644\u064f\u0648\u0643\u064b\u0627 \u0648\u064e\u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u062a\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",21,"\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u062a\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627 \u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",22,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u0652 \u0646\u064e\u062f\u0652\u062e\u064f\u0644\u064e\u0647\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u062f\u064e\u0627\u062e\u0650\u0644\u064f\u0648\u0646\u064e",23,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u062c\u064f\u0644\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",24,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u0652 \u0646\u064e\u062f\u0652\u062e\u064f\u0644\u064e\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0639\u0650\u062f\u064f\u0648\u0646\u064e",25,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627 \u0623\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0648\u064e\u0623\u064e\u062e\u0650\u064a \u06d6 \u0641\u064e\u0627\u0641\u0652\u0631\u064f\u0642\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",26,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06db \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0633\u064e\u0646\u064e\u0629\u064b \u06db \u064a\u064e\u062a\u0650\u064a\u0647\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",27,"\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064e \u0627\u0628\u0652\u0646\u064e\u064a\u0652 \u0622\u062f\u064e\u0645\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0631\u0651\u064e\u0628\u064e\u0627 \u0642\u064f\u0631\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u062a\u064f\u0642\u064f\u0628\u0651\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064e\u0642\u0652\u062a\u064f\u0644\u064e\u0646\u0651\u064e\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",28,"\u0644\u064e\u0626\u0650\u0646\u0652 \u0628\u064e\u0633\u064e\u0637\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u064a\u064e\u062f\u064e\u0643\u064e \u0644\u0650\u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064e\u0646\u0650\u064a \u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0627\u0633\u0650\u0637\u064d \u064a\u064e\u062f\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0644\u0650\u0623\u064e\u0642\u0652\u062a\u064f\u0644\u064e\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",29,"\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u064f\u0648\u0621\u064e \u0628\u0650\u0625\u0650\u062b\u0652\u0645\u0650\u064a \u0648\u064e\u0625\u0650\u062b\u0652\u0645\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",30,"\u0641\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e\u062a\u0652 \u0644\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064f\u0647\u064f \u0642\u064e\u062a\u0652\u0644\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0641\u064e\u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",31,"\u0641\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u064a\u064e\u0628\u0652\u062d\u064e\u062b\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0647\u064f \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064f\u0648\u064e\u0627\u0631\u0650\u064a \u0633\u064e\u0648\u0652\u0621\u064e\u0629\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u062a\u064e\u0649\u0670 \u0623\u064e\u0639\u064e\u062c\u064e\u0632\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u0652\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u063a\u064f\u0631\u064e\u0627\u0628\u0650 \u0641\u064e\u0623\u064f\u0648\u064e\u0627\u0631\u0650\u064a\u064e \u0633\u064e\u0648\u0652\u0621\u064e\u0629\u064e \u0623\u064e\u062e\u0650\u064a \u06d6 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",32,"\u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0644\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0642\u064e\u062a\u064e\u0644\u064e \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0646\u064e\u0641\u0652\u0633\u064d \u0623\u064e\u0648\u0652 \u0641\u064e\u0633\u064e\u0627\u062f\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u062d\u0652\u064a\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e",33,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0633\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0633\u064e\u0627\u062f\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0642\u064e\u062a\u0651\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u064a\u064f\u0635\u064e\u0644\u0651\u064e\u0628\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u062a\u064f\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064d \u0623\u064e\u0648\u0652 \u064a\u064f\u0646\u0652\u0641\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u0650\u0632\u0652\u064a\u064c \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",34,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",35,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",36,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0641\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0627 \u062a\u064f\u0642\u064f\u0628\u0651\u0650\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",37,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0627\u0631\u0650\u062c\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0642\u0650\u064a\u0645\u064c",38,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0631\u0650\u0642\u064f \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0631\u0650\u0642\u064e\u0629\u064f \u0641\u064e\u0627\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u0627 \u0646\u064e\u0643\u064e\u0627\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",39,"\u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0638\u064f\u0644\u0652\u0645\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",40,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",41,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0652\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06db \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u06db \u0633\u064e\u0645\u0651\u064e\u0627\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u0650 \u0633\u064e\u0645\u0651\u064e\u0627\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u06d6 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0644\u0650\u0645\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650 \u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0624\u0652\u062a\u064e\u0648\u0652\u0647\u064f \u0641\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u062a\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0645\u0652\u0644\u0650\u0643\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064f\u0631\u0650\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u0652 \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062e\u0650\u0632\u0652\u064a\u064c \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",42,"\u0633\u064e\u0645\u0651\u064e\u0627\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u0650 \u0623\u064e\u0643\u0651\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0633\u0651\u064f\u062d\u0652\u062a\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064e \u0641\u064e\u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0643\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062d\u064e\u0643\u064e\u0645\u0652\u062a\u064e \u0641\u064e\u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0642\u0652\u0633\u0650\u0637\u0650\u064a\u0646\u064e",43,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064f\u062d\u064e\u0643\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064f\u0643\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",44,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0646\u064f\u0648\u0631\u064c \u06da \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0628\u0651\u064e\u0627\u0646\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0628\u064e\u0627\u0631\u064f \u0628\u0650\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064f\u062d\u0652\u0641\u0650\u0638\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0634\u064e\u0648\u064f\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0627\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u064a\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064e \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0630\u064f\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u0630\u064f\u0646\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u0650\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0631\u064f\u0648\u062d\u064e \u0642\u0650\u0635\u064e\u0627\u0635\u064c \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064e\u0629\u064c \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u0650 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e \u0641\u0650\u064a\u0647\u0650 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0646\u064f\u0648\u0631\u064c \u0648\u064e\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",47,"\u0648\u064e\u0644\u0652\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0645\u064f\u0647\u064e\u064a\u0652\u0645\u0650\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0641\u064e\u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0644\u0650\u0643\u064f\u0644\u0651\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0634\u0650\u0631\u0652\u0639\u064e\u0629\u064b \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627\u062c\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0628\u0650\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u06da \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0623\u064e\u0646\u0650 \u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u062a\u0650\u0646\u064f\u0648\u0643\u064e \u0639\u064e\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u0650 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u0650 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",50,"\u0623\u064e\u0641\u064e\u062d\u064f\u0643\u0652\u0645\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",51,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06d8 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",52,"\u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064e\u062e\u0652\u0634\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0626\u0650\u0631\u064e\u0629\u064c \u06da \u0641\u064e\u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0628\u0650\u0627\u0644\u0652\u0641\u064e\u062a\u0652\u062d\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0645\u0652\u0631\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0647\u0650 \u0641\u064e\u064a\u064f\u0635\u0652\u0628\u0650\u062d\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0646\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",53,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06da \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",54,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0647\u0650 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u0650\u0632\u0651\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u0652\u0645\u064e\u0629\u064e \u0644\u064e\u0627\u0626\u0650\u0645\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",55,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0627\u0643\u0650\u0639\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u0652\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",57,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",58,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0627\u062f\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",59,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0647\u064e\u0644\u0652 \u062a\u064e\u0646\u0652\u0642\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",60,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0634\u064e\u0631\u0651\u064d \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064f\u0648\u0628\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0645\u064e\u0646\u0652 \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0646\u064e\u0627\u0632\u0650\u064a\u0631\u064e \u0648\u064e\u0639\u064e\u0628\u064e\u062f\u064e \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u064e \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0634\u064e\u0631\u0651\u064c \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0639\u064e\u0646\u0652 \u0633\u064e\u0648\u064e\u0627\u0621\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",61,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u0652 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",62,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u0650 \u0648\u064e\u0623\u064e\u0643\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064f\u062d\u0652\u062a\u064e \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",63,"\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0647\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0628\u0651\u064e\u0627\u0646\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0628\u064e\u0627\u0631\u064f \u0639\u064e\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u064e \u0648\u064e\u0623\u064e\u0643\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064f\u062d\u0652\u062a\u064e \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",64,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u064a\u064e\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u063a\u0652\u0644\u064f\u0648\u0644\u064e\u0629\u064c \u06da \u063a\u064f\u0644\u0651\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064f\u0639\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u06d8 \u0628\u064e\u0644\u0652 \u064a\u064e\u062f\u064e\u0627\u0647\u064f \u0645\u064e\u0628\u0652\u0633\u064f\u0648\u0637\u064e\u062a\u064e\u0627\u0646\u0650 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0644\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u0636\u064e\u0627\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0648\u0652\u0642\u064e\u062f\u064f\u0648\u0627 \u0646\u064e\u0627\u0631\u064b\u0627 \u0644\u0650\u0644\u0652\u062d\u064e\u0631\u0652\u0628\u0650 \u0623\u064e\u0637\u0652\u0641\u064e\u0623\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u064a\u064e\u0633\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0633\u064e\u0627\u062f\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",65,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0644\u064e\u0643\u064e\u0641\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0623\u064e\u062f\u0652\u062e\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",66,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0623\u064e\u0643\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650 \u0623\u064e\u0631\u0652\u062c\u064f\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0645\u064f\u0642\u0652\u062a\u064e\u0635\u0650\u062f\u064e\u0629\u064c \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",67,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u064e\u0644\u0651\u0650\u063a\u0652 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u0651\u064e\u063a\u0652\u062a\u064e \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u062a\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0635\u0650\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",68,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0633\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0644\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",69,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0626\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",70,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0647\u0652\u0648\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u062d\u064e\u0633\u0650\u0628\u064f\u0648\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0641\u064e\u0639\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u0645\u0651\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u0645\u0651\u064f\u0648\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",72,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064d",73,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062b\u064e\u0627\u0644\u0650\u062b\u064f \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064d \u06d8 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",74,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",75,"\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0648\u064e\u0623\u064f\u0645\u0651\u064f\u0647\u064f \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u064e\u0629\u064c \u06d6 \u0643\u064e\u0627\u0646\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064e\u0627\u0646\u0650 \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u06d7 \u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",76,"\u0642\u064f\u0644\u0652 \u0623\u064e\u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",77,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0627 \u062a\u064e\u063a\u0652\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e \u0642\u064e\u0648\u0652\u0645\u064d \u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0648\u064e\u0627\u0621\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",78,"\u0644\u064f\u0639\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0644\u0650\u0633\u064e\u0627\u0646\u0650 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u0650 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0652\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",79,"\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0652 \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064d \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",80,"\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0633\u064e\u062e\u0650\u0637\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0647\u064f\u0645\u0652 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",81,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",82,"\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u0650\u0633\u0651\u0650\u064a\u0633\u0650\u064a\u0646\u064e \u0648\u064e\u0631\u064f\u0647\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",83,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u062a\u064e\u0631\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0641\u0650\u064a\u0636\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064e\u0645\u0652\u0639\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0631\u064e\u0641\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u0643\u0652\u062a\u064f\u0628\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",84,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0646\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",85,"\u0641\u064e\u0623\u064e\u062b\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",86,u.aX,87,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",88,"\u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",89,"\u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u0650 \u0641\u0650\u064a \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0642\u0651\u064e\u062f\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u06d6 \u0641\u064e\u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064e\u062a\u064f\u0647\u064f \u0625\u0650\u0637\u0652\u0639\u064e\u0627\u0645\u064f \u0639\u064e\u0634\u064e\u0631\u064e\u0629\u0650 \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0633\u064e\u0637\u0650 \u0645\u064e\u0627 \u062a\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0643\u0650\u0633\u0652\u0648\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u062a\u064e\u062d\u0652\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064e\u0629\u064f \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u062d\u0652\u0641\u064e\u0638\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",90,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062e\u064e\u0645\u0652\u0631\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0633\u0650\u0631\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0628\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0632\u0652\u0644\u064e\u0627\u0645\u064f \u0631\u0650\u062c\u0652\u0633\u064c \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0641\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0647\u064f \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",91,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0648\u0642\u0650\u0639\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u0636\u064e\u0627\u0621\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0633\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u06d6 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",92,"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0627 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",93,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0641\u0650\u064a\u0645\u064e\u0627 \u0637\u064e\u0639\u0650\u0645\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",94,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062f\u0650 \u062a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u0650\u0645\u064e\u0627\u062d\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",95,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062f\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062d\u064f\u0631\u064f\u0645\u064c \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u062a\u064e\u0639\u064e\u0645\u0651\u0650\u062f\u064b\u0627 \u0641\u064e\u062c\u064e\u0632\u064e\u0627\u0621\u064c \u0645\u0650\u062b\u0652\u0644\u064f \u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0639\u064e\u0645\u0650 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u0650\u0647\u0650 \u0630\u064e\u0648\u064e\u0627 \u0639\u064e\u062f\u0652\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0647\u064e\u062f\u0652\u064a\u064b\u0627 \u0628\u064e\u0627\u0644\u0650\u063a\u064e \u0627\u0644\u0652\u0643\u064e\u0639\u0652\u0628\u064e\u0629\u0650 \u0623\u064e\u0648\u0652 \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064e\u0629\u064c \u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652 \u0639\u064e\u062f\u0652\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0635\u0650\u064a\u064e\u0627\u0645\u064b\u0627 \u0644\u0650\u064a\u064e\u0630\u064f\u0648\u0642\u064e \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0639\u064e\u0641\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0644\u064e\u0641\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u062f\u064e \u0641\u064e\u064a\u064e\u0646\u0652\u062a\u064e\u0642\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u0630\u064f\u0648 \u0627\u0646\u0652\u062a\u0650\u0642\u064e\u0627\u0645\u064d",96,"\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0635\u064e\u064a\u0652\u062f\u064f \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f\u0647\u064f \u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u0644\u0633\u0651\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0635\u064e\u064a\u0652\u062f\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062f\u064f\u0645\u0652\u062a\u064f\u0645\u0652 \u062d\u064f\u0631\u064f\u0645\u064b\u0627 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",97,"\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0643\u064e\u0639\u0652\u0628\u064e\u0629\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0642\u0650\u064a\u064e\u0627\u0645\u064b\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0648\u064e\u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0644\u064e\u0627\u0626\u0650\u062f\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",98,"\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",99,"\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",100,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064f \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e\u0643\u064e \u0643\u064e\u062b\u0652\u0631\u064e\u0629\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u0650 \u06da \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",101,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e \u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062f\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0633\u064f\u0624\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u062d\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u062a\u064f\u0628\u0652\u062f\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0641\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",102,"\u0642\u064e\u062f\u0652 \u0633\u064e\u0623\u064e\u0644\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",103,"\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u062d\u0650\u064a\u0631\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0626\u0650\u0628\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0635\u0650\u064a\u0644\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0627\u0645\u064d \u06d9 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u06d6 \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",104,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062d\u064e\u0633\u0652\u0628\u064f\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",105,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u06da \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",106,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064f \u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u062d\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0650 \u0627\u062b\u0652\u0646\u064e\u0627\u0646\u0650 \u0630\u064e\u0648\u064e\u0627 \u0639\u064e\u062f\u0652\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0622\u062e\u064e\u0631\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0636\u064e\u0631\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06da \u062a\u064e\u062d\u0652\u0628\u0650\u0633\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0641\u064e\u064a\u064f\u0642\u0652\u0633\u0650\u0645\u064e\u0627\u0646\u0650 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0650 \u0627\u0631\u0652\u062a\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u0646\u064e\u0634\u0652\u062a\u064e\u0631\u0650\u064a \u0628\u0650\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u06d9 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0643\u0652\u062a\u064f\u0645\u064f \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062b\u0650\u0645\u0650\u064a\u0646\u064e",107,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064f\u062b\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u062d\u064e\u0642\u0651\u064e\u0627 \u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0641\u064e\u0622\u062e\u064e\u0631\u064e\u0627\u0646\u0650 \u064a\u064e\u0642\u064f\u0648\u0645\u064e\u0627\u0646\u0650 \u0645\u064e\u0642\u064e\u0627\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u0644\u064e\u064a\u064e\u0627\u0646\u0650 \u0641\u064e\u064a\u064f\u0642\u0652\u0633\u0650\u0645\u064e\u0627\u0646\u0650 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0634\u064e\u0647\u064e\u0627\u062f\u064e\u062a\u064f\u0646\u064e\u0627 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0627\u0639\u0652\u062a\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",108,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0631\u064e\u062f\u0651\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064c \u0628\u064e\u0639\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",109,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064f\u062c\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064e \u0644\u064e\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u0651\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u063a\u064f\u064a\u064f\u0648\u0628\u0650",110,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0650\u062f\u064e\u062a\u0650\u0643\u064e \u0625\u0650\u0630\u0652 \u0623\u064e\u064a\u0651\u064e\u062f\u0652\u062a\u064f\u0643\u064e \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0633\u0650 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0647\u0652\u062f\u0650 \u0648\u064e\u0643\u064e\u0647\u0652\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0630\u0652 \u0639\u064e\u0644\u0651\u064e\u0645\u0652\u062a\u064f\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e \u06d6 \u0648\u064e\u0625\u0650\u0630\u0652 \u062a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0643\u064e\u0647\u064e\u064a\u0652\u0626\u064e\u0629\u0650 \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u064a \u0641\u064e\u062a\u064e\u0646\u0652\u0641\u064f\u062e\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0637\u064e\u064a\u0652\u0631\u064b\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u064a \u06d6 \u0648\u064e\u062a\u064f\u0628\u0652\u0631\u0650\u0626\u064f \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0645\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0635\u064e \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u064a \u06d6 \u0648\u064e\u0625\u0650\u0630\u0652 \u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u064a \u06d6 \u0648\u064e\u0625\u0650\u0630\u0652 \u0643\u064e\u0641\u064e\u0641\u0652\u062a\u064f \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0639\u064e\u0646\u0652\u0643\u064e \u0625\u0650\u0630\u0652 \u062c\u0650\u0626\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",111,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u064a \u0648\u064e\u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u064a \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0627\u0634\u0652\u0647\u064e\u062f\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0646\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",112,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u064a\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0627\u0626\u0650\u062f\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",113,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0646\u064e\u0623\u0652\u0643\u064f\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0652 \u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u064e\u0642\u0652\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",114,"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0627\u0626\u0650\u062f\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627 \u0639\u0650\u064a\u062f\u064b\u0627 \u0644\u0650\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0622\u062e\u0650\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0622\u064a\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0643\u064e \u06d6 \u0648\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",115,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0644\u064e\u0627 \u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",116,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0642\u064f\u0644\u0652\u062a\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0627\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0623\u064f\u0645\u0651\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u064f\u0648\u0644\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u062d\u064e\u0642\u0651\u064d \u06da \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0642\u064f\u0644\u0652\u062a\u064f\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e\u0647\u064f \u06da \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u0651\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u063a\u064f\u064a\u064f\u0648\u0628\u0650",117,"\u0645\u064e\u0627 \u0642\u064f\u0644\u0652\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u0652\u062a\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0645\u064e\u0627 \u062f\u064f\u0645\u0652\u062a\u064f \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0631\u0651\u064e\u0642\u0650\u064a\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",118,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064f\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",119,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0635\u0650\u062f\u0652\u0642\u064f\u0647\u064f\u0645\u0652 \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",120,"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c"],t.v)
B.ap4=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0648\u0631\u064e \u06d6 \u062b\u064f\u0645\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e",2,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d \u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0636\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u064c \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u06d6 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0645\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",3,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0633\u0650\u0631\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0647\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",4,u.d1,5,"\u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",6,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u0646\u064d \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u062f\u0652\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0631\u0652\u0646\u064b\u0627 \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0641\u0650\u064a \u0642\u0650\u0631\u0652\u0637\u064e\u0627\u0633\u064d \u0641\u064e\u0644\u064e\u0645\u064e\u0633\u064f\u0648\u0647\u064f \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0644\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",8,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u064c \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064b\u0627 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u0644\u064e\u0643\u064b\u0627 \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0648\u064e\u0644\u064e\u0644\u064e\u0628\u064e\u0633\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0646\u064e",10,u.ai,11,"\u0642\u064f\u0644\u0652 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",12,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0645\u064e\u0646\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0643\u064e\u062a\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u064e \u06da \u0644\u064e\u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0633\u064e\u0643\u064e\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",14,"\u0642\u064f\u0644\u0652 \u0623\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u0637\u0652\u0639\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0637\u0652\u0639\u064e\u0645\u064f \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",15,u.aG,16,"\u0645\u064e\u0646\u0652 \u064a\u064f\u0635\u0652\u0631\u064e\u0641\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0641\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u062d\u0650\u0645\u064e\u0647\u064f \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",17,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u064d \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064e \u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0643\u064e \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",18,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0647\u0650\u0631\u064f \u0641\u064e\u0648\u0652\u0642\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",19,"\u0642\u064f\u0644\u0652 \u0623\u064e\u064a\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064b \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0644\u0650\u0623\u064f\u0646\u0652\u0630\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0628\u064e\u0644\u064e\u063a\u064e \u06da \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06da \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u06da \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",20,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u06d8 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0632\u0652\u0639\u064f\u0645\u064f\u0648\u0646\u064e",23,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",24,"\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064f\u0644\u0651\u064e \u0622\u064a\u064e\u0629\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",26,"\u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u064a\u064e\u0646\u0652\u0623\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u0648\u064f\u0642\u0650\u0641\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",28,"\u0628\u064e\u0644\u0652 \u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0631\u064f\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u0627\u062f\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",29,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u0650\u064a\u0646\u064e",30,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u0648\u064f\u0642\u0650\u0641\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",31,"\u0642\u064e\u062f\u0652 \u062e\u064e\u0633\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u062d\u064e\u0633\u0652\u0631\u064e\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0652\u0632\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u06da \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u0631\u064f\u0648\u0646\u064e",32,"\u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u064c \u0648\u064e\u0644\u064e\u0647\u0652\u0648\u064c \u06d6 \u0648\u064e\u0644\u064e\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",33,"\u0642\u064e\u062f\u0652 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u064a\u064e\u062d\u0652\u0632\u064f\u0646\u064f\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0630\u0651\u0650\u0628\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u064e\u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0643\u064f\u0630\u0651\u0650\u0628\u064f\u0648\u0627 \u0648\u064e\u0623\u064f\u0648\u0630\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0652\u0631\u064f\u0646\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u064e\u0625\u0650 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",35,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0639\u0652\u0631\u064e\u0627\u0636\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u062a\u064e\u063a\u0650\u064a\u064e \u0646\u064e\u0641\u064e\u0642\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0648\u0652 \u0633\u064f\u0644\u0651\u064e\u0645\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",36,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u06d8 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0627\u062f\u0650\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0622\u064a\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0637\u064e\u0627\u0626\u0650\u0631\u064d \u064a\u064e\u0637\u0650\u064a\u0631\u064f \u0628\u0650\u062c\u064e\u0646\u064e\u0627\u062d\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064f\u0645\u064e\u0645\u064c \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u06da \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0635\u064f\u0645\u0651\u064c \u0648\u064e\u0628\u064f\u0643\u0652\u0645\u064c \u0641\u0650\u064a \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u06d7 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0625\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0652\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",40,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u062a\u064e\u062a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",41,"\u0628\u064e\u0644\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0641\u064e\u064a\u064e\u0643\u0652\u0634\u0650\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0648\u064e\u062a\u064e\u0646\u0652\u0633\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",42,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u064e\u0645\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",43,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0642\u064e\u0633\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",44,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627 \u0645\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u064f\u0628\u0652\u0644\u0650\u0633\u064f\u0648\u0646\u064e",45,"\u0641\u064e\u0642\u064f\u0637\u0650\u0639\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",46,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0652\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062e\u064e\u062a\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d7 \u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0647\u064f\u0645\u0652 \u064a\u064e\u0635\u0652\u062f\u0650\u0641\u064f\u0648\u0646\u064e",47,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u062c\u064e\u0647\u0652\u0631\u064e\u0629\u064b \u0647\u064e\u0644\u0652 \u064a\u064f\u0647\u0652\u0644\u064e\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",50,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u064c \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u06da \u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",51,"\u0648\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d9 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064c \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u064c \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",52,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u0652\u0631\u064f\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u062f\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u06d6 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u062a\u064e\u0637\u0652\u0631\u064f\u062f\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",53,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0623\u064e\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0646\u064e\u0627 \u06d7 \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",54,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0642\u064f\u0644\u0652 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0643\u064e\u062a\u064e\u0628\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u064e \u06d6 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064b\u0627 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0644\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",55,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0633\u0652\u062a\u064e\u0628\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",56,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064f\u0647\u0650\u064a\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06d9 \u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u064e\u0644\u0652\u062a\u064f \u0625\u0650\u0630\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",57,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06da \u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0650 \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06d6 \u064a\u064e\u0642\u064f\u0635\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0635\u0650\u0644\u0650\u064a\u0646\u064e",58,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",59,"\u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u0642\u064f\u0637\u064f \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0642\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0637\u0652\u0628\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0627\u0628\u0650\u0633\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",60,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062c\u064e\u0631\u064e\u062d\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0644\u0650\u064a\u064f\u0642\u0652\u0636\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064c \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",61,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0647\u0650\u0631\u064f \u0641\u064e\u0648\u0652\u0642\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0648\u064e\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062d\u064e\u0641\u064e\u0638\u064e\u0629\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u062a\u0652\u0647\u064f \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0637\u064f\u0648\u0646\u064e",62,"\u062b\u064f\u0645\u0651\u064e \u0631\u064f\u062f\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0633\u0652\u0631\u064e\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u0627\u0633\u0650\u0628\u0650\u064a\u0646\u064e",63,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0647\u064f \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u064b\u0627 \u0648\u064e\u062e\u064f\u0641\u0652\u064a\u064e\u0629\u064b \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u0627\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",64,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0643\u064e\u0631\u0652\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",65,"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650 \u0623\u064e\u0631\u0652\u062c\u064f\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0644\u0652\u0628\u0650\u0633\u064e\u0643\u064f\u0645\u0652 \u0634\u0650\u064a\u064e\u0639\u064b\u0627 \u0648\u064e\u064a\u064f\u0630\u0650\u064a\u0642\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064e \u0628\u064e\u0639\u0652\u0636\u064d \u06d7 \u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",66,"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064f\u0643\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06da \u0642\u064f\u0644\u0652 \u0644\u064e\u0633\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",67,"\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u064e\u0625\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064c \u06da \u0648\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627 \u0641\u0650\u064a \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u063a\u064e\u064a\u0652\u0631\u0650\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0646\u0652\u0633\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0639\u064f\u062f\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",69,"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",70,"\u0648\u064e\u0630\u064e\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u0650\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0647\u0652\u0648\u064b\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062a\u064f\u0628\u0652\u0633\u064e\u0644\u064e \u0646\u064e\u0641\u0652\u0633\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064c \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u064c \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u0652 \u0643\u064f\u0644\u0651\u064e \u0639\u064e\u062f\u0652\u0644\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062e\u064e\u0630\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0628\u0652\u0633\u0650\u0644\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0631\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u0650\u064a\u0645\u064d \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",71,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0646\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0633\u0652\u062a\u064e\u0647\u0652\u0648\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062d\u064e\u064a\u0652\u0631\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064c \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649 \u0627\u0626\u0652\u062a\u0650\u0646\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0647\u064f\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u0646\u064e\u0627 \u0644\u0650\u0646\u064f\u0633\u0652\u0644\u0650\u0645\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",72,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u06da \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06da \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u0652\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u06da \u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",74,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0622\u0632\u064e\u0631\u064e \u0623\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064b\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0643\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",75,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0631\u0650\u064a \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",76,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064f \u0631\u064e\u0623\u064e\u0649\u0670 \u0643\u064e\u0648\u0652\u0643\u064e\u0628\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u0623\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0622\u0641\u0650\u0644\u0650\u064a\u0646\u064e",77,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",78,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0641\u064e\u0644\u064e\u062a\u0652 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",79,"\u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u062c\u0651\u064e\u0647\u0652\u062a\u064f \u0648\u064e\u062c\u0652\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",80,"\u0648\u064e\u062d\u064e\u0627\u062c\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u0651\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d7 \u0648\u064e\u0633\u0650\u0639\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",81,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u06da \u0641\u064e\u0623\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0646\u0650 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",82,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0646\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",83,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062c\u0651\u064e\u062a\u064f\u0646\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u06da \u0646\u064e\u0631\u0652\u0641\u064e\u0639\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",84,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u06da \u0643\u064f\u0644\u0651\u064b\u0627 \u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u06da \u0648\u064e\u0646\u064f\u0648\u062d\u064b\u0627 \u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0648\u064e\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",85,"\u0648\u064e\u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0648\u064e\u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0644\u0652\u064a\u064e\u0627\u0633\u064e \u06d6 \u0643\u064f\u0644\u0651\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",86,"\u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0633\u064e\u0639\u064e \u0648\u064e\u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0627\u062c\u0652\u062a\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",88,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0644\u064e\u062d\u064e\u0628\u0650\u0637\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",89,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0647\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0648\u064e\u0643\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064e\u064a\u0652\u0633\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0628\u0650\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",90,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u0628\u0650\u0647\u064f\u062f\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0642\u0652\u062a\u064e\u062f\u0650\u0647\u0652 \u06d7 \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",91,"\u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u0652\u0631\u0650\u0647\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0634\u064e\u0631\u064d \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06d7 \u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e\u0647\u064f \u0642\u064e\u0631\u064e\u0627\u0637\u0650\u064a\u0633\u064e \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0639\u064f\u0644\u0651\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u062b\u064f\u0645\u0651\u064e \u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062e\u064e\u0648\u0652\u0636\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0644\u0652\u0639\u064e\u0628\u064f\u0648\u0646\u064e",92,"\u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064c \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0623\u064f\u0645\u0651\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064e\u0627 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",93,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u0652 \u0642\u064e\u0627\u0644\u064e \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u062d\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064f \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u063a\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0628\u064e\u0627\u0633\u0650\u0637\u064f\u0648 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u064f \u06d6 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u062a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",94,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627 \u0641\u064f\u0631\u064e\u0627\u062f\u064e\u0649\u0670 \u0643\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u06da \u0644\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0632\u0652\u0639\u064f\u0645\u064f\u0648\u0646\u064e",95,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0627\u0644\u0650\u0642\u064f \u0627\u0644\u0652\u062d\u064e\u0628\u0651\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0648\u064e\u0649\u0670 \u06d6 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u0645\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",96,"\u0641\u064e\u0627\u0644\u0650\u0642\u064f \u0627\u0644\u0652\u0625\u0650\u0635\u0652\u0628\u064e\u0627\u062d\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0633\u064e\u0643\u064e\u0646\u064b\u0627 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u062d\u064f\u0633\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u0650",97,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064e \u0644\u0650\u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u06d7 \u0642\u064e\u062f\u0652 \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",98,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u0641\u064e\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064c \u0648\u064e\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u0652\u062f\u064e\u0639\u064c \u06d7 \u0642\u064e\u062f\u0652 \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",99,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0646\u064e\u0628\u064e\u0627\u062a\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u062e\u064e\u0636\u0650\u0631\u064b\u0627 \u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u062d\u064e\u0628\u0651\u064b\u0627 \u0645\u064f\u062a\u064e\u0631\u064e\u0627\u0643\u0650\u0628\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u0650 \u0645\u0650\u0646\u0652 \u0637\u064e\u0644\u0652\u0639\u0650\u0647\u064e\u0627 \u0642\u0650\u0646\u0652\u0648\u064e\u0627\u0646\u064c \u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064c \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0645\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0634\u0652\u062a\u064e\u0628\u0650\u0647\u064b\u0627 \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064d \u06d7 \u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062b\u0652\u0645\u064e\u0631\u064e \u0648\u064e\u064a\u064e\u0646\u0652\u0639\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",100,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u062e\u064e\u0631\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064d \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",101,"\u0628\u064e\u062f\u0650\u064a\u0639\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064c \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u0629\u064c \u06d6 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",102,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0643\u0650\u064a\u0644\u064c",103,"\u0644\u064e\u0627 \u062a\u064f\u062f\u0652\u0631\u0650\u0643\u064f\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062f\u0652\u0631\u0650\u0643\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0637\u0650\u064a\u0641\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",104,"\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0628\u0652\u0635\u064e\u0631\u064e \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u064a\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u062d\u064e\u0641\u0650\u064a\u0638\u064d",105,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u062f\u064e\u0631\u064e\u0633\u0652\u062a\u064e \u0648\u064e\u0644\u0650\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0647\u064f \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",106,"\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0645\u064e\u0627 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0648\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",107,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0641\u0650\u064a\u0638\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",108,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u064f\u0628\u0651\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0633\u064f\u0628\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u062f\u0652\u0648\u064b\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0639\u064e\u0645\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",109,"\u0648\u064e\u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0626\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064c \u0644\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u06da \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0634\u0652\u0639\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",110,"\u0648\u064e\u0646\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",111,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u062d\u064e\u0634\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064f\u0628\u064f\u0644\u064b\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062c\u0652\u0647\u064e\u0644\u064f\u0648\u0646\u064e",112,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0634\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u064a\u064f\u0648\u062d\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0632\u064f\u062e\u0652\u0631\u064f\u0641\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u06d6 \u0641\u064e\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",113,"\u0648\u064e\u0644\u0650\u062a\u064e\u0635\u0652\u063a\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u064f\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0646\u064e",114,"\u0623\u064e\u0641\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u0652\u062a\u064e\u063a\u0650\u064a \u062d\u064e\u0643\u064e\u0645\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u064f\u0641\u064e\u0635\u0651\u064e\u0644\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0645\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0645\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e",115,"\u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0635\u0650\u062f\u0652\u0642\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u0652\u0644\u064b\u0627 \u06da \u0644\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",116,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u0639\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0643\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u0635\u064f\u0648\u0646\u064e",117,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",118,"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",119,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u0635\u0651\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0627\u0636\u0652\u0637\u064f\u0631\u0650\u0631\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0644\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",120,"\u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627 \u0638\u064e\u0627\u0647\u0650\u0631\u064e \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0646\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u064e \u0633\u064e\u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0646\u064e",121,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0630\u0652\u0643\u064e\u0631\u0650 \u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u0650\u0633\u0652\u0642\u064c \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u064f\u0648\u062d\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",122,"\u0623\u064e\u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u064a\u0652\u062a\u064b\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0646\u064f\u0648\u0631\u064b\u0627 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0628\u0650\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u062e\u064e\u0627\u0631\u0650\u062c\u064d \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",123,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0643\u064e\u0627\u0628\u0650\u0631\u064e \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",124,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064c \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064f\u0624\u0652\u062a\u064e\u0649\u0670 \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0631\u064f\u0633\u064f\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d8 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u062d\u064e\u064a\u0652\u062b\u064f \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u062a\u064e\u0647\u064f \u06d7 \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0645\u064f\u0648\u0627 \u0635\u064e\u063a\u064e\u0627\u0631\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",125,"\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0647\u064f \u064a\u064e\u0634\u0652\u0631\u064e\u062d\u0652 \u0635\u064e\u062f\u0652\u0631\u064e\u0647\u064f \u0644\u0650\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0635\u064e\u062f\u0652\u0631\u064e\u0647\u064f \u0636\u064e\u064a\u0651\u0650\u0642\u064b\u0627 \u062d\u064e\u0631\u064e\u062c\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0635\u0651\u064e\u0639\u0651\u064e\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",126,"\u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627 \u06d7 \u0642\u064e\u062f\u0652 \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",127,"\u0644\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",128,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u064a\u064e\u0627 \u0645\u064e\u0639\u0652\u0634\u064e\u0631\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0642\u064e\u062f\u0650 \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u062b\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u0652\u0646\u064e\u0627 \u0623\u064e\u062c\u064e\u0644\u064e\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062c\u0651\u064e\u0644\u0652\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u0652 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",129,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0648\u064e\u0644\u0651\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",130,"\u064a\u064e\u0627 \u0645\u064e\u0639\u0652\u0634\u064e\u0631\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0642\u064f\u0635\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u0650\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0634\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",131,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",132,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u064d \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",133,"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0630\u064f\u0648 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u0650\u0641\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0642\u064e\u0648\u0652\u0645\u064d \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",134,"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0622\u062a\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e",135,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0627\u0645\u0650\u0644\u064c \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",136,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064e\u0631\u064e\u0623\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u062b\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0632\u064e\u0639\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",137,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u0650\u0643\u064e\u062b\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0642\u064e\u062a\u0652\u0644\u064e \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u0650\u0647\u0650\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064f\u0631\u0652\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u06d6 \u0641\u064e\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",138,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064c \u0648\u064e\u062d\u064e\u0631\u0652\u062b\u064c \u062d\u0650\u062c\u0652\u0631\u064c \u0644\u064e\u0627 \u064a\u064e\u0637\u0652\u0639\u064e\u0645\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0628\u0650\u0632\u064e\u0639\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064c \u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u0652 \u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0627\u0641\u0652\u062a\u0650\u0631\u064e\u0627\u0621\u064b \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0633\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u0647\u0650\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",139,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u064c \u0644\u0650\u0630\u064f\u0643\u064f\u0648\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064b \u0641\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u06da \u0633\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0635\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",140,"\u0642\u064e\u062f\u0652 \u062e\u064e\u0633\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0641\u064e\u0647\u064b\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u064f\u0648\u0627 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0641\u0652\u062a\u0650\u0631\u064e\u0627\u0621\u064b \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",141,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0634\u064e\u0627\u062a\u064d \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0634\u064e\u0627\u062a\u064d \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u0631\u0652\u0639\u064e \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064f\u0643\u064f\u0644\u064f\u0647\u064f \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0645\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064b\u0627 \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064d \u06da \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062b\u0652\u0645\u064e\u0631\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u062d\u064e\u0642\u0651\u064e\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u062d\u064e\u0635\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",142,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u062d\u064e\u0645\u064f\u0648\u0644\u064e\u0629\u064b \u0648\u064e\u0641\u064e\u0631\u0652\u0634\u064b\u0627 \u06da \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u062e\u064f\u0637\u064f\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",143,"\u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064d \u06d6 \u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0623\u0652\u0646\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0632\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0622\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e\u064a\u0652\u0646\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0623\u064e\u0645\u0650 \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0634\u0652\u062a\u064e\u0645\u064e\u0644\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u064d \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",144,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0628\u0650\u0644\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0642\u064e\u0631\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0622\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e\u064a\u0652\u0646\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0623\u064e\u0645\u0650 \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0634\u0652\u062a\u064e\u0645\u064e\u0644\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0623\u064e\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0625\u0650\u0630\u0652 \u0648\u064e\u0635\u0651\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",145,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u062c\u0650\u062f\u064f \u0641\u0650\u064a \u0645\u064e\u0627 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0639\u0650\u0645\u064d \u064a\u064e\u0637\u0652\u0639\u064e\u0645\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u062f\u064e\u0645\u064b\u0627 \u0645\u064e\u0633\u0652\u0641\u064f\u0648\u062d\u064b\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u062d\u0652\u0645\u064e \u062e\u0650\u0646\u0652\u0632\u0650\u064a\u0631\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0631\u0650\u062c\u0652\u0633\u064c \u0623\u064e\u0648\u0652 \u0641\u0650\u0633\u0652\u0642\u064b\u0627 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0636\u0652\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u0627\u063a\u064d \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",146,"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0630\u0650\u064a \u0638\u064f\u0641\u064f\u0631\u064d \u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0642\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0646\u064e\u0645\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0634\u064f\u062d\u064f\u0648\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u0652 \u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0648\u0650 \u0627\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u064a\u064e\u0627 \u0623\u064e\u0648\u0652 \u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0639\u064e\u0638\u0652\u0645\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u063a\u0652\u064a\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",147,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0630\u064f\u0648 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0648\u064e\u0627\u0633\u0650\u0639\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u0652\u0633\u064f\u0647\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",148,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0630\u064e\u0627\u0642\u064f\u0648\u0627 \u0628\u064e\u0623\u0652\u0633\u064e\u0646\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0641\u064e\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0647\u064f \u0644\u064e\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u0652\u0631\u064f\u0635\u064f\u0648\u0646\u064e",149,"\u0642\u064f\u0644\u0652 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u062d\u064f\u062c\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0644\u0650\u063a\u064e\u0629\u064f \u06d6 \u0641\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0644\u064e\u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",150,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u064f\u0645\u0651\u064e \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e",151,"\u0642\u064f\u0644\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u0623\u064e\u062a\u0652\u0644\u064f \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0645\u0652\u0644\u064e\u0627\u0642\u064d \u06d6 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0652\u0641\u064e\u0648\u064e\u0627\u062d\u0650\u0634\u064e \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0637\u064e\u0646\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0635\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",152,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0645\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u064a\u064e\u062a\u0650\u064a\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06d6 \u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0635\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",153,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u0650\u064a \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627 \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0628\u064f\u0644\u064e \u0641\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0635\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",154,"\u062b\u064f\u0645\u0651\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u062a\u064e\u0645\u064e\u0627\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0648\u064e\u062a\u064e\u0641\u0652\u0635\u0650\u064a\u0644\u064b\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",155,"\u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064c \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",156,"\u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u0652 \u062f\u0650\u0631\u064e\u0627\u0633\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",157,"\u0623\u064e\u0648\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0635\u064e\u062f\u064e\u0641\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u06d7 \u0633\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u0652\u062f\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0635\u0652\u062f\u0650\u0641\u064f\u0648\u0646\u064e",158,"\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0628\u064e\u0639\u0652\u0636\u064f \u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d7 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u064f \u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f\u0647\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0622\u0645\u064e\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0623\u064e\u0648\u0652 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0641\u0650\u064a \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u06d7 \u0642\u064f\u0644\u0650 \u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e",159,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0634\u0650\u064a\u064e\u0639\u064b\u0627 \u0644\u064e\u0633\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",160,"\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0634\u0652\u0631\u064f \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u0652\u0632\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",161,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0647\u064e\u062f\u064e\u0627\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d \u062f\u0650\u064a\u0646\u064b\u0627 \u0642\u0650\u064a\u064e\u0645\u064b\u0627 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",162,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0646\u064f\u0633\u064f\u0643\u0650\u064a \u0648\u064e\u0645\u064e\u062d\u0652\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u064a \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",163,"\u0644\u064e\u0627 \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",164,"\u0642\u064f\u0644\u0652 \u0623\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u0652\u063a\u0650\u064a \u0631\u064e\u0628\u0651\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u064c \u0648\u0650\u0632\u0652\u0631\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",165,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0644\u064e\u0627\u0626\u0650\u0641\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0648\u0652\u0642\u064e \u0628\u064e\u0639\u0652\u0636\u064d \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c"],t.v)
B.abS=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0645\u0635",2,"\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u064a \u0635\u064e\u062f\u0652\u0631\u0650\u0643\u064e \u062d\u064e\u0631\u064e\u062c\u064c \u0645\u0650\u0646\u0652\u0647\u064f \u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",3,"\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06d7 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064e\u0627 \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u062a\u064b\u0627 \u0623\u064e\u0648\u0652 \u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0626\u0650\u0644\u064f\u0648\u0646\u064e",5,"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062f\u064e\u0639\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",6,"\u0641\u064e\u0644\u064e\u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",7,"\u0641\u064e\u0644\u064e\u0646\u064e\u0642\u064f\u0635\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u063a\u064e\u0627\u0626\u0650\u0628\u0650\u064a\u0646\u064e",8,"\u0648\u064e\u0627\u0644\u0652\u0648\u064e\u0632\u0652\u0646\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0645\u064e\u0646\u0652 \u062e\u064e\u0641\u0651\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0639\u064e\u0627\u064a\u0650\u0634\u064e \u06d7 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",11,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0635\u064e\u0648\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0622\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",12,"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0633\u0652\u062c\u064f\u062f\u064e \u0625\u0650\u0630\u0652 \u0623\u064e\u0645\u064e\u0631\u0652\u062a\u064f\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",13,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0627\u0647\u0652\u0628\u0650\u0637\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0643\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u062a\u064e\u0643\u064e\u0628\u0651\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u063a\u0650\u0631\u0650\u064a\u0646\u064e",14,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0652\u0638\u0650\u0631\u0652\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",15,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0638\u064e\u0631\u0650\u064a\u0646\u064e",16,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064e\u0642\u0652\u0639\u064f\u062f\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0635\u0650\u0631\u064e\u0627\u0637\u064e\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064e",17,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0622\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u0646\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u0646\u0652 \u0634\u064e\u0645\u064e\u0627\u0626\u0650\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",18,"\u0642\u064e\u0627\u0644\u064e \u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0630\u0652\u0621\u064f\u0648\u0645\u064b\u0627 \u0645\u064e\u062f\u0652\u062d\u064f\u0648\u0631\u064b\u0627 \u06d6 \u0644\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",19,"\u0648\u064e\u064a\u064e\u0627 \u0622\u062f\u064e\u0645\u064f \u0627\u0633\u0652\u0643\u064f\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0632\u064e\u0648\u0652\u062c\u064f\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0641\u064e\u0643\u064f\u0644\u064e\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",20,"\u0641\u064e\u0648\u064e\u0633\u0652\u0648\u064e\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0644\u0650\u064a\u064f\u0628\u0652\u062f\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u064e\u0627 \u0648\u064f\u0648\u0631\u0650\u064a\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0633\u064e\u0648\u0652\u0622\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0627\u0643\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0648\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0642\u064e\u0627\u0633\u064e\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u062d\u0650\u064a\u0646\u064e",22,"\u0641\u064e\u062f\u064e\u0644\u0651\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u063a\u064f\u0631\u064f\u0648\u0631\u064d \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0627\u0642\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0628\u064e\u062f\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u0652\u0622\u062a\u064f\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0637\u064e\u0641\u0650\u0642\u064e\u0627 \u064a\u064e\u062e\u0652\u0635\u0650\u0641\u064e\u0627\u0646\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0642\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u0647\u064e\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u0646\u0652 \u062a\u0650\u0644\u0652\u0643\u064f\u0645\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",23,"\u0642\u064e\u0627\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",24,"\u0642\u064e\u0627\u0644\u064e \u0627\u0647\u0652\u0628\u0650\u0637\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064c \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",25,"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u062d\u0652\u064a\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e",26,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0627\u0633\u064b\u0627 \u064a\u064f\u0648\u064e\u0627\u0631\u0650\u064a \u0633\u064e\u0648\u0652\u0622\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u0650\u064a\u0634\u064b\u0627 \u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",27,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u064a\u064e\u0646\u0652\u0632\u0650\u0639\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u0628\u064e\u0627\u0633\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u0652\u0622\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0647\u064f\u0648\u064e \u0648\u064e\u0642\u064e\u0628\u0650\u064a\u0644\u064f\u0647\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",28,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f \u0628\u0650\u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u06d6 \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",29,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0645\u064e\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06d6 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064d \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u06da \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e",30,"\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0647\u064e\u062f\u064e\u0649\u0670 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",31,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u062e\u064f\u0630\u064f\u0648\u0627 \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064d \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",32,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u0650 \u06da \u0642\u064f\u0644\u0652 \u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u064b \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",33,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u064e\u0627\u062d\u0650\u0634\u064e \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0637\u064e\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u064a\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0628\u0650\u0647\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u064c \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0645\u064f\u0648\u0646\u064e",35,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0642\u064f\u0635\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u06d9 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",37,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",38,"\u0642\u064e\u0627\u0644\u064e \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0623\u064f\u0645\u064e\u0645\u064d \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064e\u062a\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0644\u064e\u0639\u064e\u0646\u064e\u062a\u0652 \u0623\u064f\u062e\u0652\u062a\u064e\u0647\u064e\u0627 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0627\u062f\u0651\u064e\u0627\u0631\u064e\u0643\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0623\u064f\u062e\u0652\u0631\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u0623\u064f\u0648\u0644\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0646\u064e\u0627 \u0641\u064e\u0622\u062a\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0636\u0650\u0639\u0652\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u064d \u0636\u0650\u0639\u0652\u0641\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0623\u064f\u0648\u0644\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u0623\u064f\u062e\u0652\u0631\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u064d \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",40,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0641\u064e\u062a\u0651\u064e\u062d\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0644\u0650\u062c\u064e \u0627\u0644\u0652\u062c\u064e\u0645\u064e\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0645\u0651\u0650 \u0627\u0644\u0652\u062e\u0650\u064a\u064e\u0627\u0637\u0650 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",41,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0647\u064e\u0627\u062f\u064c \u0648\u064e\u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u063a\u064e\u0648\u064e\u0627\u0634\u064d \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",42,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",43,"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u063a\u0650\u0644\u0651\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0644\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u064e \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0648\u064e\u0646\u064f\u0648\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u0650\u0644\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0623\u064f\u0648\u0631\u0650\u062b\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",44,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0646\u0652 \u0642\u064e\u062f\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062d\u064e\u0642\u0651\u064b\u0627 \u0641\u064e\u0647\u064e\u0644\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u062d\u064e\u0642\u0651\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0639\u064e\u0645\u0652 \u06da \u0641\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0645\u064f\u0624\u064e\u0630\u0651\u0650\u0646\u064c \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",45,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0628\u064c \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0641\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0643\u064f\u0644\u0651\u064b\u0627 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0644\u064e\u0645\u0652 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0637\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0635\u064f\u0631\u0650\u0641\u064e\u062a\u0652 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u062a\u0650\u0644\u0652\u0642\u064e\u0627\u0621\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",48,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0641\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0652\u0639\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",49,"\u0623\u064e\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0642\u0652\u0633\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u06da \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u0623\u064e\u0641\u0650\u064a\u0636\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0623\u064e\u0648\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",51,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u0652\u0648\u064b\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u064b\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0646\u0652\u0633\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",52,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",53,"\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064e\u0647\u064f \u06da \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064f\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0633\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0647\u064e\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0621\u064e \u0641\u064e\u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0641\u064e\u0646\u064e\u0639\u0652\u0645\u064e\u0644\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u06da \u0642\u064e\u062f\u0652 \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",54,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u064a\u064f\u063a\u0652\u0634\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u064a\u064e\u0637\u0652\u0644\u064f\u0628\u064f\u0647\u064f \u062d\u064e\u062b\u0650\u064a\u062b\u064b\u0627 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064e \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0627\u062a\u064d \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u06d7 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",55,"\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u064b\u0627 \u0648\u064e\u062e\u064f\u0641\u0652\u064a\u064e\u0629\u064b \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",56,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u062e\u064e\u0648\u0652\u0641\u064b\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0631\u0650\u064a\u0628\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0628\u064f\u0634\u0652\u0631\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0642\u064e\u0644\u0651\u064e\u062a\u0652 \u0633\u064e\u062d\u064e\u0627\u0628\u064b\u0627 \u062b\u0650\u0642\u064e\u0627\u0644\u064b\u0627 \u0633\u064f\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0644\u0650\u0628\u064e\u0644\u064e\u062f\u064d \u0645\u064e\u064a\u0651\u0650\u062a\u064d \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0644\u064e\u062f\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0646\u064e\u0628\u064e\u0627\u062a\u064f\u0647\u064f \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0628\u064f\u062b\u064e \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0643\u0650\u062f\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",59,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",60,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",61,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",62,"\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645\u0652 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u0652\u0635\u064e\u062d\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",63,"\u0623\u064e\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",64,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u064e\u0645\u0650\u064a\u0646\u064e",65,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064d \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0647\u064f\u0648\u062f\u064b\u0627 \u06d7 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",66,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0641\u0650\u064a \u0633\u064e\u0641\u064e\u0627\u0647\u064e\u0629\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",67,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u064a \u0633\u064e\u0641\u064e\u0627\u0647\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",68,"\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645\u0652 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0627\u0635\u0650\u062d\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",69,"\u0623\u064e\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0642\u064e\u0648\u0652\u0645\u0650 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u0628\u064e\u0633\u0652\u0637\u064e\u0629\u064b \u06d6 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0622\u0644\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",70,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0623\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",71,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u0652 \u0648\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0631\u0650\u062c\u0652\u0633\u064c \u0648\u064e\u063a\u064e\u0636\u064e\u0628\u064c \u06d6 \u0623\u064e\u062a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0641\u0650\u064a \u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064d \u0633\u064e\u0645\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u06da \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",72,"\u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",73,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u06d7 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064b \u06d6 \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u0652 \u0641\u0650\u064a \u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0621\u064d \u0641\u064e\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",74,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0639\u064e\u0627\u062f\u064d \u0648\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0633\u064f\u0647\u064f\u0648\u0644\u0650\u0647\u064e\u0627 \u0642\u064f\u0635\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u062a\u064e\u0646\u0652\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u06d6 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0622\u0644\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",75,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0628\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",76,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",77,"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064f \u0627\u0626\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",78,u.r,79,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0628\u0652\u0644\u064e\u063a\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0646\u064e\u0635\u064e\u062d\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u062d\u0650\u064a\u0646\u064e",80,"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0623\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",81,"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0634\u064e\u0647\u0652\u0648\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e",82,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u0646\u064e\u0627\u0633\u064c \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",83,"\u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",84,"\u0648\u064e\u0623\u064e\u0645\u0652\u0637\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0637\u064e\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",85,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u06d7 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062e\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u0650\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",86,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0639\u064f\u062f\u064f\u0648\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u062a\u064f\u0648\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u062a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u06da \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0641\u064e\u0643\u064e\u062b\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f \u0628\u0650\u0647\u0650 \u0648\u064e\u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u062d\u064e\u0627\u0643\u0650\u0645\u0650\u064a\u0646\u064e",88,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0644\u064e\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064e \u064a\u064e\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u062a\u0650\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0643\u064e\u0627\u0631\u0650\u0647\u0650\u064a\u0646\u064e",89,"\u0642\u064e\u062f\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0625\u0650\u0646\u0652 \u0639\u064f\u062f\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0639\u064f\u0648\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06da \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u062a\u0650\u062d\u0650\u064a\u0646\u064e",90,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",91,u.r,92,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u063a\u0652\u0646\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",93,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0628\u0652\u0644\u064e\u063a\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0646\u064e\u0635\u064e\u062d\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0622\u0633\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",94,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0636\u0651\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",95,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0639\u064e\u0641\u064e\u0648\u0652\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0642\u064e\u062f\u0652 \u0645\u064e\u0633\u0651\u064e \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0627\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u064f \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0631\u0651\u064e\u0627\u0621\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",96,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0644\u064e\u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u064e\u0631\u064e\u0643\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",97,"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u062a\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0627\u0626\u0650\u0645\u064f\u0648\u0646\u064e",98,"\u0623\u064e\u0648\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u0636\u064f\u062d\u064b\u0649 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0644\u0652\u0639\u064e\u0628\u064f\u0648\u0646\u064e",99,"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064f\u0648\u0627 \u0645\u064e\u0643\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064e\u0646\u064f \u0645\u064e\u0643\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",100,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0623\u064e\u0635\u064e\u0628\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0646\u064e\u0637\u0652\u0628\u064e\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",101,"\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0626\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u0652\u0628\u064e\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",102,"\u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0647\u0652\u062f\u064d \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",103,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u0641\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",104,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u064a\u064e\u0627 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",105,"\u062d\u064e\u0642\u0650\u064a\u0642\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06da \u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",106,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u062c\u0650\u0626\u0652\u062a\u064e \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",107,u.bX,108,u.ad,109,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",110,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e",111,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0631\u0652\u062c\u0650\u0647\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u064e\u0627\u0626\u0650\u0646\u0650 \u062d\u064e\u0627\u0634\u0650\u0631\u0650\u064a\u0646\u064e",112,"\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0627\u062d\u0650\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",113,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",114,"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0639\u064e\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",115,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0642\u0650\u064a\u0646\u064e",116,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0633\u064e\u062d\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",117,"\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0641\u0650\u0643\u064f\u0648\u0646\u064e",118,"\u0641\u064e\u0648\u064e\u0642\u064e\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0628\u064e\u0637\u064e\u0644\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",119,"\u0641\u064e\u063a\u064f\u0644\u0650\u0628\u064f\u0648\u0627 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0635\u064e\u0627\u063a\u0650\u0631\u0650\u064a\u0646\u064e",120,"\u0648\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",121,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",122,"\u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",123,"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u0622\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0645\u064e\u0643\u0652\u0631\u064c \u0645\u064e\u0643\u064e\u0631\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u0650\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",124,"\u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064d \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",125,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",126,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u0652\u0642\u0650\u0645\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0646\u064e\u0627 \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0641\u0652\u0631\u0650\u063a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0635\u064e\u0628\u0652\u0631\u064b\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",127,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u062a\u064e\u0630\u064e\u0631\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064e\u0643\u064e \u0648\u064e\u0622\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064f\u0642\u064e\u062a\u0651\u0650\u0644\u064f \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u0650\u064a \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0647\u0650\u0631\u064f\u0648\u0646\u064e",128,"\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0627\u0633\u0652\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0648\u0631\u0650\u062b\u064f\u0647\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",129,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064f\u0648\u0630\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u0650\u0641\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",130,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0622\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0646\u064e\u0642\u0652\u0635\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",131,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u064a\u064e\u0637\u0651\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0637\u064e\u0627\u0626\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",132,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0647\u0652\u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0629\u064d \u0644\u0650\u062a\u064e\u0633\u0652\u062d\u064e\u0631\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",133,"\u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0637\u0651\u064f\u0648\u0641\u064e\u0627\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0631\u064e\u0627\u062f\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0645\u0651\u064e\u0644\u064e \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0641\u064e\u0627\u062f\u0650\u0639\u064e \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0645\u064e \u0622\u064a\u064e\u0627\u062a\u064d \u0645\u064f\u0641\u064e\u0635\u0651\u064e\u0644\u064e\u0627\u062a\u064d \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",134,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0632\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0647\u0650\u062f\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u06d6 \u0644\u064e\u0626\u0650\u0646\u0652 \u0643\u064e\u0634\u064e\u0641\u0652\u062a\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0632\u064e \u0644\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",135,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0632\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0647\u064f\u0645\u0652 \u0628\u064e\u0627\u0644\u0650\u063a\u064f\u0648\u0647\u064f \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0643\u064f\u062b\u064f\u0648\u0646\u064e",136,"\u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0642\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",137,"\u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u063a\u064e\u0627\u0631\u0650\u0628\u064e\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0634\u064f\u0648\u0646\u064e",138,"\u0648\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u0652\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0641\u064e\u0623\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0643\u064f\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064d \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0644\u0650\u0647\u064e\u0629\u064c \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u062a\u064e\u062c\u0652\u0647\u064e\u0644\u064f\u0648\u0646\u064e",139,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0645\u064f\u062a\u064e\u0628\u0651\u064e\u0631\u064c \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0644\u064c \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",140,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u0652\u063a\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u064e\u0636\u0651\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",141,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06d6 \u064a\u064f\u0642\u064e\u062a\u0651\u0650\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0644\u064e\u0627\u0621\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c",142,"\u0648\u064e\u0648\u064e\u0627\u0639\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062b\u064e\u0644\u064e\u0627\u062b\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u062a\u0652\u0645\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0628\u0650\u0639\u064e\u0634\u0652\u0631\u064d \u0641\u064e\u062a\u064e\u0645\u0651\u064e \u0645\u0650\u064a\u0642\u064e\u0627\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0627\u062e\u0652\u0644\u064f\u0641\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",143,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0631\u0650\u0646\u0650\u064a \u0623\u064e\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0646\u0652 \u062a\u064e\u0631\u064e\u0627\u0646\u0650\u064a \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0628\u064e\u0644\u0650 \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0631\u064e\u0627\u0646\u0650\u064a \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u062c\u064e\u0644\u0651\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0644\u0650\u0644\u0652\u062c\u064e\u0628\u064e\u0644\u0650 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u062f\u064e\u0643\u0651\u064b\u0627 \u0648\u064e\u062e\u064e\u0631\u0651\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0635\u064e\u0639\u0650\u0642\u064b\u0627 \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0641\u064e\u0627\u0642\u064e \u0642\u064e\u0627\u0644\u064e \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u062a\u064f\u0628\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",144,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u0650\u064a \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u064a\u0652\u062a\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0628\u0650\u0643\u064e\u0644\u064e\u0627\u0645\u0650\u064a \u0641\u064e\u062e\u064f\u0630\u0652 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0643\u064e \u0648\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",145,"\u0648\u064e\u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0648\u064e\u0627\u062d\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064b \u0648\u064e\u062a\u064e\u0641\u0652\u0635\u0650\u064a\u0644\u064b\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u062e\u064f\u0630\u0652\u0647\u064e\u0627 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0623\u0652\u0645\u064f\u0631\u0652 \u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650\u0647\u064e\u0627 \u06da \u0633\u064e\u0623\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u062f\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",146,"\u0633\u064e\u0623\u064e\u0635\u0652\u0631\u0650\u0641\u064f \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0643\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064f\u0644\u0651\u064e \u0622\u064a\u064e\u0629\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0631\u0651\u064f\u0634\u0652\u062f\u0650 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0651\u0650 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",147,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u06da \u0647\u064e\u0644\u0652 \u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",148,"\u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0642\u064e\u0648\u0652\u0645\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u062d\u064f\u0644\u0650\u064a\u0651\u0650\u0647\u0650\u0645\u0652 \u0639\u0650\u062c\u0652\u0644\u064b\u0627 \u062c\u064e\u0633\u064e\u062f\u064b\u0627 \u0644\u064e\u0647\u064f \u062e\u064f\u0648\u064e\u0627\u0631\u064c \u06da \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627 \u06d8 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",149,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064f\u0642\u0650\u0637\u064e \u0641\u0650\u064a \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",150,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u063a\u064e\u0636\u0652\u0628\u064e\u0627\u0646\u064e \u0623\u064e\u0633\u0650\u0641\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0628\u0650\u0626\u0652\u0633\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u064a \u06d6 \u0623\u064e\u0639\u064e\u062c\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0648\u064e\u0627\u062d\u064e \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e \u0628\u0650\u0631\u064e\u0623\u0652\u0633\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u064a\u064e\u062c\u064f\u0631\u0651\u064f\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u0627\u0628\u0652\u0646\u064e \u0623\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0627 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0645\u0650\u062a\u0652 \u0628\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",151,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0623\u064e\u062e\u0650\u064a \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u06d6 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0623\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",152,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0633\u064e\u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u063a\u064e\u0636\u064e\u0628\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e",153,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",154,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0643\u064e\u062a\u064e \u0639\u064e\u0646\u0652 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u063a\u064e\u0636\u064e\u0628\u064f \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0648\u064e\u0627\u062d\u064e \u06d6 \u0648\u064e\u0641\u0650\u064a \u0646\u064f\u0633\u0652\u062e\u064e\u062a\u0650\u0647\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u064e",155,"\u0648\u064e\u0627\u062e\u0652\u062a\u064e\u0627\u0631\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u0633\u064e\u0628\u0652\u0639\u0650\u064a\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062c\u0652\u0641\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0648\u0652 \u0634\u0650\u0626\u0652\u062a\u064e \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u064a\u064e \u06d6 \u0623\u064e\u062a\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u062a\u064f\u0643\u064e \u062a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0646\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",156,"\u0648\u064e\u0627\u0643\u0652\u062a\u064f\u0628\u0652 \u0644\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064f\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0623\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u0623\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0633\u0650\u0639\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0641\u064e\u0633\u064e\u0623\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",157,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0627\u0644\u0652\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u064e\u0643\u0652\u062a\u064f\u0648\u0628\u064b\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u0650 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u064e\u0627\u0626\u0650\u062b\u064e \u0648\u064e\u064a\u064e\u0636\u064e\u0639\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0635\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u06d9 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",158,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06d6 \u0641\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0627\u0644\u0652\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",159,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u064a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0647\u0650 \u064a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e",160,"\u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u064a\u0652 \u0639\u064e\u0634\u0652\u0631\u064e\u0629\u064e \u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0637\u064b\u0627 \u0623\u064f\u0645\u064e\u0645\u064b\u0627 \u06da \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0630\u0650 \u0627\u0633\u0652\u062a\u064e\u0633\u0652\u0642\u064e\u0627\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u0623\u064e\u0646\u0650 \u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0628\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u062c\u064e\u0631\u064e \u06d6 \u0641\u064e\u0627\u0646\u0652\u0628\u064e\u062c\u064e\u0633\u064e\u062a\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u0627 \u0639\u064e\u0634\u0652\u0631\u064e\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u06d6 \u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u064e\u0627\u0633\u064d \u0645\u064e\u0634\u0652\u0631\u064e\u0628\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0638\u064e\u0644\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0645\u064e\u0627\u0645\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u0652\u0648\u064e\u0649\u0670 \u06d6 \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",161,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064e \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u062d\u0650\u0637\u0651\u064e\u0629\u064c \u0648\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0646\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u06da \u0633\u064e\u0646\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",162,"\u0641\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u0650\u062c\u0652\u0632\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",163,"\u0648\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u062d\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0625\u0650\u0630\u0652 \u064a\u064e\u0639\u0652\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u062a\u0650 \u0625\u0650\u0630\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u062d\u0650\u064a\u062a\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0633\u064e\u0628\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0634\u064f\u0631\u0651\u064e\u0639\u064b\u0627 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0628\u0650\u062a\u064f\u0648\u0646\u064e \u06d9 \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0628\u0652\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",164,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u0650\u0645\u064e \u062a\u064e\u0639\u0650\u0638\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u06d9 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0639\u0652\u0630\u0650\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",165,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627 \u0645\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u0650 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0628\u064e\u0626\u0650\u064a\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",166,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652 \u0645\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064b \u062e\u064e\u0627\u0633\u0650\u0626\u0650\u064a\u0646\u064e",167,"\u0648\u064e\u0625\u0650\u0630\u0652 \u062a\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",168,"\u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064f\u0645\u064e\u0645\u064b\u0627 \u06d6 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0648\u064e\u0628\u064e\u0644\u064e\u0648\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",169,"\u0641\u064e\u062e\u064e\u0644\u064e\u0641\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u0644\u0652\u0641\u064c \u0648\u064e\u0631\u0650\u062b\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u064a\u064f\u063a\u0652\u0641\u064e\u0631\u064f \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0631\u064e\u0636\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064f \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u06da \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u062e\u064e\u0630\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u062f\u064e\u0631\u064e\u0633\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",170,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0645\u064e\u0633\u0651\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u0644\u0650\u062d\u0650\u064a\u0646\u064e",171,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062a\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0628\u064e\u0644\u064e \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0638\u064f\u0644\u0651\u064e\u0629\u064c \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0642\u0650\u0639\u064c \u0628\u0650\u0647\u0650\u0645\u0652 \u062e\u064f\u0630\u064f\u0648\u0627 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",172,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0645\u0650\u0646\u0652 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u064e\u0633\u0652\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u06db \u0634\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u06db \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",173,"\u0623\u064e\u0648\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0623\u064e\u0641\u064e\u062a\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0646\u064e",174,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",175,"\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0627\u0646\u0652\u0633\u064e\u0644\u064e\u062e\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",176,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u0650\u0626\u0652\u0646\u064e\u0627 \u0644\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u062e\u0652\u0644\u064e\u062f\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u06da \u0641\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0652\u0643\u064e\u0644\u0652\u0628\u0650 \u0625\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0644\u0652\u0647\u064e\u062b\u0652 \u0623\u064e\u0648\u0652 \u062a\u064e\u062a\u0652\u0631\u064f\u0643\u0652\u0647\u064f \u064a\u064e\u0644\u0652\u0647\u064e\u062b\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0641\u064e\u0627\u0642\u0652\u0635\u064f\u0635\u0650 \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",177,"\u0633\u064e\u0627\u0621\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",178,"\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0652 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",179,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0630\u064e\u0631\u064e\u0623\u0652\u0646\u064e\u0627 \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064c \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064c \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0630\u064e\u0627\u0646\u064c \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0643\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",180,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u0641\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0644\u0652\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0626\u0650\u0647\u0650 \u06da \u0633\u064e\u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",181,"\u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u064a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0647\u0650 \u064a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e",182,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0633\u064e\u0646\u064e\u0633\u0652\u062a\u064e\u062f\u0652\u0631\u0650\u062c\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",183,"\u0648\u064e\u0623\u064f\u0645\u0652\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u0650\u064a \u0645\u064e\u062a\u0650\u064a\u0646\u064c",184,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u06d7 \u0645\u064e\u0627 \u0628\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u062c\u0650\u0646\u0651\u064e\u0629\u064d \u06da \u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",185,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0623\u064e\u0646\u0652 \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0642\u064e\u062f\u0650 \u0627\u0642\u0652\u062a\u064e\u0631\u064e\u0628\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",186,"\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u0647\u064e\u0627\u062f\u0650\u064a\u064e \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",187,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0631\u0652\u0633\u064e\u0627\u0647\u064e\u0627 \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0644\u0651\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u0648\u064e\u0642\u0652\u062a\u0650\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u06d7 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062d\u064e\u0641\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",188,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0644\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u062b\u064e\u0631\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064f \u06da \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0648\u064e\u0628\u064e\u0634\u0650\u064a\u0631\u064c \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",189,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0632\u064e\u0648\u0652\u062c\u064e\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0633\u0652\u0643\u064f\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u063a\u064e\u0634\u0651\u064e\u0627\u0647\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u0652 \u062d\u064e\u0645\u0652\u0644\u064b\u0627 \u062e\u064e\u0641\u0650\u064a\u0641\u064b\u0627 \u0641\u064e\u0645\u064e\u0631\u0651\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062b\u0652\u0642\u064e\u0644\u064e\u062a\u0652 \u062f\u064e\u0639\u064e\u0648\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0622\u062a\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",190,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u06da \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",191,"\u0623\u064e\u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u062e\u0652\u0644\u064e\u0642\u064f\u0648\u0646\u064e",192,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0652\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e",193,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u06da \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u0645\u0650\u062a\u064f\u0648\u0646\u064e",194,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u064c \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",195,"\u0623\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064c \u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u062f\u064d \u064a\u064e\u0628\u0652\u0637\u0650\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064c \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0630\u064e\u0627\u0646\u064c \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0650 \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0638\u0650\u0631\u064f\u0648\u0646\u0650",196,"\u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",197,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e",198,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0648\u064e\u062a\u064e\u0631\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",199,"\u062e\u064f\u0630\u0650 \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0623\u0652\u0645\u064f\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0631\u0652\u0641\u0650 \u0648\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",200,"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0646\u0652\u0632\u064e\u063a\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0646\u064e\u0632\u0652\u063a\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0630\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",201,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f\u0645\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",202,"\u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u064a\u0651\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",203,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0627\u062c\u0652\u062a\u064e\u0628\u064e\u064a\u0652\u062a\u064e\u0647\u064e\u0627 \u06da \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u06da \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",204,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0626\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u0635\u0650\u062a\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",205,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u064b\u0627 \u0648\u064e\u062e\u0650\u064a\u0641\u064e\u0629\u064b \u0648\u064e\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0647\u0652\u0631\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0628\u0650\u0627\u0644\u0652\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0622\u0635\u064e\u0627\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",206,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0646\u064e \u06e9"],t.v)
B.asc=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064e\u0627\u0644\u0650 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064e\u0627\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u06d6 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0630\u064e\u0627\u062a\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",2,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u0644\u0650\u064a\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0647\u064f \u0632\u064e\u0627\u062f\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",4,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",5,"\u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u062a\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0644\u064e\u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",6,"\u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0633\u064e\u0627\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u0627\u0626\u0650\u0641\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u0648\u0652\u0643\u064e\u0629\u0650 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",8,"\u0644\u0650\u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064f\u0628\u0652\u0637\u0650\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",9,"\u0625\u0650\u0630\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u062b\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064f\u0645\u0650\u062f\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0644\u0652\u0641\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0631\u0652\u062f\u0650\u0641\u0650\u064a\u0646\u064e",10,"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u0650\u062a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0628\u0650\u0647\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0635\u0652\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",11,"\u0625\u0650\u0630\u0652 \u064a\u064f\u063a\u064e\u0634\u0651\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064f\u0639\u064e\u0627\u0633\u064e \u0623\u064e\u0645\u064e\u0646\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0644\u0650\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0630\u0652\u0647\u0650\u0628\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0631\u0650\u062c\u0652\u0632\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0631\u0652\u0628\u0650\u0637\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u064e",12,"\u0625\u0650\u0630\u0652 \u064a\u064f\u0648\u062d\u0650\u064a \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06da \u0633\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064f\u0639\u0652\u0628\u064e \u0641\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0627 \u0641\u064e\u0648\u0652\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650 \u0648\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0628\u064e\u0646\u064e\u0627\u0646\u064d",13,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0627\u0642\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u064e\u0627\u0642\u0650\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",14,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",15,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0632\u064e\u062d\u0652\u0641\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e",16,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0648\u064e\u0644\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062f\u064f\u0628\u064f\u0631\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u062a\u064e\u062d\u064e\u0631\u0651\u0650\u0641\u064b\u0627 \u0644\u0650\u0642\u0650\u062a\u064e\u0627\u0644\u064d \u0623\u064e\u0648\u0652 \u0645\u064f\u062a\u064e\u062d\u064e\u064a\u0651\u0650\u0632\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0626\u064e\u0629\u064d \u0641\u064e\u0642\u064e\u062f\u0652 \u0628\u064e\u0627\u0621\u064e \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",17,"\u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0645\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0630\u0652 \u0631\u064e\u0645\u064e\u064a\u0652\u062a\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0645\u064e\u0649\u0670 \u06da \u0648\u064e\u0644\u0650\u064a\u064f\u0628\u0652\u0644\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0628\u064e\u0644\u064e\u0627\u0621\u064b \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",18,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u0648\u0647\u0650\u0646\u064f \u0643\u064e\u064a\u0652\u062f\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",19,"\u0625\u0650\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650\u062d\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u062a\u0652\u062d\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627 \u0646\u064e\u0639\u064f\u062f\u0652 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064f\u063a\u0652\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u0626\u064e\u062a\u064f\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u062b\u064f\u0631\u064e\u062a\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",20,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",22,"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u0631\u0651\u064e \u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0628\u0651\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064f \u0627\u0644\u0652\u0628\u064f\u0643\u0652\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0639\u064e\u0644\u0650\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0623\u064e\u0633\u0652\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0633\u0652\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",24,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0643\u064f\u0645\u0652 \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u064f\u0648\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u0650 \u0648\u064e\u0642\u064e\u0644\u0652\u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u064e\u0627 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u062e\u064e\u0627\u0635\u0651\u064e\u0629\u064b \u06d6 \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",26,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u064e\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0641\u064e\u0622\u0648\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0646\u064e\u0635\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",27,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064f\u0648\u0646\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u062a\u064e\u062e\u064f\u0648\u0646\u064f\u0648\u0627 \u0623\u064e\u0645\u064e\u0627\u0646\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",28,"\u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",29,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u0652 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",30,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f \u0628\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u064a\u064f\u062b\u0652\u0628\u0650\u062a\u064f\u0648\u0643\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0643\u064e \u0623\u064e\u0648\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0643\u064e \u06da \u0648\u064e\u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",31,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0642\u064e\u062f\u0652 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d9 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",32,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0645\u0652\u0637\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0623\u064e\u0648\u0650 \u0627\u0626\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",33,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0624\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0643\u064e\u0627\u0621\u064b \u0648\u064e\u062a\u064e\u0635\u0652\u062f\u0650\u064a\u064e\u0629\u064b \u06da \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",36,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0633\u064e\u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0633\u0652\u0631\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u063a\u0652\u0644\u064e\u0628\u064f\u0648\u0646\u064e \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",37,"\u0644\u0650\u064a\u064e\u0645\u0650\u064a\u0632\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0641\u064e\u064a\u064e\u0631\u0652\u0643\u064f\u0645\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064f \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",38,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u064a\u064f\u063a\u0652\u0641\u064e\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0642\u064e\u062f\u0652 \u0633\u064e\u0644\u064e\u0641\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0636\u064e\u062a\u0652 \u0633\u064f\u0646\u0651\u064e\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",39,"\u0648\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0646\u0652\u062a\u064e\u0647\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",40,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064f",41,"\u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u063a\u064e\u0646\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062e\u064f\u0645\u064f\u0633\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0644\u0650\u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0628\u0652\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",42,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064f\u0635\u0652\u0648\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0643\u0652\u0628\u064f \u0623\u064e\u0633\u0652\u0641\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0648\u064e\u0627\u0639\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u0650 \u06d9 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u0650\u064a\u064e\u0642\u0652\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627 \u0644\u0650\u064a\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u0645\u064e\u0646\u0652 \u0647\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0648\u064e\u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u062d\u064e\u064a\u0651\u064e \u0639\u064e\u0646\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",43,"\u0625\u0650\u0630\u0652 \u064a\u064f\u0631\u0650\u064a\u0643\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0645\u0650\u0643\u064e \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u0643\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0644\u064e\u0641\u064e\u0634\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0644\u0651\u064e\u0645\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",44,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u0650 \u0627\u0644\u0652\u062a\u064e\u0642\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0643\u064f\u0645\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0644\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u064a\u064e\u0642\u0652\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627 \u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",45,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u0652 \u0641\u0650\u0626\u064e\u0629\u064b \u0641\u064e\u0627\u062b\u0652\u0628\u064f\u062a\u064f\u0648\u0627 \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u0641\u0652\u0634\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0630\u0652\u0647\u064e\u0628\u064e \u0631\u0650\u064a\u062d\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",47,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0628\u064e\u0637\u064e\u0631\u064b\u0627 \u0648\u064e\u0631\u0650\u0626\u064e\u0627\u0621\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u064c",48,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u063a\u064e\u0627\u0644\u0650\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0621\u064e\u062a\u0650 \u0627\u0644\u0652\u0641\u0650\u0626\u064e\u062a\u064e\u0627\u0646\u0650 \u0646\u064e\u0643\u064e\u0635\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0649\u0670 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",49,"\u0625\u0650\u0630\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u063a\u064e\u0631\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u062f\u0650\u064a\u0646\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",50,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06d9 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",51,u.Z,52,"\u0643\u064e\u062f\u064e\u0623\u0652\u0628\u0650 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06d9 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",53,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f \u0645\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064b\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064b \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d9 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",54,"\u0643\u064e\u062f\u064e\u0623\u0652\u0628\u0650 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06d9 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0622\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",55,"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u0631\u0651\u064e \u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0628\u0651\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",56,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0647\u064e\u062f\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0646\u0652\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",57,"\u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062b\u0652\u0642\u064e\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u0628\u0650 \u0641\u064e\u0634\u064e\u0631\u0651\u0650\u062f\u0652 \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u062e\u0650\u064a\u064e\u0627\u0646\u064e\u0629\u064b \u0641\u064e\u0627\u0646\u0652\u0628\u0650\u0630\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0621\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0626\u0650\u0646\u0650\u064a\u0646\u064e",59,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0639\u0652\u062c\u0650\u0632\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0623\u064e\u0639\u0650\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0645\u0650\u0646\u0652 \u0631\u0650\u0628\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0644\u0650 \u062a\u064f\u0631\u0652\u0647\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0648\u064e\u0641\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",61,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062c\u064e\u0646\u064e\u062d\u064f\u0648\u0627 \u0644\u0650\u0644\u0633\u0651\u064e\u0644\u0652\u0645\u0650 \u0641\u064e\u0627\u062c\u0652\u0646\u064e\u062d\u0652 \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",62,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u062f\u064e\u0639\u064f\u0648\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062d\u064e\u0633\u0652\u0628\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0643\u064e \u0628\u0650\u0646\u064e\u0635\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",63,"\u0648\u064e\u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u0652\u062a\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0645\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0641\u0652\u062a\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",64,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062d\u064e\u0633\u0652\u0628\u064f\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",65,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062d\u064e\u0631\u0651\u0650\u0636\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u0650 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0639\u0650\u0634\u0652\u0631\u064f\u0648\u0646\u064e \u0635\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0627 \u0645\u0650\u0627\u0626\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0627\u0626\u064e\u0629\u064c \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0627 \u0623\u064e\u0644\u0652\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",66,"\u0627\u0644\u0652\u0622\u0646\u064e \u062e\u064e\u0641\u0651\u064e\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0636\u064e\u0639\u0652\u0641\u064b\u0627 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0627\u0626\u064e\u0629\u064c \u0635\u064e\u0627\u0628\u0650\u0631\u064e\u0629\u064c \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0627 \u0645\u0650\u0627\u0626\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0644\u0652\u0641\u064c \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0627 \u0623\u064e\u0644\u0652\u0641\u064e\u064a\u0652\u0646\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",67,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u062b\u0652\u062e\u0650\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",68,"\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0633\u064e\u0628\u064e\u0642\u064e \u0644\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",69,"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u063a\u064e\u0646\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",70,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644\u0652 \u0644\u0650\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0631\u064e\u0649\u0670 \u0625\u0650\u0646\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u064a\u064f\u0624\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064f\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",71,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0627 \u062e\u0650\u064a\u064e\u0627\u0646\u064e\u062a\u064e\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0627\u0646\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0623\u064e\u0645\u0652\u0643\u064e\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",72,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0648\u064e\u0648\u0652\u0627 \u0648\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u064e\u0627\u064a\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0635\u0652\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064c \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",73,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u062a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0641\u064e\u0633\u064e\u0627\u062f\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",74,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0648\u064e\u0648\u0652\u0627 \u0648\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",75,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c"],t.v)
B.as9=new A.U([1,"\u0628\u064e\u0631\u064e\u0627\u0621\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0647\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",2,"\u0641\u064e\u0633\u0650\u064a\u062d\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u064e \u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064d \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",3,"\u0648\u064e\u0623\u064e\u0630\u064e\u0627\u0646\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0628\u064e\u0631\u0650 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u06d9 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",4,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0647\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u0642\u064f\u0635\u064f\u0648\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0641\u064e\u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0639\u064e\u0647\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",5,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0633\u064e\u0644\u064e\u062e\u064e \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064f \u0627\u0644\u0652\u062d\u064f\u0631\u064f\u0645\u064f \u0641\u064e\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062d\u064e\u064a\u0652\u062b\u064f \u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u062d\u0652\u0635\u064f\u0631\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0642\u0652\u0639\u064f\u062f\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0631\u0652\u0635\u064e\u062f\u064d \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0648\u064f\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0641\u064e\u062e\u064e\u0644\u0651\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",6,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0631\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u062c\u0650\u0631\u0652\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064e \u0643\u064e\u0644\u064e\u0627\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0628\u0652\u0644\u0650\u063a\u0652\u0647\u064f \u0645\u064e\u0623\u0652\u0645\u064e\u0646\u064e\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",7,"\u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0639\u064e\u0647\u0652\u062f\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0647\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",8,"\u0643\u064e\u064a\u0652\u0641\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0638\u0652\u0647\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0642\u064f\u0628\u064f\u0648\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0645\u0651\u064e\u0629\u064b \u06da \u064a\u064f\u0631\u0652\u0636\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062a\u064e\u0623\u0652\u0628\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",9,"\u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u0652\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",10,"\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0642\u064f\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064d \u0625\u0650\u0644\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0645\u0651\u064e\u0629\u064b \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",11,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0648\u064f\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0641\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u06d7 \u0648\u064e\u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0646\u064e\u0643\u064e\u062b\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0639\u064e\u0647\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0637\u064e\u0639\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",13,"\u0623\u064e\u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0646\u064e\u0643\u064e\u062b\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064e\u0645\u0651\u064f\u0648\u0627 \u0628\u0650\u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u062f\u064e\u0621\u064f\u0648\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u06da \u0623\u064e\u062a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0647\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",14,"\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062e\u0652\u0632\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0646\u0652\u0635\u064f\u0631\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0634\u0652\u0641\u0650 \u0635\u064f\u062f\u064f\u0648\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064d \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",15,"\u0648\u064e\u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652 \u063a\u064e\u064a\u0652\u0638\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",16,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u062a\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u062c\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",17,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064f\u0631\u064f\u0648\u0627 \u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u0652 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",18,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064f\u0631\u064f \u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0649 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062e\u0652\u0634\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",19,"\u0623\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0633\u0650\u0642\u064e\u0627\u064a\u064e\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u0627\u062c\u0651\u0650 \u0648\u064e\u0639\u0650\u0645\u064e\u0627\u0631\u064e\u0629\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0643\u064e\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",20,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0639\u0652\u0638\u064e\u0645\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0626\u0650\u0632\u064f\u0648\u0646\u064e",21,"\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064d \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0639\u0650\u064a\u0645\u064c \u0645\u064f\u0642\u0650\u064a\u0645\u064c",22,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",23,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",24,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064c \u0627\u0642\u0652\u062a\u064e\u0631\u064e\u0641\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064c \u062a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0643\u064e\u0633\u064e\u0627\u062f\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064f \u062a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u0623\u064e\u062d\u064e\u0628\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u062c\u0650\u0647\u064e\u0627\u062f\u064d \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",25,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0635\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0645\u064e\u0648\u064e\u0627\u0637\u0650\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064d \u06d9 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062d\u064f\u0646\u064e\u064a\u0652\u0646\u064d \u06d9 \u0625\u0650\u0630\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0643\u064e\u062b\u0652\u0631\u064e\u062a\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064f\u063a\u0652\u0646\u0650 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0636\u064e\u0627\u0642\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u064f\u0628\u064e\u062a\u0652 \u062b\u064f\u0645\u0651\u064e \u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",26,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u062c\u064f\u0646\u064f\u0648\u062f\u064b\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0648\u0652\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",27,"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",28,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0646\u064e\u062c\u064e\u0633\u064c \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0639\u064e\u0627\u0645\u0650\u0647\u0650\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062e\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u063a\u0652\u0646\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",29,"\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062f\u0650\u064a\u0646\u064f\u0648\u0646\u064e \u062f\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0639\u0652\u0637\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u0650\u0632\u0652\u064a\u064e\u0629\u064e \u0639\u064e\u0646\u0652 \u064a\u064e\u062f\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u063a\u0650\u0631\u064f\u0648\u0646\u064e",30,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0639\u064f\u0632\u064e\u064a\u0652\u0631\u064c \u0627\u0628\u0652\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0627\u0628\u0652\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u06d6 \u064a\u064f\u0636\u064e\u0627\u0647\u0650\u0626\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0642\u064e\u0627\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",31,"\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0623\u064e\u062d\u0652\u0628\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064f\u0647\u0652\u0628\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0631\u0652\u0628\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064b\u0627 \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",32,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0637\u0652\u0641\u0650\u0626\u064f\u0648\u0627 \u0646\u064f\u0648\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0623\u0652\u0628\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u064f\u0648\u0631\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",33,u.b8,34,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0628\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0647\u0652\u0628\u064e\u0627\u0646\u0650 \u0644\u064e\u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u0646\u0650\u0632\u064f\u0648\u0646\u064e \u0627\u0644\u0630\u0651\u064e\u0647\u064e\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u0650\u0636\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",35,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u062d\u0652\u0645\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0641\u064e\u062a\u064f\u0643\u0652\u0648\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u062c\u0650\u0628\u064e\u0627\u0647\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0646\u064e\u0632\u0652\u062a\u064f\u0645\u0652 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0646\u0650\u0632\u064f\u0648\u0646\u064e",36,"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0627\u0644\u0634\u0651\u064f\u0647\u064f\u0648\u0631\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u062b\u0652\u0646\u064e\u0627 \u0639\u064e\u0634\u064e\u0631\u064e \u0634\u064e\u0647\u0652\u0631\u064b\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u064c \u062d\u064f\u0631\u064f\u0645\u064c \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u0650\u0645\u064f \u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0641\u0651\u064e\u0629\u064b \u0643\u064e\u0645\u064e\u0627 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0651\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",37,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0633\u0650\u064a\u0621\u064f \u0632\u0650\u064a\u064e\u0627\u062f\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u06d6 \u064a\u064f\u0636\u064e\u0644\u0651\u064f \u0628\u0650\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0647\u064f \u0639\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0647\u064f \u0639\u064e\u0627\u0645\u064b\u0627 \u0644\u0650\u064a\u064f\u0648\u064e\u0627\u0637\u0650\u0626\u064f\u0648\u0627 \u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u064a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0627 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",38,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u062b\u0651\u064e\u0627\u0642\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0623\u064e\u0631\u064e\u0636\u0650\u064a\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0641\u064e\u0645\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c",39,"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u062f\u0650\u0644\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",40,"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0635\u064e\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062b\u064e\u0627\u0646\u0650\u064a\u064e \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u0630\u0652 \u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0647\u0650 \u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0647\u064f \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u064d \u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0648\u0652\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0641\u0652\u0644\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u0650\u064a\u064e \u0627\u0644\u0652\u0639\u064f\u0644\u0652\u064a\u064e\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",41,"\u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u062e\u0650\u0641\u064e\u0627\u0641\u064b\u0627 \u0648\u064e\u062b\u0650\u0642\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",42,"\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064b\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627 \u0648\u064e\u0633\u064e\u0641\u064e\u0631\u064b\u0627 \u0642\u064e\u0627\u0635\u0650\u062f\u064b\u0627 \u0644\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0643\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0628\u064e\u0639\u064f\u062f\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0634\u0651\u064f\u0642\u0651\u064e\u0629\u064f \u06da \u0648\u064e\u0633\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0644\u064e\u062e\u064e\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",43,"\u0639\u064e\u0641\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0643\u064e \u0644\u0650\u0645\u064e \u0623\u064e\u0630\u0650\u0646\u0652\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",44,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",45,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u0627\u0631\u0652\u062a\u064e\u0627\u0628\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u064a\u0652\u0628\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u064e\u0631\u064e\u062f\u0651\u064e\u062f\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064f\u0631\u064f\u0648\u062c\u064e \u0644\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0639\u064f\u062f\u0651\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0646\u0652\u0628\u0650\u0639\u064e\u0627\u062b\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062b\u064e\u0628\u0651\u064e\u0637\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u0642\u0652\u0639\u064f\u062f\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0639\u0650\u062f\u0650\u064a\u0646\u064e",47,"\u0644\u064e\u0648\u0652 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064f\u0648\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0628\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0644\u064e\u0623\u064e\u0648\u0652\u0636\u064e\u0639\u064f\u0648\u0627 \u062e\u0650\u0644\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064e \u0648\u064e\u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0633\u064e\u0645\u0651\u064e\u0627\u0639\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",48,"\u0644\u064e\u0642\u064e\u062f\u0650 \u0627\u0628\u0652\u062a\u064e\u063a\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0638\u064e\u0647\u064e\u0631\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0626\u0652\u0630\u064e\u0646\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u062a\u0650\u0646\u0651\u0650\u064a \u06da \u0623\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0633\u064e\u0642\u064e\u0637\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064f\u062d\u0650\u064a\u0637\u064e\u0629\u064c \u0628\u0650\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",50,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0643\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u062a\u064e\u0633\u064f\u0624\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0643\u064e \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",51,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0646\u0652 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0646\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0646\u064e\u0627 \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",52,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u064a\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0647\u0650 \u0623\u064e\u0648\u0652 \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0646\u064e\u0627 \u06d6 \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u064f\u0648\u0646\u064e",53,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0637\u064e\u0648\u0652\u0639\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0631\u0652\u0647\u064b\u0627 \u0644\u064e\u0646\u0652 \u064a\u064f\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",54,"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0642\u0652\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0646\u064e\u0641\u064e\u0642\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0633\u064e\u0627\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",55,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u0652\u062c\u0650\u0628\u0652\u0643\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u062a\u064e\u0632\u0652\u0647\u064e\u0642\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u064a\u064e\u0641\u0652\u0631\u064e\u0642\u064f\u0648\u0646\u064e",57,"\u0644\u064e\u0648\u0652 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0644\u0652\u062c\u064e\u0623\u064b \u0623\u064e\u0648\u0652 \u0645\u064e\u063a\u064e\u0627\u0631\u064e\u0627\u062a\u064d \u0623\u064e\u0648\u0652 \u0645\u064f\u062f\u0651\u064e\u062e\u064e\u0644\u064b\u0627 \u0644\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062c\u0652\u0645\u064e\u062d\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0644\u0652\u0645\u0650\u0632\u064f\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064f\u0639\u0652\u0637\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0631\u064e\u0636\u064f\u0648\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064f\u0639\u0652\u0637\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062e\u064e\u0637\u064f\u0648\u0646\u064e",59,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0636\u064f\u0648\u0627 \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062d\u064e\u0633\u0652\u0628\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0627\u063a\u0650\u0628\u064f\u0648\u0646\u064e",60,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u064e\u0644\u0651\u064e\u0641\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0627\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0628\u0652\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u06d6 \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",61,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0630\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064f\u0648\u064e \u0623\u064f\u0630\u064f\u0646\u064c \u06da \u0642\u064f\u0644\u0652 \u0623\u064f\u0630\u064f\u0646\u064f \u062e\u064e\u064a\u0652\u0631\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0630\u064f\u0648\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",62,"\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064f\u0631\u0652\u0636\u064f\u0648\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0631\u0652\u0636\u064f\u0648\u0647\u064f \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",63,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064f\u062d\u064e\u0627\u062f\u0650\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u064b\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u062e\u0650\u0632\u0652\u064a\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",64,"\u064a\u064e\u062d\u0652\u0630\u064e\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0650 \u0627\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0631\u0650\u062c\u064c \u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0646\u064e",65,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064f\u0648\u0636\u064f \u0648\u064e\u0646\u064e\u0644\u0652\u0639\u064e\u0628\u064f \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",66,"\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627 \u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0652 \u0646\u064e\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064b \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",67,"\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064e\u0627\u062a\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u0628\u0650\u0636\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u06da \u0646\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0647\u0650\u064a\u064e \u062d\u064e\u0633\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0642\u0650\u064a\u0645\u064c",69,"\u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064b\u0627 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u064f\u0648\u0627 \u0628\u0650\u062e\u064e\u0644\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0644\u064e\u0627\u0642\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0644\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062e\u064f\u0636\u0652\u062a\u064f\u0645\u0652 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0627\u0636\u064f\u0648\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",70,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u062a\u064e\u0641\u0650\u0643\u064e\u0627\u062a\u0650 \u06da \u0623\u064e\u062a\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u064a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0633\u064e\u064a\u064e\u0631\u0652\u062d\u064e\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",72,"\u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064e \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0639\u064e\u062f\u0652\u0646\u064d \u06da \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",73,u.b9,74,"\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0647\u064e\u0645\u0651\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0645\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0623\u064e\u063a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u064a\u064e\u0643\u064f \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",75,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u0647\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0622\u062a\u064e\u0627\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0646\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064e\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",76,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0628\u064e\u062e\u0650\u0644\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",77,"\u0641\u064e\u0623\u064e\u0639\u0652\u0642\u064e\u0628\u064e\u0647\u064f\u0645\u0652 \u0646\u0650\u0641\u064e\u0627\u0642\u064b\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0644\u064e\u0641\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0647\u064f \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0648\u0646\u064e",78,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0633\u0650\u0631\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u062c\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0651\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u063a\u064f\u064a\u064f\u0648\u0628\u0650",79,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0644\u0652\u0645\u0650\u0632\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0637\u0651\u064e\u0648\u0651\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064f\u0647\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u064a\u064e\u0633\u0652\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d9 \u0633\u064e\u062e\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",80,"\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0628\u0652\u0639\u0650\u064a\u0646\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064b \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",81,"\u0641\u064e\u0631\u0650\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0642\u0652\u0639\u064e\u062f\u0650\u0647\u0650\u0645\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0631\u0651\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0646\u064e\u0627\u0631\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062d\u064e\u0631\u0651\u064b\u0627 \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",82,"\u0641\u064e\u0644\u0652\u064a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0644\u0652\u064a\u064e\u0628\u0652\u0643\u064f\u0648\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",83,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0631\u064e\u062c\u064e\u0639\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u064e\u0646\u064f\u0648\u0643\u064e \u0644\u0650\u0644\u0652\u062e\u064f\u0631\u064f\u0648\u062c\u0650 \u0641\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0646\u0652 \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u064e\u0639\u0650\u064a\u064e \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0645\u064e\u0639\u0650\u064a\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0636\u0650\u064a\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0639\u064f\u0648\u062f\u0650 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0641\u064e\u0627\u0642\u0652\u0639\u064f\u062f\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0641\u0650\u064a\u0646\u064e",84,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0644\u0651\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627\u062a\u064e \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0628\u0652\u0631\u0650\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u0652\u062c\u0650\u0628\u0652\u0643\u064e \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u062a\u064e\u0632\u0652\u0647\u064e\u0642\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",86,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0623\u064e\u0646\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u064e\u0646\u064e\u0643\u064e \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0637\u0651\u064e\u0648\u0652\u0644\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0630\u064e\u0631\u0652\u0646\u064e\u0627 \u0646\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0639\u0650\u062f\u0650\u064a\u0646\u064e",87,"\u0631\u064e\u0636\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u062e\u064e\u0648\u064e\u0627\u0644\u0650\u0641\u0650 \u0648\u064e\u0637\u064f\u0628\u0650\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",88,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u064f \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",89,"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",90,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0644\u0650\u064a\u064f\u0624\u0652\u0630\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",91,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u062d\u064e\u0631\u064e\u062c\u064c \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0635\u064e\u062d\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06da \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064d \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",92,"\u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0648\u0652\u0643\u064e \u0644\u0650\u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064f\u0644\u0652\u062a\u064e \u0644\u064e\u0627 \u0623\u064e\u062c\u0650\u062f\u064f \u0645\u064e\u0627 \u0623\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0648\u064e\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u0652 \u062a\u064e\u0641\u0650\u064a\u0636\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064e\u0645\u0652\u0639\u0650 \u062d\u064e\u0632\u064e\u0646\u064b\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",93,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u063a\u0652\u0646\u0650\u064a\u064e\u0627\u0621\u064f \u06da \u0631\u064e\u0636\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u062e\u064e\u0648\u064e\u0627\u0644\u0650\u0641\u0650 \u0648\u064e\u0637\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",94,"\u064a\u064e\u0639\u0652\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u062e\u0652\u0628\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",95,"\u0633\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u0650\u062a\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u062c\u0652\u0633\u064c \u06d6 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",96,"\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u062a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",97,"\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u0648\u064e\u0646\u0650\u0641\u064e\u0627\u0642\u064b\u0627 \u0648\u064e\u0623\u064e\u062c\u0652\u062f\u064e\u0631\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",98,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f \u0645\u064e\u063a\u0652\u0631\u064e\u0645\u064b\u0627 \u0648\u064e\u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0626\u0650\u0631\u064e \u06da \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062f\u064e\u0627\u0626\u0650\u0631\u064e\u0629\u064f \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",99,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f \u0642\u064f\u0631\u064f\u0628\u064e\u0627\u062a\u064d \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u06da \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0642\u064f\u0631\u0652\u0628\u064e\u0629\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0633\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",100,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u062a\u064e\u062d\u0652\u062a\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",101,"\u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u06d6 \u0645\u064e\u0631\u064e\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u0650\u0641\u064e\u0627\u0642\u0650 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u0652 \u06da \u0633\u064e\u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",102,"\u0648\u064e\u0622\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0627\u0639\u0652\u062a\u064e\u0631\u064e\u0641\u064f\u0648\u0627 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u0644\u064e\u0637\u064f\u0648\u0627 \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0622\u062e\u064e\u0631\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064b\u0627 \u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",103,"\u062e\u064f\u0630\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b \u062a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u062a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0635\u064e\u0644\u0651\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u064e\u0643\u064e \u0633\u064e\u0643\u064e\u0646\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",104,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0642\u0652\u0628\u064e\u0644\u064f \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0628\u064e\u0629\u064e \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",105,"\u0648\u064e\u0642\u064f\u0644\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u0633\u064e\u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",106,"\u0648\u064e\u0622\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u064f\u0631\u0652\u062c\u064e\u0648\u0652\u0646\u064e \u0644\u0650\u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",107,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064b\u0627 \u0636\u0650\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u0648\u064e\u062a\u064e\u0641\u0652\u0631\u0650\u064a\u0642\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0631\u0652\u0635\u064e\u0627\u062f\u064b\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u062d\u064e\u0627\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0648\u064e\u0644\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",108,"\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0644\u064e\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064c \u0623\u064f\u0633\u0651\u0650\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0641\u0650\u064a\u0647\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0637\u0651\u064e\u0647\u0651\u0650\u0631\u0650\u064a\u0646\u064e",109,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0651\u064e\u0633\u064e \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064d \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0651\u064e\u0633\u064e \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0641\u064e\u0627 \u062c\u064f\u0631\u064f\u0641\u064d \u0647\u064e\u0627\u0631\u064d \u0641\u064e\u0627\u0646\u0652\u0647\u064e\u0627\u0631\u064e \u0628\u0650\u0647\u0650 \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",110,"\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0646\u064e\u0648\u0652\u0627 \u0631\u0650\u064a\u0628\u064e\u0629\u064b \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",111,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u06da \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064f\u0642\u0652\u062a\u064e\u0644\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0648\u0652\u0641\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0628\u064e\u064a\u0652\u0639\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0627\u064a\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",112,"\u0627\u0644\u062a\u0651\u064e\u0627\u0626\u0650\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0628\u0650\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0627\u0645\u0650\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u062d\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0627\u0643\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0622\u0645\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0647\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e \u0644\u0650\u062d\u064f\u062f\u064f\u0648\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",113,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",114,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0633\u0652\u062a\u0650\u063a\u0652\u0641\u064e\u0627\u0631\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0646\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064e\u0629\u064d \u0648\u064e\u0639\u064e\u062f\u064e\u0647\u064e\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u0623\u064e\u0648\u0651\u064e\u0627\u0647\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",115,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0647\u064e\u062f\u064e\u0627\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",116,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",117,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0633\u064e\u0627\u0639\u064e\u0629\u0650 \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u062f\u064e \u064a\u064e\u0632\u0650\u064a\u063a\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0641\u064e\u0631\u0650\u064a\u0642\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u0645\u0652 \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",118,"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u062b\u0651\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064f\u0644\u0651\u0650\u0641\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0627\u0642\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u064f\u0628\u064e\u062a\u0652 \u0648\u064e\u0636\u064e\u0627\u0642\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0645\u064e\u0644\u0652\u062c\u064e\u0623\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u0650\u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",119,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",120,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u063a\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u0652 \u0638\u064e\u0645\u064e\u0623\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u064c \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u062e\u0652\u0645\u064e\u0635\u064e\u0629\u064c \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0637\u064e\u0626\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u0652\u0637\u0650\u0626\u064b\u0627 \u064a\u064e\u063a\u0650\u064a\u0638\u064f \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064d \u0646\u064e\u064a\u0652\u0644\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u064e\u0645\u064e\u0644\u064c \u0635\u064e\u0627\u0644\u0650\u062d\u064c \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",121,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0646\u064e\u0641\u064e\u0642\u064e\u0629\u064b \u0635\u064e\u063a\u0650\u064a\u0631\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u062f\u0650\u064a\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",122,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064e\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0643\u064e\u0627\u0641\u0651\u064e\u0629\u064b \u06da \u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064e\u0641\u064e\u0631\u064e \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0641\u0650\u0631\u0652\u0642\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0644\u0650\u064a\u064e\u062a\u064e\u0641\u064e\u0642\u0651\u064e\u0647\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0646\u064e",123,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0644\u0652\u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u063a\u0650\u0644\u0652\u0638\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",124,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u0652 \u0632\u064e\u0627\u062f\u064e\u062a\u0652\u0647\u064f \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e",125,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u0650\u062c\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u0650\u062c\u0652\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",126,"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0641\u0652\u062a\u064e\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0627\u0645\u064d \u0645\u064e\u0631\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",127,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0646\u064e\u0638\u064e\u0631\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0647\u064e\u0644\u0652 \u064a\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0646\u0652\u0635\u064e\u0631\u064e\u0641\u064f\u0648\u0627 \u06da \u0635\u064e\u0631\u064e\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",128,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0627 \u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u0652 \u062d\u064e\u0631\u0650\u064a\u0635\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",129,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0642\u064f\u0644\u0652 \u062d\u064e\u0633\u0652\u0628\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650"],t.v)
B.asj=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",2,"\u0623\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u062c\u064e\u0628\u064b\u0627 \u0623\u064e\u0646\u0652 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u062f\u064e\u0645\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",3,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u06d6 \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u06d6 \u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u0641\u0650\u064a\u0639\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",4,"\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0631\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u0650\u064a\u0645\u064d \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",5,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0636\u0650\u064a\u064e\u0627\u0621\u064b \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0646\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f \u0645\u064e\u0646\u064e\u0627\u0632\u0650\u0644\u064e \u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0639\u064e\u062f\u064e\u062f\u064e \u0627\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u064e \u06da \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u064a\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",6,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",7,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0637\u0652\u0645\u064e\u0623\u064e\u0646\u0651\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",8,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",9,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",10,"\u062f\u064e\u0639\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0648\u064e\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u06da \u0648\u064e\u0622\u062e\u0650\u0631\u064f \u062f\u064e\u0639\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0644\u064e\u0648\u0652 \u064a\u064f\u0639\u064e\u062c\u0651\u0650\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064e \u0627\u0633\u0652\u062a\u0650\u0639\u0652\u062c\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0646\u064e\u0630\u064e\u0631\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u062f\u064e\u0639\u064e\u0627\u0646\u064e\u0627 \u0644\u0650\u062c\u064e\u0646\u0652\u0628\u0650\u0647\u0650 \u0623\u064e\u0648\u0652 \u0642\u064e\u0627\u0639\u0650\u062f\u064b\u0627 \u0623\u064e\u0648\u0652 \u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0636\u064f\u0631\u0651\u064e\u0647\u064f \u0645\u064e\u0631\u0651\u064e \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062f\u0652\u0639\u064f\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0636\u064f\u0631\u0651\u064d \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u06d9 \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",14,"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u062e\u064e\u0644\u064e\u0627\u0626\u0650\u0641\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u0646\u064e\u0646\u0652\u0638\u064f\u0631\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",15,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u06d9 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0627\u0626\u0652\u062a\u0650 \u0628\u0650\u0642\u064f\u0631\u0652\u0622\u0646\u064d \u063a\u064e\u064a\u0652\u0631\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u0648\u0652 \u0628\u064e\u062f\u0651\u0650\u0644\u0652\u0647\u064f \u06da \u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u0623\u064e\u0646\u0652 \u0623\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062a\u0650\u0644\u0652\u0642\u064e\u0627\u0621\u0650 \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0625\u0650\u0646\u0652 \u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",16,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u062a\u064e\u0644\u064e\u0648\u0652\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0639\u064f\u0645\u064f\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",17,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0636\u064e\u0631\u0651\u064e\u0627\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0643\u0652\u0631\u064c \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0631\u064e\u0639\u064f \u0645\u064e\u0643\u0652\u0631\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",22,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0633\u064e\u064a\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u062c\u064e\u0631\u064e\u064a\u0652\u0646\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0631\u0650\u064a\u062d\u064d \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064d \u0648\u064e\u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064e\u0627 \u0631\u0650\u064a\u062d\u064c \u0639\u064e\u0627\u0635\u0650\u0641\u064c \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062c\u064f \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u062d\u0650\u064a\u0637\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u06d9 \u062f\u064e\u0639\u064e\u0648\u064f\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",23,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062c\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0628\u064e\u063a\u0652\u064a\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0645\u064e\u062a\u064e\u0627\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",24,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u0627\u0621\u064d \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0647\u0650 \u0646\u064e\u0628\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0632\u064f\u062e\u0652\u0631\u064f\u0641\u064e\u0647\u064e\u0627 \u0648\u064e\u0627\u0632\u0651\u064e\u064a\u0651\u064e\u0646\u064e\u062a\u0652 \u0648\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0644\u064e\u064a\u0652\u0644\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0647\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u062d\u064e\u0635\u0650\u064a\u062f\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u063a\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0625\u0650\u0644\u064e\u0649\u0670 \u062f\u064e\u0627\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u0650 \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",26,"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u0632\u0650\u064a\u064e\u0627\u062f\u064e\u0629\u064c \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0647\u064e\u0642\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u062a\u064e\u0631\u064c \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0644\u0651\u064e\u0629\u064c \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064d \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u0652\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u0652 \u0630\u0650\u0644\u0651\u064e\u0629\u064c \u06d6 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u064e\u0627\u0635\u0650\u0645\u064d \u06d6 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u063a\u0652\u0634\u0650\u064a\u064e\u062a\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0642\u0650\u0637\u064e\u0639\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0645\u064f\u0638\u0652\u0644\u0650\u0645\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",28,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u06da \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0646\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",29,"\u0641\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",30,"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062a\u064e\u0628\u0652\u0644\u064f\u0648 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0644\u064e\u0641\u064e\u062a\u0652 \u06da \u0648\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",31,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u06da \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0641\u064e\u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",32,"\u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d6 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064f \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0635\u0652\u0631\u064e\u0641\u064f\u0648\u0646\u064e",33,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",34,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",35,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0647\u0650\u062f\u0651\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0647\u0652\u062f\u064e\u0649\u0670 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0638\u064e\u0646\u0651\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062a\u064e\u0635\u0652\u062f\u0650\u064a\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u062a\u064e\u0641\u0652\u0635\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",38,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u06d6 \u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0633\u064f\u0648\u0631\u064e\u0629\u064d \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",39,"\u0628\u064e\u0644\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0627 \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064f\u0647\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",40,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",41,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0644\u0650\u064a \u0639\u064e\u0645\u064e\u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0645\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0631\u0650\u064a\u0626\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",42,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",43,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0639\u064f\u0645\u0652\u064a\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",44,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u0628\u064e\u062b\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u064a\u064e\u062a\u064e\u0639\u064e\u0627\u0631\u064e\u0641\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0642\u064e\u062f\u0652 \u062e\u064e\u0633\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u0645\u0652 \u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",48,u.k,49,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u064c \u06da \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0645\u064f\u0648\u0646\u064e",50,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f\u0647\u064f \u0628\u064e\u064a\u064e\u0627\u062a\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u0647\u064e\u0627\u0631\u064b\u0627 \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",51,"\u0623\u064e\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06da \u0622\u0644\u0652\u0622\u0646\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",52,"\u062b\u064f\u0645\u0651\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u0650 \u0647\u064e\u0644\u0652 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0628\u0650\u0626\u064f\u0648\u0646\u064e\u0643\u064e \u0623\u064e\u062d\u064e\u0642\u0651\u064c \u0647\u064f\u0648\u064e \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0642\u0651\u064c \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e",54,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0641\u0652\u0633\u064d \u0638\u064e\u0644\u064e\u0645\u064e\u062a\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0627\u0641\u0652\u062a\u064e\u062f\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u062f\u064e\u0627\u0645\u064e\u0629\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u06d6 \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06da \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",55,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",56,"\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",57,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0634\u0650\u0641\u064e\u0627\u0621\u064c \u0644\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",58,"\u0642\u064f\u0644\u0652 \u0628\u0650\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0641\u064e\u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u0652\u064a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",59,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u064d \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u062d\u064e\u0631\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0642\u064f\u0644\u0652 \u0622\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",61,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0641\u0650\u064a \u0634\u064e\u0623\u0652\u0646\u064d \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062a\u0652\u0644\u064f\u0648 \u0645\u0650\u0646\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064f\u0631\u0652\u0622\u0646\u064d \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0634\u064f\u0647\u064f\u0648\u062f\u064b\u0627 \u0625\u0650\u0630\u0652 \u062a\u064f\u0641\u0650\u064a\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0632\u064f\u0628\u064f \u0639\u064e\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u0650 \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0635\u0652\u063a\u064e\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",62,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",63,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",64,"\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",65,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0652\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u06d8 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",66,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u0635\u064f\u0648\u0646\u064e",67,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0644\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",68,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u06d7 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06d6 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u06d6 \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",69,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",70,"\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0630\u0650\u064a\u0642\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0634\u0651\u064e\u062f\u0650\u064a\u062f\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064e \u0646\u064f\u0648\u062d\u064d \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0642\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u062a\u064e\u0630\u0652\u0643\u0650\u064a\u0631\u0650\u064a \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0641\u064e\u0623\u064e\u062c\u0652\u0645\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u063a\u064f\u0645\u0651\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u0627\u0642\u0652\u0636\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0638\u0650\u0631\u064f\u0648\u0646\u0650",72,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",73,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062e\u064e\u0644\u064e\u0627\u0626\u0650\u0641\u064e \u0648\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0630\u064e\u0631\u0650\u064a\u0646\u064e",74,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u062c\u064e\u0627\u0621\u064f\u0648\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0637\u0652\u0628\u064e\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",75,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",76,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",77,"\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0633\u0650\u062d\u0652\u0631\u064c \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f\u0648\u0646\u064e",78,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064e\u0644\u0652\u0641\u0650\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u0628\u0652\u0631\u0650\u064a\u064e\u0627\u0621\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",79,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0627\u0626\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0627\u062d\u0650\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",80,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e",81,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u064a\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f \u0639\u064e\u0645\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",82,"\u0648\u064e\u064a\u064f\u062d\u0650\u0642\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",83,"\u0641\u064e\u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u064e \u0644\u0650\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0648\u0652\u0641\u064d \u0645\u0650\u0646\u0652 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0644\u064e\u0639\u064e\u0627\u0644\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",84,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",85,"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",86,"\u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0622 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0645\u0650\u0635\u0652\u0631\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0643\u064f\u0645\u0652 \u0642\u0650\u0628\u0652\u0644\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",88,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0622\u062a\u064e\u064a\u0652\u062a\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0623\u064e\u0647\u064f \u0632\u0650\u064a\u0646\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0643\u064e \u06d6 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u0637\u0652\u0645\u0650\u0633\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0634\u0652\u062f\u064f\u062f\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064e",89,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u0652 \u0623\u064f\u062c\u0650\u064a\u0628\u064e\u062a\u0652 \u062f\u064e\u0639\u0652\u0648\u064e\u062a\u064f\u0643\u064f\u0645\u064e\u0627 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e\u0627\u0646\u0651\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",90,"\u0648\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u0652\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u0652\u0648\u064b\u0627 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0643\u064e\u0647\u064f \u0627\u0644\u0652\u063a\u064e\u0631\u064e\u0642\u064f \u0642\u064e\u0627\u0644\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u0645\u064e\u0646\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0628\u064e\u0646\u064f\u0648 \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",91,"\u0622\u0644\u0652\u0622\u0646\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064e \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",92,"\u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064e \u0628\u0650\u0628\u064e\u062f\u064e\u0646\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u064e\u0643\u064e \u0622\u064a\u064e\u0629\u064b \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",93,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0628\u064e\u0648\u0651\u064e\u0623\u0652\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0645\u064f\u0628\u064e\u0648\u0651\u064e\u0623\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u0652\u0636\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",94,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u0652\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u06da \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0645\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e",95,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",96,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",97,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064f \u0622\u064a\u064e\u0629\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064e",98,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064c \u0622\u0645\u064e\u0646\u064e\u062a\u0652 \u0641\u064e\u0646\u064e\u0641\u064e\u0639\u064e\u0647\u064e\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062e\u0650\u0632\u0652\u064a\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",99,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u0622\u0645\u064e\u0646\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064f\u0643\u0652\u0631\u0650\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",100,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u064d \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",101,"\u0642\u064f\u0644\u0650 \u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0645\u064e\u0627\u0630\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u063a\u0652\u0646\u0650\u064a \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f \u0639\u064e\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",102,"\u0641\u064e\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",103,"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0646\u064f\u0646\u0652\u062c\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",104,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",105,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0650\u0645\u0652 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",106,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",107,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u064d \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064e \u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652\u0643\u064e \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0644\u064e\u0627 \u0631\u064e\u0627\u062f\u0651\u064e \u0644\u0650\u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",108,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",109,"\u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u062d\u064e\u0627\u0643\u0650\u0645\u0650\u064a\u0646\u064e"],t.v)
B.apv=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631 \u06da \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064f\u062d\u0652\u0643\u0650\u0645\u064e\u062a\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u062e\u064e\u0628\u0650\u064a\u0631\u064d",2,"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0648\u064e\u0628\u064e\u0634\u0650\u064a\u0631\u064c",3,"\u0648\u064e\u0623\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u0650 \u0643\u064f\u0644\u0651\u064e \u0630\u0650\u064a \u0641\u064e\u0636\u0652\u0644\u064d \u0641\u064e\u0636\u0652\u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0643\u064e\u0628\u0650\u064a\u0631\u064d",4,"\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",5,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062b\u0652\u0646\u064f\u0648\u0646\u064e \u0635\u064f\u062f\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0641\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0623\u064e\u0644\u064e\u0627 \u062d\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0634\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",6,"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u0650\u0632\u0652\u0642\u064f\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u0652\u062f\u064e\u0639\u064e\u0647\u064e\u0627 \u06da \u0643\u064f\u0644\u0651\u064c \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",7,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0631\u0652\u0634\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u06d7 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0642\u064f\u0644\u0652\u062a\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",8,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0629\u064d \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0628\u0650\u0633\u064f\u0647\u064f \u06d7 \u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0644\u064e\u064a\u0652\u0633\u064e \u0645\u064e\u0635\u0652\u0631\u064f\u0648\u0641\u064b\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0632\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u064a\u064e\u0626\u064f\u0648\u0633\u064c \u0643\u064e\u0641\u064f\u0648\u0631\u064c",10,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0646\u064e\u0639\u0652\u0645\u064e\u0627\u0621\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0636\u064e\u0631\u0651\u064e\u0627\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u0652\u0647\u064f \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0630\u064e\u0647\u064e\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0639\u064e\u0646\u0651\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u064e\u0631\u0650\u062d\u064c \u0641\u064e\u062e\u064f\u0648\u0631\u064c",11,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",12,"\u0641\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u062a\u064e\u0627\u0631\u0650\u0643\u064c \u0628\u064e\u0639\u0652\u0636\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0636\u064e\u0627\u0626\u0650\u0642\u064c \u0628\u0650\u0647\u0650 \u0635\u064e\u062f\u0652\u0631\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064e\u0646\u0652\u0632\u064c \u0623\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0645\u064e\u0644\u064e\u0643\u064c \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0643\u0650\u064a\u0644\u064c",13,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u06d6 \u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0634\u0652\u0631\u0650 \u0633\u064f\u0648\u064e\u0631\u064d \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0645\u064f\u0641\u0652\u062a\u064e\u0631\u064e\u064a\u064e\u0627\u062a\u064d \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",14,"\u0641\u064e\u0625\u0650\u0644\u0651\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",15,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064e\u0627 \u0646\u064f\u0648\u064e\u0641\u0651\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u062e\u064e\u0633\u064f\u0648\u0646\u064e",16,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u062d\u064e\u0628\u0650\u0637\u064e \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0644\u064c \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",17,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0647\u064f \u0634\u064e\u0627\u0647\u0650\u062f\u064c \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0645\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u0650 \u0641\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064f\u0647\u064f \u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0647\u064e\u0627\u062f\u064f \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06da \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",19,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",20,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06d8 \u064a\u064f\u0636\u064e\u0627\u0639\u064e\u0641\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06da \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",21,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",22,"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u0633\u064e\u0631\u064f\u0648\u0646\u064e",23,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u062e\u0652\u0628\u064e\u062a\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",24,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u0652\u0646\u0650 \u0643\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0635\u064e\u0645\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u0650 \u06da \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a\u064e\u0627\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",26,"\u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",27,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0650\u062b\u0652\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0623\u064e\u0631\u064e\u0627\u0630\u0650\u0644\u064f\u0646\u064e\u0627 \u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0631\u0651\u064e\u0623\u0652\u064a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u064d \u0628\u064e\u0644\u0652 \u0646\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",28,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0622\u062a\u064e\u0627\u0646\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0647\u0650 \u0641\u064e\u0639\u064f\u0645\u0651\u0650\u064a\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u064f\u0644\u0652\u0632\u0650\u0645\u064f\u0643\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",29,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0627\u0644\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0637\u064e\u0627\u0631\u0650\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0644\u064e\u0627\u0642\u064f\u0648 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u062a\u064e\u062c\u0652\u0647\u064e\u0644\u064f\u0648\u0646\u064e",30,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0637\u064e\u0631\u064e\u062f\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u064c \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0632\u0652\u062f\u064e\u0631\u0650\u064a \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u06d6 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0646\u064f\u0648\u062d\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u062f\u064e\u0644\u0652\u062a\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u0652\u062a\u064e \u062c\u0650\u062f\u064e\u0627\u0644\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",33,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e",34,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0643\u064f\u0645\u0652 \u0646\u064f\u0635\u0652\u062d\u0650\u064a \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u062d\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u063a\u0652\u0648\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u06da \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",35,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u064a\u0652\u062a\u064f\u0647\u064f \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u062c\u0652\u0631\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064d \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0642\u064e\u062f\u0652 \u0622\u0645\u064e\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062a\u064e\u0626\u0650\u0633\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0627\u0635\u0652\u0646\u064e\u0639\u0650 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u062d\u0652\u064a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0627\u0637\u0650\u0628\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u063a\u0652\u0631\u064e\u0642\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0648\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0645\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0644\u064e\u0623\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0633\u064e\u062e\u0650\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0652 \u062a\u064e\u0633\u0652\u062e\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0652\u062e\u064e\u0631\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u062e\u064e\u0631\u064f\u0648\u0646\u064e",39,"\u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u064a\u064f\u062e\u0652\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0642\u0650\u064a\u0645\u064c",40,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0641\u064e\u0627\u0631\u064e \u0627\u0644\u062a\u0651\u064e\u0646\u0651\u064f\u0648\u0631\u064f \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u062d\u0652\u0645\u0650\u0644\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064d \u0632\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0633\u064e\u0628\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c",41,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0631\u0652\u0643\u064e\u0628\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062c\u0652\u0631\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0645\u064f\u0631\u0652\u0633\u064e\u0627\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",42,"\u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0648\u0652\u062c\u064d \u0643\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064c \u0627\u0628\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0639\u0652\u0632\u0650\u0644\u064d \u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0627\u0631\u0652\u0643\u064e\u0628\u0652 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",43,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0622\u0648\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0628\u064e\u0644\u064d \u064a\u064e\u0639\u0652\u0635\u0650\u0645\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u0639\u064e\u0627\u0635\u0650\u0645\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0631\u064e\u062d\u0650\u0645\u064e \u06da \u0648\u064e\u062d\u064e\u0627\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062c\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u063a\u0652\u0631\u064e\u0642\u0650\u064a\u0646\u064e",44,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u0631\u0652\u0636\u064f \u0627\u0628\u0652\u0644\u064e\u0639\u0650\u064a \u0645\u064e\u0627\u0621\u064e\u0643\u0650 \u0648\u064e\u064a\u064e\u0627 \u0633\u064e\u0645\u064e\u0627\u0621\u064f \u0623\u064e\u0642\u0652\u0644\u0650\u0639\u0650\u064a \u0648\u064e\u063a\u0650\u064a\u0636\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0648\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064f\u0648\u062f\u0650\u064a\u0651\u0650 \u06d6 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064c \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0627\u0628\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u064a \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0623\u064e\u062d\u0652\u0643\u064e\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0627\u0643\u0650\u0645\u0650\u064a\u0646\u064e",46,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0646\u064f\u0648\u062d\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u064a\u0652\u0633\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0635\u064e\u0627\u0644\u0650\u062d\u064d \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u0652\u0646\u0650 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0650\u0638\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",47,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064e\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06d6 \u0648\u064e\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u062a\u064e\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u0650\u064a \u0623\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",48,"\u0642\u0650\u064a\u0644\u064e \u064a\u064e\u0627 \u0646\u064f\u0648\u062d\u064f \u0627\u0647\u0652\u0628\u0650\u0637\u0652 \u0628\u0650\u0633\u064e\u0644\u064e\u0627\u0645\u064d \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0627\u062a\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u064e\u0645\u064d \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u06da \u0648\u064e\u0623\u064f\u0645\u064e\u0645\u064c \u0633\u064e\u0646\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",49,"\u062a\u0650\u0644\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",50,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064d \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0647\u064f\u0648\u062f\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",51,"\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",52,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u062f\u0652\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u064a\u064e\u0632\u0650\u062f\u0652\u0643\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064f\u0648\u0651\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",53,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0647\u064f\u0648\u062f\u064f \u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u062a\u064e\u0627\u0631\u0650\u0643\u0650\u064a \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",54,"\u0625\u0650\u0646\u0652 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0639\u0652\u062a\u064e\u0631\u064e\u0627\u0643\u064e \u0628\u064e\u0639\u0652\u0636\u064f \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0621\u064d \u06d7 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0634\u0652\u0647\u0650\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",55,"\u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650\u064a \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0638\u0650\u0631\u064f\u0648\u0646\u0650",56,"\u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06da \u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0622\u062e\u0650\u0630\u064c \u0628\u0650\u0646\u064e\u0627\u0635\u0650\u064a\u064e\u062a\u0650\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",57,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0628\u0652\u0644\u064e\u063a\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f \u0628\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u0650\u0641\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u064c",58,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0647\u064f\u0648\u062f\u064b\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u064d",59,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0639\u064e\u0627\u062f\u064c \u06d6 \u062c\u064e\u062d\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u0635\u064e\u0648\u0652\u0627 \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u064d",60,"\u0648\u064e\u0623\u064f\u062a\u0652\u0628\u0650\u0639\u064f\u0648\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064b \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0627\u062f\u064b\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u0639\u064e\u0627\u062f\u064d \u0642\u064e\u0648\u0652\u0645\u0650 \u0647\u064f\u0648\u062f\u064d",61,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0652\u0645\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0628\u064c \u0645\u064f\u062c\u0650\u064a\u0628\u064c",62,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064f \u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0645\u064e\u0631\u0652\u062c\u064f\u0648\u0651\u064b\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0623\u064e\u062a\u064e\u0646\u0652\u0647\u064e\u0627\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064f\u0631\u0650\u064a\u0628\u064d",63,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0622\u062a\u064e\u0627\u0646\u0650\u064a \u0645\u0650\u0646\u0652\u0647\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064f\u0647\u064f \u06d6 \u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0632\u0650\u064a\u062f\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u063a\u064e\u064a\u0652\u0631\u064e \u062a\u064e\u062e\u0652\u0633\u0650\u064a\u0631\u064d",64,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064b \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u0652 \u0641\u0650\u064a \u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0621\u064d \u0641\u064e\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0642\u064e\u0631\u0650\u064a\u0628\u064c",65,"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0639\u0652\u062f\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0643\u0652\u0630\u064f\u0648\u0628\u064d",66,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u0650\u0632\u0652\u064a\u0650 \u064a\u064e\u0648\u0652\u0645\u0650\u0626\u0650\u0630\u064d \u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f",67,"\u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0627\u062b\u0650\u0645\u0650\u064a\u0646\u064e",68,"\u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u063a\u0652\u0646\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u062b\u064e\u0645\u064f\u0648\u062f\u064e",69,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064e \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0639\u0650\u062c\u0652\u0644\u064d \u062d\u064e\u0646\u0650\u064a\u0630\u064d",70,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0649\u0670 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0646\u064e\u0643\u0650\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u062c\u064e\u0633\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062e\u0650\u064a\u0641\u064e\u0629\u064b \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064f\u0648\u0637\u064d",71,"\u0648\u064e\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f\u0647\u064f \u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064c \u0641\u064e\u0636\u064e\u062d\u0650\u0643\u064e\u062a\u0652 \u0641\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e",72,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u062a\u064e\u0649\u0670 \u0623\u064e\u0623\u064e\u0644\u0650\u062f\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u064c \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0639\u0652\u0644\u0650\u064a \u0634\u064e\u064a\u0652\u062e\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u0652\u0621\u064c \u0639\u064e\u062c\u0650\u064a\u0628\u064c",73,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062a\u064e\u0639\u0652\u062c\u064e\u0628\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0627\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u0650\u064a\u062f\u064c",74,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064e \u0639\u064e\u0646\u0652 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0627\u0644\u0631\u0651\u064e\u0648\u0652\u0639\u064f \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064f\u0648\u0637\u064d",75,"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u062d\u064e\u0644\u0650\u064a\u0645\u064c \u0623\u064e\u0648\u0651\u064e\u0627\u0647\u064c \u0645\u064f\u0646\u0650\u064a\u0628\u064c",76,"\u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0622\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0631\u0652\u062f\u064f\u0648\u062f\u064d",77,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064f\u0648\u0637\u064b\u0627 \u0633\u0650\u064a\u0621\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0636\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0630\u064e\u0631\u0652\u0639\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064c \u0639\u064e\u0635\u0650\u064a\u0628\u064c",78,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u064a\u064f\u0647\u0652\u0631\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u064a \u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0637\u0652\u0647\u064e\u0631\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0632\u064f\u0648\u0646\u0650 \u0641\u0650\u064a \u0636\u064e\u064a\u0652\u0641\u0650\u064a \u06d6 \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0631\u064e\u062c\u064f\u0644\u064c \u0631\u064e\u0634\u0650\u064a\u062f\u064c",79,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u0642\u0651\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u062f\u064f",80,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u064a \u0628\u0650\u0643\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0622\u0648\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064f\u0643\u0652\u0646\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d",81,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0644\u064f\u0648\u0637\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646\u0652 \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0641\u064e\u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u0650\u0637\u0652\u0639\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u0652\u062a\u064e\u0641\u0650\u062a\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064f\u0628\u0652\u062d\u064f \u06da \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0635\u0651\u064f\u0628\u0652\u062d\u064f \u0628\u0650\u0642\u064e\u0631\u0650\u064a\u0628\u064d",82,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0641\u0650\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u0652\u0637\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u064d \u0645\u064e\u0646\u0652\u0636\u064f\u0648\u062f\u064d",83,"\u0645\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u0650\u064a\u062f\u064d",84,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0642\u064f\u0635\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u0650\u0643\u0652\u064a\u064e\u0627\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u064f\u062d\u0650\u064a\u0637\u064d",85,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u0650\u0643\u0652\u064a\u064e\u0627\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062e\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",86,"\u0628\u064e\u0642\u0650\u064a\u0651\u064e\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u062d\u064e\u0641\u0650\u064a\u0638\u064d",87,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064f \u0623\u064e\u0635\u064e\u0644\u064e\u0627\u062a\u064f\u0643\u064e \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u0646\u064e\u062a\u0652\u0631\u064f\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0639\u064e\u0644\u064e \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u062d\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0634\u0650\u064a\u062f\u064f",88,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u0652\u0647\u064f \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0623\u064f\u062e\u064e\u0627\u0644\u0650\u0641\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u06da \u0625\u0650\u0646\u0652 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0635\u0652\u0644\u064e\u0627\u062d\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0648\u0652\u0641\u0650\u064a\u0642\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064f\u0646\u0650\u064a\u0628\u064f",89,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0627 \u064a\u064e\u062c\u0652\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0634\u0650\u0642\u064e\u0627\u0642\u0650\u064a \u0623\u064e\u0646\u0652 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064f \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0648\u062d\u064d \u0623\u064e\u0648\u0652 \u0642\u064e\u0648\u0652\u0645\u064e \u0647\u064f\u0648\u062f\u064d \u0623\u064e\u0648\u0652 \u0642\u064e\u0648\u0652\u0645\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064d \u06da \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0650\u064a\u062f\u064d",90,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0631\u064e\u062d\u0650\u064a\u0645\u064c \u0648\u064e\u062f\u064f\u0648\u062f\u064c",91,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064f \u0645\u064e\u0627 \u0646\u064e\u0641\u0652\u0642\u064e\u0647\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0631\u064e\u0647\u0652\u0637\u064f\u0643\u064e \u0644\u064e\u0631\u064e\u062c\u064e\u0645\u0652\u0646\u064e\u0627\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u064d",92,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0631\u064e\u0647\u0652\u0637\u0650\u064a \u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0631\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0638\u0650\u0647\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u064c",93,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0627\u0645\u0650\u0644\u064c \u06d6 \u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u064a\u064f\u062e\u0652\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0643\u064e\u0627\u0630\u0650\u0628\u064c \u06d6 \u0648\u064e\u0627\u0631\u0652\u062a\u064e\u0642\u0650\u0628\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0642\u0650\u064a\u0628\u064c",94,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0627\u062b\u0650\u0645\u0650\u064a\u0646\u064e",95,"\u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u063a\u0652\u0646\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0639\u0650\u062f\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f",96,u.bN,97,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0631\u064e\u0634\u0650\u064a\u062f\u064d",98,"\u064a\u064e\u0642\u0652\u062f\u064f\u0645\u064f \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0648\u0650\u0631\u0652\u062f\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0631\u064f\u0648\u062f\u064f",99,"\u0648\u064e\u0623\u064f\u062a\u0652\u0628\u0650\u0639\u064f\u0648\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064b \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0631\u0651\u0650\u0641\u0652\u062f\u064f \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0641\u064f\u0648\u062f\u064f",100,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0646\u064e\u0642\u064f\u0635\u0651\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0642\u064e\u0627\u0626\u0650\u0645\u064c \u0648\u064e\u062d\u064e\u0635\u0650\u064a\u062f\u064c",101,"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u062a\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0622\u0644\u0650\u0647\u064e\u062a\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u062a\u064e\u062a\u0652\u0628\u0650\u064a\u0628\u064d",102,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062e\u0652\u0630\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064c \u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062e\u0652\u0630\u064e\u0647\u064f \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c",103,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0627\u0641\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0645\u064e\u062c\u0652\u0645\u064f\u0648\u0639\u064c \u0644\u064e\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0645\u064e\u0634\u0652\u0647\u064f\u0648\u062f\u064c",104,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064d",105,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u0650 \u0644\u064e\u0627 \u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06da \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0634\u064e\u0642\u0650\u064a\u0651\u064c \u0648\u064e\u0633\u064e\u0639\u0650\u064a\u062f\u064c",106,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0634\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0641\u0650\u064a\u0631\u064c \u0648\u064e\u0634\u064e\u0647\u0650\u064a\u0642\u064c",107,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u064e\u0639\u0651\u064e\u0627\u0644\u064c \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",108,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064f\u0639\u0650\u062f\u064f\u0648\u0627 \u0641\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u06d6 \u0639\u064e\u0637\u064e\u0627\u0621\u064b \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u062c\u0652\u0630\u064f\u0648\u0630\u064d",109,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u06da \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0648\u064e\u0641\u0651\u064f\u0648\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0646\u0652\u0642\u064f\u0648\u0635\u064d",110,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0641\u064e\u0627\u062e\u0652\u062a\u064f\u0644\u0650\u0641\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u064d",111,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064f\u0644\u0651\u064b\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0644\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",112,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0642\u0650\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u0652\u063a\u064e\u0648\u0652\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",113,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u0643\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",114,"\u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0637\u064e\u0631\u064e\u0641\u064e\u064a\u0650 \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0632\u064f\u0644\u064e\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u0650 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0630\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",115,"\u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",116,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064f\u0648\u0644\u064f\u0648 \u0628\u064e\u0642\u0650\u064a\u0651\u064e\u0629\u064d \u064a\u064e\u0646\u0652\u0647\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064f\u062a\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",117,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u0645\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",118,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u0650\u064a\u0646\u064e",119,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0631\u064e\u062d\u0650\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u06da \u0648\u064e\u0644\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",120,"\u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0645\u064e\u0627 \u0646\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064f \u0628\u0650\u0647\u0650 \u0641\u064f\u0624\u064e\u0627\u062f\u064e\u0643\u064e \u06da \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064c \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",121,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0627\u0645\u0650\u0644\u064f\u0648\u0646\u064e",122,"\u0648\u064e\u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e",123,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0628\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0652\u0647\u064f \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e"],t.v)
B.asA=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",2,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",3,"\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",4,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f \u0623\u064e\u062d\u064e\u062f\u064e \u0639\u064e\u0634\u064e\u0631\u064e \u0643\u064e\u0648\u0652\u0643\u064e\u0628\u064b\u0627 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u064a \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",5,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0635\u064f\u0635\u0652 \u0631\u064f\u0624\u0652\u064a\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u062e\u0652\u0648\u064e\u062a\u0650\u0643\u064e \u0641\u064e\u064a\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0627 \u0644\u064e\u0643\u064e \u0643\u064e\u064a\u0652\u062f\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",6,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u0652\u062a\u064e\u0628\u0650\u064a\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650 \u0648\u064e\u064a\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u0644\u0650 \u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0645\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",7,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u062a\u0650\u0647\u0650 \u0622\u064a\u064e\u0627\u062a\u064c \u0644\u0650\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u0650\u064a\u0646\u064e",8,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0648\u064e\u0623\u064e\u062e\u064f\u0648\u0647\u064f \u0623\u064e\u062d\u064e\u0628\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0628\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0639\u064f\u0635\u0652\u0628\u064e\u0629\u064c \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",9,"\u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0623\u064e\u0648\u0650 \u0627\u0637\u0652\u0631\u064e\u062d\u064f\u0648\u0647\u064f \u0623\u064e\u0631\u0652\u0636\u064b\u0627 \u064a\u064e\u062e\u0652\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u0652\u0647\u064f \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",10,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0626\u0650\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u063a\u064e\u064a\u064e\u0627\u0628\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064f\u0628\u0651\u0650 \u064a\u064e\u0644\u0652\u062a\u064e\u0642\u0650\u0637\u0652\u0647\u064f \u0628\u064e\u0639\u0652\u0636\u064f \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",11,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0644\u064e\u0646\u064e\u0627\u0635\u0650\u062d\u064f\u0648\u0646\u064e",12,"\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652\u0647\u064f \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u063a\u064e\u062f\u064b\u0627 \u064a\u064e\u0631\u0652\u062a\u064e\u0639\u0652 \u0648\u064e\u064a\u064e\u0644\u0652\u0639\u064e\u0628\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",13,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u064a\u064e\u062d\u0652\u0632\u064f\u0646\u064f\u0646\u0650\u064a \u0623\u064e\u0646\u0652 \u062a\u064e\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064e\u0647\u064f \u0627\u0644\u0630\u0651\u0650\u0626\u0652\u0628\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",14,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0643\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0630\u0651\u0650\u0626\u0652\u0628\u064f \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0639\u064f\u0635\u0652\u0628\u064e\u0629\u064c \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",15,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u063a\u064e\u064a\u064e\u0627\u0628\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064f\u0628\u0651\u0650 \u06da \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",16,"\u0648\u064e\u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0623\u064e\u0628\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u0650\u0634\u064e\u0627\u0621\u064b \u064a\u064e\u0628\u0652\u0643\u064f\u0648\u0646\u064e",17,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0646\u064e\u0633\u0652\u062a\u064e\u0628\u0650\u0642\u064f \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0645\u064e\u062a\u064e\u0627\u0639\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0643\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0630\u0651\u0650\u0626\u0652\u0628\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064d \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",18,"\u0648\u064e\u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0645\u0650\u064a\u0635\u0650\u0647\u0650 \u0628\u0650\u062f\u064e\u0645\u064d \u0643\u064e\u0630\u0650\u0628\u064d \u06da \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0635\u064e\u0628\u0652\u0631\u064c \u062c\u064e\u0645\u0650\u064a\u0644\u064c \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0639\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0633\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u064c \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062f\u0652\u0644\u064e\u0649\u0670 \u062f\u064e\u0644\u0652\u0648\u064e\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u063a\u064f\u0644\u064e\u0627\u0645\u064c \u06da \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0647\u064f \u0628\u0650\u0636\u064e\u0627\u0639\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0634\u064e\u0631\u064e\u0648\u0652\u0647\u064f \u0628\u0650\u062b\u064e\u0645\u064e\u0646\u064d \u0628\u064e\u062e\u0652\u0633\u064d \u062f\u064e\u0631\u064e\u0627\u0647\u0650\u0645\u064e \u0645\u064e\u0639\u0652\u062f\u064f\u0648\u062f\u064e\u0629\u064d \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0634\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0645\u0650\u0635\u0652\u0631\u064e \u0644\u0650\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u0650\u0647\u0650 \u0623\u064e\u0643\u0652\u0631\u0650\u0645\u0650\u064a \u0645\u064e\u062b\u0652\u0648\u064e\u0627\u0647\u064f \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u0650\u0646\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0627\u0644\u0650\u0628\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",23,"\u0648\u064e\u0631\u064e\u0627\u0648\u064e\u062f\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0628\u064e\u064a\u0652\u062a\u0650\u0647\u064e\u0627 \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u063a\u064e\u0644\u0651\u064e\u0642\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0647\u064e\u064a\u0652\u062a\u064e \u0644\u064e\u0643\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0627\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u064e\u062b\u0652\u0648\u064e\u0627\u064a\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0647\u064e\u0645\u0651\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0647\u064e\u0645\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0631\u064e\u0623\u064e\u0649\u0670 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0646\u064e\u0635\u0652\u0631\u0650\u0641\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",25,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0628\u064e\u0642\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u062a\u0652 \u0642\u064e\u0645\u0650\u064a\u0635\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0628\u064f\u0631\u064d \u0648\u064e\u0623\u064e\u0644\u0652\u0641\u064e\u064a\u064e\u0627 \u0633\u064e\u064a\u0651\u0650\u062f\u064e\u0647\u064e\u0627 \u0644\u064e\u062f\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0627\u0628\u0650 \u06da \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u0633\u064f\u0648\u0621\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0633\u0652\u062c\u064e\u0646\u064e \u0623\u064e\u0648\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",26,"\u0642\u064e\u0627\u0644\u064e \u0647\u0650\u064a\u064e \u0631\u064e\u0627\u0648\u064e\u062f\u064e\u062a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u06da \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0645\u0650\u064a\u0635\u064f\u0647\u064f \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646\u0652 \u0642\u064f\u0628\u064f\u0644\u064d \u0641\u064e\u0635\u064e\u062f\u064e\u0642\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",27,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0645\u0650\u064a\u0635\u064f\u0647\u064f \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0628\u064f\u0631\u064d \u0641\u064e\u0643\u064e\u0630\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",28,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0649\u0670 \u0642\u064e\u0645\u0650\u064a\u0635\u064e\u0647\u064f \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0628\u064f\u0631\u064d \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0643\u064e\u064a\u0652\u062f\u0650\u0643\u064f\u0646\u0651\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u064e\u0643\u064f\u0646\u0651\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u064c",29,"\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0650\u064a \u0644\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0643\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u0650 \u0643\u064f\u0646\u0652\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0637\u0650\u0626\u0650\u064a\u0646\u064e",30,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0646\u0650\u0633\u0652\u0648\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u062a\u064f\u0631\u064e\u0627\u0648\u0650\u062f\u064f \u0641\u064e\u062a\u064e\u0627\u0647\u064e\u0627 \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0642\u064e\u062f\u0652 \u0634\u064e\u063a\u064e\u0641\u064e\u0647\u064e\u0627 \u062d\u064f\u0628\u0651\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0627\u0647\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",31,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064e\u062a\u0652 \u0628\u0650\u0645\u064e\u0643\u0652\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u062a\u0651\u064e\u0643\u064e\u0623\u064b \u0648\u064e\u0622\u062a\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064e \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u0633\u0650\u0643\u0651\u0650\u064a\u0646\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e \u062d\u064e\u0627\u0634\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",32,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064f\u0645\u0652\u062a\u064f\u0646\u0651\u064e\u0646\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0627\u0648\u064e\u062f\u0652\u062a\u064f\u0647\u064f \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0652\u0635\u064e\u0645\u064e \u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0645\u064e\u0627 \u0622\u0645\u064f\u0631\u064f\u0647\u064f \u0644\u064e\u064a\u064f\u0633\u0652\u062c\u064e\u0646\u064e\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u063a\u0650\u0631\u0650\u064a\u0646\u064e",33,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u064f \u0623\u064e\u062d\u064e\u0628\u0651\u064f \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0635\u0652\u0631\u0650\u0641\u0652 \u0639\u064e\u0646\u0651\u0650\u064a \u0643\u064e\u064a\u0652\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0635\u0652\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",34,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0641\u064e\u0635\u064e\u0631\u064e\u0641\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0643\u064e\u064a\u0652\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",35,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u064a\u064e\u0633\u0652\u062c\u064f\u0646\u064f\u0646\u0651\u064e\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",36,"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u064e \u0641\u064e\u062a\u064e\u064a\u064e\u0627\u0646\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0646\u0650\u064a \u0623\u064e\u0639\u0652\u0635\u0650\u0631\u064f \u062e\u064e\u0645\u0652\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0646\u0650\u064a \u0623\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0641\u064e\u0648\u0652\u0642\u064e \u0631\u064e\u0623\u0652\u0633\u0650\u064a \u062e\u064f\u0628\u0652\u0632\u064b\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u06d6 \u0646\u064e\u0628\u0651\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",37,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u064e\u0627 \u0637\u064e\u0639\u064e\u0627\u0645\u064c \u062a\u064f\u0631\u0652\u0632\u064e\u0642\u064e\u0627\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u0652\u062a\u064f\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650\u0647\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0642\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064f \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0622\u0628\u064e\u0627\u0626\u0650\u064a \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u06da \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",39,"\u064a\u064e\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u064a\u0650 \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u0650 \u0623\u064e\u0623\u064e\u0631\u0652\u0628\u064e\u0627\u0628\u064c \u0645\u064f\u062a\u064e\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",40,"\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064b \u0633\u064e\u0645\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u06da \u0625\u0650\u0646\u0650 \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064e\u0645\u064e\u0631\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",41,"\u064a\u064e\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u064a\u0650 \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u064e\u0627 \u0641\u064e\u064a\u064e\u0633\u0652\u0642\u0650\u064a \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u062e\u064e\u0645\u0652\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u064f \u0641\u064e\u064a\u064f\u0635\u0652\u0644\u064e\u0628\u064f \u0641\u064e\u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0623\u0652\u0633\u0650\u0647\u0650 \u06da \u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650\u064a\u064e\u0627\u0646\u0650",42,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0646\u064e\u0627\u062c\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0627\u0630\u0652\u0643\u064f\u0631\u0652\u0646\u0650\u064a \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0646\u0652\u0633\u064e\u0627\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0630\u0650\u0643\u0652\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u0650 \u0628\u0650\u0636\u0652\u0639\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",43,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0649\u0670 \u0633\u064e\u0628\u0652\u0639\u064e \u0628\u064e\u0642\u064e\u0631\u064e\u0627\u062a\u064d \u0633\u0650\u0645\u064e\u0627\u0646\u064d \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0652\u0639\u064c \u0639\u0650\u062c\u064e\u0627\u0641\u064c \u0648\u064e\u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064f\u0646\u0652\u0628\u064f\u0644\u064e\u0627\u062a\u064d \u062e\u064f\u0636\u0652\u0631\u064d \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064e \u064a\u064e\u0627\u0628\u0650\u0633\u064e\u0627\u062a\u064d \u06d6 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0623\u064e\u0641\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0641\u0650\u064a \u0631\u064f\u0624\u0652\u064a\u064e\u0627\u064a\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u0650\u0644\u0631\u0651\u064f\u0624\u0652\u064a\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u0631\u064f\u0648\u0646\u064e",44,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0636\u0652\u063a\u064e\u0627\u062b\u064f \u0623\u064e\u062d\u0652\u0644\u064e\u0627\u0645\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0644\u064e\u0627\u0645\u0650 \u0628\u0650\u0639\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u062c\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0627\u062f\u0651\u064e\u0643\u064e\u0631\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u064e\u0627 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650\u0647\u0650 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u064f\u0648\u0646\u0650",46,"\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u064f \u0623\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0652\u0639\u0650 \u0628\u064e\u0642\u064e\u0631\u064e\u0627\u062a\u064d \u0633\u0650\u0645\u064e\u0627\u0646\u064d \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0652\u0639\u064c \u0639\u0650\u062c\u064e\u0627\u0641\u064c \u0648\u064e\u0633\u064e\u0628\u0652\u0639\u0650 \u0633\u064f\u0646\u0652\u0628\u064f\u0644\u064e\u0627\u062a\u064d \u062e\u064f\u0636\u0652\u0631\u064d \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064e \u064a\u064e\u0627\u0628\u0650\u0633\u064e\u0627\u062a\u064d \u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0631\u0652\u062c\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",47,"\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0632\u0652\u0631\u064e\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u062f\u064e\u0623\u064e\u0628\u064b\u0627 \u0641\u064e\u0645\u064e\u0627 \u062d\u064e\u0635\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0633\u064f\u0646\u0652\u0628\u064f\u0644\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",48,"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u0652\u0639\u064c \u0634\u0650\u062f\u064e\u0627\u062f\u064c \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u0652\u0646\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062d\u0652\u0635\u0650\u0646\u064f\u0648\u0646\u064e",49,"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0627\u0645\u064c \u0641\u0650\u064a\u0647\u0650 \u064a\u064f\u063a\u064e\u0627\u062b\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0639\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0626\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0642\u064e\u0627\u0644\u064e \u0627\u0631\u0652\u062c\u0650\u0639\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652\u0647\u064f \u0645\u064e\u0627 \u0628\u064e\u0627\u0644\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0642\u064e\u0637\u0651\u064e\u0639\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0643\u064e\u064a\u0652\u062f\u0650\u0647\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c",51,"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u062e\u064e\u0637\u0652\u0628\u064f\u0643\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u0652 \u0631\u064e\u0627\u0648\u064e\u062f\u0652\u062a\u064f\u0646\u0651\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0642\u064f\u0644\u0652\u0646\u064e \u062d\u064e\u0627\u0634\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0633\u064f\u0648\u0621\u064d \u06da \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0622\u0646\u064e \u062d\u064e\u0635\u0652\u062d\u064e\u0635\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0627\u0648\u064e\u062f\u0652\u062a\u064f\u0647\u064f \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",52,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0644\u064e\u0645\u0652 \u0623\u064e\u062e\u064f\u0646\u0652\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0643\u064e\u064a\u0652\u062f\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0626\u0650\u0646\u0650\u064a\u0646\u064e",53,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0628\u064e\u0631\u0651\u0650\u0626\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0644\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0631\u064e\u0629\u064c \u0628\u0650\u0627\u0644\u0633\u0651\u064f\u0648\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0631\u064e\u062d\u0650\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",54,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0626\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650 \u0623\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u0650\u0635\u0652\u0647\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u064a \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0643\u0650\u064a\u0646\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",55,"\u0642\u064e\u0627\u0644\u064e \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062d\u064e\u0641\u0650\u064a\u0638\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",56,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0646\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0625\u0650\u062e\u0652\u0648\u064e\u0629\u064f \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u064e\u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0639\u064e\u0631\u064e\u0641\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0645\u064f\u0646\u0652\u0643\u0650\u0631\u064f\u0648\u0646\u064e",59,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0647\u0651\u064e\u0632\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0632\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0626\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u062e\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u0652 \u06da \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0623\u064f\u0648\u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0632\u0650\u0644\u0650\u064a\u0646\u064e",60,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u064a\u0652\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u0650",61,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0646\u064f\u0631\u064e\u0627\u0648\u0650\u062f\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u0628\u064e\u0627\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u064e\u0627\u0639\u0650\u0644\u064f\u0648\u0646\u064e",62,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0641\u0650\u062a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0628\u0650\u0636\u064e\u0627\u0639\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u0650\u062d\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",63,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0628\u0650\u064a\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064f\u0646\u0650\u0639\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064f \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u064e\u0627\u0646\u064e\u0627 \u0646\u064e\u0643\u0652\u062a\u064e\u0644\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",64,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u0622\u0645\u064e\u0646\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u062d\u064e\u0627\u0641\u0650\u0638\u064b\u0627 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",65,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u064f\u0648\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0636\u064e\u0627\u0639\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0631\u064f\u062f\u0651\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0628\u0652\u063a\u0650\u064a \u06d6 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0628\u0650\u0636\u064e\u0627\u0639\u064e\u062a\u064f\u0646\u064e\u0627 \u0631\u064f\u062f\u0651\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0646\u064e\u0645\u0650\u064a\u0631\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u0652\u0641\u064e\u0638\u064f \u0623\u064e\u062e\u064e\u0627\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0632\u0652\u062f\u064e\u0627\u062f\u064f \u0643\u064e\u064a\u0652\u0644\u064e \u0628\u064e\u0639\u0650\u064a\u0631\u064d \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0633\u0650\u064a\u0631\u064c",66,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0646\u0652 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u0650 \u0645\u064e\u0648\u0652\u062b\u0650\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u0648\u0652\u0647\u064f \u0645\u064e\u0648\u0652\u062b\u0650\u0642\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u064c",67,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0627\u0628\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0648\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064d \u0645\u064f\u062a\u064e\u0641\u064e\u0631\u0651\u0650\u0642\u064e\u0629\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0625\u0650\u0646\u0650 \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u06d6 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u0627\u062c\u064e\u0629\u064b \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650 \u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0642\u064e\u0636\u064e\u0627\u0647\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u064f\u0648 \u0639\u0650\u0644\u0652\u0645\u064d \u0644\u0650\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",69,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0622\u0648\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u064f\u0648\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062a\u064e\u0626\u0650\u0633\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",70,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0647\u0651\u064e\u0632\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0632\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u0650\u0642\u064e\u0627\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0644\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0645\u064f\u0624\u064e\u0630\u0651\u0650\u0646\u064c \u0623\u064e\u064a\u0651\u064e\u062a\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u064a\u0631\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0633\u064e\u0627\u0631\u0650\u0642\u064f\u0648\u0646\u064e",71,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0641\u0652\u0642\u0650\u062f\u064f\u0648\u0646\u064e",72,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0641\u0652\u0642\u0650\u062f\u064f \u0635\u064f\u0648\u064e\u0627\u0639\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u0650 \u0648\u064e\u0644\u0650\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0647\u0650 \u062d\u0650\u0645\u0652\u0644\u064f \u0628\u064e\u0639\u0650\u064a\u0631\u064d \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0632\u064e\u0639\u0650\u064a\u0645\u064c",73,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0644\u0650\u0646\u064f\u0641\u0652\u0633\u0650\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0633\u064e\u0627\u0631\u0650\u0642\u0650\u064a\u0646\u064e",74,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",75,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f \u0645\u064e\u0646\u0652 \u0648\u064f\u062c\u0650\u062f\u064e \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0644\u0650\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",76,"\u0641\u064e\u0628\u064e\u062f\u064e\u0623\u064e \u0628\u0650\u0623\u064e\u0648\u0652\u0639\u0650\u064a\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0628\u0652\u0644\u064e \u0648\u0650\u0639\u064e\u0627\u0621\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0648\u0650\u0639\u064e\u0627\u0621\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u0650\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u06d6 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0646\u064e\u0631\u0652\u0641\u064e\u0639\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0641\u064e\u0648\u0652\u0642\u064e \u0643\u064f\u0644\u0651\u0650 \u0630\u0650\u064a \u0639\u0650\u0644\u0652\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",77,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u064a\u064e\u0633\u0652\u0631\u0650\u0642\u0652 \u0641\u064e\u0642\u064e\u062f\u0652 \u0633\u064e\u0631\u064e\u0642\u064e \u0623\u064e\u062e\u064c \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0641\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064e\u0647\u064e\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0628\u0652\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0634\u064e\u0631\u0651\u064c \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",78,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0628\u064b\u0627 \u0634\u064e\u064a\u0652\u062e\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0641\u064e\u062e\u064f\u0630\u0652 \u0623\u064e\u062d\u064e\u062f\u064e\u0646\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0631\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",79,"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0627\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u0623\u0652\u062e\u064f\u0630\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064e\u0646\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",80,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u064a\u0652\u0623\u064e\u0633\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u062e\u064e\u0644\u064e\u0635\u064f\u0648\u0627 \u0646\u064e\u062c\u0650\u064a\u0651\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0628\u064e\u0627\u0643\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u062b\u0650\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u06d6 \u0641\u064e\u0644\u064e\u0646\u0652 \u0623\u064e\u0628\u0652\u0631\u064e\u062d\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u0630\u064e\u0646\u064e \u0644\u0650\u064a \u0623\u064e\u0628\u0650\u064a \u0623\u064e\u0648\u0652 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u062d\u064e\u0627\u0643\u0650\u0645\u0650\u064a\u0646\u064e",81,"\u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u0652 \u0641\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0628\u0652\u0646\u064e\u0643\u064e \u0633\u064e\u0631\u064e\u0642\u064e \u0648\u064e\u0645\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u062d\u064e\u0627\u0641\u0650\u0638\u0650\u064a\u0646\u064e",82,"\u0648\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0639\u0650\u064a\u0631\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0642\u0652\u0628\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",83,"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0635\u064e\u0628\u0652\u0631\u064c \u062c\u064e\u0645\u0650\u064a\u0644\u064c \u06d6 \u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",84,"\u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u0633\u064e\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0627\u0628\u0652\u064a\u064e\u0636\u0651\u064e\u062a\u0652 \u0639\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064f\u0632\u0652\u0646\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u064c",85,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0641\u0652\u062a\u064e\u0623\u064f \u062a\u064e\u0630\u0652\u0643\u064f\u0631\u064f \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062d\u064e\u0631\u064e\u0636\u064b\u0627 \u0623\u064e\u0648\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u0627\u0644\u0650\u0643\u0650\u064a\u0646\u064e",86,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0643\u064f\u0648 \u0628\u064e\u062b\u0651\u0650\u064a \u0648\u064e\u062d\u064f\u0632\u0652\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",87,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0627\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u062d\u064e\u0633\u0651\u064e\u0633\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u064a\u0652\u0623\u064e\u0633\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0648\u0652\u062d\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u064a\u0652\u0623\u064e\u0633\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0648\u0652\u062d\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",88,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0646\u064e\u0627 \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0648\u064e\u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u0628\u0650\u0636\u064e\u0627\u0639\u064e\u0629\u064d \u0645\u064f\u0632\u0652\u062c\u064e\u0627\u0629\u064d \u0641\u064e\u0623\u064e\u0648\u0652\u0641\u0650 \u0644\u064e\u0646\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e",89,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062c\u064e\u0627\u0647\u0650\u0644\u064f\u0648\u0646\u064e",90,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u062e\u0650\u064a \u06d6 \u0642\u064e\u062f\u0652 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0648\u064e\u064a\u064e\u0635\u0652\u0628\u0650\u0631\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",91,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062b\u064e\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u062e\u064e\u0627\u0637\u0650\u0626\u0650\u064a\u0646\u064e",92,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062b\u0652\u0631\u0650\u064a\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06d6 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",93,"\u0627\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0642\u064e\u0645\u0650\u064a\u0635\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650 \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",94,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u0635\u064e\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0639\u0650\u064a\u0631\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0650\u062f\u064f \u0631\u0650\u064a\u062d\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u06d6 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0641\u064e\u0646\u0651\u0650\u062f\u064f\u0648\u0646\u0650",95,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064e\u062f\u0650\u064a\u0645\u0650",96,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u0628\u064e\u0634\u0650\u064a\u0631\u064f \u0623\u064e\u0644\u0652\u0642\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u0641\u064e\u0627\u0631\u0652\u062a\u064e\u062f\u0651\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",97,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062e\u064e\u0627\u0637\u0650\u0626\u0650\u064a\u0646\u064e",98,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0648\u0652\u0641\u064e \u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",99,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0622\u0648\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0635\u0652\u0631\u064e \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",100,"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0648\u064e\u062e\u064e\u0631\u0651\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064f \u0631\u064f\u0624\u0652\u064a\u064e\u0627\u064a\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u0642\u0651\u064b\u0627 \u06d6 \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0628\u0650\u064a \u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u0650\u062c\u0652\u0646\u0650 \u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u062f\u0652\u0648\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u0632\u064e\u063a\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0625\u0650\u062e\u0652\u0648\u064e\u062a\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u0644\u0650\u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",101,"\u0631\u064e\u0628\u0651\u0650 \u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650 \u06da \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u0650\u064a \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u0644\u0652\u062d\u0650\u0642\u0652\u0646\u0650\u064a \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",102,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",103,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u062d\u064e\u0631\u064e\u0635\u0652\u062a\u064e \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",104,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06da \u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",105,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u0645\u064f\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",106,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",107,"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u063a\u064e\u0627\u0634\u0650\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",108,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0623\u064e\u062f\u0652\u0639\u064f\u0648 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u0629\u064d \u0623\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0646\u0650\u064a \u06d6 \u0648\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",109,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0646\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0644\u064e\u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",110,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u064a\u0652\u0623\u064e\u0633\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u062f\u0652 \u0643\u064f\u0630\u0650\u0628\u064f\u0648\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0635\u0652\u0631\u064f\u0646\u064e\u0627 \u0641\u064e\u0646\u064f\u062c\u0651\u0650\u064a\u064e \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u0652\u0633\u064f\u0646\u064e\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",111,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0642\u064e\u0635\u064e\u0635\u0650\u0647\u0650\u0645\u0652 \u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064c \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650 \u06d7 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064b\u0627 \u064a\u064f\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062a\u064e\u0635\u0652\u062f\u0650\u064a\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u062a\u064e\u0641\u0652\u0635\u0650\u064a\u0644\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e"],t.v)
B.apg=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0645\u0631 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",2,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0631\u064e\u0641\u064e\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u064e\u0645\u064e\u062f\u064d \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u06d6 \u0643\u064f\u0644\u0651\u064c \u064a\u064e\u062c\u0652\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u064a\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u062a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",3,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u062f\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u06d6 \u064a\u064f\u063a\u0652\u0634\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0642\u0650\u0637\u064e\u0639\u064c \u0645\u064f\u062a\u064e\u062c\u064e\u0627\u0648\u0650\u0631\u064e\u0627\u062a\u064c \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u0648\u064e\u0632\u064e\u0631\u0652\u0639\u064c \u0648\u064e\u0646\u064e\u062e\u0650\u064a\u0644\u064c \u0635\u0650\u0646\u0652\u0648\u064e\u0627\u0646\u064c \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064f \u0635\u0650\u0646\u0652\u0648\u064e\u0627\u0646\u064d \u064a\u064f\u0633\u0652\u0642\u064e\u0649\u0670 \u0628\u0650\u0645\u064e\u0627\u0621\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0648\u064e\u0646\u064f\u0641\u064e\u0636\u0651\u0650\u0644\u064f \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064f\u0643\u064f\u0644\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",5,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u0652\u062c\u064e\u0628\u0652 \u0641\u064e\u0639\u064e\u062c\u064e\u0628\u064c \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d \u06d7 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064f \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",6,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u062b\u064f\u0644\u064e\u0627\u062a\u064f \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0644\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",7,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064c \u06d6 \u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0648\u0652\u0645\u064d \u0647\u064e\u0627\u062f\u064d",8,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u063a\u0650\u064a\u0636\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064f \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0632\u0652\u062f\u064e\u0627\u062f\u064f \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0628\u0650\u0645\u0650\u0642\u0652\u062f\u064e\u0627\u0631\u064d",9,"\u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0639\u064e\u0627\u0644\u0650",10,"\u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u064e\u0631\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0647\u064e\u0631\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u0652\u062a\u064e\u062e\u0652\u0641\u064d \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0633\u064e\u0627\u0631\u0650\u0628\u064c \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650",11,"\u0644\u064e\u0647\u064f \u0645\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u064e\u0627\u062a\u064c \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650 \u064a\u064e\u062d\u0652\u0641\u064e\u0638\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f \u0645\u064e\u0627 \u0628\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u0633\u064f\u0648\u0621\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0627\u0644\u064d",12,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0652\u0642\u064e \u062e\u064e\u0648\u0652\u0641\u064b\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u064b\u0627 \u0648\u064e\u064a\u064f\u0646\u0652\u0634\u0650\u0626\u064f \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u062b\u0651\u0650\u0642\u064e\u0627\u0644\u064e",13,"\u0648\u064e\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0627\u0644\u0631\u0651\u064e\u0639\u0652\u062f\u064f \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0645\u0650\u0646\u0652 \u062e\u0650\u064a\u0641\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0635\u0651\u064e\u0648\u064e\u0627\u0639\u0650\u0642\u064e \u0641\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0645\u0650\u062d\u064e\u0627\u0644\u0650",14,"\u0644\u064e\u0647\u064f \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0628\u064e\u0627\u0633\u0650\u0637\u0650 \u0643\u064e\u0641\u0651\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0641\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0628\u064e\u0627\u0644\u0650\u063a\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d",15,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0637\u064e\u0648\u0652\u0639\u064b\u0627 \u0648\u064e\u0643\u064e\u0631\u0652\u0647\u064b\u0627 \u0648\u064e\u0638\u0650\u0644\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0622\u0635\u064e\u0627\u0644\u0650 \u06e9",16,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u064b\u0627 \u06da \u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f \u0623\u064e\u0645\u0652 \u0647\u064e\u0644\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0648\u0631\u064f \u06d7 \u0623\u064e\u0645\u0652 \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627 \u0643\u064e\u062e\u064e\u0644\u0652\u0642\u0650\u0647\u0650 \u0641\u064e\u062a\u064e\u0634\u064e\u0627\u0628\u064e\u0647\u064e \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",17,"\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0633\u064e\u0627\u0644\u064e\u062a\u0652 \u0623\u064e\u0648\u0652\u062f\u0650\u064a\u064e\u0629\u064c \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0650\u0647\u064e\u0627 \u0641\u064e\u0627\u062d\u0652\u062a\u064e\u0645\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0652\u0644\u064f \u0632\u064e\u0628\u064e\u062f\u064b\u0627 \u0631\u064e\u0627\u0628\u0650\u064a\u064b\u0627 \u06da \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u062d\u0650\u0644\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0645\u064e\u062a\u064e\u0627\u0639\u064d \u0632\u064e\u0628\u064e\u062f\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064f \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0632\u0651\u064e\u0628\u064e\u062f\u064f \u0641\u064e\u064a\u064e\u0630\u0652\u0647\u064e\u0628\u064f \u062c\u064f\u0641\u064e\u0627\u0621\u064b \u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u064e\u064a\u064e\u0645\u0652\u0643\u064f\u062b\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e",18,"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0647\u064f \u0644\u064e\u0627\u0641\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",19,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0643\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",20,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e",21,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",22,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0648\u064e\u062c\u0652\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u0631\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0648\u064e\u064a\u064e\u062f\u0652\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064f\u0642\u0652\u0628\u064e\u0649 \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",23,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0652 \u0635\u064e\u0644\u064e\u062d\u064e \u0645\u0650\u0646\u0652 \u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0628\u064e\u0627\u0628\u064d",24,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u06da \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0639\u064f\u0642\u0652\u0628\u064e\u0649 \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",25,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u0652\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d9 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",26,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06da \u0648\u064e\u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064c",27,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u064e\u0627\u0628\u064e",28,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u0650\u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064f \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f",29,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0637\u064f\u0648\u0628\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u064f \u0645\u064e\u0622\u0628\u064d",30,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0641\u0650\u064a \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u064e\u0627 \u0623\u064f\u0645\u064e\u0645\u064c \u0644\u0650\u062a\u064e\u062a\u0652\u0644\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u06da \u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u062a\u064e\u0627\u0628\u0650",31,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0623\u064e\u0648\u0652 \u0642\u064f\u0637\u0651\u0650\u0639\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0623\u064e\u0648\u0652 \u0643\u064f\u0644\u0651\u0650\u0645\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u06d7 \u0628\u064e\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u064a\u0652\u0623\u064e\u0633\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0648\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064e\u062f\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064c \u0623\u064e\u0648\u0652 \u062a\u064e\u062d\u064f\u0644\u0651\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",32,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0627\u0633\u0652\u062a\u064f\u0647\u0652\u0632\u0650\u0626\u064e \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u064a\u0652\u062a\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",33,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0641\u0652\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u06d7 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u0642\u064f\u0644\u0652 \u0633\u064e\u0645\u0651\u064f\u0648\u0647\u064f\u0645\u0652 \u06da \u0623\u064e\u0645\u0652 \u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0648\u0646\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0652 \u0628\u0650\u0638\u064e\u0627\u0647\u0650\u0631\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u06d7 \u0628\u064e\u0644\u0652 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u064e\u0643\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0647\u064e\u0627\u062f\u064d",34,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0634\u064e\u0642\u0651\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0627\u0642\u064d",35,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06d6 \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0623\u064f\u0643\u064f\u0644\u064f\u0647\u064e\u0627 \u062f\u064e\u0627\u0626\u0650\u0645\u064c \u0648\u064e\u0638\u0650\u0644\u0651\u064f\u0647\u064e\u0627 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0639\u064f\u0642\u0652\u0628\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u06d6 \u0648\u064e\u0639\u064f\u0642\u0652\u0628\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f",36,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u0646\u0652\u0643\u0650\u0631\u064f \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f \u06da \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650 \u06da \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062f\u0652\u0639\u064f\u0648 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0622\u0628\u0650",37,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0627\u0642\u064d",38,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064b \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u062c\u064e\u0644\u064d \u0643\u0650\u062a\u064e\u0627\u0628\u064c",39,"\u064a\u064e\u0645\u0652\u062d\u064f\u0648 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064f\u062b\u0652\u0628\u0650\u062a\u064f \u06d6 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0623\u064f\u0645\u0651\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650",40,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u064f",41,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0623\u0652\u062a\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0646\u064e\u0646\u0652\u0642\u064f\u0635\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0637\u0652\u0631\u064e\u0627\u0641\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0644\u064e\u0627 \u0645\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u064e \u0644\u0650\u062d\u064f\u0643\u0652\u0645\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",42,"\u0648\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0643\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0643\u0652\u0631\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u0639\u064f\u0642\u0652\u0628\u064e\u0649 \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",43,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0633\u0652\u062a\u064e \u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064b\u0627 \u06da \u0642\u064f\u0644\u0652 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u0650\u0644\u0652\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650"],t.v)
B.abZ=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631 \u06da \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0644\u0650\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u0650",2,"\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",4,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",5,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652 \u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0634\u064e\u0643\u064f\u0648\u0631\u064d",6,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0644\u064e\u0627\u0621\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c",7,"\u0648\u064e\u0625\u0650\u0630\u0652 \u062a\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0626\u0650\u0646\u0652 \u0634\u064e\u0643\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0623\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064c",8,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",9,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u06db \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u06db \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0631\u064e\u062f\u0651\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064f\u0631\u0650\u064a\u0628\u064d",10,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0643\u0651\u064c \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e\u0627 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",11,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0645\u064f\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u064e\u0646\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0646\u064e\u0635\u0652\u0628\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0622\u0630\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627 \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u064f\u0647\u0652\u0644\u0650\u0643\u064e\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0646\u064f\u0633\u0652\u0643\u0650\u0646\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u062e\u064e\u0627\u0641\u064e \u0648\u064e\u0639\u0650\u064a\u062f\u0650",15,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u064e\u062d\u064f\u0648\u0627 \u0648\u064e\u062e\u064e\u0627\u0628\u064e \u0643\u064f\u0644\u0651\u064f \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u064d",16,"\u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0648\u064e\u064a\u064f\u0633\u0652\u0642\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u0635\u064e\u062f\u0650\u064a\u062f\u064d",17,"\u064a\u064e\u062a\u064e\u062c\u064e\u0631\u0651\u064e\u0639\u064f\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u064a\u064f\u0633\u0650\u064a\u063a\u064f\u0647\u064f \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0645\u064e\u064a\u0651\u0650\u062a\u064d \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u063a\u064e\u0644\u0650\u064a\u0638\u064c",18,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0631\u064e\u0645\u064e\u0627\u062f\u064d \u0627\u0634\u0652\u062a\u064e\u062f\u0651\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064f \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0627\u0635\u0650\u0641\u064d \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064f \u0627\u0644\u0652\u0628\u064e\u0639\u0650\u064a\u062f\u064f",19,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d",20,"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u064d",21,"\u0648\u064e\u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0627\u0621\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0628\u064e\u0639\u064b\u0627 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u063a\u0652\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0647\u064e\u062f\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u062c\u064e\u0632\u0650\u0639\u0652\u0646\u064e\u0627 \u0623\u064e\u0645\u0652 \u0635\u064e\u0628\u064e\u0631\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u062d\u0650\u064a\u0635\u064d",22,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0639\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062e\u0652\u0644\u064e\u0641\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0644\u0650\u064a \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u064f\u0648\u0645\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0644\u064f\u0648\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0645\u064f\u0635\u0652\u0631\u0650\u062e\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0635\u0652\u0631\u0650\u062e\u0650\u064a\u0651\u064e \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",23,"\u0648\u064e\u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064c",24,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064b \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u0643\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064d \u0623\u064e\u0635\u0652\u0644\u064f\u0647\u064e\u0627 \u062b\u064e\u0627\u0628\u0650\u062a\u064c \u0648\u064e\u0641\u064e\u0631\u0652\u0639\u064f\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650",25,"\u062a\u064f\u0624\u0652\u062a\u0650\u064a \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u062d\u0650\u064a\u0646\u064d \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u06d7 \u0648\u064e\u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",26,"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064d \u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0629\u064d \u0643\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0629\u064d \u0627\u062c\u0652\u062a\u064f\u062b\u0651\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u064e\u0627\u0631\u064d",27,"\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0627\u0644\u062b\u0651\u064e\u0627\u0628\u0650\u062a\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u06da \u0648\u064e\u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f",28,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064f\u0641\u0652\u0631\u064b\u0627 \u0648\u064e\u0623\u064e\u062d\u064e\u0644\u0651\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0628\u064e\u0648\u064e\u0627\u0631\u0650",29,"\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u064e\u0627\u0631\u064f",30,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0635\u0650\u064a\u0631\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",31,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u0631\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u0628\u064e\u064a\u0652\u0639\u064c \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u0650\u0644\u064e\u0627\u0644\u064c",32,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0644\u0650\u062a\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064e",33,"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u062f\u064e\u0627\u0626\u0650\u0628\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e",34,"\u0648\u064e\u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u062d\u0652\u0635\u064f\u0648\u0647\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0638\u064e\u0644\u064f\u0648\u0645\u064c \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064c",35,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u062f\u064e \u0622\u0645\u0650\u0646\u064b\u0627 \u0648\u064e\u0627\u062c\u0652\u0646\u064f\u0628\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0623\u064e\u0646\u0652 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0652\u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064e",36,"\u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0636\u0652\u0644\u064e\u0644\u0652\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0635\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",37,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0643\u064e\u0646\u0652\u062a\u064f \u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a \u0628\u0650\u0648\u064e\u0627\u062f\u064d \u063a\u064e\u064a\u0652\u0631\u0650 \u0630\u0650\u064a \u0632\u064e\u0631\u0652\u0639\u064d \u0639\u0650\u0646\u0652\u062f\u064e \u0628\u064e\u064a\u0652\u062a\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0641\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062a\u064e\u0647\u0652\u0648\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0631\u0652\u0632\u064f\u0642\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",38,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0646\u064f\u062e\u0652\u0641\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0639\u0652\u0644\u0650\u0646\u064f \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650",39,"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0647\u064e\u0628\u064e \u0644\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u0650 \u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0633\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u0650",40,"\u0631\u064e\u0628\u0651\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0645\u064f\u0642\u0650\u064a\u0645\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a \u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u0652 \u062f\u064f\u0639\u064e\u0627\u0621\u0650",41,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u064f",42,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0627\u0641\u0650\u0644\u064b\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u064d \u062a\u064e\u0634\u0652\u062e\u064e\u0635\u064f \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f",43,"\u0645\u064f\u0647\u0652\u0637\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u064f\u0642\u0652\u0646\u0650\u0639\u0650\u064a \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062a\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0637\u064e\u0631\u0652\u0641\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0647\u064e\u0648\u064e\u0627\u0621\u064c",44,"\u0648\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u0651\u0650\u0631\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0642\u064e\u0631\u0650\u064a\u0628\u064d \u0646\u064f\u062c\u0650\u0628\u0652 \u062f\u064e\u0639\u0652\u0648\u064e\u062a\u064e\u0643\u064e \u0648\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u06d7 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0623\u064e\u0642\u0652\u0633\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0632\u064e\u0648\u064e\u0627\u0644\u064d",45,"\u0648\u064e\u0633\u064e\u0643\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0636\u064e\u0631\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e",46,"\u0648\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0645\u064e\u0643\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0643\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0643\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u062a\u064e\u0632\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f",47,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0641\u064e \u0648\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u0630\u064f\u0648 \u0627\u0646\u0652\u062a\u0650\u0642\u064e\u0627\u0645\u064d",48,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u0628\u064e\u062f\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u06d6 \u0648\u064e\u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u0650 \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u0650",49,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0635\u0652\u0641\u064e\u0627\u062f\u0650",50,"\u0633\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0644\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0637\u0650\u0631\u064e\u0627\u0646\u064d \u0648\u064e\u062a\u064e\u063a\u0652\u0634\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f",51,"\u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064f\u0644\u0651\u064e \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",52,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u0627\u063a\u064c \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u0646\u0652\u0630\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0648\u064e\u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650"],t.v)
B.aph=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",2,"\u0631\u064f\u0628\u064e\u0645\u064e\u0627 \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",3,"\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u064a\u064f\u0644\u0652\u0647\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u0644\u064f \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064c",5,u.bI,6,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",7,"\u0644\u064e\u0648\u0652 \u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",8,"\u0645\u064e\u0627 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064b\u0627 \u0645\u064f\u0646\u0652\u0638\u064e\u0631\u0650\u064a\u0646\u064e",9,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0634\u0650\u064a\u064e\u0639\u0650 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",12,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0633\u0652\u0644\u064f\u0643\u064f\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",13,"\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0633\u064f\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0638\u064e\u0644\u0651\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0639\u0652\u0631\u064f\u062c\u064f\u0648\u0646\u064e",15,"\u0644\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0633\u064f\u0643\u0651\u0650\u0631\u064e\u062a\u0652 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0646\u064e\u0627 \u0628\u064e\u0644\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064e\u0633\u0652\u062d\u064f\u0648\u0631\u064f\u0648\u0646\u064e",16,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u064f\u0631\u064f\u0648\u062c\u064b\u0627 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0638\u0650\u0631\u0650\u064a\u0646\u064e",17,"\u0648\u064e\u062d\u064e\u0641\u0650\u0638\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0631\u064e\u062c\u0650\u064a\u0645\u064d",18,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0631\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f \u0634\u0650\u0647\u064e\u0627\u0628\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",19,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064e\u0648\u0652\u0632\u064f\u0648\u0646\u064d",20,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0639\u064e\u0627\u064a\u0650\u0634\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0633\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",22,"\u0648\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0644\u064e\u0648\u064e\u0627\u0642\u0650\u062d\u064e \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u0633\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0628\u0650\u062e\u064e\u0627\u0632\u0650\u0646\u0650\u064a\u0646\u064e",23,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u0646\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0623\u0652\u062e\u0650\u0631\u0650\u064a\u0646\u064e",25,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",26,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0635\u064e\u0644\u0652\u0635\u064e\u0627\u0644\u064d \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u064e\u0625\u064d \u0645\u064e\u0633\u0652\u0646\u064f\u0648\u0646\u064d",27,"\u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0627\u0646\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064f\u0648\u0645\u0650",28,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0627\u0644\u0650\u0642\u064c \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0635\u064e\u0644\u0652\u0635\u064e\u0627\u0644\u064d \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u064e\u0625\u064d \u0645\u064e\u0633\u0652\u0646\u064f\u0648\u0646\u064d",29,u.ci,30,u.bu,31,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064f \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",33,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0645\u0652 \u0623\u064e\u0643\u064f\u0646\u0652 \u0644\u0650\u0623\u064e\u0633\u0652\u062c\u064f\u062f\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0635\u064e\u0644\u0652\u0635\u064e\u0627\u0644\u064d \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u064e\u0625\u064d \u0645\u064e\u0633\u0652\u0646\u064f\u0648\u0646\u064d",34,u.av,35,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0639\u0652\u0646\u064e\u0629\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",36,u.O,37,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0638\u064e\u0631\u0650\u064a\u0646\u064e",38,"\u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0648\u064e\u0642\u0652\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u0650",39,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064f\u0632\u064e\u064a\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0623\u064f\u063a\u0652\u0648\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",40,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",41,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",42,"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",43,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",44,"\u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0628\u0652\u0639\u064e\u0629\u064f \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064d \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0628\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062c\u064f\u0632\u0652\u0621\u064c \u0645\u064e\u0642\u0652\u0633\u064f\u0648\u0645\u064c",45,u.M,46,"\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064e\u0644\u064e\u0627\u0645\u064d \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",47,"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u063a\u0650\u0644\u0651\u064d \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u064d \u0645\u064f\u062a\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650\u064a\u0646\u064e",48,"\u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u064c \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u0645\u064f\u062e\u0652\u0631\u064e\u062c\u0650\u064a\u0646\u064e",49,"\u0646\u064e\u0628\u0651\u0650\u0626\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0623\u064e\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",50,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064f",51,"\u0648\u064e\u0646\u064e\u0628\u0651\u0650\u0626\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0636\u064e\u064a\u0652\u0641\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",52,"\u0625\u0650\u0630\u0652 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u0650\u0644\u064f\u0648\u0646\u064e",53,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0648\u0652\u062c\u064e\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u063a\u064f\u0644\u064e\u0627\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",54,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u064f \u0641\u064e\u0628\u0650\u0645\u064e \u062a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0648\u0646\u064e",55,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0634\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u0637\u0650\u064a\u0646\u064e",56,"\u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u0646\u064e\u0637\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u064f\u0648\u0646\u064e",57,u.as,58,u.d8,59,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0622\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u064e\u062c\u0651\u064f\u0648\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",60,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0642\u064e\u062f\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",61,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0622\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",62,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064f\u0648\u0646\u064e",63,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u062c\u0650\u0626\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0645\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",64,"\u0648\u064e\u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",65,"\u0641\u064e\u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u0650\u0637\u0652\u0639\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u0652\u062a\u064e\u0641\u0650\u062a\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064c \u0648\u064e\u0627\u0645\u0652\u0636\u064f\u0648\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u062a\u064f\u0624\u0652\u0645\u064e\u0631\u064f\u0648\u0646\u064e",66,"\u0648\u064e\u0642\u064e\u0636\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0645\u064e\u0642\u0652\u0637\u064f\u0648\u0639\u064c \u0645\u064f\u0635\u0652\u0628\u0650\u062d\u0650\u064a\u0646\u064e",67,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e",68,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0636\u064e\u064a\u0652\u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0636\u064e\u062d\u064f\u0648\u0646\u0650",69,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0632\u064f\u0648\u0646\u0650",70,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0646\u0652\u0647\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",71,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u064a \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",72,"\u0644\u064e\u0639\u064e\u0645\u0652\u0631\u064f\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u0633\u064e\u0643\u0652\u0631\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",73,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0645\u064f\u0634\u0652\u0631\u0650\u0642\u0650\u064a\u0646\u064e",74,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0641\u0650\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u0652\u0637\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u064d",75,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0633\u0651\u0650\u0645\u0650\u064a\u0646\u064e",76,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0628\u0650\u0633\u064e\u0628\u0650\u064a\u0644\u064d \u0645\u064f\u0642\u0650\u064a\u0645\u064d",77,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",78,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0643\u064e\u0629\u0650 \u0644\u064e\u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",79,"\u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0642\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u0625\u0650\u0645\u064e\u0627\u0645\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",80,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062d\u0650\u062c\u0652\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",81,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u0650\u064a\u0646\u064e",82,"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0646\u0652\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",83,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0645\u064f\u0635\u0652\u0628\u0650\u062d\u0650\u064a\u0646\u064e",84,"\u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0622\u062a\u0650\u064a\u064e\u0629\u064c \u06d6 \u0641\u064e\u0627\u0635\u0652\u0641\u064e\u062d\u0650 \u0627\u0644\u0635\u0651\u064e\u0641\u0652\u062d\u064e \u0627\u0644\u0652\u062c\u064e\u0645\u0650\u064a\u0644\u064e",86,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062e\u064e\u0644\u0651\u064e\u0627\u0642\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",87,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0633\u064e\u0628\u0652\u0639\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u062b\u064e\u0627\u0646\u0650\u064a \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064e",88,"\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u062f\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u064a\u0652\u0646\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u062e\u0652\u0641\u0650\u0636\u0652 \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",89,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",90,"\u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0642\u0652\u062a\u064e\u0633\u0650\u0645\u0650\u064a\u0646\u064e",91,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0639\u0650\u0636\u0650\u064a\u0646\u064e",92,"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",93,"\u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",94,"\u0641\u064e\u0627\u0635\u0652\u062f\u064e\u0639\u0652 \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u064e\u0631\u064f \u0648\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",95,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u0650\u064a\u0646\u064e",96,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u06da \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",97,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u064a\u064e\u0636\u0650\u064a\u0642\u064f \u0635\u064e\u062f\u0652\u0631\u064f\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",98,"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",99,"\u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u064f"],t.v)
B.ap_=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0623\u064e\u062a\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0647\u064f \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",2,"\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0628\u0650\u0627\u0644\u0631\u0651\u064f\u0648\u062d\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",3,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",4,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",5,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064e\u0627 \u06d7 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062f\u0650\u0641\u0652\u0621\u064c \u0648\u064e\u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",6,"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0645\u064e\u0627\u0644\u064c \u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0631\u0650\u064a\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0633\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0644\u064e\u062f\u064d \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0628\u064e\u0627\u0644\u0650\u063a\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0634\u0650\u0642\u0651\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",8,"\u0648\u064e\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u0650\u063a\u064e\u0627\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0631\u064e \u0644\u0650\u062a\u064e\u0631\u0652\u0643\u064e\u0628\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u0629\u064b \u06da \u0648\u064e\u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0635\u0652\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062c\u064e\u0627\u0626\u0650\u0631\u064c \u06da \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0644\u064e\u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",10,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u06d6 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u0631\u064e\u0627\u0628\u064c \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u062c\u064e\u0631\u064c \u0641\u0650\u064a\u0647\u0650 \u062a\u064f\u0633\u0650\u064a\u0645\u064f\u0648\u0646\u064e",11,"\u064a\u064f\u0646\u0652\u0628\u0650\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0632\u0651\u064e\u0631\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062e\u0650\u064a\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064e \u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u06d6 \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0627\u062a\u064c \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0631\u064e\u0623\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0644\u0650\u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0644\u064e\u062d\u0652\u0645\u064b\u0627 \u0637\u064e\u0631\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u062a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u062d\u0650\u0644\u0652\u064a\u064e\u0629\u064b \u062a\u064e\u0644\u0652\u0628\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0645\u064e\u0648\u064e\u0627\u062e\u0650\u0631\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",15,"\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0633\u064f\u0628\u064f\u0644\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",16,"\u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0645\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0628\u0650\u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0645\u0650 \u0647\u064f\u0645\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",17,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0643\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u062d\u0652\u0635\u064f\u0648\u0647\u064e\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",19,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u062e\u0652\u0644\u064e\u0642\u064f\u0648\u0646\u064e",21,"\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064d \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",22,"\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06da \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u0643\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",23,"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",24,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06d9 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",25,"\u0644\u0650\u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0632\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u064b \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d9 \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0632\u064e\u0627\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u0631\u064f\u0648\u0646\u064e",26,"\u0642\u064e\u062f\u0652 \u0645\u064e\u0643\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u062a\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u064e\u0627\u0639\u0650\u062f\u0650 \u0641\u064e\u062e\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0642\u0652\u0641\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",27,"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064f\u062e\u0652\u0632\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u0652\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0634\u064e\u0627\u0642\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062e\u0650\u0632\u0652\u064a\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",28,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u064f\u0627 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0645\u0650\u0646\u0652 \u0633\u064f\u0648\u0621\u064d \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",29,"\u0641\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u062b\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",30,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u06d7 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u06da \u0648\u064e\u0644\u064e\u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u06da \u0648\u064e\u0644\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",31,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",32,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0637\u064e\u064a\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u06d9 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",33,"\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",34,"\u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0639\u064e\u0628\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0646\u064e\u062d\u0652\u0646\u064f \u0648\u064e\u0644\u064e\u0627 \u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0647\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",36,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u064e \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062d\u064e\u0642\u0651\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064f \u06da \u0641\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",37,"\u0625\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u0631\u0650\u0635\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",38,"\u0648\u064e\u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d9 \u0644\u064e\u0627 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",39,"\u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",40,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064f\u0646\u064e\u0627 \u0644\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u0646\u0652 \u0646\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",41,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u0644\u064e\u0646\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",42,u.c4,43,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0646\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",44,"\u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650 \u06d7 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0644\u0650\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",45,"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0633\u0650\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",46,"\u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e",47,"\u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u064e\u062e\u064e\u0648\u0651\u064f\u0641\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",48,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u064a\u0651\u064e\u0623\u064f \u0638\u0650\u0644\u064e\u0627\u0644\u064f\u0647\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u064e\u0627\u0626\u0650\u0644\u0650 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0627\u062e\u0650\u0631\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",50,"\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u064e\u0631\u064f\u0648\u0646\u064e \u06e9",51,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u064a\u0652\u0646\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06d6 \u0641\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u064a\u064e \u0641\u064e\u0627\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u0650",52,"\u0648\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0648\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u06da \u0623\u064e\u0641\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u0645\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064d \u0641\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u062c\u0652\u0623\u064e\u0631\u064f\u0648\u0646\u064e",54,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u064e \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",55,"\u0644\u0650\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06d7 \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0646\u0651\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",57,"\u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06d9 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0638\u064e\u0644\u0651\u064e \u0648\u064e\u062c\u0652\u0647\u064f\u0647\u064f \u0645\u064f\u0633\u0652\u0648\u064e\u062f\u0651\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u064c",59,"\u064a\u064e\u062a\u064e\u0648\u064e\u0627\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u0650\u0646\u0652 \u0633\u064f\u0648\u0621\u0650 \u0645\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u06da \u0623\u064e\u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u0648\u0646\u064d \u0623\u064e\u0645\u0652 \u064a\u064e\u062f\u064f\u0633\u0651\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062a\u0651\u064f\u0631\u064e\u0627\u0628\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",60,"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u06d6 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",61,"\u0648\u064e\u0644\u064e\u0648\u0652 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0645\u064f\u0648\u0646\u064e",62,"\u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u064a\u064e\u0643\u0652\u0631\u064e\u0647\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064e\u0635\u0650\u0641\u064f \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06d6 \u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0641\u0652\u0631\u064e\u0637\u064f\u0648\u0646\u064e",63,"\u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u064e\u0645\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",64,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u06d9 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",65,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",66,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0644\u064e\u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064b \u06d6 \u0646\u064f\u0633\u0652\u0642\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0631\u0652\u062b\u064d \u0648\u064e\u062f\u064e\u0645\u064d \u0644\u064e\u0628\u064e\u0646\u064b\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u064b\u0627 \u0633\u064e\u0627\u0626\u0650\u063a\u064b\u0627 \u0644\u0650\u0644\u0634\u0651\u064e\u0627\u0631\u0650\u0628\u0650\u064a\u0646\u064e",67,"\u0648\u064e\u0645\u0650\u0646\u0652 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u0650 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0633\u064e\u0643\u064e\u0631\u064b\u0627 \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u062d\u0652\u0644\u0650 \u0623\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u0650\u0630\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0634\u064f\u0648\u0646\u064e",69,"\u062b\u064f\u0645\u0651\u064e \u0643\u064f\u0644\u0650\u064a \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0641\u064e\u0627\u0633\u0652\u0644\u064f\u0643\u0650\u064a \u0633\u064f\u0628\u064f\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0630\u064f\u0644\u064f\u0644\u064b\u0627 \u06da \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0634\u064e\u0631\u064e\u0627\u0628\u064c \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064f \u0641\u0650\u064a\u0647\u0650 \u0634\u0650\u0641\u064e\u0627\u0621\u064c \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",70,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0631\u0652\u0630\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u0650 \u0644\u0650\u0643\u064e\u064a\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0639\u0650\u0644\u0652\u0645\u064d \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0642\u064e\u062f\u0650\u064a\u0631\u064c",71,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0641\u0650\u064a \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u0650 \u06da \u0641\u064e\u0645\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064f\u0636\u0651\u0650\u0644\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0627\u062f\u0651\u0650\u064a \u0631\u0650\u0632\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",72,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u062d\u064e\u0641\u064e\u062f\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",74,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",75,"\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0639\u064e\u0628\u0652\u062f\u064b\u0627 \u0645\u064e\u0645\u0652\u0644\u064f\u0648\u0643\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0645\u064e\u0646\u0652 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0633\u0650\u0631\u0651\u064b\u0627 \u0648\u064e\u062c\u064e\u0647\u0652\u0631\u064b\u0627 \u06d6 \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u064f\u0648\u0646\u064e \u06da \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",76,"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0628\u0652\u0643\u064e\u0645\u064f \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0644\u0651\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0647\u064f \u0623\u064e\u064a\u0652\u0646\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u064e\u062c\u0651\u0650\u0647\u0652\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d \u06d6 \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0647\u064f\u0648\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u06d9 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",77,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0628\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0644\u064e\u0645\u0652\u062d\u0650 \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u0650 \u0623\u064e\u0648\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",78,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064e \u06d9 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",79,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0627\u062a\u064d \u0641\u0650\u064a \u062c\u064e\u0648\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627 \u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",80,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u0633\u064e\u0643\u064e\u0646\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062c\u064f\u0644\u064f\u0648\u062f\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u062e\u0650\u0641\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0638\u064e\u0639\u0652\u0646\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0625\u0650\u0642\u064e\u0627\u0645\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u06d9 \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u0648\u064e\u0627\u0641\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0648\u0652\u0628\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0634\u0652\u0639\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u0623\u064e\u062b\u064e\u0627\u062b\u064b\u0627 \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",81,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0638\u0650\u0644\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0623\u064e\u0643\u0652\u0646\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0633\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0644\u064e \u062a\u064e\u0642\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0631\u0651\u064e \u0648\u064e\u0633\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0644\u064e \u062a\u064e\u0642\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u064e\u0623\u0652\u0633\u064e\u0643\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",82,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",83,"\u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u0652\u0643\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",84,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0630\u064e\u0646\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0633\u0652\u062a\u064e\u0639\u0652\u062a\u064e\u0628\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",86,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0643\u064e \u06d6 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",87,"\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u06d6 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",88,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0632\u0650\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0641\u064e\u0648\u0652\u0642\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e",89,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u06da \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u062a\u0650\u0628\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0648\u064e\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",90,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0621\u0650 \u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0646\u0652\u0647\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u064a\u0650 \u06da \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",91,"\u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0642\u064f\u0636\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u062a\u064e\u0648\u0652\u0643\u0650\u064a\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0643\u064e\u0641\u0650\u064a\u0644\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",92,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0646\u064e\u0642\u064e\u0636\u064e\u062a\u0652 \u063a\u064e\u0632\u0652\u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u0652\u0643\u064e\u0627\u062b\u064b\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u062f\u064e\u062e\u064e\u0644\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0647\u0650\u064a\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u0652\u0644\u064f\u0648\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",93,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0644\u064e\u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0646\u0651\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",94,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u062f\u064e\u062e\u064e\u0644\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0632\u0650\u0644\u0651\u064e \u0642\u064e\u062f\u064e\u0645\u064c \u0628\u064e\u0639\u0652\u062f\u064e \u062b\u064f\u0628\u064f\u0648\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u062f\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",95,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",96,"\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u062f\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u0627\u0642\u064d \u06d7 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",97,"\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0645\u0650\u0646\u0652 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0644\u064e\u0646\u064f\u062d\u0652\u064a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f \u062d\u064e\u064a\u064e\u0627\u0629\u064b \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u06d6 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",98,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u0652\u062a\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0630\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062c\u0650\u064a\u0645\u0650",99,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064c \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",100,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",101,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0622\u064a\u064e\u0629\u064d \u06d9 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064f\u0641\u0652\u062a\u064e\u0631\u064d \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",102,"\u0642\u064f\u0644\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u064e\u0647\u064f \u0631\u064f\u0648\u062d\u064f \u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0633\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",103,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f \u0628\u064e\u0634\u064e\u0631\u064c \u06d7 \u0644\u0650\u0633\u064e\u0627\u0646\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0644\u0652\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0639\u0652\u062c\u064e\u0645\u0650\u064a\u0651\u064c \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u0650\u0633\u064e\u0627\u0646\u064c \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",104,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",105,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",106,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064f\u0643\u0652\u0631\u0650\u0647\u064e \u0648\u064e\u0642\u064e\u0644\u0652\u0628\u064f\u0647\u064f \u0645\u064f\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064c \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0645\u064e\u0646\u0652 \u0634\u064e\u0631\u064e\u062d\u064e \u0628\u0650\u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0635\u064e\u062f\u0652\u0631\u064b\u0627 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u063a\u064e\u0636\u064e\u0628\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",107,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u0633\u0652\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",108,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0633\u064e\u0645\u0652\u0639\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",109,"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",110,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0641\u064f\u062a\u0650\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",111,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0623\u0652\u062a\u0650\u064a \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u062a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",112,"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064b \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0622\u0645\u0650\u0646\u064e\u0629\u064b \u0645\u064f\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e\u0629\u064b \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u064e\u0627 \u0631\u0650\u0632\u0652\u0642\u064f\u0647\u064e\u0627 \u0631\u064e\u063a\u064e\u062f\u064b\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064e\u062a\u0652 \u0628\u0650\u0623\u064e\u0646\u0652\u0639\u064f\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u0630\u064e\u0627\u0642\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0628\u064e\u0627\u0633\u064e \u0627\u0644\u0652\u062c\u064f\u0648\u0639\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0648\u0652\u0641\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",113,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",114,"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",115,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u062d\u0652\u0645\u064e \u0627\u0644\u0652\u062e\u0650\u0646\u0652\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0636\u0652\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u0627\u063a\u064d \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",116,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0627\u0644\u064c \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u062d\u064e\u0631\u064e\u0627\u0645\u064c \u0644\u0650\u062a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",117,"\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",118,"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u0635\u064e\u0635\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",119,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0644\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",120,"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0643\u064e\u0627\u0646\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0642\u064e\u0627\u0646\u0650\u062a\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",121,"\u0634\u064e\u0627\u0643\u0650\u0631\u064b\u0627 \u0644\u0650\u0623\u064e\u0646\u0652\u0639\u064f\u0645\u0650\u0647\u0650 \u06da \u0627\u062c\u0652\u062a\u064e\u0628\u064e\u0627\u0647\u064f \u0648\u064e\u0647\u064e\u062f\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",122,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",123,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",124,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062c\u064f\u0639\u0650\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",125,"\u0627\u062f\u0652\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u0650 \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u06d6 \u0648\u064e\u062c\u064e\u0627\u062f\u0650\u0644\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",126,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0627\u0642\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0639\u064e\u0627\u0642\u0650\u0628\u064f\u0648\u0627 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0635\u064e\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",127,"\u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0628\u0652\u0631\u064f\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0636\u064e\u064a\u0652\u0642\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",128,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0646\u064e"],t.v)
B.asz=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0633\u0652\u0631\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0628\u0652\u062f\u0650\u0647\u0650 \u0644\u064e\u064a\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0635\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0644\u0650\u0646\u064f\u0631\u0650\u064a\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",2,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",3,"\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064e \u0645\u064e\u0646\u0652 \u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0646\u064f\u0648\u062d\u064d \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0628\u0652\u062f\u064b\u0627 \u0634\u064e\u0643\u064f\u0648\u0631\u064b\u0627",4,"\u0648\u064e\u0642\u064e\u0636\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u0652\u0644\u064f\u0646\u0651\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",5,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0623\u064f\u0648\u0644\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064b\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0628\u064e\u0623\u0652\u0633\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d \u0641\u064e\u062c\u064e\u0627\u0633\u064f\u0648\u0627 \u062e\u0650\u0644\u064e\u0627\u0644\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u064e\u0627\u0631\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627",6,"\u062b\u064f\u0645\u0651\u064e \u0631\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0631\u0651\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0646\u064e\u0641\u0650\u064a\u0631\u064b\u0627",7,"\u0625\u0650\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0633\u064e\u0623\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0647\u064e\u0627 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u0650\u064a\u064e\u0633\u064f\u0648\u0621\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064e \u0643\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0648\u064e\u0644\u0650\u064a\u064f\u062a\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0648\u0652\u0627 \u062a\u064e\u062a\u0652\u0628\u0650\u064a\u0631\u064b\u0627",8,"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062d\u064e\u0645\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0639\u064f\u062f\u0652\u062a\u064f\u0645\u0652 \u0639\u064f\u062f\u0652\u0646\u064e\u0627 \u06d8 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062d\u064e\u0635\u0650\u064a\u0631\u064b\u0627",9,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0644\u0650\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u0642\u0652\u0648\u064e\u0645\u064f \u0648\u064e\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",10,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",11,"\u0648\u064e\u064a\u064e\u062f\u0652\u0639\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0631\u0651\u0650 \u062f\u064f\u0639\u064e\u0627\u0621\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0639\u064e\u062c\u064f\u0648\u0644\u064b\u0627",12,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0622\u064a\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0641\u064e\u0645\u064e\u062d\u064e\u0648\u0652\u0646\u064e\u0627 \u0622\u064a\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0622\u064a\u064e\u0629\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064e\u0629\u064b \u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0639\u064e\u062f\u064e\u062f\u064e \u0627\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u064e \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u062a\u064e\u0641\u0652\u0635\u0650\u064a\u0644\u064b\u0627",13,"\u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064d \u0623\u064e\u0644\u0652\u0632\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f \u0637\u064e\u0627\u0626\u0650\u0631\u064e\u0647\u064f \u0641\u0650\u064a \u0639\u064f\u0646\u064f\u0642\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0644\u064e\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u064a\u064e\u0644\u0652\u0642\u064e\u0627\u0647\u064f \u0645\u064e\u0646\u0652\u0634\u064f\u0648\u0631\u064b\u0627",14,"\u0627\u0642\u0652\u0631\u064e\u0623\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0643\u064e \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u062d\u064e\u0633\u0650\u064a\u0628\u064b\u0627",15,"\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u064c \u0648\u0650\u0632\u0652\u0631\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",16,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064b \u0623\u064e\u0645\u064e\u0631\u0652\u0646\u064e\u0627 \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0641\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u062a\u064e\u062f\u0652\u0645\u0650\u064a\u0631\u064b\u0627",17,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0646\u064f\u0648\u062d\u064d \u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",18,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e \u0639\u064e\u062c\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u0646\u064f\u0631\u0650\u064a\u062f\u064f \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u0652\u0644\u064e\u0627\u0647\u064e\u0627 \u0645\u064e\u0630\u0652\u0645\u064f\u0648\u0645\u064b\u0627 \u0645\u064e\u062f\u0652\u062d\u064f\u0648\u0631\u064b\u0627",19,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u0633\u064e\u0639\u064e\u0649\u0670 \u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0639\u0652\u064a\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0639\u0652\u064a\u064f\u0647\u064f\u0645\u0652 \u0645\u064e\u0634\u0652\u0643\u064f\u0648\u0631\u064b\u0627",20,"\u0643\u064f\u0644\u0651\u064b\u0627 \u0646\u064f\u0645\u0650\u062f\u0651\u064f \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0645\u0650\u0646\u0652 \u0639\u064e\u0637\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0637\u064e\u0627\u0621\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064e\u062d\u0652\u0638\u064f\u0648\u0631\u064b\u0627",21,"\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0648\u064e\u0644\u064e\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u062a\u064e\u0641\u0652\u0636\u0650\u064a\u0644\u064b\u0627",22,"\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064e\u0642\u0652\u0639\u064f\u062f\u064e \u0645\u064e\u0630\u0652\u0645\u064f\u0648\u0645\u064b\u0627 \u0645\u064e\u062e\u0652\u0630\u064f\u0648\u0644\u064b\u0627",23,"\u0648\u064e\u0642\u064e\u0636\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u06da \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0648\u0652 \u0643\u0650\u0644\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0623\u064f\u0641\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0647\u064e\u0631\u0652\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064b\u0627",24,"\u0648\u064e\u0627\u062e\u0652\u0641\u0650\u0636\u0652 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u062c\u064e\u0646\u064e\u0627\u062d\u064e \u0627\u0644\u0630\u0651\u064f\u0644\u0651\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f\u0645\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u064a\u064e\u0627\u0646\u0650\u064a \u0635\u064e\u063a\u0650\u064a\u0631\u064b\u0627",25,"\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064f\u0641\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0627\u0628\u0650\u064a\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",26,"\u0648\u064e\u0622\u062a\u0650 \u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u062d\u064e\u0642\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u064e\u0630\u0651\u0650\u0631\u0652 \u062a\u064e\u0628\u0652\u0630\u0650\u064a\u0631\u064b\u0627",27,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0628\u064e\u0630\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",28,"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0639\u0652\u0631\u0650\u0636\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062a\u064e\u0631\u0652\u062c\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u064e\u064a\u0652\u0633\u064f\u0648\u0631\u064b\u0627",29,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u064a\u064e\u062f\u064e\u0643\u064e \u0645\u064e\u063a\u0652\u0644\u064f\u0648\u0644\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064f\u0646\u064f\u0642\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u0633\u064f\u0637\u0652\u0647\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u0633\u0652\u0637\u0650 \u0641\u064e\u062a\u064e\u0642\u0652\u0639\u064f\u062f\u064e \u0645\u064e\u0644\u064f\u0648\u0645\u064b\u0627 \u0645\u064e\u062d\u0652\u0633\u064f\u0648\u0631\u064b\u0627",30,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",31,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u064e \u0625\u0650\u0645\u0652\u0644\u064e\u0627\u0642\u064d \u06d6 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u062a\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064e \u062e\u0650\u0637\u0652\u0626\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",32,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u0650\u0646\u064e\u0649\u0670 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064b \u0648\u064e\u0633\u064e\u0627\u0621\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",33,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064f\u062a\u0650\u0644\u064e \u0645\u064e\u0638\u0652\u0644\u064f\u0648\u0645\u064b\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0648\u064e\u0644\u0650\u064a\u0651\u0650\u0647\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0631\u0650\u0641\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0646\u0652\u0635\u064f\u0648\u0631\u064b\u0627",34,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0645\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u064a\u064e\u062a\u0650\u064a\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0647\u0652\u062f\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0647\u0652\u062f\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064b\u0627",35,"\u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0632\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u064e\u0627\u0633\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064b\u0627",36,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0641\u064f \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0624\u064e\u0627\u062f\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064b\u0627",37,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u0634\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0631\u064e\u062d\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646\u0652 \u062a\u064e\u062e\u0652\u0631\u0650\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0637\u064f\u0648\u0644\u064b\u0627",38,"\u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064f\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064e\u0643\u0652\u0631\u064f\u0648\u0647\u064b\u0627",39,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064f\u0644\u0652\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u0644\u064f\u0648\u0645\u064b\u0627 \u0645\u064e\u062f\u0652\u062d\u064f\u0648\u0631\u064b\u0627",40,"\u0623\u064e\u0641\u064e\u0623\u064e\u0635\u0652\u0641\u064e\u0627\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",41,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0641\u064f\u0648\u0631\u064b\u0627",42,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0622\u0644\u0650\u0647\u064e\u0629\u064c \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",43,"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",44,"\u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u0639\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u062a\u064e\u0633\u0652\u0628\u0650\u064a\u062d\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",45,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u0652\u062a\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u064b\u0627 \u0645\u064e\u0633\u0652\u062a\u064f\u0648\u0631\u064b\u0627",46,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064e\u0643\u064e\u0631\u0652\u062a\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0646\u064f\u0641\u064f\u0648\u0631\u064b\u0627",47,"\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0625\u0650\u0630\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0625\u0650\u0630\u0652 \u0647\u064f\u0645\u0652 \u0646\u064e\u062c\u0652\u0648\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0645\u064e\u0633\u0652\u062d\u064f\u0648\u0631\u064b\u0627",48,u.cp,49,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0631\u064f\u0641\u064e\u0627\u062a\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u062c\u064e\u062f\u0650\u064a\u062f\u064b\u0627",50,"\u0642\u064f\u0644\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u062d\u064e\u062f\u0650\u064a\u062f\u064b\u0627",51,"\u0623\u064e\u0648\u0652 \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u0652\u0628\u064f\u0631\u064f \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u06da \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0646\u064e\u0627 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u06da \u0641\u064e\u0633\u064e\u064a\u064f\u0646\u0652\u063a\u0650\u0636\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064f\u0648\u064e \u06d6 \u0642\u064f\u0644\u0652 \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",52,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u062a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",53,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u064a\u064e\u0646\u0652\u0632\u064e\u063a\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",54,"\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064e\u0631\u0652\u062d\u064e\u0645\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",55,"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0632\u064e\u0628\u064f\u0648\u0631\u064b\u0627",56,"\u0642\u064f\u0644\u0650 \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0643\u064e\u0634\u0652\u0641\u064e \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u0650 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0648\u0650\u064a\u0644\u064b\u0627",57,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0648\u064e\u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u062d\u0652\u0630\u064f\u0648\u0631\u064b\u0627",58,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648\u0647\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0623\u064e\u0648\u0652 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u06da \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u064e\u0633\u0652\u0637\u064f\u0648\u0631\u064b\u0627",59,"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u064e \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064e\u0629\u064b \u0641\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0628\u0650\u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u0652\u0648\u0650\u064a\u0641\u064b\u0627",60,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0631\u0651\u064f\u0624\u0652\u064a\u064e\u0627 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0631\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0652\u0639\u064f\u0648\u0646\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u06da \u0648\u064e\u0646\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",61,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0622\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0623\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e \u0637\u0650\u064a\u0646\u064b\u0627",62,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0643\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0631\u0651\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u062e\u0651\u064e\u0631\u0652\u062a\u064e\u0646\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0623\u064e\u062d\u0652\u062a\u064e\u0646\u0650\u0643\u064e\u0646\u0651\u064e \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",63,"\u0642\u064e\u0627\u0644\u064e \u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0641\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0645\u064e\u0648\u0652\u0641\u064f\u0648\u0631\u064b\u0627",64,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0641\u0652\u0632\u0650\u0632\u0652 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0635\u064e\u0648\u0652\u062a\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u062c\u0652\u0644\u0650\u0628\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u062e\u064e\u064a\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u0631\u064e\u062c\u0650\u0644\u0650\u0643\u064e \u0648\u064e\u0634\u064e\u0627\u0631\u0650\u0643\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u0650 \u0648\u064e\u0639\u0650\u062f\u0652\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",65,"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064c \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",66,"\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0632\u0652\u062c\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",67,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0636\u064e\u0644\u0651\u064e \u0645\u064e\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",68,"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0633\u0650\u0641\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u062c\u064e\u0627\u0646\u0650\u0628\u064e \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0623\u064e\u0648\u0652 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062d\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",69,"\u0623\u064e\u0645\u0652 \u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0639\u0650\u064a\u062f\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0641\u064e\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0642\u064e\u0627\u0635\u0650\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u0650 \u0641\u064e\u064a\u064f\u063a\u0652\u0631\u0650\u0642\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u06d9 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u062a\u064e\u0628\u0650\u064a\u0639\u064b\u0627",70,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0648\u064e\u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u064d \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u062a\u064e\u0641\u0652\u0636\u0650\u064a\u0644\u064b\u0627",71,"\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062f\u0652\u0639\u064f\u0648 \u0643\u064f\u0644\u0651\u064e \u0623\u064f\u0646\u064e\u0627\u0633\u064d \u0628\u0650\u0625\u0650\u0645\u064e\u0627\u0645\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0642\u0652\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u064b\u0627",72,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",73,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u062f\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0641\u0652\u062a\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0644\u0650\u062a\u064e\u0641\u0652\u062a\u064e\u0631\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0643\u064e \u062e\u064e\u0644\u0650\u064a\u0644\u064b\u0627",74,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062b\u064e\u0628\u0651\u064e\u062a\u0652\u0646\u064e\u0627\u0643\u064e \u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u0650\u062f\u0652\u062a\u064e \u062a\u064e\u0631\u0652\u0643\u064e\u0646\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",75,"\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064e \u0636\u0650\u0639\u0652\u0641\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0648\u064e\u0636\u0650\u0639\u0652\u0641\u064e \u0627\u0644\u0652\u0645\u064e\u0645\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",76,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u062f\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0641\u0650\u0632\u0651\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u0650\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0644\u0652\u0628\u064e\u062b\u064f\u0648\u0646\u064e \u062e\u0650\u0644\u064e\u0627\u0641\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",77,"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0645\u064e\u0646\u0652 \u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650\u0646\u064e\u0627 \u062a\u064e\u062d\u0652\u0648\u0650\u064a\u0644\u064b\u0627",78,"\u0623\u064e\u0642\u0650\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0644\u0650\u062f\u064f\u0644\u064f\u0648\u0643\u0650 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u063a\u064e\u0633\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0634\u0652\u0647\u064f\u0648\u062f\u064b\u0627",79,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u062a\u064e\u0647\u064e\u062c\u0651\u064e\u062f\u0652 \u0628\u0650\u0647\u0650 \u0646\u064e\u0627\u0641\u0650\u0644\u064e\u0629\u064b \u0644\u064e\u0643\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u064b\u0627 \u0645\u064e\u062d\u0652\u0645\u064f\u0648\u062f\u064b\u0627",80,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0646\u0650\u064a \u0645\u064f\u062f\u0652\u062e\u064e\u0644\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0648\u064e\u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u0650\u064a \u0645\u064f\u062e\u0652\u0631\u064e\u062c\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",81,"\u0648\u064e\u0642\u064f\u0644\u0652 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0632\u064e\u0647\u064e\u0642\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u0643\u064e\u0627\u0646\u064e \u0632\u064e\u0647\u064f\u0648\u0642\u064b\u0627",82,"\u0648\u064e\u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0634\u0650\u0641\u064e\u0627\u0621\u064c \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d9 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u064b\u0627",83,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0648\u064e\u0646\u064e\u0623\u064e\u0649\u0670 \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0626\u064f\u0648\u0633\u064b\u0627",84,"\u0642\u064f\u0644\u0652 \u0643\u064f\u0644\u0651\u064c \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0627\u0643\u0650\u0644\u064e\u062a\u0650\u0647\u0650 \u0641\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",85,"\u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u0650 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",86,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0634\u0650\u0626\u0652\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0630\u0652\u0647\u064e\u0628\u064e\u0646\u0651\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",87,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0636\u0652\u0644\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",88,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064e\u062a\u0650 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627",89,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u064d \u0641\u064e\u0623\u064e\u0628\u064e\u0649\u0670 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u064b\u0627",90,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0641\u0652\u062c\u064f\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u0646\u0652\u0628\u064f\u0648\u0639\u064b\u0627",91,"\u0623\u064e\u0648\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e \u062c\u064e\u0646\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0646\u064e\u062e\u0650\u064a\u0644\u064d \u0648\u064e\u0639\u0650\u0646\u064e\u0628\u064d \u0641\u064e\u062a\u064f\u0641\u064e\u062c\u0651\u0650\u0631\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064e \u062e\u0650\u0644\u064e\u0627\u0644\u064e\u0647\u064e\u0627 \u062a\u064e\u0641\u0652\u062c\u0650\u064a\u0631\u064b\u0627",92,"\u0623\u064e\u0648\u0652 \u062a\u064f\u0633\u0652\u0642\u0650\u0637\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0643\u064e\u0645\u064e\u0627 \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0623\u064e\u0648\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0642\u064e\u0628\u0650\u064a\u0644\u064b\u0627",93,"\u0623\u064e\u0648\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e \u0628\u064e\u064a\u0652\u062a\u064c \u0645\u0650\u0646\u0652 \u0632\u064f\u062e\u0652\u0631\u064f\u0641\u064d \u0623\u064e\u0648\u0652 \u062a\u064e\u0631\u0652\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0644\u0650\u0631\u064f\u0642\u0650\u064a\u0651\u0650\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0646\u064e\u0642\u0652\u0631\u064e\u0624\u064f\u0647\u064f \u06d7 \u0642\u064f\u0644\u0652 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0647\u064e\u0644\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",94,"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",95,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064c \u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0645\u064f\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0644\u064e\u0643\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",96,"\u0642\u064f\u0644\u0652 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",97,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0652 \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 \u0639\u064f\u0645\u0652\u064a\u064b\u0627 \u0648\u064e\u0628\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0635\u064f\u0645\u0651\u064b\u0627 \u06d6 \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0628\u064e\u062a\u0652 \u0632\u0650\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",98,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0631\u064f\u0641\u064e\u0627\u062a\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u062c\u064e\u062f\u0650\u064a\u062f\u064b\u0627",99,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0642\u064e\u0627\u062f\u0650\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064e \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u064e\u0644\u064b\u0627 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u0623\u064e\u0628\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u064b\u0627",100,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0623\u064e\u0645\u0652\u0633\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0641\u064e\u0627\u0642\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0642\u064e\u062a\u064f\u0648\u0631\u064b\u0627",101,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062a\u0650\u0633\u0652\u0639\u064e \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u06d6 \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064e\u0633\u0652\u062d\u064f\u0648\u0631\u064b\u0627",102,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u064a\u064e\u0627 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0645\u064e\u062b\u0652\u0628\u064f\u0648\u0631\u064b\u0627",103,"\u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0641\u0650\u0632\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",104,"\u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0644\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a\u0641\u064b\u0627",105,"\u0648\u064e\u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0646\u064e\u0632\u064e\u0644\u064e \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",106,"\u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0641\u064e\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0644\u0650\u062a\u064e\u0642\u0652\u0631\u064e\u0623\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0643\u0652\u062b\u064d \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064b\u0627",107,"\u0642\u064f\u0644\u0652 \u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u0623\u064e\u0630\u0652\u0642\u064e\u0627\u0646\u0650 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627",108,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627",109,"\u0648\u064e\u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u0623\u064e\u0630\u0652\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u0628\u0652\u0643\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u0652 \u062e\u064f\u0634\u064f\u0648\u0639\u064b\u0627 \u06e9",110,"\u0642\u064f\u0644\u0650 \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0648\u0650 \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064e \u06d6 \u0623\u064e\u064a\u0651\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0647\u064e\u0631\u0652 \u0628\u0650\u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0627\u0641\u0650\u062a\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u0650 \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",111,"\u0648\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0652 \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0634\u064e\u0631\u0650\u064a\u0643\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0630\u0651\u064f\u0644\u0651\u0650 \u06d6 \u0648\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0652\u0647\u064f \u062a\u064e\u0643\u0652\u0628\u0650\u064a\u0631\u064b\u0627"],t.v)
B.art=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u06dc",2,"\u0642\u064e\u064a\u0651\u0650\u0645\u064b\u0627 \u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0628\u064e\u0623\u0652\u0633\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0647\u064f \u0648\u064e\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627",3,"\u0645\u064e\u0627\u0643\u0650\u062b\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",4,"\u0648\u064e\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627",5,"\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0628\u064f\u0631\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064b \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0630\u0650\u0628\u064b\u0627",6,"\u0641\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u0628\u064e\u0627\u062e\u0650\u0639\u064c \u0646\u064e\u0641\u0652\u0633\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0623\u064e\u0633\u064e\u0641\u064b\u0627",7,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0632\u0650\u064a\u0646\u064e\u0629\u064b \u0644\u064e\u0647\u064e\u0627 \u0644\u0650\u0646\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u064b\u0627",8,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062c\u064e\u0627\u0639\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0635\u064e\u0639\u0650\u064a\u062f\u064b\u0627 \u062c\u064f\u0631\u064f\u0632\u064b\u0627",9,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064e \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0643\u064e\u0647\u0652\u0641\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0642\u0650\u064a\u0645\u0650 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u062c\u064e\u0628\u064b\u0627",10,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0648\u064e\u0649 \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u064a\u064e\u0629\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0647\u0652\u0641\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0648\u064e\u0647\u064e\u064a\u0651\u0650\u0626\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u064b\u0627",11,"\u0641\u064e\u0636\u064e\u0631\u064e\u0628\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u0647\u0652\u0641\u0650 \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u062f\u064e\u062f\u064b\u0627",12,"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u0650\u0632\u0652\u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u062d\u0652\u0635\u064e\u0649\u0670 \u0644\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627 \u0623\u064e\u0645\u064e\u062f\u064b\u0627",13,"\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0646\u064e\u0628\u064e\u0623\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u062a\u0652\u064a\u064e\u0629\u064c \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0632\u0650\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0647\u064f\u062f\u064b\u0649",14,"\u0648\u064e\u0631\u064e\u0628\u064e\u0637\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0646\u0652 \u0646\u064e\u062f\u0652\u0639\u064f\u0648\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u06d6 \u0644\u064e\u0642\u064e\u062f\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0634\u064e\u0637\u064e\u0637\u064b\u0627",15,"\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0642\u064e\u0648\u0652\u0645\u064f\u0646\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u06d6 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064d \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627",16,"\u0648\u064e\u0625\u0650\u0630\u0650 \u0627\u0639\u0652\u062a\u064e\u0632\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0623\u0652\u0648\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0647\u0652\u0641\u0650 \u064a\u064e\u0646\u0652\u0634\u064f\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0647\u064e\u064a\u0651\u0650\u0626\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0631\u0652\u0641\u064e\u0642\u064b\u0627",17,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u064e\u0639\u064e\u062a\u0652 \u062a\u064e\u0632\u064e\u0627\u0648\u064e\u0631\u064f \u0639\u064e\u0646\u0652 \u0643\u064e\u0647\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0630\u064e\u0627\u062a\u064e \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u063a\u064e\u0631\u064e\u0628\u064e\u062a\u0652 \u062a\u064e\u0642\u0652\u0631\u0650\u0636\u064f\u0647\u064f\u0645\u0652 \u0630\u064e\u0627\u062a\u064e \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0641\u064e\u062c\u0652\u0648\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0652 \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0645\u064f\u0631\u0652\u0634\u0650\u062f\u064b\u0627",18,"\u0648\u064e\u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0642\u064e\u0627\u0638\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0631\u064f\u0642\u064f\u0648\u062f\u064c \u06da \u0648\u064e\u0646\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u0652 \u0630\u064e\u0627\u062a\u064e \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0630\u064e\u0627\u062a\u064e \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u06d6 \u0648\u064e\u0643\u064e\u0644\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u0627\u0633\u0650\u0637\u064c \u0630\u0650\u0631\u064e\u0627\u0639\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0635\u0650\u064a\u062f\u0650 \u06da \u0644\u064e\u0648\u0650 \u0627\u0637\u0651\u064e\u0644\u064e\u0639\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u064f\u0644\u0650\u0626\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0639\u0652\u0628\u064b\u0627",19,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0626\u0650\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0628\u0650\u062b\u0652\u0646\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0623\u064e\u0648\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0627 \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0648\u064e\u0631\u0650\u0642\u0650\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0623\u064e\u0632\u0652\u0643\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0631\u0650\u0632\u0652\u0642\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0644\u064e\u0637\u0651\u064e\u0641\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0639\u0650\u0631\u064e\u0646\u0651\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",20,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u064a\u064e\u0638\u0652\u0647\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u064f\u0645\u064f\u0648\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0625\u0650\u0630\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",21,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0639\u0652\u062b\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0630\u0652 \u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0628\u0652\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u063a\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064b\u0627",22,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064c \u0631\u064e\u0627\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0644\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0645\u0652\u0633\u064e\u0629\u064c \u0633\u064e\u0627\u062f\u0650\u0633\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0644\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u0631\u064e\u062c\u0652\u0645\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06d6 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0652\u0639\u064e\u0629\u064c \u0648\u064e\u062b\u064e\u0627\u0645\u0650\u0646\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0644\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0639\u0650\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c \u06d7 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u064e\u0627\u0631\u0650 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0631\u064e\u0627\u0621\u064b \u0638\u064e\u0627\u0647\u0650\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",23,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0644\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0646\u0651\u0650\u064a \u0641\u064e\u0627\u0639\u0650\u0644\u064c \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u063a\u064e\u062f\u064b\u0627",24,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064e \u0648\u064e\u0642\u064f\u0644\u0652 \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u0650\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064e \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u064b\u0627",25,"\u0648\u064e\u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627 \u0641\u0650\u064a \u0643\u064e\u0647\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u062b\u064e\u0644\u064e\u0627\u062b\u064e \u0645\u0650\u0627\u0626\u064e\u0629\u064d \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0632\u0652\u062f\u064e\u0627\u062f\u064f\u0648\u0627 \u062a\u0650\u0633\u0652\u0639\u064b\u0627",26,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627 \u06d6 \u0644\u064e\u0647\u064f \u063a\u064e\u064a\u0652\u0628\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0623\u064e\u0628\u0652\u0635\u0650\u0631\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0633\u0652\u0645\u0650\u0639\u0652 \u06da \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f \u0641\u0650\u064a \u062d\u064f\u0643\u0652\u0645\u0650\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",27,"\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0645\u064e\u0627 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0644\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u064f\u0644\u0652\u062a\u064e\u062d\u064e\u062f\u064b\u0627",28,"\u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0646\u064e\u0641\u0652\u0633\u064e\u0643\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u062f\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062f\u064f \u0639\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u063a\u0652\u0641\u064e\u0644\u0652\u0646\u064e\u0627 \u0642\u064e\u0644\u0652\u0628\u064e\u0647\u064f \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0647\u064f \u0641\u064f\u0631\u064f\u0637\u064b\u0627",29,"\u0648\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0641\u064e\u0644\u0652\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0641\u064e\u0644\u0652\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0631\u064b\u0627 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0633\u064f\u0631\u064e\u0627\u062f\u0650\u0642\u064f\u0647\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u062b\u064f\u0648\u0627 \u064a\u064f\u063a\u064e\u0627\u062b\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627\u0621\u064d \u0643\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u0644\u0650 \u064a\u064e\u0634\u0652\u0648\u0650\u064a \u0627\u0644\u0652\u0648\u064f\u062c\u064f\u0648\u0647\u064e \u06da \u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0634\u0651\u064e\u0631\u064e\u0627\u0628\u064f \u0648\u064e\u0633\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064f\u0631\u0652\u062a\u064e\u0641\u064e\u0642\u064b\u0627",30,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u0652\u0631\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0639\u064e\u0645\u064e\u0644\u064b\u0627",31,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0647\u064e\u0628\u064d \u0648\u064e\u064a\u064e\u0644\u0652\u0628\u064e\u0633\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064b\u0627 \u062e\u064f\u0636\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0633\u064f\u0646\u0652\u062f\u064f\u0633\u064d \u0648\u064e\u0625\u0650\u0633\u0652\u062a\u064e\u0628\u0652\u0631\u064e\u0642\u064d \u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u0650 \u06da \u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u062b\u0651\u064e\u0648\u064e\u0627\u0628\u064f \u0648\u064e\u062d\u064e\u0633\u064f\u0646\u064e\u062a\u0652 \u0645\u064f\u0631\u0652\u062a\u064e\u0641\u064e\u0642\u064b\u0627",32,"\u0648\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u0652\u0646\u0650 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u0648\u064e\u062d\u064e\u0641\u064e\u0641\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u0646\u064e\u062e\u0652\u0644\u064d \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0632\u064e\u0631\u0652\u0639\u064b\u0627",33,"\u0643\u0650\u0644\u0652\u062a\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0622\u062a\u064e\u062a\u0652 \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0638\u0652\u0644\u0650\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u062e\u0650\u0644\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0631\u064b\u0627",34,"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u062b\u064e\u0645\u064e\u0631\u064c \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u064e\u0627\u0648\u0650\u0631\u064f\u0647\u064f \u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0645\u0650\u0646\u0652\u0643\u064e \u0645\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0646\u064e\u0641\u064e\u0631\u064b\u0627",35,"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064c \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u064a\u062f\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",36,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0631\u064f\u062f\u0650\u062f\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064f\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064b\u0627",37,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u064e\u0627\u0648\u0650\u0631\u064f\u0647\u064f \u0623\u064e\u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u0633\u064e\u0648\u0651\u064e\u0627\u0643\u064e \u0631\u064e\u062c\u064f\u0644\u064b\u0627",38,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0623\u064f\u0634\u0652\u0631\u0650\u0643\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u062d\u064e\u062f\u064b\u0627",39,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0630\u0652 \u062f\u064e\u062e\u064e\u0644\u0652\u062a\u064e \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0643\u064e \u0642\u064f\u0644\u0652\u062a\u064e \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0652 \u062a\u064e\u0631\u064e\u0646\u0650 \u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0642\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064e \u0645\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u064b\u0627",40,"\u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u064e\u0646\u0650 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u062c\u064e\u0646\u0651\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062d\u064f\u0633\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u062a\u064f\u0635\u0652\u0628\u0650\u062d\u064e \u0635\u064e\u0639\u0650\u064a\u062f\u064b\u0627 \u0632\u064e\u0644\u064e\u0642\u064b\u0627",41,"\u0623\u064e\u0648\u0652 \u064a\u064f\u0635\u0652\u0628\u0650\u062d\u064e \u0645\u064e\u0627\u0624\u064f\u0647\u064e\u0627 \u063a\u064e\u0648\u0652\u0631\u064b\u0627 \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0644\u064e\u0647\u064f \u0637\u064e\u0644\u064e\u0628\u064b\u0627",42,"\u0648\u064e\u0623\u064f\u062d\u0650\u064a\u0637\u064e \u0628\u0650\u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0643\u064e\u0641\u0651\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u0652 \u0623\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u062d\u064e\u062f\u064b\u0627",43,"\u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0641\u0650\u0626\u064e\u0629\u064c \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064b\u0627",44,"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0648\u064e\u0644\u064e\u0627\u064a\u064e\u0629\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u062b\u064e\u0648\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064c \u0639\u064f\u0642\u0652\u0628\u064b\u0627",45,"\u0648\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u062b\u064e\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u0627\u0621\u064d \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0647\u0650 \u0646\u064e\u0628\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0647\u064e\u0634\u0650\u064a\u0645\u064b\u0627 \u062a\u064e\u0630\u0652\u0631\u064f\u0648\u0647\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064f \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064f\u0642\u0652\u062a\u064e\u062f\u0650\u0631\u064b\u0627",46,"\u0627\u0644\u0652\u0645\u064e\u0627\u0644\u064f \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0646\u064f\u0648\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u0629\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u064e\u0644\u064b\u0627",47,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0633\u064e\u064a\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0627\u0631\u0650\u0632\u064e\u0629\u064b \u0648\u064e\u062d\u064e\u0634\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u063a\u064e\u0627\u062f\u0650\u0631\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",48,"\u0648\u064e\u0639\u064f\u0631\u0650\u0636\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0635\u064e\u0641\u0651\u064b\u0627 \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u06da \u0628\u064e\u0644\u0652 \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0646\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064b\u0627",49,"\u0648\u064e\u0648\u064f\u0636\u0650\u0639\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u062a\u064e\u0646\u064e\u0627 \u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0627 \u064a\u064f\u063a\u064e\u0627\u062f\u0650\u0631\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u062d\u0652\u0635\u064e\u0627\u0647\u064e\u0627 \u06da \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u062d\u064e\u0627\u0636\u0650\u0631\u064b\u0627 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u062d\u064e\u062f\u064b\u0627",50,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0622\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0641\u064e\u0633\u064e\u0642\u064e \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0623\u064e\u0641\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0647\u064f \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u06da \u0628\u0650\u0626\u0652\u0633\u064e \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u062f\u064e\u0644\u064b\u0627",51,"\u0645\u064e\u0627 \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u062e\u064e\u0644\u0652\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0644\u0652\u0642\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0627\u0644\u0652\u0645\u064f\u0636\u0650\u0644\u0651\u0650\u064a\u0646\u064e \u0639\u064e\u0636\u064f\u062f\u064b\u0627",52,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0646\u064e\u0627\u062f\u064f\u0648\u0627 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u062f\u064e\u0639\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u0628\u0650\u0642\u064b\u0627",53,"\u0648\u064e\u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0641\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u064e\u0627\u0642\u0650\u0639\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0635\u0652\u0631\u0650\u0641\u064b\u0627",54,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u064d \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u062c\u064e\u062f\u064e\u0644\u064b\u0627",55,"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0642\u064f\u0628\u064f\u0644\u064b\u0627",56,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u06da \u0648\u064e\u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0644\u0650\u064a\u064f\u062f\u0652\u062d\u0650\u0636\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627",57,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0630\u064f\u0643\u0651\u0650\u0631\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u064a\u064e\u062f\u064e\u0627\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u0652\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0630\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",58,"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0630\u064f\u0648 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u06d6 \u0644\u064e\u0648\u0652 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064c \u0644\u064e\u0646\u0652 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u064e\u0648\u0652\u0626\u0650\u0644\u064b\u0627",59,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0647\u0652\u0644\u0650\u0643\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064b\u0627",60,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0641\u064e\u062a\u064e\u0627\u0647\u064f \u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0631\u064e\u062d\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0645\u064e\u062c\u0652\u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0645\u0652\u0636\u0650\u064a\u064e \u062d\u064f\u0642\u064f\u0628\u064b\u0627",61,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u0627 \u0645\u064e\u062c\u0652\u0645\u064e\u0639\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u064e\u0627 \u062d\u064f\u0648\u062a\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0633\u064e\u0631\u064e\u0628\u064b\u0627",62,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0648\u064e\u0632\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0641\u064e\u062a\u064e\u0627\u0647\u064f \u0622\u062a\u0650\u0646\u064e\u0627 \u063a\u064e\u062f\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0642\u064e\u062f\u0652 \u0644\u064e\u0642\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0633\u064e\u0641\u064e\u0631\u0650\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u064b\u0627",63,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0630\u0652 \u0623\u064e\u0648\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u062e\u0652\u0631\u064e\u0629\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0633\u0650\u064a\u062a\u064f \u0627\u0644\u0652\u062d\u064f\u0648\u062a\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0633\u064e\u0627\u0646\u0650\u064a\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0630\u0652\u0643\u064f\u0631\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0639\u064e\u062c\u064e\u0628\u064b\u0627",64,"\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0628\u0652\u063a\u0650 \u06da \u0641\u064e\u0627\u0631\u0652\u062a\u064e\u062f\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u064e\u0627 \u0642\u064e\u0635\u064e\u0635\u064b\u0627",65,"\u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064b\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064b\u0627",66,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064f\u0644\u0651\u0650\u0645\u0652\u062a\u064e \u0631\u064f\u0634\u0652\u062f\u064b\u0627",67,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u0652\u0631\u064b\u0627",68,"\u0648\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064f\u062d\u0650\u0637\u0652 \u0628\u0650\u0647\u0650 \u062e\u064f\u0628\u0652\u0631\u064b\u0627",69,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0635\u064e\u0627\u0628\u0650\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0635\u0650\u064a \u0644\u064e\u0643\u064e \u0623\u064e\u0645\u0652\u0631\u064b\u0627",70,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u0652\u062a\u064e\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064f\u062d\u0652\u062f\u0650\u062b\u064e \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0630\u0650\u0643\u0652\u0631\u064b\u0627",71,"\u0641\u064e\u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0643\u0650\u0628\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u0650 \u062e\u064e\u0631\u064e\u0642\u064e\u0647\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062e\u064e\u0631\u064e\u0642\u0652\u062a\u064e\u0647\u064e\u0627 \u0644\u0650\u062a\u064f\u063a\u0652\u0631\u0650\u0642\u064e \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0645\u0652\u0631\u064b\u0627",72,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u0652\u0631\u064b\u0627",73,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u0652\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0631\u0652\u0647\u0650\u0642\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u064a \u0639\u064f\u0633\u0652\u0631\u064b\u0627",74,"\u0641\u064e\u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u064e\u0627 \u063a\u064f\u0644\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064e \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0632\u064e\u0643\u0650\u064a\u0651\u064e\u0629\u064b \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0646\u064e\u0641\u0652\u0633\u064d \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0646\u064f\u0643\u0652\u0631\u064b\u0627",75,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u0652\u0631\u064b\u0627",76,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0643\u064e \u0639\u064e\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0627\u062d\u0650\u0628\u0652\u0646\u0650\u064a \u06d6 \u0642\u064e\u062f\u0652 \u0628\u064e\u0644\u064e\u063a\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u0652\u0631\u064b\u0627",77,"\u0641\u064e\u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062a\u064e\u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0627\u0633\u0652\u062a\u064e\u0637\u0652\u0639\u064e\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0628\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0636\u064e\u064a\u0651\u0650\u0641\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u0650\u062f\u064e\u0627\u0631\u064b\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0636\u0651\u064e \u0641\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u0652 \u0634\u0650\u0626\u0652\u062a\u064e \u0644\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627",78,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0642\u064f \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064e \u06da \u0633\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064e \u0628\u0650\u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u0639\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0635\u064e\u0628\u0652\u0631\u064b\u0627",79,"\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u0650\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0641\u064e\u0623\u064e\u0631\u064e\u062f\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0650\u064a\u0628\u064e\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0631\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0644\u0650\u0643\u064c \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f \u0643\u064f\u0644\u0651\u064e \u0633\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u064d \u063a\u064e\u0635\u0652\u0628\u064b\u0627",80,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u063a\u064f\u0644\u064e\u0627\u0645\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u062e\u064e\u0634\u0650\u064a\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0631\u0652\u0647\u0650\u0642\u064e\u0647\u064f\u0645\u064e\u0627 \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064b\u0627",81,"\u0641\u064e\u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0628\u0652\u062f\u0650\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0632\u064e\u0643\u064e\u0627\u0629\u064b \u0648\u064e\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064e \u0631\u064f\u062d\u0652\u0645\u064b\u0627",82,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u062c\u0650\u062f\u064e\u0627\u0631\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u063a\u064f\u0644\u064e\u0627\u0645\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062a\u0650\u064a\u0645\u064e\u064a\u0652\u0646\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062a\u064e\u062d\u0652\u062a\u064e\u0647\u064f \u0643\u064e\u0646\u0652\u0632\u064c \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e\u0627 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0631\u0650\u062c\u064e\u0627 \u0643\u064e\u0646\u0652\u0632\u064e\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0647\u064f \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u064a \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0623\u0652\u0648\u0650\u064a\u0644\u064f \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0633\u0652\u0637\u0650\u0639\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0635\u064e\u0628\u0652\u0631\u064b\u0627",83,"\u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0633\u064e\u0623\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0630\u0650\u0643\u0652\u0631\u064b\u0627",84,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0633\u064e\u0628\u064e\u0628\u064b\u0627",85,"\u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",86,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u063a\u0652\u0631\u0650\u0628\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u062c\u064e\u062f\u064e\u0647\u064e\u0627 \u062a\u064e\u063a\u0652\u0631\u064f\u0628\u064f \u0641\u0650\u064a \u0639\u064e\u064a\u0652\u0646\u064d \u062d\u064e\u0645\u0650\u0626\u064e\u0629\u064d \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u06d7 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u062d\u064f\u0633\u0652\u0646\u064b\u0627",87,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0638\u064e\u0644\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0646\u064f\u0643\u0652\u0631\u064b\u0627",88,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u0647\u064f \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0633\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u064a\u064f\u0633\u0652\u0631\u064b\u0627",89,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",90,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u0637\u0652\u0644\u0650\u0639\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u062c\u064e\u062f\u064e\u0647\u064e\u0627 \u062a\u064e\u0637\u0652\u0644\u064f\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0633\u0650\u062a\u0652\u0631\u064b\u0627",91,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u064e\u0637\u0652\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u062e\u064f\u0628\u0652\u0631\u064b\u0627",92,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",93,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u062f\u0651\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u062c\u064e\u062f\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064b\u0627",94,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0623\u0652\u062c\u064f\u0648\u062c\u064e \u0648\u064e\u0645\u064e\u0623\u0652\u062c\u064f\u0648\u062c\u064e \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0647\u064e\u0644\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0643\u064e \u062e\u064e\u0631\u0652\u062c\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627",95,"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u062e\u064e\u064a\u0652\u0631\u064c \u0641\u064e\u0623\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u062f\u0652\u0645\u064b\u0627",96,"\u0622\u062a\u064f\u0648\u0646\u0650\u064a \u0632\u064f\u0628\u064e\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062f\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0627\u0648\u064e\u0649\u0670 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0641\u064e\u064a\u0652\u0646\u0650 \u0642\u064e\u0627\u0644\u064e \u0627\u0646\u0652\u0641\u064f\u062e\u064f\u0648\u0627 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0622\u062a\u064f\u0648\u0646\u0650\u064a \u0623\u064f\u0641\u0652\u0631\u0650\u063a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0642\u0650\u0637\u0652\u0631\u064b\u0627",97,"\u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0638\u0652\u0647\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0646\u064e\u0642\u0652\u0628\u064b\u0627",98,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u062f\u064e\u0643\u0651\u064e\u0627\u0621\u064e \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u0652\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u0642\u0651\u064b\u0627",99,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0645\u064f\u0648\u062c\u064f \u0641\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u064d \u06d6 \u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u062c\u064e\u0645\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0652\u0639\u064b\u0627",100,"\u0648\u064e\u0639\u064e\u0631\u064e\u0636\u0652\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0631\u0652\u0636\u064b\u0627",101,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u0650\u0637\u064e\u0627\u0621\u064d \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0645\u0652\u0639\u064b\u0627",102,"\u0623\u064e\u0641\u064e\u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0646\u064f\u0632\u064f\u0644\u064b\u0627",103,"\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u062e\u0652\u0633\u064e\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064b\u0627",104,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0639\u0652\u064a\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0646\u064e \u0635\u064f\u0646\u0652\u0639\u064b\u0627",105,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0626\u0650\u0647\u0650 \u0641\u064e\u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u0646\u064f\u0642\u0650\u064a\u0645\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u0632\u0652\u0646\u064b\u0627",106,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u064a \u0647\u064f\u0632\u064f\u0648\u064b\u0627",107,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0641\u0650\u0631\u0652\u062f\u064e\u0648\u0652\u0633\u0650 \u0646\u064f\u0632\u064f\u0644\u064b\u0627",108,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u062d\u0650\u0648\u064e\u0644\u064b\u0627",109,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064f \u0645\u0650\u062f\u064e\u0627\u062f\u064b\u0627 \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0646\u064e\u0641\u0650\u062f\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064f \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0641\u064e\u062f\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0645\u064e\u062f\u064e\u062f\u064b\u0627",110,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627"],t.v)
B.ac0=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0643\u0647\u064a\u0639\u0635",2,"\u0630\u0650\u0643\u0652\u0631\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0628\u0652\u062f\u064e\u0647\u064f \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627",3,"\u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0646\u0650\u062f\u064e\u0627\u0621\u064b \u062e\u064e\u0641\u0650\u064a\u0651\u064b\u0627",4,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0647\u064e\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0652\u0645\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0627\u0634\u0652\u062a\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u0623\u0652\u0633\u064f \u0634\u064e\u064a\u0652\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0643\u064f\u0646\u0652 \u0628\u0650\u062f\u064f\u0639\u064e\u0627\u0626\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0634\u064e\u0642\u0650\u064a\u0651\u064b\u0627",5,"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u062e\u0650\u0641\u0652\u062a\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u064e\u0627\u0644\u0650\u064a\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u064b\u0627 \u0641\u064e\u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652\u0643\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627",6,"\u064a\u064e\u0631\u0650\u062b\u064f\u0646\u0650\u064a \u0648\u064e\u064a\u064e\u0631\u0650\u062b\u064f \u0645\u0650\u0646\u0652 \u0622\u0644\u0650 \u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u06d6 \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0647\u064f \u0631\u064e\u0628\u0651\u0650 \u0631\u064e\u0636\u0650\u064a\u0651\u064b\u0627",7,"\u064a\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u063a\u064f\u0644\u064e\u0627\u0645\u064d \u0627\u0633\u0652\u0645\u064f\u0647\u064f \u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0633\u064e\u0645\u0650\u064a\u0651\u064b\u0627",8,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0627\u0645\u064c \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u064b\u0627 \u0648\u064e\u0642\u064e\u062f\u0652 \u0628\u064e\u0644\u064e\u063a\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u0650 \u0639\u0650\u062a\u0650\u064a\u0651\u064b\u0627",9,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u064a\u0651\u0650\u0646\u064c \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627",10,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0622\u064a\u064e\u0629\u064b \u06da \u0642\u064e\u0627\u0644\u064e \u0622\u064a\u064e\u062a\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062b\u064e\u0644\u064e\u0627\u062b\u064e \u0644\u064e\u064a\u064e\u0627\u0644\u064d \u0633\u064e\u0648\u0650\u064a\u0651\u064b\u0627",11,"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u0650\u062d\u0652\u0631\u064e\u0627\u0628\u0650 \u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0652 \u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0627 \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u064b\u0627",12,"\u064a\u064e\u0627 \u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u062e\u064f\u0630\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064e \u0635\u064e\u0628\u0650\u064a\u0651\u064b\u0627",13,"\u0648\u064e\u062d\u064e\u0646\u064e\u0627\u0646\u064b\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0632\u064e\u0643\u064e\u0627\u0629\u064b \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u064b\u0627",14,"\u0648\u064e\u0628\u064e\u0631\u0651\u064b\u0627 \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064b\u0627 \u0639\u064e\u0635\u0650\u064a\u0651\u064b\u0627",15,"\u0648\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0648\u064f\u0644\u0650\u062f\u064e \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f \u062d\u064e\u064a\u0651\u064b\u0627",16,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0625\u0650\u0630\u0650 \u0627\u0646\u0652\u062a\u064e\u0628\u064e\u0630\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0634\u064e\u0631\u0652\u0642\u0650\u064a\u0651\u064b\u0627",17,"\u0641\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u062d\u0650\u062c\u064e\u0627\u0628\u064b\u0627 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0631\u064f\u0648\u062d\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u0645\u064e\u062b\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0633\u064e\u0648\u0650\u064a\u0651\u064b\u0627",18,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0645\u0650\u0646\u0652\u0643\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u064b\u0627",19,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0644\u0650\u0623\u064e\u0647\u064e\u0628\u064e \u0644\u064e\u0643\u0650 \u063a\u064f\u0644\u064e\u0627\u0645\u064b\u0627 \u0632\u064e\u0643\u0650\u064a\u0651\u064b\u0627",20,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0627\u0645\u064c \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0646\u0650\u064a \u0628\u064e\u0634\u064e\u0631\u064c \u0648\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0643\u064f \u0628\u064e\u063a\u0650\u064a\u0651\u064b\u0627",21,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u064a\u0651\u0650\u0646\u064c \u06d6 \u0648\u064e\u0644\u0650\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064f \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0645\u064e\u0642\u0652\u0636\u0650\u064a\u0651\u064b\u0627",22,"\u0641\u064e\u062d\u064e\u0645\u064e\u0644\u064e\u062a\u0652\u0647\u064f \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0628\u064e\u0630\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0642\u064e\u0635\u0650\u064a\u0651\u064b\u0627",23,"\u0641\u064e\u0623\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u062e\u064e\u0627\u0636\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u0650\u0630\u0652\u0639\u0650 \u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064e\u0629\u0650 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u062a\u0651\u064f \u0642\u064e\u0628\u0652\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f \u0646\u064e\u0633\u0652\u064a\u064b\u0627 \u0645\u064e\u0646\u0652\u0633\u0650\u064a\u0651\u064b\u0627",24,"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0627\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0650\u064a \u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650 \u062a\u064e\u062d\u0652\u062a\u064e\u0643\u0650 \u0633\u064e\u0631\u0650\u064a\u0651\u064b\u0627",25,"\u0648\u064e\u0647\u064f\u0632\u0651\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u0650 \u0628\u0650\u062c\u0650\u0630\u0652\u0639\u0650 \u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064e\u0629\u0650 \u062a\u064f\u0633\u064e\u0627\u0642\u0650\u0637\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u0650 \u0631\u064f\u0637\u064e\u0628\u064b\u0627 \u062c\u064e\u0646\u0650\u064a\u0651\u064b\u0627",26,"\u0641\u064e\u0643\u064f\u0644\u0650\u064a \u0648\u064e\u0627\u0634\u0652\u0631\u064e\u0628\u0650\u064a \u0648\u064e\u0642\u064e\u0631\u0651\u0650\u064a \u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u064a\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0634\u064e\u0631\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0641\u064e\u0642\u064f\u0648\u0644\u0650\u064a \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0630\u064e\u0631\u0652\u062a\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0635\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0644\u064e\u0646\u0652 \u0623\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0625\u0650\u0646\u0652\u0633\u0650\u064a\u0651\u064b\u0627",27,"\u0641\u064e\u0623\u064e\u062a\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064f \u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0641\u064e\u0631\u0650\u064a\u0651\u064b\u0627",28,"\u064a\u064e\u0627 \u0623\u064f\u062e\u0652\u062a\u064e \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064f\u0648\u0643\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e \u0633\u064e\u0648\u0652\u0621\u064d \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0623\u064f\u0645\u0651\u064f\u0643\u0650 \u0628\u064e\u063a\u0650\u064a\u0651\u064b\u0627",29,"\u0641\u064e\u0623\u064e\u0634\u064e\u0627\u0631\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0647\u0652\u062f\u0650 \u0635\u064e\u0628\u0650\u064a\u0651\u064b\u0627",30,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u062a\u064e\u0627\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",31,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064b\u0627 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f \u0648\u064e\u0623\u064e\u0648\u0652\u0635\u064e\u0627\u0646\u0650\u064a \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u0650 \u0645\u064e\u0627 \u062f\u064f\u0645\u0652\u062a\u064f \u062d\u064e\u064a\u0651\u064b\u0627",32,"\u0648\u064e\u0628\u064e\u0631\u0651\u064b\u0627 \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064b\u0627 \u0634\u064e\u0642\u0650\u064a\u0651\u064b\u0627",33,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0648\u064f\u0644\u0650\u062f\u0652\u062a\u064f \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064f\u0628\u0652\u0639\u064e\u062b\u064f \u062d\u064e\u064a\u0651\u064b\u0627",34,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u06da \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0645\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",35,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u064e\u062f\u064d \u06d6 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06da \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",36,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u06da \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",37,"\u0641\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u0634\u0652\u0647\u064e\u062f\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",38,"\u0623\u064e\u0633\u0652\u0645\u0650\u0639\u0652 \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u0650\u0631\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u06d6 \u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",39,"\u0648\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u0652\u0631\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u0642\u064f\u0636\u0650\u064a\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",40,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0631\u0650\u062b\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",41,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u064b\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",42,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0643\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627",43,"\u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064e \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652\u0646\u0650\u064a \u0623\u064e\u0647\u0652\u062f\u0650\u0643\u064e \u0635\u0650\u0631\u064e\u0627\u0637\u064b\u0627 \u0633\u064e\u0648\u0650\u064a\u0651\u064b\u0627",44,"\u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0639\u064e\u0635\u0650\u064a\u0651\u064b\u0627",45,"\u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627",46,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0627\u063a\u0650\u0628\u064c \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0646\u0652 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u064a \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u06d6 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u0650 \u0644\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0645\u064e\u0646\u0651\u064e\u0643\u064e \u06d6 \u0648\u064e\u0627\u0647\u0652\u062c\u064f\u0631\u0652\u0646\u0650\u064a \u0645\u064e\u0644\u0650\u064a\u0651\u064b\u0627",47,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0633\u064e\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u064a \u062d\u064e\u0641\u0650\u064a\u0651\u064b\u0627",48,"\u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u0632\u0650\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062f\u0652\u0639\u064f\u0648 \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0644\u0651\u064e\u0627 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u062f\u064f\u0639\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0634\u064e\u0642\u0650\u064a\u0651\u064b\u0627",49,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0627\u0639\u0652\u062a\u064e\u0632\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",50,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u0633\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0639\u064e\u0644\u0650\u064a\u0651\u064b\u0627",51,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062e\u0652\u0644\u064e\u0635\u064b\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",52,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0646\u0650 \u0648\u064e\u0642\u064e\u0631\u0651\u064e\u0628\u0652\u0646\u064e\u0627\u0647\u064f \u0646\u064e\u062c\u0650\u064a\u0651\u064b\u0627",53,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",54,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0635\u064e\u0627\u062f\u0650\u0642\u064e \u0627\u0644\u0652\u0648\u064e\u0639\u0652\u062f\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",55,"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0645\u064e\u0631\u0652\u0636\u0650\u064a\u0651\u064b\u0627",56,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0625\u0650\u062f\u0652\u0631\u0650\u064a\u0633\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u064b\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627",57,"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0651\u064b\u0627",58,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0622\u062f\u064e\u0645\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0627\u062c\u0652\u062a\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0627 \u06da \u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u062e\u064e\u0631\u0651\u064f\u0648\u0627 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0628\u064f\u0643\u0650\u064a\u0651\u064b\u0627 \u06e9",59,"\u0641\u064e\u062e\u064e\u0644\u064e\u0641\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u0644\u0652\u0641\u064c \u0623\u064e\u0636\u064e\u0627\u0639\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0627\u062a\u0650 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0646\u064e \u063a\u064e\u064a\u0651\u064b\u0627",60,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627",61,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0639\u064e\u062f\u0652\u0646\u064d \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u0652\u062f\u064f\u0647\u064f \u0645\u064e\u0623\u0652\u062a\u0650\u064a\u0651\u064b\u0627",62,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u0652\u0648\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0632\u0652\u0642\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u064b\u0627",63,"\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0646\u064f\u0648\u0631\u0650\u062b\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u064b\u0627",64,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0646\u064e\u0633\u0650\u064a\u0651\u064b\u0627",65,"\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0652\u0647\u064f \u0648\u064e\u0627\u0635\u0652\u0637\u064e\u0628\u0650\u0631\u0652 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650 \u06da \u0647\u064e\u0644\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0644\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0651\u064b\u0627",66,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0645\u0650\u062a\u0651\u064f \u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u062c\u064f \u062d\u064e\u064a\u0651\u064b\u0627",67,"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627",68,"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064f\u062d\u0652\u0636\u0650\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0648\u0652\u0644\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u0650\u062b\u0650\u064a\u0651\u064b\u0627",69,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0646\u0652\u0632\u0650\u0639\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u0650\u064a\u0639\u064e\u0629\u064d \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0639\u0650\u062a\u0650\u064a\u0651\u064b\u0627",70,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u0635\u0650\u0644\u0650\u064a\u0651\u064b\u0627",71,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064f\u0647\u064e\u0627 \u06da \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062d\u064e\u062a\u0652\u0645\u064b\u0627 \u0645\u064e\u0642\u0652\u0636\u0650\u064a\u0651\u064b\u0627",72,"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u0650\u062b\u0650\u064a\u0651\u064b\u0627",73,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u0652\u0646\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u064e\u0642\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0646\u064e\u062f\u0650\u064a\u0651\u064b\u0627",74,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u0646\u064d \u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0623\u064e\u062b\u064e\u0627\u062b\u064b\u0627 \u0648\u064e\u0631\u0650\u0626\u0652\u064a\u064b\u0627",75,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0645\u0652\u062f\u064f\u062f\u0652 \u0644\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0645\u064e\u062f\u0651\u064b\u0627 \u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0641\u064e\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u064c \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0636\u0652\u0639\u064e\u0641\u064f \u062c\u064f\u0646\u0652\u062f\u064b\u0627",76,"\u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u0647\u064f\u062f\u064b\u0649 \u06d7 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064c \u0645\u064e\u0631\u064e\u062f\u0651\u064b\u0627",77,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064f\u0648\u062a\u064e\u064a\u064e\u0646\u0651\u064e \u0645\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u064b\u0627",78,"\u0623\u064e\u0637\u0651\u064e\u0644\u064e\u0639\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0639\u064e\u0647\u0652\u062f\u064b\u0627",79,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06da \u0633\u064e\u0646\u064e\u0643\u0652\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0646\u064e\u0645\u064f\u062f\u0651\u064f \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064e\u062f\u0651\u064b\u0627",80,"\u0648\u064e\u0646\u064e\u0631\u0650\u062b\u064f\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0641\u064e\u0631\u0652\u062f\u064b\u0627",81,"\u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u0650\u0632\u0651\u064b\u0627",82,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06da \u0633\u064e\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0636\u0650\u062f\u0651\u064b\u0627",83,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062a\u064e\u0624\u064f\u0632\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0632\u0651\u064b\u0627",84,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062c\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u0651\u064b\u0627",85,"\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0648\u064e\u0641\u0652\u062f\u064b\u0627",86,"\u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0642\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0648\u0650\u0631\u0652\u062f\u064b\u0627",87,"\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0639\u064e\u0647\u0652\u062f\u064b\u0627",88,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627",89,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u062f\u0651\u064b\u0627",90,"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u064a\u064e\u062a\u064e\u0641\u064e\u0637\u0651\u064e\u0631\u0652\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u062a\u064e\u0646\u0652\u0634\u064e\u0642\u0651\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u062a\u064e\u062e\u0650\u0631\u0651\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0647\u064e\u062f\u0651\u064b\u0627",91,"\u0623\u064e\u0646\u0652 \u062f\u064e\u0639\u064e\u0648\u0652\u0627 \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u062f\u064b\u0627",92,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0648\u064e\u0644\u064e\u062f\u064b\u0627",93,"\u0625\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0622\u062a\u0650\u064a \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u064b\u0627",94,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u0652\u0635\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u0651\u064b\u0627",95,"\u0648\u064e\u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u0652 \u0622\u062a\u0650\u064a\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u064e\u0631\u0652\u062f\u064b\u0627",96,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064f\u062f\u0651\u064b\u0627",97,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064f\u062f\u0651\u064b\u0627",98,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u0646\u064d \u0647\u064e\u0644\u0652 \u062a\u064f\u062d\u0650\u0633\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0623\u064e\u0648\u0652 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0643\u0652\u0632\u064b\u0627"],t.v)
B.apo=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0637\u0647",2,"\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0644\u0650\u062a\u064e\u0634\u0652\u0642\u064e\u0649\u0670",3,"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064b \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",4,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0639\u064f\u0644\u064e\u0649",5,"\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670",6,"\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u062a\u064e \u0627\u0644\u062b\u0651\u064e\u0631\u064e\u0649\u0670",7,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062c\u0652\u0647\u064e\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0633\u0651\u0650\u0631\u0651\u064e \u0648\u064e\u0623\u064e\u062e\u0652\u0641\u064e\u0649",8,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670",9,"\u0648\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670",10,"\u0625\u0650\u0630\u0652 \u0631\u064e\u0623\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0627\u0645\u0652\u0643\u064f\u062b\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0622\u0646\u064e\u0633\u0652\u062a\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0622\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u0642\u064e\u0628\u064e\u0633\u064d \u0623\u064e\u0648\u0652 \u0623\u064e\u062c\u0650\u062f\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u062f\u064b\u0649",11,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",12,"\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u0627\u062e\u0652\u0644\u064e\u0639\u0652 \u0646\u064e\u0639\u0652\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u0650 \u0637\u064f\u0648\u064b\u0649",13,"\u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0631\u0652\u062a\u064f\u0643\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u0652 \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670",14,"\u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0652\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0644\u0650\u0630\u0650\u0643\u0652\u0631\u0650\u064a",15,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0622\u062a\u0650\u064a\u064e\u0629\u064c \u0623\u064e\u0643\u064e\u0627\u062f\u064f \u0623\u064f\u062e\u0652\u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u062a\u064f\u062c\u0652\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u0639\u064e\u0649\u0670",16,"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0641\u064e\u062a\u064e\u0631\u0652\u062f\u064e\u0649\u0670",17,"\u0648\u064e\u0645\u064e\u0627 \u062a\u0650\u0644\u0652\u0643\u064e \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",18,"\u0642\u064e\u0627\u0644\u064e \u0647\u0650\u064a\u064e \u0639\u064e\u0635\u064e\u0627\u064a\u064e \u0623\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0623\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u064f\u0634\u0651\u064f \u0628\u0650\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u0646\u064e\u0645\u0650\u064a \u0648\u064e\u0644\u0650\u064a\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0622\u0631\u0650\u0628\u064f \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",19,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u0652\u0642\u0650\u0647\u064e\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",20,"\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062d\u064e\u064a\u0651\u064e\u0629\u064c \u062a\u064e\u0633\u0652\u0639\u064e\u0649\u0670",21,"\u0642\u064e\u0627\u0644\u064e \u062e\u064f\u0630\u0652\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0633\u064e\u0646\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064e\u0627 \u0633\u0650\u064a\u0631\u064e\u062a\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",22,"\u0648\u064e\u0627\u0636\u0652\u0645\u064f\u0645\u0652 \u064a\u064e\u062f\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0646\u064e\u0627\u062d\u0650\u0643\u064e \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u0652 \u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0648\u0621\u064d \u0622\u064a\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",23,"\u0644\u0650\u0646\u064f\u0631\u0650\u064a\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649",24,"\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0637\u064e\u063a\u064e\u0649\u0670",25,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0634\u0652\u0631\u064e\u062d\u0652 \u0644\u0650\u064a \u0635\u064e\u062f\u0652\u0631\u0650\u064a",26,"\u0648\u064e\u064a\u064e\u0633\u0651\u0650\u0631\u0652 \u0644\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u0650\u064a",27,"\u0648\u064e\u0627\u062d\u0652\u0644\u064f\u0644\u0652 \u0639\u064f\u0642\u0652\u062f\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0644\u0650\u0633\u064e\u0627\u0646\u0650\u064a",28,"\u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u0650\u064a",29,"\u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0648\u064e\u0632\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u064a",30,"\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062e\u0650\u064a",31,"\u0627\u0634\u0652\u062f\u064f\u062f\u0652 \u0628\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0631\u0650\u064a",32,"\u0648\u064e\u0623\u064e\u0634\u0652\u0631\u0650\u0643\u0652\u0647\u064f \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u0650\u064a",33,"\u0643\u064e\u064a\u0652 \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",34,"\u0648\u064e\u0646\u064e\u0630\u0652\u0643\u064f\u0631\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",35,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0643\u064f\u0646\u0652\u062a\u064e \u0628\u0650\u0646\u064e\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",36,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064e \u0633\u064f\u0624\u0652\u0644\u064e\u0643\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",37,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",38,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u0650\u0643\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670",39,"\u0623\u064e\u0646\u0650 \u0627\u0642\u0652\u0630\u0650\u0641\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u062a\u0651\u064e\u0627\u0628\u064f\u0648\u062a\u0650 \u0641\u064e\u0627\u0642\u0652\u0630\u0650\u0641\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0641\u064e\u0644\u0652\u064a\u064f\u0644\u0652\u0642\u0650\u0647\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u064f \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0644\u0650 \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u0652\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u064a\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u064e\u062d\u064e\u0628\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0644\u0650\u062a\u064f\u0635\u0652\u0646\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u064a\u0652\u0646\u0650\u064a",40,"\u0625\u0650\u0630\u0652 \u062a\u064e\u0645\u0652\u0634\u0650\u064a \u0623\u064f\u062e\u0652\u062a\u064f\u0643\u064e \u0641\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0644\u0652 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0644\u064f\u0647\u064f \u06d6 \u0641\u064e\u0631\u064e\u062c\u064e\u0639\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u0650\u0643\u064e \u0643\u064e\u064a\u0652 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0639\u064e\u064a\u0652\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064e \u06da \u0648\u064e\u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064e \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0645\u0651\u0650 \u0648\u064e\u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627\u0643\u064e \u0641\u064f\u062a\u064f\u0648\u0646\u064b\u0627 \u06da \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0647\u0652\u0644\u0650 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u062c\u0650\u0626\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u064e\u0631\u064d \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",41,"\u0648\u064e\u0627\u0635\u0652\u0637\u064e\u0646\u064e\u0639\u0652\u062a\u064f\u0643\u064e \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u064a",42,"\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0623\u064e\u062e\u064f\u0648\u0643\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0650\u064a\u064e\u0627 \u0641\u0650\u064a \u0630\u0650\u0643\u0652\u0631\u0650\u064a",43,"\u0627\u0630\u0652\u0647\u064e\u0628\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0637\u064e\u063a\u064e\u0649\u0670",44,"\u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0644\u064e\u064a\u0651\u0650\u0646\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064e\u0648\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",45,"\u0642\u064e\u0627\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0631\u064f\u0637\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0637\u0652\u063a\u064e\u0649\u0670",46,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0648\u064e\u0623\u064e\u0631\u064e\u0649\u0670",47,"\u0641\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0627\u0647\u064f \u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670",48,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062f\u0652 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",49,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0646\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064e\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",50,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0639\u0652\u0637\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0647\u064e\u062f\u064e\u0649\u0670",51,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0627\u0644\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",52,"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u0644\u0652\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0633\u064e\u0649",53,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u064e\u0647\u0652\u062f\u064b\u0627 \u0648\u064e\u0633\u064e\u0644\u064e\u0643\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u064e\u0627\u062a\u064d \u0634\u064e\u062a\u0651\u064e\u0649\u0670",54,"\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0631\u0652\u0639\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0646\u0651\u064f\u0647\u064e\u0649\u0670",55,"\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064f\u0639\u0650\u064a\u062f\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u0652 \u062a\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",56,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u0623\u064e\u0628\u064e\u0649\u0670",57,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0646\u064e\u0627 \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u0650\u0643\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",58,"\u0641\u064e\u0644\u064e\u0646\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u064d \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0641\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064b\u0627 \u0644\u064e\u0627 \u0646\u064f\u062e\u0652\u0644\u0650\u0641\u064f\u0647\u064f \u0646\u064e\u062d\u0652\u0646\u064f \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0633\u064f\u0648\u064b\u0649",59,"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0632\u0651\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0636\u064f\u062d\u064b\u0649",60,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0641\u064e\u062c\u064e\u0645\u064e\u0639\u064e \u0643\u064e\u064a\u0652\u062f\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u064e\u0649\u0670",61,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u064a\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0641\u064e\u064a\u064f\u0633\u0652\u062d\u0650\u062a\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u06d6 \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670",62,"\u0641\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0648\u064e\u0649\u0670",63,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627\u0646\u0650 \u0644\u064e\u0633\u064e\u0627\u062d\u0650\u0631\u064e\u0627\u0646\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064e\u0627\u0646\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u064a\u064e\u0630\u0652\u0647\u064e\u0628\u064e\u0627 \u0628\u0650\u0637\u064e\u0631\u0650\u064a\u0642\u064e\u062a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062b\u0652\u0644\u064e\u0649\u0670",64,"\u0641\u064e\u0623\u064e\u062c\u0652\u0645\u0650\u0639\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u062f\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0627\u0626\u0652\u062a\u064f\u0648\u0627 \u0635\u064e\u0641\u0651\u064b\u0627 \u06da \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0641\u0652\u0644\u064e\u062d\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0639\u0652\u0644\u064e\u0649\u0670",65,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670",66,"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u0650\u0628\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u0650\u0635\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u064a\u064f\u062e\u064e\u064a\u0651\u064e\u0644\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0633\u0650\u062d\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0633\u0652\u0639\u064e\u0649\u0670",67,"\u0641\u064e\u0623\u064e\u0648\u0652\u062c\u064e\u0633\u064e \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u062e\u0650\u064a\u0641\u064e\u0629\u064b \u0645\u064f\u0648\u0633\u064e\u0649\u0670",68,"\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670",69,"\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u0652 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u062f\u064f \u0633\u064e\u0627\u062d\u0650\u0631\u064d \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u062a\u064e\u0649\u0670",70,"\u0641\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670",71,"\u0642\u064e\u0627\u0644\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u0622\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064e \u06d6 \u0641\u064e\u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064d \u0648\u064e\u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u062c\u064f\u0630\u064f\u0648\u0639\u0650 \u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u0650 \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0646\u0651\u064e \u0623\u064e\u064a\u0651\u064f\u0646\u064e\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",72,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u062b\u0650\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0642\u0652\u0636\u0650 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0642\u064e\u0627\u0636\u064d \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u0642\u0652\u0636\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627",73,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u0650\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0643\u0652\u0631\u064e\u0647\u0652\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",74,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670",75,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u0642\u064e\u062f\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u062f\u0651\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0639\u064f\u0644\u064e\u0649\u0670",76,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0645\u064e\u0646\u0652 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",77,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0641\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u064a\u064e\u0628\u064e\u0633\u064b\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f \u062f\u064e\u0631\u064e\u0643\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",78,"\u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650 \u0641\u064e\u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0645\u064e\u0627 \u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645\u0652",79,"\u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0649\u0670",80,"\u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0648\u064e\u0627\u0639\u064e\u062f\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u062c\u064e\u0627\u0646\u0650\u0628\u064e \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0646\u064e \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u0652\u0648\u064e\u0649\u0670",81,"\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u0652\u063a\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u063a\u064e\u0636\u064e\u0628\u0650\u064a \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0644\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u063a\u064e\u0636\u064e\u0628\u0650\u064a \u0641\u064e\u0642\u064e\u062f\u0652 \u0647\u064e\u0648\u064e\u0649\u0670",82,"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u064c \u0644\u0650\u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670",83,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u062c\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0643\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",84,"\u0642\u064e\u0627\u0644\u064e \u0647\u064f\u0645\u0652 \u0623\u064f\u0648\u0644\u064e\u0627\u0621\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062b\u064e\u0631\u0650\u064a \u0648\u064e\u0639\u064e\u062c\u0650\u0644\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u0650\u062a\u064e\u0631\u0652\u0636\u064e\u0649\u0670",85,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062f\u0652 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0645\u0650\u0631\u0650\u064a\u0651\u064f",86,"\u0641\u064e\u0631\u064e\u062c\u064e\u0639\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u063a\u064e\u0636\u0652\u0628\u064e\u0627\u0646\u064e \u0623\u064e\u0633\u0650\u0641\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0650\u062f\u0652\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0623\u064e\u0641\u064e\u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0647\u0652\u062f\u064f \u0623\u064e\u0645\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0650\u0644\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u063a\u064e\u0636\u064e\u0628\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062e\u0652\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u0650\u064a",87,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0644\u064e\u0641\u0652\u0646\u064e\u0627 \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0644\u0652\u0643\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u0652\u0646\u064e\u0627 \u0623\u064e\u0648\u0652\u0632\u064e\u0627\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0632\u0650\u064a\u0646\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0641\u064e\u0642\u064e\u0630\u064e\u0641\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0644\u0652\u0642\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0627\u0645\u0650\u0631\u0650\u064a\u0651\u064f",88,"\u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u0650\u062c\u0652\u0644\u064b\u0627 \u062c\u064e\u0633\u064e\u062f\u064b\u0627 \u0644\u064e\u0647\u064f \u062e\u064f\u0648\u064e\u0627\u0631\u064c \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e",89,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u0652\u0639\u064b\u0627",90,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u064f\u062a\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u0650\u064a",91,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064e\u0628\u0652\u0631\u064e\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0627\u0643\u0650\u0641\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",92,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0625\u0650\u0630\u0652 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627",93,"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e\u0646\u0650 \u06d6 \u0623\u064e\u0641\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u064a",94,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0627\u0628\u0652\u0646\u064e \u0623\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u0652 \u0628\u0650\u0644\u0650\u062d\u0652\u064a\u064e\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0631\u064e\u0623\u0652\u0633\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0634\u0650\u064a\u062a\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u0652\u062a\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u0652\u0642\u064f\u0628\u0652 \u0642\u064e\u0648\u0652\u0644\u0650\u064a",95,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u062e\u064e\u0637\u0652\u0628\u064f\u0643\u064e \u064a\u064e\u0627 \u0633\u064e\u0627\u0645\u0650\u0631\u0650\u064a\u0651\u064f",96,"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0635\u064f\u0631\u0652\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0628\u0652\u0635\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u0642\u064e\u0628\u064e\u0636\u0652\u062a\u064f \u0642\u064e\u0628\u0652\u0636\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0623\u064e\u062b\u064e\u0631\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u0652\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u0652 \u0644\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u064a",97,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0627 \u0645\u0650\u0633\u064e\u0627\u0633\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064b\u0627 \u0644\u064e\u0646\u0652 \u062a\u064f\u062e\u0652\u0644\u064e\u0641\u064e\u0647\u064f \u06d6 \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0644\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0627\u0643\u0650\u0641\u064b\u0627 \u06d6 \u0644\u064e\u0646\u064f\u062d\u064e\u0631\u0651\u0650\u0642\u064e\u0646\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0646\u0652\u0633\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0646\u064e\u0633\u0652\u0641\u064b\u0627",98,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0644\u0652\u0645\u064b\u0627",99,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0645\u064e\u0627 \u0642\u064e\u062f\u0652 \u0633\u064e\u0628\u064e\u0642\u064e \u06da \u0648\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064b\u0627",100,"\u0645\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u0650\u0632\u0652\u0631\u064b\u0627",101,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0648\u064e\u0633\u064e\u0627\u0621\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u062d\u0650\u0645\u0652\u0644\u064b\u0627",102,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u0652\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u06da \u0648\u064e\u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0632\u064f\u0631\u0652\u0642\u064b\u0627",103,"\u064a\u064e\u062a\u064e\u062e\u064e\u0627\u0641\u064e\u062a\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0634\u0652\u0631\u064b\u0627",104,"\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0645\u0652\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0637\u064e\u0631\u0650\u064a\u0642\u064e\u0629\u064b \u0625\u0650\u0646\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627",105,"\u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0641\u064e\u0642\u064f\u0644\u0652 \u064a\u064e\u0646\u0652\u0633\u0650\u0641\u064f\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u0646\u064e\u0633\u0652\u0641\u064b\u0627",106,"\u0641\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0647\u064e\u0627 \u0642\u064e\u0627\u0639\u064b\u0627 \u0635\u064e\u0641\u0652\u0635\u064e\u0641\u064b\u0627",107,"\u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0645\u0652\u062a\u064b\u0627",108,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0639\u0650\u064a\u064e \u0644\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064e \u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u062e\u064e\u0634\u064e\u0639\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0635\u0652\u0648\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064e\u0645\u0652\u0633\u064b\u0627",109,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064e\u0631\u064e\u0636\u0650\u064a\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0644\u064b\u0627",110,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064b\u0627",111,"\u0648\u064e\u0639\u064e\u0646\u064e\u062a\u0650 \u0627\u0644\u0652\u0648\u064f\u062c\u064f\u0648\u0647\u064f \u0644\u0650\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u0650 \u06d6 \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u0652 \u062d\u064e\u0645\u064e\u0644\u064e \u0638\u064f\u0644\u0652\u0645\u064b\u0627",112,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064e\u0636\u0652\u0645\u064b\u0627",113,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0648\u064e\u0639\u0650\u064a\u062f\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0652 \u064a\u064f\u062d\u0652\u062f\u0650\u062b\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064b\u0627",114,"\u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062c\u064e\u0644\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0642\u0652\u0636\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u062d\u0652\u064a\u064f\u0647\u064f \u06d6 \u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0632\u0650\u062f\u0652\u0646\u0650\u064a \u0639\u0650\u0644\u0652\u0645\u064b\u0627",115,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0622\u062f\u064e\u0645\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0639\u064e\u0632\u0652\u0645\u064b\u0627",116,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0622\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670",117,"\u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u064a\u064e\u0627 \u0622\u062f\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u064e\u0643\u064e \u0648\u064e\u0644\u0650\u0632\u064e\u0648\u0652\u062c\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0641\u064e\u062a\u064e\u0634\u0652\u0642\u064e\u0649\u0670",118,"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u064f\u0648\u0639\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0631\u064e\u0649\u0670",119,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0638\u0652\u0645\u064e\u0623\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u0652\u062d\u064e\u0649\u0670",120,"\u0641\u064e\u0648\u064e\u0633\u0652\u0648\u064e\u0633\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0622\u062f\u064e\u0645\u064f \u0647\u064e\u0644\u0652 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u0650 \u0648\u064e\u0645\u064f\u0644\u0652\u0643\u064d \u0644\u064e\u0627 \u064a\u064e\u0628\u0652\u0644\u064e\u0649\u0670",121,"\u0641\u064e\u0623\u064e\u0643\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0628\u064e\u062f\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u0652\u0622\u062a\u064f\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0637\u064e\u0641\u0650\u0642\u064e\u0627 \u064a\u064e\u062e\u0652\u0635\u0650\u0641\u064e\u0627\u0646\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0642\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06da \u0648\u064e\u0639\u064e\u0635\u064e\u0649\u0670 \u0622\u062f\u064e\u0645\u064f \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0641\u064e\u063a\u064e\u0648\u064e\u0649\u0670",122,"\u062b\u064f\u0645\u0651\u064e \u0627\u062c\u0652\u062a\u064e\u0628\u064e\u0627\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0647\u064e\u062f\u064e\u0649\u0670",123,"\u0642\u064e\u0627\u0644\u064e \u0627\u0647\u0652\u0628\u0650\u0637\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u0650\u064a \u0647\u064f\u062f\u064b\u0649 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064f\u062f\u064e\u0627\u064a\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0642\u064e\u0649\u0670",124,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u0629\u064b \u0636\u064e\u0646\u0652\u0643\u064b\u0627 \u0648\u064e\u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670",125,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u0650\u0645\u064e \u062d\u064e\u0634\u064e\u0631\u0652\u062a\u064e\u0646\u0650\u064a \u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",126,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062a\u064e\u062a\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u062a\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u0646\u0652\u0633\u064e\u0649\u0670",127,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0631\u064e\u0641\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",128,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0646\u0651\u064f\u0647\u064e\u0649\u0670",129,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0632\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u064c \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649",130,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0642\u064e\u0628\u0652\u0644\u064e \u0637\u064f\u0644\u064f\u0648\u0639\u0650 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u0642\u064e\u0628\u0652\u0644\u064e \u063a\u064f\u0631\u064f\u0648\u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u0646\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0648\u064e\u0623\u064e\u0637\u0652\u0631\u064e\u0627\u0641\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u062a\u064e\u0631\u0652\u0636\u064e\u0649\u0670",131,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u062f\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u064a\u0652\u0646\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0632\u064e\u0647\u0652\u0631\u064e\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u0650\u0646\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",132,"\u0648\u064e\u0623\u0652\u0645\u064f\u0631\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0635\u0652\u0637\u064e\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d6 \u0644\u064e\u0627 \u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u06d6 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064e \u06d7 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670",133,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",134,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0622\u064a\u064e\u0627\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u0630\u0650\u0644\u0651\u064e \u0648\u064e\u0646\u064e\u062e\u0652\u0632\u064e\u0649\u0670",135,"\u0642\u064f\u0644\u0652 \u0643\u064f\u0644\u0651\u064c \u0645\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u064c \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0633\u0651\u064e\u0648\u0650\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670"],t.v)
B.aom=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0642\u0652\u062a\u064e\u0631\u064e\u0628\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",2,"\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u062d\u0652\u062f\u064e\u062b\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0644\u0652\u0639\u064e\u0628\u064f\u0648\u0646\u064e",3,"\u0644\u064e\u0627\u0647\u0650\u064a\u064e\u0629\u064b \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0648\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0647\u064e\u0644\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0641\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",4,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",5,"\u0628\u064e\u0644\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0636\u0652\u063a\u064e\u0627\u062b\u064f \u0623\u064e\u062d\u0652\u0644\u064e\u0627\u0645\u064d \u0628\u064e\u0644\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0634\u064e\u0627\u0639\u0650\u0631\u064c \u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0643\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",6,"\u0645\u064e\u0627 \u0622\u0645\u064e\u0646\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u06d6 \u0623\u064e\u0641\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0646\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",8,"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062c\u064e\u0633\u064e\u062f\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e",9,"\u062b\u064f\u0645\u0651\u064e \u0635\u064e\u062f\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u0639\u0652\u062f\u064e \u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",10,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0641\u0650\u064a\u0647\u0650 \u0630\u0650\u0643\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",11,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0642\u064e\u0635\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",12,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062d\u064e\u0633\u0651\u064f\u0648\u0627 \u0628\u064e\u0623\u0652\u0633\u064e\u0646\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u064a\u064e\u0631\u0652\u0643\u064f\u0636\u064f\u0648\u0646\u064e",13,"\u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u0643\u064f\u0636\u064f\u0648\u0627 \u0648\u064e\u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064f\u062a\u0652\u0631\u0650\u0641\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e",14,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",15,"\u0641\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u0644\u064e\u062a\u0652 \u062a\u0650\u0644\u0652\u0643\u064e \u062f\u064e\u0639\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062d\u064e\u0635\u0650\u064a\u062f\u064b\u0627 \u062e\u064e\u0627\u0645\u0650\u062f\u0650\u064a\u0646\u064e",16,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0627\u0639\u0650\u0628\u0650\u064a\u0646\u064e",17,"\u0644\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0644\u064e\u0647\u0652\u0648\u064b\u0627 \u0644\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",18,"\u0628\u064e\u0644\u0652 \u0646\u064e\u0642\u0652\u0630\u0650\u0641\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0641\u064e\u064a\u064e\u062f\u0652\u0645\u064e\u063a\u064f\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u0632\u064e\u0627\u0647\u0650\u0642\u064c \u06da \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u064a\u0652\u0644\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u0633\u0650\u0631\u064f\u0648\u0646\u064e",20,"\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u064f\u0631\u064f\u0648\u0646\u064e",21,"\u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e",22,"\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u064e\u0627 \u06da \u0641\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",23,"\u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e",24,"\u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u06d6 \u0642\u064f\u0644\u0652 \u0647\u064e\u0627\u062a\u064f\u0648\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064f \u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064f \u0645\u064e\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u064a \u06d7 \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06d6 \u0641\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u0650",26,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u06d7 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064c \u0645\u064f\u0643\u0652\u0631\u064e\u0645\u064f\u0648\u0646\u064e",27,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0628\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",28,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u0631\u0652\u062a\u064e\u0636\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u062a\u0650\u0647\u0650 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",29,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0644\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",30,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u0631\u064e\u062a\u0652\u0642\u064b\u0627 \u0641\u064e\u0641\u064e\u062a\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u064a\u0651\u064d \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u0650\u062c\u064e\u0627\u062c\u064b\u0627 \u0633\u064f\u0628\u064f\u0644\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",32,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0633\u064e\u0642\u0652\u0641\u064b\u0627 \u0645\u064e\u062d\u0652\u0641\u064f\u0648\u0638\u064b\u0627 \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u064e\u0627 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u06d6 \u0643\u064f\u0644\u0651\u064c \u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0643\u064d \u064a\u064e\u0633\u0652\u0628\u064e\u062d\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u064e \u06d6 \u0623\u064e\u0641\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u062a\u0651\u064e \u0641\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",35,"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0630\u064e\u0627\u0626\u0650\u0642\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06d7 \u0648\u064e\u0646\u064e\u0628\u0652\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0622\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0623\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f \u0622\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",37,"\u062e\u064f\u0644\u0650\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u0650\u0646\u0652 \u0639\u064e\u062c\u064e\u0644\u064d \u06da \u0633\u064e\u0623\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u0650",38,u.k,39,"\u0644\u064e\u0648\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u062d\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0641\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0646\u0652 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",40,"\u0628\u064e\u0644\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0641\u064e\u062a\u064e\u0628\u0652\u0647\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u062f\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",41,u.ai,42,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0644\u064e\u0624\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u06d7 \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",43,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u0644\u0650\u0647\u064e\u0629\u064c \u062a\u064e\u0645\u0652\u0646\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0646\u064e\u0627 \u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u0652\u0631\u064e \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u064a\u064f\u0635\u0652\u062d\u064e\u0628\u064f\u0648\u0646\u064e",44,"\u0628\u064e\u0644\u0652 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0648\u064e\u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u064f \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0623\u0652\u062a\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0646\u064e\u0646\u0652\u0642\u064f\u0635\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0637\u0652\u0631\u064e\u0627\u0641\u0650\u0647\u064e\u0627 \u06da \u0623\u064e\u0641\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",45,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u062d\u0652\u064a\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064f \u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0646\u0652\u0630\u064e\u0631\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0645\u064e\u0633\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u062d\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",47,"\u0648\u064e\u0646\u064e\u0636\u064e\u0639\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u064e \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u062e\u064e\u0631\u0652\u062f\u064e\u0644\u064d \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0646\u064e\u0627 \u062d\u064e\u0627\u0633\u0650\u0628\u0650\u064a\u0646\u064e",48,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064e \u0648\u064e\u0636\u0650\u064a\u064e\u0627\u0621\u064b \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064b\u0627 \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",49,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0645\u064f\u0646\u0652\u0643\u0650\u0631\u064f\u0648\u0646\u064e",51,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0631\u064f\u0634\u0652\u062f\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0639\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",52,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062a\u0651\u064e\u0645\u064e\u0627\u062b\u0650\u064a\u0644\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0643\u0650\u0641\u064f\u0648\u0646\u064e",53,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0628\u0650\u062f\u0650\u064a\u0646\u064e",54,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",55,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0627\u0639\u0650\u0628\u0650\u064a\u0646\u064e",56,"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0623\u064e\u0643\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0623\u064e\u0646\u0652 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",58,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064f\u0630\u064e\u0627\u0630\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",59,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u0641\u064e\u0639\u064e\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u0650\u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",60,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u062a\u064b\u0649 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0644\u064e\u0647\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f",61,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e",62,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u0650\u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f",63,"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u0652 \u0641\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0647\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",64,"\u0641\u064e\u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",65,"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0643\u0650\u0633\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",66,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0641\u064e\u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645\u0652",67,"\u0623\u064f\u0641\u0651\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",68,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062d\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0627\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0627 \u0622\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",69,"\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u064a\u064e\u0627 \u0646\u064e\u0627\u0631\u064f \u0643\u064f\u0648\u0646\u0650\u064a \u0628\u064e\u0631\u0652\u062f\u064b\u0627 \u0648\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",70,"\u0648\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0643\u064e\u064a\u0652\u062f\u064b\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u0633\u064e\u0631\u0650\u064a\u0646\u064e",71,"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",72,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0646\u064e\u0627\u0641\u0650\u0644\u064e\u0629\u064b \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",73,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064b \u064a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u0650\u0639\u0652\u0644\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0625\u0650\u0642\u064e\u0627\u0645\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0621\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u0650 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0627\u0628\u0650\u062f\u0650\u064a\u0646\u064e",74,"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u064e\u0627\u0626\u0650\u062b\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e \u0633\u064e\u0648\u0652\u0621\u064d \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",75,"\u0648\u064e\u0623\u064e\u062f\u0652\u062e\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",76,"\u0648\u064e\u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0652\u0628\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",77,"\u0648\u064e\u0646\u064e\u0635\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064e \u0633\u064e\u0648\u0652\u0621\u064d \u0641\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",78,"\u0648\u064e\u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0625\u0650\u0630\u0652 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e\u0627\u0646\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u062b\u0650 \u0625\u0650\u0630\u0652 \u0646\u064e\u0641\u064e\u0634\u064e\u062a\u0652 \u0641\u0650\u064a\u0647\u0650 \u063a\u064e\u0646\u064e\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u062d\u064f\u0643\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0634\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",79,"\u0641\u064e\u0641\u064e\u0647\u0651\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06da \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u0652\u0646\u064e \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064e \u06da \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",80,"\u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f \u0635\u064e\u0646\u0652\u0639\u064e\u0629\u064e \u0644\u064e\u0628\u064f\u0648\u0633\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u062a\u064f\u062d\u0652\u0635\u0650\u0646\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0623\u0652\u0633\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0634\u064e\u0627\u0643\u0650\u0631\u064f\u0648\u0646\u064e",81,"\u0648\u064e\u0644\u0650\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0639\u064e\u0627\u0635\u0650\u0641\u064e\u0629\u064b \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",82,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u063a\u064f\u0648\u0635\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0627\u0641\u0650\u0638\u0650\u064a\u0646\u064e",83,"\u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0623\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",84,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u064e\u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0636\u064f\u0631\u0651\u064d \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0628\u0650\u062f\u0650\u064a\u0646\u064e",85,"\u0648\u064e\u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u062f\u0652\u0631\u0650\u064a\u0633\u064e \u0648\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u0641\u0652\u0644\u0650 \u06d6 \u0643\u064f\u0644\u0651\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",86,"\u0648\u064e\u0623\u064e\u062f\u0652\u062e\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0630\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u0648\u0646\u0650 \u0625\u0650\u0630\u0652 \u0630\u064e\u0647\u064e\u0628\u064e \u0645\u064f\u063a\u064e\u0627\u0636\u0650\u0628\u064b\u0627 \u0641\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u0646\u064e\u0642\u0652\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",88,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0645\u0651\u0650 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0646\u0652\u062c\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",89,"\u0648\u064e\u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u0652\u0646\u0650\u064a \u0641\u064e\u0631\u0652\u062f\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u0650\u064a\u0646\u064e",90,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0632\u064e\u0648\u0652\u062c\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0631\u064e\u063a\u064e\u0628\u064b\u0627 \u0648\u064e\u0631\u064e\u0647\u064e\u0628\u064b\u0627 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u0627\u0634\u0650\u0639\u0650\u064a\u0646\u064e",91,"\u0648\u064e\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u062d\u0652\u0635\u064e\u0646\u064e\u062a\u0652 \u0641\u064e\u0631\u0652\u062c\u064e\u0647\u064e\u0627 \u0641\u064e\u0646\u064e\u0641\u064e\u062e\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0631\u064f\u0648\u062d\u0650\u0646\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0652\u0646\u064e\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",92,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0623\u064f\u0645\u0651\u064e\u062a\u064f\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u0650",93,"\u0648\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0643\u064f\u0644\u0651\u064c \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e",94,"\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0644\u064e\u0627 \u0643\u064f\u0641\u0652\u0631\u064e\u0627\u0646\u064e \u0644\u0650\u0633\u064e\u0639\u0652\u064a\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0643\u064e\u0627\u062a\u0650\u0628\u064f\u0648\u0646\u064e",95,"\u0648\u064e\u062d\u064e\u0631\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",96,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0641\u064f\u062a\u0650\u062d\u064e\u062a\u0652 \u064a\u064e\u0623\u0652\u062c\u064f\u0648\u062c\u064f \u0648\u064e\u0645\u064e\u0623\u0652\u062c\u064f\u0648\u062c\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u062d\u064e\u062f\u064e\u0628\u064d \u064a\u064e\u0646\u0652\u0633\u0650\u0644\u064f\u0648\u0646\u064e",97,"\u0648\u064e\u0627\u0642\u0652\u062a\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0652\u0648\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u0634\u064e\u0627\u062e\u0650\u0635\u064e\u0629\u064c \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",98,"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0635\u064e\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064f\u0648\u0646\u064e",99,"\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u062f\u064f\u0648\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",100,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0641\u0650\u064a\u0631\u064c \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",101,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0645\u064f\u0628\u0652\u0639\u064e\u062f\u064f\u0648\u0646\u064e",102,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u062d\u064e\u0633\u0650\u064a\u0633\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0627\u0634\u0652\u062a\u064e\u0647\u064e\u062a\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",103,"\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0632\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0648\u064e\u062a\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",104,"\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0637\u0652\u0648\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0643\u064e\u0637\u064e\u064a\u0651\u0650 \u0627\u0644\u0633\u0651\u0650\u062c\u0650\u0644\u0651\u0650 \u0644\u0650\u0644\u0652\u0643\u064f\u062a\u064f\u0628\u0650 \u06da \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u064e\u0623\u0652\u0646\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u062e\u064e\u0644\u0652\u0642\u064d \u0646\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u06da \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u0639\u0650\u0644\u0650\u064a\u0646\u064e",105,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0632\u0651\u064e\u0628\u064f\u0648\u0631\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0647\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064f\u0648\u0646\u064e",106,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0628\u064e\u0644\u064e\u0627\u063a\u064b\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0627\u0628\u0650\u062f\u0650\u064a\u0646\u064e",107,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",108,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u06d6 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",109,"\u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0642\u064f\u0644\u0652 \u0622\u0630\u064e\u0646\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0621\u064d \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062f\u0652\u0631\u0650\u064a \u0623\u064e\u0642\u064e\u0631\u0650\u064a\u0628\u064c \u0623\u064e\u0645\u0652 \u0628\u064e\u0639\u0650\u064a\u062f\u064c \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",110,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0647\u0652\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",111,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062f\u0652\u0631\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",112,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d7 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0639\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e"],t.v)
B.aoW=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0632\u064e\u0644\u0652\u0632\u064e\u0644\u064e\u0629\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",2,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u0630\u0652\u0647\u064e\u0644\u064f \u0643\u064f\u0644\u0651\u064f \u0645\u064f\u0631\u0652\u0636\u0650\u0639\u064e\u0629\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0636\u064e\u0639\u064e\u062a\u0652 \u0648\u064e\u062a\u064e\u0636\u064e\u0639\u064f \u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0627\u062a\u0650 \u062d\u064e\u0645\u0652\u0644\u064d \u062d\u064e\u0645\u0652\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0633\u064f\u0643\u064e\u0627\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0643\u064e\u0627\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u062f\u0650\u064a\u062f\u064c",3,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064e\u0631\u0650\u064a\u062f\u064d",4,"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0627\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0647\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",5,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u064a\u0652\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0639\u0652\u062b\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0645\u064f\u0636\u0652\u063a\u064e\u0629\u064d \u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u064d \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u0650 \u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u064d \u0644\u0650\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0646\u064f\u0642\u0650\u0631\u0651\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u0652 \u0637\u0650\u0641\u0652\u0644\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0631\u0652\u0630\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u0650 \u0644\u0650\u0643\u064e\u064a\u0652\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0647\u064e\u0627\u0645\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0627\u0647\u0652\u062a\u064e\u0632\u0651\u064e\u062a\u0652 \u0648\u064e\u0631\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u0652\u062c\u064d \u0628\u064e\u0647\u0650\u064a\u062c\u064d",6,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",7,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0622\u062a\u0650\u064a\u064e\u0629\u064c \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u0650",8,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0646\u0650\u064a\u0631\u064d",9,"\u062b\u064e\u0627\u0646\u0650\u064a\u064e \u0639\u0650\u0637\u0652\u0641\u0650\u0647\u0650 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062e\u0650\u0632\u0652\u064a\u064c \u06d6 \u0648\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064f\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",10,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u064a\u064e\u062f\u064e\u0627\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0627\u0645\u064d \u0644\u0650\u0644\u0652\u0639\u064e\u0628\u0650\u064a\u062f\u0650",11,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u0652\u0641\u064d \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0627\u0637\u0652\u0645\u064e\u0623\u064e\u0646\u0651\u064e \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0647\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u062e\u064e\u0633\u0650\u0631\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062e\u064f\u0633\u0652\u0631\u064e\u0627\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",12,"\u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064f \u0627\u0644\u0652\u0628\u064e\u0639\u0650\u064a\u062f\u064f",13,"\u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0644\u064e\u0645\u064e\u0646\u0652 \u0636\u064e\u0631\u0651\u064f\u0647\u064f \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0639\u0650\u0647\u0650 \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0631\u064f",14,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",15,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0645\u0652\u062f\u064f\u062f\u0652 \u0628\u0650\u0633\u064e\u0628\u064e\u0628\u064d \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u0652\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u0652 \u0641\u064e\u0644\u0652\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u0652 \u0647\u064e\u0644\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u064e\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u064f\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u063a\u0650\u064a\u0638\u064f",16,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",17,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0626\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u062c\u064f\u0648\u0633\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",18,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064f \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0628\u0651\u064f \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0647\u0650\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0645\u064f\u0643\u0652\u0631\u0650\u0645\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06e9",19,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627\u0646\u0650 \u062e\u064e\u0635\u0652\u0645\u064e\u0627\u0646\u0650 \u0627\u062e\u0652\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627 \u0641\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0642\u064f\u0637\u0651\u0650\u0639\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062b\u0650\u064a\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d \u064a\u064f\u0635\u064e\u0628\u0651\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u064f",20,"\u064a\u064f\u0635\u0652\u0647\u064e\u0631\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0644\u064f\u0648\u062f\u064f",21,"\u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0642\u064e\u0627\u0645\u0650\u0639\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u062f\u0650\u064a\u062f\u064d",22,"\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u063a\u064e\u0645\u0651\u064d \u0623\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",23,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0647\u064e\u0628\u064d \u0648\u064e\u0644\u064f\u0624\u0652\u0644\u064f\u0624\u064b\u0627 \u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0631\u0650\u064a\u0631\u064c",24,"\u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u0650",25,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u0627\u0644\u0652\u0639\u064e\u0627\u0643\u0650\u0641\u064f \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u062f\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652 \u0641\u0650\u064a\u0647\u0650 \u0628\u0650\u0625\u0650\u0644\u0652\u062d\u064e\u0627\u062f\u064d \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0646\u064f\u0630\u0650\u0642\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",26,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0628\u064e\u0648\u0651\u064e\u0623\u0652\u0646\u064e\u0627 \u0644\u0650\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u0652 \u0628\u064e\u064a\u0652\u062a\u0650\u064a\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0626\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0643\u0651\u064e\u0639\u0650 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",27,"\u0648\u064e\u0623\u064e\u0630\u0651\u0650\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0636\u064e\u0627\u0645\u0650\u0631\u064d \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u062c\u0651\u064d \u0639\u064e\u0645\u0650\u064a\u0642\u064d",28,"\u0644\u0650\u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064e\u0627\u062a\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u06d6 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0626\u0650\u0633\u064e \u0627\u0644\u0652\u0641\u064e\u0642\u0650\u064a\u0631\u064e",29,"\u062b\u064f\u0645\u0651\u064e \u0644\u0652\u064a\u064e\u0642\u0652\u0636\u064f\u0648\u0627 \u062a\u064e\u0641\u064e\u062b\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u064a\u064f\u0648\u0641\u064f\u0648\u0627 \u0646\u064f\u0630\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0652\u0639\u064e\u062a\u0650\u064a\u0642\u0650",30,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u0652 \u062d\u064f\u0631\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0633\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0632\u0651\u064f\u0648\u0631\u0650",31,"\u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0631\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u062a\u064e\u062e\u0652\u0637\u064e\u0641\u064f\u0647\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064f \u0623\u064e\u0648\u0652 \u062a\u064e\u0647\u0652\u0648\u0650\u064a \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064f \u0641\u0650\u064a \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0633\u064e\u062d\u0650\u064a\u0642\u064d",32,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u0652 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062a\u064e\u0642\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650",33,"\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u062d\u0650\u0644\u0651\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0652\u0639\u064e\u062a\u0650\u064a\u0642\u0650",34,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0652\u0633\u064e\u0643\u064b\u0627 \u0644\u0650\u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u06d7 \u0641\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0641\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0628\u0650\u062a\u0650\u064a\u0646\u064e",35,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0642\u0650\u064a\u0645\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062f\u0652\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u06d6 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0635\u064e\u0648\u064e\u0627\u0641\u0651\u064e \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u062c\u064e\u0628\u064e\u062a\u0652 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064e\u0627 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u0631\u0651\u064e \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",37,"\u0644\u064e\u0646\u0652 \u064a\u064e\u0646\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064f\u062d\u064f\u0648\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062f\u0650\u0645\u064e\u0627\u0624\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u062a\u064f\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",38,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u064e\u0627\u0641\u0650\u0639\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u062e\u064e\u0648\u0651\u064e\u0627\u0646\u064d \u0643\u064e\u0641\u064f\u0648\u0631\u064d",39,"\u0623\u064f\u0630\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0635\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0642\u064e\u062f\u0650\u064a\u0631\u064c",40,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062f\u064e\u0641\u0652\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0644\u064e\u0647\u064f\u062f\u0651\u0650\u0645\u064e\u062a\u0652 \u0635\u064e\u0648\u064e\u0627\u0645\u0650\u0639\u064f \u0648\u064e\u0628\u0650\u064a\u064e\u0639\u064c \u0648\u064e\u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u064c \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064f \u064a\u064f\u0630\u0652\u0643\u064e\u0631\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d7 \u0648\u064e\u0644\u064e\u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",41,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0646\u0652 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0648\u064f\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0645\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0646\u064e\u0647\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",42,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064c \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f",43,"\u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d",44,"\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u06d6 \u0648\u064e\u0643\u064f\u0630\u0651\u0650\u0628\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u064a\u0652\u062a\u064f \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",45,"\u0641\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064c \u0641\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u0650\u0626\u0652\u0631\u064d \u0645\u064f\u0639\u064e\u0637\u0651\u064e\u0644\u064e\u0629\u064d \u0648\u064e\u0642\u064e\u0635\u0652\u0631\u064d \u0645\u064e\u0634\u0650\u064a\u062f\u064d",46,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064c \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0622\u0630\u064e\u0627\u0646\u064c \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0649 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",47,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u0623\u064e\u0644\u0652\u0641\u0650 \u0633\u064e\u0646\u064e\u0629\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0645\u0652\u0644\u064e\u064a\u0652\u062a\u064f \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064c \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",49,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",50,"\u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",51,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0627\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",52,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0649\u0670 \u0623\u064e\u0644\u0652\u0642\u064e\u0649 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u0650\u064a \u0623\u064f\u0645\u0652\u0646\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0633\u064e\u062e\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064f\u0644\u0652\u0642\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u0643\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",53,"\u0644\u0650\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0645\u064e\u0627 \u064a\u064f\u0644\u0652\u0642\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",54,"\u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u062a\u064f\u062e\u0652\u0628\u0650\u062a\u064e \u0644\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064e\u0627\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",55,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0642\u0650\u064a\u0645\u064d",56,"\u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",57,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",58,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",59,"\u0644\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u062f\u0652\u062e\u064e\u0644\u064b\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",60,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u0642\u064e\u0628\u064e \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u064e \u0628\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0628\u064f\u063a\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u064e\u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0641\u064f\u0648\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",61,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",62,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",63,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u062a\u064f\u0635\u0652\u0628\u0650\u062d\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0645\u064f\u062e\u0652\u0636\u064e\u0631\u0651\u064e\u0629\u064b \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064c",64,"\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",65,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",66,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064e\u0641\u064f\u0648\u0631\u064c",67,"\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0652\u0633\u064e\u0643\u064b\u0627 \u0647\u064f\u0645\u0652 \u0646\u064e\u0627\u0633\u0650\u0643\u064f\u0648\u0647\u064f \u06d6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u064e\u0627\u0632\u0650\u0639\u064f\u0646\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u06da \u0648\u064e\u0627\u062f\u0652\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064b\u0649 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",68,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u062f\u064e\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",69,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",70,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",71,"\u0648\u064e\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0628\u0650\u0647\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",72,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064f \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064e \u06d6 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0633\u0652\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0634\u064e\u0631\u0651\u064d \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u06d7 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0639\u064e\u062f\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",73,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0636\u064f\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0627 \u0630\u064f\u0628\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0648\u0650 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0633\u0652\u0644\u064f\u0628\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0630\u0651\u064f\u0628\u064e\u0627\u0628\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0642\u0650\u0630\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0636\u064e\u0639\u064f\u0641\u064e \u0627\u0644\u0637\u0651\u064e\u0627\u0644\u0650\u0628\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0637\u0652\u0644\u064f\u0648\u0628\u064f",74,"\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",75,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0635\u0652\u0637\u064e\u0641\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",76,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",77,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0631\u0652\u0643\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u06e9",78,"\u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064e \u062c\u0650\u0647\u064e\u0627\u062f\u0650\u0647\u0650 \u06da \u0647\u064f\u0648\u064e \u0627\u062c\u0652\u062a\u064e\u0628\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u0650\u0646\u0652 \u062d\u064e\u0631\u064e\u062c\u064d \u06da \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u06da \u0647\u064f\u0648\u064e \u0633\u064e\u0645\u0651\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064f"],t.v)
B.aol=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0642\u064e\u062f\u0652 \u0623\u064e\u0641\u0652\u0644\u064e\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u0627\u0634\u0650\u0639\u064f\u0648\u0646\u064e",3,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u0650 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u0650 \u0641\u064e\u0627\u0639\u0650\u0644\u064f\u0648\u0646\u064e",5,u.F,6,u.bC,7,u.W,8,u.ab,9,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",10,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u064f\u0648\u0646\u064e",11,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u0650\u0631\u0652\u062f\u064e\u0648\u0652\u0633\u064e \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u064e\u0627\u0644\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",13,"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064b \u0641\u0650\u064a \u0642\u064e\u0631\u064e\u0627\u0631\u064d \u0645\u064e\u0643\u0650\u064a\u0646\u064d",14,"\u062b\u064f\u0645\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u0637\u0652\u0641\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064b \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064e \u0645\u064f\u0636\u0652\u063a\u064e\u0629\u064b \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0636\u0652\u063a\u064e\u0629\u064e \u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0643\u064e\u0633\u064e\u0648\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u0638\u064e\u0627\u0645\u064e \u0644\u064e\u062d\u0652\u0645\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627\u0647\u064f \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u06da \u0641\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u0650\u064a\u0646\u064e",15,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e",16,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u062a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",17,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u0652 \u0633\u064e\u0628\u0652\u0639\u064e \u0637\u064e\u0631\u064e\u0627\u0626\u0650\u0642\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u063a\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",18,"\u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d \u0641\u064e\u0623\u064e\u0633\u0652\u0643\u064e\u0646\u0651\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0647\u064e\u0627\u0628\u064d \u0628\u0650\u0647\u0650 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e",19,"\u0641\u064e\u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u062e\u0650\u064a\u0644\u064d \u0648\u064e\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0648\u064e\u0627\u0643\u0650\u0647\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064c \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064b \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u0637\u064f\u0648\u0631\u0650 \u0633\u064e\u064a\u0652\u0646\u064e\u0627\u0621\u064e \u062a\u064e\u0646\u0652\u0628\u064f\u062a\u064f \u0628\u0650\u0627\u0644\u062f\u0651\u064f\u0647\u0652\u0646\u0650 \u0648\u064e\u0635\u0650\u0628\u0652\u063a\u064d \u0644\u0650\u0644\u0652\u0622\u0643\u0650\u0644\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0644\u064e\u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064b \u06d6 \u0646\u064f\u0633\u0652\u0642\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064c \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u062a\u064f\u062d\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",24,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064b \u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u0650\u064a \u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",25,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064c \u0628\u0650\u0647\u0650 \u062c\u0650\u0646\u0651\u064e\u0629\u064c \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",26,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",27,"\u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0646\u0650 \u0627\u0635\u0652\u0646\u064e\u0639\u0650 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u062d\u0652\u064a\u0650\u0646\u064e\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0641\u064e\u0627\u0631\u064e \u0627\u0644\u062a\u0651\u064e\u0646\u0651\u064f\u0648\u0631\u064f \u06d9 \u0641\u064e\u0627\u0633\u0652\u0644\u064f\u0643\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064d \u0632\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0633\u064e\u0628\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0627\u0637\u0650\u0628\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u063a\u0652\u0631\u064e\u0642\u064f\u0648\u0646\u064e",28,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u064a\u0652\u062a\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0641\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u062c\u0651\u064e\u0627\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",29,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0652\u0632\u0650\u0644\u0652\u0646\u0650\u064a \u0645\u064f\u0646\u0652\u0632\u064e\u0644\u064b\u0627 \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0632\u0650\u0644\u0650\u064a\u0646\u064e",30,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u0646\u064e",31,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0631\u0652\u0646\u064b\u0627 \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",32,"\u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u062a\u0652\u0631\u064e\u0641\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0648\u064e\u064a\u064e\u0634\u0652\u0631\u064e\u0628\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0650\u062b\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",35,"\u0623\u064e\u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0651\u064f\u0645\u0652 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e",36,"\u0647\u064e\u064a\u0652\u0647\u064e\u0627\u062a\u064e \u0647\u064e\u064a\u0652\u0647\u064e\u0627\u062a\u064e \u0644\u0650\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",37,"\u0625\u0650\u0646\u0652 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0646\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u0650\u064a\u0646\u064e",38,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064c \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",39,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",40,"\u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064d \u0644\u064e\u064a\u064f\u0635\u0652\u0628\u0650\u062d\u064f\u0646\u0651\u064e \u0646\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",41,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u063a\u064f\u062b\u064e\u0627\u0621\u064b \u06da \u0641\u064e\u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",42,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0642\u064f\u0631\u064f\u0648\u0646\u064b\u0627 \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",43,u.bI,44,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u062a\u064e\u062a\u0652\u0631\u064e\u0649\u0670 \u06d6 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u06da \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u064e \u06da \u0641\u064e\u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",45,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",46,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u064e\u0627\u0644\u0650\u064a\u0646\u064e",47,"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u062b\u0652\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0627\u0628\u0650\u062f\u064f\u0648\u0646\u064e",48,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0647\u0652\u0644\u064e\u0643\u0650\u064a\u0646\u064e",49,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0628\u0652\u0646\u064e \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064f \u0622\u064a\u064e\u0629\u064b \u0648\u064e\u0622\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0652\u0648\u064e\u0629\u064d \u0630\u064e\u0627\u062a\u0650 \u0642\u064e\u0631\u064e\u0627\u0631\u064d \u0648\u064e\u0645\u064e\u0639\u0650\u064a\u0646\u064d",51,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c",52,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0623\u064f\u0645\u0651\u064e\u062a\u064f\u0643\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",53,"\u0641\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0632\u064f\u0628\u064f\u0631\u064b\u0627 \u06d6 \u0643\u064f\u0644\u0651\u064f \u062d\u0650\u0632\u0652\u0628\u064d \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",54,"\u0641\u064e\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0645\u0652\u0631\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",55,"\u0623\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u0650\u062f\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0644\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",56,"\u0646\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",57,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",59,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0622\u062a\u064e\u0648\u0652\u0627 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u0650\u0644\u064e\u0629\u064c \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e",61,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0646\u064e",62,"\u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u0652\u0639\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",63,"\u0628\u064e\u0644\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0645\u0652\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064c \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0645\u0650\u0644\u064f\u0648\u0646\u064e",64,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062c\u0652\u0623\u064e\u0631\u064f\u0648\u0646\u064e",65,"\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0623\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",66,"\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u062a\u064e\u0646\u0652\u0643\u0650\u0635\u064f\u0648\u0646\u064e",67,"\u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650 \u0633\u064e\u0627\u0645\u0650\u0631\u064b\u0627 \u062a\u064e\u0647\u0652\u062c\u064f\u0631\u064f\u0648\u0646\u064e",68,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062f\u0651\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0623\u064e\u0645\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",69,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0645\u064f\u0646\u0652\u0643\u0650\u0631\u064f\u0648\u0646\u064e",70,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u062c\u0650\u0646\u0651\u064e\u0629\u064c \u06da \u0628\u064e\u0644\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u0644\u064e\u0648\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u0650\u0643\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",72,"\u0623\u064e\u0645\u0652 \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u062e\u064e\u0631\u0652\u062c\u064b\u0627 \u0641\u064e\u062e\u064e\u0631\u064e\u0627\u062c\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",73,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",74,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0646\u0650 \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u0650 \u0644\u064e\u0646\u064e\u0627\u0643\u0650\u0628\u064f\u0648\u0646\u064e",75,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0631\u064e\u062d\u0650\u0645\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0636\u064f\u0631\u0651\u064d \u0644\u064e\u0644\u064e\u062c\u0651\u064f\u0648\u0627 \u0641\u0650\u064a \u0637\u064f\u063a\u0652\u064a\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",76,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",77,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u064e\u0627\u0628\u064b\u0627 \u0630\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0628\u0652\u0644\u0650\u0633\u064f\u0648\u0646\u064e",78,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064e \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",79,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0630\u064e\u0631\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",80,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",81,"\u0628\u064e\u0644\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",82,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",83,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0648\u064f\u0639\u0650\u062f\u0652\u0646\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",84,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",85,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",86,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u0639\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",87,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",88,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062c\u0650\u064a\u0631\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0631\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",89,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0633\u0652\u062d\u064e\u0631\u064f\u0648\u0646\u064e",90,"\u0628\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",91,"\u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u064e\u062f\u064d \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u06da \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0630\u064e\u0647\u064e\u0628\u064e \u0643\u064f\u0644\u0651\u064f \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u0628\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",92,"\u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",93,"\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",94,"\u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",95,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0646\u064f\u0631\u0650\u064a\u064e\u0643\u064e \u0645\u064e\u0627 \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e",96,"\u0627\u062f\u0652\u0641\u064e\u0639\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u06da \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",97,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0632\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650",98,"\u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0636\u064f\u0631\u064f\u0648\u0646\u0650",99,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u0650",100,"\u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f \u06da \u0643\u064e\u0644\u0651\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0626\u0650\u0644\u064f\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0628\u064e\u0631\u0652\u0632\u064e\u062e\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",101,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u0633\u064e\u0627\u0628\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",102,"\u0641\u064e\u0645\u064e\u0646\u0652 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",103,"\u0648\u064e\u0645\u064e\u0646\u0652 \u062e\u064e\u0641\u0651\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",104,"\u062a\u064e\u0644\u0652\u0641\u064e\u062d\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0627\u0644\u0650\u062d\u064f\u0648\u0646\u064e",105,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",106,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0634\u0650\u0642\u0652\u0648\u064e\u062a\u064f\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0636\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",107,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064f\u062f\u0652\u0646\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",108,"\u0642\u064e\u0627\u0644\u064e \u0627\u062e\u0652\u0633\u064e\u0626\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u0650",109,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e",110,"\u0641\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0633\u0650\u062e\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0633\u064e\u0648\u0652\u0643\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u064a \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e",111,"\u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0632\u064e\u064a\u0652\u062a\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0626\u0650\u0632\u064f\u0648\u0646\u064e",112,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0645\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0639\u064e\u062f\u064e\u062f\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",113,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0628\u0650\u062b\u0652\u0646\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0623\u064e\u0648\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u062f\u0651\u0650\u064a\u0646\u064e",114,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",115,"\u0623\u064e\u0641\u064e\u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0628\u064e\u062b\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",116,"\u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u0650",117,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0644\u064e\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",118,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0646\u064e"],t.v)
B.aoC=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0641\u064e\u0631\u064e\u0636\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",2,"\u0627\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0627\u062c\u0652\u0644\u0650\u062f\u064f\u0648\u0627 \u0643\u064f\u0644\u0651\u064e \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0627\u0626\u064e\u0629\u064e \u062c\u064e\u0644\u0652\u062f\u064e\u0629\u064d \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650\u0645\u064e\u0627 \u0631\u064e\u0623\u0652\u0641\u064e\u0629\u064c \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06d6 \u0648\u064e\u0644\u0652\u064a\u064e\u0634\u0652\u0647\u064e\u062f\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064e\u0627 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",3,"\u0627\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0643\u0650\u062d\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0632\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064e\u0629\u064b \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064f \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0632\u064e\u0627\u0646\u064d \u0623\u064e\u0648\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064c \u06da \u0648\u064e\u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",4,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0652\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0641\u064e\u0627\u062c\u0652\u0644\u0650\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0646\u064e \u062c\u064e\u0644\u0652\u062f\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0628\u064e\u0644\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064b \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",5,u.h,6,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0652\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064f \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064f \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0627\u062a\u064d \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0627\u0645\u0650\u0633\u064e\u0629\u064f \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0639\u0652\u0646\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",8,"\u0648\u064e\u064a\u064e\u062f\u0652\u0631\u064e\u0623\u064f \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0627\u062a\u064d \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",9,"\u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0627\u0645\u0650\u0633\u064e\u0629\u064e \u0623\u064e\u0646\u0651\u064e \u063a\u064e\u0636\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",10,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",11,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u0641\u0652\u0643\u0650 \u0639\u064f\u0635\u0652\u0628\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0647\u064f \u0634\u064e\u0631\u0651\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0633\u064e\u0628\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0643\u0650\u0628\u0652\u0631\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",12,"\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0630\u0652 \u0633\u064e\u0645\u0650\u0639\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0638\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064f \u0628\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0641\u0652\u0643\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",13,"\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u06da \u0641\u064e\u0625\u0650\u0630\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0623\u064e\u0641\u064e\u0636\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",15,"\u0625\u0650\u0630\u0652 \u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0648\u064e\u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e\u0647\u064f \u0647\u064e\u064a\u0651\u0650\u0646\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u064c",16,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0630\u0652 \u0633\u064e\u0645\u0650\u0639\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",17,"\u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627 \u0644\u0650\u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",18,"\u0648\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",19,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0634\u0650\u064a\u0639\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064f \u0641\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",21,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u062e\u064f\u0637\u064f\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u062e\u064f\u0637\u064f\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f \u0628\u0650\u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f\u0647\u064f \u0645\u064e\u0627 \u0632\u064e\u0643\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",22,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064e\u0644\u0650 \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0644\u0652\u064a\u064e\u0639\u0652\u0641\u064f\u0648\u0627 \u0648\u064e\u0644\u0652\u064a\u064e\u0635\u0652\u0641\u064e\u062d\u064f\u0648\u0627 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",23,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0652\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u064e\u0646\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u063a\u064e\u0627\u0641\u0650\u0644\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0644\u064f\u0639\u0650\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",24,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",25,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",26,"\u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0627\u062a\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064f\u0628\u064e\u0631\u0651\u064e\u0621\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",27,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0646\u0650\u0633\u064f\u0648\u0627 \u0648\u064e\u062a\u064f\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",28,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u0641\u064e\u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0632\u0652\u0643\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c",29,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646\u0652 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0633\u0652\u0643\u064f\u0648\u0646\u064e\u0629\u064d \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",30,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064e\u063a\u064f\u0636\u0651\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u062d\u0652\u0641\u064e\u0638\u064f\u0648\u0627 \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0632\u0652\u0643\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u064a\u064e\u063a\u0652\u0636\u064f\u0636\u0652\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u064a\u064e\u062d\u0652\u0641\u064e\u0638\u0652\u0646\u064e \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u062f\u0650\u064a\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0644\u0652\u064a\u064e\u0636\u0652\u0631\u0650\u0628\u0652\u0646\u064e \u0628\u0650\u062e\u064f\u0645\u064f\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u064a\u064f\u0648\u0628\u0650\u0647\u0650\u0646\u0651\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u062f\u0650\u064a\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0622\u0628\u064e\u0627\u0621\u0650 \u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u0650 \u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0628\u064e\u0646\u0650\u064a \u0623\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0648\u0650 \u0627\u0644\u062a\u0651\u064e\u0627\u0628\u0650\u0639\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u0650 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0625\u0650\u0631\u0652\u0628\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0623\u064e\u0648\u0650 \u0627\u0644\u0637\u0651\u0650\u0641\u0652\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0638\u0652\u0647\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0648\u0652\u0631\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u0652\u0646\u064e \u0628\u0650\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0644\u0650\u064a\u064f\u0639\u0652\u0644\u064e\u0645\u064e \u0645\u064e\u0627 \u064a\u064f\u062e\u0652\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0632\u0650\u064a\u0646\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",32,"\u0648\u064e\u0623\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u064a\u064e\u0627\u0645\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0645\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u064e \u064a\u064f\u063a\u0652\u0646\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",33,"\u0648\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u0641\u0650\u0641\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0646\u0650\u0643\u064e\u0627\u062d\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u0652\u0646\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0643\u064e\u0627\u062a\u0650\u0628\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u0652\u0631\u0650\u0647\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u064a\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u0650\u063a\u064e\u0627\u0621\u0650 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u0652\u0646\u064e \u062a\u064e\u062d\u064e\u0635\u0651\u064f\u0646\u064b\u0627 \u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0639\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0643\u0652\u0631\u0650\u0647\u0652\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0647\u0650\u0647\u0650\u0646\u0651\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",34,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064d \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",35,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064f\u0648\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0645\u064e\u062b\u064e\u0644\u064f \u0646\u064f\u0648\u0631\u0650\u0647\u0650 \u0643\u064e\u0645\u0650\u0634\u0652\u0643\u064e\u0627\u0629\u064d \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0635\u0652\u0628\u064e\u0627\u062d\u064c \u06d6 \u0627\u0644\u0652\u0645\u0650\u0635\u0652\u0628\u064e\u0627\u062d\u064f \u0641\u0650\u064a \u0632\u064f\u062c\u064e\u0627\u062c\u064e\u0629\u064d \u06d6 \u0627\u0644\u0632\u0651\u064f\u062c\u064e\u0627\u062c\u064e\u0629\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0648\u0652\u0643\u064e\u0628\u064c \u062f\u064f\u0631\u0651\u0650\u064a\u0651\u064c \u064a\u064f\u0648\u0642\u064e\u062f\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064e\u0629\u064d \u0632\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u064e\u0629\u064d \u0644\u064e\u0627 \u0634\u064e\u0631\u0652\u0642\u0650\u064a\u0651\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u063a\u064e\u0631\u0652\u0628\u0650\u064a\u0651\u064e\u0629\u064d \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0632\u064e\u064a\u0652\u062a\u064f\u0647\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0621\u064f \u0648\u064e\u0644\u064e\u0648\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0645\u0652\u0633\u064e\u0633\u0652\u0647\u064f \u0646\u064e\u0627\u0631\u064c \u06da \u0646\u064f\u0648\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u064d \u06d7 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0646\u064f\u0648\u0631\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",36,"\u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u064d \u0623\u064e\u0630\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u062a\u064f\u0631\u0652\u0641\u064e\u0639\u064e \u0648\u064e\u064a\u064f\u0630\u0652\u0643\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0633\u0652\u0645\u064f\u0647\u064f \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0622\u0635\u064e\u0627\u0644\u0650",37,"\u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0644\u064e\u0627 \u062a\u064f\u0644\u0652\u0647\u0650\u064a\u0647\u0650\u0645\u0652 \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u064a\u0652\u0639\u064c \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0642\u064e\u0627\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0621\u0650 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u0650 \u06d9 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u062a\u064e\u062a\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064f \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f",38,"\u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",39,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0633\u064e\u0631\u064e\u0627\u0628\u064d \u0628\u0650\u0642\u0650\u064a\u0639\u064e\u0629\u064d \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064f \u0627\u0644\u0638\u0651\u064e\u0645\u0652\u0622\u0646\u064f \u0645\u064e\u0627\u0621\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652\u0647\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0641\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0647\u064f \u062d\u0650\u0633\u064e\u0627\u0628\u064e\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",40,"\u0623\u064e\u0648\u0652 \u0643\u064e\u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064d \u0641\u0650\u064a \u0628\u064e\u062d\u0652\u0631\u064d \u0644\u064f\u062c\u0651\u0650\u064a\u0651\u064d \u064a\u064e\u063a\u0652\u0634\u064e\u0627\u0647\u064f \u0645\u064e\u0648\u0652\u062c\u064c \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650 \u0645\u064e\u0648\u0652\u062c\u064c \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650 \u0633\u064e\u062d\u064e\u0627\u0628\u064c \u06da \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064c \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e \u0628\u064e\u0639\u0652\u0636\u064d \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u064a\u064e\u062f\u064e\u0647\u064f \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064e\u062f\u0652 \u064a\u064e\u0631\u064e\u0627\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0646\u064f\u0648\u0631\u064b\u0627 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0646\u064f\u0648\u0631\u064d",41,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064f \u0635\u064e\u0627\u0641\u0651\u064e\u0627\u062a\u064d \u06d6 \u0643\u064f\u0644\u0651\u064c \u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0633\u0652\u0628\u0650\u064a\u062d\u064e\u0647\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",42,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",43,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0632\u0652\u062c\u0650\u064a \u0633\u064e\u062d\u064e\u0627\u0628\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0624\u064e\u0644\u0651\u0650\u0641\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0647\u064f \u0631\u064f\u0643\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0648\u064e\u062f\u0652\u0642\u064e \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0644\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u0650\u0646\u0652 \u062c\u0650\u0628\u064e\u0627\u0644\u064d \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0631\u064e\u062f\u064d \u0641\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0635\u0652\u0631\u0650\u0641\u064f\u0647\u064f \u0639\u064e\u0646\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0633\u064e\u0646\u064e\u0627 \u0628\u064e\u0631\u0652\u0642\u0650\u0647\u0650 \u064a\u064e\u0630\u0652\u0647\u064e\u0628\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650",44,"\u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064b \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650",45,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0637\u0652\u0646\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u0650\u062c\u0652\u0644\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064d \u06da \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",46,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0622\u064a\u064e\u0627\u062a\u064d \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",47,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",48,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0644\u0650\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064f\u0630\u0652\u0639\u0650\u0646\u0650\u064a\u0646\u064e",50,"\u0623\u064e\u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0623\u064e\u0645\u0650 \u0627\u0631\u0652\u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0623\u064e\u0645\u0652 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0650\u064a\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",51,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0644\u0650\u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",52,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u062e\u0652\u0634\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0642\u0652\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0626\u0650\u0632\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0645\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0646\u0651\u064e \u06d6 \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u062a\u064f\u0642\u0652\u0633\u0650\u0645\u064f\u0648\u0627 \u06d6 \u0637\u064e\u0627\u0639\u064e\u0629\u064c \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064e\u0629\u064c \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",54,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0647\u064f \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",55,"\u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0643\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u064e\u0641\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u064a\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0631\u0652\u062a\u064e\u0636\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u062e\u064e\u0648\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0645\u0652\u0646\u064b\u0627 \u06da \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",57,"\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",58,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u0650\u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064f\u0644\u064f\u0645\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u062b\u064e\u0644\u064e\u0627\u062b\u064e \u0645\u064e\u0631\u0651\u064e\u0627\u062a\u064d \u06da \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0635\u064e\u0644\u064e\u0627\u0629\u0650 \u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0636\u064e\u0639\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0647\u0650\u064a\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0635\u064e\u0644\u064e\u0627\u0629\u0650 \u0627\u0644\u0652\u0639\u0650\u0634\u064e\u0627\u0621\u0650 \u06da \u062b\u064e\u0644\u064e\u0627\u062b\u064f \u0639\u064e\u0648\u0652\u0631\u064e\u0627\u062a\u064d \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0637\u064e\u0648\u0651\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",59,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0627\u0644\u0652\u0623\u064e\u0637\u0652\u0641\u064e\u0627\u0644\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064f\u0644\u064f\u0645\u064e \u0641\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u064e\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",60,"\u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0648\u064e\u0627\u0639\u0650\u062f\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0646\u0650\u0643\u064e\u0627\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646\u0652 \u064a\u064e\u0636\u064e\u0639\u0652\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0646\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u062a\u064e\u0628\u064e\u0631\u0651\u0650\u062c\u064e\u0627\u062a\u064d \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u064d \u06d6 \u0648\u064e\u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u0641\u0650\u0641\u0652\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",61,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u062d\u064e\u0631\u064e\u062c\u064c \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u062c\u0650 \u062d\u064e\u0631\u064e\u062c\u064c \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0631\u0650\u064a\u0636\u0650 \u062d\u064e\u0631\u064e\u062c\u064c \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0645\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0639\u064e\u0645\u0651\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u062e\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u062e\u064e\u0627\u0644\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064e\u0647\u064f \u0623\u064e\u0648\u0652 \u0635\u064e\u062f\u0650\u064a\u0642\u0650\u0643\u064f\u0645\u0652 \u06da \u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u0634\u0652\u062a\u064e\u0627\u062a\u064b\u0627 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0641\u064e\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064e\u0629\u064b \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",62,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064d \u062c\u064e\u0627\u0645\u0650\u0639\u064d \u0644\u064e\u0645\u0652 \u064a\u064e\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0648\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u064e\u0646\u064f\u0648\u0643\u064e \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u0650 \u0634\u064e\u0623\u0652\u0646\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u0652\u0630\u064e\u0646\u0652 \u0644\u0650\u0645\u064e\u0646\u0652 \u0634\u0650\u0626\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",63,"\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u062f\u064f\u0639\u064e\u0627\u0621\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u062f\u064f\u0639\u064e\u0627\u0621\u0650 \u0628\u064e\u0639\u0652\u0636\u0650\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u06da \u0642\u064e\u062f\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0633\u064e\u0644\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0644\u0650\u0648\u064e\u0627\u0630\u064b\u0627 \u06da \u0641\u064e\u0644\u0652\u064a\u064e\u062d\u0652\u0630\u064e\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062e\u064e\u0627\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0623\u064e\u0648\u0652 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",64,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0642\u064e\u062f\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c"],t.v)
B.asB=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0647\u0650 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0652 \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0634\u064e\u0631\u0650\u064a\u0643\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f \u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064b\u0627",3,"\u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u062e\u0652\u0644\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u0652\u062a\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0634\u064f\u0648\u0631\u064b\u0627",4,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0641\u0652\u0643\u064c \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064e\u0627\u0646\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064c \u0622\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0648\u064e\u0632\u064f\u0648\u0631\u064b\u0627",5,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0627\u0643\u0652\u062a\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0641\u064e\u0647\u0650\u064a\u064e \u062a\u064f\u0645\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",6,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0633\u0651\u0650\u0631\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",7,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0648\u064e\u0627\u0642\u0650 \u06d9 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u064c \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",8,"\u0623\u064e\u0648\u0652 \u064a\u064f\u0644\u0652\u0642\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064e\u0646\u0652\u0632\u064c \u0623\u064e\u0648\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0629\u064c \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0645\u064e\u0633\u0652\u062d\u064f\u0648\u0631\u064b\u0627",9,u.cp,10,"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0643\u064e \u0642\u064f\u0635\u064f\u0648\u0631\u064b\u0627",11,"\u0628\u064e\u0644\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",12,"\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064e\u0627 \u062a\u064e\u063a\u064e\u064a\u0651\u064f\u0638\u064b\u0627 \u0648\u064e\u0632\u064e\u0641\u0650\u064a\u0631\u064b\u0627",13,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0644\u0652\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0636\u064e\u064a\u0651\u0650\u0642\u064b\u0627 \u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u062f\u064e\u0639\u064e\u0648\u0652\u0627 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062b\u064f\u0628\u064f\u0648\u0631\u064b\u0627",14,"\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062b\u064f\u0628\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064b\u0627 \u0648\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u062b\u064f\u0628\u064f\u0648\u0631\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",15,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06da \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0648\u064e\u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",16,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u06da \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064b\u0627",17,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0636\u0652\u0644\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0623\u064e\u0645\u0652 \u0647\u064f\u0645\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",18,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0628\u064f\u0648\u0631\u064b\u0627",19,"\u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0635\u064e\u0631\u0652\u0641\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0646\u064f\u0630\u0650\u0642\u0652\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",20,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0648\u064e\u0627\u0642\u0650 \u06d7 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0623\u064e\u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",21,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u0652 \u0646\u064e\u0631\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u06d7 \u0644\u064e\u0642\u064e\u062f\u0650 \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064f\u062a\u064f\u0648\u0651\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",22,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0644\u064e\u0627 \u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062d\u0650\u062c\u0652\u0631\u064b\u0627 \u0645\u064e\u062d\u0652\u062c\u064f\u0648\u0631\u064b\u0627",23,"\u0648\u064e\u0642\u064e\u062f\u0650\u0645\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u064d \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0647\u064e\u0628\u064e\u0627\u0621\u064b \u0645\u064e\u0646\u0652\u062b\u064f\u0648\u0631\u064b\u0627",24,"\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0645\u064e\u0642\u0650\u064a\u0644\u064b\u0627",25,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0634\u064e\u0642\u0651\u064e\u0642\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u0645\u064e\u0627\u0645\u0650 \u0648\u064e\u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064b\u0627",26,"\u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0633\u0650\u064a\u0631\u064b\u0627",27,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0639\u064e\u0636\u0651\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",28,"\u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u062a\u064e\u0649\u0670 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u0652 \u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0652 \u0641\u064f\u0644\u064e\u0627\u0646\u064b\u0627 \u062e\u064e\u0644\u0650\u064a\u0644\u064b\u0627",29,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0646\u0650\u064a \u0639\u064e\u0646\u0650 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0646\u0650\u064a \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u062e\u064e\u0630\u064f\u0648\u0644\u064b\u0627",30,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u0627 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0645\u064e\u0647\u0652\u062c\u064f\u0648\u0631\u064b\u0627",31,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0647\u064e\u0627\u062f\u0650\u064a\u064b\u0627 \u0648\u064e\u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",32,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u062c\u064f\u0645\u0652\u0644\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0646\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0628\u0650\u0647\u0650 \u0641\u064f\u0624\u064e\u0627\u062f\u064e\u0643\u064e \u06d6 \u0648\u064e\u0631\u064e\u062a\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u062a\u064e\u0631\u0652\u062a\u0650\u064a\u0644\u064b\u0627",33,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u062b\u064e\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u0650\u0626\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u062a\u064e\u0641\u0652\u0633\u0650\u064a\u0631\u064b\u0627",34,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0634\u064e\u0631\u0651\u064c \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",35,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0632\u0650\u064a\u0631\u064b\u0627",36,"\u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0627\u0630\u0652\u0647\u064e\u0628\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u062a\u064e\u062f\u0652\u0645\u0650\u064a\u0631\u064b\u0627",37,"\u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0648\u062d\u064d \u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",38,"\u0648\u064e\u0639\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u0651\u0650 \u0648\u064e\u0642\u064f\u0631\u064f\u0648\u0646\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",39,"\u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0636\u064e\u0631\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u062a\u064e\u0628\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u062a\u064e\u062a\u0652\u0628\u0650\u064a\u0631\u064b\u0627",40,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064f\u0645\u0652\u0637\u0650\u0631\u064e\u062a\u0652 \u0645\u064e\u0637\u064e\u0631\u064e \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u06da \u0628\u064e\u0644\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0646\u064f\u0634\u064f\u0648\u0631\u064b\u0627",41,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0643\u064e \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0623\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",42,"\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u062f\u064e \u0644\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0646\u064e\u0627 \u0639\u064e\u0646\u0652 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0635\u064e\u0628\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u062d\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",43,"\u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u0647\u064f \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",44,"\u0623\u064e\u0645\u0652 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u06d6 \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",45,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0645\u064e\u062f\u0651\u064e \u0627\u0644\u0638\u0651\u0650\u0644\u0651\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0633\u064e\u0627\u0643\u0650\u0646\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062f\u064e\u0644\u0650\u064a\u0644\u064b\u0627",46,"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0628\u064e\u0636\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0636\u064b\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",47,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u064b\u0627 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0648\u0652\u0645\u064e \u0633\u064f\u0628\u064e\u0627\u062a\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0646\u064f\u0634\u064f\u0648\u0631\u064b\u0627",48,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0628\u064f\u0634\u0652\u0631\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0637\u064e\u0647\u064f\u0648\u0631\u064b\u0627",49,"\u0644\u0650\u0646\u064f\u062d\u0652\u064a\u0650\u064a\u064e \u0628\u0650\u0647\u0650 \u0628\u064e\u0644\u0652\u062f\u064e\u0629\u064b \u0645\u064e\u064a\u0652\u062a\u064b\u0627 \u0648\u064e\u0646\u064f\u0633\u0652\u0642\u0650\u064a\u064e\u0647\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0633\u0650\u064a\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",50,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u0628\u064e\u0649\u0670 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u064b\u0627",51,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u0650\u0626\u0652\u0646\u064e\u0627 \u0644\u064e\u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",52,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062c\u0650\u0647\u064e\u0627\u062f\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",53,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u0631\u064e\u062c\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u0652\u0628\u064c \u0641\u064f\u0631\u064e\u0627\u062a\u064c \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0644\u0652\u062d\u064c \u0623\u064f\u062c\u064e\u0627\u062c\u064c \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0631\u0652\u0632\u064e\u062e\u064b\u0627 \u0648\u064e\u062d\u0650\u062c\u0652\u0631\u064b\u0627 \u0645\u064e\u062d\u0652\u062c\u064f\u0648\u0631\u064b\u0627",54,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u0650 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0646\u064e\u0633\u064e\u0628\u064b\u0627 \u0648\u064e\u0635\u0650\u0647\u0652\u0631\u064b\u0627 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",55,"\u0648\u064e\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627",56,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",57,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",58,"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",59,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u06da \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652 \u0628\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",60,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0623\u064e\u0646\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0646\u064f\u0641\u064f\u0648\u0631\u064b\u0627 \u06e9",61,"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u064f\u0631\u064f\u0648\u062c\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u0650\u0631\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u0642\u064e\u0645\u064e\u0631\u064b\u0627 \u0645\u064f\u0646\u0650\u064a\u0631\u064b\u0627",62,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u062e\u0650\u0644\u0652\u0641\u064e\u0629\u064b \u0644\u0650\u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0634\u064f\u0643\u064f\u0648\u0631\u064b\u0627",63,"\u0648\u064e\u0639\u0650\u0628\u064e\u0627\u062f\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0647\u064e\u0648\u0652\u0646\u064b\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0627\u0637\u064e\u0628\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627",64,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0650\u064a\u062a\u064f\u0648\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0642\u0650\u064a\u064e\u0627\u0645\u064b\u0627",65,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u0635\u0652\u0631\u0650\u0641\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0631\u064e\u0627\u0645\u064b\u0627",66,"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0645\u064f\u0642\u064e\u0627\u0645\u064b\u0627",67,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0648\u064e\u0627\u0645\u064b\u0627",68,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0652\u0646\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0644\u0652\u0642\u064e \u0623\u064e\u062b\u064e\u0627\u0645\u064b\u0627",69,"\u064a\u064f\u0636\u064e\u0627\u0639\u064e\u0641\u0652 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u064a\u064e\u062e\u0652\u0644\u064f\u062f\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0647\u064e\u0627\u0646\u064b\u0627",70,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u064d \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",71,"\u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062a\u064e\u0627\u0628\u064b\u0627",72,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064f\u0648\u0631\u064e \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0651\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u0650 \u0645\u064e\u0631\u0651\u064f\u0648\u0627 \u0643\u0650\u0631\u064e\u0627\u0645\u064b\u0627",73,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0635\u064f\u0645\u0651\u064b\u0627 \u0648\u064e\u0639\u064f\u0645\u0652\u064a\u064e\u0627\u0646\u064b\u0627",74,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0628\u0652 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0646\u064e\u0627 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0642\u064f\u0631\u0651\u064e\u0629\u064e \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064d \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0645\u064e\u0627\u0645\u064b\u0627",75,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0652\u063a\u064f\u0631\u0652\u0641\u064e\u0629\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u064b \u0648\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627",76,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u062d\u064e\u0633\u064f\u0646\u064e\u062a\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0645\u064f\u0642\u064e\u0627\u0645\u064b\u0627",77,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064e\u0623\u064f \u0628\u0650\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u0632\u064e\u0627\u0645\u064b\u0627"],t.v)
B.aqY=new A.U([1,u.bc,2,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",3,"\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u0628\u064e\u0627\u062e\u0650\u0639\u064c \u0646\u064e\u0641\u0652\u0633\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",4,"\u0625\u0650\u0646\u0652 \u0646\u064e\u0634\u064e\u0623\u0652 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0622\u064a\u064e\u0629\u064b \u0641\u064e\u0638\u064e\u0644\u0651\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u062e\u064e\u0627\u0636\u0650\u0639\u0650\u064a\u0646\u064e",5,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0645\u064f\u062d\u0652\u062f\u064e\u062b\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u0650\u064a\u0646\u064e",6,"\u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0641\u064e\u0633\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",7,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0643\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u0652\u062c\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",8,u.J,9,u.z,10,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0650 \u0627\u0626\u0652\u062a\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",11,"\u0642\u064e\u0648\u0652\u0645\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06da \u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",12,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u0650",13,"\u0648\u064e\u064a\u064e\u0636\u0650\u064a\u0642\u064f \u0635\u064e\u062f\u0652\u0631\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0637\u064e\u0644\u0650\u0642\u064f \u0644\u0650\u0633\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0630\u064e\u0646\u0652\u0628\u064c \u0641\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u0650",15,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0641\u064e\u0627\u0630\u0652\u0647\u064e\u0628\u064e\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",16,"\u0641\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0627 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",17,"\u0623\u064e\u0646\u0652 \u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",18,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064f\u0645\u064f\u0631\u0650\u0643\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",19,"\u0648\u064e\u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0641\u064e\u0639\u0652\u0644\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",20,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0647\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",21,"\u0641\u064e\u0641\u064e\u0631\u064e\u0631\u0652\u062a\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u062e\u0650\u0641\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0647\u064e\u0628\u064e \u0644\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",22,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064c \u062a\u064e\u0645\u064f\u0646\u0651\u064f\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0652 \u0639\u064e\u0628\u0651\u064e\u062f\u0652\u062a\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",23,"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",24,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",25,"\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",26,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",27,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",28,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",29,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u064f\u0648\u0646\u0650\u064a\u0646\u064e",30,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",31,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",32,u.bX,33,u.ad,34,"\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",35,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u0650\u0647\u0650 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e",36,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0631\u0652\u062c\u0650\u0647\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0648\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u064e\u0627\u0626\u0650\u0646\u0650 \u062d\u064e\u0627\u0634\u0650\u0631\u0650\u064a\u0646\u064e",37,"\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u062d\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",38,"\u0641\u064e\u062c\u064f\u0645\u0650\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0627\u062a\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",39,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u062c\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",40,"\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",41,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0626\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",42,"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0639\u064e\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",43,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e",44,"\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u062d\u0650\u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u0650\u0635\u0650\u064a\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u0650\u0639\u0650\u0632\u0651\u064e\u0629\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",45,"\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0641\u0650\u0643\u064f\u0648\u0646\u064e",46,"\u0641\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",47,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",48,"\u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",49,"\u0642\u064e\u0627\u0644\u064e \u0622\u0645\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u0622\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064e \u0641\u064e\u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u06da \u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064d \u0648\u064e\u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",50,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u0636\u064e\u064a\u0652\u0631\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",51,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",52,"\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0646\u064e",53,"\u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u064e\u0627\u0626\u0650\u0646\u0650 \u062d\u064e\u0627\u0634\u0650\u0631\u0650\u064a\u0646\u064e",54,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0644\u064e\u0634\u0650\u0631\u0652\u0630\u0650\u0645\u064e\u0629\u064c \u0642\u064e\u0644\u0650\u064a\u0644\u064f\u0648\u0646\u064e",55,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0627\u0626\u0650\u0638\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062c\u064e\u0645\u0650\u064a\u0639\u064c \u062d\u064e\u0627\u0630\u0650\u0631\u064f\u0648\u0646\u064e",57,"\u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",58,"\u0648\u064e\u0643\u064f\u0646\u064f\u0648\u0632\u064d \u0648\u064e\u0645\u064e\u0642\u064e\u0627\u0645\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",59,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",60,"\u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0642\u0650\u064a\u0646\u064e",61,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0621\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u0650 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u062f\u0652\u0631\u064e\u0643\u064f\u0648\u0646\u064e",62,"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0633\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",63,"\u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0650 \u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0628\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u06d6 \u0641\u064e\u0627\u0646\u0652\u0641\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0643\u064f\u0644\u0651\u064f \u0641\u0650\u0631\u0652\u0642\u064d \u0643\u064e\u0627\u0644\u0637\u0651\u064e\u0648\u0652\u062f\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",64,"\u0648\u064e\u0623\u064e\u0632\u0652\u0644\u064e\u0641\u0652\u0646\u064e\u0627 \u062b\u064e\u0645\u0651\u064e \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",65,"\u0648\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",66,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",67,u.J,68,u.z,69,"\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",70,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",71,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0646\u064e\u0638\u064e\u0644\u0651\u064f \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0643\u0650\u0641\u0650\u064a\u0646\u064e",72,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e",73,"\u0623\u064e\u0648\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e",74,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",75,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",76,"\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u062f\u064e\u0645\u064f\u0648\u0646\u064e",77,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",78,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0646\u0650\u064a \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",79,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u064a\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0646\u0650\u064a \u0648\u064e\u064a\u064e\u0633\u0652\u0642\u0650\u064a\u0646\u0650",80,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0650\u0636\u0652\u062a\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0634\u0652\u0641\u0650\u064a\u0646\u0650",81,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0646\u0650\u064a \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0646\u0650",82,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u0650\u064a \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u062a\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",83,"\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u0644\u0652\u062d\u0650\u0642\u0652\u0646\u0650\u064a \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",84,"\u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",85,"\u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u062b\u064e\u0629\u0650 \u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",86,"\u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0623\u064e\u0628\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0632\u0650\u0646\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",88,"\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0645\u064e\u0627\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0646\u064f\u0648\u0646\u064e",89,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u062a\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0642\u064e\u0644\u0652\u0628\u064d \u0633\u064e\u0644\u0650\u064a\u0645\u064d",90,"\u0648\u064e\u0623\u064f\u0632\u0652\u0644\u0650\u0641\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",91,"\u0648\u064e\u0628\u064f\u0631\u0651\u0650\u0632\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0644\u0650\u0644\u0652\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",92,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",93,"\u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064f\u0648\u0646\u064e",94,"\u0641\u064e\u0643\u064f\u0628\u0652\u0643\u0650\u0628\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0627\u0648\u064f\u0648\u0646\u064e",95,"\u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",96,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",97,"\u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",98,"\u0625\u0650\u0630\u0652 \u0646\u064f\u0633\u064e\u0648\u0651\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",99,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",100,"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u0627\u0641\u0650\u0639\u0650\u064a\u0646\u064e",101,"\u0648\u064e\u0644\u064e\u0627 \u0635\u064e\u062f\u0650\u064a\u0642\u064d \u062d\u064e\u0645\u0650\u064a\u0645\u064d",102,"\u0641\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u064b \u0641\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",103,u.J,104,u.z,105,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",106,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0646\u064f\u0648\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",107,"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",108,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",109,u.C,110,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",111,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0644\u064e\u0643\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0630\u064e\u0644\u064f\u0648\u0646\u064e",112,"\u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",113,"\u0625\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0644\u064e\u0648\u0652 \u062a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",114,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0637\u064e\u0627\u0631\u0650\u062f\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",115,"\u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",116,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u0650 \u064a\u064e\u0627 \u0646\u064f\u0648\u062d\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u062c\u064f\u0648\u0645\u0650\u064a\u0646\u064e",117,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",118,"\u0641\u064e\u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u0652\u062d\u064b\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",119,"\u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u062d\u064f\u0648\u0646\u0650",120,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a\u0646\u064e",121,u.J,122,u.z,123,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0639\u064e\u0627\u062f\u064c \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",124,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0647\u064f\u0648\u062f\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",125,"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",126,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",127,u.C,128,"\u0623\u064e\u062a\u064e\u0628\u0652\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0631\u0650\u064a\u0639\u064d \u0622\u064a\u064e\u0629\u064b \u062a\u064e\u0639\u0652\u0628\u064e\u062b\u064f\u0648\u0646\u064e",129,"\u0648\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u064e\u0635\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u0644\u064f\u062f\u064f\u0648\u0646\u064e",130,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0637\u064e\u0634\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0637\u064e\u0634\u0652\u062a\u064f\u0645\u0652 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0650\u064a\u0646\u064e",131,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",132,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",133,"\u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",134,"\u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",135,"\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",136,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0648\u064e\u0639\u064e\u0638\u0652\u062a\u064e \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u0639\u0650\u0638\u0650\u064a\u0646\u064e",137,"\u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064f\u0644\u064f\u0642\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",138,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",139,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",140,u.z,141,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",142,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",143,"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",144,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",145,u.C,146,"\u0623\u064e\u062a\u064f\u062a\u0652\u0631\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",147,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",148,"\u0648\u064e\u0632\u064f\u0631\u064f\u0648\u0639\u064d \u0648\u064e\u0646\u064e\u062e\u0652\u0644\u064d \u0637\u064e\u0644\u0652\u0639\u064f\u0647\u064e\u0627 \u0647\u064e\u0636\u0650\u064a\u0645\u064c",149,"\u0648\u064e\u062a\u064e\u0646\u0652\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0641\u064e\u0627\u0631\u0650\u0647\u0650\u064a\u0646\u064e",150,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",151,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",152,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",153,u.cD,154,"\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",155,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064c \u0644\u064e\u0647\u064e\u0627 \u0634\u0650\u0631\u0652\u0628\u064c \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0634\u0650\u0631\u0652\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",156,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0621\u064d \u0641\u064e\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",157,"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0646\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",158,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",159,u.z,160,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",161,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0644\u064f\u0648\u0637\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",162,"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",163,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",164,u.C,165,"\u0623\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0630\u0651\u064f\u0643\u0652\u0631\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",166,"\u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0639\u064e\u0627\u062f\u064f\u0648\u0646\u064e",167,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u0650 \u064a\u064e\u0627 \u0644\u064f\u0648\u0637\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0631\u064e\u062c\u0650\u064a\u0646\u064e",168,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0639\u064e\u0645\u064e\u0644\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0644\u0650\u064a\u0646\u064e",169,"\u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",170,"\u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",171,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",172,"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",173,u.d2,174,u.J,175,u.z,176,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0643\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",177,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",178,"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",179,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",180,u.C,181,"\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0633\u0650\u0631\u0650\u064a\u0646\u064e",182,"\u0648\u064e\u0632\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u064e\u0627\u0633\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u0650",183,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062e\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",184,"\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u0650\u0644\u0651\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",185,u.cD,186,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0646\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",187,"\u0641\u064e\u0623\u064e\u0633\u0652\u0642\u0650\u0637\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",188,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",189,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064f\u0644\u0651\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",190,u.J,191,u.z,192,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",193,"\u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0650\u064a\u0646\u064f",194,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e",195,"\u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u064d \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",196,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u0650\u064a \u0632\u064f\u0628\u064f\u0631\u0650 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",197,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064b \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0647\u064f \u0639\u064f\u0644\u064e\u0645\u064e\u0627\u0621\u064f \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",198,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u062c\u064e\u0645\u0650\u064a\u0646\u064e",199,"\u0641\u064e\u0642\u064e\u0631\u064e\u0623\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",200,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",201,"\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064e",202,"\u0641\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",203,"\u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0647\u064e\u0644\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",204,"\u0623\u064e\u0641\u064e\u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",205,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u0646\u0650\u064a\u0646\u064e",206,"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",207,"\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e",208,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0646\u064e",209,"\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",210,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f",211,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",212,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u0650 \u0644\u064e\u0645\u064e\u0639\u0652\u0632\u064f\u0648\u0644\u064f\u0648\u0646\u064e",213,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",214,"\u0648\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652 \u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u0650\u064a\u0646\u064e",215,"\u0648\u064e\u0627\u062e\u0652\u0641\u0650\u0636\u0652 \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",216,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0635\u064e\u0648\u0652\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",217,"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",218,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0631\u064e\u0627\u0643\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f",219,"\u0648\u064e\u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",220,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",221,"\u0647\u064e\u0644\u0652 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f",222,"\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0641\u0651\u064e\u0627\u0643\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",223,"\u064a\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",224,"\u0648\u064e\u0627\u0644\u0634\u0651\u064f\u0639\u064e\u0631\u064e\u0627\u0621\u064f \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0648\u064f\u0648\u0646\u064e",225,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0627\u062f\u064d \u064a\u064e\u0647\u0650\u064a\u0645\u064f\u0648\u0646\u064e",226,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",227,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0627\u0646\u0652\u062a\u064e\u0635\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u064a\u0651\u064e \u0645\u064f\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064d \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e"],t.v)
B.apx=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0637\u0633 \u06da \u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",2,"\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",3,u.ae,4,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0647\u064f\u0648\u0646\u064e",5,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u0633\u064e\u0631\u064f\u0648\u0646\u064e",6,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064f\u0644\u064e\u0642\u0651\u064e\u0649 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0652 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",7,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0622\u0646\u064e\u0633\u0652\u062a\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u0633\u064e\u0622\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u062e\u064e\u0628\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0622\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0634\u0650\u0647\u064e\u0627\u0628\u064d \u0642\u064e\u0628\u064e\u0633\u064d \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0635\u0652\u0637\u064e\u0644\u064f\u0648\u0646\u064e",8,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0623\u064e\u0646\u0652 \u0628\u064f\u0648\u0631\u0650\u0643\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",9,"\u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",10,"\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0622\u0647\u064e\u0627 \u062a\u064e\u0647\u0652\u062a\u064e\u0632\u0651\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u0652 \u06da \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",11,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0638\u064e\u0644\u064e\u0645\u064e \u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u064e \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0633\u064f\u0648\u0621\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",12,"\u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652 \u064a\u064e\u062f\u064e\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u064a\u0652\u0628\u0650\u0643\u064e \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u0652 \u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0648\u0621\u064d \u06d6 \u0641\u0650\u064a \u062a\u0650\u0633\u0652\u0639\u0650 \u0622\u064a\u064e\u0627\u062a\u064d \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",13,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",14,"\u0648\u064e\u062c\u064e\u062d\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u064a\u0652\u0642\u064e\u0646\u064e\u062a\u0652\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u064f\u0644\u064f\u0648\u0651\u064b\u0627 \u06da \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",15,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",16,"\u0648\u064e\u0648\u064e\u0631\u0650\u062b\u064e \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0639\u064f\u0644\u0651\u0650\u0645\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",17,"\u0648\u064e\u062d\u064f\u0634\u0650\u0631\u064e \u0644\u0650\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",18,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0646\u0651\u064e\u0645\u0652\u0644\u0650 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0646\u064e\u0645\u0652\u0644\u064e\u0629\u064c \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0645\u0652\u0644\u064f \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0637\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",19,"\u0641\u064e\u062a\u064e\u0628\u064e\u0633\u0651\u064e\u0645\u064e \u0636\u064e\u0627\u062d\u0650\u0643\u064b\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0648\u0652\u0632\u0650\u0639\u0652\u0646\u0650\u064a \u0623\u064e\u0646\u0652 \u0623\u064e\u0634\u0652\u0643\u064f\u0631\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u062a\u064e\u0631\u0652\u0636\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0646\u0650\u064a \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",20,"\u0648\u064e\u062a\u064e\u0641\u064e\u0642\u0651\u064e\u062f\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0644\u0650\u064a\u064e \u0644\u064e\u0627 \u0623\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u0652\u0647\u064f\u062f\u064e \u0623\u064e\u0645\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0626\u0650\u0628\u0650\u064a\u0646\u064e",21,"\u0644\u064e\u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u0623\u064e\u0630\u0652\u0628\u064e\u062d\u064e\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0652 \u0644\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u0650\u064a \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",22,"\u0641\u064e\u0645\u064e\u0643\u064e\u062b\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u0639\u0650\u064a\u062f\u064d \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062d\u064e\u0637\u0652\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064f\u062d\u0650\u0637\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u064e\u0625\u064d \u0628\u0650\u0646\u064e\u0628\u064e\u0625\u064d \u064a\u064e\u0642\u0650\u064a\u0646\u064d",23,"\u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u0629\u064b \u062a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0631\u0652\u0634\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",24,"\u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064e\u0627 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",25,"\u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0652\u0621\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",26,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650 \u06e9",27,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0623\u064e\u0635\u064e\u062f\u064e\u0642\u0652\u062a\u064e \u0623\u064e\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",28,"\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u0650\u0647\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",29,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",30,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",31,"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0623\u064e\u0641\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u0650\u064a \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f \u0642\u064e\u0627\u0637\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u0650",33,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064f\u0648\u0644\u064f\u0648 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0623\u064f\u0648\u0644\u064f\u0648 \u0628\u064e\u0623\u0652\u0633\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u0650\u064a\u0646\u064e",34,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u064f\u0648\u0643\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064b \u0623\u064e\u0641\u0652\u0633\u064e\u062f\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064b \u06d6 \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0647\u064e\u062f\u0650\u064a\u0651\u064e\u0629\u064d \u0641\u064e\u0646\u064e\u0627\u0638\u0650\u0631\u064e\u0629\u064c \u0628\u0650\u0645\u064e \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",36,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064f\u0645\u0650\u062f\u0651\u064f\u0648\u0646\u064e\u0646\u0650 \u0628\u0650\u0645\u064e\u0627\u0644\u064d \u0641\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0646\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u062f\u0650\u064a\u0651\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u062a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e",37,"\u0627\u0631\u0652\u062c\u0650\u0639\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0646\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u064d \u0644\u064e\u0627 \u0642\u0650\u0628\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u063a\u0650\u0631\u064f\u0648\u0646\u064e",38,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u0650\u064a \u0628\u0650\u0639\u064e\u0631\u0652\u0634\u0650\u0647\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",39,"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u0641\u0652\u0631\u0650\u064a\u062a\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0623\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u064a\u0643\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0645\u0650\u0646\u0652 \u0645\u064e\u0642\u064e\u0627\u0645\u0650\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",40,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u0650\u0644\u0652\u0645\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u064a\u0643\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u062f\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0637\u064e\u0631\u0652\u0641\u064f\u0643\u064e \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0622\u0647\u064f \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u0631\u0651\u064b\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0646\u0650\u064a \u0623\u064e\u0623\u064e\u0634\u0652\u0643\u064f\u0631\u064f \u0623\u064e\u0645\u0652 \u0623\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0643\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",41,"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0631\u0652\u0634\u064e\u0647\u064e\u0627 \u0646\u064e\u0646\u0652\u0638\u064f\u0631\u0652 \u0623\u064e\u062a\u064e\u0647\u0652\u062a\u064e\u062f\u0650\u064a \u0623\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",42,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0642\u0650\u064a\u0644\u064e \u0623\u064e\u0647\u064e\u0640\u0670\u0643\u064e\u0630\u064e\u0627 \u0639\u064e\u0631\u0652\u0634\u064f\u0643\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u06da \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u0646\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",43,"\u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",44,"\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0627\u062f\u0652\u062e\u064f\u0644\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u0631\u0652\u062d\u064e \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u062a\u0652\u0647\u064f \u062d\u064e\u0633\u0650\u0628\u064e\u062a\u0652\u0647\u064f \u0644\u064f\u062c\u0651\u064e\u0629\u064b \u0648\u064e\u0643\u064e\u0634\u064e\u0641\u064e\u062a\u0652 \u0639\u064e\u0646\u0652 \u0633\u064e\u0627\u0642\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0635\u064e\u0631\u0652\u062d\u064c \u0645\u064f\u0645\u064e\u0631\u0651\u064e\u062f\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e \u06d7 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0648\u064e\u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u062a\u064f \u0645\u064e\u0639\u064e \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0641\u064e\u0631\u0650\u064a\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",46,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0642\u064e\u0628\u0652\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u06d6 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",47,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0637\u0651\u064e\u064a\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u06da \u0642\u064e\u0627\u0644\u064e \u0637\u064e\u0627\u0626\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u062a\u064f\u0641\u0652\u062a\u064e\u0646\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u062a\u0650\u0633\u0652\u0639\u064e\u0629\u064f \u0631\u064e\u0647\u0652\u0637\u064d \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",49,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u064e\u0642\u064e\u0627\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064e\u0646\u0651\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0644\u0650\u0648\u064e\u0644\u0650\u064a\u0651\u0650\u0647\u0650 \u0645\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u0652\u0646\u064e\u0627 \u0645\u064e\u0647\u0652\u0644\u0650\u0643\u064e \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0645\u064e\u0643\u0652\u0631\u064b\u0627 \u0648\u064e\u0645\u064e\u0643\u064e\u0631\u0652\u0646\u064e\u0627 \u0645\u064e\u0643\u0652\u0631\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",51,"\u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0645\u064e\u0643\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",52,"\u0641\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064f\u0647\u064f\u0645\u0652 \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064b \u0628\u0650\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",54,"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0623\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",55,"\u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0634\u064e\u0647\u0652\u0648\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u062a\u064e\u062c\u0652\u0647\u064e\u0644\u064f\u0648\u0646\u064e",56,"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0622\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u0646\u064e\u0627\u0633\u064c \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",57,"\u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0642\u064e\u062f\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",58,u.d2,59,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0649\u0670 \u06d7 \u0622\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",60,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u062d\u064e\u062f\u064e\u0627\u0626\u0650\u0642\u064e \u0630\u064e\u0627\u062a\u064e \u0628\u064e\u0647\u0652\u062c\u064e\u0629\u064d \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0646\u0652\u0628\u0650\u062a\u064f\u0648\u0627 \u0634\u064e\u062c\u064e\u0631\u064e\u0647\u064e\u0627 \u06d7 \u0623\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u064a\u064e\u0639\u0652\u062f\u0650\u0644\u064f\u0648\u0646\u064e",61,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0642\u064e\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u062e\u0650\u0644\u064e\u0627\u0644\u064e\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u062d\u064e\u0627\u062c\u0650\u0632\u064b\u0627 \u06d7 \u0623\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",62,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u064a\u064f\u062c\u0650\u064a\u0628\u064f \u0627\u0644\u0652\u0645\u064f\u0636\u0652\u0637\u064e\u0631\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0647\u064f \u0648\u064e\u064a\u064e\u0643\u0652\u0634\u0650\u0641\u064f \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064e \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0623\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",63,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0628\u064f\u0634\u0652\u0631\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06d7 \u0623\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",64,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0623\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0647\u064e\u0627\u062a\u064f\u0648\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",65,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",66,"\u0628\u064e\u0644\u0650 \u0627\u062f\u0651\u064e\u0627\u0631\u064e\u0643\u064e \u0639\u0650\u0644\u0652\u0645\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0639\u064e\u0645\u064f\u0648\u0646\u064e",67,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e",68,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0648\u064f\u0639\u0650\u062f\u0652\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",69,"\u0642\u064f\u0644\u0652 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",70,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u064a \u0636\u064e\u064a\u0652\u0642\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",71,u.k,72,"\u0642\u064f\u0644\u0652 \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0631\u064e\u062f\u0650\u0641\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",74,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0643\u0650\u0646\u0651\u064f \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",75,"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u063a\u064e\u0627\u0626\u0650\u0628\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",76,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u064a\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",77,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",78,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u0652\u0636\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u062d\u064f\u0643\u0652\u0645\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",79,"\u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",80,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",81,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0647\u064e\u0627\u062f\u0650\u064a \u0627\u0644\u0652\u0639\u064f\u0645\u0652\u064a\u0650 \u0639\u064e\u0646\u0652 \u0636\u064e\u0644\u064e\u0627\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",82,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",83,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062d\u0652\u0634\u064f\u0631\u064f \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0641\u064e\u0648\u0652\u062c\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",84,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0623\u064e\u0645\u0651\u064e\u0627\u0630\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0648\u064e\u0642\u064e\u0639\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",86,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0644\u0650\u064a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",87,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u0652\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0641\u064e\u0632\u0650\u0639\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0623\u064e\u062a\u064e\u0648\u0652\u0647\u064f \u062f\u064e\u0627\u062e\u0650\u0631\u0650\u064a\u0646\u064e",88,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064e\u0627 \u062c\u064e\u0627\u0645\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u0645\u064f\u0631\u0651\u064f \u0645\u064e\u0631\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u0650 \u06da \u0635\u064f\u0646\u0652\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062a\u0652\u0642\u064e\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",89,"\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0632\u064e\u0639\u064d \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0622\u0645\u0650\u0646\u064f\u0648\u0646\u064e",90,"\u0648\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0643\u064f\u0628\u0651\u064e\u062a\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064e\u0644\u0652 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",91,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0631\u064e\u0628\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0628\u064e\u0644\u0652\u062f\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f \u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",92,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u062a\u0652\u0644\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e",93,"\u0648\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0633\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0641\u064e\u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0627\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e"],t.v)
B.ark=new A.U([1,u.bc,2,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",3,"\u0646\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u064e\u0625\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",4,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0634\u0650\u064a\u064e\u0639\u064b\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0636\u0652\u0639\u0650\u0641\u064f \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u0650\u064a \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",5,"\u0648\u064e\u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0646\u064e\u0645\u064f\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u0650\u064a\u0646\u064e",6,"\u0648\u064e\u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0646\u064f\u0631\u0650\u064a\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0639\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u0650\u0641\u0652\u062a\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0627\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u0650 \u0648\u064e\u062c\u064e\u0627\u0639\u0650\u0644\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",8,"\u0641\u064e\u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0637\u064e\u0647\u064f \u0622\u0644\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0648\u064e\u062d\u064e\u0632\u064e\u0646\u064b\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u062e\u064e\u0627\u0637\u0650\u0626\u0650\u064a\u0646\u064e",9,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0642\u064f\u0631\u0651\u064e\u062a\u064f \u0639\u064e\u064a\u0652\u0646\u064d \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0643\u064e \u06d6 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0641\u064f\u0624\u064e\u0627\u062f\u064f \u0623\u064f\u0645\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0627\u0631\u0650\u063a\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u062f\u064e\u062a\u0652 \u0644\u064e\u062a\u064f\u0628\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0631\u064e\u0628\u064e\u0637\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0647\u064e\u0627 \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0644\u0650\u0623\u064f\u062e\u0652\u062a\u0650\u0647\u0650 \u0642\u064f\u0635\u0651\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0628\u064e\u0635\u064f\u0631\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0639\u064e\u0646\u0652 \u062c\u064f\u0646\u064f\u0628\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0631\u064e\u0627\u0636\u0650\u0639\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0647\u064e\u0644\u0652 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650 \u0628\u064e\u064a\u0652\u062a\u064d \u064a\u064e\u0643\u0652\u0641\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0646\u064e\u0627\u0635\u0650\u062d\u064f\u0648\u0646\u064e",13,"\u0641\u064e\u0631\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0643\u064e\u064a\u0652 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0639\u064e\u064a\u0652\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064e \u0648\u064e\u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",15,"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0650 \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u0642\u0652\u062a\u064e\u062a\u0650\u0644\u064e\u0627\u0646\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u064e\u0627\u062b\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646\u0652 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650 \u0641\u064e\u0648\u064e\u0643\u064e\u0632\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0642\u064e\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0636\u0650\u0644\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",16,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0641\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",17,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0641\u064e\u0644\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627 \u0644\u0650\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",18,"\u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u062e\u064e\u0627\u0626\u0650\u0641\u064b\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0633\u0652\u062a\u064e\u0646\u0652\u0635\u064e\u0631\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0635\u0652\u0631\u0650\u062e\u064f\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u063a\u064e\u0648\u0650\u064a\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",19,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0637\u0650\u0634\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064e\u0646\u0650\u064a \u0643\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064e \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u06d6 \u0625\u0650\u0646\u0652 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u0644\u0650\u062d\u0650\u064a\u0646\u064e",20,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0635\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064e \u064a\u064e\u0623\u0652\u062a\u064e\u0645\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064e \u0644\u0650\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u062d\u0650\u064a\u0646\u064e",21,"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062e\u064e\u0627\u0626\u0650\u0641\u064b\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",22,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0648\u064e\u062c\u0651\u064e\u0647\u064e \u062a\u0650\u0644\u0652\u0642\u064e\u0627\u0621\u064e \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0646\u0650\u064a \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",23,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0631\u064e\u062f\u064e \u0645\u064e\u0627\u0621\u064e \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0648\u064e\u062c\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0633\u0652\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064f \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u062a\u064e\u0630\u064f\u0648\u062f\u064e\u0627\u0646\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u062e\u064e\u0637\u0652\u0628\u064f\u0643\u064f\u0645\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0633\u0652\u0642\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0635\u0652\u062f\u0650\u0631\u064e \u0627\u0644\u0631\u0651\u0650\u0639\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0646\u064e\u0627 \u0634\u064e\u064a\u0652\u062e\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",24,"\u0641\u064e\u0633\u064e\u0642\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u0650\u0644\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0642\u0650\u064a\u0631\u064c",25,"\u0641\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u062a\u064e\u0645\u0652\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0633\u0652\u062a\u0650\u062d\u0652\u064a\u064e\u0627\u0621\u064d \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064e \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0643\u064e \u0623\u064e\u062c\u0652\u0631\u064e \u0645\u064e\u0627 \u0633\u064e\u0642\u064e\u064a\u0652\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u0635\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0646\u064e\u062c\u064e\u0648\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",26,"\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u062c\u0650\u0631\u0652\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u062c\u064e\u0631\u0652\u062a\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0650\u064a\u0646\u064f",27,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0623\u064f\u0646\u0652\u0643\u0650\u062d\u064e\u0643\u064e \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0628\u0652\u0646\u064e\u062a\u064e\u064a\u0651\u064e \u0647\u064e\u0627\u062a\u064e\u064a\u0652\u0646\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062c\u064f\u0631\u064e\u0646\u0650\u064a \u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e \u062d\u0650\u062c\u064e\u062c\u064d \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u0652\u0645\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0634\u0652\u0631\u064b\u0627 \u0641\u064e\u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0634\u064f\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",28,"\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u06d6 \u0623\u064e\u064a\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u062c\u064e\u0644\u064e\u064a\u0652\u0646\u0650 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064f \u0641\u064e\u0644\u064e\u0627 \u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u064c",29,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u062c\u064e\u0644\u064e \u0648\u064e\u0633\u064e\u0627\u0631\u064e \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0622\u0646\u064e\u0633\u064e \u0645\u0650\u0646\u0652 \u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0646\u064e\u0627\u0631\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0627\u0645\u0652\u0643\u064f\u062b\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0622\u0646\u064e\u0633\u0652\u062a\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0622\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u062e\u064e\u0628\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u062c\u064e\u0630\u0652\u0648\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0635\u0652\u0637\u064e\u0644\u064f\u0648\u0646\u064e",30,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0627\u0637\u0650\u0626\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0646\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064f\u0642\u0652\u0639\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",31,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0622\u0647\u064e\u0627 \u062a\u064e\u0647\u0652\u062a\u064e\u0632\u0651\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u0652 \u06da \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0642\u0652\u0628\u0650\u0644\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",32,"\u0627\u0633\u0652\u0644\u064f\u0643\u0652 \u064a\u064e\u062f\u064e\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u064a\u0652\u0628\u0650\u0643\u064e \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u0652 \u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0648\u0621\u064d \u0648\u064e\u0627\u0636\u0652\u0645\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0647\u0652\u0628\u0650 \u06d6 \u0641\u064e\u0630\u064e\u0627\u0646\u0650\u0643\u064e \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",33,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u0650",34,"\u0648\u064e\u0623\u064e\u062e\u0650\u064a \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u0641\u0652\u0635\u064e\u062d\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652\u0647\u064f \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u0650\u062f\u0652\u0621\u064b\u0627 \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0646\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u0650",35,"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064e\u0634\u064f\u062f\u0651\u064f \u0639\u064e\u0636\u064f\u062f\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u062e\u0650\u064a\u0643\u064e \u0648\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064e\u0627 \u06da \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",36,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0641\u0652\u062a\u064e\u0631\u064b\u0649 \u0648\u064e\u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u0650\u064a \u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",37,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u0650\u064a \u0641\u064e\u0623\u064e\u0648\u0652\u0642\u0650\u062f\u0652 \u0644\u0650\u064a \u064a\u064e\u0627 \u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0641\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0635\u064e\u0631\u0652\u062d\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",39,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0647\u064f\u0648\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",40,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",41,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064b \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",42,"\u0648\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064b \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0642\u0652\u0628\u064f\u0648\u062d\u0650\u064a\u0646\u064e",43,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",44,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0652\u063a\u064e\u0631\u0652\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0636\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0642\u064f\u0631\u064f\u0648\u0646\u064b\u0627 \u0641\u064e\u062a\u064e\u0637\u064e\u0627\u0648\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062b\u064e\u0627\u0648\u0650\u064a\u064b\u0627 \u0641\u0650\u064a \u0623\u064e\u0647\u0652\u0644\u0650 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u062a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0622\u064a\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",48,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u0650\u062d\u0652\u0631\u064e\u0627\u0646\u0650 \u062a\u064e\u0638\u064e\u0627\u0647\u064e\u0631\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u064d \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",49,"\u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652\u0647\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",50,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064e \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0647\u064f\u062f\u064b\u0649 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",51,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0648\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",52,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",54,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u0652\u062a\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062f\u0652\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",55,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u064e \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u0646\u064e\u0628\u0652\u062a\u064e\u063a\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",56,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0628\u064e\u0628\u0652\u062a\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064e \u0646\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0646\u064e\u0627 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0622\u0645\u0650\u0646\u064b\u0627 \u064a\u064f\u062c\u0652\u0628\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0645\u0650\u0646\u0652 \u0644\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0628\u064e\u0637\u0650\u0631\u064e\u062a\u0652 \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u062a\u064e\u0647\u064e\u0627 \u06d6 \u0641\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0633\u0652\u0643\u064e\u0646\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u0650\u064a\u0646\u064e",59,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0641\u0650\u064a \u0623\u064f\u0645\u0651\u0650\u0647\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",61,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0648\u064e\u0639\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0627\u0642\u0650\u064a\u0647\u0650 \u0643\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u062a\u064e\u0627\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0636\u064e\u0631\u0650\u064a\u0646\u064e",62,u.v,63,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u063a\u064e\u0648\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0646\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",64,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062f\u064e\u0639\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u06da \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",65,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u062c\u064e\u0628\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",66,"\u0641\u064e\u0639\u064e\u0645\u0650\u064a\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",67,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u0650\u064a\u0646\u064e",68,"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u062e\u0652\u062a\u064e\u0627\u0631\u064f \u06d7 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",69,"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0643\u0650\u0646\u0651\u064f \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",70,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",71,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0633\u064e\u0631\u0652\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0636\u0650\u064a\u064e\u0627\u0621\u064d \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",72,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0633\u064e\u0631\u0652\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0644\u064e\u064a\u0652\u0644\u064d \u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0644\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",74,u.v,75,"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0647\u064e\u0627\u062a\u064f\u0648\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",76,"\u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0628\u064e\u063a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0646\u064f\u0648\u0632\u0650 \u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064e\u0647\u064f \u0644\u064e\u062a\u064e\u0646\u064f\u0648\u0621\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0635\u0652\u0628\u064e\u0629\u0650 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0631\u064e\u062d\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u062d\u0650\u064a\u0646\u064e",77,"\u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0633\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646\u0652 \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u063a\u0650 \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",78,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u062c\u064e\u0645\u0652\u0639\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",79,"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u0650\u064a \u0632\u0650\u064a\u0646\u064e\u062a\u0650\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u064f\u0648 \u062d\u064e\u0638\u0651\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",80,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0648\u064e\u064a\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u062b\u064e\u0648\u064e\u0627\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0646\u064e",81,"\u0641\u064e\u062e\u064e\u0633\u064e\u0641\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0628\u0650\u062f\u064e\u0627\u0631\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0641\u0650\u0626\u064e\u0629\u064d \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u0650\u064a\u0646\u064e",82,"\u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u0652\u0643\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06d6 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u062e\u064e\u0633\u064e\u0641\u064e \u0628\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u064a\u0652\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",83,"\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u064e\u0633\u064e\u0627\u062f\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",84,"\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u0652\u0632\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",85,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0631\u064e\u0636\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0644\u064e\u0631\u064e\u0627\u062f\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0627\u062f\u064d \u06da \u0642\u064f\u0644\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",86,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u0631\u0652\u062c\u064f\u0648 \u0623\u064e\u0646\u0652 \u064a\u064f\u0644\u0652\u0642\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",87,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0627\u062f\u0652\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",88,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u06d8 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0647\u064e\u0627\u0644\u0650\u0643\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u06da \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e"],t.v)
B.aoF=new A.U([1,u.d,2,"\u0623\u064e\u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062a\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u062a\u064e\u0646\u064f\u0648\u0646\u064e",3,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",4,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u0628\u0650\u0642\u064f\u0648\u0646\u064e\u0627 \u06da \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",5,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062c\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0622\u062a\u064d \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",6,"\u0648\u064e\u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0647\u064e\u062f\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0646\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",8,"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u0647\u064e\u062f\u064e\u0627\u0643\u064e \u0644\u0650\u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652\u0647\u064f\u0645\u064e\u0627 \u06da \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0646\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",10,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0648\u0630\u0650\u064a\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064e \u0646\u064e\u0635\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e",12,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u0652\u0646\u064e\u062d\u0652\u0645\u0650\u0644\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u062d\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0644\u064e\u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0646\u0651\u064e \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064b\u0627 \u0645\u064e\u0639\u064e \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0645\u0652\u0633\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0637\u0651\u064f\u0648\u0641\u064e\u0627\u0646\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",15,"\u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",16,"\u0648\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",17,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u062a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0641\u0652\u0643\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0641\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06d6 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064f\u0645\u064e\u0645\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",19,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064f\u0628\u0652\u062f\u0650\u0626\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",20,"\u0642\u064f\u0644\u0652 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0628\u064e\u062f\u064e\u0623\u064e \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u06da \u062b\u064f\u0645\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0646\u0652\u0634\u0650\u0626\u064f \u0627\u0644\u0646\u0651\u064e\u0634\u0652\u0623\u064e\u0629\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",21,"\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0631\u0652\u062d\u064e\u0645\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0642\u0652\u0644\u064e\u0628\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",23,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0626\u0650\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u0626\u0650\u0633\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",24,"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u0652 \u062d\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u0652\u062c\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u064b\u0627 \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0648\u064e\u064a\u064e\u0644\u0652\u0639\u064e\u0646\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",26,"\u0641\u064e\u0622\u0645\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0644\u064f\u0648\u0637\u064c \u06d8 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",27,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650 \u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",28,"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",29,"\u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0648\u064e\u062a\u064e\u0642\u0652\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u0648\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0646\u064e\u0627\u062f\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064e \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0626\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",30,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0646\u0652\u0635\u064f\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",31,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648 \u0623\u064e\u0647\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064f\u0648\u0637\u064b\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0644\u064e\u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",33,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064f\u0648\u0637\u064b\u0627 \u0633\u0650\u064a\u0621\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0636\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0630\u064e\u0631\u0652\u0639\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u064e\u062c\u0651\u064f\u0648\u0643\u064e \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u0643\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",34,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u0632\u0650\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0631\u0650\u062c\u0652\u0632\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064b \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064b\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0631\u0652\u062c\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",37,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062c\u0652\u0641\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0627\u062b\u0650\u0645\u0650\u064a\u0646\u064e",38,"\u0648\u064e\u0639\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0628\u0652\u0635\u0650\u0631\u0650\u064a\u0646\u064e",39,"\u0648\u064e\u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064e \u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0633\u064e\u0627\u0628\u0650\u0642\u0650\u064a\u0646\u064e",40,"\u0641\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062d\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0633\u064e\u0641\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",41,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0646\u0652\u0643\u064e\u0628\u064f\u0648\u062a\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u062a\u0652 \u0628\u064e\u064a\u0652\u062a\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0652\u0647\u064e\u0646\u064e \u0627\u0644\u0652\u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0644\u064e\u0628\u064e\u064a\u0652\u062a\u064f \u0627\u0644\u0652\u0639\u064e\u0646\u0652\u0643\u064e\u0628\u064f\u0648\u062a\u0650 \u06d6 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",42,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",43,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f \u0646\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",44,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",45,"\u0627\u062a\u0652\u0644\u064f \u0645\u064e\u0627 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u062a\u064e\u0646\u0652\u0647\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0641\u064e\u062d\u0652\u0634\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0630\u0650\u0643\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0644\u064e\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u06da \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u062a\u0652\u0644\u064f\u0648 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064f\u0637\u0651\u064f\u0647\u064f \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u06d6 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627\u0631\u0652\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0645\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0646\u064e",49,"\u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0622\u064a\u064e\u0627\u062a\u064c \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064c \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",50,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0627\u062a\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",51,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",52,"\u0642\u064f\u0644\u0652 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u06d6 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",53,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u062c\u064e\u0644\u064c \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0644\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",54,"\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064f\u062d\u0650\u064a\u0637\u064e\u0629\u064c \u0628\u0650\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",55,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u063a\u0652\u0634\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650 \u0623\u064e\u0631\u0652\u062c\u064f\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",56,"\u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u0652\u0636\u0650\u064a \u0648\u064e\u0627\u0633\u0650\u0639\u064e\u0629\u064c \u0641\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u064a\u064e \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u0650",57,"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0630\u064e\u0627\u0626\u0650\u0642\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0646\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u063a\u064f\u0631\u064e\u0641\u064b\u0627 \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0646\u0650\u0639\u0652\u0645\u064e \u0623\u064e\u062c\u0652\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e",59,u.c4,60,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0631\u0650\u0632\u0652\u0642\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",61,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",62,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",63,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",64,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u0652\u0648\u064c \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u064c \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0644\u064e\u0647\u0650\u064a\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0648\u064e\u0627\u0646\u064f \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",65,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0643\u0650\u0628\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u062f\u064e\u0639\u064e\u0648\u064f\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",66,"\u0644\u0650\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",67,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0622\u0645\u0650\u0646\u064b\u0627 \u0648\u064e\u064a\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u06da \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u0652\u0648\u064b\u0649 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",69,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0628\u064f\u0644\u064e\u0646\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e"],t.v)
B.asF=new A.U([1,u.d,2,"\u063a\u064f\u0644\u0650\u0628\u064e\u062a\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u0645\u064f",3,"\u0641\u0650\u064a \u0623\u064e\u062f\u0652\u0646\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u063a\u064e\u0644\u064e\u0628\u0650\u0647\u0650\u0645\u0652 \u0633\u064e\u064a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0646\u064e",4,"\u0641\u0650\u064a \u0628\u0650\u0636\u0652\u0639\u0650 \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u06d7 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u06da \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0641\u0652\u0631\u064e\u062d\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",5,"\u0628\u0650\u0646\u064e\u0635\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",6,"\u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",7,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0638\u064e\u0627\u0647\u0650\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",8,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",9,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u062b\u064e\u0627\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0639\u064e\u0645\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",10,"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u064e\u0627\u0621\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064f\u0648\u0623\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",11,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064f\u0628\u0652\u0644\u0650\u0633\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0621\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0646\u064e",15,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u0648\u0652\u0636\u064e\u0629\u064d \u064a\u064f\u062d\u0652\u0628\u064e\u0631\u064f\u0648\u0646\u064e",16,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",17,"\u0641\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0645\u0652\u0633\u064f\u0648\u0646\u064e \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0635\u0652\u0628\u0650\u062d\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0638\u0652\u0647\u0650\u0631\u064f\u0648\u0646\u064e",19,"\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u0650 \u0648\u064e\u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u064e\u0634\u064e\u0631\u064c \u062a\u064e\u0646\u0652\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0644\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u062e\u064e\u0644\u0652\u0642\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u064f \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",23,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0645\u064e\u0646\u064e\u0627\u0645\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0652\u0642\u064e \u062e\u064e\u0648\u0652\u0641\u064b\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u064b\u0627 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0643\u064f\u0645\u0652 \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0646\u064e",26,"\u0648\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0643\u064f\u0644\u0651\u064c \u0644\u064e\u0647\u064f \u0642\u064e\u0627\u0646\u0650\u062a\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0628\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",28,"\u0636\u064e\u0631\u064e\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0647\u064e\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u062e\u0650\u064a\u0641\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",29,"\u0628\u064e\u0644\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",30,"\u0641\u064e\u0623\u064e\u0642\u0650\u0645\u0652 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u064b\u0627 \u06da \u0641\u0650\u0637\u0652\u0631\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06da \u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064e \u0644\u0650\u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",31,"\u0645\u064f\u0646\u0650\u064a\u0628\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",32,"\u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0634\u0650\u064a\u064e\u0639\u064b\u0627 \u06d6 \u0643\u064f\u0644\u0651\u064f \u062d\u0650\u0632\u0652\u0628\u064d \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0636\u064f\u0631\u0651\u064c \u062f\u064e\u0639\u064e\u0648\u0652\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0650\u064a\u0628\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0630\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",34,"\u0644\u0650\u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",35,"\u0623\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0642\u0652\u0646\u064e\u0637\u064f\u0648\u0646\u064e",37,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",38,"\u0641\u064e\u0622\u062a\u0650 \u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u062d\u064e\u0642\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0652\u0647\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u0650\u0628\u064b\u0627 \u0644\u0650\u064a\u064e\u0631\u0652\u0628\u064f\u0648\u064e \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0628\u064f\u0648 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0632\u064e\u0643\u064e\u0627\u0629\u064d \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0652\u0647\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0646\u064e",40,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u06d6 \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",41,"\u0638\u064e\u0647\u064e\u0631\u064e \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u0650\u064a\u064f\u0630\u0650\u064a\u0642\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",42,"\u0642\u064f\u0644\u0652 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",43,"\u0641\u064e\u0623\u064e\u0642\u0650\u0645\u0652 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u0650\u0645\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",44,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064f\u0641\u0652\u0631\u064f\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0645\u0652\u0647\u064e\u062f\u064f\u0648\u0646\u064e",45,"\u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e\u0627\u062a\u064d \u0648\u064e\u0644\u0650\u064a\u064f\u0630\u0650\u064a\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064f \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u062c\u064e\u0627\u0621\u064f\u0648\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0642\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0645\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0646\u064e\u0635\u0652\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",48,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0641\u064e\u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0633\u064e\u062d\u064e\u0627\u0628\u064b\u0627 \u0641\u064e\u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0647\u064f \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0648\u064e\u062f\u0652\u0642\u064e \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0644\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0645\u064f\u0628\u0652\u0644\u0650\u0633\u0650\u064a\u0646\u064e",50,"\u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",51,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u0650\u064a\u062d\u064b\u0627 \u0641\u064e\u0631\u064e\u0623\u064e\u0648\u0652\u0647\u064f \u0645\u064f\u0635\u0652\u0641\u064e\u0631\u0651\u064b\u0627 \u0644\u064e\u0638\u064e\u0644\u0651\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",52,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0627\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",53,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0647\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0639\u064f\u0645\u0652\u064a\u0650 \u0639\u064e\u0646\u0652 \u0636\u064e\u0644\u064e\u0627\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",54,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0636\u064e\u0639\u0652\u0641\u064d \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0636\u064e\u0639\u0652\u0641\u064d \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0636\u064e\u0639\u0652\u0641\u064b\u0627 \u0648\u064e\u0634\u064e\u064a\u0652\u0628\u064e\u0629\u064b \u06da \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u062f\u0650\u064a\u0631\u064f",55,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u064d \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",56,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e \u0644\u064e\u0642\u064e\u062f\u0652 \u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0628\u064e\u0639\u0652\u062b\u0650 \u06d6 \u0641\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0639\u0652\u062b\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",57,"\u0641\u064e\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u064e\u0639\u0652\u0630\u0650\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0633\u0652\u062a\u064e\u0639\u0652\u062a\u064e\u0628\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0631\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u064d \u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u062c\u0650\u0626\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0646\u064e",59,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u0652\u0628\u064e\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",60,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0650\u0641\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e"],t.v)
B.ape=new A.U([1,u.d,2,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",3,"\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",4,u.ae,5,u.g,6,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u062a\u064e\u0631\u0650\u064a \u0644\u064e\u0647\u0652\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",7,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u0652\u0647\u064e\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a \u0623\u064f\u0630\u064f\u0646\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0642\u0652\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",8,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",9,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",10,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u064e\u0645\u064e\u062f\u064d \u062a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u06da \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u0652\u062c\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",11,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u062e\u064e\u0644\u0652\u0642\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u06da \u0628\u064e\u0644\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",12,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064f\u0642\u0652\u0645\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0623\u064e\u0646\u0650 \u0627\u0634\u0652\u0643\u064f\u0631\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",13,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064f\u0642\u0652\u0645\u064e\u0627\u0646\u064f \u0644\u0650\u0627\u0628\u0652\u0646\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0639\u0650\u0638\u064f\u0647\u064f \u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u0650\u0631\u0652\u0643\u064e \u0644\u064e\u0638\u064f\u0644\u0652\u0645\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",14,"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u0652\u0647\u064f \u0623\u064f\u0645\u0651\u064f\u0647\u064f \u0648\u064e\u0647\u0652\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0647\u0652\u0646\u064d \u0648\u064e\u0641\u0650\u0635\u064e\u0627\u0644\u064f\u0647\u064f \u0641\u0650\u064a \u0639\u064e\u0627\u0645\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0646\u0650 \u0627\u0634\u0652\u0643\u064f\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",15,"\u0648\u064e\u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u0647\u064e\u062f\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0648\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u0652\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",16,"\u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u064f \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u062e\u064e\u0631\u0652\u062f\u064e\u0644\u064d \u0641\u064e\u062a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u064a \u0635\u064e\u062e\u0652\u0631\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0623\u064e\u0648\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064c",17,"\u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0623\u064e\u0642\u0650\u0645\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u0652\u0645\u064f\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0627\u0646\u0652\u0647\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0643\u064e\u0631\u0650 \u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0632\u0652\u0645\u0650 \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",18,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0639\u0651\u0650\u0631\u0652 \u062e\u064e\u062f\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u0634\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064e\u0631\u064e\u062d\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u062e\u0652\u062a\u064e\u0627\u0644\u064d \u0641\u064e\u062e\u064f\u0648\u0631\u064d",19,"\u0648\u064e\u0627\u0642\u0652\u0635\u0650\u062f\u0652 \u0641\u0650\u064a \u0645\u064e\u0634\u0652\u064a\u0650\u0643\u064e \u0648\u064e\u0627\u063a\u0652\u0636\u064f\u0636\u0652 \u0645\u0650\u0646\u0652 \u0635\u064e\u0648\u0652\u062a\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0646\u0652\u0643\u064e\u0631\u064e \u0627\u0644\u0652\u0623\u064e\u0635\u0652\u0648\u064e\u0627\u062a\u0650 \u0644\u064e\u0635\u064e\u0648\u0652\u062a\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0631\u0650",20,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0623\u064e\u0633\u0652\u0628\u064e\u063a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0646\u0650\u0639\u064e\u0645\u064e\u0647\u064f \u0638\u064e\u0627\u0647\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0646\u064e\u0629\u064b \u06d7 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0646\u0650\u064a\u0631\u064d",21,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",22,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0633\u0652\u0644\u0650\u0645\u0652 \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064c \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u0633\u0652\u062a\u064e\u0645\u0652\u0633\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0631\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0648\u064f\u062b\u0652\u0642\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",23,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0652\u0643\u064e \u0643\u064f\u0641\u0652\u0631\u064f\u0647\u064f \u06da \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",24,"\u0646\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0636\u0652\u0637\u064e\u0631\u0651\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u064d",25,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0642\u064f\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",26,"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",27,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u0623\u064e\u0642\u0652\u0644\u064e\u0627\u0645\u064c \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064f \u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0633\u064e\u0628\u0652\u0639\u064e\u0629\u064f \u0623\u064e\u0628\u0652\u062d\u064f\u0631\u064d \u0645\u064e\u0627 \u0646\u064e\u0641\u0650\u062f\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",28,"\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0642\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u0652\u062b\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",29,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0643\u064f\u0644\u0651\u064c \u064a\u064e\u062c\u0652\u0631\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",30,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",31,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0634\u064e\u0643\u064f\u0648\u0631\u064d",32,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0648\u0652\u062c\u064c \u0643\u064e\u0627\u0644\u0638\u0651\u064f\u0644\u064e\u0644\u0650 \u062f\u064e\u0639\u064e\u0648\u064f\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u0650 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0642\u0652\u062a\u064e\u0635\u0650\u062f\u064c \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064f \u062e\u064e\u062a\u0651\u064e\u0627\u0631\u064d \u0643\u064e\u0641\u064f\u0648\u0631\u064d",33,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u062e\u0652\u0634\u064e\u0648\u0652\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0648\u064e\u0627\u0644\u0650\u062f\u064c \u0639\u064e\u0646\u0652 \u0648\u064e\u0644\u064e\u062f\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0648\u0652\u0644\u064f\u0648\u062f\u064c \u0647\u064f\u0648\u064e \u062c\u064e\u0627\u0632\u064d \u0639\u064e\u0646\u0652 \u0648\u064e\u0627\u0644\u0650\u062f\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u063a\u064e\u0631\u064f\u0648\u0631\u064f",34,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u0650\u0644\u0652\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u062b\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0631\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u064c \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f \u063a\u064e\u062f\u064b\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0631\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u064c \u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0623\u064e\u0631\u0652\u0636\u064d \u062a\u064e\u0645\u064f\u0648\u062a\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064c"],t.v)
B.api=new A.U([1,u.d,2,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",3,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",4,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u06d6 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u064d \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",5,"\u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u0652\u0631\u064f\u062c\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064d \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0642\u0652\u062f\u064e\u0627\u0631\u064f\u0647\u064f \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0646\u064e",6,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",7,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f \u06d6 \u0648\u064e\u0628\u064e\u062f\u064e\u0623\u064e \u062e\u064e\u0644\u0652\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",8,"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0646\u064e\u0633\u0652\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u064e\u0627\u0644\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u0645\u064e\u0647\u0650\u064a\u0646\u064d",9,"\u062b\u064f\u0645\u0651\u064e \u0633\u064e\u0648\u0651\u064e\u0627\u0647\u064f \u0648\u064e\u0646\u064e\u0641\u064e\u062e\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064f\u0648\u062d\u0650\u0647\u0650 \u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064e \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0644\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",11,"\u0642\u064f\u0644\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u064e\u0644\u064e\u0643\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064f\u0643\u0651\u0650\u0644\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0627\u0643\u0650\u0633\u064f\u0648 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0628\u0652\u0635\u064e\u0631\u0652\u0646\u064e\u0627 \u0648\u064e\u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0627\u0631\u0652\u062c\u0650\u0639\u0652\u0646\u064e\u0627 \u0646\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u0650\u0626\u0652\u0646\u064e\u0627 \u0644\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0646\u064e\u0641\u0652\u0633\u064d \u0647\u064f\u062f\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062d\u064e\u0642\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",14,"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f\u0645\u0652 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u0650\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",15,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u062e\u064e\u0631\u0651\u064f\u0648\u0627 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0633\u064e\u0628\u0651\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u06e9",16,"\u062a\u064e\u062a\u064e\u062c\u064e\u0627\u0641\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0648\u0652\u0641\u064b\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u064b\u0627 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",17,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0645\u064e\u0627 \u0623\u064f\u062e\u0652\u0641\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064f\u0631\u0651\u064e\u0629\u0650 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064d \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",18,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u0643\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0627\u0633\u0650\u0642\u064b\u0627 \u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u064f\u0648\u0646\u064e",19,"\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0645\u064e\u0623\u0652\u0648\u064e\u0649\u0670 \u0646\u064f\u0632\u064f\u0644\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0623\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0628\u064e\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0630\u064f\u0643\u0651\u0650\u0631\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0646\u0652\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0644\u0650\u0642\u064e\u0627\u0626\u0650\u0647\u0650 \u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0647\u064f\u062f\u064b\u0649 \u0644\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",24,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064b \u064a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",25,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0641\u0652\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",26,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u064a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",27,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0642\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0652\u062c\u064f\u0631\u064f\u0632\u0650 \u0641\u064e\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0628\u0650\u0647\u0650 \u0632\u064e\u0631\u0652\u0639\u064b\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",28,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0641\u064e\u062a\u0652\u062d\u064f \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",29,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u062a\u0652\u062d\u0650 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0638\u064e\u0631\u064f\u0648\u0646\u064e",30,"\u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0652 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e"],t.v)
B.aoL=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0627\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",2,"\u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",3,"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",4,"\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0631\u064e\u062c\u064f\u0644\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0644\u0652\u0628\u064e\u064a\u0652\u0646\u0650 \u0641\u0650\u064a \u062c\u064e\u0648\u0652\u0641\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u0626\u0650\u064a \u062a\u064f\u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u062f\u0652\u0639\u0650\u064a\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",5,"\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0644\u0650\u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u0652\u0633\u064e\u0637\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0645\u064e\u0648\u064e\u0627\u0644\u0650\u064a\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0641\u0650\u064a\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0637\u064e\u0623\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0645\u064e\u0627 \u062a\u064e\u0639\u064e\u0645\u0651\u064e\u062f\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",6,"\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0647\u064f \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u0650 \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627 \u06da \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u064e\u0633\u0652\u0637\u064f\u0648\u0631\u064b\u0627",7,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u0652 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u0650 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u06d6 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064b\u0627",8,"\u0644\u0650\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0639\u064e\u0646\u0652 \u0635\u0650\u062f\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",9,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064f\u0645\u0652 \u062c\u064f\u0646\u064f\u0648\u062f\u064c \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u0650\u064a\u062d\u064b\u0627 \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064b\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0648\u0652\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",10,"\u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0633\u0652\u0641\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0630\u0652 \u0632\u064e\u0627\u063a\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0627\u0644\u0652\u062d\u064e\u0646\u064e\u0627\u062c\u0650\u0631\u064e \u0648\u064e\u062a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0638\u0651\u064f\u0646\u064f\u0648\u0646\u064e\u0627",11,"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0628\u0652\u062a\u064f\u0644\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0632\u064f\u0644\u0652\u0632\u0650\u0644\u064f\u0648\u0627 \u0632\u0650\u0644\u0652\u0632\u064e\u0627\u0644\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627",12,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",13,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e \u064a\u064e\u062b\u0652\u0631\u0650\u0628\u064e \u0644\u064e\u0627 \u0645\u064f\u0642\u064e\u0627\u0645\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u06da \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u0630\u0650\u0646\u064f \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0648\u0652\u0631\u064e\u0629\u064c \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0628\u0650\u0639\u064e\u0648\u0652\u0631\u064e\u0629\u064d \u06d6 \u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0631\u064b\u0627",14,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062f\u064f\u062e\u0650\u0644\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0637\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0633\u064f\u0626\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064e \u0644\u064e\u0622\u062a\u064e\u0648\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0644\u064e\u0628\u0651\u064e\u062b\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",15,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0644\u064e\u0627 \u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0647\u0652\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064b\u0627",16,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u0650\u0631\u064e\u0627\u0631\u064f \u0625\u0650\u0646\u0652 \u0641\u064e\u0631\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0623\u064e\u0648\u0650 \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u0650 \u0648\u064e\u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0627 \u062a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",17,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u0652\u0635\u0650\u0645\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064b\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",18,"\u0642\u064e\u062f\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0639\u064e\u0648\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0626\u0650\u0644\u0650\u064a\u0646\u064e \u0644\u0650\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0647\u064e\u0644\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u0623\u0652\u0633\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",19,"\u0623\u064e\u0634\u0650\u062d\u0651\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u062e\u064e\u0648\u0652\u0641\u064f \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062a\u064e\u062f\u064f\u0648\u0631\u064f \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u063a\u0652\u0634\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064e \u0627\u0644\u0652\u062e\u064e\u0648\u0652\u0641\u064f \u0633\u064e\u0644\u064e\u0642\u064f\u0648\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u0629\u064d \u062d\u0650\u062f\u064e\u0627\u062f\u064d \u0623\u064e\u0634\u0650\u062d\u0651\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u0628\u064e\u0637\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",20,"\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",21,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0633\u0652\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u0644\u0650\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",22,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0635\u064e\u062f\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u062a\u064e\u0633\u0652\u0644\u0650\u064a\u0645\u064b\u0627",23,"\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0642\u064e\u0636\u064e\u0649\u0670 \u0646\u064e\u062d\u0652\u0628\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064b\u0627",24,"\u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0628\u0650\u0635\u0650\u062f\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",25,"\u0648\u064e\u0631\u064e\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0638\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064e \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0650\u064a\u0651\u064b\u0627 \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627",26,"\u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0627\u0647\u064e\u0631\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u0650\u0646\u0652 \u0635\u064e\u064a\u064e\u0627\u0635\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u064e\u0630\u064e\u0641\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0631\u0651\u064f\u0639\u0652\u0628\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064e\u0623\u0652\u0633\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627",27,"\u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0631\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062f\u0650\u064a\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u0636\u064b\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0637\u064e\u0626\u064f\u0648\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",28,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644\u0652 \u0644\u0650\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0646\u0651\u064e \u062a\u064f\u0631\u0650\u062f\u0652\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064e\u0627 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u064a\u0652\u0646\u064e \u0623\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u0652\u0643\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064f\u0633\u064e\u0631\u0651\u0650\u062d\u0652\u0643\u064f\u0646\u0651\u064e \u0633\u064e\u0631\u064e\u0627\u062d\u064b\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u064b\u0627",29,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0646\u0651\u064e \u062a\u064f\u0631\u0650\u062f\u0652\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0646\u0651\u064e \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",30,"\u064a\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0621\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0646\u0651\u064e \u0628\u0650\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064d \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u064a\u064f\u0636\u064e\u0627\u0639\u064e\u0641\u0652 \u0644\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0636\u0650\u0639\u0652\u0641\u064e\u064a\u0652\u0646\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",31,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u0646\u064f\u062a\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u062a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0646\u064f\u0624\u0652\u062a\u0650\u0647\u064e\u0627 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064e\u0627 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064b\u0627",32,"\u064a\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0621\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0644\u064e\u0633\u0652\u062a\u064f\u0646\u0651\u064e \u0643\u064e\u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u0650 \u06da \u0625\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u064a\u0652\u062a\u064f\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0636\u064e\u0639\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0641\u064e\u064a\u064e\u0637\u0652\u0645\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a \u0642\u064e\u0644\u0652\u0628\u0650\u0647\u0650 \u0645\u064e\u0631\u064e\u0636\u064c \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064b\u0627",33,"\u0648\u064e\u0642\u064e\u0631\u0652\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u062c\u0652\u0646\u064e \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u062c\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0652\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u0650\u064a\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u0639\u0652\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0630\u0652\u0647\u0650\u0628\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0633\u064e \u0623\u064e\u0647\u0652\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0648\u064e\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0637\u0652\u0647\u0650\u064a\u0631\u064b\u0627",34,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064b\u0627 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",35,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u062a\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0627\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0626\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0626\u0650\u0645\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0627\u0641\u0650\u0638\u0650\u064a\u0646\u064e \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0627\u0641\u0650\u0638\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0630\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0627\u0644\u0630\u0651\u064e\u0627\u0643\u0650\u0631\u064e\u0627\u062a\u0650 \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",36,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064d \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0635\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",37,"\u0648\u064e\u0625\u0650\u0630\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0645\u0652\u0633\u0650\u0643\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0632\u064e\u0648\u0652\u062c\u064e\u0643\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u062a\u064f\u062e\u0652\u0641\u0650\u064a \u0641\u0650\u064a \u0646\u064e\u0641\u0652\u0633\u0650\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0628\u0652\u062f\u0650\u064a\u0647\u0650 \u0648\u064e\u062a\u064e\u062e\u0652\u0634\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u062e\u0652\u0634\u064e\u0627\u0647\u064f \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0632\u064e\u064a\u0652\u062f\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0637\u064e\u0631\u064b\u0627 \u0632\u064e\u0648\u0651\u064e\u062c\u0652\u0646\u064e\u0627\u0643\u064e\u0647\u064e\u0627 \u0644\u0650\u0643\u064e\u064a\u0652 \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u062d\u064e\u0631\u064e\u062c\u064c \u0641\u0650\u064a \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650 \u0623\u064e\u062f\u0652\u0639\u0650\u064a\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0637\u064e\u0631\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627",38,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0645\u0650\u0646\u0652 \u062d\u064e\u0631\u064e\u062c\u064d \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u06d6 \u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u062f\u064e\u0631\u064b\u0627 \u0645\u064e\u0642\u0652\u062f\u064f\u0648\u0631\u064b\u0627",39,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0648\u0646\u064e \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0633\u0650\u064a\u0628\u064b\u0627",40,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0623\u064e\u0628\u064e\u0627 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652 \u0631\u0650\u062c\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062e\u064e\u0627\u062a\u064e\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",41,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0630\u0650\u0643\u0652\u0631\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",42,"\u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0647\u064f \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",43,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u064f\u0647\u064f \u0644\u0650\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",44,"\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u06da \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064b\u0627",45,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u064b\u0627 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",46,"\u0648\u064e\u062f\u064e\u0627\u0639\u0650\u064a\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u0648\u064e\u0633\u0650\u0631\u064e\u0627\u062c\u064b\u0627 \u0645\u064f\u0646\u0650\u064a\u0631\u064b\u0627",47,"\u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",48,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u062f\u064e\u0639\u0652 \u0623\u064e\u0630\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",49,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0643\u064e\u062d\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u062f\u0651\u064e\u0629\u064d \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0633\u064e\u0631\u0651\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0631\u064e\u0627\u062d\u064b\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u064b\u0627",50,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u062d\u0652\u0644\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0622\u062a\u064e\u064a\u0652\u062a\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u064a\u064e\u0645\u0650\u064a\u0646\u064f\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064e\u0641\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0645\u0651\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0645\u0651\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u062e\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u062e\u064e\u0627\u0644\u064e\u0627\u062a\u0650\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u0650\u064a \u0647\u064e\u0627\u062c\u064e\u0631\u0652\u0646\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u0629\u064b \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0629\u064b \u0625\u0650\u0646\u0652 \u0648\u064e\u0647\u064e\u0628\u064e\u062a\u0652 \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064e\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u064b \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d7 \u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0643\u064e\u064a\u0652\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u062d\u064e\u0631\u064e\u062c\u064c \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",51,"\u062a\u064f\u0631\u0652\u062c\u0650\u064a \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u062a\u064f\u0624\u0652\u0648\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u064e\u0646\u0652 \u062a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u0628\u0652\u062a\u064e\u063a\u064e\u064a\u0652\u062a\u064e \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0639\u064e\u0632\u064e\u0644\u0652\u062a\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u0651\u064e \u0648\u064e\u064a\u064e\u0631\u0652\u0636\u064e\u064a\u0652\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0646\u0651\u064e \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0644\u0650\u064a\u0645\u064b\u0627",52,"\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064d \u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e\u0643\u064e \u062d\u064f\u0633\u0652\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u064a\u064e\u0645\u0650\u064a\u0646\u064f\u0643\u064e \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0631\u064e\u0642\u0650\u064a\u0628\u064b\u0627",53,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u064d \u063a\u064e\u064a\u0652\u0631\u064e \u0646\u064e\u0627\u0638\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u0650\u064a\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0639\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0623\u0652\u0646\u0650\u0633\u0650\u064a\u0646\u064e \u0644\u0650\u062d\u064e\u062f\u0650\u064a\u062b\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u0652\u0630\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0641\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u0650\u064a \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0637\u0652\u0647\u064e\u0631\u064f \u0644\u0650\u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u0652\u0630\u064f\u0648\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0627 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",54,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0628\u0652\u062f\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0623\u064e\u0648\u0652 \u062a\u064f\u062e\u0652\u0641\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",55,"\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u0650 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u0650 \u0623\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u06d7 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",56,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u064e\u0647\u064f \u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u06da \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0635\u064e\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627 \u062a\u064e\u0633\u0652\u0644\u0650\u064a\u0645\u064b\u0627",57,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0630\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u0647\u0650\u064a\u0646\u064b\u0627",58,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0630\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0645\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0641\u064e\u0642\u064e\u062f\u0650 \u0627\u062d\u0652\u062a\u064e\u0645\u064e\u0644\u064f\u0648\u0627 \u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0625\u0650\u062b\u0652\u0645\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",59,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644\u0652 \u0644\u0650\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064f\u062f\u0652\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u062c\u064e\u0644\u064e\u0627\u0628\u0650\u064a\u0628\u0650\u0647\u0650\u0646\u0651\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064f\u0639\u0652\u0631\u064e\u0641\u0652\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0630\u064e\u064a\u0652\u0646\u064e \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",60,"\u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0631\u0652\u062c\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u064e\u0646\u064f\u063a\u0652\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0648\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",61,"\u0645\u064e\u0644\u0652\u0639\u064f\u0648\u0646\u0650\u064a\u0646\u064e \u06d6 \u0623\u064e\u064a\u0652\u0646\u064e\u0645\u064e\u0627 \u062b\u064f\u0642\u0650\u0641\u064f\u0648\u0627 \u0623\u064f\u062e\u0650\u0630\u064f\u0648\u0627 \u0648\u064e\u0642\u064f\u062a\u0651\u0650\u0644\u064f\u0648\u0627 \u062a\u064e\u0642\u0652\u062a\u0650\u064a\u0644\u064b\u0627",62,"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u0652\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064b\u0627",63,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u0652\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",64,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",65,"\u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",66,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u0642\u064e\u0644\u0651\u064e\u0628\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e\u0627",67,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0633\u064e\u0627\u062f\u064e\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0628\u064e\u0631\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e\u0627",68,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0622\u062a\u0650\u0647\u0650\u0645\u0652 \u0636\u0650\u0639\u0652\u0641\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0639\u0652\u0646\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",69,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0630\u064e\u0648\u0652\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062c\u0650\u064a\u0647\u064b\u0627",70,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0633\u064e\u062f\u0650\u064a\u062f\u064b\u0627",71,"\u064a\u064f\u0635\u0652\u0644\u0650\u062d\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u0627\u0632\u064e \u0641\u064e\u0648\u0652\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",72,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0631\u064e\u0636\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u0627\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0641\u064e\u0623\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u0652\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0634\u0652\u0641\u064e\u0642\u0652\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u062d\u064e\u0645\u064e\u0644\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0638\u064e\u0644\u064f\u0648\u0645\u064b\u0627 \u062c\u064e\u0647\u064f\u0648\u0644\u064b\u0627",73,"\u0644\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627"],t.v)
B.asp=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",2,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u0644\u0650\u062c\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0632\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u064f\u062c\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f",3,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u06d6 \u0642\u064f\u0644\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0632\u064f\u0628\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064f \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0635\u0652\u063a\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",4,"\u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",5,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0627\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u0631\u0650\u062c\u0652\u0632\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064c",6,"\u0648\u064e\u064a\u064e\u0631\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u0650",7,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0647\u064e\u0644\u0652 \u0646\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u064d \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0645\u064f\u0632\u0651\u0650\u0642\u0652\u062a\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u0645\u064e\u0632\u0651\u064e\u0642\u064d \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d",8,"\u0623\u064e\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0645\u0652 \u0628\u0650\u0647\u0650 \u062c\u0650\u0646\u0651\u064e\u0629\u064c \u06d7 \u0628\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u0650 \u0627\u0644\u0652\u0628\u064e\u0639\u0650\u064a\u062f\u0650",9,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0652 \u0646\u064e\u0634\u064e\u0623\u0652 \u0646\u064e\u062e\u0652\u0633\u0650\u0641\u0652 \u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0623\u064e\u0648\u0652 \u0646\u064f\u0633\u0652\u0642\u0650\u0637\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0628\u0652\u062f\u064d \u0645\u064f\u0646\u0650\u064a\u0628\u064d",10,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u06d6 \u064a\u064e\u0627 \u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0623\u064e\u0648\u0651\u0650\u0628\u0650\u064a \u0645\u064e\u0639\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064e \u06d6 \u0648\u064e\u0623\u064e\u0644\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062f\u064e",11,"\u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u0652 \u0633\u064e\u0627\u0628\u0650\u063a\u064e\u0627\u062a\u064d \u0648\u064e\u0642\u064e\u062f\u0651\u0650\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0631\u0652\u062f\u0650 \u06d6 \u0648\u064e\u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",12,"\u0648\u064e\u0644\u0650\u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u063a\u064f\u062f\u064f\u0648\u0651\u064f\u0647\u064e\u0627 \u0634\u064e\u0647\u0652\u0631\u064c \u0648\u064e\u0631\u064e\u0648\u064e\u0627\u062d\u064f\u0647\u064e\u0627 \u0634\u064e\u0647\u0652\u0631\u064c \u06d6 \u0648\u064e\u0623\u064e\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0639\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0642\u0650\u0637\u0652\u0631\u0650 \u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0632\u0650\u063a\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0646\u064f\u0630\u0650\u0642\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",13,"\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0645\u064e\u062d\u064e\u0627\u0631\u0650\u064a\u0628\u064e \u0648\u064e\u062a\u064e\u0645\u064e\u0627\u062b\u0650\u064a\u0644\u064e \u0648\u064e\u062c\u0650\u0641\u064e\u0627\u0646\u064d \u0643\u064e\u0627\u0644\u0652\u062c\u064e\u0648\u064e\u0627\u0628\u0650 \u0648\u064e\u0642\u064f\u062f\u064f\u0648\u0631\u064d \u0631\u064e\u0627\u0633\u0650\u064a\u064e\u0627\u062a\u064d \u06da \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0622\u0644\u064e \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0634\u064f\u0643\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0634\u0651\u064e\u0643\u064f\u0648\u0631\u064f",14,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0645\u064e\u0627 \u062f\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u0652\u0633\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062e\u064e\u0631\u0651\u064e \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u064e \u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0647\u0650\u064a\u0646\u0650",15,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0633\u064e\u0628\u064e\u0625\u064d \u0641\u0650\u064a \u0645\u064e\u0633\u0652\u0643\u064e\u0646\u0650\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0629\u064c \u06d6 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650 \u0639\u064e\u0646\u0652 \u064a\u064e\u0645\u0650\u064a\u0646\u064d \u0648\u064e\u0634\u0650\u0645\u064e\u0627\u0644\u064d \u06d6 \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06da \u0628\u064e\u0644\u0652\u062f\u064e\u0629\u064c \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064c \u0648\u064e\u0631\u064e\u0628\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",16,"\u0641\u064e\u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064e\u064a\u0652\u0644\u064e \u0627\u0644\u0652\u0639\u064e\u0631\u0650\u0645\u0650 \u0648\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0630\u064e\u0648\u064e\u0627\u062a\u064e\u064a\u0652 \u0623\u064f\u0643\u064f\u0644\u064d \u062e\u064e\u0645\u0652\u0637\u064d \u0648\u064e\u0623\u064e\u062b\u0652\u0644\u064d \u0648\u064e\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u0652 \u0633\u0650\u062f\u0652\u0631\u064d \u0642\u064e\u0644\u0650\u064a\u0644\u064d",17,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0647\u064e\u0644\u0652 \u0646\u064f\u062c\u064e\u0627\u0632\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u0641\u064f\u0648\u0631\u064e",18,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064f\u0631\u064b\u0649 \u0638\u064e\u0627\u0647\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0652\u0631\u064e \u06d6 \u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u064a\u064e\u0627\u0644\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064b\u0627 \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",19,"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0628\u064e\u0627\u0639\u0650\u062f\u0652 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u0633\u0652\u0641\u064e\u0627\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u064e \u0648\u064e\u0645\u064e\u0632\u0651\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u0645\u064e\u0632\u0651\u064e\u0642\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0634\u064e\u0643\u064f\u0648\u0631\u064d",20,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064f \u0638\u064e\u0646\u0651\u064e\u0647\u064f \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u06d7 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u064c",22,"\u0642\u064f\u0644\u0650 \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u0650\u0631\u0652\u0643\u064d \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0638\u064e\u0647\u0650\u064a\u0631\u064d",23,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0641\u064f\u0632\u0651\u0650\u0639\u064e \u0639\u064e\u0646\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627\u0630\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",24,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0648\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064b\u0649 \u0623\u064e\u0648\u0652 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",25,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062c\u0652\u0631\u064e\u0645\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",26,"\u0642\u064f\u0644\u0652 \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0641\u0652\u062a\u064e\u062d\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u062a\u0651\u064e\u0627\u062d\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",27,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u0652\u062d\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e \u06d6 \u0643\u064e\u0644\u0651\u064e\u0627 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",28,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0641\u0651\u064e\u0629\u064b \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",29,u.k,30,"\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0623\u0652\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0642\u0652\u062f\u0650\u0645\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0646\u0652 \u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u0652\u0642\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",32,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0627 \u0623\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0635\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",33,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064f\u0636\u0652\u0639\u0650\u0641\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0645\u064e\u0643\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u0652 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u0646\u064e\u0643\u0652\u0641\u064f\u0631\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u06da \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u062f\u064e\u0627\u0645\u064e\u0629\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064e \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0647\u064e\u0644\u0652 \u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u064f\u0648\u0647\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",36,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0632\u064f\u0644\u0652\u0641\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0636\u0651\u0650\u0639\u0652\u0641\u0650 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064f\u0631\u064f\u0641\u064e\u0627\u062a\u0650 \u0622\u0645\u0650\u0646\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0627\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",39,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064f\u0647\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",40,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062d\u0652\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0623\u064e\u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",41,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e \u06d6 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",42,"\u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",43,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064c \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0641\u0652\u0643\u064c \u0645\u064f\u0641\u0652\u062a\u064e\u0631\u064b\u0649 \u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",44,"\u0648\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u062a\u064f\u0628\u064d \u064a\u064e\u062f\u0652\u0631\u064f\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064d",45,"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0639\u0652\u0634\u064e\u0627\u0631\u064e \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0631\u064f\u0633\u064f\u0644\u0650\u064a \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",46,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u06d6 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062b\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u0641\u064f\u0631\u064e\u0627\u062f\u064e\u0649\u0670 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627 \u06da \u0645\u064e\u0627 \u0628\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062c\u0650\u0646\u0651\u064e\u0629\u064d \u06da \u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d",47,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",48,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0642\u0652\u0630\u0650\u0641\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0639\u064e\u0644\u0651\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u063a\u064f\u064a\u064f\u0648\u0628\u0650",49,"\u0642\u064f\u0644\u0652 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0628\u0652\u062f\u0650\u0626\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0650\u064a\u062f\u064f",50,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0636\u064e\u0644\u064e\u0644\u0652\u062a\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u06d6 \u0648\u064e\u0625\u0650\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u064a\u0652\u062a\u064f \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0642\u064e\u0631\u0650\u064a\u0628\u064c",51,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u0641\u064e\u0632\u0650\u0639\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0627 \u0641\u064e\u0648\u0652\u062a\u064e \u0648\u064e\u0623\u064f\u062e\u0650\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0642\u064e\u0631\u0650\u064a\u0628\u064d",52,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u062a\u0651\u064e\u0646\u064e\u0627\u0648\u064f\u0634\u064f \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",53,"\u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u064a\u064e\u0642\u0652\u0630\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",54,"\u0648\u064e\u062d\u0650\u064a\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0641\u064f\u0639\u0650\u0644\u064e \u0628\u0650\u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0639\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u064f\u0631\u0650\u064a\u0628\u064d"],t.v)
B.ar4=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0627\u0639\u0650\u0644\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0623\u064e\u062c\u0652\u0646\u0650\u062d\u064e\u0629\u064d \u0645\u064e\u062b\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u062b\u064f\u0644\u064e\u0627\u062b\u064e \u0648\u064e\u0631\u064f\u0628\u064e\u0627\u0639\u064e \u06da \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",2,"\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u062d\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0641\u064e\u0644\u064e\u0627 \u0645\u064f\u0645\u0652\u0633\u0650\u0643\u064e \u0644\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0645\u0652\u0633\u0650\u0643\u0652 \u0641\u064e\u0644\u064e\u0627 \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",3,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u0627\u0644\u0650\u0642\u064d \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0630\u0651\u0650\u0628\u064e\u062a\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",5,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u063a\u064e\u0631\u064f\u0648\u0631\u064f",6,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0641\u064e\u0627\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u062d\u0650\u0632\u0652\u0628\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",7,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",8,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0633\u064f\u0648\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650 \u0641\u064e\u0631\u064e\u0622\u0647\u064f \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u0652\u0647\u064e\u0628\u0652 \u0646\u064e\u0641\u0652\u0633\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0633\u064e\u0631\u064e\u0627\u062a\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u0652\u0646\u064e\u0639\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0641\u064e\u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0633\u064e\u062d\u064e\u0627\u0628\u064b\u0627 \u0641\u064e\u0633\u064f\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0644\u064e\u062f\u064d \u0645\u064e\u064a\u0651\u0650\u062a\u064d \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f",10,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0635\u0652\u0639\u064e\u062f\u064f \u0627\u0644\u0652\u0643\u064e\u0644\u0650\u0645\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0645\u064e\u0644\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064f \u064a\u064e\u0631\u0652\u0641\u064e\u0639\u064f\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u06d6 \u0648\u064e\u0645\u064e\u0643\u0652\u0631\u064f \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0628\u064f\u0648\u0631\u064f",11,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0645\u0650\u0646\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0645\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0642\u064e\u0635\u064f \u0645\u0650\u0646\u0652 \u0639\u064f\u0645\u064f\u0631\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",12,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e\u0627\u0646\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u0652\u0628\u064c \u0641\u064f\u0631\u064e\u0627\u062a\u064c \u0633\u064e\u0627\u0626\u0650\u063a\u064c \u0634\u064e\u0631\u064e\u0627\u0628\u064f\u0647\u064f \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u0650\u0644\u0652\u062d\u064c \u0623\u064f\u062c\u064e\u0627\u062c\u064c \u06d6 \u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064d \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u062d\u0652\u0645\u064b\u0627 \u0637\u064e\u0631\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u062a\u064e\u0633\u0652\u062a\u064e\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u062d\u0650\u0644\u0652\u064a\u064e\u0629\u064b \u062a\u064e\u0644\u0652\u0628\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u064e\u0648\u064e\u0627\u062e\u0650\u0631\u064e \u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",13,"\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0643\u064f\u0644\u0651\u064c \u064a\u064e\u062c\u0652\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u0650\u0637\u0652\u0645\u0650\u064a\u0631\u064d",14,"\u0625\u0650\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u062f\u064f\u0639\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0648\u0652 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u0650\u0631\u0652\u0643\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064e \u0645\u0650\u062b\u0652\u0644\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064d",15,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",16,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d",17,"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u064d",18,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u064c \u0648\u0650\u0632\u0652\u0631\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u064f\u062b\u0652\u0642\u064e\u0644\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u0645\u0652\u0644\u0650\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u062d\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0634\u064e\u064a\u0652\u0621\u064c \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670 \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",19,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",20,"\u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u064f",21,"\u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0638\u0651\u0650\u0644\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0631\u064f\u0648\u0631\u064f",22,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0645\u064f\u0633\u0652\u0645\u0650\u0639\u064d \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u0650",23,"\u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c",24,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c",25,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0650\u064a\u0631\u0650",26,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",27,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u064d \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u062c\u064f\u062f\u064e\u062f\u064c \u0628\u0650\u064a\u0636\u064c \u0648\u064e\u062d\u064f\u0645\u0652\u0631\u064c \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u063a\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0628\u064f \u0633\u064f\u0648\u062f\u064c",28,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0628\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064f \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u0634\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u0639\u064f\u0644\u064e\u0645\u064e\u0627\u0621\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",29,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u0631\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0644\u064e\u0646\u0652 \u062a\u064e\u0628\u064f\u0648\u0631\u064e",30,"\u0644\u0650\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0634\u064e\u0643\u064f\u0648\u0631\u064c",31,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0644\u064e\u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",32,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0635\u0652\u0637\u064e\u0641\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0638\u064e\u0627\u0644\u0650\u0645\u064c \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0642\u0652\u062a\u064e\u0635\u0650\u062f\u064c \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0628\u0650\u0642\u064c \u0628\u0650\u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u0650 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",33,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0647\u064e\u0628\u064d \u0648\u064e\u0644\u064f\u0624\u0652\u0644\u064f\u0624\u064b\u0627 \u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0631\u0650\u064a\u0631\u064c",34,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0630\u0652\u0647\u064e\u0628\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0632\u064e\u0646\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0634\u064e\u0643\u064f\u0648\u0631\u064c",35,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u064c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064f\u063a\u064f\u0648\u0628\u064c",36,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0627\u0631\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0647\u064e\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u064f\u0648\u0631\u064d",37,"\u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0635\u0652\u0637\u064e\u0631\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u064e\u0627 \u0646\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0639\u064e\u0645\u0651\u0650\u0631\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0641\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064e \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064f \u06d6 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",38,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0627\u0644\u0650\u0645\u064f \u063a\u064e\u064a\u0652\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",39,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0644\u064e\u0627\u0626\u0650\u0641\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064f\u0641\u0652\u0631\u064f\u0647\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064f\u0641\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0642\u0652\u062a\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064f\u0641\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u064b\u0627",40,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u0650\u0631\u0652\u0643\u064c \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0623\u064e\u0645\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u062a\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0625\u0650\u0646\u0652 \u064a\u064e\u0639\u0650\u062f\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",41,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0632\u064f\u0648\u0644\u064e\u0627 \u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0632\u064e\u0627\u0644\u064e\u062a\u064e\u0627 \u0625\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0633\u064e\u0643\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",42,"\u0648\u064e\u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u0652\u062f\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0626\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0644\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0646\u0651\u064e \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0644\u0652\u0623\u064f\u0645\u064e\u0645\u0650 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0641\u064f\u0648\u0631\u064b\u0627",43,"\u0627\u0633\u0652\u062a\u0650\u0643\u0652\u0628\u064e\u0627\u0631\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0643\u0652\u0631\u064e \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u0650 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u064a\u0642\u064f \u0627\u0644\u0652\u0645\u064e\u0643\u0652\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u06da \u0641\u064e\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064f\u0646\u0651\u064e\u062a\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u06da \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062d\u0652\u0648\u0650\u064a\u0644\u064b\u0627",44,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u0652\u062c\u0650\u0632\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",45,"\u0648\u064e\u0644\u064e\u0648\u0652 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064e\u0647\u0652\u0631\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627"],t.v)
B.ash=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u0633",2,"\u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",3,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",4,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",5,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",6,"\u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0622\u0628\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",7,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062d\u064e\u0642\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",8,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064b\u0627 \u0641\u064e\u0647\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0630\u0652\u0642\u064e\u0627\u0646\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0642\u0652\u0645\u064e\u062d\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627 \u0641\u064e\u0623\u064e\u063a\u0652\u0634\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0623\u064e\u0646\u0652\u0630\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0646\u0652\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",11,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064f \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0648\u064e\u062e\u064e\u0634\u0650\u064a\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f \u0628\u0650\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",12,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0646\u064e\u0643\u0652\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u0622\u062b\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u062d\u0652\u0635\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0625\u0650\u0645\u064e\u0627\u0645\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",13,"\u0648\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",14,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0632\u0651\u064e\u0632\u0652\u0646\u064e\u0627 \u0628\u0650\u062b\u064e\u0627\u0644\u0650\u062b\u064d \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",15,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0648\u0646\u064e",16,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",17,"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",18,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u062a\u064e\u0637\u064e\u064a\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0631\u0652\u062c\u064f\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",19,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0637\u064e\u0627\u0626\u0650\u0631\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06da \u0623\u064e\u0626\u0650\u0646\u0652 \u0630\u064f\u0643\u0651\u0650\u0631\u0652\u062a\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064f\u0633\u0652\u0631\u0650\u0641\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0635\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0631\u064e\u062c\u064f\u0644\u064c \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",21,"\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u064a\u064e \u0644\u064e\u0627 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",23,"\u0623\u064e\u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0625\u0650\u0646\u0652 \u064a\u064f\u0631\u0650\u062f\u0652\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u064d \u0644\u064e\u0627 \u062a\u064f\u063a\u0652\u0646\u0650 \u0639\u064e\u0646\u0651\u0650\u064a \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0642\u0650\u0630\u064f\u0648\u0646\u0650",24,"\u0625\u0650\u0646\u0651\u0650\u064a \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",25,"\u0625\u0650\u0646\u0651\u0650\u064a \u0622\u0645\u064e\u0646\u0652\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u0650",26,"\u0642\u0650\u064a\u0644\u064e \u0627\u062f\u0652\u062e\u064f\u0644\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",27,"\u0628\u0650\u0645\u064e\u0627 \u063a\u064e\u0641\u064e\u0631\u064e \u0644\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0643\u0652\u0631\u064e\u0645\u0650\u064a\u0646\u064e",28,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u062c\u064f\u0646\u0652\u062f\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u0632\u0650\u0644\u0650\u064a\u0646\u064e",29,"\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u062e\u064e\u0627\u0645\u0650\u062f\u064f\u0648\u0646\u064e",30,"\u064a\u064e\u0627 \u062d\u064e\u0633\u0652\u0631\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u06da \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",31,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",32,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064c \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064c \u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0622\u064a\u064e\u0629\u064c \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u062a\u064e\u0629\u064f \u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062d\u064e\u0628\u0651\u064b\u0627 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u062e\u0650\u064a\u0644\u064d \u0648\u064e\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064d \u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064f\u064a\u064f\u0648\u0646\u0650",35,"\u0644\u0650\u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652\u0647\u064f \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",36,"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0646\u0652\u0628\u0650\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0622\u064a\u064e\u0629\u064c \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064f \u0646\u064e\u0633\u0652\u0644\u064e\u062e\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u064f\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0644\u0650\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064d \u0644\u064e\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u0650",39,"\u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u0646\u064e\u0627\u0632\u0650\u0644\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064e \u0643\u064e\u0627\u0644\u0652\u0639\u064f\u0631\u0652\u062c\u064f\u0648\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u062f\u0650\u064a\u0645\u0650",40,"\u0644\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u062f\u0652\u0631\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064f \u0633\u064e\u0627\u0628\u0650\u0642\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0643\u064d \u064a\u064e\u0633\u0652\u0628\u064e\u062d\u064f\u0648\u0646\u064e",41,"\u0648\u064e\u0622\u064a\u064e\u0629\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u062d\u064f\u0648\u0646\u0650",42,"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0645\u064e\u0627 \u064a\u064e\u0631\u0652\u0643\u064e\u0628\u064f\u0648\u0646\u064e",43,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0646\u064e\u0634\u064e\u0623\u0652 \u0646\u064f\u063a\u0652\u0631\u0650\u0642\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u0635\u064e\u0631\u0650\u064a\u062e\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0642\u064e\u0630\u064f\u0648\u0646\u064e",44,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",45,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",46,u.d1,47,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u064f\u0637\u0652\u0639\u0650\u0645\u064f \u0645\u064e\u0646\u0652 \u0644\u064e\u0648\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0637\u0652\u0639\u064e\u0645\u064e\u0647\u064f \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",48,u.k,49,"\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062e\u0650\u0635\u0651\u0650\u0645\u064f\u0648\u0646\u064e",50,"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u062a\u064e\u0648\u0652\u0635\u0650\u064a\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",51,"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062c\u0652\u062f\u064e\u0627\u062b\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0646\u0652\u0633\u0650\u0644\u064f\u0648\u0646\u064e",52,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0646\u0652 \u0628\u064e\u0639\u064e\u062b\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u0631\u0652\u0642\u064e\u062f\u0650\u0646\u064e\u0627 \u06dc \u06d7 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064e\u0635\u064e\u062f\u064e\u0642\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e",53,"\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064c \u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",54,"\u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u062a\u064f\u0638\u0652\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",55,"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0641\u0650\u064a \u0634\u064f\u063a\u064f\u0644\u064d \u0641\u064e\u0627\u0643\u0650\u0647\u064f\u0648\u0646\u064e",56,"\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0638\u0650\u0644\u064e\u0627\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u0650 \u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u064f\u0648\u0646\u064e",57,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",58,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u064d \u0631\u064e\u062d\u0650\u064a\u0645\u064d",59,"\u0648\u064e\u0627\u0645\u0652\u062a\u064e\u0627\u0632\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",60,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0639\u0652\u0647\u064e\u062f\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0622\u062f\u064e\u0645\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",61,"\u0648\u064e\u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u0650\u064a \u06da \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",62,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u062c\u0650\u0628\u0650\u0644\u0651\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",63,"\u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",64,"\u0627\u0635\u0652\u0644\u064e\u0648\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",65,"\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u062e\u0652\u062a\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0646\u064e\u0627 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",66,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u0637\u064e\u0645\u064e\u0633\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0628\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u064e \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",67,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u0645\u064e\u0633\u064e\u062e\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u0645\u064f\u0636\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0646\u064f\u0639\u064e\u0645\u0651\u0650\u0631\u0652\u0647\u064f \u0646\u064f\u0646\u064e\u0643\u0651\u0650\u0633\u0652\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",69,"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0634\u0651\u0650\u0639\u0652\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",70,"\u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u064a\u0651\u064b\u0627 \u0648\u064e\u064a\u064e\u062d\u0650\u0642\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",71,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0627\u0644\u0650\u0643\u064f\u0648\u0646\u064e",72,"\u0648\u064e\u0630\u064e\u0644\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0631\u064e\u0643\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",73,"\u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0648\u064e\u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0628\u064f \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",74,"\u0648\u064e\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",75,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064f\u0646\u0652\u062f\u064c \u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",76,"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0632\u064f\u0646\u0652\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064f\u0647\u064f\u0645\u0652 \u06d8 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",77,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",78,"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0648\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0639\u0650\u0638\u064e\u0627\u0645\u064e \u0648\u064e\u0647\u0650\u064a\u064e \u0631\u064e\u0645\u0650\u064a\u0645\u064c",79,"\u0642\u064f\u0644\u0652 \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0647\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u062e\u064e\u0644\u0652\u0642\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",80,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650 \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u0636\u064e\u0631\u0650 \u0646\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u062a\u064f\u0648\u0642\u0650\u062f\u064f\u0648\u0646\u064e",81,"\u0623\u064e\u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0642\u064e\u0627\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064e \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062e\u064e\u0644\u0651\u064e\u0627\u0642\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",82,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f\u0647\u064f \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",83,"\u0641\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e"],t.v)
B.asE=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0641\u0651\u064e\u0627\u062a\u0650 \u0635\u064e\u0641\u0651\u064b\u0627",2,"\u0641\u064e\u0627\u0644\u0632\u0651\u064e\u0627\u062c\u0650\u0631\u064e\u0627\u062a\u0650 \u0632\u064e\u062c\u0652\u0631\u064b\u0627",3,"\u0641\u064e\u0627\u0644\u062a\u0651\u064e\u0627\u0644\u0650\u064a\u064e\u0627\u062a\u0650 \u0630\u0650\u0643\u0652\u0631\u064b\u0627",4,"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0648\u064e\u0627\u062d\u0650\u062f\u064c",5,"\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0642\u0650",6,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u064d \u0627\u0644\u0652\u0643\u064e\u0648\u064e\u0627\u0643\u0650\u0628\u0650",7,"\u0648\u064e\u062d\u0650\u0641\u0652\u0638\u064b\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064e\u0627\u0631\u0650\u062f\u064d",8,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0645\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u064a\u064f\u0642\u0652\u0630\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0627\u0646\u0650\u0628\u064d",9,"\u062f\u064f\u062d\u064f\u0648\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0648\u064e\u0627\u0635\u0650\u0628\u064c",10,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062e\u064e\u0637\u0650\u0641\u064e \u0627\u0644\u0652\u062e\u064e\u0637\u0652\u0641\u064e\u0629\u064e \u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064e\u0647\u064f \u0634\u0650\u0647\u064e\u0627\u0628\u064c \u062b\u064e\u0627\u0642\u0650\u0628\u064c",11,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u0623\u064e\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d \u0644\u064e\u0627\u0632\u0650\u0628\u064d",12,"\u0628\u064e\u0644\u0652 \u0639\u064e\u062c\u0650\u0628\u0652\u062a\u064e \u0648\u064e\u064a\u064e\u0633\u0652\u062e\u064e\u0631\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",14,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0622\u064a\u064e\u0629\u064b \u064a\u064e\u0633\u0652\u062a\u064e\u0633\u0652\u062e\u0650\u0631\u064f\u0648\u0646\u064e",15,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",16,"\u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",17,"\u0623\u064e\u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",18,"\u0642\u064f\u0644\u0652 \u0646\u064e\u0639\u064e\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062f\u064e\u0627\u062e\u0650\u0631\u064f\u0648\u0646\u064e",19,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0632\u064e\u062c\u0652\u0631\u064e\u0629\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064c \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",21,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",22,"\u0627\u062d\u0652\u0634\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",23,"\u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0627\u0647\u0652\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",24,"\u0648\u064e\u0642\u0650\u0641\u064f\u0648\u0647\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064f\u0648\u0646\u064e",25,"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u0635\u064e\u0631\u064f\u0648\u0646\u064e",26,"\u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0645\u064f\u0633\u0652\u062a\u064e\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e",27,u.a,28,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",29,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",30,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u06d6 \u0628\u064e\u0644\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0637\u064e\u0627\u063a\u0650\u064a\u0646\u064e",31,"\u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0630\u064e\u0627\u0626\u0650\u0642\u064f\u0648\u0646\u064e",32,"\u0641\u064e\u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",33,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u0634\u0652\u062a\u064e\u0631\u0650\u0643\u064f\u0648\u0646\u064e",34,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",35,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062a\u064e\u0627\u0631\u0650\u0643\u064f\u0648 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0644\u0650\u0634\u064e\u0627\u0639\u0650\u0631\u064d \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064d",37,"\u0628\u064e\u0644\u0652 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",38,"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0630\u064e\u0627\u0626\u0650\u0642\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u0650",39,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",40,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",41,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0632\u0652\u0642\u064c \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064c",42,"\u0641\u064e\u0648\u064e\u0627\u0643\u0650\u0647\u064f \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0643\u0652\u0631\u064e\u0645\u064f\u0648\u0646\u064e",43,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",44,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u064d \u0645\u064f\u062a\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650\u064a\u0646\u064e",45,"\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0643\u064e\u0623\u0652\u0633\u064d \u0645\u0650\u0646\u0652 \u0645\u064e\u0639\u0650\u064a\u0646\u064d",46,"\u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064e \u0644\u064e\u0630\u0651\u064e\u0629\u064d \u0644\u0650\u0644\u0634\u0651\u064e\u0627\u0631\u0650\u0628\u0650\u064a\u0646\u064e",47,"\u0644\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u063a\u064e\u0648\u0652\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u064a\u064f\u0646\u0652\u0632\u064e\u0641\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0635\u0650\u0631\u064e\u0627\u062a\u064f \u0627\u0644\u0637\u0651\u064e\u0631\u0652\u0641\u0650 \u0639\u0650\u064a\u0646\u064c",49,"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0628\u064e\u064a\u0652\u0636\u064c \u0645\u064e\u0643\u0652\u0646\u064f\u0648\u0646\u064c",50,"\u0641\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",51,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0626\u0650\u0644\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0646\u064c",52,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e",53,"\u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u062f\u0650\u064a\u0646\u064f\u0648\u0646\u064e",54,"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0637\u0651\u064e\u0644\u0650\u0639\u064f\u0648\u0646\u064e",55,"\u0641\u064e\u0627\u0637\u0651\u064e\u0644\u064e\u0639\u064e \u0641\u064e\u0631\u064e\u0622\u0647\u064f \u0641\u0650\u064a \u0633\u064e\u0648\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",56,"\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u0650\u062f\u0652\u062a\u064e \u0644\u064e\u062a\u064f\u0631\u0652\u062f\u0650\u064a\u0646\u0650",57,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0646\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0636\u064e\u0631\u0650\u064a\u0646\u064e",58,"\u0623\u064e\u0641\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064e\u064a\u0651\u0650\u062a\u0650\u064a\u0646\u064e",59,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0648\u0652\u062a\u064e\u062a\u064e\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",60,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",61,"\u0644\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u064f\u0648\u0646\u064e",62,"\u0623\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0646\u064f\u0632\u064f\u0644\u064b\u0627 \u0623\u064e\u0645\u0652 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064f \u0627\u0644\u0632\u0651\u064e\u0642\u0651\u064f\u0648\u0645\u0650",63,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",64,"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064c \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0641\u0650\u064a \u0623\u064e\u0635\u0652\u0644\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",65,"\u0637\u064e\u0644\u0652\u0639\u064f\u0647\u064e\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0631\u064f\u0621\u064f\u0648\u0633\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650",66,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0622\u0643\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627\u0644\u0650\u0626\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0628\u064f\u0637\u064f\u0648\u0646\u064e",67,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0644\u064e\u0634\u064e\u0648\u0652\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u0650\u064a\u0645\u064d",68,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",69,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0644\u0652\u0641\u064e\u0648\u0652\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0636\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",70,"\u0641\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0647\u0652\u0631\u064e\u0639\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",72,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e",73,"\u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0630\u064e\u0631\u0650\u064a\u0646\u064e",74,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",75,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u0627\u062f\u064e\u0627\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064c \u0641\u064e\u0644\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e",76,"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0652\u0628\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",77,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a\u0646\u064e",78,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",79,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",80,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",81,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",82,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",83,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650 \u0644\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",84,"\u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0628\u0650\u0642\u064e\u0644\u0652\u0628\u064d \u0633\u064e\u0644\u0650\u064a\u0645\u064d",85,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",86,"\u0623\u064e\u0626\u0650\u0641\u0652\u0643\u064b\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e",87,"\u0641\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",88,"\u0641\u064e\u0646\u064e\u0638\u064e\u0631\u064e \u0646\u064e\u0638\u0652\u0631\u064e\u0629\u064b \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650",89,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0633\u064e\u0642\u0650\u064a\u0645\u064c",90,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e",91,"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",92,"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",93,"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0636\u064e\u0631\u0652\u0628\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",94,"\u0641\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0644\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0632\u0650\u0641\u0651\u064f\u0648\u0646\u064e",95,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0646\u0652\u062d\u0650\u062a\u064f\u0648\u0646\u064e",96,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",97,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0628\u0652\u0646\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",98,"\u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0643\u064e\u064a\u0652\u062f\u064b\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0641\u064e\u0644\u0650\u064a\u0646\u064e",99,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0630\u064e\u0627\u0647\u0650\u0628\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0633\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",100,"\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",101,"\u0641\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u063a\u064f\u0644\u064e\u0627\u0645\u064d \u062d\u064e\u0644\u0650\u064a\u0645\u064d",102,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0639\u0652\u064a\u064e \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0646\u064e\u0627\u0645\u0650 \u0623\u064e\u0646\u0651\u0650\u064a \u0623\u064e\u0630\u0652\u0628\u064e\u062d\u064f\u0643\u064e \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670 \u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0627\u0641\u0652\u0639\u064e\u0644\u0652 \u0645\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u064e\u0631\u064f \u06d6 \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",103,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e\u0627 \u0648\u064e\u062a\u064e\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0652\u062c\u064e\u0628\u0650\u064a\u0646\u0650",104,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f",105,"\u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u0651\u064e\u0642\u0652\u062a\u064e \u0627\u0644\u0631\u0651\u064f\u0624\u0652\u064a\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",106,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",107,"\u0648\u064e\u0641\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0630\u0650\u0628\u0652\u062d\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",108,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",109,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",110,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",111,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",112,"\u0648\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0646\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",113,"\u0648\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u06da \u0648\u064e\u0645\u0650\u0646\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u064c \u0648\u064e\u0638\u064e\u0627\u0644\u0650\u0645\u064c \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0645\u064f\u0628\u0650\u064a\u0646\u064c",114,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",115,"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0652\u0628\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",116,"\u0648\u064e\u0646\u064e\u0635\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",117,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0628\u0650\u064a\u0646\u064e",118,"\u0648\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064e",119,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",120,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",121,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",122,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",123,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u0652\u064a\u064e\u0627\u0633\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",124,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",125,"\u0623\u064e\u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0628\u064e\u0639\u0652\u0644\u064b\u0627 \u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u0650\u064a\u0646\u064e",126,"\u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",127,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",128,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",129,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",130,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0644\u0652 \u064a\u064e\u0627\u0633\u0650\u064a\u0646\u064e",131,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",132,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",133,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064f\u0648\u0637\u064b\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",134,"\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",135,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",136,"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",137,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0645\u064f\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064f\u0635\u0652\u0628\u0650\u062d\u0650\u064a\u0646\u064e",138,"\u0648\u064e\u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",139,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",140,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0628\u064e\u0642\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u062d\u064f\u0648\u0646\u0650",141,"\u0641\u064e\u0633\u064e\u0627\u0647\u064e\u0645\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062f\u0652\u062d\u064e\u0636\u0650\u064a\u0646\u064e",142,"\u0641\u064e\u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0645\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0648\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0644\u0650\u064a\u0645\u064c",143,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u0650\u064a\u0646\u064e",144,"\u0644\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a \u0628\u064e\u0637\u0652\u0646\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",145,"\u0641\u064e\u0646\u064e\u0628\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0631\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0633\u064e\u0642\u0650\u064a\u0645\u064c",146,"\u0648\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u064a\u064e\u0642\u0652\u0637\u0650\u064a\u0646\u064d",147,"\u0648\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u0650\u0627\u0626\u064e\u0629\u0650 \u0623\u064e\u0644\u0652\u0641\u064d \u0623\u064e\u0648\u0652 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0648\u0646\u064e",148,"\u0641\u064e\u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",149,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0641\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0646\u064f\u0648\u0646\u064e",150,"\u0623\u064e\u0645\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0646\u064e",151,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0625\u0650\u0641\u0652\u0643\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",152,"\u0648\u064e\u0644\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",153,"\u0623\u064e\u0635\u0652\u0637\u064e\u0641\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u0646\u0650\u064a\u0646\u064e",154,"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",155,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",156,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",157,"\u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",158,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0646\u064e\u0633\u064e\u0628\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u064f\u062d\u0652\u0636\u064e\u0631\u064f\u0648\u0646\u064e",159,"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",160,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",161,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",162,"\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0641\u064e\u0627\u062a\u0650\u0646\u0650\u064a\u0646\u064e",163,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0635\u064e\u0627\u0644\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",164,"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u064e\u0642\u064e\u0627\u0645\u064c \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064c",165,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0641\u0651\u064f\u0648\u0646\u064e",166,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e",167,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",168,"\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",169,"\u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",170,"\u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",171,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f\u0646\u064e\u0627 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",172,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0646\u0652\u0635\u064f\u0648\u0631\u064f\u0648\u0646\u064e",173,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064f\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",174,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",175,"\u0648\u064e\u0623\u064e\u0628\u0652\u0635\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",176,"\u0623\u064e\u0641\u064e\u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",177,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0650\u0633\u064e\u0627\u062d\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0633\u064e\u0627\u0621\u064e \u0635\u064e\u0628\u064e\u0627\u062d\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0630\u064e\u0631\u0650\u064a\u0646\u064e",178,"\u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",179,"\u0648\u064e\u0623\u064e\u0628\u0652\u0635\u0650\u0631\u0652 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",180,"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",181,"\u0648\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",182,"\u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e"],t.v)
B.arl=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0635 \u06da \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0630\u0650\u064a \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650",2,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0639\u0650\u0632\u0651\u064e\u0629\u064d \u0648\u064e\u0634\u0650\u0642\u064e\u0627\u0642\u064d",3,"\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u0646\u064d \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0627 \u0648\u064e\u0644\u064e\u0627\u062a\u064e \u062d\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u064e\u0627\u0635\u064d",4,"\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c",5,"\u0623\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u0622\u0644\u0650\u0647\u064e\u0629\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u0652\u0621\u064c \u0639\u064f\u062c\u064e\u0627\u0628\u064c",6,"\u0648\u064e\u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0650 \u0627\u0645\u0652\u0634\u064f\u0648\u0627 \u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u0652\u0621\u064c \u064a\u064f\u0631\u064e\u0627\u062f\u064f",7,"\u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u0650\u0644\u0651\u064e\u0629\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0642\u064c",8,"\u0623\u064e\u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0646\u064e\u0627 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u064a \u06d6 \u0628\u064e\u0644\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0650",9,"\u0623\u064e\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u0650",10,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0641\u064e\u0644\u0652\u064a\u064e\u0631\u0652\u062a\u064e\u0642\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0628\u0650",11,"\u062c\u064f\u0646\u0652\u062f\u064c \u0645\u064e\u0627 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0645\u064e\u0647\u0652\u0632\u064f\u0648\u0645\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u0650",12,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064c \u0648\u064e\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u062a\u064e\u0627\u062f\u0650",13,"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0643\u064e\u0629\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064f",14,"\u0625\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",15,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u064e\u0627\u0642\u064d",16,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u062c\u0651\u0650\u0644\u0652 \u0644\u064e\u0646\u064e\u0627 \u0642\u0650\u0637\u0651\u064e\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",17,"\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0639\u064e\u0628\u0652\u062f\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0630\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u062f\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",18,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0634\u0652\u0631\u064e\u0627\u0642\u0650",19,"\u0648\u064e\u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u062d\u0652\u0634\u064f\u0648\u0631\u064e\u0629\u064b \u06d6 \u0643\u064f\u0644\u0651\u064c \u0644\u064e\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",20,"\u0648\u064e\u0634\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064f\u0644\u0652\u0643\u064e\u0647\u064f \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0641\u064e\u0635\u0652\u0644\u064e \u0627\u0644\u0652\u062e\u0650\u0637\u064e\u0627\u0628\u0650",21,"\u0648\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u0646\u064e\u0628\u064e\u0623\u064f \u0627\u0644\u0652\u062e\u064e\u0635\u0652\u0645\u0650 \u0625\u0650\u0630\u0652 \u062a\u064e\u0633\u064e\u0648\u0651\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u0650\u062d\u0652\u0631\u064e\u0627\u0628\u064e",22,"\u0625\u0650\u0630\u0652 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0641\u064e\u0641\u064e\u0632\u0650\u0639\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u062e\u064e\u0635\u0652\u0645\u064e\u0627\u0646\u0650 \u0628\u064e\u063a\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064f\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0641\u064e\u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0637\u0650\u0637\u0652 \u0648\u064e\u0627\u0647\u0652\u062f\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0621\u0650 \u0627\u0644\u0635\u0651\u0650\u0631\u064e\u0627\u0637\u0650",23,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u062e\u0650\u064a \u0644\u064e\u0647\u064f \u062a\u0650\u0633\u0652\u0639\u064c \u0648\u064e\u062a\u0650\u0633\u0652\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0639\u0652\u062c\u064e\u0629\u064b \u0648\u064e\u0644\u0650\u064a\u064e \u0646\u064e\u0639\u0652\u062c\u064e\u0629\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064c \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0643\u0652\u0641\u0650\u0644\u0652\u0646\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0646\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u0650\u0637\u064e\u0627\u0628\u0650",24,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u0652 \u0638\u064e\u0644\u064e\u0645\u064e\u0643\u064e \u0628\u0650\u0633\u064f\u0624\u064e\u0627\u0644\u0650 \u0646\u064e\u0639\u0652\u062c\u064e\u062a\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u0650\u0639\u064e\u0627\u062c\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064f\u0644\u064e\u0637\u064e\u0627\u0621\u0650 \u0644\u064e\u064a\u064e\u0628\u0652\u063a\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0638\u064e\u0646\u0651\u064e \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064f \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627\u0647\u064f \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0648\u064e\u062e\u064e\u0631\u0651\u064e \u0631\u064e\u0627\u0643\u0650\u0639\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0628\u064e \u06e9",25,"\u0641\u064e\u063a\u064e\u0641\u064e\u0631\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0632\u064f\u0644\u0652\u0641\u064e\u0649\u0670 \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u064e \u0645\u064e\u0622\u0628\u064d",26,"\u064a\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u064b \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u062d\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0627\u0644\u0652\u0647\u064e\u0648\u064e\u0649\u0670 \u0641\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",27,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0627\u0637\u0650\u0644\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0638\u064e\u0646\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",28,"\u0623\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0643\u064e\u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0644\u0652\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u0650",29,"\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064c \u0644\u0650\u064a\u064e\u062f\u0651\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0627 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",30,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u0650\u062f\u064e\u0627\u0648\u064f\u0648\u062f\u064e \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u06da \u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",31,"\u0625\u0650\u0630\u0652 \u0639\u064f\u0631\u0650\u0636\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0627\u0644\u0635\u0651\u064e\u0627\u0641\u0650\u0646\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u062c\u0650\u064a\u064e\u0627\u062f\u064f",32,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062d\u0652\u0628\u064e\u0628\u0652\u062a\u064f \u062d\u064f\u0628\u0651\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0648\u064e\u0627\u0631\u064e\u062a\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0628\u0650",33,"\u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u06d6 \u0641\u064e\u0637\u064e\u0641\u0650\u0642\u064e \u0645\u064e\u0633\u0652\u062d\u064b\u0627 \u0628\u0650\u0627\u0644\u0633\u0651\u064f\u0648\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650",34,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u0650\u0647\u0650 \u062c\u064e\u0633\u064e\u062f\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u064e\u0627\u0628\u064e",35,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u0645\u064f\u0644\u0652\u0643\u064b\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0628\u064e\u063a\u0650\u064a \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u064f",36,"\u0641\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0631\u064f\u062e\u064e\u0627\u0621\u064b \u062d\u064e\u064a\u0652\u062b\u064f \u0623\u064e\u0635\u064e\u0627\u0628\u064e",37,"\u0648\u064e\u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0628\u064e\u0646\u0651\u064e\u0627\u0621\u064d \u0648\u064e\u063a\u064e\u0648\u0651\u064e\u0627\u0635\u064d",38,"\u0648\u064e\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0635\u0652\u0641\u064e\u0627\u062f\u0650",39,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u0637\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0641\u064e\u0627\u0645\u0652\u0646\u064f\u0646\u0652 \u0623\u064e\u0648\u0652 \u0623\u064e\u0645\u0652\u0633\u0650\u0643\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",40,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0632\u064f\u0644\u0652\u0641\u064e\u0649\u0670 \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u064e \u0645\u064e\u0622\u0628\u064d",41,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0639\u064e\u0628\u0652\u062f\u064e\u0646\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0628\u0650\u0646\u064f\u0635\u0652\u0628\u064d \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064d",42,"\u0627\u0631\u0652\u0643\u064f\u0636\u0652 \u0628\u0650\u0631\u0650\u062c\u0652\u0644\u0650\u0643\u064e \u06d6 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064f\u063a\u0652\u062a\u064e\u0633\u064e\u0644\u064c \u0628\u064e\u0627\u0631\u0650\u062f\u064c \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u064c",43,"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",44,"\u0648\u064e\u062e\u064f\u0630\u0652 \u0628\u0650\u064a\u064e\u062f\u0650\u0643\u064e \u0636\u0650\u063a\u0652\u062b\u064b\u0627 \u0641\u064e\u0627\u0636\u0652\u0631\u0650\u0628\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0646\u064e\u062b\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0635\u064e\u0627\u0628\u0650\u0631\u064b\u0627 \u06da \u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",45,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u0652\u0642\u064f\u0648\u0628\u064e \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u062f\u0650\u064a \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650",46,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u062e\u0652\u0644\u064e\u0635\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u064d \u0630\u0650\u0643\u0652\u0631\u064e\u0649 \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",47,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u0637\u064e\u0641\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u064a\u064e\u0627\u0631\u0650",48,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0633\u064e\u0639\u064e \u0648\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u0641\u0652\u0644\u0650 \u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062e\u0652\u064a\u064e\u0627\u0631\u0650",49,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u062d\u064f\u0633\u0652\u0646\u064e \u0645\u064e\u0622\u0628\u064d",50,"\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0639\u064e\u062f\u0652\u0646\u064d \u0645\u064f\u0641\u064e\u062a\u0651\u064e\u062d\u064e\u0629\u064b \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064f",51,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064d \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u064d",52,"\u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0635\u0650\u0631\u064e\u0627\u062a\u064f \u0627\u0644\u0637\u0651\u064e\u0631\u0652\u0641\u0650 \u0623\u064e\u062a\u0652\u0631\u064e\u0627\u0628\u064c",53,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",54,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0631\u0650\u0632\u0652\u0642\u064f\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u064e\u0627\u062f\u064d",55,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u063a\u0650\u064a\u0646\u064e \u0644\u064e\u0634\u064e\u0631\u0651\u064e \u0645\u064e\u0622\u0628\u064d",56,"\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u0650\u0647\u064e\u0627\u062f\u064f",57,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0647\u064f \u062d\u064e\u0645\u0650\u064a\u0645\u064c \u0648\u064e\u063a\u064e\u0633\u0651\u064e\u0627\u0642\u064c",58,"\u0648\u064e\u0622\u062e\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u0643\u0652\u0644\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064c",59,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0648\u0652\u062c\u064c \u0645\u064f\u0642\u0652\u062a\u064e\u062d\u0650\u0645\u064c \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u0645\u064e\u0631\u0652\u062d\u064e\u0628\u064b\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u064f\u0648 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",60,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u0645\u064e\u0631\u0652\u062d\u064e\u0628\u064b\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u062f\u0651\u064e\u0645\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0644\u064e\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u064e\u0627\u0631\u064f",61,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0646\u0652 \u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0632\u0650\u062f\u0652\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0636\u0650\u0639\u0652\u0641\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",62,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0631\u064e\u0627\u0631\u0650",63,"\u0623\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u062e\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u0623\u064e\u0645\u0652 \u0632\u064e\u0627\u063a\u064e\u062a\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f",64,"\u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u062d\u064e\u0642\u0651\u064c \u062a\u064e\u062e\u064e\u0627\u0635\u064f\u0645\u064f \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",65,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064c \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",66,"\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u064f",67,"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0646\u064e\u0628\u064e\u0623\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",68,"\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",69,"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",70,"\u0625\u0650\u0646\u0652 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",71,"\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0627\u0644\u0650\u0642\u064c \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",72,u.ci,73,u.bu,74,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",75,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064f \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0633\u0652\u062c\u064f\u062f\u064e \u0644\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f \u0628\u0650\u064a\u064e\u062f\u064e\u064a\u0651\u064e \u06d6 \u0623\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064e \u0623\u064e\u0645\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u0650\u064a\u0646\u064e",76,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f \u06d6 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",77,u.av,78,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0644\u064e\u0639\u0652\u0646\u064e\u062a\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",79,u.O,80,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0638\u064e\u0631\u0650\u064a\u0646\u064e",81,"\u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0648\u064e\u0642\u0652\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u0650",82,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0628\u0650\u0639\u0650\u0632\u0651\u064e\u062a\u0650\u0643\u064e \u0644\u064e\u0623\u064f\u063a\u0652\u0648\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",83,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0644\u064e\u0635\u0650\u064a\u0646\u064e",84,"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0623\u064e\u0642\u064f\u0648\u0644\u064f",85,"\u0644\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u0652\u0643\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",86,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0644\u0651\u0650\u0641\u0650\u064a\u0646\u064e",87,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",88,"\u0648\u064e\u0644\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0646\u0651\u064e \u0646\u064e\u0628\u064e\u0623\u064e\u0647\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u062d\u0650\u064a\u0646\u064d"],t.v)
B.asd=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",2,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u064b\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e",3,"\u0623\u064e\u0644\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0635\u064f \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0648\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0632\u064f\u0644\u0652\u0641\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0643\u064e\u0627\u0630\u0650\u0628\u064c \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064c",4,"\u0644\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0648\u064e\u0644\u064e\u062f\u064b\u0627 \u0644\u064e\u0627\u0635\u0652\u0637\u064e\u0641\u064e\u0649\u0670 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u06d6 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u064f \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",5,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u064a\u064f\u0643\u064e\u0648\u0651\u0650\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0643\u064e\u0648\u0651\u0650\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u06d6 \u0643\u064f\u0644\u0651\u064c \u064a\u064e\u062c\u0652\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u064f",6,"\u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0632\u064e\u0648\u0652\u062c\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064d \u06da \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u062e\u064e\u0644\u0652\u0642\u064d \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064d \u062b\u064e\u0644\u064e\u0627\u062b\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0635\u0652\u0631\u064e\u0641\u064f\u0648\u0646\u064e",7,"\u0625\u0650\u0646\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u064c \u0648\u0650\u0632\u0652\u0631\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u06d7 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",8,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0636\u064f\u0631\u0651\u064c \u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0645\u064f\u0646\u0650\u064a\u0628\u064b\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u064e\u0647\u064f \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0633\u0650\u064a\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u0652 \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0643\u064e \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",9,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0646\u0650\u062a\u064c \u0622\u0646\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0633\u064e\u0627\u062c\u0650\u062f\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u064a\u064e\u062d\u0652\u0630\u064e\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",10,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u06da \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u06d7 \u0648\u064e\u0623\u064e\u0631\u0652\u0636\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0633\u0650\u0639\u064e\u0629\u064c \u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u064e\u0641\u0651\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",11,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u064b\u0627 \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e",12,"\u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0644\u0650\u0623\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",13,u.aG,14,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u064b\u0627 \u0644\u064e\u0647\u064f \u062f\u0650\u064a\u0646\u0650\u064a",15,"\u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0645\u064e\u0627 \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062e\u064f\u0633\u0652\u0631\u064e\u0627\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",16,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0645\u0652 \u0638\u064f\u0644\u064e\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u0650\u0645\u0652 \u0638\u064f\u0644\u064e\u0644\u064c \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f \u06da \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",17,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062c\u0652\u062a\u064e\u0646\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u06da \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650",18,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0641\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e\u0647\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",19,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064f\u0646\u0652\u0642\u0650\u0630\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",20,"\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u063a\u064f\u0631\u064e\u0641\u064c \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u064e\u0627 \u063a\u064f\u0631\u064e\u0641\u064c \u0645\u064e\u0628\u0652\u0646\u0650\u064a\u0651\u064e\u0629\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",21,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u0633\u064e\u0644\u064e\u0643\u064e\u0647\u064f \u064a\u064e\u0646\u064e\u0627\u0628\u0650\u064a\u0639\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f \u0628\u0650\u0647\u0650 \u0632\u064e\u0631\u0652\u0639\u064b\u0627 \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u0646\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0647\u0650\u064a\u062c\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0645\u064f\u0635\u0652\u0641\u064e\u0631\u0651\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0647\u064f \u062d\u064f\u0637\u064e\u0627\u0645\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",22,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0631\u064e\u062d\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0635\u064e\u062f\u0652\u0631\u064e\u0647\u064f \u0644\u0650\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06da \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",23,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0628\u0650\u0647\u064b\u0627 \u0645\u064e\u062b\u064e\u0627\u0646\u0650\u064a\u064e \u062a\u064e\u0642\u0652\u0634\u064e\u0639\u0650\u0631\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u062c\u064f\u0644\u064f\u0648\u062f\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0644\u0650\u064a\u0646\u064f \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u062f\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0647\u064e\u0627\u062f\u064d",24,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u0650\u064a \u0628\u0650\u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u0633\u064f\u0648\u0621\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",25,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",26,"\u0641\u064e\u0623\u064e\u0630\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u0650\u0632\u0652\u064a\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0631\u064e\u0628\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u064d \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",28,"\u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0630\u0650\u064a \u0639\u0650\u0648\u064e\u062c\u064d \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",29,"\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0641\u0650\u064a\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u0645\u064f\u062a\u064e\u0634\u064e\u0627\u0643\u0650\u0633\u064f\u0648\u0646\u064e \u0648\u064e\u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0633\u064e\u0644\u064e\u0645\u064b\u0627 \u0644\u0650\u0631\u064e\u062c\u064f\u0644\u064d \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a\u064e\u0627\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u06da \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",30,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u064e\u064a\u0651\u0650\u062a\u064c \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e",31,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",32,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0643\u064e\u0630\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0627\u0644\u0635\u0651\u0650\u062f\u0652\u0642\u0650 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u06da \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u0652\u0648\u064b\u0649 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",33,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0635\u0651\u0650\u062f\u0652\u0642\u0650 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0647\u0650 \u06d9 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",34,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",35,"\u0644\u0650\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0633\u0652\u0648\u064e\u0623\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",36,"\u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064e\u0627\u0641\u064d \u0639\u064e\u0628\u0652\u062f\u064e\u0647\u064f \u06d6 \u0648\u064e\u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0647\u064e\u0627\u062f\u064d",37,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0645\u064f\u0636\u0650\u0644\u0651\u064d \u06d7 \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u064d \u0630\u0650\u064a \u0627\u0646\u0652\u062a\u0650\u0642\u064e\u0627\u0645\u064d",38,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u064d \u0647\u064e\u0644\u0652 \u0647\u064f\u0646\u0651\u064e \u0643\u064e\u0627\u0634\u0650\u0641\u064e\u0627\u062a\u064f \u0636\u064f\u0631\u0651\u0650\u0647\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0646\u0650\u064a \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0647\u064e\u0644\u0652 \u0647\u064f\u0646\u0651\u064e \u0645\u064f\u0645\u0652\u0633\u0650\u0643\u064e\u0627\u062a\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u062d\u064e\u0633\u0652\u0628\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",39,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0627\u0645\u0650\u0644\u064c \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",40,"\u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u064a\u064f\u062e\u0652\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0642\u0650\u064a\u0645\u064c",41,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",42,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e \u062d\u0650\u064a\u0646\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0644\u064e\u0645\u0652 \u062a\u064e\u0645\u064f\u062a\u0652 \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0645\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0648\u064e\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",43,"\u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0621\u064e \u06da \u0642\u064f\u0644\u0652 \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",44,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0627\u0634\u0652\u0645\u064e\u0623\u064e\u0632\u0651\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0646\u064e",46,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0639\u064e\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0647\u064f \u0644\u064e\u0627\u0641\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u064a\u064e\u062d\u0652\u062a\u064e\u0633\u0650\u0628\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",49,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0636\u064f\u0631\u0651\u064c \u062f\u064e\u0639\u064e\u0627\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u06da \u0628\u064e\u0644\u0652 \u0647\u0650\u064a\u064e \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",50,"\u0642\u064e\u062f\u0652 \u0642\u064e\u0627\u0644\u064e\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",51,"\u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e",52,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",53,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u0652\u0631\u064e\u0641\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0646\u064e\u0637\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",54,"\u0648\u064e\u0623\u064e\u0646\u0650\u064a\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",55,"\u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",56,"\u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0646\u064e\u0641\u0652\u0633\u064c \u064a\u064e\u0627 \u062d\u064e\u0633\u0652\u0631\u064e\u062a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u0652\u062a\u064f \u0641\u0650\u064a \u062c\u064e\u0646\u0652\u0628\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062e\u0650\u0631\u0650\u064a\u0646\u064e",57,"\u0623\u064e\u0648\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064e\u062f\u064e\u0627\u0646\u0650\u064a \u0644\u064e\u0643\u064f\u0646\u0652\u062a\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",58,"\u0623\u064e\u0648\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u064a \u0643\u064e\u0631\u0651\u064e\u0629\u064b \u0641\u064e\u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",59,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u0652\u062a\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064e \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",60,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u0648\u064e\u062f\u0651\u064e\u0629\u064c \u06da \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u0652\u0648\u064b\u0649 \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",61,"\u0648\u064e\u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0628\u0650\u0645\u064e\u0641\u064e\u0627\u0632\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064f\u0648\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",62,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0643\u0650\u064a\u0644\u064c",63,"\u0644\u064e\u0647\u064f \u0645\u064e\u0642\u064e\u0627\u0644\u0650\u064a\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",64,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u063a\u064e\u064a\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u064f\u0648\u0646\u064e",65,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u0652\u062a\u064e \u0644\u064e\u064a\u064e\u062d\u0652\u0628\u064e\u0637\u064e\u0646\u0651\u064e \u0639\u064e\u0645\u064e\u0644\u064f\u0643\u064e \u0648\u064e\u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",66,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u0652 \u0648\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e",67,"\u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0642\u064e\u0628\u0652\u0636\u064e\u062a\u064f\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u0645\u064e\u0637\u0652\u0648\u0650\u064a\u0651\u064e\u0627\u062a\u064c \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650 \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0647\u064f \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",68,"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0635\u064e\u0639\u0650\u0642\u064e \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a\u0647\u0650 \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0642\u0650\u064a\u064e\u0627\u0645\u064c \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",69,"\u0648\u064e\u0623\u064e\u0634\u0652\u0631\u064e\u0642\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0628\u0650\u0646\u064f\u0648\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0648\u064f\u0636\u0650\u0639\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0648\u064e\u062c\u0650\u064a\u0621\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u0650 \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",70,"\u0648\u064e\u0648\u064f\u0641\u0651\u0650\u064a\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",71,"\u0648\u064e\u0633\u0650\u064a\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0632\u064f\u0645\u064e\u0631\u064b\u0627 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0647\u064e\u0627 \u0641\u064f\u062a\u0650\u062d\u064e\u062a\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064c \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u0650\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062d\u064e\u0642\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",72,"\u0642\u0650\u064a\u0644\u064e \u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u062b\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",73,"\u0648\u064e\u0633\u0650\u064a\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0632\u064f\u0645\u064e\u0631\u064b\u0627 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0641\u064f\u062a\u0650\u062d\u064e\u062a\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0637\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e",74,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0635\u064e\u062f\u064e\u0642\u064e\u0646\u064e\u0627 \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u064e\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0646\u064e\u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062d\u064e\u064a\u0652\u062b\u064f \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0623\u064e\u062c\u0652\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u0650\u064a\u0646\u064e",75,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u062d\u064e\u0627\u0641\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e"],t.v)
B.ask=new A.U([1,u.B,2,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u0650",3,"\u063a\u064e\u0627\u0641\u0650\u0631\u0650 \u0627\u0644\u0630\u0651\u064e\u0646\u0652\u0628\u0650 \u0648\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0628\u0650 \u0634\u064e\u062f\u0650\u064a\u062f\u0650 \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0630\u0650\u064a \u0627\u0644\u0637\u0651\u064e\u0648\u0652\u0644\u0650 \u06d6 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",4,"\u0645\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0631\u064f\u0631\u0652\u0643\u064e \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u0650\u0644\u064e\u0627\u062f\u0650",5,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064e\u0645\u0651\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u06d6 \u0648\u064e\u062c\u064e\u0627\u062f\u064e\u0644\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u0650 \u0644\u0650\u064a\u064f\u062f\u0652\u062d\u0650\u0636\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",6,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",7,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0633\u0650\u0639\u0652\u062a\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0643\u064e \u0648\u064e\u0642\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",8,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0639\u064e\u062f\u0652\u0646\u064d \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u0635\u064e\u0644\u064e\u062d\u064e \u0645\u0650\u0646\u0652 \u0622\u0628\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",9,"\u0648\u064e\u0642\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0642\u0650 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0641\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u062d\u0650\u0645\u0652\u062a\u064e\u0647\u064f \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",10,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0646\u064e \u0644\u064e\u0645\u064e\u0642\u0652\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0645\u064e\u0642\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0641\u064e\u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",11,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0645\u064e\u062a\u0651\u064e\u0646\u064e\u0627 \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627 \u0627\u062b\u0652\u0646\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0627\u0639\u0652\u062a\u064e\u0631\u064e\u0641\u0652\u0646\u064e\u0627 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064e\u0644\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062e\u064f\u0631\u064f\u0648\u062c\u064d \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",12,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u064e\u0643\u0652 \u0628\u0650\u0647\u0650 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u06da \u0641\u064e\u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u0650 \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u0650",13,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u064a\u064f\u0646\u0650\u064a\u0628\u064f",14,"\u0641\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",15,"\u0631\u064e\u0641\u0650\u064a\u0639\u064f \u0627\u0644\u062f\u0651\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u0650 \u0630\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u064a\u064f\u0644\u0652\u0642\u0650\u064a \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062a\u0651\u064e\u0644\u064e\u0627\u0642\u0650",16,"\u064a\u064e\u0648\u0652\u0645\u064e \u0647\u064f\u0645\u0652 \u0628\u064e\u0627\u0631\u0650\u0632\u064f\u0648\u0646\u064e \u06d6 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0621\u064c \u06da \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06d6 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u062d\u0650\u062f\u0650 \u0627\u0644\u0652\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u0650",17,"\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u062c\u0652\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u06da \u0644\u064e\u0627 \u0638\u064f\u0644\u0652\u0645\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",18,"\u0648\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0622\u0632\u0650\u0641\u064e\u0629\u0650 \u0625\u0650\u0630\u0650 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0644\u064e\u062f\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0646\u064e\u0627\u062c\u0650\u0631\u0650 \u0643\u064e\u0627\u0638\u0650\u0645\u0650\u064a\u0646\u064e \u06da \u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u0650\u064a\u0645\u064d \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u064d \u064a\u064f\u0637\u064e\u0627\u0639\u064f",19,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u062e\u064e\u0627\u0626\u0650\u0646\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062e\u0652\u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u064f",20,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u0652\u0636\u0650\u064a \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u0636\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",21,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0622\u062b\u064e\u0627\u0631\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0627\u0642\u064d",22,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",23,u.bN,24,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c",25,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0627 \u0646\u0650\u0633\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u064a\u0652\u062f\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d",26,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0630\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0642\u0652\u062a\u064f\u0644\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0644\u0652\u064a\u064e\u062f\u0652\u0639\u064f \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0638\u0652\u0647\u0650\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064e",27,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u0652\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u064d \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u0650",28,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0645\u0650\u0646\u0652 \u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0643\u0652\u062a\u064f\u0645\u064f \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e\u0647\u064f \u0623\u064e\u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f \u0643\u064e\u0627\u0630\u0650\u0628\u064b\u0627 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064f\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064f \u0635\u064e\u0627\u062f\u0650\u0642\u064b\u0627 \u064a\u064f\u0635\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u0652\u0631\u0650\u0641\u064c \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c",29,"\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0638\u064e\u0627\u0647\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0623\u0652\u0633\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u0634\u064e\u0627\u062f\u0650",30,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u0645\u064e\u0646\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064e \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u0650",31,"\u0645\u0650\u062b\u0652\u0644\u064e \u062f\u064e\u0623\u0652\u0628\u0650 \u0642\u064e\u0648\u0652\u0645\u0650 \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0638\u064f\u0644\u0652\u0645\u064b\u0627 \u0644\u0650\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",32,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062a\u0651\u064e\u0646\u064e\u0627\u062f\u0650",33,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u064e\u0627\u0635\u0650\u0645\u064d \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0647\u064e\u0627\u062f\u064d",34,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0632\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0647\u064e\u0644\u064e\u0643\u064e \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u0652\u0631\u0650\u0641\u064c \u0645\u064f\u0631\u0652\u062a\u064e\u0627\u0628\u064c",35,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u06d6 \u0643\u064e\u0628\u064f\u0631\u064e \u0645\u064e\u0642\u0652\u062a\u064b\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u0652\u0628\u064e\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0644\u0652\u0628\u0650 \u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u064d \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d",36,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u064a\u064e\u0627 \u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064f \u0627\u0628\u0652\u0646\u0650 \u0644\u0650\u064a \u0635\u064e\u0631\u0652\u062d\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0628\u0652\u0644\u064f\u063a\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0628\u064e",37,"\u0623\u064e\u0633\u0652\u0628\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0641\u064e\u0623\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0647\u064f \u0643\u064e\u0627\u0630\u0650\u0628\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0633\u064f\u0648\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650 \u0648\u064e\u0635\u064f\u062f\u0651\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u064a\u0652\u062f\u064f \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u062a\u064e\u0628\u064e\u0627\u0628\u064d",38,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0622\u0645\u064e\u0646\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650 \u0623\u064e\u0647\u0652\u062f\u0650\u0643\u064f\u0645\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0627\u0644\u0631\u0651\u064e\u0634\u064e\u0627\u062f\u0650",39,"\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064c \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0647\u0650\u064a\u064e \u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0642\u064e\u0631\u064e\u0627\u0631\u0650",40,"\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064b \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u0652\u0632\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0645\u0650\u0646\u0652 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u064a\u064f\u0631\u0652\u0632\u064e\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",41,"\u0648\u064e\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u064e\u0627 \u0644\u0650\u064a \u0623\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u062c\u064e\u0627\u0629\u0650 \u0648\u064e\u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",42,"\u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0644\u0650\u0623\u064e\u0643\u0652\u0641\u064f\u0631\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u0650",43,"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0631\u064e\u062f\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",44,"\u0641\u064e\u0633\u064e\u062a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0623\u064f\u0641\u064e\u0648\u0651\u0650\u0636\u064f \u0623\u064e\u0645\u0652\u0631\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",45,"\u0641\u064e\u0648\u064e\u0642\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0622\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0633\u064f\u0648\u0621\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650",46,"\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u063a\u064f\u062f\u064f\u0648\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u064b\u0627 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u062f\u0652\u062e\u0650\u0644\u064f\u0648\u0627 \u0622\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650",47,"\u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u062a\u064e\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0627\u0621\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0628\u064e\u0639\u064b\u0627 \u0641\u064e\u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u063a\u0652\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",48,"\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064c \u0641\u0650\u064a\u0647\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u0652 \u062d\u064e\u0643\u064e\u0645\u064e \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650",49,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u0650\u062e\u064e\u0632\u064e\u0646\u064e\u0629\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u064a\u064f\u062e\u064e\u0641\u0651\u0650\u0641\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650",50,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0641\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d",51,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0646\u0652\u0635\u064f\u0631\u064f \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0647\u064e\u0627\u062f\u064f",52,"\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u0652\u0630\u0650\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0639\u0652\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0648\u0621\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650",53,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e",54,"\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650",55,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0643\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0628\u0652\u0643\u064e\u0627\u0631\u0650",56,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u06d9 \u0625\u0650\u0646\u0652 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u0650\u0628\u0652\u0631\u064c \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0627\u0644\u0650\u063a\u0650\u064a\u0647\u0650 \u06da \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0630\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",57,"\u0644\u064e\u062e\u064e\u0644\u0652\u0642\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0650\u064a\u0621\u064f \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",59,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0622\u062a\u0650\u064a\u064e\u0629\u064c \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u062f\u0652\u0639\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u0628\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u064a \u0633\u064e\u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062f\u064e\u0627\u062e\u0650\u0631\u0650\u064a\u0646\u064e",61,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0644\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",62,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",63,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",64,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0642\u064e\u0631\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0621\u064b \u0648\u064e\u0635\u064e\u0648\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0635\u064f\u0648\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",65,"\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0641\u064e\u0627\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u06d7 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",66,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064f\u0647\u0650\u064a\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064f\u0633\u0652\u0644\u0650\u0645\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",67,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062a\u064f\u0631\u064e\u0627\u0628\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064d \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u0652 \u0637\u0650\u0641\u0652\u0644\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0634\u064f\u064a\u064f\u0648\u062e\u064b\u0627 \u06da \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0623\u064e\u062c\u064e\u0644\u064b\u0627 \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",68,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f \u0643\u064f\u0646\u0652 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",69,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0635\u0652\u0631\u064e\u0641\u064f\u0648\u0646\u064e",70,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",71,"\u0625\u0650\u0630\u0650 \u0627\u0644\u0652\u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064f \u0641\u0650\u064a \u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0633\u0650\u0644\u064f \u064a\u064f\u0633\u0652\u062d\u064e\u0628\u064f\u0648\u0646\u064e",72,"\u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u0650 \u062b\u064f\u0645\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064f\u0633\u0652\u062c\u064e\u0631\u064f\u0648\u0646\u064e",73,"\u062b\u064f\u0645\u0651\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",74,"\u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0651\u064e\u0627 \u0628\u064e\u0644\u0652 \u0644\u064e\u0645\u0652 \u0646\u064e\u0643\u064f\u0646\u0652 \u0646\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",75,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0645\u0652\u0631\u064e\u062d\u064f\u0648\u0646\u064e",76,"\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u062b\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",77,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u06da \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",78,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0642\u064e\u0635\u064e\u0635\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u0646\u064e\u0642\u0652\u0635\u064f\u0635\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064f\u0636\u0650\u064a\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u062e\u064e\u0633\u0650\u0631\u064e \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0646\u064e",79,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064e \u0644\u0650\u062a\u064e\u0631\u0652\u0643\u064e\u0628\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",80,"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062d\u064e\u0627\u062c\u064e\u0629\u064b \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u062a\u064f\u062d\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",81,"\u0648\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0641\u064e\u0623\u064e\u064a\u0651\u064e \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0646\u0652\u0643\u0650\u0631\u064f\u0648\u0646\u064e",82,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0622\u062b\u064e\u0627\u0631\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",83,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",84,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0628\u064e\u0623\u0652\u0633\u064e\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",85,"\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0628\u064e\u0623\u0652\u0633\u064e\u0646\u064e\u0627 \u06d6 \u0633\u064f\u0646\u0651\u064e\u062a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u06d6 \u0648\u064e\u062e\u064e\u0633\u0650\u0631\u064e \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e"],t.v)
B.aso=new A.U([1,u.B,2,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",3,"\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0647\u064f \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",4,"\u0628\u064e\u0634\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627 \u0641\u064e\u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",5,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u0652\u0631\u064c \u0648\u064e\u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u0650\u0643\u064e \u062d\u0650\u062c\u064e\u0627\u0628\u064c \u0641\u064e\u0627\u0639\u0652\u0645\u064e\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u0627\u0645\u0650\u0644\u064f\u0648\u0646\u064e",6,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0643\u064f\u0645\u0652 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0647\u064f \u06d7 \u0648\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",7,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",8,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0645\u0652\u0646\u064f\u0648\u0646\u064d",9,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0646\u0652\u062f\u064e\u0627\u062f\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",10,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0642\u0652\u0648\u064e\u0627\u062a\u064e\u0647\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u0644\u0650\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u0650\u064a\u0646\u064e",11,"\u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u0650\u064a\u064e \u062f\u064f\u062e\u064e\u0627\u0646\u064c \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u0650\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0626\u0652\u062a\u0650\u064a\u064e\u0627 \u0637\u064e\u0648\u0652\u0639\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0631\u0652\u0647\u064b\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u064e\u0627 \u0623\u064e\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0637\u064e\u0627\u0626\u0650\u0639\u0650\u064a\u0646\u064e",12,"\u0641\u064e\u0642\u064e\u0636\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064d \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0645\u064e\u0627\u0621\u064d \u0623\u064e\u0645\u0652\u0631\u064e\u0647\u064e\u0627 \u06da \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0645\u064e\u0635\u064e\u0627\u0628\u0650\u064a\u062d\u064e \u0648\u064e\u062d\u0650\u0641\u0652\u0638\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u0650",13,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0641\u064e\u0642\u064f\u0644\u0652 \u0623\u064e\u0646\u0652\u0630\u064e\u0631\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064b \u0645\u0650\u062b\u0652\u0644\u064e \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u0650 \u0639\u064e\u0627\u062f\u064d \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e",14,"\u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",15,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0627\u062f\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u06d6 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",16,"\u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u0650\u064a\u062d\u064b\u0627 \u0635\u064e\u0631\u0652\u0635\u064e\u0631\u064b\u0627 \u0641\u0650\u064a \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0646\u064e\u062d\u0650\u0633\u064e\u0627\u062a\u064d \u0644\u0650\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062e\u0650\u0632\u0652\u064a\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u062e\u0652\u0632\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",17,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0641\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0645\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u062d\u0652\u0634\u064e\u0631\u064f \u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",20,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0647\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064e\u0645\u0652\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u062c\u064f\u0644\u064f\u0648\u062f\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u0645\u064e \u0634\u064e\u0647\u0650\u062f\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0637\u064e\u0642\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0637\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u062a\u0650\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u0645\u0652\u0639\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0638\u064e\u0646\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0631\u0652\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",24,"\u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0641\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u0652\u0648\u064b\u0649 \u0644\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062a\u0650\u0628\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u0628\u0650\u064a\u0646\u064e",25,"\u0648\u064e\u0642\u064e\u064a\u0651\u064e\u0636\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064f\u0631\u064e\u0646\u064e\u0627\u0621\u064e \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0641\u0650\u064a \u0623\u064f\u0645\u064e\u0645\u064d \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",26,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u0644\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0648\u0652\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u063a\u0652\u0644\u0650\u0628\u064f\u0648\u0646\u064e",27,"\u0641\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0633\u0652\u0648\u064e\u0623\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",28,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062f\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u062e\u064f\u0644\u0652\u062f\u0650 \u06d6 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e",29,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0630\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0627\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0647\u064f\u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u062a\u064e \u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u0650\u0646\u064e\u0627 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0641\u064e\u0644\u0650\u064a\u0646\u064e",30,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u062a\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0628\u0652\u0634\u0650\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",31,"\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0647\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",32,"\u0646\u064f\u0632\u064f\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u063a\u064e\u0641\u064f\u0648\u0631\u064d \u0631\u064e\u062d\u0650\u064a\u0645\u064d",33,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062f\u064e\u0639\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",34,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064f \u06da \u0627\u062f\u0652\u0641\u064e\u0639\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064c \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u0645\u064c",35,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u064f\u0648 \u062d\u064e\u0638\u0651\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",36,"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0646\u0652\u0632\u064e\u063a\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0646\u064e\u0632\u0652\u063a\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0630\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",37,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064f \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u0650 \u0648\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",38,"\u0641\u064e\u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0645\u064f\u0648\u0646\u064e \u06e9",39,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0629\u064b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0627\u0647\u0652\u062a\u064e\u0632\u0651\u064e\u062a\u0652 \u0648\u064e\u0631\u064e\u0628\u064e\u062a\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0645\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",40,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0644\u0652\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0641\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u06d7 \u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0644\u0652\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0622\u0645\u0650\u0646\u064b\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",41,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",42,"\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650 \u06d6 \u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u0652 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u062d\u064e\u0645\u0650\u064a\u062f\u064d",43,"\u0645\u064e\u0627 \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u0652 \u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0648\u064e\u0630\u064f\u0648 \u0639\u0650\u0642\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",44,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0623\u064e\u0639\u0652\u062c\u064e\u0645\u0650\u064a\u0651\u064b\u0627 \u0644\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0647\u064f \u06d6 \u0623\u064e\u0623\u064e\u0639\u0652\u062c\u064e\u0645\u0650\u064a\u0651\u064c \u0648\u064e\u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064c \u06d7 \u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0634\u0650\u0641\u064e\u0627\u0621\u064c \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0642\u0652\u0631\u064c \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0639\u064e\u0645\u064b\u0649 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",45,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0641\u064e\u0627\u062e\u0652\u062a\u064f\u0644\u0650\u0641\u064e \u0641\u0650\u064a\u0647\u0650 \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u064d",46,"\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0627\u0645\u064d \u0644\u0650\u0644\u0652\u0639\u064e\u0628\u0650\u064a\u062f\u0650",47,"\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0639\u0650\u0644\u0652\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u0652 \u0623\u064e\u0643\u0652\u0645\u064e\u0627\u0645\u0650\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0645\u0650\u0646\u0652 \u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u06da \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u064a \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0630\u064e\u0646\u0651\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064d",48,"\u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u062d\u0650\u064a\u0635\u064d",49,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0645\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0639\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0641\u064e\u064a\u064e\u0626\u064f\u0648\u0633\u064c \u0642\u064e\u0646\u064f\u0648\u0637\u064c",50,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0636\u064e\u0631\u0651\u064e\u0627\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u0652\u0647\u064f \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0631\u064f\u062c\u0650\u0639\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u064a \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0644\u064e\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u0641\u064e\u0644\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u064d",51,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0648\u064e\u0646\u064e\u0623\u064e\u0649\u0670 \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650\u0647\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0641\u064e\u0630\u064f\u0648 \u062f\u064f\u0639\u064e\u0627\u0621\u064d \u0639\u064e\u0631\u0650\u064a\u0636\u064d",52,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",53,"\u0633\u064e\u0646\u064f\u0631\u0650\u064a\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u0641\u064e\u0627\u0642\u0650 \u0648\u064e\u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d7 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u0650 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",54,"\u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0644\u0650\u0642\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u064f\u062d\u0650\u064a\u0637\u064c"],t.v)
B.aow=new A.U([1,u.B,2,"\u0639\u0633\u0642",3,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0648\u062d\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",4,"\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",5,"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064f \u064a\u064e\u062a\u064e\u0641\u064e\u0637\u0651\u064e\u0631\u0652\u0646\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",6,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0641\u0650\u064a\u0638\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",7,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u0650\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0623\u064f\u0645\u0651\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u06da \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",8,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",9,"\u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06d6 \u0641\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",10,"\u0648\u064e\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u062d\u064f\u0643\u0652\u0645\u064f\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064f\u0646\u0650\u064a\u0628\u064f",11,"\u0641\u064e\u0627\u0637\u0650\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u06d6 \u064a\u064e\u0630\u0652\u0631\u064e\u0624\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u06da \u0644\u064e\u064a\u0652\u0633\u064e \u0643\u064e\u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0621\u064c \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",12,"\u0644\u064e\u0647\u064f \u0645\u064e\u0642\u064e\u0627\u0644\u0650\u064a\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",13,"\u0634\u064e\u0631\u064e\u0639\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u064e\u0627 \u0648\u064e\u0635\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u0650 \u0646\u064f\u0648\u062d\u064b\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0635\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u06d6 \u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u06da \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062c\u0652\u062a\u064e\u0628\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064f\u0646\u0650\u064a\u0628\u064f",14,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0631\u0650\u062b\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u064d",15,"\u0641\u064e\u0644\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0627\u062f\u0652\u0639\u064f \u06d6 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0642\u0650\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0642\u064f\u0644\u0652 \u0622\u0645\u064e\u0646\u0652\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0644\u0650\u0623\u064e\u0639\u0652\u062f\u0650\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u064f \u06d6 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u062d\u064f\u062c\u0651\u064e\u0629\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u064f \u06d6 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",16,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064f\u062c\u0650\u064a\u0628\u064e \u0644\u064e\u0647\u064f \u062d\u064f\u062c\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u062f\u064e\u0627\u062d\u0650\u0636\u064e\u0629\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u063a\u064e\u0636\u064e\u0628\u064c \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c",17,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u0652\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0631\u0650\u064a\u0628\u064c",18,"\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0645\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",19,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f",20,"\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062d\u064e\u0631\u0652\u062b\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0646\u064e\u0632\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u062d\u064e\u0631\u0652\u062b\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062d\u064e\u0631\u0652\u062b\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0646\u064f\u0624\u0652\u062a\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064d",21,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u0634\u064e\u0631\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u0630\u064e\u0646\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",22,"\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0627\u0642\u0650\u0639\u064c \u0628\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u0650\u064a \u0631\u064e\u0648\u0652\u0636\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u06d6 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",23,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u06d7 \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u0652 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0646\u064e\u0632\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0634\u064e\u0643\u064f\u0648\u0631\u064c",24,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0625\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u0652\u062a\u0650\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0643\u064e \u06d7 \u0648\u064e\u064a\u064e\u0645\u0652\u062d\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u0648\u064e\u064a\u064f\u062d\u0650\u0642\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",25,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0642\u0652\u0628\u064e\u0644\u064f \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0628\u064e\u0629\u064e \u0639\u064e\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0641\u064f\u0648 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",26,"\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c",27,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0628\u064e\u0633\u064e\u0637\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0644\u064e\u0628\u064e\u063a\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",28,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u062b\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0642\u064e\u0646\u064e\u0637\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0646\u0652\u0634\u064f\u0631\u064f \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",29,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u062e\u064e\u0644\u0652\u0642\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064e\u0645\u0652\u0639\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0642\u064e\u062f\u0650\u064a\u0631\u064c",30,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064d \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0639\u0652\u0641\u064f\u0648 \u0639\u064e\u0646\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u064d",31,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",32,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0627\u0644\u0652\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0643\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0627\u0645\u0650",33,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0634\u064e\u0623\u0652 \u064a\u064f\u0633\u0652\u0643\u0650\u0646\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0641\u064e\u064a\u064e\u0638\u0652\u0644\u064e\u0644\u0652\u0646\u064e \u0631\u064e\u0648\u064e\u0627\u0643\u0650\u062f\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064e\u0647\u0652\u0631\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0634\u064e\u0643\u064f\u0648\u0631\u064d",34,"\u0623\u064e\u0648\u0652 \u064a\u064f\u0648\u0628\u0650\u0642\u0652\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u064d",35,"\u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u062d\u0650\u064a\u0635\u064d",36,"\u0641\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0646\u064e \u0643\u064e\u0628\u064e\u0627\u0626\u0650\u0631\u064e \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0648\u064e\u0627\u062d\u0650\u0634\u064e \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u063a\u064e\u0636\u0650\u0628\u064f\u0648\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e",38,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0645\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0634\u064f\u0648\u0631\u064e\u0649\u0670 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u063a\u0652\u064a\u064f \u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064f\u0648\u0646\u064e",40,"\u0648\u064e\u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064d \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0641\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0641\u064e\u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",41,"\u0648\u064e\u0644\u064e\u0645\u064e\u0646\u0650 \u0627\u0646\u0652\u062a\u064e\u0635\u064e\u0631\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0638\u064f\u0644\u0652\u0645\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",42,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u064a\u064e\u0628\u0652\u063a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",43,"\u0648\u064e\u0644\u064e\u0645\u064e\u0646\u0652 \u0635\u064e\u0628\u064e\u0631\u064e \u0648\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u0652 \u0639\u064e\u0632\u0652\u0645\u0650 \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",44,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0648\u064e\u0644\u0650\u064a\u0651\u064d \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650 \u06d7 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0644\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u064e\u062f\u0651\u064d \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",45,"\u0648\u064e\u062a\u064e\u0631\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062e\u064e\u0627\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0630\u0651\u064f\u0644\u0651\u0650 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0637\u064e\u0631\u0652\u0641\u064d \u062e\u064e\u0641\u0650\u064a\u0651\u064d \u06d7 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0645\u064f\u0642\u0650\u064a\u0645\u064d",46,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0636\u0652\u0644\u0650\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",47,"\u0627\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0644\u0652\u062c\u064e\u0625\u064d \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0643\u0650\u064a\u0631\u064d",48,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0641\u0650\u064a\u0638\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0630\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0641\u064e\u0631\u0650\u062d\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0635\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064c \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0643\u064e\u0641\u064f\u0648\u0631\u064c",49,"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u064a\u064e\u0647\u064e\u0628\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u0648\u064e\u064a\u064e\u0647\u064e\u0628\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0627\u0644\u0630\u0651\u064f\u0643\u064f\u0648\u0631\u064e",50,"\u0623\u064e\u0648\u0652 \u064a\u064f\u0632\u064e\u0648\u0651\u0650\u062c\u064f\u0647\u064f\u0645\u0652 \u0630\u064f\u0643\u0652\u0631\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u06d6 \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0639\u064e\u0642\u0650\u064a\u0645\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0642\u064e\u062f\u0650\u064a\u0631\u064c",51,"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u0623\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062d\u0652\u064a\u064b\u0627 \u0623\u064e\u0648\u0652 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u064d \u0623\u064e\u0648\u0652 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u064a\u064f\u0648\u062d\u0650\u064a\u064e \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",52,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0631\u064f\u0648\u062d\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u06da \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064e\u062f\u0652\u0631\u0650\u064a \u0645\u064e\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0646\u064f\u0648\u0631\u064b\u0627 \u0646\u064e\u0647\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",53,"\u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0635\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f"],t.v)
B.asJ=new A.U([1,u.B,2,"\u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",3,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0623\u064f\u0645\u0651\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0639\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",5,"\u0623\u064e\u0641\u064e\u0646\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0635\u064e\u0641\u0652\u062d\u064b\u0627 \u0623\u064e\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",6,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",8,"\u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u064e\u0637\u0652\u0634\u064b\u0627 \u0648\u064e\u0645\u064e\u0636\u064e\u0649\u0670 \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",9,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",10,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u064e\u0647\u0652\u062f\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",11,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d \u0641\u064e\u0623\u064e\u0646\u0652\u0634\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0628\u064e\u0644\u0652\u062f\u064e\u0629\u064b \u0645\u064e\u064a\u0652\u062a\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e",12,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u0645\u064e\u0627 \u062a\u064e\u0631\u0652\u0643\u064e\u0628\u064f\u0648\u0646\u064e",13,"\u0644\u0650\u062a\u064e\u0633\u0652\u062a\u064e\u0648\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u064f\u0642\u0652\u0631\u0650\u0646\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",15,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u062c\u064f\u0632\u0652\u0621\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064e\u0641\u064f\u0648\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",16,"\u0623\u064e\u0645\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0628\u064e\u0646\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0635\u0652\u0641\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0646\u0650\u064a\u0646\u064e",17,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0638\u064e\u0644\u0651\u064e \u0648\u064e\u062c\u0652\u0647\u064f\u0647\u064f \u0645\u064f\u0633\u0652\u0648\u064e\u062f\u0651\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u064c",18,"\u0623\u064e\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0646\u064e\u0634\u0651\u064e\u0623\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u0650\u0644\u0652\u064a\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u0650\u0635\u064e\u0627\u0645\u0650 \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064f\u0628\u0650\u064a\u0646\u064d",19,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0625\u0650\u0646\u064e\u0627\u062b\u064b\u0627 \u06da \u0623\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627 \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u06da \u0633\u064e\u062a\u064f\u0643\u0652\u062a\u064e\u0628\u064f \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0645\u064e\u0627 \u0639\u064e\u0628\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06d7 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u0635\u064f\u0648\u0646\u064e",21,"\u0623\u064e\u0645\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0641\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0646\u064e",22,"\u0628\u064e\u0644\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u064f\u0648\u0647\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0642\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",24,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0645\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0622\u0628\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",25,"\u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0642\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",26,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u064e\u0631\u064e\u0627\u0621\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",27,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",28,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064b \u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0629\u064b \u0641\u0650\u064a \u0639\u064e\u0642\u0650\u0628\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",29,"\u0628\u064e\u0644\u0652 \u0645\u064e\u062a\u0651\u064e\u0639\u0652\u062a\u064f \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0648\u064e\u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",30,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u064d",32,"\u0623\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0642\u0652\u0633\u0650\u0645\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0646\u064e\u062d\u0652\u0646\u064f \u0642\u064e\u0633\u064e\u0645\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0648\u0652\u0642\u064e \u0628\u064e\u0639\u0652\u0636\u064d \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0644\u0650\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u0633\u064f\u062e\u0652\u0631\u0650\u064a\u0651\u064b\u0627 \u06d7 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f \u0628\u0650\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0644\u0650\u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0645\u0652 \u0633\u064f\u0642\u064f\u0641\u064b\u0627 \u0645\u0650\u0646\u0652 \u0641\u0650\u0636\u0651\u064e\u0629\u064d \u0648\u064e\u0645\u064e\u0639\u064e\u0627\u0631\u0650\u062c\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u064a\u064e\u0638\u0652\u0647\u064e\u0631\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0644\u0650\u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0633\u064f\u0631\u064f\u0631\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0643\u0650\u0626\u064f\u0648\u0646\u064e",35,"\u0648\u064e\u0632\u064f\u062e\u0652\u0631\u064f\u0641\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",36,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0634\u064f \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0646\u064f\u0642\u064e\u064a\u0651\u0650\u0636\u0652 \u0644\u064e\u0647\u064f \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0631\u0650\u064a\u0646\u064c",37,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",38,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u0628\u064f\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0642\u064e\u0631\u0650\u064a\u0646\u064f",39,"\u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0625\u0650\u0630\u0652 \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u0634\u0652\u062a\u064e\u0631\u0650\u0643\u064f\u0648\u0646\u064e",40,"\u0623\u064e\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064f\u0633\u0652\u0645\u0650\u0639\u064f \u0627\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u0652 \u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0639\u064f\u0645\u0652\u064a\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",41,"\u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0630\u0652\u0647\u064e\u0628\u064e\u0646\u0651\u064e \u0628\u0650\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",42,"\u0623\u064e\u0648\u0652 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064f\u0642\u0652\u062a\u064e\u062f\u0650\u0631\u064f\u0648\u0646\u064e",43,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0652\u0633\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",44,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u0650\u0643\u0652\u0631\u064c \u0644\u064e\u0643\u064e \u0648\u064e\u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0643\u064e \u06d6 \u0648\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627 \u0623\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u064a\u064f\u0639\u0652\u0628\u064e\u062f\u064f\u0648\u0646\u064e",46,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",47,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u064a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u0650\u064a\u064e \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0623\u064f\u062e\u0652\u062a\u0650\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f \u0627\u062f\u0652\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0647\u0650\u062f\u064e \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",50,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0643\u064f\u062b\u064f\u0648\u0646\u064e",51,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0641\u0650\u064a \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u064a \u0645\u064f\u0644\u0652\u0643\u064f \u0645\u0650\u0635\u0652\u0631\u064e \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u064a \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",52,"\u0623\u064e\u0645\u0652 \u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0645\u064e\u0647\u0650\u064a\u0646\u064c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u064a\u064f\u0628\u0650\u064a\u0646\u064f",53,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0633\u0652\u0648\u0650\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0630\u064e\u0647\u064e\u0628\u064d \u0623\u064e\u0648\u0652 \u062c\u064e\u0627\u0621\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0645\u064f\u0642\u0652\u062a\u064e\u0631\u0650\u0646\u0650\u064a\u0646\u064e",54,"\u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062e\u064e\u0641\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",55,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0622\u0633\u064e\u0641\u064f\u0648\u0646\u064e\u0627 \u0627\u0646\u0652\u062a\u064e\u0642\u064e\u0645\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",56,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u064e\u0644\u064e\u0641\u064b\u0627 \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0644\u0650\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",57,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0636\u064f\u0631\u0650\u0628\u064e \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u064a\u064e\u0635\u0650\u062f\u0651\u064f\u0648\u0646\u064e",58,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0622\u0644\u0650\u0647\u064e\u062a\u064f\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0652 \u0647\u064f\u0648\u064e \u06da \u0645\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0647\u064f \u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064e\u062f\u064e\u0644\u064b\u0627 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u062e\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",59,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064c \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0644\u0650\u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",60,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064b \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u062e\u0652\u0644\u064f\u0641\u064f\u0648\u0646\u064e",61,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0639\u0650\u0644\u0652\u0645\u064c \u0644\u0650\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u062a\u064e\u0631\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650 \u06da \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",62,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",63,"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u0650\u0623\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",64,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u06da \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0627\u0637\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064c",65,"\u0641\u064e\u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064e \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",66,"\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",67,"\u0627\u0644\u0652\u0623\u064e\u062e\u0650\u0644\u0651\u064e\u0627\u0621\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",68,"\u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",69,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",70,"\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0643\u064f\u0645\u0652 \u062a\u064f\u062d\u0652\u0628\u064e\u0631\u064f\u0648\u0646\u064e",71,"\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0635\u0650\u062d\u064e\u0627\u0641\u064d \u0645\u0650\u0646\u0652 \u0630\u064e\u0647\u064e\u0628\u064d \u0648\u064e\u0623\u064e\u0643\u0652\u0648\u064e\u0627\u0628\u064d \u06d6 \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0647\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f \u0648\u064e\u062a\u064e\u0644\u064e\u0630\u0651\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064f \u06d6 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",72,"\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064f\u0648\u0631\u0650\u062b\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",73,"\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064c \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",74,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",75,"\u0644\u064e\u0627 \u064a\u064f\u0641\u064e\u062a\u0651\u064e\u0631\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0628\u0652\u0644\u0650\u0633\u064f\u0648\u0646\u064e",76,"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",77,"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0627 \u064a\u064e\u0627 \u0645\u064e\u0627\u0644\u0650\u0643\u064f \u0644\u0650\u064a\u064e\u0642\u0652\u0636\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627\u0643\u0650\u062b\u064f\u0648\u0646\u064e",78,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u0650\u0626\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e",79,"\u0623\u064e\u0645\u0652 \u0623\u064e\u0628\u0652\u0631\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0628\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",80,"\u0623\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0633\u0650\u0631\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064e\u062c\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0646\u064e",81,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u062f\u064c \u0641\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0628\u0650\u062f\u0650\u064a\u0646\u064e",82,"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",83,u.N,84,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",85,"\u0648\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u0650\u0644\u0652\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",86,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0634\u064e\u0647\u0650\u062f\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",87,"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",88,"\u0648\u064e\u0642\u0650\u064a\u0644\u0650\u0647\u0650 \u064a\u064e\u0627 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",89,"\u0641\u064e\u0627\u0635\u0652\u0641\u064e\u062d\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064f\u0644\u0652 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u06da \u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"],t.v)
B.aoZ=new A.U([1,u.B,2,"\u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",3,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064d \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064e\u0629\u064d \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e",4,"\u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064f\u0641\u0652\u0631\u064e\u0642\u064f \u0643\u064f\u0644\u0651\u064f \u0623\u064e\u0645\u0652\u0631\u064d \u062d\u064e\u0643\u0650\u064a\u0645\u064d",5,"\u0623\u064e\u0645\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u0650\u064a\u0646\u064e",6,"\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",7,"\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",8,"\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06d6 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",9,"\u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u064d \u064a\u064e\u0644\u0652\u0639\u064e\u0628\u064f\u0648\u0646\u064e",10,"\u0641\u064e\u0627\u0631\u0652\u062a\u064e\u0642\u0650\u0628\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0623\u0652\u062a\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0628\u0650\u062f\u064f\u062e\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",11,"\u064a\u064e\u063a\u0652\u0634\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u06d6 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",12,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u0643\u0652\u0634\u0650\u0641\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",13,"\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",14,"\u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064f\u0639\u064e\u0644\u0651\u064e\u0645\u064c \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",15,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0627\u0626\u0650\u062f\u064f\u0648\u0646\u064e",16,"\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0628\u0652\u0637\u0650\u0634\u064f \u0627\u0644\u0652\u0628\u064e\u0637\u0652\u0634\u064e\u0629\u064e \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0652\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",17,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",18,"\u0623\u064e\u0646\u0652 \u0623\u064e\u062f\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",19,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0622\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",20,"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u0652\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0631\u0652\u062c\u064f\u0645\u064f\u0648\u0646\u0650",21,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0644\u0650\u064a \u0641\u064e\u0627\u0639\u0652\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0646\u0650",22,"\u0641\u064e\u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",23,"\u0641\u064e\u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u0652\u0644\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0627\u062a\u0652\u0631\u064f\u0643\u0650 \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0631\u064e\u0647\u0652\u0648\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062c\u064f\u0646\u0652\u062f\u064c \u0645\u064f\u063a\u0652\u0631\u064e\u0642\u064f\u0648\u0646\u064e",25,"\u0643\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",26,"\u0648\u064e\u0632\u064f\u0631\u064f\u0648\u0639\u064d \u0648\u064e\u0645\u064e\u0642\u064e\u0627\u0645\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",27,"\u0648\u064e\u0646\u064e\u0639\u0652\u0645\u064e\u0629\u064d \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0643\u0650\u0647\u0650\u064a\u0646\u064e",28,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",29,"\u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0643\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0646\u0652\u0638\u064e\u0631\u0650\u064a\u0646\u064e",30,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0647\u0650\u064a\u0646\u0650",31,"\u0645\u0650\u0646\u0652 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0644\u0650\u064a\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",32,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0627\u062e\u0652\u062a\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",33,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0628\u064e\u0644\u064e\u0627\u0621\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",34,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",35,"\u0625\u0650\u0646\u0652 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0648\u0652\u062a\u064e\u062a\u064f\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0646\u0652\u0634\u064e\u0631\u0650\u064a\u0646\u064e",36,"\u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",37,"\u0623\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0623\u064e\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u062a\u064f\u0628\u0651\u064e\u0639\u064d \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",38,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0627\u0639\u0650\u0628\u0650\u064a\u0646\u064e",39,"\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",40,"\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650 \u0645\u0650\u064a\u0642\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",41,"\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0645\u064e\u0648\u0652\u0644\u064b\u0649 \u0639\u064e\u0646\u0652 \u0645\u064e\u0648\u0652\u0644\u064b\u0649 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",42,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0631\u064e\u062d\u0650\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",43,"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u062c\u064e\u0631\u064e\u062a\u064e \u0627\u0644\u0632\u0651\u064e\u0642\u0651\u064f\u0648\u0645\u0650",44,"\u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u062b\u0650\u064a\u0645\u0650",45,"\u0643\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u0644\u0650 \u064a\u064e\u063a\u0652\u0644\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064f\u0637\u064f\u0648\u0646\u0650",46,"\u0643\u064e\u063a\u064e\u0644\u0652\u064a\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u0650",47,"\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0641\u064e\u0627\u0639\u0652\u062a\u0650\u0644\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",48,"\u062b\u064f\u0645\u0651\u064e \u0635\u064f\u0628\u0651\u064f\u0648\u0627 \u0641\u064e\u0648\u0652\u0642\u064e \u0631\u064e\u0623\u0652\u0633\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u0650",49,"\u0630\u064f\u0642\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u064f",50,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064e\u0645\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",51,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0642\u064e\u0627\u0645\u064d \u0623\u064e\u0645\u0650\u064a\u0646\u064d",52,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",53,"\u064a\u064e\u0644\u0652\u0628\u064e\u0633\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0633\u064f\u0646\u0652\u062f\u064f\u0633\u064d \u0648\u064e\u0625\u0650\u0633\u0652\u062a\u064e\u0628\u0652\u0631\u064e\u0642\u064d \u0645\u064f\u062a\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650\u064a\u0646\u064e",54,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0632\u064e\u0648\u0651\u064e\u062c\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u062d\u064f\u0648\u0631\u064d \u0639\u0650\u064a\u0646\u064d",55,"\u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",56,"\u0644\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0648\u064e\u0642\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",57,"\u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",58,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",59,"\u0641\u064e\u0627\u0631\u0652\u062a\u064e\u0642\u0650\u0628\u0652 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0631\u0652\u062a\u064e\u0642\u0650\u0628\u064f\u0648\u0646\u064e"],t.v)
B.asl=new A.U([1,u.B,2,u.da,3,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",4,"\u0648\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u064f\u062b\u0651\u064f \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0628\u0651\u064e\u0629\u064d \u0622\u064a\u064e\u0627\u062a\u064c \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",5,"\u0648\u064e\u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u064d \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0635\u0652\u0631\u0650\u064a\u0641\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u0650 \u0622\u064a\u064e\u0627\u062a\u064c \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",6,"\u062a\u0650\u0644\u0652\u0643\u064e \u0622\u064a\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u0652\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",7,"\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0641\u0651\u064e\u0627\u0643\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",8,"\u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0635\u0650\u0631\u0651\u064f \u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u0652\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",9,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u064e \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",10,"\u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",11,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u0650\u0646\u0652 \u0631\u0650\u062c\u0652\u0632\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064c",12,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u0644\u0650\u062a\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064f \u0641\u0650\u064a\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",13,"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0627\u062a\u064d \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",14,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",15,"\u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",16,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650 \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",17,"\u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u0628\u064e\u063a\u0652\u064a\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u0652\u0636\u0650\u064a \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",18,"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0631\u0650\u064a\u0639\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",19,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u064a\u064f\u063a\u0652\u0646\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0628\u064e\u0639\u0652\u0636\u064d \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",20,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u064d \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",21,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062c\u0652\u062a\u064e\u0631\u064e\u062d\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u0645\u064e\u062d\u0652\u064a\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u06da \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u0650\u062a\u064f\u062c\u0652\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",23,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e\u0647\u064f \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u062e\u064e\u062a\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0645\u0652\u0639\u0650\u0647\u0650 \u0648\u064e\u0642\u064e\u0644\u0652\u0628\u0650\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u064e\u0631\u0650\u0647\u0650 \u063a\u0650\u0634\u064e\u0627\u0648\u064e\u0629\u064b \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0646\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u062f\u0651\u064e\u0647\u0652\u0631\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e",25,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062d\u064f\u062c\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0627\u0626\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",26,"\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u062e\u0652\u0633\u064e\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0646\u064e",28,"\u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062c\u064e\u0627\u062b\u0650\u064a\u064e\u0629\u064b \u06da \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062a\u064f\u062f\u0652\u0639\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u0650\u062a\u064e\u0627\u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",29,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064f\u0646\u064e\u0627 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0652\u062a\u064e\u0646\u0652\u0633\u0650\u062e\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",30,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",31,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u064a \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",32,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0644\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064f\u0644\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u0646\u064e\u062f\u0652\u0631\u0650\u064a \u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0625\u0650\u0646\u0652 \u0646\u064e\u0638\u064f\u0646\u0651\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0638\u064e\u0646\u0651\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0633\u0652\u062a\u064e\u064a\u0652\u0642\u0650\u0646\u0650\u064a\u0646\u064e",33,"\u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0646\u0652\u0633\u064e\u0627\u0643\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f\u0645\u0652 \u0644\u0650\u0642\u064e\u0627\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u0650\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0635\u0650\u0631\u0650\u064a\u0646\u064e",35,"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06da \u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0633\u0652\u062a\u064e\u0639\u0652\u062a\u064e\u0628\u064f\u0648\u0646\u064e",36,"\u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",37,"\u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0643\u0650\u0628\u0652\u0631\u0650\u064a\u064e\u0627\u0621\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f"],t.v)
B.arc=new A.U([1,u.B,2,u.da,3,"\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u0623\u064f\u0646\u0652\u0630\u0650\u0631\u064f\u0648\u0627 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e",4,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u0650\u0631\u0652\u0643\u064c \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u06d6 \u0627\u0626\u0652\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u062b\u064e\u0627\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",5,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0644\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u064f\u0639\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u063a\u064e\u0627\u0641\u0650\u0644\u064f\u0648\u0646\u064e",6,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064f\u0634\u0650\u0631\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u064b \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",8,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u06d6 \u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u064a\u0652\u062a\u064f\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0641\u0650\u064a\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",9,"\u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f \u0628\u0650\u062f\u0652\u0639\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u0650\u064a \u0645\u064e\u0627 \u064a\u064f\u0641\u0652\u0639\u064e\u0644\u064f \u0628\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",10,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u064c \u0645\u0650\u0646\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0641\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0648\u064e\u0625\u0650\u0630\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0641\u0652\u0643\u064c \u0642\u064e\u062f\u0650\u064a\u0645\u064c",12,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0645\u064e\u0627\u0645\u064b\u0627 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u06da \u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064c \u0644\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u0644\u0650\u064a\u064f\u0646\u0652\u0630\u0650\u0631\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0648\u064e\u0628\u064f\u0634\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",13,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e",14,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",15,"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0628\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u06d6 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u0652\u0647\u064f \u0623\u064f\u0645\u0651\u064f\u0647\u064f \u0643\u064f\u0631\u0652\u0647\u064b\u0627 \u0648\u064e\u0648\u064e\u0636\u064e\u0639\u064e\u062a\u0652\u0647\u064f \u0643\u064f\u0631\u0652\u0647\u064b\u0627 \u06d6 \u0648\u064e\u062d\u064e\u0645\u0652\u0644\u064f\u0647\u064f \u0648\u064e\u0641\u0650\u0635\u064e\u0627\u0644\u064f\u0647\u064f \u062b\u064e\u0644\u064e\u0627\u062b\u064f\u0648\u0646\u064e \u0634\u064e\u0647\u0652\u0631\u064b\u0627 \u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0633\u064e\u0646\u064e\u0629\u064b \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0648\u0652\u0632\u0650\u0639\u0652\u0646\u0650\u064a \u0623\u064e\u0646\u0652 \u0623\u064e\u0634\u0652\u0643\u064f\u0631\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u062a\u064e\u0631\u0652\u0636\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u0652 \u0644\u0650\u064a \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064f\u0628\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",16,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u0646\u064e\u062a\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u064f \u0639\u064e\u0646\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0635\u0651\u0650\u062f\u0652\u0642\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",17,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u0623\u064f\u0641\u0651\u064d \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0639\u0650\u062f\u064e\u0627\u0646\u0650\u0646\u0650\u064a \u0623\u064e\u0646\u0652 \u0623\u064f\u062e\u0652\u0631\u064e\u062c\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u064a \u0648\u064e\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u062b\u064e\u0627\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u064a\u0652\u0644\u064e\u0643\u064e \u0622\u0645\u0650\u0646\u0652 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u064e\u0627\u0637\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",18,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0641\u0650\u064a \u0623\u064f\u0645\u064e\u0645\u064d \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e",19,"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u064d \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064c \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0644\u0650\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0630\u0652\u0647\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u062d\u064e\u064a\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0652\u062a\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0641\u0652\u0633\u064f\u0642\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0652 \u0623\u064e\u062e\u064e\u0627 \u0639\u064e\u0627\u062f\u064d \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u0630\u064e\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0642\u064e\u0627\u0641\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0650 \u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",22,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u062c\u0650\u0626\u0652\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064e\u0623\u0652\u0641\u0650\u0643\u064e\u0646\u064e\u0627 \u0639\u064e\u0646\u0652 \u0622\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",23,"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u0652\u062a\u064f \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u062a\u064e\u062c\u0652\u0647\u064e\u0644\u064f\u0648\u0646\u064e",24,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0647\u064f \u0639\u064e\u0627\u0631\u0650\u0636\u064b\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0623\u064e\u0648\u0652\u062f\u0650\u064a\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0639\u064e\u0627\u0631\u0650\u0636\u064c \u0645\u064f\u0645\u0652\u0637\u0650\u0631\u064f\u0646\u064e\u0627 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u06d6 \u0631\u0650\u064a\u062d\u064c \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",25,"\u062a\u064f\u062f\u064e\u0645\u0651\u0650\u0631\u064f \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064f\u0647\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",26,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0625\u0650\u0646\u0652 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0645\u0652\u0639\u064b\u0627 \u0648\u064e\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u0645\u0652\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0630\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062c\u0652\u062d\u064e\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0647\u0652\u0632\u0650\u0626\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0635\u064e\u0631\u0651\u064e\u0641\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e",28,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064e\u0635\u064e\u0631\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064f\u0631\u0652\u0628\u064e\u0627\u0646\u064b\u0627 \u0622\u0644\u0650\u0647\u064e\u0629\u064b \u06d6 \u0628\u064e\u0644\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0641\u0652\u0643\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",29,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0635\u064e\u0631\u064e\u0641\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0646\u064e\u0641\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064f\u0648\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0635\u0650\u062a\u064f\u0648\u0627 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e \u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u0650\u064a\u0646\u064e",30,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0631\u0650\u064a\u0642\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",31,"\u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u064e\u0646\u064e\u0627 \u0623\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062c\u0650\u0631\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",32,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064f\u062c\u0650\u0628\u0652 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0645\u064f\u0639\u0652\u062c\u0650\u0632\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",33,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u064a\u064e \u0628\u0650\u062e\u064e\u0644\u0652\u0642\u0650\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0642\u064e\u0627\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",34,"\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",35,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0643\u064e\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064e \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0632\u0652\u0645\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u0628\u064e\u062b\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0627\u0639\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0646\u064e\u0647\u064e\u0627\u0631\u064d \u06da \u0628\u064e\u0644\u064e\u0627\u063a\u064c \u06da \u0641\u064e\u0647\u064e\u0644\u0652 \u064a\u064f\u0647\u0652\u0644\u064e\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e"],t.v)
B.apr=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",2,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064d \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d9 \u0643\u064e\u0641\u0651\u064e\u0631\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u064e\u062d\u064e \u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",3,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",4,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0636\u064e\u0631\u0652\u0628\u064e \u0627\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062b\u0652\u062e\u064e\u0646\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0641\u064e\u0634\u064f\u062f\u0651\u064f\u0648\u0627 \u0627\u0644\u0652\u0648\u064e\u062b\u064e\u0627\u0642\u064e \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0651\u064b\u0627 \u0628\u064e\u0639\u0652\u062f\u064f \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u062f\u064e\u0627\u0621\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0636\u064e\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0652\u0628\u064f \u0623\u064e\u0648\u0652\u0632\u064e\u0627\u0631\u064e\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0646\u0652\u062a\u064e\u0635\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u06d7 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",5,"\u0633\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f \u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",6,"\u0648\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0639\u064e\u0631\u0651\u064e\u0641\u064e\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652",7,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u062a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u0652 \u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u0652",8,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u0639\u0652\u0633\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",9,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u062d\u0652\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",10,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u062f\u064e\u0645\u0651\u064e\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f\u0647\u064e\u0627",11,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652",12,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u0652\u0648\u064b\u0649 \u0644\u064e\u0647\u064f\u0645\u0652",13,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0647\u0650\u064a\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u062a\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u062a\u0652\u0643\u064e \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u0646\u064e\u0627\u0635\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u0652",14,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0643\u064e\u0645\u064e\u0646\u0652 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0633\u064f\u0648\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652",15,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u06d6 \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064c \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u063a\u064e\u064a\u0652\u0631\u0650 \u0622\u0633\u0650\u0646\u064d \u0648\u064e\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064c \u0645\u0650\u0646\u0652 \u0644\u064e\u0628\u064e\u0646\u064d \u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064e\u063a\u064e\u064a\u0651\u064e\u0631\u0652 \u0637\u064e\u0639\u0652\u0645\u064f\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064c \u0645\u0650\u0646\u0652 \u062e\u064e\u0645\u0652\u0631\u064d \u0644\u064e\u0630\u0651\u064e\u0629\u064d \u0644\u0650\u0644\u0634\u0651\u064e\u0627\u0631\u0650\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064c \u0645\u0650\u0646\u0652 \u0639\u064e\u0633\u064e\u0644\u064d \u0645\u064f\u0635\u064e\u0641\u0651\u064b\u0649 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0627\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0643\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u064c \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0633\u064f\u0642\u064f\u0648\u0627 \u0645\u064e\u0627\u0621\u064b \u062d\u064e\u0645\u0650\u064a\u0645\u064b\u0627 \u0641\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0623\u064e\u0645\u0652\u0639\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652",16,"\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0622\u0646\u0650\u0641\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u0628\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652",17,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0648\u0652\u0627 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0622\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u062a\u064e\u0642\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652",18,"\u0641\u064e\u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u06d6 \u0641\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0627\u0637\u064f\u0647\u064e\u0627 \u06da \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064e\u0627\u0647\u064f\u0645\u0652",19,"\u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0643\u064e \u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064f\u062a\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u062b\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u0652",20,"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e\u062a\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0645\u064f\u062d\u0652\u0643\u064e\u0645\u064e\u0629\u064c \u0648\u064e\u0630\u064f\u0643\u0650\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0644\u0652\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u06d9 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0646\u064e\u0638\u064e\u0631\u064e \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0634\u0650\u064a\u0651\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06d6 \u0641\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652",21,"\u0637\u064e\u0627\u0639\u064e\u0629\u064c \u0648\u064e\u0642\u064e\u0648\u0652\u0644\u064c \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064c \u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0641\u064e\u0644\u064e\u0648\u0652 \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652",22,"\u0641\u064e\u0647\u064e\u0644\u0652 \u0639\u064e\u0633\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u062a\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u0652",23,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0635\u064e\u0645\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652",24,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u062f\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0623\u064e\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u064d \u0623\u064e\u0642\u0652\u0641\u064e\u0627\u0644\u064f\u0647\u064e\u0627",25,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0631\u0652\u062a\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649 \u06d9 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0633\u064e\u0648\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652",26,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627 \u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0646\u064f\u0637\u0650\u064a\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652",27,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u0652",28,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u062e\u064e\u0637\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627 \u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u062d\u0652\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",29,"\u0623\u064e\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0636\u0652\u063a\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652",30,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u0623\u064e\u0631\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0639\u064e\u0631\u064e\u0641\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0644\u064e\u062d\u0652\u0646\u0650 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652",31,"\u0648\u064e\u0644\u064e\u0646\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0646\u064e\u0628\u0652\u0644\u064f\u0648\u064e \u0623\u064e\u062e\u0652\u0628\u064e\u0627\u0631\u064e\u0643\u064f\u0645\u0652",32,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0634\u064e\u0627\u0642\u0651\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0633\u064e\u064a\u064f\u062d\u0652\u0628\u0650\u0637\u064f \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",33,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0637\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652",34,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652",35,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0644\u0652\u0645\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u062a\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652",36,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u064c \u0648\u064e\u0644\u064e\u0647\u0652\u0648\u064c \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u064a\u064f\u0624\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652",37,"\u0625\u0650\u0646\u0652 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u0652\u0643\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u064a\u064f\u062d\u0652\u0641\u0650\u0643\u064f\u0645\u0652 \u062a\u064e\u0628\u0652\u062e\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u0652 \u0623\u064e\u0636\u0652\u063a\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652",38,"\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u062a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0644\u0650\u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u064f \u0639\u064e\u0646\u0652 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0628\u0652\u062f\u0650\u0644\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652"],t.v)
B.aoO=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0641\u064e\u062a\u0652\u062d\u064b\u0627 \u0645\u064f\u0628\u0650\u064a\u0646\u064b\u0627",2,"\u0644\u0650\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u062a\u064e\u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u0652 \u0630\u064e\u0646\u0652\u0628\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e \u0648\u064e\u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0643\u064e \u0635\u0650\u0631\u064e\u0627\u0637\u064b\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627",3,"\u0648\u064e\u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0635\u0652\u0631\u064b\u0627 \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627",4,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0644\u0650\u064a\u064e\u0632\u0652\u062f\u064e\u0627\u062f\u064f\u0648\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u0645\u064e\u0639\u064e \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",5,"\u0644\u0650\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0648\u0652\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",6,"\u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u064e\u0627\u062a\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0646\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0638\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u06da \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062f\u064e\u0627\u0626\u0650\u0631\u064e\u0629\u064f \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u06d6 \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06d6 \u0648\u064e\u0633\u064e\u0627\u0621\u064e\u062a\u0652 \u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",7,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",8,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u064b\u0627 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064b\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",9,"\u0644\u0650\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u062a\u064f\u0639\u064e\u0632\u0651\u0650\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u062a\u064f\u0648\u064e\u0642\u0651\u0650\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0647\u064f \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",10,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0648\u0652\u0642\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0641\u064e\u0645\u064e\u0646\u0652 \u0646\u064e\u0643\u064e\u062b\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0643\u064f\u062b\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0648\u0652\u0641\u064e\u0649\u0670 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0633\u064e\u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",11,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0634\u064e\u063a\u064e\u0644\u064e\u062a\u0652\u0646\u064e\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f\u0648\u0646\u064e\u0627 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u06da \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0636\u064e\u0631\u0651\u064b\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u0639\u064b\u0627 \u06da \u0628\u064e\u0644\u0652 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",12,"\u0628\u064e\u0644\u0652 \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0648\u064e\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0638\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0648\u0652\u0621\u0650 \u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0628\u064f\u0648\u0631\u064b\u0627",13,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",14,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627",15,"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0644\u0650\u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0647\u064e\u0627 \u0630\u064e\u0631\u064f\u0648\u0646\u064e\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652\u0643\u064f\u0645\u0652 \u06d6 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f\u0648\u0627 \u0643\u064e\u0644\u064e\u0627\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0642\u064f\u0644\u0652 \u0644\u064e\u0646\u0652 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0644\u0652 \u062a\u064e\u062d\u0652\u0633\u064f\u062f\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u06da \u0628\u064e\u0644\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",16,"\u0642\u064f\u0644\u0652 \u0644\u0650\u0644\u0652\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u0650 \u0633\u064e\u062a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u064d \u0623\u064f\u0648\u0644\u0650\u064a \u0628\u064e\u0623\u0652\u0633\u064d \u0634\u064e\u062f\u0650\u064a\u062f\u064d \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u064a\u064f\u0624\u0652\u062a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",17,"\u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670 \u062d\u064e\u0631\u064e\u062c\u064c \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u062c\u0650 \u062d\u064e\u0631\u064e\u062c\u064c \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0631\u0650\u064a\u0636\u0650 \u062d\u064e\u0631\u064e\u062c\u064c \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0652\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",18,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u0652 \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e\u0643\u064e \u062a\u064e\u062d\u0652\u062a\u064e \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0633\u0651\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u062b\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u0652\u062d\u064b\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",19,"\u0648\u064e\u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064b \u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",20,"\u0648\u064e\u0639\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064b \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0641\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0648\u064e\u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0635\u0650\u0631\u064e\u0627\u0637\u064b\u0627 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064b\u0627",21,"\u0648\u064e\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0644\u064e\u0645\u0652 \u062a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",22,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0642\u064e\u0627\u062a\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",23,"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064b\u0627",24,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0628\u064e\u0637\u0652\u0646\u0650 \u0645\u064e\u0643\u0651\u064e\u0629\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0623\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0641\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",25,"\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0647\u064e\u062f\u0652\u064a\u064e \u0645\u064e\u0639\u0652\u0643\u064f\u0648\u0641\u064b\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0644\u064f\u063a\u064e \u0645\u064e\u062d\u0650\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064c \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064c \u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0637\u064e\u0626\u064f\u0648\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0639\u064e\u0631\u0651\u064e\u0629\u064c \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0644\u0650\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0644\u064e\u0648\u0652 \u062a\u064e\u0632\u064e\u064a\u0651\u064e\u0644\u064f\u0648\u0627 \u0644\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",26,"\u0625\u0650\u0630\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0651\u064e\u0629\u064e \u062d\u064e\u0645\u0650\u064a\u0651\u064e\u0629\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0644\u0652\u0632\u064e\u0645\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0623\u064e\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064e\u0627 \u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",27,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064f\u0624\u0652\u064a\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0644\u064e\u062a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u064f\u062d\u064e\u0644\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064f\u0642\u064e\u0635\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u062a\u0652\u062d\u064b\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",28,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u062f\u0650\u064a\u0646\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u0638\u0652\u0647\u0650\u0631\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650 \u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",29,"\u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0623\u064e\u0634\u0650\u062f\u0651\u064e\u0627\u0621\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0631\u064f\u062d\u064e\u0645\u064e\u0627\u0621\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u062a\u064e\u0631\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064f\u0643\u0651\u064e\u0639\u064b\u0627 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u06d6 \u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062b\u064e\u0631\u0650 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u06da \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u0650 \u0643\u064e\u0632\u064e\u0631\u0652\u0639\u064d \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0634\u064e\u0637\u0652\u0623\u064e\u0647\u064f \u0641\u064e\u0622\u0632\u064e\u0631\u064e\u0647\u064f \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0644\u064e\u0638\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0648\u0642\u0650\u0647\u0650 \u064a\u064f\u0639\u0652\u062c\u0650\u0628\u064f \u0627\u0644\u0632\u0651\u064f\u0631\u0651\u064e\u0627\u0639\u064e \u0644\u0650\u064a\u064e\u063a\u0650\u064a\u0638\u064e \u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u06d7 \u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627"],t.v)
B.ap1=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",2,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u0641\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0635\u0652\u0648\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0648\u0652\u0642\u064e \u0635\u064e\u0648\u0652\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0647\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0643\u064e\u062c\u064e\u0647\u0652\u0631\u0650 \u0628\u064e\u0639\u0652\u0636\u0650\u0643\u064f\u0645\u0652 \u0644\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0623\u064e\u0646\u0652 \u062a\u064e\u062d\u0652\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",3,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u063a\u064f\u0636\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0635\u0652\u0648\u064e\u0627\u062a\u064e\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u0645\u0652\u062a\u064e\u062d\u064e\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u0652 \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06da \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",4,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u062d\u064f\u062c\u064f\u0631\u064e\u0627\u062a\u0650 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",5,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",6,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064c \u0628\u0650\u0646\u064e\u0628\u064e\u0625\u064d \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064f\u0635\u0650\u064a\u0628\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0644\u064e\u0629\u064d \u0641\u064e\u062a\u064f\u0635\u0652\u0628\u0650\u062d\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0646\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0644\u064e\u0648\u0652 \u064a\u064f\u0637\u0650\u064a\u0639\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0643\u064e\u062b\u0650\u064a\u0631\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0644\u064e\u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0628\u0651\u064e\u0628\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0643\u064e\u0631\u0651\u064e\u0647\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0633\u064f\u0648\u0642\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u0650\u0635\u0652\u064a\u064e\u0627\u0646\u064e \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0634\u0650\u062f\u064f\u0648\u0646\u064e",8,"\u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",9,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0627\u0642\u0652\u062a\u064e\u062a\u064e\u0644\u064f\u0648\u0627 \u0641\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0628\u064e\u063a\u064e\u062a\u0652 \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u0628\u0652\u063a\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0641\u0650\u064a\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0641\u064e\u0627\u0621\u064e\u062a\u0652 \u0641\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u0650 \u0648\u064e\u0623\u064e\u0642\u0652\u0633\u0650\u0637\u064f\u0648\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0642\u0652\u0633\u0650\u0637\u0650\u064a\u0646\u064e",10,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u062e\u0652\u0648\u064e\u0629\u064c \u0641\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062e\u064e\u0648\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0631\u0652\u062d\u064e\u0645\u064f\u0648\u0646\u064e",11,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062e\u064e\u0631\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0621\u064c \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0621\u064d \u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0646\u0651\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u0652\u0645\u0650\u0632\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u0628\u064e\u0632\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0642\u064e\u0627\u0628\u0650 \u06d6 \u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0650\u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0652\u0641\u064f\u0633\u064f\u0648\u0642\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064f\u0628\u0652 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",12,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u0650 \u0625\u0650\u062b\u0652\u0645\u064c \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u064e\u0633\u0651\u064e\u0633\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u062a\u064e\u0628\u0652 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0628\u064e\u0639\u0652\u0636\u064b\u0627 \u06da \u0623\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064e \u0644\u064e\u062d\u0652\u0645\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0645\u064e\u064a\u0652\u062a\u064b\u0627 \u0641\u064e\u0643\u064e\u0631\u0650\u0647\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",13,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064e\u0643\u064e\u0631\u064d \u0648\u064e\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0634\u064f\u0639\u064f\u0648\u0628\u064b\u0627 \u0648\u064e\u0642\u064e\u0628\u064e\u0627\u0626\u0650\u0644\u064e \u0644\u0650\u062a\u064e\u0639\u064e\u0627\u0631\u064e\u0641\u064f\u0648\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u0631\u064e\u0645\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062a\u0652\u0642\u064e\u0627\u0643\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064c",14,"\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0631\u064e\u0627\u0628\u064f \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u06d6 \u0642\u064f\u0644\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u0650 \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0644\u0650\u062a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",15,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u0627\u0628\u064f\u0648\u0627 \u0648\u064e\u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",16,"\u0642\u064f\u0644\u0652 \u0623\u064e\u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",17,"\u064a\u064e\u0645\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u06d6 \u0642\u064f\u0644\u0652 \u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0646\u0651\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0628\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0645\u064f\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u0644\u0650\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",18,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u063a\u064e\u064a\u0652\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e"],t.v)
B.ar5=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0642 \u06da \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u062c\u0650\u064a\u062f\u0650",2,"\u0628\u064e\u0644\u0652 \u0639\u064e\u062c\u0650\u0628\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0634\u064e\u064a\u0652\u0621\u064c \u0639\u064e\u062c\u0650\u064a\u0628\u064c",3,"\u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0631\u064e\u062c\u0652\u0639\u064c \u0628\u064e\u0639\u0650\u064a\u062f\u064c",4,"\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0646\u0652\u0642\u064f\u0635\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u062d\u064e\u0641\u0650\u064a\u0638\u064c",5,"\u0628\u064e\u0644\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u064d \u0645\u064e\u0631\u0650\u064a\u062c\u064d",6,"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0628\u064e\u0646\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0641\u064f\u0631\u064f\u0648\u062c\u064d",7,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u0652\u062c\u064d \u0628\u064e\u0647\u0650\u064a\u062c\u064d",8,"\u062a\u064e\u0628\u0652\u0635\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0628\u0652\u062f\u064d \u0645\u064f\u0646\u0650\u064a\u0628\u064d",9,"\u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064b\u0627 \u0641\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u062d\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0635\u0650\u064a\u062f\u0650",10,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064e \u0628\u064e\u0627\u0633\u0650\u0642\u064e\u0627\u062a\u064d \u0644\u064e\u0647\u064e\u0627 \u0637\u064e\u0644\u0652\u0639\u064c \u0646\u064e\u0636\u0650\u064a\u062f\u064c",11,"\u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0644\u0650\u0644\u0652\u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u06d6 \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0628\u064e\u0644\u0652\u062f\u064e\u0629\u064b \u0645\u064e\u064a\u0652\u062a\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u062e\u064f\u0631\u064f\u0648\u062c\u064f",12,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u0651\u0650 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f",13,"\u0648\u064e\u0639\u064e\u0627\u062f\u064c \u0648\u064e\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064f \u0644\u064f\u0648\u0637\u064d",14,"\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0643\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u062a\u064f\u0628\u0651\u064e\u0639\u064d \u06da \u0643\u064f\u0644\u0651\u064c \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0639\u0650\u064a\u062f\u0650",15,"\u0623\u064e\u0641\u064e\u0639\u064e\u064a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0644\u064e\u0628\u0652\u0633\u064d \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0642\u064d \u062c\u064e\u062f\u0650\u064a\u062f\u064d",16,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0648\u064e\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0633\u0652\u0648\u0650\u0633\u064f \u0628\u0650\u0647\u0650 \u0646\u064e\u0641\u0652\u0633\u064f\u0647\u064f \u06d6 \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u062d\u064e\u0628\u0652\u0644\u0650 \u0627\u0644\u0652\u0648\u064e\u0631\u0650\u064a\u062f\u0650",17,"\u0625\u0650\u0630\u0652 \u064a\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0644\u064e\u0642\u0651\u0650\u064a\u064e\u0627\u0646\u0650 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0642\u064e\u0639\u0650\u064a\u062f\u064c",18,"\u0645\u064e\u0627 \u064a\u064e\u0644\u0652\u0641\u0650\u0638\u064f \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0642\u0650\u064a\u0628\u064c \u0639\u064e\u062a\u0650\u064a\u062f\u064c",19,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0633\u064e\u0643\u0652\u0631\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u062a\u064e\u062d\u0650\u064a\u062f\u064f",20,"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0648\u064e\u0639\u0650\u064a\u062f\u0650",21,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0645\u064e\u0639\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0626\u0650\u0642\u064c \u0648\u064e\u0634\u064e\u0647\u0650\u064a\u062f\u064c",22,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u0650\u064a \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0641\u064e\u0643\u064e\u0634\u064e\u0641\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064e \u063a\u0650\u0637\u064e\u0627\u0621\u064e\u0643\u064e \u0641\u064e\u0628\u064e\u0635\u064e\u0631\u064f\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062d\u064e\u062f\u0650\u064a\u062f\u064c",23,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u064f\u0647\u064f \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0639\u064e\u062a\u0650\u064a\u062f\u064c",24,"\u0623\u064e\u0644\u0652\u0642\u0650\u064a\u064e\u0627 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u064d",25,"\u0645\u064e\u0646\u0651\u064e\u0627\u0639\u064d \u0644\u0650\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0645\u064f\u0639\u0652\u062a\u064e\u062f\u064d \u0645\u064f\u0631\u0650\u064a\u0628\u064d",26,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u0623\u064e\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0634\u0651\u064e\u062f\u0650\u064a\u062f\u0650",27,"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u064f\u0647\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0623\u064e\u0637\u0652\u063a\u064e\u064a\u0652\u062a\u064f\u0647\u064f \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",28,"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627 \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0642\u064e\u062f\u0652 \u0642\u064e\u062f\u0651\u064e\u0645\u0652\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0639\u0650\u064a\u062f\u0650",29,"\u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u062f\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0627\u0645\u064d \u0644\u0650\u0644\u0652\u0639\u064e\u0628\u0650\u064a\u062f\u0650",30,"\u064a\u064e\u0648\u0652\u0645\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0647\u064e\u0644\u0650 \u0627\u0645\u0652\u062a\u064e\u0644\u064e\u0623\u0652\u062a\u0650 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0632\u0650\u064a\u062f\u064d",31,"\u0648\u064e\u0623\u064f\u0632\u0652\u0644\u0650\u0641\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u0639\u0650\u064a\u062f\u064d",32,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u064d",33,"\u0645\u064e\u0646\u0652 \u062e\u064e\u0634\u0650\u064a\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0642\u064e\u0644\u0652\u0628\u064d \u0645\u064f\u0646\u0650\u064a\u0628\u064d",34,"\u0627\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064e\u0644\u064e\u0627\u0645\u064d \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u062e\u064f\u0644\u064f\u0648\u062f\u0650",35,"\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064e\u0632\u0650\u064a\u062f\u064c",36,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u0646\u064d \u0647\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0628\u064e\u0637\u0652\u0634\u064b\u0627 \u0641\u064e\u0646\u064e\u0642\u0651\u064e\u0628\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u0650\u0644\u064e\u0627\u062f\u0650 \u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u062d\u0650\u064a\u0635\u064d",37,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0644\u0652\u0628\u064c \u0623\u064e\u0648\u0652 \u0623\u064e\u0644\u0652\u0642\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u0647\u0650\u064a\u062f\u064c",38,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0644\u064f\u063a\u064f\u0648\u0628\u064d",39,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0642\u064e\u0628\u0652\u0644\u064e \u0637\u064f\u0644\u064f\u0648\u0639\u0650 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u0642\u064e\u0628\u0652\u0644\u064e \u0627\u0644\u0652\u063a\u064f\u0631\u064f\u0648\u0628\u0650",40,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652\u0647\u064f \u0648\u064e\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",41,"\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u062f\u0650 \u0645\u0650\u0646\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0642\u064e\u0631\u0650\u064a\u0628\u064d",42,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u064a\u0652\u062d\u064e\u0629\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u062e\u064f\u0631\u064f\u0648\u062c\u0650",43,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u0646\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",44,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0634\u064e\u0642\u0651\u064e\u0642\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0633\u0650\u0631\u064e\u0627\u0639\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0634\u0652\u0631\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",45,"\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u06d6 \u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0648\u064e\u0639\u0650\u064a\u062f\u0650"],t.v)
B.asG=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0630\u0651\u064e\u0627\u0631\u0650\u064a\u064e\u0627\u062a\u0650 \u0630\u064e\u0631\u0652\u0648\u064b\u0627",2,"\u0641\u064e\u0627\u0644\u0652\u062d\u064e\u0627\u0645\u0650\u0644\u064e\u0627\u062a\u0650 \u0648\u0650\u0642\u0652\u0631\u064b\u0627",3,"\u0641\u064e\u0627\u0644\u0652\u062c\u064e\u0627\u0631\u0650\u064a\u064e\u0627\u062a\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627",4,"\u0641\u064e\u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0633\u0651\u0650\u0645\u064e\u0627\u062a\u0650 \u0623\u064e\u0645\u0652\u0631\u064b\u0627",5,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u064c",6,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0648\u064e\u0627\u0642\u0650\u0639\u064c",7,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u062d\u064f\u0628\u064f\u0643\u0650",8,"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0641\u0650\u064a \u0642\u064e\u0648\u0652\u0644\u064d \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064d",9,"\u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064e\u0646\u0652 \u0623\u064f\u0641\u0650\u0643\u064e",10,"\u0642\u064f\u062a\u0650\u0644\u064e \u0627\u0644\u0652\u062e\u064e\u0631\u0651\u064e\u0627\u0635\u064f\u0648\u0646\u064e",11,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u063a\u064e\u0645\u0652\u0631\u064e\u0629\u064d \u0633\u064e\u0627\u0647\u064f\u0648\u0646\u064e",12,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",13,"\u064a\u064e\u0648\u0652\u0645\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064f\u0641\u0652\u062a\u064e\u0646\u064f\u0648\u0646\u064e",14,"\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",15,u.M,16,"\u0622\u062e\u0650\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",17,"\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",18,"\u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0633\u0652\u062d\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u0642\u0651\u064c \u0644\u0650\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u062d\u0652\u0631\u064f\u0648\u0645\u0650",20,"\u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0622\u064a\u064e\u0627\u062a\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",21,"\u0648\u064e\u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0631\u0650\u0632\u0652\u0642\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",23,"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0642\u0651\u064c \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",24,"\u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0636\u064e\u064a\u0652\u0641\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0627\u0644\u0652\u0645\u064f\u0643\u0652\u0631\u064e\u0645\u0650\u064a\u0646\u064e",25,"\u0625\u0650\u0630\u0652 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0642\u064e\u0648\u0652\u0645\u064c \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064f\u0648\u0646\u064e",26,"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0641\u064e\u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0639\u0650\u062c\u0652\u0644\u064d \u0633\u064e\u0645\u0650\u064a\u0646\u064d",27,"\u0641\u064e\u0642\u064e\u0631\u0651\u064e\u0628\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e",28,"\u0641\u064e\u0623\u064e\u0648\u0652\u062c\u064e\u0633\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u062e\u0650\u064a\u0641\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0648\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u064f\u0648\u0647\u064f \u0628\u0650\u063a\u064f\u0644\u064e\u0627\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",29,"\u0641\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0644\u064e\u062a\u0650 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064f\u0647\u064f \u0641\u0650\u064a \u0635\u064e\u0631\u0651\u064e\u0629\u064d \u0641\u064e\u0635\u064e\u0643\u0651\u064e\u062a\u0652 \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0639\u064e\u062c\u064f\u0648\u0632\u064c \u0639\u064e\u0642\u0650\u064a\u0645\u064c",30,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",31,u.as,32,u.d8,33,"\u0644\u0650\u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0637\u0650\u064a\u0646\u064d",34,"\u0645\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",35,"\u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",36,"\u0641\u064e\u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0628\u064e\u064a\u0652\u062a\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",37,"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064e",38,"\u0648\u064e\u0641\u0650\u064a \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0630\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",39,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0628\u0650\u0631\u064f\u0643\u0652\u0646\u0650\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0623\u064e\u0648\u0652 \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",40,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0644\u0650\u064a\u0645\u064c",41,"\u0648\u064e\u0641\u0650\u064a \u0639\u064e\u0627\u062f\u064d \u0625\u0650\u0630\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0627\u0644\u0652\u0639\u064e\u0642\u0650\u064a\u0645\u064e",42,"\u0645\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u062a\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u062a\u0652\u0647\u064f \u0643\u064e\u0627\u0644\u0631\u0651\u064e\u0645\u0650\u064a\u0645\u0650",43,"\u0648\u064e\u0641\u0650\u064a \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0625\u0650\u0630\u0652 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",44,"\u0641\u064e\u0639\u064e\u062a\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0639\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",45,"\u0641\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u0650\u064a\u064e\u0627\u0645\u064d \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u064f\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0648\u062d\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",47,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0628\u064e\u0646\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u064d \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0648\u0633\u0650\u0639\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u064e\u0631\u064e\u0634\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0632\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",50,"\u0641\u064e\u0641\u0650\u0631\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",51,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",52,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0623\u064e\u062a\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0623\u064e\u0648\u0652 \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",53,"\u0623\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0652\u0627 \u0628\u0650\u0647\u0650 \u06da \u0628\u064e\u0644\u0652 \u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0637\u064e\u0627\u063a\u064f\u0648\u0646\u064e",54,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0645\u064e\u0644\u064f\u0648\u0645\u064d",55,"\u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",56,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u0650",57,"\u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u064d \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0646\u0650",58,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u0632\u0651\u064e\u0627\u0642\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u062a\u0650\u064a\u0646\u064f",59,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0630\u064e\u0646\u064f\u0648\u0628\u064b\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0630\u064e\u0646\u064f\u0648\u0628\u0650 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u0650",60,"\u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u064a\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e"],t.v)
B.ar7=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650",2,"\u0648\u064e\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064e\u0633\u0652\u0637\u064f\u0648\u0631\u064d",3,"\u0641\u0650\u064a \u0631\u064e\u0642\u0651\u064d \u0645\u064e\u0646\u0652\u0634\u064f\u0648\u0631\u064d",4,"\u0648\u064e\u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0645\u064f\u0648\u0631\u0650",5,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0642\u0652\u0641\u0650 \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0641\u064f\u0648\u0639\u0650",6,"\u0648\u064e\u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u064f\u0648\u0631\u0650",7,"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0648\u064e\u0627\u0642\u0650\u0639\u064c",8,"\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062f\u064e\u0627\u0641\u0650\u0639\u064d",9,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0645\u064f\u0648\u0631\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0645\u064e\u0648\u0652\u0631\u064b\u0627",10,"\u0648\u064e\u062a\u064e\u0633\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0633\u064e\u064a\u0652\u0631\u064b\u0627",11,"\u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",12,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u062e\u064e\u0648\u0652\u0636\u064d \u064a\u064e\u0644\u0652\u0639\u064e\u0628\u064f\u0648\u0646\u064e",13,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u062f\u064e\u0639\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062f\u064e\u0639\u0651\u064b\u0627",14,"\u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",15,"\u0623\u064e\u0641\u064e\u0633\u0650\u062d\u0652\u0631\u064c \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0623\u064e\u0645\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",16,"\u0627\u0635\u0652\u0644\u064e\u0648\u0652\u0647\u064e\u0627 \u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u0644\u064e\u0627 \u062a\u064e\u0635\u0652\u0628\u0650\u0631\u064f\u0648\u0627 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",17,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0646\u064e\u0639\u0650\u064a\u0645\u064d",18,"\u0641\u064e\u0627\u0643\u0650\u0647\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0648\u064e\u0642\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",19,u.bg,20,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u064d \u0645\u064e\u0635\u0652\u0641\u064f\u0648\u0641\u064e\u0629\u064d \u06d6 \u0648\u064e\u0632\u064e\u0648\u0651\u064e\u062c\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u062d\u064f\u0648\u0631\u064d \u0639\u0650\u064a\u0646\u064d",21,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064d \u0623\u064e\u0644\u0652\u062d\u064e\u0642\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0644\u064e\u062a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0643\u064f\u0644\u0651\u064f \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e \u0631\u064e\u0647\u0650\u064a\u0646\u064c",22,"\u0648\u064e\u0623\u064e\u0645\u0652\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u062d\u0652\u0645\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",23,"\u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0623\u0652\u0633\u064b\u0627 \u0644\u064e\u0627 \u0644\u064e\u063a\u0652\u0648\u064c \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062b\u0650\u064a\u0645\u064c",24,"\u0648\u064e\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u063a\u0650\u0644\u0652\u0645\u064e\u0627\u0646\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064f\u0624\u0652\u0644\u064f\u0624\u064c \u0645\u064e\u0643\u0652\u0646\u064f\u0648\u0646\u064c",25,u.a,26,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u0650\u064a \u0623\u064e\u0647\u0652\u0644\u0650\u0646\u064e\u0627 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u0650\u064a\u0646\u064e",27,"\u0641\u064e\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u0642\u064e\u0627\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064f\u0648\u0645\u0650",28,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0646\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0628\u064e\u0631\u0651\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",29,"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0643\u064e\u0627\u0647\u0650\u0646\u064d \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064d",30,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0634\u064e\u0627\u0639\u0650\u0631\u064c \u0646\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0647\u0650 \u0631\u064e\u064a\u0652\u0628\u064e \u0627\u0644\u0652\u0645\u064e\u0646\u064f\u0648\u0646\u0650",31,"\u0642\u064f\u0644\u0652 \u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u0650\u064a\u0646\u064e",32,"\u0623\u064e\u0645\u0652 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0644\u064e\u0627\u0645\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06da \u0623\u064e\u0645\u0652 \u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0637\u064e\u0627\u063a\u064f\u0648\u0646\u064e",33,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0644\u064e\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",34,"\u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u062d\u064e\u062f\u0650\u064a\u062b\u064d \u0645\u0650\u062b\u0652\u0644\u0650\u0647\u0650 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",35,"\u0623\u064e\u0645\u0652 \u062e\u064f\u0644\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u064f\u0648\u0646\u064e",36,"\u0623\u064e\u0645\u0652 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",37,"\u0623\u064e\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0623\u064e\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u064a\u0652\u0637\u0650\u0631\u064f\u0648\u0646\u064e",38,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0633\u064f\u0644\u0651\u064e\u0645\u064c \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062a\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",39,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u0646\u064f\u0648\u0646\u064e",40,u.n,41,u.V,42,"\u0623\u064e\u0645\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u0652\u062f\u064b\u0627 \u06d6 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u064e",43,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",44,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u0650\u0633\u0652\u0641\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0633\u064e\u0627\u0642\u0650\u0637\u064b\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0633\u064e\u062d\u064e\u0627\u0628\u064c \u0645\u064e\u0631\u0652\u0643\u064f\u0648\u0645\u064c",45,"\u0641\u064e\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0644\u064e\u0627\u0642\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u064a\u064f\u0635\u0652\u0639\u064e\u0642\u064f\u0648\u0646\u064e",46,"\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u062f\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",48,"\u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0644\u0650\u062d\u064f\u0643\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f",49,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650"],t.v)
B.as5=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064e\u0648\u064e\u0649\u0670",2,"\u0645\u064e\u0627 \u0636\u064e\u0644\u0651\u064e \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u063a\u064e\u0648\u064e\u0649\u0670",3,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0647\u064e\u0648\u064e\u0649\u0670",4,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062d\u0652\u064a\u064c \u064a\u064f\u0648\u062d\u064e\u0649\u0670",5,"\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0642\u064f\u0648\u064e\u0649\u0670",6,"\u0630\u064f\u0648 \u0645\u0650\u0631\u0651\u064e\u0629\u064d \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670",7,"\u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u0641\u064f\u0642\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670",8,"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u062f\u064e\u0644\u0651\u064e\u0649\u0670",9,"\u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u0652\u0633\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670",10,"\u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0647\u0650 \u0645\u064e\u0627 \u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670",11,"\u0645\u064e\u0627 \u0643\u064e\u0630\u064e\u0628\u064e \u0627\u0644\u0652\u0641\u064f\u0624\u064e\u0627\u062f\u064f \u0645\u064e\u0627 \u0631\u064e\u0623\u064e\u0649\u0670",12,"\u0623\u064e\u0641\u064e\u062a\u064f\u0645\u064e\u0627\u0631\u064f\u0648\u0646\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0631\u064e\u0649\u0670",13,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0622\u0647\u064f \u0646\u064e\u0632\u0652\u0644\u064e\u0629\u064b \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",14,"\u0639\u0650\u0646\u0652\u062f\u064e \u0633\u0650\u062f\u0652\u0631\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0647\u064e\u0649\u0670",15,"\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064e\u0623\u0652\u0648\u064e\u0649\u0670",16,"\u0625\u0650\u0630\u0652 \u064a\u064e\u063a\u0652\u0634\u064e\u0649 \u0627\u0644\u0633\u0651\u0650\u062f\u0652\u0631\u064e\u0629\u064e \u0645\u064e\u0627 \u064a\u064e\u063a\u0652\u0634\u064e\u0649\u0670",17,"\u0645\u064e\u0627 \u0632\u064e\u0627\u063a\u064e \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0637\u064e\u063a\u064e\u0649\u0670",18,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0623\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649\u0670",19,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0627\u062a\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u0632\u0651\u064e\u0649\u0670",20,"\u0648\u064e\u0645\u064e\u0646\u064e\u0627\u0629\u064e \u0627\u0644\u062b\u0651\u064e\u0627\u0644\u0650\u062b\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",21,"\u0623\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670",22,"\u062a\u0650\u0644\u0652\u0643\u064e \u0625\u0650\u0630\u064b\u0627 \u0642\u0650\u0633\u0652\u0645\u064e\u0629\u064c \u0636\u0650\u064a\u0632\u064e\u0649\u0670",23,"\u0625\u0650\u0646\u0652 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064c \u0633\u064e\u0645\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d \u06da \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0647\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064f \u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670",24,"\u0623\u064e\u0645\u0652 \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0645\u064e\u0627 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0649\u0670",25,"\u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",26,"\u0648\u064e\u0643\u064e\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0644\u064e\u0643\u064d \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0644\u064e\u0627 \u062a\u064f\u063a\u0652\u0646\u0650\u064a \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u0630\u064e\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0631\u0652\u0636\u064e\u0649\u0670",27,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u064a\u064f\u0633\u064e\u0645\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064e \u062a\u064e\u0633\u0652\u0645\u0650\u064a\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670",28,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u064d \u06d6 \u0625\u0650\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627",29,"\u0641\u064e\u0623\u064e\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652 \u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0631\u0650\u062f\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627",30,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0628\u0652\u0644\u064e\u063a\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0650 \u0627\u0647\u0652\u062a\u064e\u062f\u064e\u0649\u0670",31,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u064e\u0627\u0621\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649",32,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0646\u064e \u0643\u064e\u0628\u064e\u0627\u0626\u0650\u0631\u064e \u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0648\u064e\u0627\u062d\u0650\u0634\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0645\u064e\u0645\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0648\u064e\u0627\u0633\u0650\u0639\u064f \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u0650 \u06da \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u062c\u0650\u0646\u0651\u064e\u0629\u064c \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0632\u064e\u0643\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670",33,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",34,"\u0648\u064e\u0623\u064e\u0639\u0652\u0637\u064e\u0649\u0670 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0623\u064e\u0643\u0652\u062f\u064e\u0649\u0670",35,"\u0623\u064e\u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u0650\u0644\u0652\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0631\u064e\u0649\u0670",36,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0628\u0651\u064e\u0623\u0652 \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062d\u064f\u0641\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",37,"\u0648\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0641\u0651\u064e\u0649\u0670",38,"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u064c \u0648\u0650\u0632\u0652\u0631\u064e \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",39,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0633\u064e\u0639\u064e\u0649\u0670",40,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0633\u064e\u0639\u0652\u064a\u064e\u0647\u064f \u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0631\u064e\u0649\u0670",41,"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062c\u0652\u0632\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u062c\u064e\u0632\u064e\u0627\u0621\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u0641\u064e\u0649\u0670",42,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0647\u064e\u0649\u0670",43,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u0636\u0652\u062d\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0628\u0652\u0643\u064e\u0649\u0670",44,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u0645\u064e\u0627\u062a\u064e \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627",45,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0632\u0651\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0627\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670",46,"\u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u0645\u0652\u0646\u064e\u0649\u0670",47,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0634\u0652\u0623\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",48,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0642\u0652\u0646\u064e\u0649\u0670",49,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0634\u0651\u0650\u0639\u0652\u0631\u064e\u0649\u0670",50,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0639\u064e\u0627\u062f\u064b\u0627 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",51,"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",52,"\u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064e \u0646\u064f\u0648\u062d\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064e \u0648\u064e\u0623\u064e\u0637\u0652\u063a\u064e\u0649\u0670",53,"\u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u062a\u064e\u0641\u0650\u0643\u064e\u0629\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0649\u0670",54,"\u0641\u064e\u063a\u064e\u0634\u0651\u064e\u0627\u0647\u064e\u0627 \u0645\u064e\u0627 \u063a\u064e\u0634\u0651\u064e\u0649\u0670",55,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062a\u064e\u062a\u064e\u0645\u064e\u0627\u0631\u064e\u0649\u0670",56,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",57,"\u0623\u064e\u0632\u0650\u0641\u064e\u062a\u0650 \u0627\u0644\u0652\u0622\u0632\u0650\u0641\u064e\u0629\u064f",58,"\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0627\u0634\u0650\u0641\u064e\u0629\u064c",59,"\u0623\u064e\u0641\u064e\u0645\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u062a\u064e\u0639\u0652\u062c\u064e\u0628\u064f\u0648\u0646\u064e",60,"\u0648\u064e\u062a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u0643\u064f\u0648\u0646\u064e",61,"\u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0633\u064e\u0627\u0645\u0650\u062f\u064f\u0648\u0646\u064e",62,"\u0641\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u06e9"],t.v)
B.aro=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0642\u0652\u062a\u064e\u0631\u064e\u0628\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0648\u064e\u0627\u0646\u0652\u0634\u064e\u0642\u0651\u064e \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f",2,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0622\u064a\u064e\u0629\u064b \u064a\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0645\u0650\u0631\u0651\u064c",3,"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0623\u064e\u0645\u0652\u0631\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u0631\u0651\u064c",4,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0628\u064e\u0627\u0621\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0632\u0652\u062f\u064e\u062c\u064e\u0631\u064c",5,"\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064c \u0628\u064e\u0627\u0644\u0650\u063a\u064e\u0629\u064c \u06d6 \u0641\u064e\u0645\u064e\u0627 \u062a\u064f\u063a\u0652\u0646\u0650 \u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f",6,"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u06d8 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062f\u0652\u0639\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0639\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0646\u064f\u0643\u064f\u0631\u064d",7,"\u062e\u064f\u0634\u0651\u064e\u0639\u064b\u0627 \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062c\u0652\u062f\u064e\u0627\u062b\u0650 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0631\u064e\u0627\u062f\u064c \u0645\u064f\u0646\u0652\u062a\u064e\u0634\u0650\u0631\u064c",8,"\u0645\u064f\u0647\u0652\u0637\u0650\u0639\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u062f\u0651\u064e\u0627\u0639\u0650 \u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064c \u0639\u064e\u0633\u0650\u0631\u064c",9,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0639\u064e\u0628\u0652\u062f\u064e\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c \u0648\u064e\u0627\u0632\u0652\u062f\u064f\u062c\u0650\u0631\u064e",10,"\u0641\u064e\u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u063a\u0652\u0644\u064f\u0648\u0628\u064c \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u0652",11,"\u0641\u064e\u0641\u064e\u062a\u064e\u062d\u0652\u0646\u064e\u0627 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0628\u0650\u0645\u064e\u0627\u0621\u064d \u0645\u064f\u0646\u0652\u0647\u064e\u0645\u0650\u0631\u064d",12,"\u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0639\u064f\u064a\u064f\u0648\u0646\u064b\u0627 \u0641\u064e\u0627\u0644\u0652\u062a\u064e\u0642\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0645\u0652\u0631\u064d \u0642\u064e\u062f\u0652 \u0642\u064f\u062f\u0650\u0631\u064e",13,"\u0648\u064e\u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0627\u062a\u0650 \u0623\u064e\u0644\u0652\u0648\u064e\u0627\u062d\u064d \u0648\u064e\u062f\u064f\u0633\u064f\u0631\u064d",14,"\u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0639\u0652\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0644\u0650\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0643\u064f\u0641\u0650\u0631\u064e",15,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0631\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0622\u064a\u064e\u0629\u064b \u0641\u064e\u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0645\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u064d",16,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",17,u.w,18,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0639\u064e\u0627\u062f\u064c \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",19,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u0650\u064a\u062d\u064b\u0627 \u0635\u064e\u0631\u0652\u0635\u064e\u0631\u064b\u0627 \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u0650 \u0646\u064e\u062d\u0652\u0633\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0645\u0650\u0631\u0651\u064d",20,"\u062a\u064e\u0646\u0652\u0632\u0650\u0639\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0627\u0632\u064f \u0646\u064e\u062e\u0652\u0644\u064d \u0645\u064f\u0646\u0652\u0642\u064e\u0639\u0650\u0631\u064d",21,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",22,u.w,23,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0628\u0650\u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",24,"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064b\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0647\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0648\u064e\u0633\u064f\u0639\u064f\u0631\u064d",25,"\u0623\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u0646\u064e\u0627 \u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c \u0623\u064e\u0634\u0650\u0631\u064c",26,"\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u063a\u064e\u062f\u064b\u0627 \u0645\u064e\u0646\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u0634\u0650\u0631\u064f",27,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u064f\u0648 \u0627\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u0650 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0631\u0652\u062a\u064e\u0642\u0650\u0628\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0635\u0652\u0637\u064e\u0628\u0650\u0631\u0652",28,"\u0648\u064e\u0646\u064e\u0628\u0651\u0650\u0626\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0642\u0650\u0633\u0652\u0645\u064e\u0629\u064c \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0643\u064f\u0644\u0651\u064f \u0634\u0650\u0631\u0652\u0628\u064d \u0645\u064f\u062d\u0652\u062a\u064e\u0636\u064e\u0631\u064c",29,"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0637\u064e\u0649\u0670 \u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064e",30,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",31,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0643\u064e\u0647\u064e\u0634\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u062a\u064e\u0638\u0650\u0631\u0650",32,u.w,33,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0628\u0650\u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",34,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0622\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u06d6 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u064e\u062d\u064e\u0631\u064d",35,"\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u0650\u0646\u064e\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0645\u064e\u0646\u0652 \u0634\u064e\u0643\u064e\u0631\u064e",36,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0630\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0628\u064e\u0637\u0652\u0634\u064e\u062a\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u0645\u064e\u0627\u0631\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",37,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0627\u0648\u064e\u062f\u064f\u0648\u0647\u064f \u0639\u064e\u0646\u0652 \u0636\u064e\u064a\u0652\u0641\u0650\u0647\u0650 \u0641\u064e\u0637\u064e\u0645\u064e\u0633\u0652\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u064a\u064f\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",38,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u0628\u0651\u064e\u062d\u064e\u0647\u064f\u0645\u0652 \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u0631\u0651\u064c",39,"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",40,u.w,41,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e \u0622\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0627\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f",42,"\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u0650\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u0652\u0630\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064d \u0645\u064f\u0642\u0652\u062a\u064e\u062f\u0650\u0631\u064d",43,"\u0623\u064e\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0628\u064e\u0631\u064e\u0627\u0621\u064e\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650",44,"\u0623\u064e\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u0652\u0646\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064c \u0645\u064f\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064c",45,"\u0633\u064e\u064a\u064f\u0647\u0652\u0632\u064e\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064f \u0648\u064e\u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u062f\u0651\u064f\u0628\u064f\u0631\u064e",46,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0645\u064e\u0648\u0652\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u062f\u0652\u0647\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0645\u064e\u0631\u0651\u064f",47,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0648\u064e\u0633\u064f\u0639\u064f\u0631\u064d",48,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0633\u0652\u062d\u064e\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 \u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0645\u064e\u0633\u0651\u064e \u0633\u064e\u0642\u064e\u0631\u064e",49,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d",50,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064c \u0643\u064e\u0644\u064e\u0645\u0652\u062d\u064d \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u0650",51,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0639\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0647\u064e\u0644\u0652 \u0645\u0650\u0646\u0652 \u0645\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u064d",52,"\u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650",53,"\u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u064d \u0648\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0637\u064e\u0631\u064c",54,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0646\u064e\u0647\u064e\u0631\u064d",55,"\u0641\u0650\u064a \u0645\u064e\u0642\u0652\u0639\u064e\u062f\u0650 \u0635\u0650\u062f\u0652\u0642\u064d \u0639\u0650\u0646\u0652\u062f\u064e \u0645\u064e\u0644\u0650\u064a\u0643\u064d \u0645\u064f\u0642\u0652\u062a\u064e\u062f\u0650\u0631\u064d"],t.v)
B.aoV=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f",2,"\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e",3,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e",4,"\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u064e\u0627\u0646\u064e",5,"\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f \u0628\u0650\u062d\u064f\u0633\u0652\u0628\u064e\u0627\u0646\u064d",6,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0645\u064f \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064f \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064e\u0627\u0646\u0650",7,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0631\u064e\u0641\u064e\u0639\u064e\u0647\u064e\u0627 \u0648\u064e\u0648\u064e\u0636\u064e\u0639\u064e \u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e",8,"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0637\u0652\u063a\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u0650",9,"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0648\u064e\u0632\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0633\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e",10,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0648\u064e\u0636\u064e\u0639\u064e\u0647\u064e\u0627 \u0644\u0650\u0644\u0652\u0623\u064e\u0646\u064e\u0627\u0645\u0650",11,"\u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064c \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062e\u0652\u0644\u064f \u0630\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0645\u064e\u0627\u0645\u0650",12,"\u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0628\u0651\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0635\u0652\u0641\u0650 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u064a\u0652\u062d\u064e\u0627\u0646\u064f",13,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",14,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0635\u064e\u0644\u0652\u0635\u064e\u0627\u0644\u064d \u0643\u064e\u0627\u0644\u0652\u0641\u064e\u062e\u0651\u064e\u0627\u0631\u0650",15,"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u062c\u064e\u0627\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0631\u0650\u062c\u064d \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d",16,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",17,"\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u064e\u064a\u0652\u0646\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u064e\u064a\u0652\u0646\u0650",18,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",19,"\u0645\u064e\u0631\u064e\u062c\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u0644\u0652\u062a\u064e\u0642\u0650\u064a\u064e\u0627\u0646\u0650",20,"\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0631\u0652\u0632\u064e\u062e\u064c \u0644\u064e\u0627 \u064a\u064e\u0628\u0652\u063a\u0650\u064a\u064e\u0627\u0646\u0650",21,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",22,"\u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0644\u0651\u064f\u0624\u0652\u0644\u064f\u0624\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0631\u0652\u062c\u064e\u0627\u0646\u064f",23,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",24,"\u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0634\u064e\u0622\u062a\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0643\u064e\u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0627\u0645\u0650",25,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",26,"\u0643\u064f\u0644\u0651\u064f \u0645\u064e\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0641\u064e\u0627\u0646\u064d",27,"\u0648\u064e\u064a\u064e\u0628\u0652\u0642\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0630\u064f\u0648 \u0627\u0644\u0652\u062c\u064e\u0644\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650",28,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",29,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0647\u064f \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0643\u064f\u0644\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0634\u064e\u0623\u0652\u0646\u064d",30,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",31,"\u0633\u064e\u0646\u064e\u0641\u0652\u0631\u064f\u063a\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0627\u0644\u062b\u0651\u064e\u0642\u064e\u0644\u064e\u0627\u0646\u0650",32,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",33,"\u064a\u064e\u0627 \u0645\u064e\u0639\u0652\u0634\u064e\u0631\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0637\u064e\u0627\u0631\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0627\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0627 \u06da \u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064f\u0630\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064d",34,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",35,"\u064a\u064f\u0631\u0652\u0633\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064e\u0627 \u0634\u064f\u0648\u064e\u0627\u0638\u064c \u0645\u0650\u0646\u0652 \u0646\u064e\u0627\u0631\u064d \u0648\u064e\u0646\u064f\u062d\u064e\u0627\u0633\u064c \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062a\u064e\u0635\u0650\u0631\u064e\u0627\u0646\u0650",36,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",37,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0634\u064e\u0642\u0651\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0648\u064e\u0631\u0652\u062f\u064e\u0629\u064b \u0643\u064e\u0627\u0644\u062f\u0651\u0650\u0647\u064e\u0627\u0646\u0650",38,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",39,"\u0641\u064e\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646\u0652 \u0630\u064e\u0646\u0652\u0628\u0650\u0647\u0650 \u0625\u0650\u0646\u0652\u0633\u064c \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c",40,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",41,"\u064a\u064f\u0639\u0652\u0631\u064e\u0641\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u064e\u064a\u064f\u0624\u0652\u062e\u064e\u0630\u064f \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0648\u064e\u0627\u0635\u0650\u064a \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0642\u0652\u062f\u064e\u0627\u0645\u0650",42,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",43,"\u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",44,"\u064a\u064e\u0637\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u062d\u064e\u0645\u0650\u064a\u0645\u064d \u0622\u0646\u064d",45,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",46,"\u0648\u064e\u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650",47,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",48,"\u0630\u064e\u0648\u064e\u0627\u062a\u064e\u0627 \u0623\u064e\u0641\u0652\u0646\u064e\u0627\u0646\u064d",49,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",50,"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0639\u064e\u064a\u0652\u0646\u064e\u0627\u0646\u0650 \u062a\u064e\u062c\u0652\u0631\u0650\u064a\u064e\u0627\u0646\u0650",51,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",52,"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0632\u064e\u0648\u0652\u062c\u064e\u0627\u0646\u0650",53,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",54,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0641\u064f\u0631\u064f\u0634\u064d \u0628\u064e\u0637\u064e\u0627\u0626\u0650\u0646\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0625\u0650\u0633\u0652\u062a\u064e\u0628\u0652\u0631\u064e\u0642\u064d \u06da \u0648\u064e\u062c\u064e\u0646\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u062f\u064e\u0627\u0646\u064d",55,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",56,"\u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0642\u064e\u0627\u0635\u0650\u0631\u064e\u0627\u062a\u064f \u0627\u0644\u0637\u0651\u064e\u0631\u0652\u0641\u0650 \u0644\u064e\u0645\u0652 \u064a\u064e\u0637\u0652\u0645\u0650\u062b\u0652\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0652\u0633\u064c \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c",57,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",58,"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u064a\u064e\u0627\u0642\u064f\u0648\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0631\u0652\u062c\u064e\u0627\u0646\u064f",59,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",60,"\u0647\u064e\u0644\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064f",61,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",62,"\u0648\u064e\u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650",63,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",64,"\u0645\u064f\u062f\u0652\u0647\u064e\u0627\u0645\u0651\u064e\u062a\u064e\u0627\u0646\u0650",65,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",66,"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0639\u064e\u064a\u0652\u0646\u064e\u0627\u0646\u0650 \u0646\u064e\u0636\u0651\u064e\u0627\u062e\u064e\u062a\u064e\u0627\u0646\u0650",67,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",68,"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064c \u0648\u064e\u0646\u064e\u062e\u0652\u0644\u064c \u0648\u064e\u0631\u064f\u0645\u0651\u064e\u0627\u0646\u064c",69,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",70,"\u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064e\u0627\u062a\u064c \u062d\u0650\u0633\u064e\u0627\u0646\u064c",71,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",72,"\u062d\u064f\u0648\u0631\u064c \u0645\u064e\u0642\u0652\u0635\u064f\u0648\u0631\u064e\u0627\u062a\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u062e\u0650\u064a\u064e\u0627\u0645\u0650",73,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",74,"\u0644\u064e\u0645\u0652 \u064a\u064e\u0637\u0652\u0645\u0650\u062b\u0652\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0652\u0633\u064c \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c",75,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",76,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0641\u0652\u0631\u064e\u0641\u064d \u062e\u064f\u0636\u0652\u0631\u064d \u0648\u064e\u0639\u064e\u0628\u0652\u0642\u064e\u0631\u0650\u064a\u0651\u064d \u062d\u0650\u0633\u064e\u0627\u0646\u064d",77,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0622\u0644\u064e\u0627\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",78,"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0633\u0652\u0645\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0630\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0644\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650"],t.v)
B.ac1=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e\u062a\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u0642\u0650\u0639\u064e\u0629\u064f",2,"\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u0650\u0648\u064e\u0642\u0652\u0639\u064e\u062a\u0650\u0647\u064e\u0627 \u0643\u064e\u0627\u0630\u0650\u0628\u064e\u0629\u064c",3,"\u062e\u064e\u0627\u0641\u0650\u0636\u064e\u0629\u064c \u0631\u064e\u0627\u0641\u0650\u0639\u064e\u0629\u064c",4,"\u0625\u0650\u0630\u064e\u0627 \u0631\u064f\u062c\u0651\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0631\u064e\u062c\u0651\u064b\u0627",5,"\u0648\u064e\u0628\u064f\u0633\u0651\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0628\u064e\u0633\u0651\u064b\u0627",6,"\u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0647\u064e\u0628\u064e\u0627\u0621\u064b \u0645\u064f\u0646\u0652\u0628\u064e\u062b\u0651\u064b\u0627",7,"\u0648\u064e\u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064b",8,"\u0641\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0645\u064e\u0646\u064e\u0629\u0650 \u0645\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0645\u064e\u0646\u064e\u0629\u0650",9,"\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0623\u064e\u0645\u064e\u0629\u0650 \u0645\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0623\u064e\u0645\u064e\u0629\u0650",10,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0646\u064e",11,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",12,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",13,"\u062b\u064f\u0644\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",14,"\u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",15,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u064d \u0645\u064e\u0648\u0652\u0636\u064f\u0648\u0646\u064e\u0629\u064d",16,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u064f\u062a\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650\u064a\u0646\u064e",17,"\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u064c \u0645\u064f\u062e\u064e\u0644\u0651\u064e\u062f\u064f\u0648\u0646\u064e",18,"\u0628\u0650\u0623\u064e\u0643\u0652\u0648\u064e\u0627\u0628\u064d \u0648\u064e\u0623\u064e\u0628\u064e\u0627\u0631\u0650\u064a\u0642\u064e \u0648\u064e\u0643\u064e\u0623\u0652\u0633\u064d \u0645\u0650\u0646\u0652 \u0645\u064e\u0639\u0650\u064a\u0646\u064d",19,"\u0644\u064e\u0627 \u064a\u064f\u0635\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0632\u0650\u0641\u064f\u0648\u0646\u064e",20,"\u0648\u064e\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u064e\u062e\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0644\u064e\u062d\u0652\u0645\u0650 \u0637\u064e\u064a\u0652\u0631\u064d \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",22,"\u0648\u064e\u062d\u064f\u0648\u0631\u064c \u0639\u0650\u064a\u0646\u064c",23,"\u0643\u064e\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u0650 \u0627\u0644\u0644\u0651\u064f\u0624\u0652\u0644\u064f\u0624\u0650 \u0627\u0644\u0652\u0645\u064e\u0643\u0652\u0646\u064f\u0648\u0646\u0650",24,"\u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",25,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u0652\u0648\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062b\u0650\u064a\u0645\u064b\u0627",26,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u0650\u064a\u0644\u064b\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627 \u0633\u064e\u0644\u064e\u0627\u0645\u064b\u0627",27,"\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0645\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",28,"\u0641\u0650\u064a \u0633\u0650\u062f\u0652\u0631\u064d \u0645\u064e\u062e\u0652\u0636\u064f\u0648\u062f\u064d",29,"\u0648\u064e\u0637\u064e\u0644\u0652\u062d\u064d \u0645\u064e\u0646\u0652\u0636\u064f\u0648\u062f\u064d",30,"\u0648\u064e\u0638\u0650\u0644\u0651\u064d \u0645\u064e\u0645\u0652\u062f\u064f\u0648\u062f\u064d",31,"\u0648\u064e\u0645\u064e\u0627\u0621\u064d \u0645\u064e\u0633\u0652\u0643\u064f\u0648\u0628\u064d",32,"\u0648\u064e\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064d \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064d",33,"\u0644\u064e\u0627 \u0645\u064e\u0642\u0652\u0637\u064f\u0648\u0639\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0645\u0652\u0646\u064f\u0648\u0639\u064e\u0629\u064d",34,"\u0648\u064e\u0641\u064f\u0631\u064f\u0634\u064d \u0645\u064e\u0631\u0652\u0641\u064f\u0648\u0639\u064e\u0629\u064d",35,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u0646\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0652\u0634\u064e\u0627\u0621\u064b",36,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0628\u0652\u0643\u064e\u0627\u0631\u064b\u0627",37,"\u0639\u064f\u0631\u064f\u0628\u064b\u0627 \u0623\u064e\u062a\u0652\u0631\u064e\u0627\u0628\u064b\u0627",38,"\u0644\u0650\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",39,"\u062b\u064f\u0644\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",40,"\u0648\u064e\u062b\u064f\u0644\u0651\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",41,"\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0645\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650",42,"\u0641\u0650\u064a \u0633\u064e\u0645\u064f\u0648\u0645\u064d \u0648\u064e\u062d\u064e\u0645\u0650\u064a\u0645\u064d",43,"\u0648\u064e\u0638\u0650\u0644\u0651\u064d \u0645\u0650\u0646\u0652 \u064a\u064e\u062d\u0652\u0645\u064f\u0648\u0645\u064d",44,"\u0644\u064e\u0627 \u0628\u064e\u0627\u0631\u0650\u062f\u064d \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064d",45,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0628\u0652\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064f\u062a\u0652\u0631\u064e\u0641\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0635\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062d\u0650\u0646\u0652\u062b\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",47,"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0626\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0652\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",48,"\u0623\u064e\u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",49,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",50,"\u0644\u064e\u0645\u064e\u062c\u0652\u0645\u064f\u0648\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u0650\u064a\u0642\u064e\u0627\u062a\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",51,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",52,"\u0644\u064e\u0622\u0643\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u062c\u064e\u0631\u064d \u0645\u0650\u0646\u0652 \u0632\u064e\u0642\u0651\u064f\u0648\u0645\u064d",53,"\u0641\u064e\u0645\u064e\u0627\u0644\u0650\u0626\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0628\u064f\u0637\u064f\u0648\u0646\u064e",54,"\u0641\u064e\u0634\u064e\u0627\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u0650",55,"\u0641\u064e\u0634\u064e\u0627\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0634\u064f\u0631\u0652\u0628\u064e \u0627\u0644\u0652\u0647\u0650\u064a\u0645\u0650",56,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0646\u064f\u0632\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",57,"\u0646\u064e\u062d\u0652\u0646\u064f \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0648\u0646\u064e",58,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064f\u0645\u0652\u0646\u064f\u0648\u0646\u064e",59,"\u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0646\u064e\u0647\u064f \u0623\u064e\u0645\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u064f\u0648\u0646\u064e",60,"\u0646\u064e\u062d\u0652\u0646\u064f \u0642\u064e\u062f\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064e\u0633\u0652\u0628\u064f\u0648\u0642\u0650\u064a\u0646\u064e",61,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0646\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0646\u064f\u0646\u0652\u0634\u0650\u0626\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",62,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0634\u0652\u0623\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",63,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0631\u064f\u062b\u064f\u0648\u0646\u064e",64,"\u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0632\u0652\u0631\u064e\u0639\u064f\u0648\u0646\u064e\u0647\u064f \u0623\u064e\u0645\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0632\u0651\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0646\u064e",65,"\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0637\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0638\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0647\u064f\u0648\u0646\u064e",66,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u063a\u0652\u0631\u064e\u0645\u064f\u0648\u0646\u064e",67,"\u0628\u064e\u0644\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064e\u062d\u0652\u0631\u064f\u0648\u0645\u064f\u0648\u0646\u064e",68,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e",69,"\u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0632\u0652\u0646\u0650 \u0623\u064e\u0645\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0632\u0650\u0644\u064f\u0648\u0646\u064e",70,"\u0644\u064e\u0648\u0652 \u0646\u064e\u0634\u064e\u0627\u0621\u064f \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064f\u062c\u064e\u0627\u062c\u064b\u0627 \u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",71,"\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0648\u0631\u064f\u0648\u0646\u064e",72,"\u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u0652\u062a\u064f\u0645\u0652 \u0634\u064e\u062c\u064e\u0631\u064e\u062a\u064e\u0647\u064e\u0627 \u0623\u064e\u0645\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0634\u0650\u0626\u064f\u0648\u0646\u064e",73,"\u0646\u064e\u062d\u0652\u0646\u064f \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0644\u0650\u0644\u0652\u0645\u064f\u0642\u0652\u0648\u0650\u064a\u0646\u064e",74,"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u0627\u0633\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",75,"\u0641\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0645\u064e\u0648\u064e\u0627\u0642\u0650\u0639\u0650 \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650",76,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0642\u064e\u0633\u064e\u0645\u064c \u0644\u064e\u0648\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u064c",77,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",78,"\u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u064e\u0643\u0652\u0646\u064f\u0648\u0646\u064d",79,"\u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",80,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",81,"\u0623\u064e\u0641\u064e\u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u062f\u0652\u0647\u0650\u0646\u064f\u0648\u0646\u064e",82,"\u0648\u064e\u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0631\u0650\u0632\u0652\u0642\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",83,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0627\u0644\u0652\u062d\u064f\u0644\u0652\u0642\u064f\u0648\u0645\u064e",84,"\u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u062d\u0650\u064a\u0646\u064e\u0626\u0650\u0630\u064d \u062a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",85,"\u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",86,"\u0641\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u062f\u0650\u064a\u0646\u0650\u064a\u0646\u064e",87,"\u062a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",88,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",89,"\u0641\u064e\u0631\u064e\u0648\u0652\u062d\u064c \u0648\u064e\u0631\u064e\u064a\u0652\u062d\u064e\u0627\u0646\u064c \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u062a\u064f \u0646\u064e\u0639\u0650\u064a\u0645\u064d",90,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",91,"\u0641\u064e\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",92,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",93,"\u0641\u064e\u0646\u064f\u0632\u064f\u0644\u064c \u0645\u0650\u0646\u0652 \u062d\u064e\u0645\u0650\u064a\u0645\u064d",94,"\u0648\u064e\u062a\u064e\u0635\u0652\u0644\u0650\u064a\u064e\u0629\u064f \u062c\u064e\u062d\u0650\u064a\u0645\u064d",95,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0642\u0651\u064f \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u0650",96,"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u0627\u0633\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650"],t.v)
B.aoN=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0633\u064e\u0628\u0651\u064e\u062d\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",2,"\u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",3,"\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064f \u0648\u064e\u0627\u0644\u0638\u0651\u064e\u0627\u0647\u0650\u0631\u064f \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0646\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",4,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062b\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u0644\u0650\u062c\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0632\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u064f\u062c\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",5,"\u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",6,"\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",7,"\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u062e\u0652\u0644\u064e\u0641\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",8,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0648\u064e\u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064f\u0645\u0652 \u0644\u0650\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u064a\u062b\u064e\u0627\u0642\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",9,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0647\u0650 \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0644\u0650\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",10,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u064a\u0631\u064e\u0627\u062b\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0627\u0644\u0652\u0641\u064e\u062a\u0652\u062d\u0650 \u0648\u064e\u0642\u064e\u0627\u062a\u064e\u0644\u064e \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0639\u0652\u0638\u064e\u0645\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u064f \u0648\u064e\u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0627 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",11,"\u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0642\u0652\u0631\u0650\u0636\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0641\u064e\u064a\u064f\u0636\u064e\u0627\u0639\u0650\u0641\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",12,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0628\u0650\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0628\u064f\u0634\u0652\u0631\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",13,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e\u0627 \u0646\u064e\u0642\u0652\u062a\u064e\u0628\u0650\u0633\u0652 \u0645\u0650\u0646\u0652 \u0646\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u0652 \u0642\u0650\u064a\u0644\u064e \u0627\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0627 \u0648\u064e\u0631\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0644\u0652\u062a\u064e\u0645\u0650\u0633\u064f\u0648\u0627 \u0646\u064f\u0648\u0631\u064b\u0627 \u0641\u064e\u0636\u064f\u0631\u0650\u0628\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0648\u0631\u064d \u0644\u064e\u0647\u064f \u0628\u064e\u0627\u0628\u064c \u0628\u064e\u0627\u0637\u0650\u0646\u064f\u0647\u064f \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u064f \u0648\u064e\u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u0650\u0628\u064e\u0644\u0650\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f",14,"\u064a\u064f\u0646\u064e\u0627\u062f\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0643\u064f\u0646\u0652 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062a\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0627\u0631\u0652\u062a\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u063a\u064e\u0631\u064f\u0648\u0631\u064f",15,"\u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062e\u064e\u0630\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u062f\u0652\u064a\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06da \u0645\u064e\u0623\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u06d6 \u0647\u0650\u064a\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",16,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u0646\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u062e\u0652\u0634\u064e\u0639\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u062f\u064f \u0641\u064e\u0642\u064e\u0633\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",17,"\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0648\u0652\u062a\u0650\u0647\u064e\u0627 \u06da \u0642\u064e\u062f\u0652 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",18,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0651\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0635\u0651\u064e\u062f\u0651\u0650\u0642\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u0642\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u064a\u064f\u0636\u064e\u0627\u0639\u064e\u0641\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",19,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u064f\u0648\u0646\u064e \u06d6 \u0648\u064e\u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",20,"\u0627\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u064c \u0648\u064e\u0644\u064e\u0647\u0652\u0648\u064c \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u0629\u064c \u0648\u064e\u062a\u064e\u0641\u064e\u0627\u062e\u064f\u0631\u064c \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0643\u064e\u0627\u062b\u064f\u0631\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u0650 \u06d6 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u063a\u064e\u064a\u0652\u062b\u064d \u0623\u064e\u0639\u0652\u062c\u064e\u0628\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0646\u064e\u0628\u064e\u0627\u062a\u064f\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0647\u0650\u064a\u062c\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0645\u064f\u0635\u0652\u0641\u064e\u0631\u0651\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u062d\u064f\u0637\u064e\u0627\u0645\u064b\u0627 \u06d6 \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064c \u06da \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u063a\u064f\u0631\u064f\u0648\u0631\u0650",21,"\u0633\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0631\u0652\u0636\u064f\u0647\u064e\u0627 \u0643\u064e\u0639\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",22,"\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u0646\u064e\u0628\u0652\u0631\u064e\u0623\u064e\u0647\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",23,"\u0644\u0650\u0643\u064e\u064a\u0652\u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u0633\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0631\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u062e\u0652\u062a\u064e\u0627\u0644\u064d \u0641\u064e\u062e\u064f\u0648\u0631\u064d",24,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0652\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",25,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u0650 \u06d6 \u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062f\u064e \u0641\u0650\u064a\u0647\u0650 \u0628\u064e\u0623\u0652\u0633\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u0648\u064e\u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0647\u064f \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",26,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0648\u064e\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u06d6 \u0641\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u064d \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",27,"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0641\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0622\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u0650\u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u0650 \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u062c\u0650\u064a\u0644\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0631\u064e\u0623\u0652\u0641\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u0647\u0652\u0628\u064e\u0627\u0646\u0650\u064a\u0651\u064e\u0629\u064b \u0627\u0628\u0652\u062a\u064e\u062f\u064e\u0639\u064f\u0648\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0645\u064e\u0627 \u0631\u064e\u0639\u064e\u0648\u0652\u0647\u064e\u0627 \u062d\u064e\u0642\u0651\u064e \u0631\u0650\u0639\u064e\u0627\u064a\u064e\u062a\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",28,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0643\u0650\u0641\u0652\u0644\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064f\u0648\u0631\u064b\u0627 \u062a\u064e\u0645\u0652\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",29,"\u0644\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064e \u0628\u0650\u064a\u064e\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650"],t.v)
B.arr=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0642\u064e\u062f\u0652 \u0633\u064e\u0645\u0650\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0643\u064e \u0641\u0650\u064a \u0632\u064e\u0648\u0652\u062c\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0634\u0652\u062a\u064e\u0643\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u062a\u064e\u062d\u064e\u0627\u0648\u064f\u0631\u064e\u0643\u064f\u0645\u064e\u0627 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0627\u0626\u0650\u064a \u0648\u064e\u0644\u064e\u062f\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u0632\u064f\u0648\u0631\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0641\u064f\u0648\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",3,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0641\u064e\u062a\u064e\u062d\u0652\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0645\u064e\u0627\u0633\u0651\u064e\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062a\u064f\u0648\u0639\u064e\u0638\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",4,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u0634\u064e\u0647\u0652\u0631\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u062a\u064e\u062a\u064e\u0627\u0628\u0650\u0639\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0645\u064e\u0627\u0633\u0651\u064e\u0627 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u0639\u0652 \u0641\u064e\u0625\u0650\u0637\u0652\u0639\u064e\u0627\u0645\u064f \u0633\u0650\u062a\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u06da \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",5,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u062f\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0643\u064f\u0628\u0650\u062a\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u0627 \u0643\u064f\u0628\u0650\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",6,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u06da \u0623\u064e\u062d\u0652\u0635\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",7,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u0652 \u0646\u064e\u062c\u0652\u0648\u064e\u0649\u0670 \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0627\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0645\u0652\u0633\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0633\u064e\u0627\u062f\u0650\u0633\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",8,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064f\u0647\u064f\u0648\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0648\u064e\u0649\u0670 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u064a\u064e\u062a\u064e\u0646\u064e\u0627\u062c\u064e\u0648\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u0650 \u0648\u064e\u0645\u064e\u0639\u0652\u0635\u0650\u064a\u064e\u062a\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064f\u0648\u0643\u064e \u062d\u064e\u064a\u0651\u064e\u0648\u0652\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u062d\u064e\u064a\u0651\u0650\u0643\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u06da \u062d\u064e\u0633\u0652\u0628\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",9,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u062c\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0646\u064e\u0627\u062c\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u0650 \u0648\u064e\u0645\u064e\u0639\u0652\u0635\u0650\u064a\u064e\u062a\u0650 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u062a\u064e\u0646\u064e\u0627\u062c\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",10,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0644\u0650\u064a\u064e\u062d\u0652\u0632\u064f\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0636\u064e\u0627\u0631\u0651\u0650\u0647\u0650\u0645\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",11,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0641\u064e\u0633\u0651\u064e\u062d\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062c\u064e\u0627\u0644\u0650\u0633\u0650 \u0641\u064e\u0627\u0641\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0633\u064e\u062d\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0627\u0646\u0652\u0634\u064f\u0632\u064f\u0648\u0627 \u0641\u064e\u0627\u0646\u0652\u0634\u064f\u0632\u064f\u0648\u0627 \u064a\u064e\u0631\u0652\u0641\u064e\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",12,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0627\u062c\u064e\u064a\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0646\u064e\u062c\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0637\u0652\u0647\u064e\u0631\u064f \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",13,"\u0623\u064e\u0623\u064e\u0634\u0652\u0641\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652 \u0646\u064e\u062c\u0652\u0648\u064e\u0627\u0643\u064f\u0645\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0627\u062a\u064d \u06da \u0641\u064e\u0625\u0650\u0630\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",14,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u063a\u064e\u0636\u0650\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",15,"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",16,"\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u062c\u064f\u0646\u0651\u064e\u0629\u064b \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u064f\u0647\u0650\u064a\u0646\u064c",17,"\u0644\u064e\u0646\u0652 \u062a\u064f\u063a\u0652\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e",18,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0641\u064e\u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u062d\u0652\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u0652\u0621\u064d \u06da \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",19,"\u0627\u0633\u0652\u062a\u064e\u062d\u0652\u0648\u064e\u0630\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u064e\u0623\u064e\u0646\u0652\u0633\u064e\u0627\u0647\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062d\u0650\u0632\u0652\u0628\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06da \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u0652\u0628\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",20,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u062f\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0630\u064e\u0644\u0651\u0650\u064a\u0646\u064e",21,"\u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u063a\u0652\u0644\u0650\u0628\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u064e\u0627 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u064a \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",22,"\u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u064a\u064f\u0648\u064e\u0627\u062f\u0651\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u062d\u064e\u0627\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0643\u064e\u062a\u064e\u0628\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0631\u064f\u0648\u062d\u064d \u0645\u0650\u0646\u0652\u0647\u064f \u06d6 \u0648\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062d\u0650\u0632\u0652\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0623\u064e\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u0652\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e"],t.v)
B.aoK=new A.U([1,u.Y,2,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0644\u0650\u0623\u064e\u0648\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u062d\u064e\u0634\u0652\u0631\u0650 \u06da \u0645\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0627\u0646\u0650\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u062d\u064f\u0635\u064f\u0648\u0646\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u062a\u064e\u0633\u0650\u0628\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0642\u064e\u0630\u064e\u0641\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0631\u0651\u064f\u0639\u0652\u0628\u064e \u06da \u064a\u064f\u062e\u0652\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u064a\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u064e\u0627\u0639\u0652\u062a\u064e\u0628\u0650\u0631\u064f\u0648\u0627 \u064a\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650",3,"\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0644\u064e\u0627\u0621\u064e \u0644\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",4,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u0627\u0642\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u064e\u0627\u0642\u0651\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",5,"\u0645\u064e\u0627 \u0642\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0644\u0650\u064a\u0646\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u062a\u064e\u0631\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064f\u0635\u064f\u0648\u0644\u0650\u0647\u064e\u0627 \u0641\u064e\u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u062e\u0652\u0632\u0650\u064a\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",6,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0641\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0645\u064e\u0627 \u0623\u064e\u0648\u0652\u062c\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0644\u064d \u0648\u064e\u0644\u064e\u0627 \u0631\u0650\u0643\u064e\u0627\u0628\u064d \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u064e\u0644\u0651\u0650\u0637\u064f \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",7,"\u0645\u064e\u0627 \u0623\u064e\u0641\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0644\u0650\u0630\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u062a\u064e\u0627\u0645\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0628\u0652\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0643\u064e\u064a\u0652 \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u062f\u064f\u0648\u0644\u064e\u0629\u064b \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u063a\u0652\u0646\u0650\u064a\u064e\u0627\u0621\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0647\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0639\u0650\u0642\u064e\u0627\u0628\u0650",8,"\u0644\u0650\u0644\u0652\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0621\u0650 \u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u0652\u0644\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u0652\u0648\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u064f\u0648\u0646\u064e",9,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0621\u064f\u0648\u0627 \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u0647\u064e\u0627\u062c\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u0627\u062c\u064e\u0629\u064b \u0645\u0650\u0645\u0651\u064e\u0627 \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0648\u064e\u064a\u064f\u0624\u0652\u062b\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u062e\u064e\u0635\u064e\u0627\u0635\u064e\u0629\u064c \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0648\u0642\u064e \u0634\u064f\u062d\u0651\u064e \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0621\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0646\u064e\u0627 \u063a\u0650\u0644\u0651\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",11,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0641\u064e\u0642\u064f\u0648\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0625\u0650\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0646\u064e\u062e\u0652\u0631\u064f\u062c\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0637\u0650\u064a\u0639\u064f \u0641\u0650\u064a\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0642\u064f\u0648\u062a\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0646\u064e\u0646\u0652\u0635\u064f\u0631\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",12,"\u0644\u064e\u0626\u0650\u0646\u0652 \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0642\u064f\u0648\u062a\u0650\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0647\u064f\u0645\u0652 \u0644\u064e\u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u062f\u0652\u0628\u064e\u0627\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0652\u0635\u064e\u0631\u064f\u0648\u0646\u064e",13,"\u0644\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0631\u064e\u0647\u0652\u0628\u064e\u0629\u064b \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",14,"\u0644\u064e\u0627 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0631\u064b\u0649 \u0645\u064f\u062d\u064e\u0635\u0651\u064e\u0646\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u062c\u064f\u062f\u064f\u0631\u064d \u06da \u0628\u064e\u0623\u0652\u0633\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u06da \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u062a\u0651\u064e\u0649\u0670 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",15,"\u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627 \u06d6 \u0630\u064e\u0627\u0642\u064f\u0648\u0627 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",16,"\u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u0627\u0643\u0652\u0641\u064f\u0631\u0652 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064e \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0650\u0646\u0652\u0643\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",17,"\u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u062a\u064e\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0621\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",18,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u0652\u062a\u064e\u0646\u0652\u0638\u064f\u0631\u0652 \u0646\u064e\u0641\u0652\u0633\u064c \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0644\u0650\u063a\u064e\u062f\u064d \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",19,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0623\u064e\u0646\u0652\u0633\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u0652 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u064f\u0648\u0646\u064e",20,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0650\u064a \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u06da \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0627\u0626\u0650\u0632\u064f\u0648\u0646\u064e",21,"\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064e\u0628\u064e\u0644\u064d \u0644\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f \u062e\u064e\u0627\u0634\u0650\u0639\u064b\u0627 \u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0639\u064b\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064f \u0646\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",22,"\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u06d6 \u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",23,"\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u0642\u064f\u062f\u0651\u064f\u0648\u0633\u064f \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0647\u064e\u064a\u0652\u0645\u0650\u0646\u064f \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u064f \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",24,"\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0631\u0650\u0626\u064f \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0648\u0651\u0650\u0631\u064f \u06d6 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0633\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670 \u06da \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f"],t.v)
B.apb=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u062a\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u06d9 \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064f\u0645\u0652 \u062c\u0650\u0647\u064e\u0627\u062f\u064b\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0648\u064e\u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u0650\u064a \u06da \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0641\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652\u0647\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",2,"\u0625\u0650\u0646\u0652 \u064a\u064e\u062b\u0652\u0642\u064e\u0641\u064f\u0648\u0643\u064f\u0645\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621\u064b \u0648\u064e\u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0633\u0651\u064f\u0648\u0621\u0650 \u0648\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e",3,"\u0644\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0631\u0652\u062d\u064e\u0627\u0645\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0643\u064f\u0645\u0652 \u06da \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u064a\u064e\u0641\u0652\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",4,"\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064f\u0633\u0652\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u0641\u0650\u064a \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u064f\u0631\u064e\u0622\u0621\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0641\u064e\u0631\u0652\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u063a\u0652\u0636\u064e\u0627\u0621\u064f \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0644\u064e\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u06d6 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0646\u064e\u0628\u0652\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",5,"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",6,"\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650\u0645\u0652 \u0623\u064f\u0633\u0652\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u0644\u0650\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u0652\u062c\u064f\u0648 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",7,"\u0639\u064e\u0633\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u062f\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064b \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u062f\u0650\u064a\u0631\u064c \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",8,"\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0647\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0652 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u0648\u0647\u064f\u0645\u0652 \u0648\u064e\u062a\u064f\u0642\u0652\u0633\u0650\u0637\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0642\u0652\u0633\u0650\u0637\u0650\u064a\u0646\u064e",9,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0647\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064f\u0648\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0638\u064e\u0627\u0647\u064e\u0631\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",10,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064f \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064e\u0627\u062a\u064d \u0641\u064e\u0627\u0645\u0652\u062a\u064e\u062d\u0650\u0646\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u06d6 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064d \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0644\u064e\u0627 \u0647\u064f\u0646\u0651\u064e \u062d\u0650\u0644\u0651\u064c \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u06d6 \u0648\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0645\u0652 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0639\u0650\u0635\u064e\u0645\u0650 \u0627\u0644\u0652\u0643\u064e\u0648\u064e\u0627\u0641\u0650\u0631\u0650 \u0648\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062d\u064f\u0643\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",11,"\u0648\u064e\u0625\u0650\u0646\u0652 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u064a\u0652\u0621\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0639\u064e\u0627\u0642\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0630\u064e\u0647\u064e\u0628\u064e\u062a\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064e\u0642\u064f\u0648\u0627 \u06da \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",12,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064f \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u0652\u0646\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0631\u0650\u0642\u0652\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0652\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u0652\u0646\u064e \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0628\u064f\u0647\u0652\u062a\u064e\u0627\u0646\u064d \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u0650\u064a\u0646\u064e\u0647\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0635\u0650\u064a\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u06d9 \u0641\u064e\u0628\u064e\u0627\u064a\u0650\u0639\u0652\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",13,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u063a\u064e\u0636\u0650\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u062f\u0652 \u064a\u064e\u0626\u0650\u0633\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0626\u0650\u0633\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u0650"],t.v)
B.apq=new A.U([1,u.Y,2,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u0650\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",3,"\u0643\u064e\u0628\u064f\u0631\u064e \u0645\u064e\u0642\u0652\u062a\u064b\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",4,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0635\u064e\u0641\u0651\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u064c \u0645\u064e\u0631\u0652\u0635\u064f\u0648\u0635\u064c",5,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0644\u0650\u0645\u064e \u062a\u064f\u0624\u0652\u0630\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0648\u064e\u0642\u064e\u062f\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0632\u064e\u0627\u063a\u064f\u0648\u0627 \u0623\u064e\u0632\u064e\u0627\u063a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",6,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u064a\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u0650 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064b\u0627 \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650\u064a \u0627\u0633\u0652\u0645\u064f\u0647\u064f \u0623\u064e\u062d\u0652\u0645\u064e\u062f\u064f \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",7,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0638\u0652\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062f\u0652\u0639\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",8,"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064f\u0637\u0652\u0641\u0650\u0626\u064f\u0648\u0627 \u0646\u064f\u0648\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0641\u0652\u0648\u064e\u0627\u0647\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u064f\u0648\u0631\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",9,u.b8,10,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0647\u064e\u0644\u0652 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064d \u062a\u064f\u0646\u0652\u062c\u0650\u064a\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",11,"\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u062a\u064f\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",12,"\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0643\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064e \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0639\u064e\u062f\u0652\u0646\u064d \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",13,"\u0648\u064e\u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u06d6 \u0646\u064e\u0635\u0652\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u062a\u0652\u062d\u064c \u0642\u064e\u0631\u0650\u064a\u0628\u064c \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",14,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0644\u0650\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u0652\u0646\u064f \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0622\u0645\u064e\u0646\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064e\u062a\u0652 \u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u06d6 \u0641\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u0652\u0646\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0638\u064e\u0627\u0647\u0650\u0631\u0650\u064a\u0646\u064e"],t.v)
B.ap7=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u0650 \u0627\u0644\u0652\u0642\u064f\u062f\u0651\u064f\u0648\u0633\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",2,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0639\u064e\u062b\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u064a\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u0643\u0652\u0645\u064e\u0629\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",3,"\u0648\u064e\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0644\u0652\u062d\u064e\u0642\u064f\u0648\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",4,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u0652\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",5,"\u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064f\u0645\u0651\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u062a\u0651\u064e\u0648\u0652\u0631\u064e\u0627\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0648\u0647\u064e\u0627 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0627\u0644\u0652\u062d\u0650\u0645\u064e\u0627\u0631\u0650 \u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0623\u064e\u0633\u0652\u0641\u064e\u0627\u0631\u064b\u0627 \u06da \u0628\u0650\u0626\u0652\u0633\u064e \u0645\u064e\u062b\u064e\u0644\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",6,"\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0625\u0650\u0646\u0652 \u0632\u064e\u0639\u064e\u0645\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",7,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",8,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0641\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064f\u0644\u064e\u0627\u0642\u0650\u064a\u0643\u064f\u0645\u0652 \u06d6 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u0644\u0650\u0645\u0650 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",9,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0644\u0650\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0645\u0650\u0646\u0652 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062c\u064f\u0645\u064f\u0639\u064e\u0629\u0650 \u0641\u064e\u0627\u0633\u0652\u0639\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u0639\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",10,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e\u062a\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064f \u0641\u064e\u0627\u0646\u0652\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",11,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u062a\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0644\u064e\u0647\u0652\u0648\u064b\u0627 \u0627\u0646\u0652\u0641\u064e\u0636\u0651\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0643\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u06da \u0642\u064f\u0644\u0652 \u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0652\u0648\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e"],t.v)
B.ap8=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",2,"\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u0647\u064f\u0645\u0652 \u062c\u064f\u0646\u0651\u064e\u0629\u064b \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627 \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",3,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u064e\u0637\u064f\u0628\u0650\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",4,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u062a\u064f\u0639\u0652\u062c\u0650\u0628\u064f\u0643\u064e \u0623\u064e\u062c\u0652\u0633\u064e\u0627\u0645\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u0652 \u0644\u0650\u0642\u064e\u0648\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062e\u064f\u0634\u064f\u0628\u064c \u0645\u064f\u0633\u064e\u0646\u0651\u064e\u062f\u064e\u0629\u064c \u06d6 \u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0635\u064e\u064a\u0652\u062d\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06da \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u062f\u064f\u0648\u0651\u064f \u0641\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u06da \u0642\u064e\u0627\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d6 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u0652\u0641\u064e\u0643\u064f\u0648\u0646\u064e",5,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0652\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u0651\u064e\u0648\u0652\u0627 \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0645\u064f\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u0650\u0631\u064f\u0648\u0646\u064e",6,"\u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u0652\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",7,"\u0647\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0646\u0652\u0641\u064e\u0636\u0651\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u0632\u064e\u0627\u0626\u0650\u0646\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e",8,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0626\u0650\u0646\u0652 \u0631\u064e\u062c\u064e\u0639\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0630\u064e\u0644\u0651\u064e \u06da \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u0648\u064e\u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u064e\u0627\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",9,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064f\u0644\u0652\u0647\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u062e\u0651\u064e\u0631\u0652\u062a\u064e\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0642\u064e\u0631\u0650\u064a\u0628\u064d \u0641\u064e\u0623\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064e \u0648\u064e\u0623\u064e\u0643\u064f\u0646\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0644\u064e\u0646\u0652 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064e\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064c \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e"],t.v)
B.ap0=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",2,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0641\u0650\u0631\u064c \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064c \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",3,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0635\u064e\u0648\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0635\u064f\u0648\u064e\u0631\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",4,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",5,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0630\u064e\u0627\u0642\u064f\u0648\u0627 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",6,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u0647\u0650\u0645\u0652 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0628\u064e\u0634\u064e\u0631\u064c \u064a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u06da \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0646\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",7,"\u0632\u064e\u0639\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0627 \u06da \u0642\u064f\u0644\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u062a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0646\u0651\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u064e\u0624\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",8,"\u0641\u064e\u0622\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064c",9,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u0650 \u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u062a\u0651\u064e\u063a\u064e\u0627\u0628\u064f\u0646\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",10,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",11,"\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u0652 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u0652\u062f\u0650 \u0642\u064e\u0644\u0652\u0628\u064e\u0647\u064f \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",12,"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u0627\u063a\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",13,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",14,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u062d\u0652\u0630\u064e\u0631\u064f\u0648\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u0652\u0641\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0635\u0652\u0641\u064e\u062d\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",15,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0627\u062f\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",16,"\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0648\u064e\u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0648\u0642\u064e \u0634\u064f\u062d\u0651\u064e \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",17,"\u0625\u0650\u0646\u0652 \u062a\u064f\u0642\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u064a\u064f\u0636\u064e\u0627\u0639\u0650\u0641\u0652\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0643\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",18,"\u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f"],t.v)
B.are=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0621\u064e \u0641\u064e\u0637\u064e\u0644\u0651\u0650\u0642\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u0639\u0650\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u062d\u0652\u0635\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u062f\u0651\u064e\u0629\u064e \u06d6 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u0652\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0641\u064e\u0627\u062d\u0650\u0634\u064e\u0629\u064d \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064d \u06da \u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0638\u064e\u0644\u064e\u0645\u064e \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0631\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0652\u062f\u0650\u062b\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0631\u064b\u0627",2,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u0652\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0623\u064e\u0645\u0652\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u0652 \u0641\u064e\u0627\u0631\u0650\u0642\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u0650\u062f\u064f\u0648\u0627 \u0630\u064e\u0648\u064e\u064a\u0652 \u0639\u064e\u062f\u0652\u0644\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0634\u0651\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u0652 \u064a\u064f\u0648\u0639\u064e\u0638\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0645\u064e\u062e\u0652\u0631\u064e\u062c\u064b\u0627",3,"\u0648\u064e\u064a\u064e\u0631\u0652\u0632\u064f\u0642\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u062a\u064e\u0633\u0650\u0628\u064f \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0633\u0652\u0628\u064f\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0627\u0644\u0650\u063a\u064f \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u06da \u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0652\u0631\u064b\u0627",4,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0627\u0626\u0650\u064a \u064a\u064e\u0626\u0650\u0633\u0652\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u062d\u0650\u064a\u0636\u0650 \u0645\u0650\u0646\u0652 \u0646\u0650\u0633\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0650 \u0627\u0631\u0652\u062a\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064f \u0623\u064e\u0634\u0652\u0647\u064f\u0631\u064d \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0627\u0626\u0650\u064a \u0644\u064e\u0645\u0652 \u064a\u064e\u062d\u0650\u0636\u0652\u0646\u064e \u06da \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0627\u062a\u064f \u0627\u0644\u0652\u0623\u064e\u062d\u0652\u0645\u064e\u0627\u0644\u0650 \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u0636\u064e\u0639\u0652\u0646\u064e \u062d\u064e\u0645\u0652\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627",5,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0639\u0652\u0638\u0650\u0645\u0652 \u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064b\u0627",6,"\u0623\u064e\u0633\u0652\u0643\u0650\u0646\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0633\u064e\u0643\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0648\u064f\u062c\u0652\u062f\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0636\u064e\u0627\u0631\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064f\u0636\u064e\u064a\u0651\u0650\u0642\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u06da \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0651\u064e \u0623\u064f\u0648\u0644\u064e\u0627\u062a\u0650 \u062d\u064e\u0645\u0652\u0644\u064d \u0641\u064e\u0623\u064e\u0646\u0652\u0641\u0650\u0642\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0646\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0636\u064e\u0639\u0652\u0646\u064e \u062d\u064e\u0645\u0652\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u06da \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u064e\u0639\u0652\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0622\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u06d6 \u0648\u064e\u0623\u0652\u062a\u064e\u0645\u0650\u0631\u064f\u0648\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0639\u064e\u0627\u0633\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0633\u064e\u062a\u064f\u0631\u0652\u0636\u0650\u0639\u064f \u0644\u064e\u0647\u064f \u0623\u064f\u062e\u0652\u0631\u064e\u0649\u0670",7,"\u0644\u0650\u064a\u064f\u0646\u0652\u0641\u0650\u0642\u0652 \u0630\u064f\u0648 \u0633\u064e\u0639\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0633\u064e\u0639\u064e\u062a\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064f\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u0650\u0632\u0652\u0642\u064f\u0647\u064f \u0641\u064e\u0644\u0652\u064a\u064f\u0646\u0652\u0641\u0650\u0642\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0647\u064e\u0627 \u06da \u0633\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0639\u064f\u0633\u0652\u0631\u064d \u064a\u064f\u0633\u0652\u0631\u064b\u0627",8,"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0639\u064e\u062a\u064e\u062a\u0652 \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0641\u064e\u062d\u064e\u0627\u0633\u064e\u0628\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0646\u064f\u0643\u0652\u0631\u064b\u0627",9,"\u0641\u064e\u0630\u064e\u0627\u0642\u064e\u062a\u0652 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0623\u064e\u0645\u0652\u0631\u0650\u0647\u064e\u0627 \u062e\u064f\u0633\u0652\u0631\u064b\u0627",10,"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u06d6 \u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0644\u0652\u0628\u064e\u0627\u0628\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06da \u0642\u064e\u062f\u0652 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0630\u0650\u0643\u0652\u0631\u064b\u0627",11,"\u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0644\u0650\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u0652\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06d6 \u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0631\u0650\u0632\u0652\u0642\u064b\u0627",12,"\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064d \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u062b\u0652\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u064a\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0644\u0652\u0645\u064b\u0627"],t.v)
B.ard=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f \u0645\u064e\u0627 \u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064e \u06d6 \u062a\u064e\u0628\u0652\u062a\u064e\u063a\u0650\u064a \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u064e \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064e \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c",2,"\u0642\u064e\u062f\u0652 \u0641\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062d\u0650\u0644\u0651\u064e\u0629\u064e \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",3,"\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u0633\u064e\u0631\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u0650 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0647\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u064b\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0638\u0652\u0647\u064e\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0639\u064e\u0631\u0651\u064e\u0641\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u0652 \u0628\u064e\u0639\u0652\u0636\u064d \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0647\u064e\u0627 \u0628\u0650\u0647\u0650 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0628\u064e\u0623\u064e\u0643\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",4,"\u0625\u0650\u0646\u0652 \u062a\u064e\u062a\u064f\u0648\u0628\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u063a\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u064e\u0627 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0638\u064e\u0627\u0647\u064e\u0631\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0647\u064f \u0648\u064e\u062c\u0650\u0628\u0652\u0631\u0650\u064a\u0644\u064f \u0648\u064e\u0635\u064e\u0627\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u06d6 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064c",5,"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0625\u0650\u0646\u0652 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0643\u064f\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u064a\u064f\u0628\u0652\u062f\u0650\u0644\u064e\u0647\u064f \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0646\u0651\u064e \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064e\u0627\u062a\u064d \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0646\u0650\u062a\u064e\u0627\u062a\u064d \u062a\u064e\u0627\u0626\u0650\u0628\u064e\u0627\u062a\u064d \u0639\u064e\u0627\u0628\u0650\u062f\u064e\u0627\u062a\u064d \u0633\u064e\u0627\u0626\u0650\u062d\u064e\u0627\u062a\u064d \u062b\u064e\u064a\u0651\u0650\u0628\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0628\u0652\u0643\u064e\u0627\u0631\u064b\u0627",6,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0642\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0643\u064f\u0645\u0652 \u0646\u064e\u0627\u0631\u064b\u0627 \u0648\u064e\u0642\u064f\u0648\u062f\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064c \u063a\u0650\u0644\u064e\u0627\u0638\u064c \u0634\u0650\u062f\u064e\u0627\u062f\u064c \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0635\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u064e\u0631\u064f\u0648\u0646\u064e",7,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u0652\u0632\u064e\u0648\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",8,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u0652\u0628\u064e\u0629\u064b \u0646\u064e\u0635\u064f\u0648\u062d\u064b\u0627 \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u0652\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u064e\u0639\u064e\u0647\u064f \u06d6 \u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0628\u0650\u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0623\u064e\u062a\u0652\u0645\u0650\u0645\u0652 \u0644\u064e\u0646\u064e\u0627 \u0646\u064f\u0648\u0631\u064e\u0646\u064e\u0627 \u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",9,u.b9,10,"\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e \u0644\u064f\u0648\u0637\u064d \u06d6 \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u062a\u064e\u062d\u0652\u062a\u064e \u0639\u064e\u0628\u0652\u062f\u064e\u064a\u0652\u0646\u0650 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u062e\u064e\u0627\u0646\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u063a\u0652\u0646\u0650\u064a\u064e\u0627 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u062f\u0652\u062e\u064f\u0644\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u062e\u0650\u0644\u0650\u064a\u0646\u064e",11,"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0628\u0652\u0646\u0650 \u0644\u0650\u064a \u0639\u0650\u0646\u0652\u062f\u064e\u0643\u064e \u0628\u064e\u064a\u0652\u062a\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",12,"\u0648\u064e\u0645\u064e\u0631\u0652\u064a\u064e\u0645\u064e \u0627\u0628\u0652\u0646\u064e\u062a\u064e \u0639\u0650\u0645\u0652\u0631\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0623\u064e\u062d\u0652\u0635\u064e\u0646\u064e\u062a\u0652 \u0641\u064e\u0631\u0652\u062c\u064e\u0647\u064e\u0627 \u0641\u064e\u0646\u064e\u0641\u064e\u062e\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064f\u0648\u062d\u0650\u0646\u064e\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e\u062a\u0652 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e"],t.v)
B.apj=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0644\u0650\u064a\u064e\u0628\u0652\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u0652 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064d \u0637\u0650\u0628\u064e\u0627\u0642\u064b\u0627 \u06d6 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u062e\u064e\u0644\u0652\u0642\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0645\u0650\u0646\u0652 \u062a\u064e\u0641\u064e\u0627\u0648\u064f\u062a\u064d \u06d6 \u0641\u064e\u0627\u0631\u0652\u062c\u0650\u0639\u0650 \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064e \u0647\u064e\u0644\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0641\u064f\u0637\u064f\u0648\u0631\u064d",4,"\u062b\u064f\u0645\u0651\u064e \u0627\u0631\u0652\u062c\u0650\u0639\u0650 \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064e \u0643\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064f \u062e\u064e\u0627\u0633\u0650\u0626\u064b\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0633\u0650\u064a\u0631\u064c",5,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0628\u0650\u0645\u064e\u0635\u064e\u0627\u0628\u0650\u064a\u062d\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0631\u064f\u062c\u064f\u0648\u0645\u064b\u0627 \u0644\u0650\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u0650 \u06d6 \u0648\u064e\u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",6,"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",7,"\u0625\u0650\u0630\u064e\u0627 \u0623\u064f\u0644\u0652\u0642\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064e\u0627 \u0634\u064e\u0647\u0650\u064a\u0642\u064b\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u0641\u064f\u0648\u0631\u064f",8,"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u062a\u064e\u0645\u064e\u064a\u0651\u064e\u0632\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0638\u0650 \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0648\u0652\u062c\u064c \u0633\u064e\u0623\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c",9,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u0652 \u062c\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u0652\u0646\u064e\u0627 \u0648\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0634\u064e\u064a\u0652\u0621\u064d \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0643\u064e\u0628\u0650\u064a\u0631\u064d",10,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0648\u0652 \u0646\u064e\u0639\u0652\u0642\u0650\u0644\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",11,"\u0641\u064e\u0627\u0639\u0652\u062a\u064e\u0631\u064e\u0641\u064f\u0648\u0627 \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0633\u064f\u062d\u0652\u0642\u064b\u0627 \u0644\u0650\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",12,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u0652\u0634\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",13,"\u0648\u064e\u0623\u064e\u0633\u0650\u0631\u0651\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0650 \u0627\u062c\u0652\u0647\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",14,"\u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0637\u0650\u064a\u0641\u064f \u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",15,"\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0630\u064e\u0644\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0627\u0645\u0652\u0634\u064f\u0648\u0627 \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0643\u0650\u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0631\u0650\u0632\u0652\u0642\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f",16,"\u0623\u064e\u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0633\u0650\u0641\u064e \u0628\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0645\u064f\u0648\u0631\u064f",17,"\u0623\u064e\u0645\u0652 \u0623\u064e\u0645\u0650\u0646\u0652\u062a\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u062d\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u0650",18,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",19,"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u0650 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0641\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u064a\u064e\u0642\u0652\u0628\u0650\u0636\u0652\u0646\u064e \u06da \u0645\u064e\u0627 \u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0628\u064e\u0635\u0650\u064a\u0631\u064c",20,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u062c\u064f\u0646\u0652\u062f\u064c \u0644\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0635\u064f\u0631\u064f\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u06da \u0625\u0650\u0646\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u063a\u064f\u0631\u064f\u0648\u0631\u064d",21,"\u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0633\u064e\u0643\u064e \u0631\u0650\u0632\u0652\u0642\u064e\u0647\u064f \u06da \u0628\u064e\u0644\u0652 \u0644\u064e\u062c\u0651\u064f\u0648\u0627 \u0641\u0650\u064a \u0639\u064f\u062a\u064f\u0648\u0651\u064d \u0648\u064e\u0646\u064f\u0641\u064f\u0648\u0631\u064d",22,"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0645\u064f\u0643\u0650\u0628\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0623\u064e\u0645\u0651\u064e\u0646\u0652 \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0633\u064e\u0648\u0650\u064a\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",23,"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u064e \u06d6 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",24,"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0630\u064e\u0631\u064e\u0623\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f\u0648\u0646\u064e",25,u.k,26,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",27,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0647\u064f \u0632\u064f\u0644\u0652\u0641\u064e\u0629\u064b \u0633\u0650\u064a\u0626\u064e\u062a\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",28,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e\u0646\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0623\u064e\u0648\u0652 \u0631\u064e\u062d\u0650\u0645\u064e\u0646\u064e\u0627 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u062c\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",29,"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d",30,"\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0645\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u0652 \u063a\u064e\u0648\u0652\u0631\u064b\u0627 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627\u0621\u064d \u0645\u064e\u0639\u0650\u064a\u0646\u064d"],t.v)
B.ac_=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0646 \u06da \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0644\u064e\u0645\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u0637\u064f\u0631\u064f\u0648\u0646\u064e",2,"\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064d",3,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0645\u0652\u0646\u064f\u0648\u0646\u064d",4,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064f\u0644\u064f\u0642\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",5,"\u0641\u064e\u0633\u064e\u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f \u0648\u064e\u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",6,"\u0628\u0650\u0623\u064e\u064a\u0652\u064a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0641\u0652\u062a\u064f\u0648\u0646\u064f",7,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0652 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",8,"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",9,"\u0648\u064e\u062f\u0651\u064f\u0648\u0627 \u0644\u064e\u0648\u0652 \u062a\u064f\u062f\u0652\u0647\u0650\u0646\u064f \u0641\u064e\u064a\u064f\u062f\u0652\u0647\u0650\u0646\u064f\u0648\u0646\u064e",10,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652 \u0643\u064f\u0644\u0651\u064e \u062d\u064e\u0644\u0651\u064e\u0627\u0641\u064d \u0645\u064e\u0647\u0650\u064a\u0646\u064d",11,"\u0647\u064e\u0645\u0651\u064e\u0627\u0632\u064d \u0645\u064e\u0634\u0651\u064e\u0627\u0621\u064d \u0628\u0650\u0646\u064e\u0645\u0650\u064a\u0645\u064d",12,"\u0645\u064e\u0646\u0651\u064e\u0627\u0639\u064d \u0644\u0650\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0645\u064f\u0639\u0652\u062a\u064e\u062f\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",13,"\u0639\u064f\u062a\u064f\u0644\u0651\u064d \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u0646\u0650\u064a\u0645\u064d",14,"\u0623\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0645\u064e\u0627\u0644\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",15,u.H,16,"\u0633\u064e\u0646\u064e\u0633\u0650\u0645\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u062e\u064f\u0631\u0652\u0637\u064f\u0648\u0645\u0650",17,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u0648\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u064e\u0648\u0652\u0646\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u0623\u064e\u0642\u0652\u0633\u064e\u0645\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0635\u0652\u0631\u0650\u0645\u064f\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u064f\u0635\u0652\u0628\u0650\u062d\u0650\u064a\u0646\u064e",18,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062b\u0652\u0646\u064f\u0648\u0646\u064e",19,"\u0641\u064e\u0637\u064e\u0627\u0641\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0637\u064e\u0627\u0626\u0650\u0641\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u0652 \u0646\u064e\u0627\u0626\u0650\u0645\u064f\u0648\u0646\u064e",20,"\u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e\u062a\u0652 \u0643\u064e\u0627\u0644\u0635\u0651\u064e\u0631\u0650\u064a\u0645\u0650",21,"\u0641\u064e\u062a\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0652\u0627 \u0645\u064f\u0635\u0652\u0628\u0650\u062d\u0650\u064a\u0646\u064e",22,"\u0623\u064e\u0646\u0650 \u0627\u063a\u0652\u062f\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u0652\u062b\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u0631\u0650\u0645\u0650\u064a\u0646\u064e",23,"\u0641\u064e\u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u062e\u064e\u0627\u0641\u064e\u062a\u064f\u0648\u0646\u064e",24,"\u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064c",25,"\u0648\u064e\u063a\u064e\u062f\u064e\u0648\u0652\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u0652\u062f\u064d \u0642\u064e\u0627\u062f\u0650\u0631\u0650\u064a\u0646\u064e",26,"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0636\u064e\u0627\u0644\u0651\u064f\u0648\u0646\u064e",27,"\u0628\u064e\u0644\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064e\u062d\u0652\u0631\u064f\u0648\u0645\u064f\u0648\u0646\u064e",28,"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u0652\u0633\u064e\u0637\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0642\u064f\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e",29,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",30,"\u0641\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u064d \u064a\u064e\u062a\u064e\u0644\u064e\u0627\u0648\u064e\u0645\u064f\u0648\u0646\u064e",31,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627 \u0648\u064e\u064a\u0652\u0644\u064e\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0637\u064e\u0627\u063a\u0650\u064a\u0646\u064e",32,"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0628\u0652\u062f\u0650\u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0631\u064e\u0627\u063a\u0650\u0628\u064f\u0648\u0646\u064e",33,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u06da \u0644\u064e\u0648\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",34,"\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",35,"\u0623\u064e\u0641\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",36,"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",37,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062f\u0652\u0631\u064f\u0633\u064f\u0648\u0646\u064e",38,"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0645\u064e\u0627 \u062a\u064e\u062e\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0646\u064e",39,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u0627\u0644\u0650\u063a\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06d9 \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u0652\u0643\u064f\u0645\u064f\u0648\u0646\u064e",40,"\u0633\u064e\u0644\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u0639\u0650\u064a\u0645\u064c",41,"\u0623\u064e\u0645\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064f \u0641\u064e\u0644\u0652\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",42,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0643\u0652\u0634\u064e\u0641\u064f \u0639\u064e\u0646\u0652 \u0633\u064e\u0627\u0642\u064d \u0648\u064e\u064a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",43,"\u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u062a\u064e\u0631\u0652\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u0652 \u0630\u0650\u0644\u0651\u064e\u0629\u064c \u06d6 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u062f\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u0633\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",44,"\u0641\u064e\u0630\u064e\u0631\u0652\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u06d6 \u0633\u064e\u0646\u064e\u0633\u0652\u062a\u064e\u062f\u0652\u0631\u0650\u062c\u064f\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",45,"\u0648\u064e\u0623\u064f\u0645\u0652\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u06da \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u0650\u064a \u0645\u064e\u062a\u0650\u064a\u0646\u064c",46,u.n,47,u.V,48,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0644\u0650\u062d\u064f\u0643\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646\u0652 \u0643\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u0650 \u0627\u0644\u0652\u062d\u064f\u0648\u062a\u0650 \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0643\u0652\u0638\u064f\u0648\u0645\u064c",49,"\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646\u0652 \u062a\u064e\u062f\u064e\u0627\u0631\u064e\u0643\u064e\u0647\u064f \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0644\u064e\u0646\u064f\u0628\u0650\u0630\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0631\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0630\u0652\u0645\u064f\u0648\u0645\u064c",50,"\u0641\u064e\u0627\u062c\u0652\u062a\u064e\u0628\u064e\u0627\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",51,"\u0648\u064e\u0625\u0650\u0646\u0652 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u064e\u064a\u064f\u0632\u0652\u0644\u0650\u0642\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",52,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e"],t.v)
B.abY=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0627\u0642\u0651\u064e\u0629\u064f",2,"\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0627\u0642\u0651\u064e\u0629\u064f",3,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0627\u0642\u0651\u064e\u0629\u064f",4,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0648\u064e\u0639\u064e\u0627\u062f\u064c \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u0650",5,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0641\u064e\u0623\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0637\u0651\u064e\u0627\u063a\u0650\u064a\u064e\u0629\u0650",6,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0627\u062f\u064c \u0641\u064e\u0623\u064f\u0647\u0652\u0644\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0631\u0650\u064a\u062d\u064d \u0635\u064e\u0631\u0652\u0635\u064e\u0631\u064d \u0639\u064e\u0627\u062a\u0650\u064a\u064e\u0629\u064d",7,"\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0633\u064e\u0628\u0652\u0639\u064e \u0644\u064e\u064a\u064e\u0627\u0644\u064d \u0648\u064e\u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062d\u064f\u0633\u064f\u0648\u0645\u064b\u0627 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0635\u064e\u0631\u0652\u0639\u064e\u0649\u0670 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u062c\u064e\u0627\u0632\u064f \u0646\u064e\u062e\u0652\u0644\u064d \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064d",8,"\u0641\u064e\u0647\u064e\u0644\u0652 \u062a\u064e\u0631\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0629\u064d",9,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u062a\u064e\u0641\u0650\u0643\u064e\u0627\u062a\u064f \u0628\u0650\u0627\u0644\u0652\u062e\u064e\u0627\u0637\u0650\u0626\u064e\u0629\u0650",10,"\u0641\u064e\u0639\u064e\u0635\u064e\u0648\u0652\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u0652\u0630\u064e\u0629\u064b \u0631\u064e\u0627\u0628\u0650\u064a\u064e\u0629\u064b",11,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0637\u064e\u063a\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f \u062d\u064e\u0645\u064e\u0644\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0627\u0631\u0650\u064a\u064e\u0629\u0650",12,"\u0644\u0650\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u062a\u064e\u0639\u0650\u064a\u064e\u0647\u064e\u0627 \u0623\u064f\u0630\u064f\u0646\u064c \u0648\u064e\u0627\u0639\u0650\u064a\u064e\u0629\u064c",13,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0646\u064e\u0641\u0652\u062e\u064e\u0629\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064c",14,"\u0648\u064e\u062d\u064f\u0645\u0650\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0641\u064e\u062f\u064f\u0643\u0651\u064e\u062a\u064e\u0627 \u062f\u064e\u0643\u0651\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b",15,"\u0641\u064e\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0642\u064e\u0639\u064e\u062a\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u0642\u0650\u0639\u064e\u0629\u064f",16,"\u0648\u064e\u0627\u0646\u0652\u0634\u064e\u0642\u0651\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0641\u064e\u0647\u0650\u064a\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0627\u0647\u0650\u064a\u064e\u0629\u064c",17,"\u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0631\u0652\u062c\u064e\u0627\u0626\u0650\u0647\u064e\u0627 \u06da \u0648\u064e\u064a\u064e\u062d\u0652\u0645\u0650\u0644\u064f \u0639\u064e\u0631\u0652\u0634\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064c",18,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062a\u064f\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u0652\u0641\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u062e\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064c",19,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0627\u0624\u064f\u0645\u064f \u0627\u0642\u0652\u0631\u064e\u0621\u064f\u0648\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u0652",20,"\u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064f\u0644\u064e\u0627\u0642\u064d \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u0652",21,"\u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0639\u0650\u064a\u0634\u064e\u0629\u064d \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064d",22,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u064d",23,"\u0642\u064f\u0637\u064f\u0648\u0641\u064f\u0647\u064e\u0627 \u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064c",24,"\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u0627\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0627 \u0647\u064e\u0646\u0650\u064a\u0626\u064b\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0644\u064e\u0641\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0650 \u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u0650",25,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f \u0628\u0650\u0634\u0650\u0645\u064e\u0627\u0644\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u0652 \u0623\u064f\u0648\u062a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u0652",26,"\u0648\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u062f\u0652\u0631\u0650 \u0645\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u0652",27,"\u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0627\u0644\u0652\u0642\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064e",28,"\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0627\u0644\u0650\u064a\u064e\u0647\u0652 \u06dc",29,"\u0647\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646\u0651\u0650\u064a \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u0650\u064a\u064e\u0647\u0652",30,"\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0641\u064e\u063a\u064f\u0644\u0651\u064f\u0648\u0647\u064f",31,"\u062b\u064f\u0645\u0651\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064e \u0635\u064e\u0644\u0651\u064f\u0648\u0647\u064f",32,"\u062b\u064f\u0645\u0651\u064e \u0641\u0650\u064a \u0633\u0650\u0644\u0652\u0633\u0650\u0644\u064e\u0629\u064d \u0630\u064e\u0631\u0652\u0639\u064f\u0647\u064e\u0627 \u0633\u064e\u0628\u0652\u0639\u064f\u0648\u0646\u064e \u0630\u0650\u0631\u064e\u0627\u0639\u064b\u0627 \u0641\u064e\u0627\u0633\u0652\u0644\u064f\u0643\u064f\u0648\u0647\u064f",33,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",34,u.bZ,35,"\u0641\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u062d\u064e\u0645\u0650\u064a\u0645\u064c",36,"\u0648\u064e\u0644\u064e\u0627 \u0637\u064e\u0639\u064e\u0627\u0645\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u063a\u0650\u0633\u0652\u0644\u0650\u064a\u0646\u064d",37,"\u0644\u064e\u0627 \u064a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u062e\u064e\u0627\u0637\u0650\u0626\u064f\u0648\u0646\u064e",38,"\u0641\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",39,"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",40,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0642\u064e\u0648\u0652\u0644\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",41,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0642\u064e\u0648\u0652\u0644\u0650 \u0634\u064e\u0627\u0639\u0650\u0631\u064d \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",42,"\u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0642\u064e\u0648\u0652\u0644\u0650 \u0643\u064e\u0627\u0647\u0650\u0646\u064d \u06da \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",43,"\u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064c \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",44,"\u0648\u064e\u0644\u064e\u0648\u0652 \u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064e \u0627\u0644\u0652\u0623\u064e\u0642\u064e\u0627\u0648\u0650\u064a\u0644\u0650",45,"\u0644\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",46,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0642\u064e\u0637\u064e\u0639\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0652\u0648\u064e\u062a\u0650\u064a\u0646\u064e",47,"\u0641\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0639\u064e\u0646\u0652\u0647\u064f \u062d\u064e\u0627\u062c\u0650\u0632\u0650\u064a\u0646\u064e",48,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",49,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",50,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0633\u0652\u0631\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",51,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062d\u064e\u0642\u0651\u064f \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u0650",52,"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652 \u0628\u0650\u0627\u0633\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650"],t.v)
B.apl=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0633\u064e\u0623\u064e\u0644\u064e \u0633\u064e\u0627\u0626\u0650\u0644\u064c \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0648\u064e\u0627\u0642\u0650\u0639\u064d",2,"\u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f \u062f\u064e\u0627\u0641\u0650\u0639\u064c",3,"\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0630\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0639\u064e\u0627\u0631\u0650\u062c\u0650",4,"\u062a\u064e\u0639\u0652\u0631\u064f\u062c\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064d \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0642\u0652\u062f\u064e\u0627\u0631\u064f\u0647\u064f \u062e\u064e\u0645\u0652\u0633\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d",5,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0635\u064e\u0628\u0652\u0631\u064b\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u064b\u0627",6,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",7,"\u0648\u064e\u0646\u064e\u0631\u064e\u0627\u0647\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",8,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0643\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u0644\u0650",9,"\u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u0627\u0644\u0652\u0639\u0650\u0647\u0652\u0646\u0650",10,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u062d\u064e\u0645\u0650\u064a\u0645\u064c \u062d\u064e\u0645\u0650\u064a\u0645\u064b\u0627",11,"\u064a\u064f\u0628\u064e\u0635\u0651\u064e\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f \u0644\u064e\u0648\u0652 \u064a\u064e\u0641\u0652\u062a\u064e\u062f\u0650\u064a \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u0650\u0626\u0650\u0630\u064d \u0628\u0650\u0628\u064e\u0646\u0650\u064a\u0647\u0650",12,"\u0648\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650",13,"\u0648\u064e\u0641\u064e\u0635\u0650\u064a\u0644\u064e\u062a\u0650\u0647\u0650 \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0624\u0652\u0648\u0650\u064a\u0647\u0650",14,"\u0648\u064e\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u0652\u062c\u0650\u064a\u0647\u0650",15,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0638\u064e\u0649\u0670",16,"\u0646\u064e\u0632\u0651\u064e\u0627\u0639\u064e\u0629\u064b \u0644\u0650\u0644\u0634\u0651\u064e\u0648\u064e\u0649\u0670",17,"\u062a\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u064e\u0646\u0652 \u0623\u064e\u062f\u0652\u0628\u064e\u0631\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",18,"\u0648\u064e\u062c\u064e\u0645\u064e\u0639\u064e \u0641\u064e\u0623\u064e\u0648\u0652\u0639\u064e\u0649\u0670",19,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u062e\u064f\u0644\u0650\u0642\u064e \u0647\u064e\u0644\u064f\u0648\u0639\u064b\u0627",20,"\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u062c\u064e\u0632\u064f\u0648\u0639\u064b\u0627",21,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0646\u064f\u0648\u0639\u064b\u0627",22,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u0646\u064e",23,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u062f\u064e\u0627\u0626\u0650\u0645\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652 \u062d\u064e\u0642\u0651\u064c \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064c",25,"\u0644\u0650\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u062d\u0652\u0631\u064f\u0648\u0645\u0650",26,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u0628\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",27,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u0634\u0652\u0641\u0650\u0642\u064f\u0648\u0646\u064e",28,"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0623\u0652\u0645\u064f\u0648\u0646\u064d",29,u.F,30,u.bC,31,u.W,32,u.ab,33,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0628\u0650\u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0626\u0650\u0645\u064f\u0648\u0646\u064e",34,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",35,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0645\u064f\u0643\u0652\u0631\u064e\u0645\u064f\u0648\u0646\u064e",36,"\u0641\u064e\u0645\u064e\u0627\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0642\u0650\u0628\u064e\u0644\u064e\u0643\u064e \u0645\u064f\u0647\u0652\u0637\u0650\u0639\u0650\u064a\u0646\u064e",37,"\u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0627\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0639\u0650\u0632\u0650\u064a\u0646\u064e",38,"\u0623\u064e\u064a\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0643\u064f\u0644\u0651\u064f \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u062f\u0652\u062e\u064e\u0644\u064e \u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0646\u064e\u0639\u0650\u064a\u0645\u064d",39,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",40,"\u0641\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u064e\u0627\u0631\u0650\u0628\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e",41,"\u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0646\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064e\u0633\u0652\u0628\u064f\u0648\u0642\u0650\u064a\u0646\u064e",42,u.N,43,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u062c\u0652\u062f\u064e\u0627\u062b\u0650 \u0633\u0650\u0631\u064e\u0627\u0639\u064b\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0635\u064f\u0628\u064d \u064a\u064f\u0648\u0641\u0650\u0636\u064f\u0648\u0646\u064e",44,"\u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064f\u0645\u0652 \u062a\u064e\u0631\u0652\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u0652 \u0630\u0650\u0644\u0651\u064e\u0629\u064c \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e"],t.v)
B.aor=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652 \u0642\u064e\u0648\u0652\u0645\u064e\u0643\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",2,"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0642\u064e\u0648\u0652\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u064f\u0628\u0650\u064a\u0646\u064c",3,"\u0623\u064e\u0646\u0650 \u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",4,"\u064a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062c\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u062e\u0651\u064e\u0631\u064f \u06d6 \u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",5,"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0644\u064e\u064a\u0652\u0644\u064b\u0627 \u0648\u064e\u0646\u064e\u0647\u064e\u0627\u0631\u064b\u0627",6,"\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0632\u0650\u062f\u0652\u0647\u064f\u0645\u0652 \u062f\u064f\u0639\u064e\u0627\u0626\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0631\u064b\u0627",7,"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0634\u064e\u0648\u0652\u0627 \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0635\u064e\u0631\u0651\u064f\u0648\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u062a\u0650\u0643\u0652\u0628\u064e\u0627\u0631\u064b\u0627",8,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u062c\u0650\u0647\u064e\u0627\u0631\u064b\u0627",9,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0633\u0652\u0631\u064e\u0631\u0652\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0631\u064b\u0627",10,"\u0641\u064e\u0642\u064f\u0644\u0652\u062a\u064f \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u0651\u064e\u0627\u0631\u064b\u0627",11,"\u064a\u064f\u0631\u0652\u0633\u0650\u0644\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u062f\u0652\u0631\u064e\u0627\u0631\u064b\u0627",12,"\u0648\u064e\u064a\u064f\u0645\u0652\u062f\u0650\u062f\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064b\u0627",13,"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0631\u064b\u0627",14,"\u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0637\u0652\u0648\u064e\u0627\u0631\u064b\u0627",15,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e\u0648\u0652\u0627 \u0643\u064e\u064a\u0652\u0641\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0628\u0652\u0639\u064e \u0633\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u064d \u0637\u0650\u0628\u064e\u0627\u0642\u064b\u0627",16,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0646\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064e \u0633\u0650\u0631\u064e\u0627\u062c\u064b\u0627",17,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652\u0628\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0646\u064e\u0628\u064e\u0627\u062a\u064b\u0627",18,"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u064b\u0627",19,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u0650\u0633\u064e\u0627\u0637\u064b\u0627",20,"\u0644\u0650\u062a\u064e\u0633\u0652\u0644\u064f\u0643\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u064b\u0627 \u0641\u0650\u062c\u064e\u0627\u062c\u064b\u0627",21,"\u0642\u064e\u0627\u0644\u064e \u0646\u064f\u0648\u062d\u064c \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0635\u064e\u0648\u0652\u0646\u0650\u064a \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627 \u0645\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0632\u0650\u062f\u0652\u0647\u064f \u0645\u064e\u0627\u0644\u064f\u0647\u064f \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u064f\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u064b\u0627",22,"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0645\u064e\u0643\u0652\u0631\u064b\u0627 \u0643\u064f\u0628\u0651\u064e\u0627\u0631\u064b\u0627",23,"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f\u0646\u0651\u064e \u0622\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f\u0646\u0651\u064e \u0648\u064e\u062f\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0633\u064f\u0648\u064e\u0627\u0639\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0648\u062b\u064e \u0648\u064e\u064a\u064e\u0639\u064f\u0648\u0642\u064e \u0648\u064e\u0646\u064e\u0633\u0652\u0631\u064b\u0627",24,"\u0648\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u062f\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0636\u064e\u0644\u064e\u0627\u0644\u064b\u0627",25,"\u0645\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u0652 \u0623\u064f\u063a\u0652\u0631\u0650\u0642\u064f\u0648\u0627 \u0641\u064e\u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0648\u0627 \u0646\u064e\u0627\u0631\u064b\u0627 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u064b\u0627",26,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0646\u064f\u0648\u062d\u064c \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062f\u064e\u064a\u0651\u064e\u0627\u0631\u064b\u0627",27,"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0646\u0652 \u062a\u064e\u0630\u064e\u0631\u0652\u0647\u064f\u0645\u0652 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u0650\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u064e\u0627\u062c\u0650\u0631\u064b\u0627 \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064b\u0627",28,"\u0631\u064e\u0628\u0651\u0650 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u0650\u0645\u064e\u0646\u0652 \u062f\u064e\u062e\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u062a\u0650\u064a\u064e \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064b\u0627 \u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u062f\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u0627\u0631\u064b\u0627"],t.v)
B.aos=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0642\u064f\u0644\u0652 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0633\u0652\u062a\u064e\u0645\u064e\u0639\u064e \u0646\u064e\u0641\u064e\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0642\u064f\u0631\u0652\u0622\u0646\u064b\u0627 \u0639\u064e\u062c\u064e\u0628\u064b\u0627",2,"\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0631\u0651\u064f\u0634\u0652\u062f\u0650 \u0641\u064e\u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0646\u0652 \u0646\u064f\u0634\u0652\u0631\u0650\u0643\u064e \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",3,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u062c\u064e\u062f\u0651\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064b\u0627",4,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0633\u064e\u0641\u0650\u064a\u0647\u064f\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0637\u064e\u0637\u064b\u0627",5,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627",6,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u0650 \u064a\u064e\u0639\u064f\u0648\u0630\u064f\u0648\u0646\u064e \u0628\u0650\u0631\u0650\u062c\u064e\u0627\u0644\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0632\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u0652 \u0631\u064e\u0647\u064e\u0642\u064b\u0627",7,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0643\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064b\u0627",8,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0633\u0652\u0646\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0645\u064f\u0644\u0650\u0626\u064e\u062a\u0652 \u062d\u064e\u0631\u064e\u0633\u064b\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0634\u064f\u0647\u064f\u0628\u064b\u0627",9,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0642\u0652\u0639\u064f\u062f\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0642\u064e\u0627\u0639\u0650\u062f\u064e \u0644\u0650\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u0650 \u0627\u0644\u0652\u0622\u0646\u064e \u064a\u064e\u062c\u0650\u062f\u0652 \u0644\u064e\u0647\u064f \u0634\u0650\u0647\u064e\u0627\u0628\u064b\u0627 \u0631\u064e\u0635\u064e\u062f\u064b\u0627",10,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u062f\u0652\u0631\u0650\u064a \u0623\u064e\u0634\u064e\u0631\u0651\u064c \u0623\u064f\u0631\u0650\u064a\u062f\u064e \u0628\u0650\u0645\u064e\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0645\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0631\u064e\u0634\u064e\u062f\u064b\u0627",11,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0651\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u06d6 \u0643\u064f\u0646\u0651\u064e\u0627 \u0637\u064e\u0631\u064e\u0627\u0626\u0650\u0642\u064e \u0642\u0650\u062f\u064e\u062f\u064b\u0627",12,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u0646\u064f\u0639\u0652\u062c\u0650\u0632\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0646\u0652 \u0646\u064f\u0639\u0652\u062c\u0650\u0632\u064e\u0647\u064f \u0647\u064e\u0631\u064e\u0628\u064b\u0627",13,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0628\u064e\u062e\u0652\u0633\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0647\u064e\u0642\u064b\u0627",14,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u0637\u064f\u0648\u0646\u064e \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0644\u064e\u0645\u064e \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u062a\u064e\u062d\u064e\u0631\u0651\u064e\u0648\u0652\u0627 \u0631\u064e\u0634\u064e\u062f\u064b\u0627",15,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u0637\u064f\u0648\u0646\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062d\u064e\u0637\u064e\u0628\u064b\u0627",16,"\u0648\u064e\u0623\u064e\u0646\u0652 \u0644\u064e\u0648\u0650 \u0627\u0633\u0652\u062a\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u0631\u0650\u064a\u0642\u064e\u0629\u0650 \u0644\u064e\u0623\u064e\u0633\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0645\u064e\u0627\u0621\u064b \u063a\u064e\u062f\u064e\u0642\u064b\u0627",17,"\u0644\u0650\u0646\u064e\u0641\u0652\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064f\u0639\u0652\u0631\u0650\u0636\u0652 \u0639\u064e\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u064a\u064e\u0633\u0652\u0644\u064f\u0643\u0652\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0635\u064e\u0639\u064e\u062f\u064b\u0627",18,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0627 \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",19,"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0627\u0645\u064e \u0639\u064e\u0628\u0652\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0647\u064f \u0643\u064e\u0627\u062f\u064f\u0648\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u0650\u0628\u064e\u062f\u064b\u0627",20,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0639\u064f\u0648 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0623\u064f\u0634\u0652\u0631\u0650\u0643\u064f \u0628\u0650\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",21,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627 \u0623\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0636\u064e\u0631\u0651\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u064b\u0627",22,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0646\u0652 \u064a\u064f\u062c\u0650\u064a\u0631\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064c \u0648\u064e\u0644\u064e\u0646\u0652 \u0623\u064e\u062c\u0650\u062f\u064e \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0645\u064f\u0644\u0652\u062a\u064e\u062d\u064e\u062f\u064b\u0627",23,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u0627\u063a\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0635\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",24,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0641\u064e\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u0652\u0639\u064e\u0641\u064f \u0646\u064e\u0627\u0635\u0650\u0631\u064b\u0627 \u0648\u064e\u0623\u064e\u0642\u064e\u0644\u0651\u064f \u0639\u064e\u062f\u064e\u062f\u064b\u0627",25,"\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0652 \u0623\u064e\u062f\u0652\u0631\u0650\u064a \u0623\u064e\u0642\u064e\u0631\u0650\u064a\u0628\u064c \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u0652 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0645\u064e\u062f\u064b\u0627",26,"\u0639\u064e\u0627\u0644\u0650\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u0652\u0647\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u064a\u0652\u0628\u0650\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",27,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u0631\u0652\u062a\u064e\u0636\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u0644\u064f\u0643\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650 \u0631\u064e\u0635\u064e\u062f\u064b\u0627",28,"\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0652 \u0642\u064e\u062f\u0652 \u0623\u064e\u0628\u0652\u0644\u064e\u063a\u064f\u0648\u0627 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0627\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0623\u064e\u062d\u0652\u0635\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u064e\u062f\u064e\u062f\u064b\u0627"],t.v)
B.aoS=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0632\u0651\u064e\u0645\u0651\u0650\u0644\u064f",2,"\u0642\u064f\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",3,"\u0646\u0650\u0635\u0652\u0641\u064e\u0647\u064f \u0623\u064e\u0648\u0650 \u0627\u0646\u0652\u0642\u064f\u0635\u0652 \u0645\u0650\u0646\u0652\u0647\u064f \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",4,"\u0623\u064e\u0648\u0652 \u0632\u0650\u062f\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0631\u064e\u062a\u0651\u0650\u0644\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u062a\u064e\u0631\u0652\u062a\u0650\u064a\u0644\u064b\u0627",5,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0646\u064f\u0644\u0652\u0642\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u062b\u064e\u0642\u0650\u064a\u0644\u064b\u0627",6,"\u0625\u0650\u0646\u0651\u064e \u0646\u064e\u0627\u0634\u0650\u0626\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0647\u0650\u064a\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0648\u064e\u0637\u0652\u0626\u064b\u0627 \u0648\u064e\u0623\u064e\u0642\u0652\u0648\u064e\u0645\u064f \u0642\u0650\u064a\u0644\u064b\u0627",7,"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0633\u064e\u0628\u0652\u062d\u064b\u0627 \u0637\u064e\u0648\u0650\u064a\u0644\u064b\u0627",8,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0650 \u0627\u0633\u0652\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u0628\u064e\u062a\u0651\u064e\u0644\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064e\u0628\u0652\u062a\u0650\u064a\u0644\u064b\u0627",9,"\u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0641\u064e\u0627\u062a\u0651\u064e\u062e\u0650\u0630\u0652\u0647\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",10,"\u0648\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u0647\u0652\u062c\u064f\u0631\u0652\u0647\u064f\u0645\u0652 \u0647\u064e\u062c\u0652\u0631\u064b\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u064b\u0627",11,"\u0648\u064e\u0630\u064e\u0631\u0652\u0646\u0650\u064a \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0639\u0652\u0645\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0647\u0651\u0650\u0644\u0652\u0647\u064f\u0645\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",12,"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0643\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u062c\u064e\u062d\u0650\u064a\u0645\u064b\u0627",13,"\u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064b\u0627 \u0630\u064e\u0627 \u063a\u064f\u0635\u0651\u064e\u0629\u064d \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",14,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0631\u0652\u062c\u064f\u0641\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u062b\u0650\u064a\u0628\u064b\u0627 \u0645\u064e\u0647\u0650\u064a\u0644\u064b\u0627",15,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0634\u064e\u0627\u0647\u0650\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",16,"\u0641\u064e\u0639\u064e\u0635\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u062e\u0652\u0630\u064b\u0627 \u0648\u064e\u0628\u0650\u064a\u0644\u064b\u0627",17,"\u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0641\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u0652\u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u064e \u0634\u0650\u064a\u0628\u064b\u0627",18,"\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0645\u064f\u0646\u0652\u0641\u064e\u0637\u0650\u0631\u064c \u0628\u0650\u0647\u0650 \u06da \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u0652\u062f\u064f\u0647\u064f \u0645\u064e\u0641\u0652\u0639\u064f\u0648\u0644\u064b\u0627",19,u.I,20,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0623\u064e\u062f\u0652\u0646\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u062b\u064f\u0644\u064f\u062b\u064e\u064a\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0646\u0650\u0635\u0652\u0641\u064e\u0647\u064f \u0648\u064e\u062b\u064f\u0644\u064f\u062b\u064e\u0647\u064f \u0648\u064e\u0637\u064e\u0627\u0626\u0650\u0641\u064e\u0629\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0642\u064e\u062f\u0651\u0650\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u062a\u064f\u062d\u0652\u0635\u064f\u0648\u0647\u064f \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0642\u0652\u0631\u064e\u0621\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064e\u064a\u064e\u0633\u0651\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646\u0652 \u0633\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0631\u0652\u0636\u064e\u0649\u0670 \u06d9 \u0648\u064e\u0622\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u064a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d9 \u0648\u064e\u0622\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0641\u064e\u0627\u0642\u0652\u0631\u064e\u0621\u064f\u0648\u0627 \u0645\u064e\u0627 \u062a\u064e\u064a\u064e\u0633\u0651\u064e\u0631\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0642\u0652\u0631\u0650\u0636\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u0652\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627 \u0644\u0650\u0623\u064e\u0646\u0652\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0648\u064e\u0623\u064e\u0639\u0652\u0638\u064e\u0645\u064e \u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u06da \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c"],t.v)
B.as6=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062f\u0651\u064e\u062b\u0651\u0650\u0631\u064f",2,"\u0642\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u0646\u0652\u0630\u0650\u0631\u0652",3,"\u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0652",4,"\u0648\u064e\u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064e \u0641\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u0652",5,"\u0648\u064e\u0627\u0644\u0631\u0651\u064f\u062c\u0652\u0632\u064e \u0641\u064e\u0627\u0647\u0652\u062c\u064f\u0631\u0652",6,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u0646\u064f\u0646\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u0643\u0652\u062b\u0650\u0631\u064f",7,"\u0648\u064e\u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652",8,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0642\u0650\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0642\u064f\u0648\u0631\u0650",9,"\u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0648\u0652\u0645\u064c \u0639\u064e\u0633\u0650\u064a\u0631\u064c",10,"\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u0652\u0631\u064f \u064a\u064e\u0633\u0650\u064a\u0631\u064d",11,"\u0630\u064e\u0631\u0652\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f \u0648\u064e\u062d\u0650\u064a\u062f\u064b\u0627",12,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0627\u0644\u064b\u0627 \u0645\u064e\u0645\u0652\u062f\u064f\u0648\u062f\u064b\u0627",13,"\u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0634\u064f\u0647\u064f\u0648\u062f\u064b\u0627",14,"\u0648\u064e\u0645\u064e\u0647\u0651\u064e\u062f\u0652\u062a\u064f \u0644\u064e\u0647\u064f \u062a\u064e\u0645\u0652\u0647\u0650\u064a\u062f\u064b\u0627",15,"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0632\u0650\u064a\u062f\u064e",16,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u0646\u0650\u064a\u062f\u064b\u0627",17,"\u0633\u064e\u0623\u064f\u0631\u0652\u0647\u0650\u0642\u064f\u0647\u064f \u0635\u064e\u0639\u064f\u0648\u062f\u064b\u0627",18,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0641\u064e\u0643\u0651\u064e\u0631\u064e \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e",19,"\u0641\u064e\u0642\u064f\u062a\u0650\u0644\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u064e",20,"\u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062a\u0650\u0644\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u064e",21,"\u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0638\u064e\u0631\u064e",22,"\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0628\u064e\u0633\u064e \u0648\u064e\u0628\u064e\u0633\u064e\u0631\u064e",23,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062f\u0652\u0628\u064e\u0631\u064e \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e",24,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u064a\u064f\u0624\u0652\u062b\u064e\u0631\u064f",25,"\u0625\u0650\u0646\u0652 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u0652\u0644\u064f \u0627\u0644\u0652\u0628\u064e\u0634\u064e\u0631\u0650",26,"\u0633\u064e\u0623\u064f\u0635\u0652\u0644\u0650\u064a\u0647\u0650 \u0633\u064e\u0642\u064e\u0631\u064e",27,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0633\u064e\u0642\u064e\u0631\u064f",28,"\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0642\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f",29,"\u0644\u064e\u0648\u0651\u064e\u0627\u062d\u064e\u0629\u064c \u0644\u0650\u0644\u0652\u0628\u064e\u0634\u064e\u0631\u0650",30,"\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062a\u0650\u0633\u0652\u0639\u064e\u0629\u064e \u0639\u064e\u0634\u064e\u0631\u064e",31,"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064b \u06d9 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u0650\u062f\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0644\u0650\u064a\u064e\u0633\u0652\u062a\u064e\u064a\u0652\u0642\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u064a\u064e\u0632\u0652\u062f\u064e\u0627\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u064a\u0645\u064e\u0627\u0646\u064b\u0627 \u06d9 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u06d9 \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0631\u064e\u0636\u064c \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u062c\u064f\u0646\u064f\u0648\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0652\u0628\u064e\u0634\u064e\u0631\u0650",32,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u0650",33,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u0652 \u0623\u064e\u062f\u0652\u0628\u064e\u0631\u064e",34,"\u0648\u064e\u0627\u0644\u0635\u0651\u064f\u0628\u0652\u062d\u0650 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0633\u0652\u0641\u064e\u0631\u064e",35,"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0644\u0652\u0643\u064f\u0628\u064e\u0631\u0650",36,"\u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627 \u0644\u0650\u0644\u0652\u0628\u064e\u0634\u064e\u0631\u0650",37,"\u0644\u0650\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u062a\u064e\u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0623\u064e\u0648\u0652 \u064a\u064e\u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e",38,"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u0652 \u0631\u064e\u0647\u0650\u064a\u0646\u064e\u0629\u064c",39,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u0650",40,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",41,"\u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",42,"\u0645\u064e\u0627 \u0633\u064e\u0644\u064e\u0643\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0633\u064e\u0642\u064e\u0631\u064e",43,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0645\u0652 \u0646\u064e\u0643\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u0646\u064e",44,"\u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0643\u064f \u0646\u064f\u0637\u0652\u0639\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064f\u0648\u0636\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0626\u0650\u0636\u0650\u064a\u0646\u064e",46,"\u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",47,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0623\u064e\u062a\u064e\u0627\u0646\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u064f",48,"\u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u0641\u064e\u0627\u0639\u064e\u0629\u064f \u0627\u0644\u0634\u0651\u064e\u0627\u0641\u0650\u0639\u0650\u064a\u0646\u064e",49,"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u062a\u0651\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u0650 \u0645\u064f\u0639\u0652\u0631\u0650\u0636\u0650\u064a\u0646\u064e",50,"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u062d\u064f\u0645\u064f\u0631\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0646\u0652\u0641\u0650\u0631\u064e\u0629\u064c",51,"\u0641\u064e\u0631\u0651\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0633\u0652\u0648\u064e\u0631\u064e\u0629\u064d",52,"\u0628\u064e\u0644\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0643\u064f\u0644\u0651\u064f \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u064e\u0649\u0670 \u0635\u064f\u062d\u064f\u0641\u064b\u0627 \u0645\u064f\u0646\u064e\u0634\u0651\u064e\u0631\u064e\u0629\u064b",53,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0628\u064e\u0644\u0652 \u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e",54,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064c",55,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f",56,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u0650"],t.v)
B.aoI=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650",2,"\u0648\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u0650 \u0627\u0644\u0644\u0651\u064e\u0648\u0651\u064e\u0627\u0645\u064e\u0629\u0650",3,"\u0623\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0644\u0651\u064e\u0646\u0652 \u0646\u064e\u062c\u0652\u0645\u064e\u0639\u064e \u0639\u0650\u0638\u064e\u0627\u0645\u064e\u0647\u064f",4,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0627\u062f\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0646\u064f\u0633\u064e\u0648\u0651\u0650\u064a\u064e \u0628\u064e\u0646\u064e\u0627\u0646\u064e\u0647\u064f",5,"\u0628\u064e\u0644\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0644\u0650\u064a\u064e\u0641\u0652\u062c\u064f\u0631\u064e \u0623\u064e\u0645\u064e\u0627\u0645\u064e\u0647\u064f",6,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650",7,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0631\u0650\u0642\u064e \u0627\u0644\u0652\u0628\u064e\u0635\u064e\u0631\u064f",8,"\u0648\u064e\u062e\u064e\u0633\u064e\u0641\u064e \u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f",9,"\u0648\u064e\u062c\u064f\u0645\u0650\u0639\u064e \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f",10,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0623\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0641\u064e\u0631\u0651\u064f",11,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0627 \u0648\u064e\u0632\u064e\u0631\u064e",12,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u064e\u0631\u0651\u064f",13,"\u064a\u064f\u0646\u064e\u0628\u0651\u064e\u0623\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e",14,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u0629\u064c",15,"\u0648\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0627\u0630\u0650\u064a\u0631\u064e\u0647\u064f",16,"\u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0643\u0652 \u0628\u0650\u0647\u0650 \u0644\u0650\u0633\u064e\u0627\u0646\u064e\u0643\u064e \u0644\u0650\u062a\u064e\u0639\u0652\u062c\u064e\u0644\u064e \u0628\u0650\u0647\u0650",17,"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u062c\u064e\u0645\u0652\u0639\u064e\u0647\u064f \u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064e\u0647\u064f",18,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u064e\u0627\u062a\u0651\u064e\u0628\u0650\u0639\u0652 \u0642\u064f\u0631\u0652\u0622\u0646\u064e\u0647\u064f",19,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u0646\u064e\u0647\u064f",20,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u0652 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e",21,"\u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e",22,"\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0646\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u064c",23,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0646\u064e\u0627\u0638\u0650\u0631\u064e\u0629\u064c",24,"\u0648\u064e\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0628\u064e\u0627\u0633\u0650\u0631\u064e\u0629\u064c",25,"\u062a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0641\u0652\u0639\u064e\u0644\u064e \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0627\u0642\u0650\u0631\u064e\u0629\u064c",26,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0627\u0644\u062a\u0651\u064e\u0631\u064e\u0627\u0642\u0650\u064a\u064e",27,"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0645\u064e\u0646\u0652 \u06dc \u0631\u064e\u0627\u0642\u064d",28,"\u0648\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0641\u0650\u0631\u064e\u0627\u0642\u064f",29,"\u0648\u064e\u0627\u0644\u0652\u062a\u064e\u0641\u0651\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0642\u064f \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u0627\u0642\u0650",30,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0642\u064f",31,"\u0641\u064e\u0644\u064e\u0627 \u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0648\u064e\u0644\u064e\u0627 \u0635\u064e\u0644\u0651\u064e\u0649\u0670",32,"\u0648\u064e\u0644\u064e\u0640\u0670\u0643\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",33,"\u062b\u064f\u0645\u0651\u064e \u0630\u064e\u0647\u064e\u0628\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u064a\u064e\u062a\u064e\u0645\u064e\u0637\u0651\u064e\u0649\u0670",34,"\u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0644\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670",35,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0644\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u0648\u0652\u0644\u064e\u0649\u0670",36,"\u0623\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062a\u0652\u0631\u064e\u0643\u064e \u0633\u064f\u062f\u064b\u0649",37,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0645\u064e\u0646\u0650\u064a\u0651\u064d \u064a\u064f\u0645\u0652\u0646\u064e\u0649\u0670",38,"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064b \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670",39,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0627\u0644\u0632\u0651\u064e\u0648\u0652\u062c\u064e\u064a\u0652\u0646\u0650 \u0627\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670",40,"\u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u064e\u0627\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670"],t.v)
B.arZ=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u0650 \u062d\u0650\u064a\u0646\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064e\u0647\u0652\u0631\u0650 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0645\u064e\u0630\u0652\u0643\u064f\u0648\u0631\u064b\u0627",2,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u0623\u064e\u0645\u0652\u0634\u064e\u0627\u062c\u064d \u0646\u064e\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u0647\u0650 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",3,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u0634\u064e\u0627\u0643\u0650\u0631\u064b\u0627 \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",4,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0639\u0652\u062a\u064e\u062f\u0652\u0646\u064e\u0627 \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0633\u064e\u0644\u064e\u0627\u0633\u0650\u0644\u064e \u0648\u064e\u0623\u064e\u063a\u0652\u0644\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",5,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u064e \u064a\u064e\u0634\u0652\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652 \u0643\u064e\u0623\u0652\u0633\u064d \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064e\u0627 \u0643\u064e\u0627\u0641\u064f\u0648\u0631\u064b\u0627",6,"\u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u064a\u064e\u0634\u0652\u0631\u064e\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0641\u064e\u062c\u0651\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u0641\u0652\u062c\u0650\u064a\u0631\u064b\u0627",7,"\u064a\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0630\u0652\u0631\u0650 \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0643\u064e\u0627\u0646\u064e \u0634\u064e\u0631\u0651\u064f\u0647\u064f \u0645\u064f\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0631\u064b\u0627",8,"\u0648\u064e\u064a\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064f\u0628\u0651\u0650\u0647\u0650 \u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064b\u0627 \u0648\u064e\u064a\u064e\u062a\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u0633\u0650\u064a\u0631\u064b\u0627",9,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0643\u064f\u0645\u0652 \u0644\u0650\u0648\u064e\u062c\u0652\u0647\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0648\u064e\u0644\u064e\u0627 \u0634\u064f\u0643\u064f\u0648\u0631\u064b\u0627",10,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u064e\u0628\u064f\u0648\u0633\u064b\u0627 \u0642\u064e\u0645\u0652\u0637\u064e\u0631\u0650\u064a\u0631\u064b\u0627",11,"\u0641\u064e\u0648\u064e\u0642\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0631\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0648\u064e\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0646\u064e\u0636\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0633\u064f\u0631\u064f\u0648\u0631\u064b\u0627",12,"\u0648\u064e\u062c\u064e\u0632\u064e\u0627\u0647\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u062c\u064e\u0646\u0651\u064e\u0629\u064b \u0648\u064e\u062d\u064e\u0631\u0650\u064a\u0631\u064b\u0627",13,"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0626\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0634\u064e\u0645\u0652\u0633\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0632\u064e\u0645\u0652\u0647\u064e\u0631\u0650\u064a\u0631\u064b\u0627",14,"\u0648\u064e\u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0638\u0650\u0644\u064e\u0627\u0644\u064f\u0647\u064e\u0627 \u0648\u064e\u0630\u064f\u0644\u0651\u0650\u0644\u064e\u062a\u0652 \u0642\u064f\u0637\u064f\u0648\u0641\u064f\u0647\u064e\u0627 \u062a\u064e\u0630\u0652\u0644\u0650\u064a\u0644\u064b\u0627",15,"\u0648\u064e\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0622\u0646\u0650\u064a\u064e\u0629\u064d \u0645\u0650\u0646\u0652 \u0641\u0650\u0636\u0651\u064e\u0629\u064d \u0648\u064e\u0623\u064e\u0643\u0652\u0648\u064e\u0627\u0628\u064d \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e\u0627",16,"\u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u0636\u0651\u064e\u0629\u064d \u0642\u064e\u062f\u0651\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064b\u0627",17,"\u0648\u064e\u064a\u064f\u0633\u0652\u0642\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0623\u0652\u0633\u064b\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064e\u0627 \u0632\u064e\u0646\u0652\u062c\u064e\u0628\u0650\u064a\u0644\u064b\u0627",18,"\u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064f\u0633\u064e\u0645\u0651\u064e\u0649\u0670 \u0633\u064e\u0644\u0652\u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",19,"\u0648\u064e\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u0650\u0644\u0652\u062f\u064e\u0627\u0646\u064c \u0645\u064f\u062e\u064e\u0644\u0651\u064e\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0633\u0650\u0628\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0644\u064f\u0624\u0652\u0644\u064f\u0624\u064b\u0627 \u0645\u064e\u0646\u0652\u062b\u064f\u0648\u0631\u064b\u0627",20,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u062b\u064e\u0645\u0651\u064e \u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0646\u064e\u0639\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u0645\u064f\u0644\u0652\u0643\u064b\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",21,"\u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u062b\u0650\u064a\u064e\u0627\u0628\u064f \u0633\u064f\u0646\u0652\u062f\u064f\u0633\u064d \u062e\u064f\u0636\u0652\u0631\u064c \u0648\u064e\u0625\u0650\u0633\u0652\u062a\u064e\u0628\u0652\u0631\u064e\u0642\u064c \u06d6 \u0648\u064e\u062d\u064f\u0644\u0651\u064f\u0648\u0627 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u0636\u0651\u064e\u0629\u064d \u0648\u064e\u0633\u064e\u0642\u064e\u0627\u0647\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u0631\u064e\u0627\u0628\u064b\u0627 \u0637\u064e\u0647\u064f\u0648\u0631\u064b\u0627",22,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0639\u0652\u064a\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0634\u0652\u0643\u064f\u0648\u0631\u064b\u0627",23,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u062a\u064e\u0646\u0652\u0632\u0650\u064a\u0644\u064b\u0627",24,"\u0641\u064e\u0627\u0635\u0652\u0628\u0650\u0631\u0652 \u0644\u0650\u062d\u064f\u0643\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0622\u062b\u0650\u0645\u064b\u0627 \u0623\u064e\u0648\u0652 \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",25,"\u0648\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u0650 \u0627\u0633\u0652\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u064f\u0643\u0652\u0631\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",26,"\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0641\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u0652\u0647\u064f \u0644\u064e\u064a\u0652\u0644\u064b\u0627 \u0637\u064e\u0648\u0650\u064a\u0644\u064b\u0627",27,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0631\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u062b\u064e\u0642\u0650\u064a\u0644\u064b\u0627",28,"\u0646\u064e\u062d\u0652\u0646\u064f \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0634\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627 \u0623\u064e\u0633\u0652\u0631\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0634\u0650\u0626\u0652\u0646\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0623\u064e\u0645\u0652\u062b\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u062a\u064e\u0628\u0652\u062f\u0650\u064a\u0644\u064b\u0627",29,u.I,30,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",31,"\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u06da \u0648\u064e\u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627"],t.v)
B.asb=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064e\u0627\u062a\u0650 \u0639\u064f\u0631\u0652\u0641\u064b\u0627",2,"\u0641\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0635\u0650\u0641\u064e\u0627\u062a\u0650 \u0639\u064e\u0635\u0652\u0641\u064b\u0627",3,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0634\u0650\u0631\u064e\u0627\u062a\u0650 \u0646\u064e\u0634\u0652\u0631\u064b\u0627",4,"\u0641\u064e\u0627\u0644\u0652\u0641\u064e\u0627\u0631\u0650\u0642\u064e\u0627\u062a\u0650 \u0641\u064e\u0631\u0652\u0642\u064b\u0627",5,"\u0641\u064e\u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u062a\u0650 \u0630\u0650\u0643\u0652\u0631\u064b\u0627",6,"\u0639\u064f\u0630\u0652\u0631\u064b\u0627 \u0623\u064e\u0648\u0652 \u0646\u064f\u0630\u0652\u0631\u064b\u0627",7,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u064e\u0627\u0642\u0650\u0639\u064c",8,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0637\u064f\u0645\u0650\u0633\u064e\u062a\u0652",9,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0641\u064f\u0631\u0650\u062c\u064e\u062a\u0652",10,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0646\u064f\u0633\u0650\u0641\u064e\u062a\u0652",11,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0623\u064f\u0642\u0651\u0650\u062a\u064e\u062a\u0652",12,"\u0644\u0650\u0623\u064e\u064a\u0651\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0623\u064f\u062c\u0651\u0650\u0644\u064e\u062a\u0652",13,"\u0644\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650",14,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650",15,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",16,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0647\u0652\u0644\u0650\u0643\u0650 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",17,"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u062a\u0652\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",18,"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",19,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",20,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u062e\u0652\u0644\u064f\u0642\u0652\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u0645\u064e\u0647\u0650\u064a\u0646\u064d",21,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0642\u064e\u0631\u064e\u0627\u0631\u064d \u0645\u064e\u0643\u0650\u064a\u0646\u064d",22,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u064e\u0631\u064d \u0645\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",23,"\u0641\u064e\u0642\u064e\u062f\u064e\u0631\u0652\u0646\u064e\u0627 \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u062f\u0650\u0631\u064f\u0648\u0646\u064e",24,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",25,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0643\u0650\u0641\u064e\u0627\u062a\u064b\u0627",26,"\u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064b \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064b\u0627",27,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0627\u0633\u0650\u064a\u064e \u0634\u064e\u0627\u0645\u0650\u062e\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0633\u0652\u0642\u064e\u064a\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u064e\u0627\u0621\u064b \u0641\u064f\u0631\u064e\u0627\u062a\u064b\u0627",28,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",29,"\u0627\u0646\u0652\u0637\u064e\u0644\u0650\u0642\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",30,"\u0627\u0646\u0652\u0637\u064e\u0644\u0650\u0642\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0638\u0650\u0644\u0651\u064d \u0630\u0650\u064a \u062b\u064e\u0644\u064e\u0627\u062b\u0650 \u0634\u064f\u0639\u064e\u0628\u064d",31,"\u0644\u064e\u0627 \u0638\u064e\u0644\u0650\u064a\u0644\u064d \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e\u0628\u0650",32,"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0631\u0652\u0645\u0650\u064a \u0628\u0650\u0634\u064e\u0631\u064e\u0631\u064d \u0643\u064e\u0627\u0644\u0652\u0642\u064e\u0635\u0652\u0631\u0650",33,"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u062c\u0650\u0645\u064e\u0627\u0644\u064e\u062a\u064c \u0635\u064f\u0641\u0652\u0631\u064c",34,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",35,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0637\u0650\u0642\u064f\u0648\u0646\u064e",36,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0630\u064e\u0646\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u064a\u064e\u0639\u0652\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0646\u064e",37,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",38,"\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650 \u06d6 \u062c\u064e\u0645\u064e\u0639\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",39,"\u0641\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0643\u064e\u064a\u0652\u062f\u064c \u0641\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650",40,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",41,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0638\u0650\u0644\u064e\u0627\u0644\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",42,"\u0648\u064e\u0641\u064e\u0648\u064e\u0627\u0643\u0650\u0647\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u0652\u062a\u064e\u0647\u064f\u0648\u0646\u064e",43,u.bg,44,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",45,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",46,"\u0643\u064f\u0644\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",47,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",48,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0631\u0652\u0643\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u0643\u064e\u0639\u064f\u0648\u0646\u064e",49,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",50,"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e"],t.v)
B.aoJ=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0639\u064e\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",2,"\u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u064e\u0625\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",4,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",5,"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",6,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0645\u0650\u0647\u064e\u0627\u062f\u064b\u0627",7,"\u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u0652\u062a\u064e\u0627\u062f\u064b\u0627",8,"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627",9,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0628\u064e\u0627\u062a\u064b\u0627",10,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u064b\u0627",11,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064e\u0639\u064e\u0627\u0634\u064b\u0627",12,"\u0648\u064e\u0628\u064e\u0646\u064e\u064a\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u0652 \u0633\u064e\u0628\u0652\u0639\u064b\u0627 \u0634\u0650\u062f\u064e\u0627\u062f\u064b\u0627",13,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0633\u0650\u0631\u064e\u0627\u062c\u064b\u0627 \u0648\u064e\u0647\u0651\u064e\u0627\u062c\u064b\u0627",14,"\u0648\u064e\u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0639\u0652\u0635\u0650\u0631\u064e\u0627\u062a\u0650 \u0645\u064e\u0627\u0621\u064b \u062b\u064e\u062c\u0651\u064e\u0627\u062c\u064b\u0627",15,"\u0644\u0650\u0646\u064f\u062e\u0652\u0631\u0650\u062c\u064e \u0628\u0650\u0647\u0650 \u062d\u064e\u0628\u0651\u064b\u0627 \u0648\u064e\u0646\u064e\u0628\u064e\u0627\u062a\u064b\u0627",16,"\u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0623\u064e\u0644\u0652\u0641\u064e\u0627\u0641\u064b\u0627",17,"\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0641\u064e\u0635\u0652\u0644\u0650 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u064a\u0642\u064e\u0627\u062a\u064b\u0627",18,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u0652\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0623\u064e\u0641\u0652\u0648\u064e\u0627\u062c\u064b\u0627",19,"\u0648\u064e\u0641\u064f\u062a\u0650\u062d\u064e\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064b\u0627",20,"\u0648\u064e\u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0633\u064e\u0631\u064e\u0627\u0628\u064b\u0627",21,"\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0645\u0650\u0631\u0652\u0635\u064e\u0627\u062f\u064b\u0627",22,"\u0644\u0650\u0644\u0637\u0651\u064e\u0627\u063a\u0650\u064a\u0646\u064e \u0645\u064e\u0622\u0628\u064b\u0627",23,"\u0644\u064e\u0627\u0628\u0650\u062b\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u062d\u0652\u0642\u064e\u0627\u0628\u064b\u0627",24,"\u0644\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u064e\u0631\u0652\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0631\u064e\u0627\u0628\u064b\u0627",25,"\u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u0645\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u063a\u064e\u0633\u0651\u064e\u0627\u0642\u064b\u0627",26,"\u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0648\u0650\u0641\u064e\u0627\u0642\u064b\u0627",27,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u0652\u062c\u064f\u0648\u0646\u064e \u062d\u0650\u0633\u064e\u0627\u0628\u064b\u0627",28,"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0643\u0650\u0630\u0651\u064e\u0627\u0628\u064b\u0627",29,"\u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u062d\u0652\u0635\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0643\u0650\u062a\u064e\u0627\u0628\u064b\u0627",30,"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0646\u0652 \u0646\u064e\u0632\u0650\u064a\u062f\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627",31,"\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0645\u064e\u0641\u064e\u0627\u0632\u064b\u0627",32,"\u062d\u064e\u062f\u064e\u0627\u0626\u0650\u0642\u064e \u0648\u064e\u0623\u064e\u0639\u0652\u0646\u064e\u0627\u0628\u064b\u0627",33,"\u0648\u064e\u0643\u064e\u0648\u064e\u0627\u0639\u0650\u0628\u064e \u0623\u064e\u062a\u0652\u0631\u064e\u0627\u0628\u064b\u0627",34,"\u0648\u064e\u0643\u064e\u0623\u0652\u0633\u064b\u0627 \u062f\u0650\u0647\u064e\u0627\u0642\u064b\u0627",35,"\u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u0652\u0648\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u0630\u0651\u064e\u0627\u0628\u064b\u0627",36,"\u062c\u064e\u0632\u064e\u0627\u0621\u064b \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0637\u064e\u0627\u0621\u064b \u062d\u0650\u0633\u064e\u0627\u0628\u064b\u0627",37,"\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u0645\u0652\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u062e\u0650\u0637\u064e\u0627\u0628\u064b\u0627",38,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0635\u064e\u0641\u0651\u064b\u0627 \u06d6 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0635\u064e\u0648\u064e\u0627\u0628\u064b\u0627",39,"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u06d6 \u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0645\u064e\u0622\u0628\u064b\u0627",40,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0630\u064e\u0631\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u064f \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u064a\u064e\u062f\u064e\u0627\u0647\u064f \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f \u062a\u064f\u0631\u064e\u0627\u0628\u064b\u0627"],t.v)
B.abT=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0632\u0650\u0639\u064e\u0627\u062a\u0650 \u063a\u064e\u0631\u0652\u0642\u064b\u0627",2,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0627\u0634\u0650\u0637\u064e\u0627\u062a\u0650 \u0646\u064e\u0634\u0652\u0637\u064b\u0627",3,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0628\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u0628\u0652\u062d\u064b\u0627",4,"\u0641\u064e\u0627\u0644\u0633\u0651\u064e\u0627\u0628\u0650\u0642\u064e\u0627\u062a\u0650 \u0633\u064e\u0628\u0652\u0642\u064b\u0627",5,"\u0641\u064e\u0627\u0644\u0652\u0645\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064e\u0627\u062a\u0650 \u0623\u064e\u0645\u0652\u0631\u064b\u0627",6,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0631\u0652\u062c\u064f\u0641\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u062c\u0650\u0641\u064e\u0629\u064f",7,"\u062a\u064e\u062a\u0652\u0628\u064e\u0639\u064f\u0647\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u0627\u062f\u0650\u0641\u064e\u0629\u064f",8,"\u0642\u064f\u0644\u064f\u0648\u0628\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0648\u064e\u0627\u062c\u0650\u0641\u064e\u0629\u064c",9,"\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f\u0647\u064e\u0627 \u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0629\u064c",10,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0631\u0652\u062f\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0627\u0641\u0650\u0631\u064e\u0629\u0650",11,"\u0623\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0627\u0645\u064b\u0627 \u0646\u064e\u062e\u0650\u0631\u064e\u0629\u064b",12,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u062a\u0650\u0644\u0652\u0643\u064e \u0625\u0650\u0630\u064b\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u064c \u062e\u064e\u0627\u0633\u0650\u0631\u064e\u0629\u064c",13,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0632\u064e\u062c\u0652\u0631\u064e\u0629\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064c",14,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u0652 \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u0627\u0647\u0650\u0631\u064e\u0629\u0650",15,"\u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670",16,"\u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u0627\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u0650 \u0637\u064f\u0648\u064b\u0649",17,"\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0637\u064e\u063a\u064e\u0649\u0670",18,"\u0641\u064e\u0642\u064f\u0644\u0652 \u0647\u064e\u0644\u0652 \u0644\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",19,"\u0648\u064e\u0623\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",20,"\u0641\u064e\u0623\u064e\u0631\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0622\u064a\u064e\u0629\u064e \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649\u0670",21,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u0639\u064e\u0635\u064e\u0649\u0670",22,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062f\u0652\u0628\u064e\u0631\u064e \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670",23,"\u0641\u064e\u062d\u064e\u0634\u064e\u0631\u064e \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670",24,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670",25,"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0643\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",26,"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u0652\u0631\u064e\u0629\u064b \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",27,"\u0623\u064e\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062e\u064e\u0644\u0652\u0642\u064b\u0627 \u0623\u064e\u0645\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u06da \u0628\u064e\u0646\u064e\u0627\u0647\u064e\u0627",28,"\u0631\u064e\u0641\u064e\u0639\u064e \u0633\u064e\u0645\u0652\u0643\u064e\u0647\u064e\u0627 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0627\u0647\u064e\u0627",29,"\u0648\u064e\u0623\u064e\u063a\u0652\u0637\u064e\u0634\u064e \u0644\u064e\u064a\u0652\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0636\u064f\u062d\u064e\u0627\u0647\u064e\u0627",30,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0628\u064e\u0639\u0652\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062f\u064e\u062d\u064e\u0627\u0647\u064e\u0627",31,"\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u064e\u0627\u0621\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0631\u0652\u0639\u064e\u0627\u0647\u064e\u0627",32,"\u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u0652\u0633\u064e\u0627\u0647\u064e\u0627",33,"\u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650\u0643\u064f\u0645\u0652",34,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0650 \u0627\u0644\u0637\u0651\u064e\u0627\u0645\u0651\u064e\u0629\u064f \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649\u0670",35,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u064e\u0627 \u0633\u064e\u0639\u064e\u0649\u0670",36,"\u0648\u064e\u0628\u064f\u0631\u0651\u0650\u0632\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0644\u0650\u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u064e\u0649\u0670",37,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0637\u064e\u063a\u064e\u0649\u0670",38,"\u0648\u064e\u0622\u062b\u064e\u0631\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627",39,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064e \u0647\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064e\u0623\u0652\u0648\u064e\u0649\u0670",40,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0648\u064e\u0646\u064e\u0647\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0647\u064e\u0648\u064e\u0649\u0670",41,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0647\u0650\u064a\u064e \u0627\u0644\u0652\u0645\u064e\u0623\u0652\u0648\u064e\u0649\u0670",42,"\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0631\u0652\u0633\u064e\u0627\u0647\u064e\u0627",43,"\u0641\u0650\u064a\u0645\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u0650\u0646\u0652 \u0630\u0650\u0643\u0652\u0631\u064e\u0627\u0647\u064e\u0627",44,"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064f\u0646\u0652\u062a\u064e\u0647\u064e\u0627\u0647\u064e\u0627",45,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064f\u0646\u0652\u0630\u0650\u0631\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0627\u0647\u064e\u0627",46,"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0652\u0628\u064e\u062b\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0634\u0650\u064a\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u0636\u064f\u062d\u064e\u0627\u0647\u064e\u0627"],t.v)
B.asD=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0639\u064e\u0628\u064e\u0633\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",2,"\u0623\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0649\u0670",3,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u0652\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0632\u0651\u064e\u0643\u0651\u064e\u0649\u0670",4,"\u0623\u064e\u0648\u0652 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0641\u064e\u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064e\u0647\u064f \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670",5,"\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0646\u064e\u0649\u0670",6,"\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0644\u064e\u0647\u064f \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0649\u0670",7,"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0632\u0651\u064e\u0643\u0651\u064e\u0649\u0670",8,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062c\u064e\u0627\u0621\u064e\u0643\u064e \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670",9,"\u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",10,"\u0641\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u0639\u064e\u0646\u0652\u0647\u064f \u062a\u064e\u0644\u064e\u0647\u0651\u064e\u0649\u0670",11,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0630\u0652\u0643\u0650\u0631\u064e\u0629\u064c",12,"\u0641\u064e\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f",13,"\u0641\u0650\u064a \u0635\u064f\u062d\u064f\u0641\u064d \u0645\u064f\u0643\u064e\u0631\u0651\u064e\u0645\u064e\u0629\u064d",14,"\u0645\u064e\u0631\u0652\u0641\u064f\u0648\u0639\u064e\u0629\u064d \u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064d",15,"\u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a \u0633\u064e\u0641\u064e\u0631\u064e\u0629\u064d",16,"\u0643\u0650\u0631\u064e\u0627\u0645\u064d \u0628\u064e\u0631\u064e\u0631\u064e\u0629\u064d",17,"\u0642\u064f\u062a\u0650\u0644\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u064e\u0627 \u0623\u064e\u0643\u0652\u0641\u064e\u0631\u064e\u0647\u064f",18,"\u0645\u0650\u0646\u0652 \u0623\u064e\u064a\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f",19,"\u0645\u0650\u0646\u0652 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f",20,"\u062b\u064f\u0645\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u064a\u064e\u0633\u0651\u064e\u0631\u064e\u0647\u064f",21,"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0642\u0652\u0628\u064e\u0631\u064e\u0647\u064f",22,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0623\u064e\u0646\u0652\u0634\u064e\u0631\u064e\u0647\u064f",23,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u0652\u0636\u0650 \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f",24,"\u0641\u064e\u0644\u0652\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u0650 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650\u0647\u0650",25,"\u0623\u064e\u0646\u0651\u064e\u0627 \u0635\u064e\u0628\u064e\u0628\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064e \u0635\u064e\u0628\u0651\u064b\u0627",26,"\u062b\u064f\u0645\u0651\u064e \u0634\u064e\u0642\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0634\u064e\u0642\u0651\u064b\u0627",27,"\u0641\u064e\u0623\u064e\u0646\u0652\u0628\u064e\u062a\u0652\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0628\u0651\u064b\u0627",28,"\u0648\u064e\u0639\u0650\u0646\u064e\u0628\u064b\u0627 \u0648\u064e\u0642\u064e\u0636\u0652\u0628\u064b\u0627",29,"\u0648\u064e\u0632\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u064b\u0627 \u0648\u064e\u0646\u064e\u062e\u0652\u0644\u064b\u0627",30,"\u0648\u064e\u062d\u064e\u062f\u064e\u0627\u0626\u0650\u0642\u064e \u063a\u064f\u0644\u0652\u0628\u064b\u0627",31,"\u0648\u064e\u0641\u064e\u0627\u0643\u0650\u0647\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0628\u0651\u064b\u0627",32,"\u0645\u064e\u062a\u064e\u0627\u0639\u064b\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u0650\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650\u0643\u064f\u0645\u0652",33,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0650 \u0627\u0644\u0635\u0651\u064e\u0627\u062e\u0651\u064e\u0629\u064f",34,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0641\u0650\u0631\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u062e\u0650\u064a\u0647\u0650",35,"\u0648\u064e\u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0628\u0650\u064a\u0647\u0650",36,"\u0648\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0647\u0650",37,"\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0634\u064e\u0623\u0652\u0646\u064c \u064a\u064f\u063a\u0652\u0646\u0650\u064a\u0647\u0650",38,"\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0645\u064f\u0633\u0652\u0641\u0650\u0631\u064e\u0629\u064c",39,"\u0636\u064e\u0627\u062d\u0650\u0643\u064e\u0629\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u0628\u0652\u0634\u0650\u0631\u064e\u0629\u064c",40,"\u0648\u064e\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u063a\u064e\u0628\u064e\u0631\u064e\u0629\u064c",41,"\u062a\u064e\u0631\u0652\u0647\u064e\u0642\u064f\u0647\u064e\u0627 \u0642\u064e\u062a\u064e\u0631\u064e\u0629\u064c",42,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u064e\u0641\u064e\u0631\u064e\u0629\u064f \u0627\u0644\u0652\u0641\u064e\u062c\u064e\u0631\u064e\u0629\u064f"],t.v)
B.aoM=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0643\u064f\u0648\u0651\u0650\u0631\u064e\u062a\u0652",2,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0627\u0646\u0652\u0643\u064e\u062f\u064e\u0631\u064e\u062a\u0652",3,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u0652",4,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0639\u0650\u0634\u064e\u0627\u0631\u064f \u0639\u064f\u0637\u0651\u0650\u0644\u064e\u062a\u0652",5,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0648\u064f\u062d\u064f\u0648\u0634\u064f \u062d\u064f\u0634\u0650\u0631\u064e\u062a\u0652",6,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u0650\u062d\u064e\u0627\u0631\u064f \u0633\u064f\u062c\u0651\u0650\u0631\u064e\u062a\u0652",7,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0646\u0651\u064f\u0641\u064f\u0648\u0633\u064f \u0632\u064f\u0648\u0651\u0650\u062c\u064e\u062a\u0652",8,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0621\u064f\u0648\u062f\u064e\u0629\u064f \u0633\u064f\u0626\u0650\u0644\u064e\u062a\u0652",9,"\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0630\u064e\u0646\u0652\u0628\u064d \u0642\u064f\u062a\u0650\u0644\u064e\u062a\u0652",10,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u064f \u0646\u064f\u0634\u0650\u0631\u064e\u062a\u0652",11,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0643\u064f\u0634\u0650\u0637\u064e\u062a\u0652",12,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0633\u064f\u0639\u0651\u0650\u0631\u064e\u062a\u0652",13,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0623\u064f\u0632\u0652\u0644\u0650\u0641\u064e\u062a\u0652",14,"\u0639\u064e\u0644\u0650\u0645\u064e\u062a\u0652 \u0646\u064e\u0641\u0652\u0633\u064c \u0645\u064e\u0627 \u0623\u064e\u062d\u0652\u0636\u064e\u0631\u064e\u062a\u0652",15,"\u0641\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u062e\u064f\u0646\u0651\u064e\u0633\u0650",16,"\u0627\u0644\u0652\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0627\u0644\u0652\u0643\u064f\u0646\u0651\u064e\u0633\u0650",17,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0633\u0652\u0639\u064e\u0633\u064e",18,"\u0648\u064e\u0627\u0644\u0635\u0651\u064f\u0628\u0652\u062d\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0646\u064e\u0641\u0651\u064e\u0633\u064e",19,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0642\u064e\u0648\u0652\u0644\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",20,"\u0630\u0650\u064a \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0639\u0650\u0646\u0652\u062f\u064e \u0630\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0645\u064e\u0643\u0650\u064a\u0646\u064d",21,"\u0645\u064f\u0637\u064e\u0627\u0639\u064d \u062b\u064e\u0645\u0651\u064e \u0623\u064e\u0645\u0650\u064a\u0646\u064d",22,"\u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064d",23,"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0631\u064e\u0622\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u0641\u064f\u0642\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u0650",24,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0628\u0650\u0636\u064e\u0646\u0650\u064a\u0646\u064d",25,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0642\u064e\u0648\u0652\u0644\u0650 \u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064d \u0631\u064e\u062c\u0650\u064a\u0645\u064d",26,"\u0641\u064e\u0623\u064e\u064a\u0652\u0646\u064e \u062a\u064e\u0630\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u064e",27,"\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0644\u0650\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",28,"\u0644\u0650\u0645\u064e\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064e",29,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0627\u0621\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064e\u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e"],t.v)
B.abW=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0627\u0646\u0652\u0641\u064e\u0637\u064e\u0631\u064e\u062a\u0652",2,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0643\u064e\u0648\u064e\u0627\u0643\u0650\u0628\u064f \u0627\u0646\u0652\u062a\u064e\u062b\u064e\u0631\u064e\u062a\u0652",3,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u0650\u062d\u064e\u0627\u0631\u064f \u0641\u064f\u062c\u0651\u0650\u0631\u064e\u062a\u0652",4,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u064f \u0628\u064f\u0639\u0652\u062b\u0650\u0631\u064e\u062a\u0652",5,"\u0639\u064e\u0644\u0650\u0645\u064e\u062a\u0652 \u0646\u064e\u0641\u0652\u0633\u064c \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0648\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e\u062a\u0652",6,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u064e\u0627 \u063a\u064e\u0631\u0651\u064e\u0643\u064e \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u0650",7,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0627\u0643\u064e \u0641\u064e\u0639\u064e\u062f\u064e\u0644\u064e\u0643\u064e",8,"\u0641\u0650\u064a \u0623\u064e\u064a\u0651\u0650 \u0635\u064f\u0648\u0631\u064e\u0629\u064d \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0631\u064e\u0643\u0651\u064e\u0628\u064e\u0643\u064e",9,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u0652 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",10,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u062d\u064e\u0627\u0641\u0650\u0638\u0650\u064a\u0646\u064e",11,"\u0643\u0650\u0631\u064e\u0627\u0645\u064b\u0627 \u0643\u064e\u0627\u062a\u0650\u0628\u0650\u064a\u0646\u064e",12,"\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",13,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u0646\u064e\u0639\u0650\u064a\u0645\u064d",14,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u062c\u064e\u062d\u0650\u064a\u0645\u064d",15,"\u064a\u064e\u0635\u0652\u0644\u064e\u0648\u0652\u0646\u064e\u0647\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",16,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u063a\u064e\u0627\u0626\u0650\u0628\u0650\u064a\u0646\u064e",17,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",18,"\u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u0652\u0645\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",19,"\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u062a\u064e\u0645\u0652\u0644\u0650\u0643\u064f \u0646\u064e\u0641\u0652\u0633\u064c \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u064d \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u06d6 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0651\u064e\u0647\u0650"],t.v)
B.apm=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0644\u0652\u0645\u064f\u0637\u064e\u0641\u0651\u0650\u0641\u0650\u064a\u0646\u064e",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0627\u0643\u0652\u062a\u064e\u0627\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0648\u0652\u0641\u064f\u0648\u0646\u064e",3,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0627\u0644\u064f\u0648\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u0648\u064e\u0632\u064e\u0646\u064f\u0648\u0647\u064f\u0645\u0652 \u064a\u064f\u062e\u0652\u0633\u0650\u0631\u064f\u0648\u0646\u064e",4,"\u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0645\u064e\u0628\u0652\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",5,"\u0644\u0650\u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",6,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",7,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0641\u0650\u064a \u0633\u0650\u062c\u0651\u0650\u064a\u0646\u064d",8,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0633\u0650\u062c\u0651\u0650\u064a\u0646\u064c",9,"\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u064e\u0631\u0652\u0642\u064f\u0648\u0645\u064c",10,"\u0648\u064e\u064a\u0652\u0644\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0650\u0644\u0652\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",11,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",12,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064f \u0645\u064f\u0639\u0652\u062a\u064e\u062f\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",13,u.H,14,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0628\u064e\u0644\u0652 \u06dc \u0631\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e",15,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u0645\u064e\u062d\u0652\u062c\u064f\u0648\u0628\u064f\u0648\u0646\u064e",16,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0635\u064e\u0627\u0644\u064f\u0648 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",17,"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",18,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u0650 \u0644\u064e\u0641\u0650\u064a \u0639\u0650\u0644\u0651\u0650\u064a\u0651\u0650\u064a\u0646\u064e",19,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0639\u0650\u0644\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e",20,"\u0643\u0650\u062a\u064e\u0627\u0628\u064c \u0645\u064e\u0631\u0652\u0642\u064f\u0648\u0645\u064c",21,"\u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",22,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0631\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u0646\u064e\u0639\u0650\u064a\u0645\u064d",23,"\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u0650 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",24,"\u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064f \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 \u0646\u064e\u0636\u0652\u0631\u064e\u0629\u064e \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",25,"\u064a\u064f\u0633\u0652\u0642\u064e\u0648\u0652\u0646\u064e \u0645\u0650\u0646\u0652 \u0631\u064e\u062d\u0650\u064a\u0642\u064d \u0645\u064e\u062e\u0652\u062a\u064f\u0648\u0645\u064d",26,"\u062e\u0650\u062a\u064e\u0627\u0645\u064f\u0647\u064f \u0645\u0650\u0633\u0652\u0643\u064c \u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u0652\u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0641\u064e\u0633\u0650 \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0646\u064e\u0627\u0641\u0650\u0633\u064f\u0648\u0646\u064e",27,"\u0648\u064e\u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064f \u0645\u0650\u0646\u0652 \u062a\u064e\u0633\u0652\u0646\u0650\u064a\u0645\u064d",28,"\u0639\u064e\u064a\u0652\u0646\u064b\u0627 \u064a\u064e\u0634\u0652\u0631\u064e\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",29,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0645\u064f\u0648\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u064a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e",30,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0651\u064f\u0648\u0627 \u0628\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u062a\u064e\u063a\u064e\u0627\u0645\u064e\u0632\u064f\u0648\u0646\u064e",31,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650\u0645\u064f \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0641\u064e\u0643\u0650\u0647\u0650\u064a\u0646\u064e",32,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0644\u064e\u0636\u064e\u0627\u0644\u0651\u064f\u0648\u0646\u064e",33,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u062d\u064e\u0627\u0641\u0650\u0638\u0650\u064a\u0646\u064e",34,"\u0641\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u064a\u064e\u0636\u0652\u062d\u064e\u0643\u064f\u0648\u0646\u064e",35,"\u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u064e\u0627\u0626\u0650\u0643\u0650 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e",36,"\u0647\u064e\u0644\u0652 \u062b\u064f\u0648\u0651\u0650\u0628\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e"],t.v)
B.apu=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064f \u0627\u0646\u0652\u0634\u064e\u0642\u0651\u064e\u062a\u0652",2,"\u0648\u064e\u0623\u064e\u0630\u0650\u0646\u064e\u062a\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u062d\u064f\u0642\u0651\u064e\u062a\u0652",3,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0645\u064f\u062f\u0651\u064e\u062a\u0652",4,"\u0648\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u062a\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u062e\u064e\u0644\u0651\u064e\u062a\u0652",5,"\u0648\u064e\u0623\u064e\u0630\u0650\u0646\u064e\u062a\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u062d\u064f\u0642\u0651\u064e\u062a\u0652",6,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0643\u064e\u0627\u062f\u0650\u062d\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u062f\u0652\u062d\u064b\u0627 \u0641\u064e\u0645\u064f\u0644\u064e\u0627\u0642\u0650\u064a\u0647\u0650",7,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650",8,"\u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u062d\u064e\u0627\u0633\u064e\u0628\u064f \u062d\u0650\u0633\u064e\u0627\u0628\u064b\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",9,"\u0648\u064e\u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0645\u064e\u0633\u0652\u0631\u064f\u0648\u0631\u064b\u0627",10,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0627\u0621\u064e \u0638\u064e\u0647\u0652\u0631\u0650\u0647\u0650",11,"\u0641\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u062b\u064f\u0628\u064f\u0648\u0631\u064b\u0627",12,"\u0648\u064e\u064a\u064e\u0635\u0652\u0644\u064e\u0649\u0670 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",13,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0645\u064e\u0633\u0652\u0631\u064f\u0648\u0631\u064b\u0627",14,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u062d\u064f\u0648\u0631\u064e",15,"\u0628\u064e\u0644\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",16,"\u0641\u064e\u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0627\u0644\u0634\u0651\u064e\u0641\u064e\u0642\u0650",17,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0633\u064e\u0642\u064e",18,"\u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u0627\u062a\u0651\u064e\u0633\u064e\u0642\u064e",19,"\u0644\u064e\u062a\u064e\u0631\u0652\u0643\u064e\u0628\u064f\u0646\u0651\u064e \u0637\u064e\u0628\u064e\u0642\u064b\u0627 \u0639\u064e\u0646\u0652 \u0637\u064e\u0628\u064e\u0642\u064d",20,"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",21,"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0626\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0646\u064e \u06e9",22,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",23,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064f\u0648\u0646\u064e",24,"\u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",25,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0645\u0652\u0646\u064f\u0648\u0646\u064d"],t.v)
B.ars=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0628\u064f\u0631\u064f\u0648\u062c\u0650",2,"\u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0639\u064f\u0648\u062f\u0650",3,"\u0648\u064e\u0634\u064e\u0627\u0647\u0650\u062f\u064d \u0648\u064e\u0645\u064e\u0634\u0652\u0647\u064f\u0648\u062f\u064d",4,"\u0642\u064f\u062a\u0650\u0644\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064f\u062e\u0652\u062f\u064f\u0648\u062f\u0650",5,"\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0648\u064e\u0642\u064f\u0648\u062f\u0650",6,"\u0625\u0650\u0630\u0652 \u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0642\u064f\u0639\u064f\u0648\u062f\u064c",7,"\u0648\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0634\u064f\u0647\u064f\u0648\u062f\u064c",8,"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u0650",9,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f \u0645\u064f\u0644\u0652\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06da \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",10,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u062a\u064e\u0646\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u0652 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",11,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064c \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",12,"\u0625\u0650\u0646\u0651\u064e \u0628\u064e\u0637\u0652\u0634\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064c",13,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u064a\u064f\u0628\u0652\u062f\u0650\u0626\u064f \u0648\u064e\u064a\u064f\u0639\u0650\u064a\u062f\u064f",14,"\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0652\u0648\u064e\u062f\u064f\u0648\u062f\u064f",15,"\u0630\u064f\u0648 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0645\u064e\u062c\u0650\u064a\u062f\u064f",16,"\u0641\u064e\u0639\u0651\u064e\u0627\u0644\u064c \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",17,"\u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0627\u0644\u0652\u062c\u064f\u0646\u064f\u0648\u062f\u0650",18,"\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e",19,"\u0628\u064e\u0644\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u062a\u064e\u0643\u0652\u0630\u0650\u064a\u0628\u064d",20,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 \u0645\u064f\u062d\u0650\u064a\u0637\u064c",21,"\u0628\u064e\u0644\u0652 \u0647\u064f\u0648\u064e \u0642\u064f\u0631\u0652\u0622\u0646\u064c \u0645\u064e\u062c\u0650\u064a\u062f\u064c",22,"\u0641\u0650\u064a \u0644\u064e\u0648\u0652\u062d\u064d \u0645\u064e\u062d\u0652\u0641\u064f\u0648\u0638\u064d"],t.v)
B.as0=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u0627\u0631\u0650\u0642\u0650",2,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0637\u0651\u064e\u0627\u0631\u0650\u0642\u064f",3,"\u0627\u0644\u0646\u0651\u064e\u062c\u0652\u0645\u064f \u0627\u0644\u062b\u0651\u064e\u0627\u0642\u0650\u0628\u064f",4,"\u0625\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u0652\u0633\u064d \u0644\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u062d\u064e\u0627\u0641\u0650\u0638\u064c",5,"\u0641\u064e\u0644\u0652\u064a\u064e\u0646\u0652\u0638\u064f\u0631\u0650 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u0650\u0645\u0651\u064e \u062e\u064f\u0644\u0650\u0642\u064e",6,"\u062e\u064f\u0644\u0650\u0642\u064e \u0645\u0650\u0646\u0652 \u0645\u064e\u0627\u0621\u064d \u062f\u064e\u0627\u0641\u0650\u0642\u064d",7,"\u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u0627\u0644\u0635\u0651\u064f\u0644\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0631\u064e\u0627\u0626\u0650\u0628\u0650",8,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u0652\u0639\u0650\u0647\u0650 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u064c",9,"\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064f\u0628\u0652\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0631\u064e\u0627\u0626\u0650\u0631\u064f",10,"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0627\u0635\u0650\u0631\u064d",11,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0631\u0651\u064e\u062c\u0652\u0639\u0650",12,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0635\u0651\u064e\u062f\u0652\u0639\u0650",13,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0642\u064e\u0648\u0652\u0644\u064c \u0641\u064e\u0635\u0652\u0644\u064c",14,"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064e\u0632\u0652\u0644\u0650",15,"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u0652\u062f\u064b\u0627",16,"\u0648\u064e\u0623\u064e\u0643\u0650\u064a\u062f\u064f \u0643\u064e\u064a\u0652\u062f\u064b\u0627",17,"\u0641\u064e\u0645\u064e\u0647\u0651\u0650\u0644\u0650 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0645\u0652\u0647\u0650\u0644\u0652\u0647\u064f\u0645\u0652 \u0631\u064f\u0648\u064e\u064a\u0652\u062f\u064b\u0627"],t.v)
B.abX=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0633\u064e\u0628\u0651\u0650\u062d\u0650 \u0627\u0633\u0652\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670",3,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064e\u062f\u0651\u064e\u0631\u064e \u0641\u064e\u0647\u064e\u062f\u064e\u0649\u0670",4,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0639\u064e\u0649\u0670",5,"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u063a\u064f\u062b\u064e\u0627\u0621\u064b \u0623\u064e\u062d\u0652\u0648\u064e\u0649\u0670",6,"\u0633\u064e\u0646\u064f\u0642\u0652\u0631\u0650\u0626\u064f\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0633\u064e\u0649\u0670",7,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0647\u0652\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u0652\u0641\u064e\u0649\u0670",8,"\u0648\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u064a\u064f\u0633\u0652\u0631\u064e\u0649\u0670",9,"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0625\u0650\u0646\u0652 \u0646\u064e\u0641\u064e\u0639\u064e\u062a\u0650 \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670",10,"\u0633\u064e\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u062e\u0652\u0634\u064e\u0649\u0670",11,"\u0648\u064e\u064a\u064e\u062a\u064e\u062c\u064e\u0646\u0651\u064e\u0628\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0642\u064e\u0649",12,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0635\u0652\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0643\u064f\u0628\u0652\u0631\u064e\u0649\u0670",13,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u064a\u064e\u0649\u0670",14,"\u0642\u064e\u062f\u0652 \u0623\u064e\u0641\u0652\u0644\u064e\u062d\u064e \u0645\u064e\u0646\u0652 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",15,"\u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e \u0627\u0633\u0652\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0641\u064e\u0635\u064e\u0644\u0651\u064e\u0649\u0670",16,"\u0628\u064e\u0644\u0652 \u062a\u064f\u0624\u0652\u062b\u0650\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627",17,"\u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670",18,"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",19,"\u0635\u064f\u062d\u064f\u0641\u0650 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670"],t.v)
B.as7=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0647\u064e\u0644\u0652 \u0623\u064e\u062a\u064e\u0627\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0634\u0650\u064a\u064e\u0629\u0650",2,"\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062e\u064e\u0627\u0634\u0650\u0639\u064e\u0629\u064c",3,"\u0639\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u064c \u0646\u064e\u0627\u0635\u0650\u0628\u064e\u0629\u064c",4,"\u062a\u064e\u0635\u0652\u0644\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u064b\u0627 \u062d\u064e\u0627\u0645\u0650\u064a\u064e\u0629\u064b",5,"\u062a\u064f\u0633\u0652\u0642\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0639\u064e\u064a\u0652\u0646\u064d \u0622\u0646\u0650\u064a\u064e\u0629\u064d",6,"\u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0637\u064e\u0639\u064e\u0627\u0645\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0636\u064e\u0631\u0650\u064a\u0639\u064d",7,"\u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0645\u0650\u0646\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u062c\u064f\u0648\u0639\u064d",8,"\u0648\u064f\u062c\u064f\u0648\u0647\u064c \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0646\u064e\u0627\u0639\u0650\u0645\u064e\u0629\u064c",9,"\u0644\u0650\u0633\u064e\u0639\u0652\u064a\u0650\u0647\u064e\u0627 \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064c",10,"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u064d",11,"\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627\u063a\u0650\u064a\u064e\u0629\u064b",12,"\u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u064a\u0652\u0646\u064c \u062c\u064e\u0627\u0631\u0650\u064a\u064e\u0629\u064c",13,"\u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0631\u064f\u0631\u064c \u0645\u064e\u0631\u0652\u0641\u064f\u0648\u0639\u064e\u0629\u064c",14,"\u0648\u064e\u0623\u064e\u0643\u0652\u0648\u064e\u0627\u0628\u064c \u0645\u064e\u0648\u0652\u0636\u064f\u0648\u0639\u064e\u0629\u064c",15,"\u0648\u064e\u0646\u064e\u0645\u064e\u0627\u0631\u0650\u0642\u064f \u0645\u064e\u0635\u0652\u0641\u064f\u0648\u0641\u064e\u0629\u064c",16,"\u0648\u064e\u0632\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0651\u064f \u0645\u064e\u0628\u0652\u062b\u064f\u0648\u062b\u064e\u0629\u064c",17,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0625\u0650\u0628\u0650\u0644\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u062e\u064f\u0644\u0650\u0642\u064e\u062a\u0652",18,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u0631\u064f\u0641\u0650\u0639\u064e\u062a\u0652",19,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u0646\u064f\u0635\u0650\u0628\u064e\u062a\u0652",20,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0643\u064e\u064a\u0652\u0641\u064e \u0633\u064f\u0637\u0650\u062d\u064e\u062a\u0652",21,"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u0645\u064f\u0630\u064e\u0643\u0651\u0650\u0631\u064c",22,"\u0644\u064e\u0633\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0645\u064f\u0635\u064e\u064a\u0652\u0637\u0650\u0631\u064d",23,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064e",24,"\u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064e",25,"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652",26,"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652"],t.v)
B.apk=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650",2,"\u0648\u064e\u0644\u064e\u064a\u064e\u0627\u0644\u064d \u0639\u064e\u0634\u0652\u0631\u064d",3,"\u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0641\u0652\u0639\u0650 \u0648\u064e\u0627\u0644\u0652\u0648\u064e\u062a\u0652\u0631\u0650",4,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u0633\u0652\u0631\u0650",5,"\u0647\u064e\u0644\u0652 \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0633\u064e\u0645\u064c \u0644\u0650\u0630\u0650\u064a \u062d\u0650\u062c\u0652\u0631\u064d",6,"\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u0652\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0639\u064e\u0627\u062f\u064d",7,"\u0625\u0650\u0631\u064e\u0645\u064e \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0639\u0650\u0645\u064e\u0627\u062f\u0650",8,"\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0644\u064e\u0645\u0652 \u064a\u064f\u062e\u0652\u0644\u064e\u0642\u0652 \u0645\u0650\u062b\u0652\u0644\u064f\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u0650\u0644\u064e\u0627\u062f\u0650",9,"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0628\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u062e\u0652\u0631\u064e \u0628\u0650\u0627\u0644\u0652\u0648\u064e\u0627\u062f\u0650",10,"\u0648\u064e\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0630\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u062a\u064e\u0627\u062f\u0650",11,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u063a\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u0650\u0644\u064e\u0627\u062f\u0650",12,"\u0641\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064e",13,"\u0641\u064e\u0635\u064e\u0628\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0633\u064e\u0648\u0652\u0637\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064d",14,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0628\u0650\u0627\u0644\u0652\u0645\u0650\u0631\u0652\u0635\u064e\u0627\u062f\u0650",15,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0627\u0628\u0652\u062a\u064e\u0644\u064e\u0627\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f \u0641\u064e\u0623\u064e\u0643\u0652\u0631\u064e\u0645\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u0639\u0651\u064e\u0645\u064e\u0647\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0643\u0652\u0631\u064e\u0645\u064e\u0646\u0650",16,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0627\u0628\u0652\u062a\u064e\u0644\u064e\u0627\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u064e\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u0650\u0632\u0652\u0642\u064e\u0647\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0647\u064e\u0627\u0646\u064e\u0646\u0650",17,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0628\u064e\u0644\u0652 \u0644\u064e\u0627 \u062a\u064f\u0643\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u064a\u064e\u062a\u0650\u064a\u0645\u064e",18,"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u064e\u0627\u0636\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650 \u0627\u0644\u0652\u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u0650",19,"\u0648\u064e\u062a\u064e\u0623\u0652\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0627\u0644\u062a\u0651\u064f\u0631\u064e\u0627\u062b\u064e \u0623\u064e\u0643\u0652\u0644\u064b\u0627 \u0644\u064e\u0645\u0651\u064b\u0627",20,"\u0648\u064e\u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0627\u0644\u064e \u062d\u064f\u0628\u0651\u064b\u0627 \u062c\u064e\u0645\u0651\u064b\u0627",21,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0643\u0651\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u062f\u064e\u0643\u0651\u064b\u0627 \u062f\u064e\u0643\u0651\u064b\u0627",22,"\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064f \u0635\u064e\u0641\u0651\u064b\u0627 \u0635\u064e\u0641\u0651\u064b\u0627",23,"\u0648\u064e\u062c\u0650\u064a\u0621\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0628\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u06da \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f \u0627\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e\u0649\u0670",24,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0642\u064e\u062f\u0651\u064e\u0645\u0652\u062a\u064f \u0644\u0650\u062d\u064e\u064a\u064e\u0627\u062a\u0650\u064a",25,"\u0641\u064e\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c",26,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0648\u062b\u0650\u0642\u064f \u0648\u064e\u062b\u064e\u0627\u0642\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c",27,"\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064e\u062a\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0641\u0652\u0633\u064f \u0627\u0644\u0652\u0645\u064f\u0637\u0652\u0645\u064e\u0626\u0650\u0646\u0651\u064e\u0629\u064f",28,"\u0627\u0631\u0652\u062c\u0650\u0639\u0650\u064a \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064b \u0645\u064e\u0631\u0652\u0636\u0650\u064a\u0651\u064e\u0629\u064b",29,"\u0641\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u0650\u064a \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a",30,"\u0648\u064e\u0627\u062f\u0652\u062e\u064f\u0644\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u062a\u0650\u064a"],t.v)
B.aoT=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0644\u064e\u0627 \u0623\u064f\u0642\u0652\u0633\u0650\u0645\u064f \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u062f\u0650",2,"\u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062d\u0650\u0644\u0651\u064c \u0628\u0650\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u062f\u0650",3,"\u0648\u064e\u0648\u064e\u0627\u0644\u0650\u062f\u064d \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064e",4,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0643\u064e\u0628\u064e\u062f\u064d",5,"\u0623\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0646\u0652 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u064c",6,"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u062a\u064f \u0645\u064e\u0627\u0644\u064b\u0627 \u0644\u064f\u0628\u064e\u062f\u064b\u0627",7,"\u0623\u064e\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c",8,"\u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u064e\u0647\u064f \u0639\u064e\u064a\u0652\u0646\u064e\u064a\u0652\u0646\u0650",9,"\u0648\u064e\u0644\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0634\u064e\u0641\u064e\u062a\u064e\u064a\u0652\u0646\u0650",10,"\u0648\u064e\u0647\u064e\u062f\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0627\u0644\u0646\u0651\u064e\u062c\u0652\u062f\u064e\u064a\u0652\u0646\u0650",11,"\u0641\u064e\u0644\u064e\u0627 \u0627\u0642\u0652\u062a\u064e\u062d\u064e\u0645\u064e \u0627\u0644\u0652\u0639\u064e\u0642\u064e\u0628\u064e\u0629\u064e",12,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0652\u0639\u064e\u0642\u064e\u0628\u064e\u0629\u064f",13,"\u0641\u064e\u0643\u0651\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d",14,"\u0623\u064e\u0648\u0652 \u0625\u0650\u0637\u0652\u0639\u064e\u0627\u0645\u064c \u0641\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064d \u0630\u0650\u064a \u0645\u064e\u0633\u0652\u063a\u064e\u0628\u064e\u0629\u064d",15,"\u064a\u064e\u062a\u0650\u064a\u0645\u064b\u0627 \u0630\u064e\u0627 \u0645\u064e\u0642\u0652\u0631\u064e\u0628\u064e\u0629\u064d",16,"\u0623\u064e\u0648\u0652 \u0645\u0650\u0633\u0652\u0643\u0650\u064a\u0646\u064b\u0627 \u0630\u064e\u0627 \u0645\u064e\u062a\u0652\u0631\u064e\u0628\u064e\u0629\u064d",17,"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0631\u0652\u062d\u064e\u0645\u064e\u0629\u0650",18,"\u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u064a\u0652\u0645\u064e\u0646\u064e\u0629\u0650",19,"\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0647\u064f\u0645\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0623\u064e\u0645\u064e\u0629\u0650",20,"\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0627\u0631\u064c \u0645\u064f\u0624\u0652\u0635\u064e\u062f\u064e\u0629\u064c"],t.v)
B.asi=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u0650 \u0648\u064e\u0636\u064f\u062d\u064e\u0627\u0647\u064e\u0627",2,"\u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0644\u064e\u0627\u0647\u064e\u0627",3,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0644\u0651\u064e\u0627\u0647\u064e\u0627",4,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u063a\u0652\u0634\u064e\u0627\u0647\u064e\u0627",5,"\u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0646\u064e\u0627\u0647\u064e\u0627",6,"\u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0637\u064e\u062d\u064e\u0627\u0647\u064e\u0627",7,"\u0648\u064e\u0646\u064e\u0641\u0652\u0633\u064d \u0648\u064e\u0645\u064e\u0627 \u0633\u064e\u0648\u0651\u064e\u0627\u0647\u064e\u0627",8,"\u0641\u064e\u0623\u064e\u0644\u0652\u0647\u064e\u0645\u064e\u0647\u064e\u0627 \u0641\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0642\u0652\u0648\u064e\u0627\u0647\u064e\u0627",9,"\u0642\u064e\u062f\u0652 \u0623\u064e\u0641\u0652\u0644\u064e\u062d\u064e \u0645\u064e\u0646\u0652 \u0632\u064e\u0643\u0651\u064e\u0627\u0647\u064e\u0627",10,"\u0648\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u0652 \u062f\u064e\u0633\u0651\u064e\u0627\u0647\u064e\u0627",11,"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0628\u0650\u0637\u064e\u063a\u0652\u0648\u064e\u0627\u0647\u064e\u0627",12,"\u0625\u0650\u0630\u0650 \u0627\u0646\u0652\u0628\u064e\u0639\u064e\u062b\u064e \u0623\u064e\u0634\u0652\u0642\u064e\u0627\u0647\u064e\u0627",13,"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064f\u0642\u0652\u064a\u064e\u0627\u0647\u064e\u0627",14,"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u062f\u064e\u0645\u0652\u062f\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u0652 \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0627\u0647\u064e\u0627",15,"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064f\u0642\u0652\u0628\u064e\u0627\u0647\u064e\u0627"],t.v)
B.apn=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u063a\u0652\u0634\u064e\u0649\u0670",2,"\u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u062c\u064e\u0644\u0651\u064e\u0649\u0670",3,"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0646\u0652\u062b\u064e\u0649\u0670",4,"\u0625\u0650\u0646\u0651\u064e \u0633\u064e\u0639\u0652\u064a\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0634\u064e\u062a\u0651\u064e\u0649\u0670",5,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0639\u0652\u0637\u064e\u0649\u0670 \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064e\u0649\u0670",6,"\u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670",7,"\u0641\u064e\u0633\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0647\u064f \u0644\u0650\u0644\u0652\u064a\u064f\u0633\u0652\u0631\u064e\u0649\u0670",8,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0628\u064e\u062e\u0650\u0644\u064e \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0646\u064e\u0649\u0670",9,"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064f\u0633\u0652\u0646\u064e\u0649\u0670",10,"\u0641\u064e\u0633\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0647\u064f \u0644\u0650\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u064e\u0649\u0670",11,"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u063a\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652\u0647\u064f \u0645\u064e\u0627\u0644\u064f\u0647\u064f \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u062f\u0651\u064e\u0649\u0670",12,"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670",13,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",14,"\u0641\u064e\u0623\u064e\u0646\u0652\u0630\u064e\u0631\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0646\u064e\u0627\u0631\u064b\u0627 \u062a\u064e\u0644\u064e\u0638\u0651\u064e\u0649\u0670",15,"\u0644\u064e\u0627 \u064a\u064e\u0635\u0652\u0644\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0642\u064e\u0649",16,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",17,"\u0648\u064e\u0633\u064e\u064a\u064f\u062c\u064e\u0646\u0651\u064e\u0628\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u062a\u0652\u0642\u064e\u0649",18,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0624\u0652\u062a\u0650\u064a \u0645\u064e\u0627\u0644\u064e\u0647\u064f \u064a\u064e\u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",19,"\u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u064d \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0645\u0650\u0646\u0652 \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064d \u062a\u064f\u062c\u0652\u0632\u064e\u0649\u0670",20,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0648\u064e\u062c\u0652\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0644\u064e\u0649\u0670",21,"\u0648\u064e\u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064e\u0631\u0652\u0636\u064e\u0649\u0670"],t.v)
B.ap9=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0636\u0651\u064f\u062d\u064e\u0649\u0670",2,"\u0648\u064e\u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u062c\u064e\u0649\u0670",3,"\u0645\u064e\u0627 \u0648\u064e\u062f\u0651\u064e\u0639\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u0644\u064e\u0649\u0670",4,"\u0648\u064e\u0644\u064e\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670",5,"\u0648\u064e\u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u064a\u064f\u0639\u0652\u0637\u0650\u064a\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u062a\u064e\u0631\u0652\u0636\u064e\u0649\u0670",6,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u062c\u0650\u062f\u0652\u0643\u064e \u064a\u064e\u062a\u0650\u064a\u0645\u064b\u0627 \u0641\u064e\u0622\u0648\u064e\u0649\u0670",7,"\u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0643\u064e \u0636\u064e\u0627\u0644\u0651\u064b\u0627 \u0641\u064e\u0647\u064e\u062f\u064e\u0649\u0670",8,"\u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0643\u064e \u0639\u064e\u0627\u0626\u0650\u0644\u064b\u0627 \u0641\u064e\u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670",9,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u062a\u0650\u064a\u0645\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0647\u064e\u0631\u0652",10,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0627\u0626\u0650\u0644\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0647\u064e\u0631\u0652",11,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u062d\u064e\u062f\u0651\u0650\u062b\u0652"],t.v)
B.asu=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064e\u0634\u0652\u0631\u064e\u062d\u0652 \u0644\u064e\u0643\u064e \u0635\u064e\u062f\u0652\u0631\u064e\u0643\u064e",2,"\u0648\u064e\u0648\u064e\u0636\u064e\u0639\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064e \u0648\u0650\u0632\u0652\u0631\u064e\u0643\u064e",3,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0646\u0652\u0642\u064e\u0636\u064e \u0638\u064e\u0647\u0652\u0631\u064e\u0643\u064e",4,"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0630\u0650\u0643\u0652\u0631\u064e\u0643\u064e",5,"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627",6,"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627",7,"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u064e\u063a\u0652\u062a\u064e \u0641\u064e\u0627\u0646\u0652\u0635\u064e\u0628\u0652",8,"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0627\u0631\u0652\u063a\u064e\u0628\u0652"],t.v)
B.asq=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u062a\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0627\u0644\u0632\u0651\u064e\u064a\u0652\u062a\u064f\u0648\u0646\u0650",2,"\u0648\u064e\u0637\u064f\u0648\u0631\u0650 \u0633\u0650\u064a\u0646\u0650\u064a\u0646\u064e",3,"\u0648\u064e\u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u0644\u064e\u062f\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0650\u064a\u0646\u0650",4,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u0650 \u062a\u064e\u0642\u0652\u0648\u0650\u064a\u0645\u064d",5,"\u062b\u064f\u0645\u0651\u064e \u0631\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0623\u064e\u0633\u0652\u0641\u064e\u0644\u064e \u0633\u064e\u0627\u0641\u0650\u0644\u0650\u064a\u0646\u064e",6,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0645\u064e\u0645\u0652\u0646\u064f\u0648\u0646\u064d",7,"\u0641\u064e\u0645\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0643\u064e \u0628\u064e\u0639\u0652\u062f\u064f \u0628\u0650\u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",8,"\u0623\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u062d\u0652\u0643\u064e\u0645\u0650 \u0627\u0644\u0652\u062d\u064e\u0627\u0643\u0650\u0645\u0650\u064a\u0646\u064e"],t.v)
B.abV=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0642\u0652\u0631\u064e\u0623\u0652 \u0628\u0650\u0627\u0633\u0652\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e",2,"\u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0644\u064e\u0642\u064d",3,"\u0627\u0642\u0652\u0631\u064e\u0623\u0652 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0643\u0652\u0631\u064e\u0645\u064f",4,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u0644\u064e\u0645\u0650",5,"\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652",6,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u064a\u064e\u0637\u0652\u063a\u064e\u0649\u0670",7,"\u0623\u064e\u0646\u0652 \u0631\u064e\u0622\u0647\u064f \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0646\u064e\u0649\u0670",8,"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0627\u0644\u0631\u0651\u064f\u062c\u0652\u0639\u064e\u0649\u0670",9,"\u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u0652\u0647\u064e\u0649\u0670",10,"\u0639\u064e\u0628\u0652\u062f\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u0635\u064e\u0644\u0651\u064e\u0649\u0670",11,"\u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670",12,"\u0623\u064e\u0648\u0652 \u0623\u064e\u0645\u064e\u0631\u064e \u0628\u0650\u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670",13,"\u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",14,"\u0623\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0631\u064e\u0649\u0670",15,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0626\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u062a\u064e\u0647\u0650 \u0644\u064e\u0646\u064e\u0633\u0652\u0641\u064e\u0639\u064b\u0627 \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u064a\u064e\u0629\u0650",16,"\u0646\u064e\u0627\u0635\u0650\u064a\u064e\u0629\u064d \u0643\u064e\u0627\u0630\u0650\u0628\u064e\u0629\u064d \u062e\u064e\u0627\u0637\u0650\u0626\u064e\u0629\u064d",17,"\u0641\u064e\u0644\u0652\u064a\u064e\u062f\u0652\u0639\u064f \u0646\u064e\u0627\u062f\u0650\u064a\u064e\u0647\u064f",18,"\u0633\u064e\u0646\u064e\u062f\u0652\u0639\u064f \u0627\u0644\u0632\u0651\u064e\u0628\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064e",19,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0652\u0647\u064f \u0648\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u0652 \u0648\u064e\u0627\u0642\u0652\u062a\u064e\u0631\u0650\u0628\u0652 \u06e9"],t.v)
B.ar0=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064e\u062f\u0652\u0631\u0650",2,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064f \u0627\u0644\u0652\u0642\u064e\u062f\u0652\u0631\u0650",3,"\u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064f \u0627\u0644\u0652\u0642\u064e\u062f\u0652\u0631\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0650\u0646\u0652 \u0623\u064e\u0644\u0652\u0641\u0650 \u0634\u064e\u0647\u0652\u0631\u064d",4,"\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0645\u0652\u0631\u064d",5,"\u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0647\u0650\u064a\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0645\u064e\u0637\u0652\u0644\u064e\u0639\u0650 \u0627\u0644\u0652\u0641\u064e\u062c\u0652\u0631\u0650"],t.v)
B.ast=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0645\u064f\u0646\u0652\u0641\u064e\u0643\u0651\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f",2,"\u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0635\u064f\u062d\u064f\u0641\u064b\u0627 \u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064b",3,"\u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064f\u062a\u064f\u0628\u064c \u0642\u064e\u064a\u0651\u0650\u0645\u064e\u0629\u064c",4,"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f",5,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0621\u064e \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062f\u0650\u064a\u0646\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u0650\u0645\u064e\u0629\u0650",6,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u06da \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u0634\u064e\u0631\u0651\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0650\u064a\u0651\u064e\u0629\u0650",7,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0623\u064f\u0648\u0644\u064e\u0640\u0670\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0652\u0628\u064e\u0631\u0650\u064a\u0651\u064e\u0629\u0650",8,"\u062c\u064e\u0632\u064e\u0627\u0624\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064f \u0639\u064e\u062f\u0652\u0646\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u062e\u064e\u0627\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u06d6 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062e\u064e\u0634\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f"],t.v)
B.asr=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0632\u064f\u0644\u0652\u0632\u0650\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0632\u0650\u0644\u0652\u0632\u064e\u0627\u0644\u064e\u0647\u064e\u0627",2,"\u0648\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0623\u064e\u062b\u0652\u0642\u064e\u0627\u0644\u064e\u0647\u064e\u0627",3,"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064f \u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627",4,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u062a\u064f\u062d\u064e\u062f\u0651\u0650\u062b\u064f \u0623\u064e\u062e\u0652\u0628\u064e\u0627\u0631\u064e\u0647\u064e\u0627",5,"\u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0623\u064e\u0648\u0652\u062d\u064e\u0649\u0670 \u0644\u064e\u0647\u064e\u0627",6,"\u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u064a\u064e\u0635\u0652\u062f\u064f\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0634\u0652\u062a\u064e\u0627\u062a\u064b\u0627 \u0644\u0650\u064a\u064f\u0631\u064e\u0648\u0652\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652",7,"\u0641\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u064a\u064e\u0631\u064e\u0647\u064f",8,"\u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652 \u0645\u0650\u062b\u0652\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u0634\u064e\u0631\u0651\u064b\u0627 \u064a\u064e\u0631\u064e\u0647\u064f"],t.v)
B.apa=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u062f\u0650\u064a\u064e\u0627\u062a\u0650 \u0636\u064e\u0628\u0652\u062d\u064b\u0627",2,"\u0641\u064e\u0627\u0644\u0652\u0645\u064f\u0648\u0631\u0650\u064a\u064e\u0627\u062a\u0650 \u0642\u064e\u062f\u0652\u062d\u064b\u0627",3,"\u0641\u064e\u0627\u0644\u0652\u0645\u064f\u063a\u0650\u064a\u0631\u064e\u0627\u062a\u0650 \u0635\u064f\u0628\u0652\u062d\u064b\u0627",4,"\u0641\u064e\u0623\u064e\u062b\u064e\u0631\u0652\u0646\u064e \u0628\u0650\u0647\u0650 \u0646\u064e\u0642\u0652\u0639\u064b\u0627",5,"\u0641\u064e\u0648\u064e\u0633\u064e\u0637\u0652\u0646\u064e \u0628\u0650\u0647\u0650 \u062c\u064e\u0645\u0652\u0639\u064b\u0627",6,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0644\u064e\u0643\u064e\u0646\u064f\u0648\u062f\u064c",7,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0634\u064e\u0647\u0650\u064a\u062f\u064c",8,"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u0650\u062d\u064f\u0628\u0651\u0650 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650 \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064c",9,"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0639\u0652\u062b\u0650\u0631\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u0650",10,"\u0648\u064e\u062d\u064f\u0635\u0651\u0650\u0644\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",11,"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0647\u0650\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u064e\u062e\u064e\u0628\u0650\u064a\u0631\u064c"],t.v)
B.ap6=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0627\u0644\u0652\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",2,"\u0645\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",3,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",4,"\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064e\u0627\u0644\u0652\u0641\u064e\u0631\u064e\u0627\u0634\u0650 \u0627\u0644\u0652\u0645\u064e\u0628\u0652\u062b\u064f\u0648\u062b\u0650",5,"\u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u0627\u0644\u0652\u0639\u0650\u0647\u0652\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0646\u0652\u0641\u064f\u0648\u0634\u0650",6,"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f",7,"\u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0639\u0650\u064a\u0634\u064e\u0629\u064d \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064d",8,"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u062e\u064e\u0641\u0651\u064e\u062a\u0652 \u0645\u064e\u0648\u064e\u0627\u0632\u0650\u064a\u0646\u064f\u0647\u064f",9,"\u0641\u064e\u0623\u064f\u0645\u0651\u064f\u0647\u064f \u0647\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c",10,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0647\u0650\u064a\u064e\u0647\u0652",11,"\u0646\u064e\u0627\u0631\u064c \u062d\u064e\u0627\u0645\u0650\u064a\u064e\u0629\u064c"],t.v)
B.ass=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0623\u064e\u0644\u0652\u0647\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u062a\u0651\u064e\u0643\u064e\u0627\u062b\u064f\u0631\u064f",2,"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0632\u064f\u0631\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0642\u064e\u0627\u0628\u0650\u0631\u064e",3,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",4,"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",5,"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0648\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0639\u0650\u0644\u0652\u0645\u064e \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u0650",6,"\u0644\u064e\u062a\u064e\u0631\u064e\u0648\u064f\u0646\u0651\u064e \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064e",7,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064e\u0631\u064e\u0648\u064f\u0646\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0652\u064a\u064e\u0642\u0650\u064a\u0646\u0650",8,"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064f\u0633\u0652\u0623\u064e\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650"],t.v)
B.as2=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0635\u0652\u0631\u0650",2,"\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u062e\u064f\u0633\u0652\u0631\u064d",3,"\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0652\u0627 \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0628\u0652\u0631\u0650"],t.v)
B.ap2=new A.U([1,"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0640\u0670\u0646\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650 \u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0647\u064f\u0645\u064e\u0632\u064e\u0629\u064d \u0644\u064f\u0645\u064e\u0632\u064e\u0629\u064d",2,"\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0645\u064e\u0639\u064e \u0645\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u0651\u064e\u062f\u064e\u0647\u064f",3,"\u064a\u064e\u062d\u0652\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627\u0644\u064e\u0647\u064f \u0623\u064e\u062e\u0652\u0644\u064e\u062f\u064e\u0647\u064f",4,"\u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0644\u064e\u064a\u064f\u0646\u0652\u0628\u064e\u0630\u064e\u0646\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064f\u0637\u064e\u0645\u064e\u0629\u0650",5,"\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0627\u0643\u064e \u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064f\u0637\u064e\u0645\u064e\u0629\u064f",6,"\u0646\u064e\u0627\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0648\u0642\u064e\u062f\u064e\u0629\u064f",7,"\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0641\u0652\u0626\u0650\u062f\u064e\u0629\u0650",8,"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0645\u064f\u0624\u0652\u0635\u064e\u062f\u064e\u0629\u064c",9,"\u0641\u0650\u064a \u0639\u064e\u0645\u064e\u062f\u064d \u0645\u064f\u0645\u064e\u062f\u0651\u064e\u062f\u064e\u0629\u064d"],t.v)
